export const VERSES_T8: Verse[] = [
  {
    id: 2123, tantraId: 8, verseNumber: 2122,
    tamil: `காயப்பை ஒன்று சரக்குப் பலவுள
மாயப்பை ஒன்றுண்டு மற்றுமோர் பையுண்டு
காயப்பைக்கு உள்நின்ற கள்வன் புறப்பட்டால்
மாயப்பை மண்ணா மயங்கிய வாறே`,
    transliteration: `kāyappai oṉṟu carakkup palavuḷa
māyappai oṉṟuṇṭu maṟṟumōr paiyuṇṭu
kāyappaikku uḷniṉṟa kaḷvaṉ puṟappaṭṭāl
māyappai maṇṇā mayaṅkiya vāṟē`,
    english: `2122: Body Bag and Maya Bag
The body is a bag
Many the ingredients it holds;
There is yet another bag within;
It is the Maya bag;
When the Thief (Jiva)
The body bag leaves,
The Maya bag
Unto dust becomes.`,
    elaborationTamil: `ஒரு பையில் பல பண்டங்களை அடைத்து வைத்தல் போல, யாவராலும் நன்கு அறியப்படும் உடம்பாகிய ஒரு பை ஒவ்வோர் உயிர்க்கும் கிடைத்திருத்தல் கண்கூடாக, அதன்கண் அடைக்கப்பட்டுள்ள பண்டங்களோ பல உள்ளன. (அவற்றை ஆராய் கின்றார் ஒருவரும் இல்லை) இனி, அந்தப் பை மாயம்போலக் கட்புல னாகி, விரைவில் மறைவதாகும். என்றாலும், அந்தப் பைக்குள்ளே மற்றொரு பையும் உண்டு; (அதனை அறிந்தோர் சிலரே.) யாவரும் அறிந்த அந்தப் பைக்குள் அதற்கு வேறாகிய ஒன்று உள்ளதோ, இல்லதோ' என ஐயுறுமாறு ஒளிந்து நிற்கின்ற உயிர் அதனை விட்டு வெளியே போய்விடுமானால், தோன்றியழிவதாகிய அந்த உடம்பு மண்ணோடு மண்ணாய்ப்போக, அதனை நிலையானதாகக் கருதி, அதனைத் தமக்கு உறவாகத் தெளிந்திருந்தோர் திகைப்புற்று நிற்கும் நிலை இரங்கத்தக்கதாகும்.`,
  },
  {
    id: 2124, tantraId: 8, verseNumber: 2123,
    tamil: `அத்தன் அமைத்த உடல்இரு கூறினில்
சுத்தம தாகிய சூக்குமம் சொல்லுங்கால்
சத்த பரிச ரூப ரசகந்தம்
புத்திமான் ஆங்காரம் புரியட்ட காயமே`,
    transliteration: `attaṉ amaitta uṭaliru kūṟiṉil
cuttama tākiya cūkkumam colluṅkāl
catta parica rūpa racakantam
puttimāṉ āṅkāram puriyaṭṭa kāyamē`,
    english: `2123: Subtle Body
Of the body thus God shaped,
In parts two,
Sukshma (Subtle) is One;
That a body of constituents eight is;
--Sound, touch, shape, taste and smell
Buddhi (Intellect), Man (Mind) and Ahankhara (Egoity)
That the Puriashta body is (subtle).`,
    elaborationTamil: `இறைவன் உயிர்கட்காக அமைத்துக் கொடுத்த, 'தூலம், சூக்குமம்' என்னும் இருவகை உடம்புகளுள் (தூலஉடம்பின் இயல்பு பற்றி மேலே கூறினோம்) இனி அதுபோலப் புலால் நாற்றம் நாறுதல் இன்றியே உயிர்க்குப் பயன்படுகின்ற சூக்கும தேகத்தைப் பற்றிக் கூறுமிடத்துச் சத்தம் முதலிய தன் மாத்திரைகள் ஐந்தும், அந்தக் கரண நான்கனுள் சித்தம் ஒழிந்த ஏனை மூன்றும் ஆக எட்டும் கூடிய தாகும். அதனால் அது, 'புரியட்டகாயம்' என்றும் சொல்லப்படும்.`,
  },
  {
    id: 2125, tantraId: 8, verseNumber: 2124,
    tamil: `எட்டினில் ஐந்தாகும் இந்திரி யங்களும்
கட்டிய மூன்று கரணமும் ஆயிடும்
ஒட்டிய பாசம் உணர்வுஅது வாகவே
கட்டி அவிழ்ந்திடும் கண்ணுதல் காணுமே`,
    transliteration: `eṭṭiṉil aintākum intiri yaṅkaḷum
kaṭṭiya mūṉṟu karaṇamum āyiṭum
oṭṭiya pācam uṇarvuatu vākavē
kaṭṭi aviḻntiṭum kaṇṇutal kāṇumē`,
    english: `2124: Five Indriyas and Three Karanas
Of the organs eight thus stated,
First Five are Indriyas (External Sense Organs)
The rest three are Karanas (Internal Sense Organs)
To these attached is primordial Pasa's sentience,
Thus He binds them
And unbinds them,
He, the Lord of Forehead-Eye.`,
    elaborationTamil: `எட்டுக் கருவிகள் கூடியதனால் 'புரியட்ட காயம்' எனப்படும் உடம்பு - என மேற்கூறப்பட்ட சூக்கும சரீரத்திலிருந்தே மாபூதங்கள் ஐந்தும், இருவகை இந்திரியங்களும் தோன்றும். (எனவே, அப்பதினைந்தும் கூடியதே தூலசரீரமாம்.) இனித்தூல சரீரத்தில் உள்ள இருவகை இந்திரியங்களும், சூக்கும சரீரத்தில் உள்ள அந்தக்கரணங்கள் மூன்றும் 'சரீரம்' எனப்பட்டாலும், உண்மையில் அவை கரணங்களேயாம். அறிவுக்குத் துணையாதல்பற்றி ஆன்மாவோடு பெரிதும் ஒற்றுமைப் பட்டு நிற்கின்ற அவற்றைக் கொண்டே சிவன் ஆன்மாவின் அறிவைப் புலன்களில் அகப்படுத்தி வைத்துப் பின்பு அப்புலன்க ளினின்றும் பிரித்துவிடுவான்.`,
  },
  {
    id: 2126, tantraId: 8, verseNumber: 2125,
    tamil: `இரதம் உதிரம் இறைச்சிதோல் மேதை
மருவிய அத்தி வழும்பொடு மச்சை
பரவிய சுக்கிலம் பாழாம் உபாதி
உருவ மலால்உடல் ஒன்றென லாமே`,
    transliteration: `iratam utiram iṟaiccitōl mētai
maruviya atti vaḻumpoṭu maccai
paraviya cukkilam pāḻām upāti
uruva malāluṭal oṉṟeṉa lāmē`,
    english: `2125: Gross Body
Lymph, blood, flesh, skin, and tendons,
Bones, marrow, fat, brain and semen,
--Of these into one shape made
Is the body gross,
By sorrow harassed.`,
    elaborationTamil: `நிலையாய் இராமல் நிலையழிந்து ஒழிந்து போவன வாகியகுருதி, இறைச்சி முதலிய அழுக்குப்பொருள்களாம் பருப் பொருள்களது தொகுதியைத் தவிரத் தூல உடம்பு வேறு ஏதுவாதல் கூடும்?`,
  },
  {
    id: 2127, tantraId: 8, verseNumber: 2126,
    tamil: `ஆரே அறிவார் அடியின் பெருமையை
யாரே அறிவார் அங்கவர் நின்றது
யாரே அறிவார் அறுபத்தெட்டு ஆக்கையை
யாரே அறிவார் அடிக்காவல் ஆனதே`,
    transliteration: `ārē aṟivār aṭiyiṉ perumaiyai
yārē aṟivār aṅkavar niṉṟatu
yārē aṟivār aṟupatteṭṭu ākkaiyai
yārē aṟivār aṭikkāval āṉatē`,
    english: `2126: God is Within the Body
Who knows the greatness of His Holy Feet
Who knows
There within the body He stood!
Who knows this body
Of Tattvas six and ten and eight!
Who knows that
He is its Yeoman Guard!`,
    elaborationTamil: `மேல், 'அத்தன் அமைத்த உடல்' என்றபடி உயிர்களின் தகுதியை அறிந்து அத்தகுதிக்கேற்பப் பல்வேறு வகையான உடம்புகளை அமைத்துத் தருகின்ற இறைவனது அருள் மிகுதியையும் ஆற்றலின் மிகுதியையும் அறிய வல்லுநர் யாவர்; அந்நிலையில் 'மக்களாய்ப் பிறந்தோர் அவ்வுடம்பைப் பெறுதற்குப் பல பிறவிகளில் தாம் செய்த நல்வினை இவை' என்பதை அறிய வல்லுநர் யாவர்; மக்களுடம்பு அசுத்த உலகத்து உளது ஆதலின் அஃது அவ்வுலகத்திற்கு மேல் உள்ள மிச்சிர உலகம், சுத்த உலகம் என்பவற்றில் உள்ளோரது உடம்புகளில் உள்ள கருவிகட்குமேல் அறுபத்தெட்டுக் கருவிகள் கூடியது என்பதை அறிபவர் யாவர்! மூவகை உலகத்து உயிர்கட்கும் திருவருளே முதற்காவலாய் உள்ளது என்பதை அறிகின்றவர் யாவர்! ஒருவரும் இல்லை.`,
  },
  {
    id: 2128, tantraId: 8, verseNumber: 2127,
    tamil: `எண்சாண் அளவால் எடுத்த உடம்புக்குள்
கண்கால் உடலில் சுரக்கின்ற கைகளில்
புண்கால் அறுபத்தெட்டு ஆக்கை புணர்கின்ற
நண்பால் உடம்பு தன் னால் உடம் பாமே`,
    transliteration: `eṇcāṇ aḷavāl eṭutta uṭampukkuḷ
kaṇkāl uṭalil curakkiṉṟa kaikaḷil
puṇkāl aṟupatteṭṭu ākkai puṇarkiṉṟa
naṇpāl uṭampu taṉ ṉāl uṭam pāmē`,
    english: `2127: Twenty-Four Bodily Tattvas (Universals)
The body eight spans measures
With eyes, legs and hands
That serve to cover it;
In that body of pores and sores
He conjoins Tattvas twenty and four
In love divine;
Thus this body He fashions,
That has four more to speak of.`,
    elaborationEnglish: `i)Vital breath-body—(Pranamaya kosam) ii)Mind-body—(Manomaya kosam) iii)Intelligence-body—(Vijnanamaya kosam) iv)Bliss-body—(Anandamaya kosam)`,
    elaborationTamil: `உடம்பை 'எண்சாண் உடம்பு' என்றல் யாவரும் அறிந்தது. 'அவரவர் கையால் எண்சாணேயாகும்' என்பது இதன் பொருள். 'எறும்பும் தன் கையால் எண்சாண்' (தனிப்பாடல் திரட்டு, என்றார் ஔவையார். இந்த அளவு யாவராலும் நன்கறியப்பட்ட தூல தேகத்தைப் பற்றியதே. அந்த உடம்பிற்றானே கண் முதலிய ஞானேந்திரியங்களும், கால் முதலிய கன்மேந்திரியங்களும் ஆற்றல் வடிவாய்ச் சூக்குமமாய்த் தோன்றாது நிற்கின்றன. எவ்வாற்றா லேனும், எவ்விடத்திலேனும் ஊறு உண்டாகுமாயின் அவ்விடம் புண்ணாகிக் குருதியையும், சீழையும் ஒழுக விடுகின்ற தூல தேகத்தைத் தோற்றுவித்தற் பொருட்டு மேற்கூறிய அறுபத்தெட்டுக் கருவிகளைத் தக்கவாற்றால் திருவருள் ஒன்று சேர்க்கின்ற சேர்க்கையால் ஓர் உடம்பிலிருந்து மற்றோர் உடம்பு தோன்றுவதாகும்.`,
  },
  {
    id: 2129, tantraId: 8, verseNumber: 2128,
    tamil: `உடம்புக்கும் நாலுக்கும் உயிராகிய சீவன்
ஒடுங்கும் பரனோடு ஒழியாகப் பிரமம்
கடந்தொறும் நின்ற கணக்கது காட்டி
அடங்கியே அற்றது ஆரறி வாறே`,
    transliteration: `uṭampukkum nālukkum uyirākiya cīvaṉ
oṭuṅkum paraṉōṭu oḻiyākap piramam
kaṭantoṟum niṉṟa kaṇakkatu kāṭṭi
aṭaṅkiyē aṟṟatu āraṟi vāṟē`,
    english: `2128: Jiva Has Five Experiences
The Jiva that as experient spirit stood (in Avastas)
In all bodies, this and four rest (Jagra, Swapna, Sushupti, Turiya and Turiyatita)
Will in Para merge;
Who knows the way it merges
Into Param that pervades all
As unto space in every pot,
Inside and out!`,
    elaborationEnglish: `Jiva standing in avastas, undergoes the five experiences — jagrat, svapna, sushupti, turiya and turiyatita—before it merges into Param that animates all.

This is a doctrine unique to Tirumular. ‘‘Beyond the fourth state (Turiya) stands the fifth (Turiyatita),"’ he says. It is like *‘a tortoise with the limbs withdrawn, when the Jiva is pervaded by Aum and the Light Divine beams from within, (whereby) the Self its sentience loses’’. (The influence of Buddhism is to be noted). In this state, ‘the Senses Five and the Tattvas’’ are left behind (verse 2165). Jiva stands in experience as AVASTA; It has FIVE experiences, namely, Jagrat, Swapna, Sushupti, Turiya and Turiyatita. (The Sth is not known (in Vedanta), but is peculiar to Sakta Religion (see = a Woodroffe, They all merge in Para akti).`,
    elaborationTamil: `தூல உடம்புக்குள் சூக்கும உடம்பாய் நிற்கின்ற அந்தக்கரணங்கள் நான்கிற்கும், மேலும் நுண்ணிதான அதிசூக்கும உடம்பைக் கொண்டு இயக்கும் முதற்பொருளாய் உள்ள சீவான்மாத் தான் பரமான்மாவாகிய சிவத்தில் வியாப்பியமாய் நிற்கும். ஆகவே, எப்பொருளிலும் எஞ்சாது நிறைந்து நிற்கும் பிரமப் பொருளாகிய சிவம், தான் ஒன்றேயாயினும் பல சீவான்மாக்களிலும் வியாபித்து அதனதன் தன்மைக்கேற்ப ஏகதேசமாயும் நின்று, பின் சீவான்மா சீவத்துவம் (பசுத்துவம்) நீங்கிய பொழுது தன்னைப் போலவே வியாபகமாகிவிடுதலால் அவ்வேகதேசத் தன்மை நீங்கி வியாபகமாகி விடுகின்ற தன்மை, ஞாயிறு ஒன்றேயாய் வியாபகமாயினும் பல குடங் களில் உள்ள நீரில் எல்லாம் அதனதன் அளவிற்கேற்ப வேறு வேறு அளவில் பலவாய்த் தோன்றி, அக்குடங்களில் நீர் நீங்கிய பொழுது முன்பு நின்ற சிறு நிலையின் நீங்கி வியாபகமாகிவிடுகின்ற தன்மையை ஒக்கும் என்னும் உண்மையை அறிந்தனர் எத்துணைப் பேர்!`,
  },
  {
    id: 2130, tantraId: 8, verseNumber: 2129,
    tamil: `ஆறுஅந்த மாகி நடுவுடன் கூடினால்
தேறிய மூவாறும் சிக்கென்று இருந்திடும்
கூறுங் கலைகள் பதினெட்டும் கூடியே
ஊறும் உடம்பை உயிருடம்பு எண்ணுமே`,
    transliteration: `āṟuanta māki naṭuvuṭaṉ kūṭiṉāl
tēṟiya mūvāṟum cikkeṉṟu iruntiṭum
kūṟuṅ kalaikaḷ patiṉeṭṭum kūṭiyē
ūṟum uṭampai uyiruṭampu eṇṇumē`,
    english: `2129: Kala Body Holds Life
You unite through central Sushumna,
The nine orifices tightly controlled will be;
The body within of Kalas eighteen formed* will be;
That the body of Jiva will be.`,
    elaborationEnglish: `The causal or kala body is yet another. It is formed of eighteen tattvas and is truly the body that enters the womb and holds life.

1) Five external senses, three internal organs, and ten vayus.`,
    elaborationTamil: `யோகமுறையால் ஆறு ஆதாரங்களும் கீழாகி யதனால், அவற்றிற்குமேல் உள்ள பிரமரந்திரத்தை அடைந்தால், அங்ஙனம் அடைந்தவருடைய தூல உடம்பு விரையில் அழிந் தொழியாது உறுதி பெற்று நெடுநாள் இருக்கும். அந்நிலையில் சூக்கும உடம்பும் அதற்கு சார்பாய் உறுதிப்பட்டு நின்று, அதனை என்றுமே உயிர் உள்ள உடம்பாகச் செய்யும்.`,
  },
  {
    id: 2131, tantraId: 8, verseNumber: 2130,
    tamil: `மெய்யினில் தூல மிகுந்த முகத்தையும்
பொய்யினில் சூக்கம் பொருந்தும் உடலையும்
கையினில் துல்லியம் காட்டும் உடலையும்
ஐயன் அடிக்குள் அடங்கும் உடம்பே`,
    transliteration: `meyyiṉil tūla mikunta mukattaiyum
poyyiṉil cūkkam poruntum uṭalaiyum
kaiyiṉil tulliyam kāṭṭum uṭalaiyum
aiyaṉ aṭikkuḷ aṭaṅkum uṭampē`,
    english: `2130: Bodies--Gross, Subtle and Causal Merge In Para
The Gross body with presence prominent,
The Subtle body that invisible takes shape,
And the Causal body that by inference is,
--All these bodies are
That in Lord's Feet merge.`,
    elaborationEnglish: `Like the prancing steed That forward leaps The Jiva, too, traverses near and far; Like those who off one garment And another The Jiva, too, from one to the other body moves.`,
    elaborationTamil: `'தூலம், சூக்குமம், பரம்' என்னும் மூன்றுடம்பு களையும் ஒருங்குசேர்த்து ஓர் உடம்பிற்கு உவமித்தால், தூல உடம்பு முகத்தையும், சூக்கும உடம்பு கழுத்திற்குக் கீழும், காலுக்கு மேலும் உள்ள உடலையும், பர உடம்பு கைகால்களையும் ஒத்து நிற்கும் அவ்வாறு அமைந்த அந்தப் பேருடம்பு சிவனது திருவருளில் அடங்கும்.`,
  },
  {
    id: 2132, tantraId: 8, verseNumber: 2131,
    tamil: `காயும் கடும்பரி கால்வைத்து வாங்கல் போல்
சேய இடம்அண்மை செல்லவும் வல்லது
காயத் துகிர் போர்வை ஒன்றுவிட்டு ஆங்குஒன்றிட்டு
ஏயும் அவரென்ன ஏய்ந்திடும் காயமே`,
    transliteration: `kāyum kaṭumpari kālvaittu vāṅkal pōl
cēya iṭamaṇmai cellavum vallatu
kāyat tukir pōrvai oṉṟuviṭṭu āṅkuoṉṟiṭṭu
ēyum avareṉṉa ēyntiṭum kāyamē`,
    english: `2131: Jiva Incarnates in Many Bodies
As unto the prancing steed
That forward leaps
The Jiva, too, traverses near and far;
As unto those who doff one garment
And another
The Jiva, too, from one to the other body moves.`,
    elaborationTamil: `பகைவரைச் சினக்கின்ற வேகம் பொருந்திய போர்க் குதிரை அண்மை, சேய்மை என்னும் இடங்கட்குத் தக்கபடி முன்கால்களை எட்டி வைத்துப் பின் கால்களை வாங்கிக்கொண்டு தடையின்றி ஓடுதல் போலச் சூக்கும உடல் அண்மை சேய்மைகளுக்கு ஏற்ப விரைந்து செல்ல வல்லது. அதனால், உயிர் அவ்வுடலைப் பற்றிக் கொண்டு, அத்தன்மையில்லாத தூல உடம்புகளுள் ஒன்றை விட்டு நீங்கி மற்றொன்றை எங்கு வேண்டுமானாலும் சென்று எடுத்துக் கொள்ளும். தூல சரீரம் சூக்கும சரீரத்தின் மேல் போர்வைபோலவே உள்ளதாகும். அதனால், உயிர் தூல உடம்பில் ஒன்றை நீக்கி விட்டு, மற்றொன்றை எடுத்துக் கொள்ளுதல் மக்கள் தமது போர்வை ஒன்றை நீக்கிவிட்டு மற்றொன்றை எடுத்துப் போர்த்துக் கொள்ளுதல் போல்வதே.`,
  },
  {
    id: 2133, tantraId: 8, verseNumber: 2132,
    tamil: `நாகம் உடல்உரி போலும்நல் அண்டச
மாக நனாவில் கானாமறந் தல்லது
போகலும் ஆகும் அரன்அரு ளாலே சென்று
ஏகும் இடம்சென்று இருபயன் உண்ணுமே`,
    transliteration: `nākam uṭaluri pōlumnal aṇṭaca
māka naṉāvil kāṉāmaṟan tallatu
pōkalum ākum araṉaru ḷālē ceṉṟu
ēkum iṭamceṉṟu irupayaṉ uṇṇumē`,
    english: `2132: In the Waking State Dreams are Forgotten;
So it is Through Successive Lives
Even as the snake sloughs off its skin
And another assumes;
Even as the bird its shell leaves
And another life pursues;
In its waking state the Jiva forgets
Happenings of the dream state;
Thus does Jiva from one body to another migrate;
Until with Grace of Hara
It reaches where it is destined to be;
And there experiences
The Karmas two, good and evil.`,
    elaborationTamil: `இவ்வுலகில் ஓர் உடம்பை விட்டு நீங்கிய உயிர் இறைவனது அருளாணையின்படி வேறோர் உடலில் சென்று, அவ் வுடலுக்குரிய இடத்தை அடைந்து, முன்பு இருந்து இடத்தில் அனுபவித்த அனுபவங்களை மறந்து அவ்விடத்து வரும் இன்பத் துன்பங்களை அனுபவிக்கும் அவை எவை போல எனின், பாம்பு முன்பிருந்த உடம்பாகிய தோலை நீக்கிவிட்டுப் புதிய உடம்பைப் பெறுதல் போல்வதும், முட்டையிற் பிறக்கும் உயிர்கள் முன்பு முட்டைக்குள் இருந்து பின்பு வெளிவந்து வேறு இடத்தை அடைதல் போல்வதும், கனவில், முன்பு நனவில் நிகழ்ந்தவற்றை மறத்தல் போல்வதுமாகும்.`,
  },
  {
    id: 2134, tantraId: 8, verseNumber: 2133,
    tamil: `உண்டு நரக சுவர்கத்தில் உள்ளன
கண்டு விடும்சூக்கம் காரண மாச்செலப்
பண்டு தொடரப் பரகாய யோகிபோல்
பிண்டம் எடுக்கும் பிறப்பு இறப்பு எய்தியே`,
    transliteration: `uṇṭu naraka cuvarkattil uḷḷaṉa
kaṇṭu viṭumcūkkam kāraṇa māccelap
paṇṭu toṭarap parakāya yōkipōl
piṇṭam eṭukkum piṟappu iṟappu eytiyē`,
    english: `2133: Cycle of Births and Deaths
Having experienced hell and heaven,
Jiva leaves Subtle body;
Entering Causal body its course continues;
And unto the Yogi that transmigrates
Enters yet another body;
Thus entangled in cycle of birth and death.`,
    elaborationEnglish: `After experiencing heaven and hell, jiva leaves the subtle body and continues its birth course with the causal body. Like the yogi that transmigrates, the causal body enters another body, and is.thus caught in the cycle of births and deaths.`,
    elaborationTamil: `ஓர் உயிர் நிலத்தில் இறந்தபின் சூக்கும சரீரம் பற்றாகச் சென்று நரக சுவர்க்கங்களை அடைந்து அங்கு உள்ளவைகளைப் பார்த்து அவற்றால் வரும் துன்ப இன்பங்களை நுகர்ந்து, அந்த உலகங்களை விடுத்துத் தான் செய்த வினையில் மேற் கூறிய உலகங்களில் நுகரப்பட்டு எஞ்சி நிற்கின்ற வினைகள் தொடர்த லால், யோக சித்தர் ஓர் உடம்பை விட்டும் மற்றோர் உடம்பில் புகுதல் போல வேறு பிறப்பை அடைந்து மீண்டு நிலவுலகத்தில் அப்பிறப்பிற் குரிய உடம்பை எடுத்துக் கொள்ளும்.`,
  },
  {
    id: 2135, tantraId: 8, verseNumber: 2134,
    tamil: `தான்அவ னாகிய தற்பரம் தாங்கினோன்
ஆனவை மாற்றிப் பரமத்து அடைந்திடும்
ஏனை உயிர்வினைக்கு எய்தும் இடம்சென்றும்
வானும் நிலனும் புகுந்தும் வருந்துமே`,
    transliteration: `tāṉava ṉākiya taṟparam tāṅkiṉōṉ
āṉavai māṟṟip paramattu aṭaintiṭum
ēṉai uyirviṉaikku eytum iṭamceṉṟum
vāṉum nilaṉum pukuntum varuntumē`,
    english: `2134: The Birth Cycle ends only when Jiva Unites in God
The Jiva that realized
"I" and "You" are one,
Is in Tatpara state;
Its course inherent diverting
Will reach Param;
The rest of Jivas
Reaching their destined abodes
In heaven and earth
Will in sorrow wallow.`,
    elaborationTamil: `தான் சிவனேயாய் நிற்கின்ற சிவ யோகி, அது காறும் தான் அடைந்திருந்த நிலைகளை யெல்லாம் போக்கி, உடல் நீங்கினபின் அந்நிலைக்கு அப்பாற்பட்ட முடிநிலைப்பேற்றை அடைவான். அந்நிலையை அடையாது தாமேயாய் நிற்கின்ற மற்ற உயிர்கள் தாம் செய்த வினைக்கீடாகக் கிடைக்கின்ற இடங்களில் செல்வனவாய், விண்ணுலகிலும், மண்ணுலகிலும் புகுந்து துன்புறும்.`,
  },
  {
    id: 2136, tantraId: 8, verseNumber: 2135,
    tamil: `ஞானிக்குக் காயம் சிவமாகும் நாட்டிடில்
ஞானிக்குக் காயம் உடம்பே அதுவாகும்
மேனிக்கும் யோகிக்கும் விந்துவும் நாதமும்
மோனிக்குக் காயம்முப் பாழ்கெட்ட முத்தியே`,
    transliteration: `ñāṉikkuk kāyam civamākum nāṭṭiṭil
ñāṉikkuk kāyam uṭampē atuvākum
mēṉikkum yōkikkum vintuvum nātamum
mōṉikkuk kāyammup pāḻkeṭṭa muttiyē`,
    english: `2135: Body Substrates of Evolved Beings
Siva is the ground (Dhanu) of Jnani's body,
Jnani's body is Siva's body,
Yogi's body is Nada and Bindu,
Mauni's body is Mukti
Beyond Voids Three.`,
    elaborationEnglish: `Siva is the ground or substrate of the jnani’s body. The ground or substrate of the -yogi’s body is nada and bindu. Mukti beyond the three voids is the substrate of the -mauni’s body. Anava (egoity) is the ground of the vijnani’s body. Maya is that of the pralayakalas and karma that of the sakalas.`,
    elaborationTamil: `மெய்ஞ்ஞானிக்கு உடம்பாவது சிவனது அரு ளாகிய உடம்பேயாம், அஞ்ஞானிக்கு உடம்பாவது புலாலால் ஆகிய அந்த உடம்பேயாம். அஞ்ஞானிக்குமேல் நிற்பவனாகிய யோகிக்குப் பைசந்தி வாக்கும் அதற்கு மேல் உள்ள சூக்குமை வாக்கும் தக்கபடி உடம்பாகும். ஞானத்தின் மேல் எல்லையாகிய மோன நிலையை எய்தியவன் முப்பாழையும் கடந்த முத்தி நிலையையே உடம்பாகக் கொண்டிருப்பான்.`,
  },
  {
    id: 2137, tantraId: 8, verseNumber: 2136,
    tamil: `விஞ்ஞானத் தோர்க்குஆ ணவமே மிகுதனு
எஞ்ஞானத் தோர்க்குத் தனுமாயை தான்என்ப
அஞ்ஞானத் தோர்க்குக் கன்மம் தனுவாகும்
மெஞ்ஞானத் தோர்க்குச் சிவதனு மேவுமே`,
    transliteration: `viññāṉat tōrkkuā ṇavamē mikutaṉu
eññāṉat tōrkkut taṉumāyai tāṉeṉpa
aññāṉat tōrkkuk kaṉmam taṉuvākum
meññāṉat tōrkkuc civataṉu mēvumē`,
    english: `2136: Body Substrates of Jivas in Three Stages of Evolution
Anava (Egoity) is the (Dhanu) ground of Vijnanis
Maya is the ground of Pralayakalas
Karma is the ground of Sakalas
Siva is the ground of Jnanis True.`,
    elaborationTamil: `மூவகை ஆன்ம வர்க்கத்தினருள் விஞ்ஞானகலர் நிலையை ஆணவமே சூக்கும தேகமாய் நிற்கும். இனி அந்த விஞ்ஞானகலர்க்கு அடைய இருப்பவராகிய பிரளயாகலருக்கு அசுத்த மாயையே எல்லா உடம்புமாய் இருக்கும். 'ஞானம் இல்லாதவர்' எனப் படுகின்ற சகலர்க்குக் கன்மத்திற்கு ஈடாக வருகின்ற பிராகிருதங்களே உடம்பாகும். ஆகவே, அருள் உடம்பு மெய்ஞ்ஞானைத்தை எய்தினவர்கட்கே வாய்ப்பதாம்.`,
  },
  {
    id: 2138, tantraId: 8, verseNumber: 2137,
    tamil: `மலமென்று உடம்பை மதியாத ஊமர்
தலமென்று வேறு தரித்தமை கண்டீர்
நலமென்று இதனையே நாடி இருக்கில்
பலமுள்ள காயத்தில் பற்றும்இவ் அண்டத்தே`,
    transliteration: `malameṉṟu uṭampai matiyāta ūmar
talameṉṟu vēṟu tarittamai kaṇṭīr
nalameṉṟu itaṉaiyē nāṭi irukkil
palamuḷḷa kāyattil paṟṟumiv aṇṭattē`,
    english: `2137: Lord is in Body, do not Despise it
Dumb fools are they
Who as Mala (Impurity) despise the body;
Other places as holy
They go about seeking;
They who consider "Good this is"
And in it seek the Lord,
Shall experience macrocosm entire,
In their body tenacious`,
    elaborationTamil: `அறிவுடையீர், தம் உடம்பை அருவருத்து நீக்கத் தக்கதாக அறிவும் அறிவையில்லாதவர் அதனையே தாம், என்றும் இருக்கும் இடமாகக் கருதி, அதன்கண் தனியான ஒருபற்று வைத்துப் போற்றிவருதலைக் கண்டீரன்றோ! அவர் நிலையை அடைந்திருக்கும் உயிர்கள் அதன் பயனாகப் பற்பல தூல தேகங்களை எடுத்து உலகங்களிலேயே உழலும்.`,
  },
  {
    id: 2139, tantraId: 8, verseNumber: 2138,
    tamil: `நல்ல வசனத்து வாக்கு மனாதிகள்
மெல்ல விளையாடும் விமலன் அகத்திலே
அல்ல செவிசத்த மாதி மனத்தையும்
மெல்ல தரித்தார் முகத்தார் பசித்தே`,
    transliteration: `nalla vacaṉattu vākku maṉātikaḷ
mella viḷaiyāṭum vimalaṉ akattilē
alla cevicatta māti maṉattaiyum
mella tarittār mukattār pacittē`,
    english: `2138: God Rejoices in the Body of the Good
Those who are
Of goodly speech, deed and thought,
In their hearts
The Pure One gently sports;
Those who are
Of evil ears, speech, and mind
Emaciated they live, their faces in hunger drawn.`,
    elaborationTamil: `நல்ல சொற்களையே பேசுகின்ற வாக்கிலும், நல்ல நினைவுகளையே நினைக்கின்ற மனம் முதலிய அகக்கருவிகளிலும் இறைவன் மெல்ல மெல்ல வெளிப்பட்டு விளையாடுவான். நல்லன அல்லாத சொற்களையே கேட்க விரும்புகின்ற செவியையும், அவ்வாறே, அறியத் தகாத தம் தம் புலன்களையே அறிய விரும்புகின்ற கண் முதலிய ஏனைப் பொறிகளையும், நல்லன அல்லாதவற்றையே நினைக்கின்ற உட்கருவிகளையும் உடைய மக்கள் இவ்வுலகில் வறுமையால் பசி மிக்கவராய் வருந்துவர்.`,
  },
  {
    id: 2140, tantraId: 8, verseNumber: 2139,
    tamil: `பண்ணாக்கும் காமம் பயிலும் வசனமும்
விண்ணாம் பிராணன் விளங்கிய சத்தமும்
புண்ணாம் உடலில் பொருந்தும் மனத்தையும்
அண்ணாந்து பார்க்க அழியும் உடம்பே`,
    transliteration: `paṇṇākkum kāmam payilum vacaṉamum
viṇṇām pirāṇaṉ viḷaṅkiya cattamum
puṇṇām uṭalil poruntum maṉattaiyum
aṇṇāntu pārkka aḻiyum uṭampē`,
    english: `2139: Sublimate Speech and Thought Godward
The sweet speech, love intones
The loud sound, airy prana articulates
The mind within fleshly body dwells
--All these you upward course (in Yogic way),
No more, the thoughts of body be.`,
    elaborationEnglish: `Divert your hearing, speech, and mind in the yogic way towards God while you are in the fleshy body. You will no more think of your body. When the body perishes, nothing remains behind. Apap CanGr_wb utg@ey Dealascor span srac Ogsmact send Onorpaep aurée wpyHerm grin epPHap eigé GHigimesx WawemavGu. 2140`,
    elaborationTamil: `நன்கு அமைந்த உடலால் எழுகின்ற காமமும், பலவகையாகப் பேசுகின்ற பேச்சுக்களும், வெளிச்செல்லும் பொழுது விளங்கி நிற்கின்ற மூச்சும், அம்மூச்சுப் பெரிதாயவழி எழுகின்ற ஓசையும், புலால் வடிவாகிய உடம்பின் உள்ளே இருப்பதாகிய மனமும் ஆகிய இவைகளையெல்லாம் பிறர், 'எங்கே போயின' என்று திகைத்து அண்ணாந்து பார்க்கும்படி உடல் முதலில் நிலையழிந்து, பின்னர் உருவும் அழிந்தொழியும்.`,
  },
  {
    id: 2141, tantraId: 8, verseNumber: 2140,
    tamil: `அழிகின்ற ஓர் உடம்பு ஆகும் செவிகள்
கழிகின்ற காலவ் விரதங்கள் தானம்
மொழிகின்ற வாக்கு முடிகின்ற நாடி
ஒழிகின்ற ஊனுக்கு உறுதுணை இல்லையே`,
    transliteration: `aḻikiṉṟa ōr uṭampu ākum cevikaḷ
kaḻikiṉṟa kālav virataṅkaḷ tāṉam
moḻikiṉṟa vākku muṭikiṉṟa nāṭi
oḻikiṉṟa ūṉukku uṟutuṇai illaiyē`,
    english: `2140: When Body Perishes, Nothing There Is
The body perishes;
With it, ears and eyes;
Speech and pulse;
Fasts and gifts;
Nothing left, for dying flesh to lean on.`,
    elaborationEnglish: `The body perishes; With it, ears and eyes; Speech and pulse;`,
    elaborationTamil: `நிலையின்றி அழிவதாகிய உடம்பை இடமாகக் கொண்டிருப்பனவே செவி, கண் முதலிய அறிவுப் பொறிகளும், வாக்கு முதலிய செயற்பொறிகளும், அவற்றின்வழி வருகின்ற புல இன்பங்களும், அந்தக் கரணங்களுக்கு வலுவூட்டுகின்ற பிராண வாயு வும், ஒன்றையொன்றோடு முடிந்துவைத்துள்ள நாடிகளும், மற்றும் பல ஆற்றல்களுக்கு உரிய இடங்களும். ஆகவே, உடம்பு அழிந்தால், அவையும் அதனோடே அழிந்தொழிதலால், அழிவதாகிய உடம்பிற்கு அதனை அழியாது நிலைபெறுத்துவதொருதுணை எதுவுமில்லை.`,
  },
  {
    id: 2142, tantraId: 8, verseNumber: 2141,
    tamil: `இலையாம் இடையில் எழுகின்ற காமம்
முலைவாய நெஞ்சத்து மூழ்கும் உளத்துத்
தலையாய மின்னுடல் தாங்கித் திரியும்
சிலையாய சித்தம் சிவமுன் இடைக்கே`,
    transliteration: `ilaiyām iṭaiyil eḻukiṉṟa kāmam
mulaivāya neñcattu mūḻkum uḷattut
talaiyāya miṉṉuṭal tāṅkit tiriyum
cilaiyāya cittam civamuṉ iṭaikkē`,
    english: `2141: The Pure Will Reach God
The heart that lusts after
Slender-waisted damsels,
Will in distress immersed be;
They, with hearts pure,
Body glowing as lightning
And Will made of iron
Are for Siva's presence destined.`,
    elaborationEnglish: `Purity and steadfastness take you Godward, while mean love and-lust immerse you in distress and misery forever.`,
    elaborationTamil: `மாதரது நுண்ணிய இடையின்மேல் எழுகின்ற காம உணர்ச்சி மக்கள் உள்ளங்களில் உலையிடத்தில் உள்ள நெருப்புப் போல மிகுகின்ற ஆசையாலே பெருகி மிகும். ஆயினும் அந்த ஆசையால் சிறிதும் கலங்காது கல்போல உறுதியுற்று நிற்கும் உள்ளம் உடையவர்கள், சிவனது திருமுன்பில் காமம், குரோதம் முதலிய குற்றங்களோடு கூடாது மேன்மையுற்று விளங்குகின்ற ஒளி உடம்பைப் பெற்று வாழ்வார்கள்.`,
  },
  {
    id: 2143, tantraId: 8, verseNumber: 2142,
    tamil: `ஐஐந்து மத்திமை யானது சாக்கிரம்
கைகண்ட பன்னான்கில் கண்டம் கனாஎன்பர்
பொய்கண் டிலாத புருடன்இத யம் சுழுனை
மெய்கண் டவன் உந்தி ஆகும் துரியமே`,
    transliteration: `aiaintu mattimai yāṉatu cākkiram
kaikaṇṭa paṉṉāṉkil kaṇṭam kaṉāeṉpar
poykaṇ ṭilāta puruṭaṉita yam cuḻuṉai
meykaṇ ṭavaṉ unti ākum turiyamē`,
    english: `2142: Where Tattvas Stand in the Four States of Jiva
Awareness
In the Waking State (Jagra)
The Tattvas twenty and five
In Eye-Brow Center their position take;
In the Dream State (Swapna)
Tattvas ten and four
In Throat Center their hold take;
In Deep Sleep state (Sushupti)
The Purusha (Soul) stands
Alone in Heart Center;
In Turiya State (Fourth)
He (Purusha) stands
In Center that is Navel.`,
    elaborationEnglish: `In Centre that is Navel.

The lower avasta pertains to jiva in its pre-biological kevala state, and has two aspects, the causal and the caused. The caused state has the five experiences: jagra (waking); svapna (dream); sushupti (deep sleep); turiya (beyond deep sleep); and turiyatita (beyond turiya). Tirumular does not refer to turiyatita in this context.`,
    elaborationTamil: `மேற்கூறிய அவத்தைகளில் மத்தியாலவத்தை ஐந்தும், கீழாலவத்தைச் சாக்கிரமும் நிகழும் இடம்புருவநடு, அவற்றுள் மத்தியா லவத்தைச் சாக்கிரமும் ஒன்றிலேதான் எல்லாக் கருவிகளும் குறை வின்றிச் செயற்படும். மற்றையவற்றில் சிற்சில கருவிகள் செயற்படாது நிற்கும். அவற்றைப் பிரிந்தும், கூடியும் வரும் கருவிகளாகக் கூறுவர். மத்தியாலவத்தையை விட்டு, ஆன்மாக் கீழாலவத்தையில் சாக்கிரத்தை அடைதற்குக் காரணம் ஆன்ம தத்துவங்களில் சிலவும், தாத்துவிகங் களில் சிலவும் குறைதலேயாகும். அந்நிலையில், கீழாலவத்தைச் சாக்கிரத்தில் செயற்படும் கருவிகள் முப்பத்தைந்து' என்று சொல்லப் படுகின்றது. 'சாக்கிரம் முப்பத்தைந்து நுதலினில்' என்பது சிவஞான சித்தியார்.3 முப்பத்தைந்தில் தத்துவம் பதினைந்து; தாத்துவிகம் இருபது. ஞானேந்திரியம் ஐந்து, கன் மேந்திரியம் ஐந்து, அந்தக்கரணம் நான்கு, புருடன் ஒன்று. இவை தத்துவங்கள், ஞானேந்திரிய விடயம் ஐந்து, கன் மேந்திரிய விடயம் ஐந்து, பிராணாதி வாயுக்கள் பத்து. இவை தாத்து விகங்கள். 'முப்பத் தைந்து' எனத் தொகை கூறி வரையறுத்தது பிரிந்தும், கூடியும் வரும் நிலைமையுடைய கருவிகளை நோக்கியேயாம். ஆகவே, பிரிவின்றி எஞ்ஞான்றும் கூடியே நிற்கும் கருவிகள் இந்த அவத்தை பேதங்களில் நீங்குவன அல்ல. அவை வித்தியா தத்துவம் ஏழும், சிவ தத்துவம் ஐந்துமாம். 'புருடன்' என்பது ஒரு தத்துவம் அன்று. காலம், நியதி, கலை, வித்தை, அராகம் ஐந்தும் கூடிய நிலையேயாம். இவை ஐந்திற்குக் காரணம் 'மாயை' என்னும் தத்துவம். எனவே, புருடன்' என்றதனால், மேற்கூறியவற்றோடு சிவ தத்துவமும் பெறப்படும். ஆகையால் 'முப்பத்தைந்து' எனச் சுருக்கமாகக் கூறியபோதிலும் 'நாற்பத்தாறு' என்பதே உண்மையாம். எனவே, கீழாலவத்தை தொடங் குங்கால், தொண்ணூற்றாறு கருவிகளில், நீங்குவன ஐம்பதே' என்பது விளங்கும். ஐம்பதில் தத்துவம் பத்தும், தாத்துவிகம் நாற்பதும் ஆகும். தத்துவம் பத்தாவன மாபூதங்கள் ஐந்து; தன்மாத்திரை ஐந்து, தாத்துவிகம் நாற்பதவான. மேற்கூறிய சத்தாதி ஐந்து, வசனாதி ஐந்து, பிராணாதி பத்து ஆகிய இருபது தவிர மற்றவையாம்.`,
  },
  {
    id: 2144, tantraId: 8, verseNumber: 2143,
    tamil: `முப்பதோடு ஆறின் முதல்நனா ஐந்தாகச்
செப்புஅதில் நான்காய்த் திகழ்ந்திரண்டு ஒன்றாகி
அப்பதி யாகும் நியதி முதலாகச்
செப்பும் சிவம்ஈறாய்த் தேர்ந்துகொள் ளீரே`,
    transliteration: `muppatōṭu āṟiṉ mutalnaṉā aintākac
ceppuatil nāṉkāyt tikaḻntiraṇṭu oṉṟāki
appati yākum niyati mutalākac
ceppum civamīṟāyt tērntukoḷ ḷīrē`,
    english: `2143: Siva the Beginning and End of Five Avastas
Of the Five Avastas Jagra commencing
That to Tattvas six and thirty pertain,
The Fourth is the luminous Turiya;
Passing beyond to Turiyatita
The Two in One inseparate merge
The Jiva himself Siva becoming;
This the Order do know,
The Siva that stands in the Beginning
Becomes verily in End of Experience all.`,
    elaborationEnglish: `Among the final thirty-six tattvas, twenty-five exist in the waking state; fourteen, in svapna state; one each in sushupti and turiya states.`,
    elaborationTamil: `முப்பத்தாறு தத்துவங்களாலும் (எனவே, தாத்து விகம் அறுபதும் உளவாம் ஆதலின் தொண்ணூற்றாறு கருவிகளாலும்) நிரம்பிய அறிவாய்க் கீழாலவத்தைக்கு முன்னே உள்ள மத்தியா லவத்தையில் சாக்கிரம் நிகழும். அதுபொழுது சிவதத்துவம் ஐந்து உள்ளனவாம். அதன் பின் மத்திய சொப்பனம், மத்திய சுழுத்தி, மத்திய துரியம், மத்திய துரியாதீதம் - என்பவை முறையே சிவ தத்துவங்களில் ஒன்று, இரண்டு, மூன்று. நான்கு குறைய நிற்கும் தத்துவங்கள் நான்கு, மூன்று, ஒன்று, ஆகுமாற்றால் நிகழும் நீங்குவன சுத்த வித்தை முதலாகவாம் ஆதலின், இறுதியில் நிற்பது 'சிவம்' என்பதொன்றுமே யாம். தத்துவங்கள் செலுத்துவனவும், கலை முதலிய ஐந்தும் செலுத்தப் படுவனவும் ஆதலின், செலுத்துவன நான்கும் நீங்கிய பொழுது செலுத்தப்படுவனவற்றிலும் நான்கும் நீங்கும். அவை, 'அராகம், வித்தை, கலை, நியதி - என்பன. எனவே, எப்பொழுதும் நீங்காது நிற்பன 'சிவம்' என்னும் தத்துவமும், அதனால், செலுத்தப்படுகின்ற காலமும் ஆம். ஆகவே, மத்திய துரியாதீதத்தில் நிற்பன அவை மட்டுமேயாம். இவற்றை ஆராய்ந்து உணர்ந்து கொள்ளுங்கள்.`,
  },
  {
    id: 2145, tantraId: 8, verseNumber: 2144,
    tamil: `இந்தியம் ஈரைந்து ஈரைந்து மாத்திரை
மந்திர மாய்நின்ற மாருதம் ஈரைந்தும் அந்தக்
கரணம் ஒருநான்கும் ஆன்மாவும்
பந்தஅச் சாக்கரப் பாலது ஆகுமே`,
    transliteration: `intiyam īraintu īraintu māttirai
mantira māyniṉṟa mārutam īraintum antak
karaṇam orunāṉkum āṉmāvum
pantaac cākkarap pālatu ākumē`,
    english: `2144: Instruments of Experience
Indriyas ten (five sensory organs and five motor organs)
Their Tanmatras ten (Subtle potent elements of Indriyas)
The Vayus ten (winds) that secret work,
The Antakaranas four (inner seats of thought)
And Purusha, the Experient Jiva,
--All these (instruments of experience)
Are again and again entangled`,
    elaborationTamil: `கேவலம் வருமாறு செய்கின்ற அந்தச் சாக்கிரா வத்தையானது ஞானேந்திரியம் ஐந்து, கன்மேந்திரியம் ஐந்து, அவற்றின் விடயங்கள் பத்து, வாயுக்கள் பத்து, அந்தக்கரணம் நான்கு, புருடன் ஒன்று - என்னும் முப்பத்தைந்து கருவிகளால் நிகழும்.`,
  },
  {
    id: 2146, tantraId: 8, verseNumber: 2145,
    tamil: `பாரது பொன்மை பசுமை உடையது
நீரது வெண்மை செம்மை நெருப்பது
காரது மாருதம் கறுப்பை உடையது
வானகம் தூமம் மறைந்துநின் றாரே`,
    transliteration: `pāratu poṉmai pacumai uṭaiyatu
nīratu veṇmai cemmai neruppatu
kāratu mārutam kaṟuppai uṭaiyatu
vāṉakam tūmam maṟaintuniṉ ṟārē`,
    english: `2145: The Five Elements Also Are Within Body
Earth is of color, gold pure;
Water is white;
Fire red;
Wind dark;
Space smoky;
Thus the five elements concealed stand within.`,
    elaborationEnglish: `1) States of experience 2) The 96 tattvas are categorized as follows: Atma tattvas — 24, Nadis — 10, Avastas — 5, Malas — 3, Gunas — 3, Mandalas — 3, Diseases —.3, Vikaras — 8, Adharas — 6, Datus — 7, Vayus — 10, Kosas — S, Orifices`,
    elaborationTamil: `(அவத்தைக்குக் காரணமான கருவிகளுள் மிக எளிதில் விளங்குவனவாகிய ஐம்பெரும் பூதங்களில்) நிலம் பசும் பொன்னிறத்தையும், நீர் வெண்மை நிறத்தையும், நெருப்புச் சிவப்பு நிறத்தையும், காற்றுக் கருப்பு நிறத்தையும், வானம் புகை நிறத்தையும் உடையன. இவற்றின் அதிதேவர்கள் இவைபோலப் புலனாகாது மறைந்து நிற்பார்கள்.`,
  },
  {
    id: 2147, tantraId: 8, verseNumber: 2146,
    tamil: `பூதங்கள் ஐந்தும் பொறியவை ஐந்துளும்
ஏதம் படஞ்செய்து இருந்து புறநிலை
ஓதும் மலம்குணம் ஆகும்ஆ தாரமொடு
ஆதி அவத்தைக் கருவிதொண் ணூற்றாறே`,
    transliteration: `pūtaṅkaḷ aintum poṟiyavai aintuḷum
ētam paṭañceytu iruntu puṟanilai
ōtum malamkuṇam ākumā tāramoṭu
āti avattaik karuvitoṇ ṇūṟṟāṟē`,
    english: `2146: Ninety-Six Tattvas
The elements five, too,
To sense organs additional function;
The five permeating each of Malas three,
Gunas three, and Adharas six;
Together with Tattvas thirty and six,
The organs of Avastas
Are six and ninety, in all.`,
    elaborationTamil: `தத்துவம் முப்பத்தாறனுள் பூதம் ஐந்து, ஞானேந் திரியம் ஐந்து, கன்மேந்திரியம் ஐந்து ஆகப்பதினைந்தும் புறக்குற்றங் களில் மூழ்கச் செய்கின்ற புறக்கருவிகளாம். ஆறு ஆதாரங்களும், ஒரு வகை மாயையாகச் சொல்லப்படுகின்ற பிரகிருதிகுணங்களும் அவத் தைக்கு ஏதுவாகும். அந்நிலையில் ஐந்தவத்தைகளுள் முதலாவதாகிய சாக்கிராவத்தையில் தொண்ணூற்றாறு கருவிகளும் தொழிற்படுவன வாம்.`,
  },
  {
    id: 2148, tantraId: 8, verseNumber: 2147,
    tamil: `இடவகை சொல்லில் இருபத்தஞ்சு ஆனை
படுபர சேனையும் பாய்பரி ஐந்தும்
உடையவன் மத்திமை உள்ளுறும் நால்வர்
அடைய நெடுங்கடை ஐந்தொடு நான்கே`,
    transliteration: `iṭavakai collil irupattañcu āṉai
paṭupara cēṉaiyum pāypari aintum
uṭaiyavaṉ mattimai uḷḷuṟum nālvar
aṭaiya neṭuṅkaṭai aintoṭu nāṉkē`,
    english: `2147: In Waking State Jiva is With Twenty-Four Tattvas
In Jagra State
The Jiva of Tattvas five and twenty
Its position takes
In Eye-Brow center;
With elephants Five, (sensory organs)
Infantry Five (motor organs)
Cavalry Five (internal sense potencies)
And Elements Five,
Inside Soldiery Four (the Antakaranas)
He with Tattvas twenty and four
Stands at the Gate of Waking (Jagra) state;
Thus, Tattvas stand in centers respective.`,
    elaborationEnglish: `The 2S atma tattvas are categorised as follows: Elements — 5 External Sense 5 Organs — Extemal motor 5 Organs — Internal Sense 5 Potencies (tanmatras) — Intelligence organs 4 (Ahtahkaranas)— Atman — I`,
    elaborationTamil: `மேற்கூறிய மத்தியலாவத்தையின் இயல்பைக் கூறுமிடத்து உயிரினது செயற்பாடு, அனைத்துச் சுற்றங்களும் சூழ அரசன் உலாவருதல் போன்றதாகும். யானை இருபத்தைந்து, (இவை ஆன்மதத்துவங்கள்) குதிரை ஐந்து, (இவை காமம், வெகுளி, உலோபம், யோகம், மதம், என்னும் உணர்ச்சிகள்) அமைச்சர் நால்வர். (இவை நால்வகை வாக்குக்கள்) புறஞ் சூழ்ந்து வரும் சேனைகள் காலாட்படைகள் (இவை வித்தியா தத்துவங்களும், சிவ தத்துவங்களும்) சென்று சென்று நிற்கும் வாயில்கள் ஒன்பது. (இவை நவத் துவாரங்கள்) இங்ஙனமாக அறிக.`,
  },
  {
    id: 2149, tantraId: 8, verseNumber: 2148,
    tamil: `உடம்பும் உடம்பும் உடம்பைத் தழுவி
உடம்பிடை நின்ற உயிரை அறியார்
உடம்பொடு உயிரிடை நட்புஅறி யாதார்
மடம்புகு நாய்போல் மயங்குகின் றாரே`,
    transliteration: `uṭampum uṭampum uṭampait taḻuvi
uṭampiṭai niṉṟa uyirai aṟiyār
uṭampoṭu uyiriṭai naṭpuaṟi yātār
maṭampuku nāypōl mayaṅkukiṉ ṟārē`,
    english: `2148: Know the Relationship Between Body and Jiva
The bodies (Causal, Subtle and Gross) embrace one another,
But the Jiva within body stood,
They know not;
They who the kinship between body and Jiva
Understood not,
Are verily bewildered
Unto the dog that into a kitchen abrupt strays.`,
    elaborationEnglish: `Know the relationship between the body and jiva. Otherwise you will be left in confusion, like a dog that enters a kitchen abruptly.`,
    elaborationTamil: `அதிசூக்கும சரீரம் முதலில் சூக்கும சரீரத்தைப் பற்றிப் பின்பு அவ்விரண்டும் கூடித் தூல சரீரத்தைப் பற்றுதலினால் உயிர் அம்மூன்று சரீரத்தோடும் பொருந்தித் தனது செயலைச் செய்துவரும் நிலையைப் பலர் அறியாது, 'உடம்புதான் உயிர்' எனமயங்குகின்றனர். உடம்போடு உயிருக்குள்ள தொடர்பு, வினை காரணமாகச் சிறிது கால அளவினதே என அறியாதவர்கள் தூய திருமடங்களின் உள்ளே எவ்வாறோ புகுந்துவிட்ட நாய் 'இந்த இடம் நமக்கு நிலையாது' என்பதை உணராமல், நிலைத்த ஒன்றுபோல நினைத்து, அங்கு அமைக்கப்பட்டுள்ள உணவைத் தனக்கே உரியன வாக எண்ணிக் களிப்பதுபோலக் களித்திருக்கின்றார்கள்.`,
  },
  {
    id: 2150, tantraId: 8, verseNumber: 2149,
    tamil: `இருக்கின்ற வாறுஒன்று அறிகிலர் ஏழைகள்
மருக்கும் அசபையை மாற்றி முகந்து
கருக்கொண்டு காமாரி சார முகந்தேர்ந்து
உருக்கொண்டு தொக்க உடல்ஒழி யாதே`,
    transliteration: `irukkiṉṟa vāṟuoṉṟu aṟikilar ēḻaikaḷ
marukkum acapaiyai māṟṟi mukantu
karukkoṇṭu kāmāri cāra mukantērntu
urukkoṇṭu tokka uṭaloḻi yātē`,
    english: `2149: Meet God in the Body By the Yoga Way
They know not how To-Be;
Poor are they in Spirit;
Those, who,
Course upward the vital Ajapa
(Through breathing in Yoga way)
And sublimate the Bindu,
They meet the Lord
That destroyed Kama, the God of Love;
Comely their body becomes
And indestructible here remains.`,
    elaborationTamil: `அறிவில்லாதவர்கள், 'உலகத்தில் நாம் எவ் வாற்றால் உயிர் வாழ்கின்றோம்' என்பதைச் சிறிதும் உணர மாட்டார்கள். (உள்வாங்கியும், வெளிப்போக்கியும் பிராண வாயுவை ஓய்வின்றி இயக்குதலால்தான் அவர்கள் வாழ்கின்றனர். ஆகையால் அதனையறிந்து) பிறவியை அறுக்கின்ற அசபா மந்திரத்தால் பிராண வாயுவை மேற்சொல்லியவாறு இயக்கிப் பயின்று தூயராய்ப் பின் அவ்வாயுவை உள்ளே நிறுத்தி' அம்மந்திரத்தை, 'சிவன் நான்' எனப் பொருள்படும் வகையில் மாற்றி நினைந்து அவ்வாற்றால், காமனை அழித்தோனாகிய சிவன் தம்மிடத்தில் பதிந்து பின் நீங்காது விளங்கும் படி செய்தலாகிய இம்முறையை உணர்ந்து, அதனால் அவன் அருளே தமது உடம்பாகச் செய்து கொள்வார்க்கு, அங்ஙனம் அமைந்த உடம்பு அழிந்தொழியாது; நிலைத்திருக்கும்.`,
  },
  {
    id: 2151, tantraId: 8, verseNumber: 2150,
    tamil: `ஒளித்திட்ட டிருக்கும் ஒருபதி னாலை
அளித்தவன் என்னுள்ளே ஆரியன் வந்து
அளிக்கும் கலைகளி னால்அறு பத்து
ஒளித்திட்டு வைத்தான் ஒடுங்கிய சித்தே`,
    transliteration: `oḷittiṭṭa ṭirukkum orupati ṉālai
aḷittavaṉ eṉṉuḷḷē āriyaṉ vantu
aḷikkum kalaikaḷi ṉālaṟu pattu
oḷittiṭṭu vaittāṉ oṭuṅkiya cittē`,
    english: `2150: Lord Placed in Concealment the Sixteen Kalas
and the Fourteen Inner Tattvas
The Tattvas four and ten
That in me lay concealed,
The Pure One appeared
And in bounty revealed;
The Kalas six and ten
That to me lend grace,
He placed, to none beknown,
My thoughts in Him to center.`,
    elaborationEnglish: `Fourteen inner tattvas: the five elements; the five sense potencies (tanmatras); and the four intelligence organs (antakaranas).`,
    elaborationTamil: `அறிவுப் பொருளேயாயினும் ஆணவ மறைப் பால் அவ்வறிவை இழந்து நின்ற உயிரை இறைவன் கருவிக் கூட்டத்துள் மறைந்து நிற்கும்படி செய்தான். (பின்பு அவ்வுயிர் பக்குவம் எய்திய காலத்தில்) குருவாகி வந்து எனக்கு உபதேசித்த நூல்கள் வழியாக என் உடம்பினுள்ளே மறைந்திருந்த பிராசாத கலைகள் பதினாறையும் விளக்கினான்.`,
  },
  {
    id: 2152, tantraId: 8, verseNumber: 2151,
    tamil: `மண்ணினில் ஒன்று மலர்நீரும் மருங்காகும்
பொன்னினில் அங்கி புகழ்வளி ஆகாயம்
மன்னும் மனோபுத்தி ஆங்காரம் ஓர்ஒன்றாய்
உன்னின் முடிந்தது ஒருபூத சயமே`,
    transliteration: `maṇṇiṉil oṉṟu malarnīrum maruṅkākum
poṉṉiṉil aṅki pukaḻvaḷi ākāyam
maṉṉum maṉōputti āṅkāram ōroṉṟāy
uṉṉiṉ muṭintatu orupūta cayamē`,
    english: `2151: Conquer the Five Elements and the Four Karanas
The Earth and Water expanses;
The Fire that blazes in color gold,
The Wind and Space
The Mind, Will, Intellect and Egoity
On their quintessence,
You in succession contemplate;
Then victorious you stand, the elements vanquishing.`,
    elaborationTamil: `மண்ணிலிருந்து தோன்றிய பல மலர்களை உடைத் தாய் விளங்குகின்ற நீர், பொன்னிறத்தை உடைத்தாகிய தீயினின்றும் அதற்குப்பின் தோன்றியதாம். இனி அத்தீக் காற்றி லிருந்தும், காற்று ஆகாயத்திலிருந்தும் தோன்றினவாம். புத்தியினின்றும் தோன்றிய தாகிய அகங்காரத்திலிருந்து தோன்றியது மனம். இவ்வாறு தூல சூக்கும தேகங்களின் உற்பத்தியைப் பகுத்துப் பகுத்து உணர்ந்தால், அவற்றை ஒடுக்கி, ஆன்மாத் தூய்மை அடைகின்ற நிலை கைகூடும்.`,
  },
  {
    id: 2153, tantraId: 8, verseNumber: 2152,
    tamil: `முன்னிக்கு ஒருமகன் மூர்த்திக்கு இருவர்
வன்னிக்கு மூவர் வதுவைக்கு நால்வர்
கன்னிக்கு பிள்ளைகள் ஐவர் முனாள்இல்லை
கன்னியைக் கன்னியே காதலித் தானே`,
    transliteration: `muṉṉikku orumakaṉ mūrttikku iruvar
vaṉṉikku mūvar vatuvaikku nālvar
kaṉṉikku piḷḷaikaḷ aivar muṉāḷillai
kaṉṉiyaik kaṉṉiyē kātalit tāṉē`,
    english: `2152: Out of the Five Elements are Born the Five Senses
One the child for Space--Sound
Two for Wind--Sound and Touch
Three for Fire--Sound, Touch and Light
Four for Water--Sound, Touch, Light and Taste
Five for Earth--Sound, Touch, Light, Taste and Smell
This was not of yore there, before creation began
Before the Virgin Sakti (Spirit), the Virgin Maya (Matter) loved.`,
    elaborationEnglish: `Out of the five elements — space, wind, fire, water and earth - are born the five senses: sound, touch, sight smell and taste. FOTN OUHFM SVESZoST SOG HI (Gh EST Dsort_or HISIGW_EGHQuGs 2 cmrbador usto_w srAL UTS aNwuTsATS`,
    elaborationTamil: `ஐவர் சத்திகளில் முன்னவளாகிய மனோன் மணிக்கு மகன் ஒருவன்தான். அவளிடத்தினின்றும் தோன்றிய மகேசுரனுக்கு மக்கள் இருவர். நெருப்புப்போலும் உருவத்தையுடைய உருத்திரனுக்கு மக்கள் மூவர். மணமகள் போல அழகு மிக உடைய திருமகளுக்கு மக்கள் நால்வர். கணவனது இயல்பு நோக்கிக் கன்னி யாகச் சொல்லத்தக்க வாணிக்கு மக்கள் ஐவர். இவையெல்லாம் அநாதியில் யில்லை. ஆயினும் அநாதியாகிய சிவன் அவ்வாறாகிய தனது சத்தியை அநாதியே தாய்மை அடையுமாறு கருதினான்.`,
  },
  {
    id: 2154, tantraId: 8, verseNumber: 2153,
    tamil: `கண்டன ஐந்தும் கலந்தனதான் ஐந்தும்சென்று
உண்டன நான்கும் ஒருங்கே உணர்ந்தபின்
பண்டைய தாகிப் பரந்து வியாக்கிரத்து
அண்டமும் தானாய் அமர்ந்துநின்றானே`,
    transliteration: `kaṇṭaṉa aintum kalantaṉatāṉ aintumceṉṟu
uṇṭaṉa nāṉkum oruṅkē uṇarntapiṉ
paṇṭaiya tākip parantu viyākkirattu
aṇṭamum tāṉāy amarntuniṉṟāṉē`,
    english: `2153: Fourteen Tattvas in Dream State
In Dream State
The Senses Five experienced;
The Tanmatras Five too;
And Antakaranas Four as well;
Having experienced thus in Dream State
The Jiva returned to Jagra State to experience;
There he stood in full knowledge of world.`,
    elaborationEnglish: `Jiva experiencing the fourteen tattvas in the dream state, returns to the jagra state where it stands in full knowledge of the world. But in the throat centre, jiva visions dreams only with the four antakaranas without involvement of the - other ten tattvas. :`,
    elaborationTamil: `சுழுத்திக்குப் பின் கண்ட கனவிலே செயற்பட்ட ஓசை முதலிய புலன்கள் ஐந்தும், பின்னர்ச் சென்று கலந்த பொறிகள் ஐந்தோடும் கூடியிருக்கும் நிலையில் அப்பொறிகளின் வழியாகப் புறப்பொருள்களை அந்தக்கரணங்கள் நான்கும் உணர்வுறும் நிலைமையை ஒருங்கே அடைந்தபின் புருடன் முன்னை நிலையை அடைந்து, விரிந்த பரந்த சிறந்த சாக்கிராவத்தையையுடையனாய், உலகமே தானாயது போன்ற வியாபக நிலையைப் பெற்று, வினைகளை நுகர்தலும் ஈட்டலும் செய்திருப்பான்.`,
  },
  {
    id: 2155, tantraId: 8, verseNumber: 2154,
    tamil: `நின்றவன் நிற்கப் பதினாலில் பத்துநீத்து
ஒன்றிய அங்தக் கரணங்கள் நான்குடன்
மன்று கலந்த மனைவாழ்க்கை வாதனை
கன்றிய கண்டத்தில் கண்டான் கனவதே`,
    transliteration: `niṉṟavaṉ niṟkap patiṉālil pattunīttu
oṉṟiya aṅtak karaṇaṅkaḷ nāṉkuṭaṉ
maṉṟu kalanta maṉaivāḻkkai vātaṉai
kaṉṟiya kaṇṭattil kaṇṭāṉ kaṉavatē`,
    english: `2154: But Only the Four Intelligence Organs are Involved in
Dream Vision
Thus it is, Jiva with Tattvas four and ten
In Dream State stands;
But with the ten sense organs uninvolved
With Antahkaranas Four alone,
And aided by the memory
Of earthly life here below,
He (Jiva) in the Throat-Center,
Dreams visioned.`,
    elaborationEnglish: ``,
    elaborationTamil: `ஞானேந்திரியமும், கன்மேந்திரியமும், அந்தக் கரணங்களும் ஆகிய பதினான்கு கருவிகளோடு கூடிச் சாக்கிரா வத்தையில் நின்ற புருடன், அவ்வாறு நிற்கும் நிலையிற்றானே இரு வகை இந்திரியங்களாகிய பத்துக் கருவிகளை நீக்கிவிட்டு, எஞ்சிய நான்காகிய அந்தக்கரணங்களோடு மட்டும் அழுத்தமான கண்டத் தானத்தில் சென்று, முன்பு சாக்கிரத்தில் புருவ நடுவில் நின்று நுகர்ந்த உலக நுகர்ச்சிகளின் வாசனையைக் கனவாகக் காண்பான்.`,
  },
  {
    id: 2156, tantraId: 8, verseNumber: 2155,
    tamil: `தானம் இழந்து தனிபுக்கு இதயத்து
மானம் அழிந்து மதிகெட்டு மாலாகி
ஆன விரிவுஅறி யாஅவ் வியத்தத்தில்
மேனி அழிந்து கழுத்தியது ஆமே`,
    transliteration: `tāṉam iḻantu taṉipukku itayattu
māṉam aḻintu matikeṭṭu mālāki
āṉa virivuaṟi yāav viyattattil
mēṉi aḻintu kaḻuttiyatu āmē`,
    english: `2155: Deep Sleep in Heart-Center
Leaving the Throat Center there,
Alone, he (Jiva) enters the Heart's-Center
There, Egoity (Ahamkara) lost, Intellect (Buddhi) lost,
Cognition (Mind) lost
In the State that discerns not world,
Consciousness of body bereft,
He (Jiva) reached the Deep Sleep State of Sushupti.`,
    elaborationEnglish: `Cognition (Mind) lost In the State that discerns not the world, Consciousness of body bereft, He (Jiva) reached the Deep Sleep State of Sushupti.`,
    elaborationTamil: `மேற்கூறிய கண்டமாகிய தானத்தை (இடத்தை) விட்டுப்புருடன் கீழ் இறங்கி, அங்ஙனம் இறங்கும் நிலையில், முன்பு இருந்த அந்தக்கரணங்களுள் மானமாகிய அகங்காரத்தையும், மதியாகிய புத்தியையும் விடுத்து, யாதொன்றையும், பற்றிநினைக்க மாட்டாத நிலையையடைந்து, இருதயத்தில் தனியேசென்று, புலன் உணர்வையிழந்து இழப்பு நிலையில் உயிரினது சொரூபமே காணப் படாது கிடக்கும் நிலையே சுழுத்தியவத்தையாம்.`,
  },
  {
    id: 2157, tantraId: 8, verseNumber: 2156,
    tamil: `கழுமுனையைச் சேர்ந்துள மூன்றுடன் காட்சி
கெழுமிய சித்தம் பிராணன்தன் காட்சி
ஒழுகக் கமலத்தின் உள்ளே யிருந்து
விழுமப் பொருளுடன் மேவிநின் றானே`,
    transliteration: `kaḻumuṉaiyaic cērntuḷa mūṉṟuṭaṉ kāṭci
keḻumiya cittam pirāṇaṉtaṉ kāṭci
oḻukak kamalattiṉ uḷḷē yiruntu
viḻumap poruḷuṭaṉ mēviniṉ ṟāṉē`,
    english: `2156: Tattvas in Deep Sleep
Having reached Deep Sleep State of Sushupti,
He with three there remains;
--Chitta (Will), Prana (Vital Breath) and Sentience of Self,
Thus into the Herat-Center Jiva enters
There one with the Subtle Object he stands
(In the state of Sushupti Deep.)`,
    elaborationEnglish: ``,
    elaborationTamil: `சுழுத்தியில் உள்ள மூன்று கருவிகளுள் புருடனுக்கு அறிவைத் தருவதாகிய சித்தம் நீங்கிப்போக, உந்திக் கமலத்தின்கண் பிராணவாயு ஒன்று மட்டுமே அவனுக்கு அறிவைத் தருவதாய் அமைய அங்கு இருந்துகொண்டு, ஆன்ம தத்துவங்கள் யாவும் தன்கண்வந்து ஒடுங்கநிற்பதாகிய மூலப்பிரகிருதியைத் தான் சிறிது அறிதலை அவன் செய்துகொண்டிருப்பான்.`,
  },
  {
    id: 2158, tantraId: 8, verseNumber: 2157,
    tamil: `தானத்து எழுந்து தருக்கு துரியத்தின்
வானத்து எழுந்துபோய் வையம் பிறகிட்டுக்
கானத்து எழுந்த கருத்தின் தலையிலே
ஊனத்து அவித்தைவிட்டு ஊமன்நின் றானே`,
    transliteration: `tāṉattu eḻuntu tarukku turiyattiṉ
vāṉattu eḻuntupōy vaiyam piṟakiṭṭuk
kāṉattu eḻunta karuttiṉ talaiyilē
ūṉattu avittaiviṭṭu ūmaṉniṉ ṟāṉē`,
    english: `2157: Nada Peaks in Turiya or Fourth State
From Sushupti Center,
He further moves continuing,
Into Turiya Expanse
Leaving thoughts of world below;
On to peaks of Nada (in navel center) he ascends;
There rid of primordial ignorance,
He remains in Mauna (Silentless).`,
    elaborationEnglish: ``,
    elaborationTamil: `உயர் தனக்குச் சிறப்பிடமாகிய இருதயத்தினின் றும் புறப்பட்டவழி அதற்குத் தரப்படும் துரியத்தானத்தில் நின்று பின்பு அதனையும் விட்டு அப்பாற் சென்று, உலகத்தைப் பின் தள்ளிவிட்டு, நாதத்தால் உணர்வு விளங்குமாறு நிற்கின்ற குண்டலினி சத்தியின் தலைபொருந்தியுள்ள மூலாதாரத்தை அடைந்து, அவ்விடத்தில் பொருள்களை மயங்கியறிதலாகிய அந்த அறிவும் இன்றி அறிவே யில்லாதது போலக் கிடக்கும்.`,
  },
  {
    id: 2159, tantraId: 8, verseNumber: 2158,
    tamil: `ஊமை எழுத்தொடு பேசும் எழுத்துறில்
ஆமை அகத்தினில் அஞ்சம் அடங்கிடும்
ஓமயம் உற்றுஅது உள்ளொளி பெற்றது
நாமயம் அற்றது நாம்அறி யோமே`,
    transliteration: `ūmai eḻuttoṭu pēcum eḻuttuṟil
āmai akattiṉil añcam aṭaṅkiṭum
ōmayam uṟṟuatu uḷḷoḷi peṟṟatu
nāmayam aṟṟatu nāmaṟi yōmē`,
    english: `2158: Turiyatita Experience
When with silent letter "M"
The articulate letters "A" and "U" conjoins,
The Five Senses are withdrawn,
As limbs within the tortoise;
Then Jiva is by "Aum" pervaded;
The light Divine beams from within;
The Self its sentience loses;
--This we know not.`,
    elaborationEnglish: `When the silent letter ‘M’ joins with the two articulate letters “A” and ‘U’, the five senses are withdrawn like limbs within the tortoise. Then jiva pervaded by ‘Aum’ loses the self. gmu Aguugie, s7éG7s gictGer Bia uUBerray BEAroIG) Ces zor = ufw youd unde uMbssi gitu WnsGi@ GendoQanes ons. 2159`,
    elaborationTamil: `[நால்வகை வாக்குக்களில் மிகவும் தூலமாகிய வைகரிவாக்குச் சகல ஐந்தவத்தையிலும் தூலமாகிய மத்திமை வாக்கு கேவல ஐந்தவத்தையிலும், சூக்குமமாகிய பைசந்தி வாக்கு யோகா லவத்தையிலும், மிகவும் சூக்குமமாகிய சூக்குமை வாக்கு சுத்த ஐந்த வத்தையிலும் செயற்படும். அதுபற்றித்தான் வாக்குக்கள் அவத்தைக்கு ஏதுவாம் கருவிகளாக எண்ணப்படவில்லை.]
மேற்கூறிய நால்வகை ஐந்தவத்தைகளில் மேற்கூறியவாறு நால்வகை வாக்குக்கள் செயற்படுங்கால், சாக்கிரம் முதலிய ஐந்திலும் முறையே, தூலதமம், தூலதரம், தூலம், சூக்குமம், அதிசூக்குமம்' என்னும் நிலையில் செயற்படும் அதிசூக்குமமே ''ஊமையெழுத்து'' என்றும் ஏனையவை ''பேசும் எழுத்து'' என்றும் மறைபொருட் கூற்றாகக் கூறப்பட்டன. அதிகாரம் கீழாலவத்தையாதலின் இங்குக் கூறப்பட்ட, 'பேசும் எழுத்து, ஊமையெழுத்து' - என்பன கீழாலவத் தையில் செயற்படுவ தாகிய மத்திமை வாக்கின் 'அதிசூக்குமம், சூக்குமம்' என்பவற்றை யாம். தூலதமம், தூலதரத்திலும், தூலதரம் தூலத்திலும், தூலம் சூக்குமத்திலும் ஒடுங்கிவிடப்பின்பு சூக்குமமும் அதிசூக்குமத்தில் ஒடுங்கிவிட்டால் பெத்தநிலையில் உள்ள உயிர் புறப்பொருள்களில் யாதொன்றையும் அறியமாட்டாது உணர்வை முற்றிலுமாக இழந்து, பிரகிருதிமயமாகியே கிடக்கும். இதுவே கீழாலவத்தையில் துரியா தீதத்தின் நிலைமை. இதனையே,
''ஊமை யெழுத்தொடு பேசும் எழுத்துறின்
ஆமை யகத்தினில் அஞ்சும் அடங்கிடும்''
என்றார். 'ஆமை' என்றது உயிரை. இஃது உருவகம். அஞ்சு - ஐம் புலன்கள்மேல் சென்று அவற்றைக் கவர்கின்ற உணர்வு. அவ்வுணர்வு சிறிதும் வெளிச்செல்லாது உயிரோடு உயிராய் ஒட்டிக் கிடத்தல், ஆமையின் ஐந்து உறுப்புக்கள் அதனது ஓட்டிற்குள்ளே அடங்கி வெளித் தோன்றாதிருத்தலோடு ஒத்திருத்தல் பற்றி, உயிர் ஆமையாக உருவகம் செய்யப்பட்டது. சுழுத்தி துரியங்களிலும் அஞ்சும் அடங்கி யிருப்பினும் சித்தமும், பிராணனும் செயற்படுதலால் 'அவற்றின் வாசனை சிறிதாயினும் இருக்கும்' என எண்ண இடம் உண்டு. உயிர்ப்பு அடங்கி விட்டமையால் அதீதத்தில் அவ்வாறு எண்ணச் சிறிதும் இடம் இல்லாமை பற்றி, இவ்விடத்திற்றானே ''அஞ்சும் அடங்கிடும்'' எனக் கூறினார். 'தமோமாய்' (இருள்மயமாய்) நிற்கும் அதீத நிலையை சிவத்தில் அழுந்தி ஒளிமயமாய் நிற்கும் நிலையாகக் கூறுபவர் யாதும் அறியாதவர்' என்பதை உணர்த்துதற்குப் பின்னிரண்டடிகளைக் கூறினார். அவற்றுள் 'ஓம்' என்றது அதன் உண்மைப் பொருளாய் நிற்கும் சிவத்தை.
'சுத்த துரியாதீதத்தில் சிவத்தை அடைந்த சிவமயமான உயிர், இருள் முழுவதும் நீங்கி ஒளிமயமானதாகும். அதனால் அது 'நாம்' என்னும் சீவபோதமும் இல்லாததாகும். அந்த நிலையை நாம் அறிந்திலோம் என்பது பின்னிரண்டடிகளின் பொருள்.`,
  },
  {
    id: 2160, tantraId: 8, verseNumber: 2159,
    tamil: `துரியம் இருப்பதும் சாக்கிரத்து உள்ளே
நரிகள் பதினாலு நஞ்சுண்டு செத்தன
பரிய புரவியும் பாறிப் பறந்தது
துரியம் இறந்திடம் சொல்லஒண் ணாதே`,
    transliteration: `turiyam iruppatum cākkirattu uḷḷē
narikaḷ patiṉālu nañcuṇṭu cettaṉa
pariya puraviyum pāṟip paṟantatu
turiyam iṟantiṭam collaoṇ ṇātē`,
    english: `2159: State Beyond Turiya--(Turiyatita)
Turiya is in Jagrat experienced;
The foxes fourteen (Indriyas etc.) of themselves die;
The swiftly steed of Prana flees,
How that State beyond Turiya (Turiyatita) is,
Impossible to state, indeed.`,
    elaborationEnglish: `The state beyond turiya is turiyatita. Experiencing turiya in jagrat, the fourteen foxes {indriyas, etc.) perish; prana stands still. It is impossible to describe adequately the state of turiyatita. :`,
    elaborationTamil: `சுழுத்தியைக் கடந்து உள்ள 'துரியம், துரியாதீதம்' - என்னும் இரண்டனுள் துரியம், 'எவ்வாறு இருந்தது' என வினாவு பவர்க்கு, 'இவ்வாறு இருந்தது' என விடையிறுக்கக் கூடியதாகும். துரியா தீதமோ எனில், அவ்வாறு வினாவுவார்க்கு இவ்வாறு இருந்தது' எனச் சொல்லவாராத நிலையாகும். ஏனெனில், சாக்கிராவத்தையில் அடக்கினும் அடங்காது, யாதானும் ஓர் ஆற்றால்தப்பிப் புறத்தே ஓடுதலால், 'நரிகள்' என்று சொல்லத்தக்கனவாகிய ஞானேந்திரியம், கன்மேந் திரியம், அந்தக்கரணம் என்னும் பதினான்கு பொறிகளும் (கரணங்களும்) பிரகிருதியின் தமோ குணமாகிய விடத்தை உண்டமையால் இறந்து போய்விட்டன. அப்பொறிகளின் வழிச் செல்லும் உணர்விற்கு ஊர்தியாகிய 'பிராணன்' என்னும் குதிரையும் தனது ஓட்டம் அடங்கி ஒழிந்தது.`,
  },
  {
    id: 2161, tantraId: 8, verseNumber: 2160,
    tamil: `மாறா மலம்ஐந்தால் மன்னும் அவத்தையில்
வேறாய மாயா தநுகர ணாதிக்குஇங்கு
ஈறாகா தேஎவ்வுயிரும் பிறந்துஇறந்து
ஆறாத வல்வினை யால்அடி யுண்ணுமே`,
    transliteration: `māṟā malamaintāl maṉṉum avattaiyil
vēṟāya māyā tanukara ṇātikkuiṅku
īṟākā tēevvuyirum piṟantuiṟantu
āṟāta valviṉai yālaṭi yuṇṇumē`,
    english: `2160: All Jivas Experience These States of Awareness
Contaminated by Primordial Mala (Impurities) Five,
Jivas, all, the Five States of Awareness experience;
Endless indeed are the bodies and organs
That Maya endows;
All Souls, caught in birth and death,
Are by Karma alike struck.`,
    elaborationEnglish: ``,
    elaborationTamil: `முத்தி பெறுங்காறும் விட்டு நீங்காதிருக்கின்ற ஐந்து மலங்களால் நிலைபெறுவதாகிய சகலாவத்தையில் தனியொரு சிறப்பினையுடைய மாயேயமாகிய தனு, கரணம் முதலியவற்றிற்கு இந்தச் சகல நிலையில் முடிவேயில்லாமையால், எல்லாவகையான உயிர்களும் ஒரு பிறப்பின் பிறந்து, பின் அதனை விட்டு நீங்கி, வேறொரு பிறப்பை அடைந்து அலமரும். அதற்குக் காரணம் தனது ஆற்றல் குன்றப்பெறாத வினையே.`,
  },
  {
    id: 2162, tantraId: 8, verseNumber: 2161,
    tamil: `உண்ணும்தன் ஊடாடது ஊட்டிடு மாயையும்
அண்ணல் அருள்பெற்ற முத்தியது ஆவது
நண்ணல் இலாஉயிர் ஞானத்தி னால்பிறந்து
எண்னுறு ஞானத்தின் நேர்முத்தி எய்துமே`,
    transliteration: `uṇṇumtaṉ ūṭāṭatu ūṭṭiṭu māyaiyum
aṇṇal aruḷpeṟṟa muttiyatu āvatu
naṇṇal ilāuyir ñāṉatti ṉālpiṟantu
eṇṉuṟu ñāṉattiṉ nērmutti eytumē`,
    english: `2161: Maya Gives States of Experience For God's Grace to
Attain;
Jnanis Reach Mukti Direct
Maya feeds Jiva with Avasta experiences unbroken,
For the Jiva by Lord's Grace
To attain Mukti;
But the Jivas in Jnana born
Them Maya nears not;
And contemplating in Jnana
They direct attain Mukti.`,
    elaborationEnglish: `Maya feeds jiva with avasta experiences and by Gods’ Grace, jiva attains mukti. Jnanis contemplating in jnana attain mukti directly.`,
    elaborationTamil: `இன்ப துன்பங்களை வினைக்கு ஏற்றவாறு விளைவித்து நிற்கின்ற மாயேயமாகிய உலகம், அந்த இன்பத் துன்பங்கள் தன்கண் வாதியாதபடி புளியம் பழத்தின் ஓடுபோல ஒட்டற்றுக் கழிய, இறைவனது திருவருளில் தோய்ந்து நிற்றலே முத்தியாகும். (என்றது, சீவன் முத்தி நிலையை, அதுவே சகலத்தில் சுத்தம் - என்க. இந்நிலைமுற்றாகக் கைகூடுதற்கு முன் பிராரத்த மாயினும் நீங்கிவிடுமாயின் அந்த உயிர் மற்றொரு பிறப்பை அடையும்) அத்தகைய உயிர் மற்றொரு பிறப்பை அடையுமாயினும் முன்னை ஞானத்தோடே பிறந்து, அது வழியாக அப்பிறப்பில் அது சீவன் முத்திநிலை முற்றாகக் கைகூடப் பெற்றுப்பின் முடிநிலையாகிய பரமுத்தியை அடையும்.`,
  },
  {
    id: 2163, tantraId: 8, verseNumber: 2162,
    tamil: `அதிமூட நித்திரை ஆணவம் நந்த
அதனால் உணர்வோன் அருங்கன்மம் முன்னி
நிதமான கேவலம் இத்திறம் சென்று
பரமாகா ஐஅவத் தைப்படு வானே`,
    transliteration: `atimūṭa nittirai āṇavam nanta
ataṉāl uṇarvōṉ aruṅkaṉmam muṉṉi
nitamāṉa kēvalam ittiṟam ceṉṟu
paramākā aiavat taippaṭu vāṉē`,
    english: `2162: Consciousness Begins With Egoity
In the Primordial Slumber State of Jivas (Kevala State)
Devoid of Awareness,
Egoity is activated;
Then Consciousness springs,
And actions diverse Jiva pursues;
From the State of Kevala
Thus passing out,
He the Five States (Avastas) experiences,
Until he becomes Para Supreme.`,
    elaborationEnglish: ``,
    elaborationTamil: `அறிவு சிறிதேனும் தொழிற்படாத, 'ஒரு பேருறக்கம்' எனச்சொல்லத்தக்கது, ஆன்மா ஆணவத்தோடு மட்டும் இருக்கின்ற நிலை (அஃது 'அநாதி கேவலம்' எனப்படும்). பின்பு அந்த ஆணவ மலத்தின் சத்தி மாயையினால் சிறிதே கெட, அந்த மாயை விளக்கும் அளவிற்கு அறிவு விளங்கப் பெற்ற உயிர், நீக்குதற்கரிய வினைக்கு ஈடான உணர்வையே உடையதாம் நிலையில் இன்பம் போல நிகழ்கின்ற அறியாமையில் செல்வதே சகலத்தில் கேவலம். இந்தக் கேவலத்தில்தான் ஆன்மாக் கீழாலவத்தை ஐந்தினையும் அடையும்.`,
  },
  {
    id: 2164, tantraId: 8, verseNumber: 2163,
    tamil: `ஆசான்முன் னேதுயில் மாண வகரைத்
தேசாய தண்டால் எழுப்பும் செயல்போல்
நேசாய ஈசனும் நீடுஆண வத்தரை
ஏசாத மாயாள்தன் னாலே எழுப்புமே`,
    transliteration: `ācāṉmuṉ ṉētuyil māṇa vakarait
tēcāya taṇṭāl eḻuppum ceyalpōl
nēcāya īcaṉum nīṭuāṇa vattarai
ēcāta māyāḷtaṉ ṉālē eḻuppumē`,
    english: `2163: Maya Awakens Soul From Primordial (Kevala) Slumber
As with his staff the teacher rouses the pupil
Who in his presence slumbers,
Even unto it,
The benevolent Lord with Maya awakens
The Soul that in prolonged Egoity slumbers.`,
    elaborationTamil: `அநாதியே பற்றி, இறுதியற்றிருக்கும் ஆணவ மலத்தால் அறிவிழந்து கிடக்கும் உயிர்களைக் கருணையே உருவாய் உள்ள இறைவன் எவ்வாறு அறிவை மறைத்தல் இன்றி, அதனை விளங்கச் செய்வதாகிய மாயையாகிய பணிப்பெண்ணை விட்டு ஆணவ உறக்கத்தினின்று தட்டி எழுப்பும்படி செய்வான். இது நல்லாசிரியன் ஒருவன் முன்னைநிலையில் சோம்பலால் உறங்கி விடுகின்ற சில மாணவர்களை அவ்வாசிரியன் மாணவர்களது அறிவை வளர்க்கத் தனது கையில் கொண்டுள்ள பிரம்பால் தட்டியெழுப்புதல் போல்வது.`,
  },
  {
    id: 2165, tantraId: 8, verseNumber: 2164,
    tamil: `மஞ்சொடு மந்தா கினிகுட மாம்என
விஞ்சுஅறி வில்லோன் விளம்பும் மிகுமதி
எஞ்சலில் ஒன்றெனு மாறுஎன இவ்வுடல்
அஞ்சணும் மன்னன்அன் றேபோம் அளவே`,
    transliteration: `mañcoṭu mantā kiṉikuṭa māmeṉa
viñcuaṟi villōṉ viḷampum mikumati
eñcalil oṉṟeṉu māṟueṉa ivvuṭal
añcaṇum maṉṉaṉaṉ ṟēpōm aḷavē`,
    english: `2164: Life After Death Is
They who say: "After death nothing left;
The Jiva the five states experienced
Forever fled;"
They are verily unenlightened surpassing;
They might as well say:
"The heavenly Ganga Mandakini
That from clouds aloft streams forth
Ends as an empty pot."`,
    elaborationEnglish: ``,
    elaborationTamil: `'காலம், இடம், கருவி, கரணம் ஆகிய இவற்றுள் எந்த ஒன்றினாலும் உட்படுத்தப்பட்டு, ஏகதேசப்படுதலை ஒரு ஞான்றும் எய்தாத பேரறிவாகிய அந்தப் பரப்பிரமந்தான் இந்த உயிர்' என ஏகான்மவாதி கூறும் அக்கூற்று, 'ஒரு குடத்துள் அடங்கியுள்ள நீரைச்சுட்டி, - மேகம் - என்பதும் இதுதான்; - தான் கங்கா நதி - என்பதும் இதுதான் எனக் கூறுகின்ற மிக்க அறிவில்லாதவன் மிக்க அறிவுடையான் போன்று கூறுகின்ற கூற்றோடு ஒப்பதாய்ப் போக, இந்த உடம்பிற்குத் தலைவனாகிய உயிர் இதைவிட்டு நீங்கும் நாள் வருகின்ற வரையில் சாக்கிரம் முதலிய அஞ்சவத்தைகளை இந்த உடம்பின்கண் எய்தி, ஏகதேசப்பட்டுத் துன்பன் உறும்.`,
  },
  {
    id: 2166, tantraId: 8, verseNumber: 2165,
    tamil: `படியுடை மன்னவன் பாய்பரி ஏறி
வடிவுடை மாநகர் தான்வரும் போது
அடியுடை ஐவரும் அங்குஉறை வோரும்
துடியில்லம் பற்றித் துயின்றனர் தாமே`,
    transliteration: `paṭiyuṭai maṉṉavaṉ pāypari ēṟi
vaṭivuṭai mānakar tāṉvarum pōtu
aṭiyuṭai aivarum aṅkuuṟai vōrum
tuṭiyillam paṟṟit tuyiṉṟaṉar tāmē`,
    english: `2165: In Turiyatita State Tattvas Remain Behind In Body
When the Earthly King, that is Jiva,
Mounting the steeds swift (of consciousness),
At the Lovely City (of Turiyatita) arrives,
The Senses Five
And Tattvas rest that remained behind,
But slept in the body,
That vibrant once was.`,
    elaborationEnglish: `When the soul, the earthly king, mounting the swift steed (consciousness) arrives at the ‘lovely city’ of turiyatita, all the five senses and the other tattvas remain behind in the body. During that fifth state, the jiva is freed from the five malas to reach God directly. Gor wasens fob sausengulesr Gores cungiciesfl 6G) poalesflev Gpor weewwsg GsGr siFlsgy Goon .upggi_er Aougs HsSsGw- 2166`,
    elaborationTamil: `இம்மந்திரம் ஒட்டணியாய் நின்று பொருளைத் தருகின்றது. படி - நாடு; என்றது புற உலகத்தை. அதனை இறைவன் ஆணையால் தனதாகக் கொண்டு இன்பத்துன்பங்களை எய்திவரும் உயிரையே, 'உடை மன்னவன்' என்றார். வடிவு - பல உள்ளமைப் புக்கள். மாநகர் - கோநகர்; என்றது உடம்பை. வருதல் - உலாவருதல். என்றது, எல்லா இடங்களிலும் வியாபித்து, எல்லாப் புலன்களையும் உணர்ந்தும் அவற்றிற்கு ஏற்ற எல்லாச் செயல்களையும் செய்தும் வரும் சாக்கிராவத்தையை. அடியுடை ஐவர் - அணுக்கமாய் நிற்கும் அமைச்சர்கள். என்றது, ஞானேந்திரியங்கள் ஐந்தையும், அவற்றால் உணரப்படும் பொருள்கள் அந்தக்கரணங்களாலே தெளிவுபடும் ஆதலின், அந்த அந்தக்கரணங்களும் 'ஐவர்' என்றதிலே அடங்கின. அங்கு உறைவோர் - அமைச்சர்களுக்குக் கீழாய் அரசனது உலாவில் பலவகைப் பணிகளையும் செய்துநிற்கும் பல பணியாளர்கள் என்றது பிறகருவிகளை. இம்முறையை, 'கால்கொடுத்து இருகை மூட்டி' என்னும் ஞானாமிர்த அகவலிலும் காண்க. (அகவல் - 9) இச்சாக்கிர நிலை, ''படைகொடு பவனிபோதும் பார் மன்னன்'' எனச் சித்தியாரிலும் கூறப்பட்டது. (சுபக். சூ. 4)`,
  },
  {
    id: 2167, tantraId: 8, verseNumber: 2166,
    tamil: `நேரா மலத்தை நீடுஐந்து அவத்தையின்
நேரான வாறுஉன்னி நீடு நனவினில்
நேரா மலம்ஐந்தும் நேரே தரிசித்து
நேராம் பரத்துடன் நிற்பது நித்தமே`,
    transliteration: `nērā malattai nīṭuaintu avattaiyiṉ
nērāṉa vāṟuuṉṉi nīṭu naṉaviṉil
nērā malamaintum nērē taricittu
nērām parattuṭaṉ niṟpatu nittamē`,
    english: `2166: Be Freed of Malas to Reach God
In the States Five,
In purity, vision Malas Five
That pure are not;
See, in the Waking State
They trouble you not;
Straight confront them;
Then shall you with Para direct,
Forever and ever be.`,
    elaborationTamil: `சகலத்திற் கேவலமாகவும், சகலத்திற் சகலமாகவும் இயல்பாக நிகழ்ந்து வருகின்ற அஞ்சவத்தைகளிலே பாகம் (பக்குவம்) எய்தாத ஆணவமலத்தைச் சகலத்தில் சுத்தமாய் நிகழும் சாக்கிரா வத்தையில் பாகம் எய்தியதாக அறிந்து, அதனானே பஞ்ச மலங்களும் பாகமெய்தியவற்றையும் நன்கு கண்டு, எஞ்ஞான்றும் தனது செம்மை யினின்றும் திரிதல் இல்லாத மேலான பொருளோடுகூடி நிற்பதே உண்மைச் சுத்தாவத்தையாகும்.`,
  },
  {
    id: 2168, tantraId: 8, verseNumber: 2167,
    tamil: `சாக்கிர சாக்கிரம் தன்னில் திரோதாயி
சாக்கிர சொப்பனம் தன்னிடை மாமாயை
சாக்கிரம் தன்னில் அழுத்திதற் காமியம்
சாக்கிரம் தன்னில் துரியத்து மாயையே`,
    transliteration: `cākkira cākkiram taṉṉil tirōtāyi
cākkira coppaṉam taṉṉiṭai māmāyai
cākkiram taṉṉil aḻuttitaṟ kāmiyam
cākkiram taṉṉil turiyattu māyaiyē`,
    english: `2167: Maya's Manifestations in the Four States of
Is Tirodayi (obfuscation Sakti) active;
In the Dream State--
Within the Waking State
Is Mamaya (Impure);
In the State of Deep Sleep--
Within the Waking State
Is Kamya (of self delusion);
In the Fourth Turiya State
Within the Waking State
Is Maya (Pure). 1`,
    elaborationEnglish: `This Peioncs to the sakala or the living state. of the jiva on earth. In the-four states of consciousness that jiva experiences — jagrat, svapna, sushupti, and turiya — maya manifests herself as tirodhayi (obscuring sakti) mamaya (impure maya sakti that gives differentiated knowledge), kamya (sakti that gives self-delusion), and finally pure maya (sakti that lends grace) in this avasta. Lorew supa Doran auss gihusgs somrport ap gicroxfl`,
    elaborationTamil: `மத்தியாலவத்தையாகிய சாக்கிர சாக்கிரத்தில் மட்டுமே திரோதானமலம் செயற்படும். (எனவே இந்நிலையில்தான் அனைத்துக் கருவிகளும் செயற்பட, ஆன்மா உலகினை நன்கு உணர்வதாகும்). சாக்கிர சொப்பனத் தளவிலேதான் - அஃதாவது, சாக்கிர சாக்கிரம், சொப்பனம் என்னும் இரண்டில் மட்டுமே ஆன்ம தத்துவம் செயற்படும். (அவற்றுள் சாக்கிரத்தில் மட்டுமே புறக் கருவிகள் செயற்படச் சொப்பனத்தில் அந்தக்கரண நிகழ்ச்சியாகிய சிந்தனை மட்டுமே உளதாகும்) சாக்கிர சுழுத்தியளவில்தான் - அஃதாவது சாக்கிர சாக்கிரம், சாக்கிர சொப்பனம், சாக்கிர சுழுத்தி என்னும் மூன்றளவிலேதான் கன்மங்கள் நிகழும். (எனவே, அந்த மூன்றளவிலேதான் ஆன்மாவிற்குச் சுக துக்கங்கள் விளங்கித் தோன்றும்). சாக்கிர துரியத்தளவில்தான் வித்தியா தத்துவங்கள் செயற்படும். (எனவே, அந்த நான்களவில்தான் ஆன்மாவிற்கு 'யான்' என்னும் தன்னுணர்வு உளதாகும்).`,
  },
  {
    id: 2169, tantraId: 8, verseNumber: 2168,
    tamil: `மாயை எழுப்பும் கலாதியை மற்றதின்
நேய இராகாதி ஏய்ந்த துரியத்துத்
தோயும் கழுமுனை கனாநனா வும்துன்னி
ஆயினன் அந்தச் சகலத்துஉ ளானே`,
    transliteration: `māyai eḻuppum kalātiyai maṟṟatiṉ
nēya irākāti ēynta turiyattut
tōyum kaḻumuṉai kaṉānaṉā vumtuṉṉi
āyiṉaṉ antac cakalattuu ḷāṉē`,
    english: `2168: In Turiya, Kalas and Raga Arise
In that Turiya State
Within the Waking State (of Jiva)
Maya rouses the Kalas and Ragas,
Then passing back through the States
Of Sushupti, Dream and Waking
The Jiva to Sakala State returns.`,
    elaborationTamil: `சிவதத்துவம் அனைத்தும் செயற் படாமையால், வித்தியா தத்துவங்களும் செயற்படாது ஒடுங்கிய அதீத நிலையில் சிவதத்துவங்கள் தொழிற்படத் தொடங்கிய பொழுது வித்தியா தத்துவங்களில் மாயா தத்துவம் எழுந்து, கலை, காலம், நியதி என்னும் மூன்று தத்துவங்களை எழுப்பும். பின்பு கலையினால் வித்தையும், வித்தையால் அராகமும் எழுந்து தொழிற்படும். இவ்வாற்றால் மத்தியா லவத்தைகளில் துரியாதீதம் முதலிய ஐந்தும் நிகழும், அவை ஐந்தும் 'மகாசகலம்' எனப் பொதுப் பெயரைப்பெறும்.`,
  },
  {
    id: 2170, tantraId: 8, verseNumber: 2169,
    tamil: `மேவிய அந்த கண் விழிகண் குருடனாம்
ஆவயின் முன்அடிக் காணு மதுகண்டு
மேவும் தடிகொண்டு சொல்லும் விழிபெற
மூவயின் ஆன்மா முயலும் கருமமே`,
    transliteration: `mēviya anta kaṇ viḻikaṇ kuruṭaṉām
āvayiṉ muṉaṭik kāṇu matukaṇṭu
mēvum taṭikoṇṭu collum viḻipeṟa
mūvayiṉ āṉmā muyalum karumamē`,
    english: `2169: Jivas Grope Their Way Back to Sakala Jagra State
The blind one,
Eyes he has; but vision none;
And so gropes for the steps,
He made of yore;
Having found them,
He seizes a stick
And with its aid
Finds the Way;
Even unto it
Do the Jivas with avastas three
Seek to march back their way.`,
    elaborationTamil: `பிறவிக் குருடன் கண்ணை விழித்து விழித்துப் பார்ப்பினும் யாதொன்றையும் காணமாட்டுவானல்லன். (இது போன்றது சாக்கிர துரியாதீதநிலை அஃதாவது, உணர்வு சிறிதும் இன்றிக் கிடக்கும் நிலையாம்).
ஒன்றும் காணப்படாத நிலையில் அக்குருடன் தன் காலில் கீழ்க் கிடப்பதைத் தடவித் தடவிப்பார்ப்பான். (இதுபோன்றது சாக்கிர துரிய நிலை. அஃதாவது, உணரத் தக்கனவற்றைச் சிறப்பாக அன்றிப் பொதுவாக உணரும் நிலையாம்).
தடவிப் பார்த்த குருடனுக்குக் கோல் ஒன்று கிடைத்ததாயின் அதனைத் துணையாகப் பற்றிச் சில இடங்களுக்குச் செல்வான். (இது போன்றது சாக்கிரச் சுழுத்தி நிலை; உணரப்படும் பொருள்களைச் சிந்தனையால் உணரும் நிலையாம்).
இதன் பிறகு அக்குருடன்தனக்குக் கண் தெரிவதற்கு வேண்டியவற்றைச் செய்வாரை அணுகி அவர்கட்கு உபசார வார்த் தைகளைச் சொல்வான். (இதுபோன்றது சாக்கிரச் சொப்பனநிலை. உணரவேண்டுவனவற்றை உணர்தற்கு முனையும் நிலையாகும்).
(இறுதியில் குருடன் கண்பெறுதலும் உண்டு. அதுபோன்றதே சாக்கிர சாக்கிரம்) சாக்கிரம், சொப்பனம், சுழுத்தி என்னும் மூன்று நிலைகளில்தான் ஆன்மா செயற்பாடுடையதாம். ஏனை இரண்டும் செயலற்ற நிலைகளாம்).`,
  },
  {
    id: 2171, tantraId: 8, verseNumber: 2170,
    tamil: `மத்திமம் ஒத்த சிலந்தி வலயத்துள்
ஒத்துஅங் கிருந்து உயிருண்ணு மாறுபோல்
அத்தனும் ஐம்பொறி ஆடகத்துள் நின்று
சத்த முதல்ஐந்தும் தான்உண்ணு மாறே`,
    transliteration: `mattimam otta cilanti valayattuḷ
ottuaṅ kiruntu uyiruṇṇu māṟupōl
attaṉum aimpoṟi āṭakattuḷ niṉṟu
catta mutalaintum tāṉuṇṇu māṟē`,
    english: `2170: Seated in the Body, Jiva Experiences
The Spider
Standing at the web's center,
Catches prey and feeds;
Even unto it,
The Jiva standing within the body stage,
Where the senses in merriment dance
Experiences the sensations five,
Sound and the rest four.`,
    elaborationEnglish: `Like the spider situated at the centre of its web catches its prey, the jiva also experiences all the actions of the five senses through being situated in the body web. DUES UE UME USSEHH (PFs (pLorencar an@lerngG aictayares Wéeer Quhwer BMmcn9e) cretOmecsrm Beh ware prelips sitGn. 2171`,
    elaborationTamil: `ஐம்பொறிகளைக் கருவியாக உடைய அந்த உடம் பாகிய ஆடரங்கத்துள் நின்று சத்தம் முதலிய புலன்களை உயிர் நுகரும் முறை, சிலந்தியானது வலைக்குள் ஏற்புடைய இடத்தில் இருந்து கொண்டு, அங்குவந்த உயிர்களை உண்ணும் முறைபோல்வது. ஆதலின், அதற்கு ஏற்புடையன மத்தியாலவத்தைகளே.`,
  },
  {
    id: 2172, tantraId: 8, verseNumber: 2171,
    tamil: `வைச்சன வச்சு வகையிரு பத்தஞ்சும்
உச்சம் உடன்அணை வான்ஒரு வன்உளன்
பிச்சன் பெரியன் பிறப்பிலி என்றென்று
நச்சி அவனருள் நான்உய்ந்த வாறே`,
    transliteration: `vaiccaṉa vaccu vakaiyiru pattañcum
uccam uṭaṉaṇai vāṉoru vaṉuḷaṉ
piccaṉ periyaṉ piṟappili eṉṟeṉṟu
nacci avaṉaruḷ nāṉuynta vāṟē`,
    english: `2171: God Placed the Twenty-Five Tattvas for Jiva
One there is,
Who placed Tattvas five and twenty,
With them in my body I abide;
"Mad is He, Great is He, Birthless is He"
--Thus in endearment I sought Him;
And by the Grace He granted,
Redeemed am I.`,
    elaborationTamil: `உயிர்களுக்கு உதவியாக அவைகளின் வசமாக வைக்கப்பட்ட கருவிகள் இருபத்தஞ்சு. எனினும், (அவைகளை வைத்துமட்டும் போதாமையால்) எல்லாவற்றையும் நடத்தும் தலைமைப்பாட்டோடு உடனாய், நீங்காது ஒருவன் இருக்கின்றான். அவனை எல்லா நூல்களும் ஒருமுகமாக, 'பித்தன்' என்றும் 'பெரியோன்' என்றும் 'பிறப்பிலி' என்றும் கூறுதலையறிந்து. அவனையே விரும்பி நான் உய்ந்தவாறு குறிக்கொளத்தக்கதாகும்.`,
  },
  {
    id: 2173, tantraId: 8, verseNumber: 2172,
    tamil: `நாலா றுடன்புருடன் நல்தத் துவமுடன்
வேறான ஐ ஐந்து மெய்ப்புரு டன்பரன்
கூறா வியோமம் பரம்எனக் கொண்டனன்
வேறான நாலேழு வேதாந்த தத்துவமே`,
    transliteration: `nālā ṟuṭaṉpuruṭaṉ naltat tuvamuṭaṉ
vēṟāṉa ai aintu meyppuru ṭaṉparaṉ
kūṟā viyōmam parameṉak koṇṭaṉaṉ
vēṟāṉa nālēḻu vētānta tattuvamē`,
    english: `2172: Vedanta School Reckons Tattvas Differently As Twenty-
Eight
With Tattvas four and twenty,
And Purusha Tattva to add,
Thus are Tattvas five and twenty;
Differently reckoned as five and twenty,
And with Purusha
And the Void (Vyoma) which is not Para,
And Para
Are Tattvas as eight and twenty reckoned,
In the school of Vedanta.`,
    elaborationEnglish: `The Vedanta school count the tattvas differently as twenty-eight. That reckoning includes purusa and the Void, which is not Para.`,
    elaborationTamil: `'சாங்கியர் கூறும் நிலம் முதல் மூலப் பகுதி ஈறான இருபத்து நான்கு தத்துவங்களுடன் அவர் இருபத்தைந்தாவதாகக் கூறு கின்ற புருடனையும் ஒரு தத்துவமாகக் கூட்ட, சாங்கியர் கொள்கை யினின்றும் வேறான இருபத்தைந்து தத்துவங்கள் உளவாகின்றன. அவற்றிற்கு மேல் உண்மையில் 'புருடன்' எனச்சொல்லத்தக்க ஈசுரனும் அவனுக்கும் மேலான, சொல்லுக்கு எட்டாத பராகாயமும், அதற்கு மேல் பரப்பிரமமும் ஆகத்தத்துவம் இருபத்தெட்டு' எனத் 'தத்துவ எண்ணிக் -கையை இவ்வாறு கொள்வதே சிறப்பு' என வேதாந்திகள் கூறுகின்றனர்.`,
  },
  {
    id: 2174, tantraId: 8, verseNumber: 2173,
    tamil: `ஏலங்கொண்டு ஆங்கே இடையொடு பிங்கலை
கோலங்கொண்டு ஆங்கே குணத்துடன் புக்கு
மூலங்கொண்டு ஆங்கே முறுக்கிமுக் கோணிலும்
காலங்கொண் டான்அடி காணலும் ஆமே`,
    transliteration: `ēlaṅkoṇṭu āṅkē iṭaiyoṭu piṅkalai
kōlaṅkoṇṭu āṅkē kuṇattuṭaṉ pukku
mūlaṅkoṇṭu āṅkē muṟukkimuk kōṇilum
kālaṅkoṇ ṭāṉaṭi kāṇalum āmē`,
    english: `2173: Practise Yoga
Course the breath in ways appropriate
Through Nadis, Idakala and Pingala,
Seat yourself in Asanas (postures) comely,
And agreeably direct the breath within;
Through Muladhara, that is triangle shaped
Upward ascend;
Verily may you see the Feet
Of Lord, that is Timeless Eternity.`,
    elaborationTamil: `உயிர் (ஏலாத நிலைகளின் நீங்கி) ஏற்புடையதாகிய அழகிய நிலையைத் தலைப்பட்டபொழுது, இடைகலை, பிங்கலை நாடிகள் வழியாக இயங்குகின்ற காற்றோடு பொருந்தி அவற்றின் வடிவாகி, அப்பொழுதே இராசத சத்துவ தாமத குணங்களிலும் பொருந்திக் (கீழ்நோக்கிச் சென்று) மூலாதாரத்தை யடைந்து, அங்கே உள்ள குண்டலி சத்தியின் கீழ் நோக்கு நிலையை மாற்றி மேல்நோக்கி எழச் செய்து, பின்பு பிருதிவிமண்டலம், அப்புமண்டலம், தேயு மண் டலம் ஆகிய மூன்று மண்டலங்களிலும் மேற்கூறிய முக்குண வடிவாய் உள்ளமும் மூர்த்திகளிடமாக இறைவனைத் தரிசித்தல் கூடும்.`,
  },
  {
    id: 2175, tantraId: 8, verseNumber: 2174,
    tamil: `நாடிகள் பத்தும் நலந்திகழ் வாயுவும்
ஓடிய காலில் ஒடுங்கி யிருந்திடும்
கூடிய காமம் குளிக்கும் இரதமும்
நாடிய நல்ல மனமும் உடலிலே`,
    transliteration: `nāṭikaḷ pattum nalantikaḻ vāyuvum
ōṭiya kālil oṭuṅki yiruntiṭum
kūṭiya kāmam kuḷikkum iratamum
nāṭiya nalla maṉamum uṭalilē`,
    english: `2174: Yoga Brings Rapture
The ten Nadis (pulsating nerves invisible)
And the ten Vayus (winds)
Will in ascending breath subside;
Rapturous your state shall be;
Agreeable your taste shall be;
Perfect your mind shall be;
In the your goodly body.`,
    elaborationEnglish: `Yoga brings a rapturous state, agreeable taste and perfect mind. The body becomes good and holy. The ‘Kingly Nandi of tender love aids us.to see all. He guides and witnesses all.`,
    elaborationTamil: `நாடிகள் பத்தும், நன்மை விளங்குகின்ற வாயுக்கள் பத்தும் நாடிகளில் சிறப்புடைய, 'இடை, பிங்கலை, என்னும் இரு நாடிகள் வழியாக இயங்குகின்ற 'பிராணன்' என்னும் வாயுவிற்குக் கீழ்ப்பட்டு, அவற்றின்வழி நிற்கும். ஆணும், பெண்ணும் கூடியதனால் விளைகின்ற இன்பத்தில் உயிர் மூழ்குதற்குக் காரணமான சுக்கில சோணிதங்களும், அவ்வின்பத்தை விரும்புவதாய் அன்பைச் செய்கின்ற மனமும் உடல் முழுவதுமாய் இருக்கும்.`,
  },
  {
    id: 2176, tantraId: 8, verseNumber: 2175,
    tamil: `ஆவன ஆக அழிவ அழிவன
போவன போவ புகுவ புகுவன
காவலன் பேர்நந்தி காட்டித்துக் கண்டவன்
ஏவன செய்யும் இலங்கிழை யோனே`,
    transliteration: `āvaṉa āka aḻiva aḻivaṉa
pōvaṉa pōva pukuva pukuvaṉa
kāvalaṉ pērnanti kāṭṭittuk kaṇṭavaṉ
ēvaṉa ceyyum ilaṅkiḻai yōṉē`,
    english: `2175: Nandi Guides and Witnesses All
Let them be that are to be;
Let them die that are to die;
Let them leave that are to leave;
Let them enter that are to enter;
The Kingly Nandi makes us see all
And Himself, witnesses all;
All things appropriate He does;
He, of tender love.`,
  },
  {
    id: 2177, tantraId: 8, verseNumber: 2176,
    tamil: `பத்தொடு பத்துமோர் மூன்றும் பகுதியும்
உய்த்த துரியமும் உள்ளுணர் காலமும்
மெய்த்த வியோமமும் மேலைத் துரியமும்
தத்துவ நாலேழ் எனஉன்னத் தக்கதே`,
    transliteration: `pattoṭu pattumōr mūṉṟum pakutiyum
uytta turiyamum uḷḷuṇar kālamum
meytta viyōmamum mēlait turiyamum
tattuva nālēḻ eṉauṉṉat takkatē`,
    english: `2176: Tattvas Are Reckoned As Twenty-Eight In Yet Another
Way
The sense organs ten and ten,
The intellectual organs one and three,
The Turiya State,
Time subjectively cognised,
The undifferentiated Void
And the Turiyatita above
--Thus it is as eight and twenty, too
The Tattvas reckoned are.`,
    elaborationEnglish: ``,
    elaborationTamil: `('வேதாந்திகள் கொள்வன' - என மேற்கூறப்பட்ட) தத்துவங்கள் இருபத்தெட்டு என்னும் தொகை, தூலபூதம் ஐந்து, சூக்கும பூதம் (தன்மாத்திரை) ஐந்து, ஆகிய பூதங்கள் பத்தும், ஞானேந்திரியம் ஐந்து, கன்மேந்திரியம் ஐந்து ஆகிய இந்திரியங்கள் பத்தும், 'மனம், அகங்காரம், புத்தி' - என்னும் அந்தக் கரணங்கள் மூன்றும், மூலப்பகுதி ஒன்றும் ஆகிய சடங்கள் இருபத்து நான்கும், அவற்றிற்கு மேல் அபர துரியமாகிய புருடன், அல்லது சீவன் ஒன்றும், அதற்குமேல் காலத்தின் வாயிலாக எல்லாவற்றையும் இயக்குகின்ற ஈசுரன் ஒருவனும், அவனுக்கு மேலேயுள்ள மாயையாகிய பராகாசமும், அவனுக்கு மேல் பரதுரியமாகிய பரம்பொருள் ஒன்றும் எனக் கருதத் தக்கதாகும்.`,
  },
  {
    id: 2178, tantraId: 8, verseNumber: 2177,
    tamil: `விளங்கிடு முந்நூற்று முப்பதோடு ஒருபான்
தளங்கொள் இரட்டிய தாறு நடந்தால்
வணங்கிடும் ஐம்மலம் வாயு எழுந்து
விளங்கிடும் அவ்வழி தத்துவம் நின்றே`,
    transliteration: `viḷaṅkiṭu munnūṟṟu muppatōṭu orupāṉ
taḷaṅkoḷ iraṭṭiya tāṟu naṭantāl
vaṇaṅkiṭum aimmalam vāyu eḻuntu
viḷaṅkiṭum avvaḻi tattuvam niṉṟē`,
    english: `2177: Breath Control For Ridding Malas
If ten times three hundred and thirty
The breath twelve finger-length
As Prana ascends upward,
The Malas Five subdued are;
So do the Tattvas, according.`,
    elaborationEnglish: `If prana ascends upward three hundred and thirty one times, the five malas are subdued. By breath control the ninety-six tattvas subside within the body which, in turn, merges in the twenty-five tattvas.`,
    elaborationTamil: `முந்நூறு, அதனுடன் முப்பதொருபான்; அஃதா வது முந்நூறு, இரண்டும் கூட அறுநூறு. தளம் - படி. இரட்டிய தாகிய ஆறு. ஆறாறு = முப்பத்தாறு, அறுநூற்றை முப்பத்தாறு படியாக உறழ வருவது இருபத்தோராயிரத்து அறுநூறு. இஃது ஒரு நாளைக்கு வெளிச்சென்றும், உட்புகுந்தும் நடக்கின்ற மூச்சின் எண்ணிக்கை யாகும். இவ்வாறு வாயு - பிராணன். எழுந்து நடந்தால், உயிரைப் பற்றி யுள்ள பஞ்சமலங்களும் தன் தன் வேலையைச் செய்யும். அப்பொழுது தான் மாயா காரியமாகிய தத்துவங்களின் செயல்களும் விளங்குவனவாம்.`,
  },
  {
    id: 2179, tantraId: 8, verseNumber: 2178,
    tamil: `நாலொரு கோடியே நாற்பத்தொண் ணாயிரம்
மேலுமோர் ஐந்நூறு வேறாய் அடங்கிடும்
பாலவை தொண்ணூறோடு ஆறுள் படும்அவை
கோலிய ஐ ஐந்துள் ஆகும் குறிக்கிலே`,
    transliteration: `nāloru kōṭiyē nāṟpattoṇ ṇāyiram
mēlumōr ainnūṟu vēṟāy aṭaṅkiṭum
pālavai toṇṇūṟōṭu āṟuḷ paṭumavai
kōliya ai aintuḷ ākum kuṟikkilē`,
    english: `2178: By Breath Control Tattvas Subside Within Body
If breath appropriate spirated
Times, four crores and forty eight thousand five hundred,
Then cessation there shall be for Prana's movement;
It in the ninety-six (Tattvas) subsides;
The ninety-six in turn
In Tattvas five and twenty merge.`,
    elaborationTamil: `'நாலுகோடியே நாற்பத்தொண்ணாயிரத்து ஐந்நூறு' என்பது முற்கூறிய எண்ணிக்கையில் உயிர்ப்பு இயங்கும் இயக்கத் தொகை. அத்தொகையளவு, சிறிதே ஏற்றம் உள்ள ஐந்தாண் டுகளாம். (எனவே, அந்த அளவு மூச்சு, உடல் வளர்வதற்குத்தவிர, உயிர்க்கு யாதும் பயன்தருவன அல்லவாம்). இனி, 'மூச்சு இயங்கும் காலத்தில் விளங்கிடும்' எனப்பட்ட தத்துவங்கள் தொண்ணூற்றா றாகும். எனினும், அவற்றை இருபத்தைந்தில் அடக்குவார் உளர்.`,
  },
  {
    id: 2180, tantraId: 8, verseNumber: 2179,
    tamil: `ஆகின்ற தொண்ணூறோடு ஆறும் பொதுஎன்பர்
ஆகின்ற ஆறாறு அருஞ்சைவர் தத்துவம்
ஆகின்ற நாலேழ் வேதாந்தி வயிணவர்க்கு
ஆகின்ற நாலாறுஐ ஐந்துமாயா வாதிக்கே`,
    transliteration: `ākiṉṟa toṇṇūṟōṭu āṟum potueṉpar
ākiṉṟa āṟāṟu aruñcaivar tattuvam
ākiṉṟa nālēḻ vētānti vayiṇavarkku
ākiṉṟa nālāṟuai aintumāyā vātikkē`,
    english: `2179: Tattvas Differently Counted By Different Schools of
Philosophy
Tattvas six and ninety are the over-all;
Out of them, six and thirty are the Tattvas for Saivas;
Eight and twenty for Vedantins;
Four and twenty for Vainavas;
Five and twenty for Mayavadins.`,
    elaborationTamil: `இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 2181, tantraId: 8, verseNumber: 2180,
    tamil: `தத்துவ மானது தன்வழி நின்றிடில்
வித்தக னாகி விளங்கி யிருக்கலாம்
பொய்த்துவ மாம்அவை போயிடும் அவ்வழி
தத்துவம் ஆவது அகார எழுத்தே`,
    transliteration: `tattuva māṉatu taṉvaḻi niṉṟiṭil
vittaka ṉāki viḷaṅki yirukkalām
poyttuva māmavai pōyiṭum avvaḻi
tattuvam āvatu akāra eḻuttē`,
    english: `2180: Letter-Sound "A" is Primal Tattva (Truth)
If Jiva can make Tattvas function his way,
He a wise one shall be;
Illumined in Knowledge Divine,
False devotion no more shall be;
The Tattva Supreme is the primal letter-sound.`,
    elaborationEnglish: `Jiya is wisé when he can make the tattvas function in the illumined way. With illumination in divine knowledge attained, false devotion leaves. The letter-sound ‘A’ is the primal tattva.`,
    elaborationTamil: `'மெய்' என்பன யாவும் ஒருவனது அறிவினுள்ளே அடங்கித் தோன்றுமாயின் அவன் ஏனையோர் பலரினும்திறம் மிக உடையனாய் விளங்கலாம். அப்பொழுது பயனில்லாத செயல்கள் யாவும் ஒழிந்து, பயனுள்ள செயல் கைவரும். அங்ஙனம் உணரப்படும் மெய்களில் நாதம் தலையாயது.`,
  },
  {
    id: 2182, tantraId: 8, verseNumber: 2181,
    tamil: `அறிவொன் றிலாதன ஐஏழும் ஒன்றும்
அறிகின்ற என்னை அறியாது இருந்தேன்
அறிகின்றாய் நீஎன்று அருள்செய்தார் நந்தி
அறிகின்ற நானென்று அறிந்து கொண்டேனே`,
    transliteration: `aṟivoṉ ṟilātaṉa aiēḻum oṉṟum
aṟikiṉṟa eṉṉai aṟiyātu iruntēṉ
aṟikiṉṟāy nīeṉṟu aruḷceytār nanti
aṟikiṉṟa nāṉeṉṟu aṟintu koṇṭēṉē`,
    english: `2181: Jiva Alone is the Sentient Being
Tattvas Thirty and Six
Are insentient verily (devoid of knowledge)
I am the sentient one;
Yet I knew not Myself;
"You shall know yourself"
--Thus in Grace, Nandi declared;
That I am the Knower,
I have now known.`,
    elaborationEnglish: `Among the thirty-six tattvas, jiva alone is the sentient being. In the waking state mala creates the five experiences. In union with God, jiva is disentangled from these five states and from the unreal tattvas. sréGgy sraOo wih soflovgopgid HEG DOTUgZags mugs sorcurH GuréA WeunGnor@w Gundiwrer cunprpy 658) OsiHerGnrsr orHCGu HHGGw. 2182`,
    elaborationTamil: `'நான் எது' என்று தொடங்கி, முப்பத்தாறு தத் துவங்களையும் நிலம் முதல் நாதம் ஈறாக, ஒவ்வொன்றாக ஆராய்ந்து வந்தபொழுது, அவை அனைத்துமே சடமாய் இருத்தலால், 'யான்' என்றும், 'எனது' என்றும் உணரும் உணர்வுகளையுடைய நான் அவை களில் ஒன்றேனும் அல்லாமை புலப்பட்டது. ஆயினும் 'அவ்வுணர் வினையுடைய நான் எது' என உணர இயலாமலே திகைத்திருந்தேன். அப்பொழுது நந்தி பெருமான், 'முப்பத்தாறு தத்துவங்களும் சடம்' என்றும், 'நான் அவைகளில் ஒன்றேனும் அல்லேன்' என்றும் உணர்ந்தது எது? அதுதான் நீ என்று உணர்த்தினார். அதன் பின் நான் அவ்வாறே உணர்ந்து மெய்யுணர்வு உடையனாயினேன்.`,
  },
  {
    id: 2183, tantraId: 8, verseNumber: 2182,
    tamil: `சாக்கிர சாக்கிர மாதி தனில்ஐந்தும்
ஆக்கும் மலாவத்தை ஐந்து நனவாதி
போக்கி இவற்றொடும் பொய்யான ஆறாறு
நீக்கி நெறிநின்றுஒன்று ஆகியே நிற்குமே`,
    transliteration: `cākkira cākkira māti taṉilaintum
ākkum malāvattai aintu naṉavāti
pōkki ivaṟṟoṭum poyyāṉa āṟāṟu
nīkki neṟiniṉṟuoṉṟu ākiyē niṟkumē`,
    english: `2182: Transcend Five States of Consciousness and Thirty-Six
In the Waking State
Are States of experiences five
Malas create;
Disentangling from these states five,
And from Tattvas unreal, thirty and six,
In the holy way Jiva stood,
And one with Him union attained.`,
    elaborationTamil: `சகலத்தில் சகலமாகிய சகலசாக்கிரத்திற்றானே நிகழும் சாக்கிரம் முதலிய ஐந்தையும், ஆணவத்தாலே ஆக்கப் படுகின்ற கேவல சாக்கிரம் முதலிய ஐந்தையும் அவை நிகழாதபடி, முதலாவதாகச் சொல்லப்படுகின்ற சகல சாக்கிரத்தில் உறைத்து நிற்கு மாற்றானே போக்கிச் சிவத்தோடும் திருவருள் வழியில் நிற்பவன், சடம் ஆதலின் நிலையின்றித் தோன்றியழிவனவாகிய முப்பத்தாறு தத்துவங்களுட்பட்டு, தத்துவான்மாவாய் நில்லாது, அவற்றின் நீங்கிச் சுத்தான்மா ஆவான்.`,
  },
  {
    id: 2184, tantraId: 8, verseNumber: 2183,
    tamil: `ஆணவ மாதி மலம்ஐந்து அவரோனுக்கு
ஆணவ மாதிநான் காம்மாற்கு அரனுக்கு
ஆணவ மாதிமூன்று ஈசர்க்கு இரண்டென்ப
ஆணவம் ஒன்றே சதாசிவற்கு ஆவதே.`,
    transliteration: `āṇava māti malamaintu avarōṉukku
āṇava mātināṉ kāmmāṟku araṉukku
āṇava mātimūṉṟu īcarkku iraṇṭeṉpa
āṇavam oṉṟē catācivaṟku āvatē.`,
    english: `2183: Number of Malas for the Five Gods
Five are the Malas
For Brahma on the Lotus Bloom,
Anava (Egoity) and the rest; (Anava, Maya, Karma, Mayeyam and Tirodayi)
Four are the Malas for Vishnu;
Anava and others (Mayeyam devoid)
Three for Rudra,
Anava and Others (Mayeyam and Tirodayi devoid);
Two for Mahesa
Anava and Karma;
One alone for Sadasiva--Anava.`,
    elaborationTamil: `(பஞ்ச மலங்களும், 'ஆணவம், கன்மம், மாயை, மாயேயம், திரோதாயி' என்னும் முறையில் வைத்துச் சொல்லப்படும். இவற்றுள் மறைத்தல் தொழிலைச் செய்வதில் தலைமை பெற்று நிற்பது திரோதாயியே. அதனால்), பிரமன் சிவனைச் சிறிதும் உணராதவன் ஆகலின் அவனைப் பஞ்ச மலங்களையும் உடையவனாகவும், மாயோன் சிவனைச் சிறிது அறிந்தவன் ஆகலின் அவனை, திரோதாயி ஒழிந்த ஏனை நான்கு மலங்களை உடையவனாகவும், மாயோன் சிவனைச் சிறிது அறிந்தவன் ஆகலின் அவனை, திரோதாயி ஒழிந்த ஏனை நான்கு மலங்களை உடையவனாகவும், சீகண்ட ருத்திரன் பிரளயாகலன் ஆகலின் அவனைத் திரோதாயி, மாயேயம் - இவை யொழிந்த மூன்று மலங்களே உடையவனாகவும், வித்தியேசுரர் மந்திர மகேசுரர் முதலியோர் விஞ்ஞானகலர் ஆயினும் அதிகார மலம் நீங்கா மையால் ஆணவத்தோடு, கன்மமும்கூட, இரண்டு மலங்களை யுடையவர்களாகவும், அணு சதாசிவர்கள் அதிகார மலம் நீங்கினும் போக மலம் நீங்காமையால் ஆணவம் நீங்கப் பெறாது அஃது ஒன்றனையே உடையவர்களாகவும் கூறலாம்.`,
  },
  {
    id: 2185, tantraId: 8, verseNumber: 2184,
    tamil: `தத்துவம் ஆறாறு தன்மனு ஏழ்கோடி
மெய்த்தரு வன்னம்ஐம் பான்ஒன்று மேதினி
ஒத்துஇரு நூற்றுஇரு பான்நான்குஎண் பான்ஒன்று
வைத்த பதம்கலை ஓர்ஐந்தும் வந்தவே`,
    transliteration: `tattuvam āṟāṟu taṉmaṉu ēḻkōṭi
meyttaru vaṉṉamaim pāṉoṉṟu mētiṉi
ottuiru nūṟṟuiru pāṉnāṉkueṇ pāṉoṉṟu
vaitta patamkalai ōraintum vantavē`,
    english: `2184: The Six Higher Steps
Six times six are the Tattvas;
Seven Crores are the Mantras;
Fifty and one are the Varnas (letter-sounds);
Two hundred and twenty four are the Bhuvanas; global constellations;
Eighty and one are the Padas Primal,
Five, the Kalas rare.`,
    elaborationEnglish: `Mantram, padam, varnam, bhuvanam, kalas and tattvas — these constitute the six adhvas or the higher paths.`,
    elaborationTamil: `ஆறத்துவாக்களில், 'தத்துவம் முப்பத்தாறு' என்பது முன்பே குறித்து, விளக்கம் தரப்பட்டது. (எனவே, அஃது இங்கு நினை வூட்டும் அளவே கூறப்பட்டதாம்.)`,
  },
  {
    id: 2186, tantraId: 8, verseNumber: 2185,
    tamil: `நாடிய மண்டலம் மூன்றும் நலந்தெரிந்து
ஓடும் அவரோடு உள்இரு பத்துஐஞ்சும்
கூடுவர் கூடிக் குறிவழி யேசென்று
தேடிய பின்னர்த் திகைத்திருந் தார்களே`,
    transliteration: `nāṭiya maṇṭalam mūṉṟum nalanterintu
ōṭum avarōṭu uḷiru pattuaiñcum
kūṭuvar kūṭik kuṟivaḻi yēceṉṟu
tēṭiya piṉṉart tikaittirun tārkaḷē`,
    english: `2185: Ascend Beyond the Three Spheres
The three Spheres within (Sun, Moon, and Fire)
They ascend and traverse, (in yogic way)
Having traversed,
They with Tattvas five and twenty
In one unite;
Further coursing the breath
Upward through Sushumna
They search;
And having sought,
Self-Consciousness lost,
They there remain.`,
    elaborationTamil: `(அத்துவாக்களைத் தரிசிக்க, அஃதாவது உள்ளபடி நேரிலே காண விரும்பியவர்கள் பிராசாத நெறியில் நின்று) உடம்பிலே கீழிருந்து பாவிக்கப்படுகின்ற நெருப்பு மண்டலம், நீர் மண்டலம், நிலா மண்டலம் - என்னும் மூன்று மண்டலங்களை உள்ளே உணர்ந்து இடை கலை, பிங்கலை வழியாக ஓடுகின்ற அந்தத் துணைவரோடு தாமும் ஓடித் தூல சூக்கும தத்துவங்களாகிய இருபத்தைந்து தத்துவங்களைக் கண்டார்கள். அதன் பின்பு அந்தத் துணைவரால் ஆகாமையின், குரு காட்டிய அந்தக் குறியான வழியிலே சென்று பர தத்துவங்களைத் தேடினர். அவ்வாறு தேடியும் அவை தரிசனப்படாமையால், ஒன்றும் தோன்றாது திகைத்து நின்றுவிட்டார்கள்.`,
  },
  {
    id: 2187, tantraId: 8, verseNumber: 2186,
    tamil: `சாக்கிர சாக்கிர மாதித் தலையாக்கி
ஆக்கிய தூலம் அளவாக்கி அதீதத்துத்
தாக்கிய அன்பான தாண்டவம் சார்ந்துஅது
தேக்கும் சிவமாதல் ஐந்தும் சிவாயவே`,
    transliteration: `cākkira cākkira mātit talaiyākki
ākkiya tūlam aḷavākki atītattut
tākkiya aṉpāṉa tāṇṭavam cārntuatu
tēkkum civamātal aintum civāyavē`,
    english: `2186: The Fifth State of Turiyatita
Waking within the Waking State,
And experiencing the rest of States,
The body and breath appropriate trained,
They reach the Turiyatita;
There they witness the felicitous Dance of Lord;
Drinking the fill of bliss
They Siva Become;
All these five, the Grace-fruits of Siva are.`,
    elaborationEnglish: ``,
    elaborationTamil: `'நமசிவாய' என்னும் ஐந்தெழுத்து மந்திரத்தை (ஏனைக் கிரியா மந்திர யோக மந்திரங்களைப் போல எண்ணாமல், உண்மையை அனுபவமாக உணர்விக்கும் ஞான மந்திரமாகக் கொண்டு) சகலசாக்கிரத்தில் (சகலஐந்தவத்தைகள் நிகழாதவாறு தடுத்து,) ஞானவத்தைகளாகிய சுத்த சாக்கிரம் முதலியனவே நிகழுமாறு, அந்தச் சாக்கிரம் முதலிய ஐந்திலும் ஐந்து வகையாகச் சுத்த மானதம் ஆகிய அறிவினாலே கணித்து, ஆதாரங்கள் ஆறும், அவற்றிற்கு மேல் ஏழாவதாகிய நிராதாரமும் உடம்பளவினவாய் நீங்க, உடம்பைக் கடந்த துவாதசாந்தமாகிய மீதானத்தில் சென்று பொருந்திய அன்பே வடிவாய் நிகழும் திருக்கூத்தை உயிர் சென்று அடைவதே, எல்லையில் இன்பத்தைச் சிவம் பெருக்கி, அதற்கு வழங்குகின்ற சிவமாம் நிலையாகும்.`,
  },
  {
    id: 2188, tantraId: 8, verseNumber: 2187,
    tamil: `நானவாதி தூலமே சூக்கப் பகுதி
அனதான ஐஐந்தும் விந்துவின் சத்தி
தனதாம் உயிர்விந்து தான்நின்று போந்து
கனவா நனவில் கலந்ததுஇவ் வாறே`,
    transliteration: `nāṉavāti tūlamē cūkkap pakuti
aṉatāṉa aiaintum vintuviṉ catti
taṉatām uyirvintu tāṉniṉṟu pōntu
kaṉavā naṉavil kalantatuiv vāṟē`,
    english: `2187: Bindu Power Permeates Tattvas
The gross body of Waking State,
The subtle body of Dream State,
Together of Tattvas five and twenty
Are of Bindu's Power verily;
That Power permeating Jiva
Penetrates, the Waking and Dream States.`,
    elaborationEnglish: `Bindu power penetrates jiva in the waking, dream and other states, and thus permeates tattvas.`,
    elaborationTamil: `கீழாலவத்தையாய் யாவராலும் நன்கு உணர நிகழும் கேவல சாக்கிரம் முதலிய ஐந்தையும் போல்வனவே, நுண்ணறி வுடையோரால் மட்டும் ஊன்றியுணரப் படுகின்ற மத்தியாலவத்தை யாகிய சகல சாக்கிரம் முதலிய ஐந்தும். அந்த ஈரைந்து அவத்தை களிலும் உள்ள இருபத்தைந்து தத்துவங்களும் சுத்த மாயையிலும் உள்ளன. (யோகாவத்தையில் அவை செயற்படும்) அவைகளி னின்றும் உயிர் தனது உணர்வு விடுபட்டுச் சென்று, திருவருளில் முன் பெல்லாம் தான் கண்டு வந்த கனவு போல உணரப்படுகின்ற காட்சியில் தோய்கின்ற நிலையே சுத்த சாக்கிரம் முதலிய சுத்தாவத்தைகளாம்.`,
  },
  {
    id: 2189, tantraId: 8, verseNumber: 2188,
    tamil: `நனவில் அதீதம் பிறந்தார் கிடந்தார்
நனவில் துரியம் நிகழ்ந்தார் தவழ்ந்தார்
நனவில் சுழுத்தி நடந்தார் வளர்ந்தார்
நனவில் கனவுஓட நன்செய்தி யானதே`,
    transliteration: `naṉavil atītam piṟantār kiṭantār
naṉavil turiyam nikaḻntār tavaḻntār
naṉavil cuḻutti naṭantār vaḷarntār
naṉavil kaṉavuōṭa naṉceyti yāṉatē`,
    english: `2188: Progression of the States of Consciousness Towards
Siva-Goal
They who reach the Turiyatita
Within the Waking State
Actionless lie;
They who reach the Turiya
Within the Waking State
Crawl (towards the Goal);
They who experience the Sushupti (Deep Sleep)
Within the Waking State
Are Jivas yet developing;`,
    elaborationEnglish: `In dream, jiva marches towards the divine goal; in the sushupti State he rises further and still further in the turiya state. In turiyatita state the jiva lies impassive.`,
    elaborationTamil: `'சாக்கிரத்தில், 'அதீதம்' என்னும் நிலை தோன்றப் பெற்றவர், தம்மால் உணரப்பட்ட பொருளையும் தம்மையும் வேறு வேறாக அறிதல் இன்றி அப்பொருளேயாய் அழுந்தித் தற்போதத்தை இழந்திருப்பர். அதனால் அவர், இடம் பெயரமாட்டாது கிடந்த கிடப்பில் கிடக்கும் பசுங்குழவி போல்பவாவர்.
சாக்கிரத்தில் 'துரியம்' - என்னும் நிலை தோன்றப் பெற்றவர், தம்மால் உணரப்படும் பொருளையும், தம்மையும் வேறு வேறாக அறிந்து, அந்த அளவில் அனுபவிக்கும் உணர்வு உடையவராவர், அதனால், அவர் இடம் பெயர்ந்து தவழ்ந்து செல்லும் குழவி போல்வர்.
சாக்கிரத்தில், 'சுழுத்தி' என்னும் நிலை தோன்றப் பெற்றவர் உணரப்படும் பொருளையும், உணரும் தம்மையும் வேறுவேறாகப் பகுத்து நன்குணர்வர். அதனால் அவர் வளர்ச்சியடைந்து நன்கு நடக்கும் சிறுபிள்ளைகள் போல்வர்.
சாக்கிரத்தில், 'சொப்பனம்' என்னும் நிலை தோன்றப் பெற்றவர், பொருளில் மேலும் மேலும் நாடும் நாட்டம் மிகுந்து இருப்பர். அதனால் அவர் நன்கு ஓடி ஆடும் பருவச் சிறுபிள்ளை களோடு ஒப்பர். (மகளிரில், 'பெதும்பைப் பருவத்தாரோடு ஒப்பர்' எனலாம்.)
சாக்கிரத்தில், 'சாக்கிரம்' என்னும் நிலை தோன்றப் பெற்றவர் வாழ்க்கையில் முழுமையாக ஈடுபடுவர். அதனால் அவரக்ள கட்டிளமையுடையவரோடு ஒப்பர். (எனினும், ஆடவர்களில் பிரமசாரிகளையும், பெண்டிரில் கன்னிகைகளையும் இங்கு உவமையாகக் கொள்க.)`,
  },
  {
    id: 2190, tantraId: 8, verseNumber: 2189,
    tamil: `செறியுங் கிரியை சிவதத் துவமாம்
பிறிவில் சுகயோகம் பேரருள் கல்வி
குறிதல் திருமேனி குணம்பல வாகும்
அறிவில் சராசரம் அண்டத் தளவே`,
    transliteration: `ceṟiyuṅ kiriyai civatat tuvamām
piṟivil cukayōkam pēraruḷ kalvi
kuṟital tirumēṉi kuṇampala vākum
aṟivil carācaram aṇṭat taḷavē`,
    english: `2189: Chariya, Kriya, Yoga and Jnana--Where They Lead To
The acts of Kriya lead to Siva Tattva;
The practice of prolonged Yoga
Leads to Divine Grace and Knowledge;
Contemplation of Lord's Form, (in Chariya)
Confers blessings many;
In Jnana is comprehended
All Cosmic creation at once.`,
    elaborationEnglish: `The acts of kriya lead to Siva tattva; and of yoga, to divine Grace and Knowledge. Charya bestows benediction; and in jnana the entire cosmic creation is comprehended.`,
    elaborationTamil: `சிவநெறி மார்க்கம் நான்கனுள் சற்புத்திர மார்க்க மாகிய கிரியையில் நிற்பின் சிவ தத்துவங்கள் ஐந்தும் காட்சிப்படுவன வாம். சிவத்தோடு தன்னை ஒன்றவைத்து உன்னும் சகமார்க்க மாகிய யோகத்தால் சிவனது திருவருளை நிரம்பப் பெறுதல் கூடும். சிவனது ஞானத்தை உணர்தலாகிய சன்மார்க்கத்தால் ஆன்மாவினது ஞானமும் சிவஞானமேயாய், அதுவே தற்சொரூபமாய் நிற்கும். அந் நிலையில் சிவனது எல்லாக் குணங்களும் ஆன்மாவுக்கு உளவாகும். அப்பொழுது ஆன்மாவும் சிவனைப் போலவே எங்கும் நிறைந்து விளங்கும்.`,
  },
  {
    id: 2191, tantraId: 8, verseNumber: 2190,
    tamil: `ஆதி பரஞ்சிவம் சத்தி சதாசிவம்
ஏதம்இல் ஈசன்நல் வித்தியா தத்துவம்
போதம் கலைகாலம் நியதிமா மாயை
நீதிஈ றாக நிறுத்தினன் என்னே`,
    transliteration: `āti parañcivam catti catācivam
ētamil īcaṉnal vittiyā tattuvam
pōtam kalaikālam niyatimā māyai
nītiī ṟāka niṟuttiṉaṉ eṉṉē`,
    english: `2190: Devolutes of Paraparam
The Beginningless Param
Thus the order brought about:
Siva, Sakti, and Sadasiva,
The Isa Pure, and the goodly Vidya Tattvas
Bodha, Kalas, Time, Niyati and Mamaya (Impure Maya)
--These devolutes in gradation appropriate
He established,
In wonder surpassing indeed!`,
    elaborationEnglish: `(i) Siva (nada); (ii) Sakti (bindu); (iii) Sadasiva (Sadakhya); (iv) Isvara (Mahesvara); (v) suddha vidya (Rudra) — these five are the first evolutes of Param. They are known as Siva tattvas, and are in the pure maya sphere.`,
    elaborationTamil: `'சிவம், சத்தி, சதாசிவம், ஈசுரம், சுத்தவித்தை' என்னும் சிவ தத்துவங்களையும், அவற்றின் கீழ் உள்ள 'கலை, காலம், நியதி, வித்தை, அராகம், மாயை' என்னும் வித்தியா தத்துவங் களையும் அநாதி நிலையினின்றும் இறங்கி ஆதியாய் நிற்கின்ற சிவன் படைத்தருளினான் என்று உணர்க.`,
  },
  {
    id: 2192, tantraId: 8, verseNumber: 2191,
    tamil: `தேச திகழ்சிவம் சத்தி சதாசிவம்
ஈசன் அனல்வித்தை இராகம் கலைகாலம்
மாசகல் வித்தை நியதி மகாமாயை
ஆசில் புருடாதி ஆன்மாஈ றாறே`,
    transliteration: `tēca tikaḻcivam catti catācivam
īcaṉ aṉalvittai irākam kalaikālam
mācakal vittai niyati makāmāyai
ācil puruṭāti āṉmāī ṟāṟē`,
    english: `2191: Jiva Ascends These Devolutes to Reach Paraparam
The luminous Siva, Sakti and Sadasivam,
The Maheswara, the Pure Vidya, and Ragas,
Kalas, Time (Kala), Knowledge (Bodha), Niyati, and Mahamaya
The Purusha (soul),
Together these twelve
(Art for the Jiva to ascend.)`,
    elaborationEnglish: `Below the five Siva tattvas in the pure maya sphere, are the seven tattvas in the impure maya (or mamaya) sphere. This . sphere is also referred to as misra (mixed) or pure/impure maya. These seven tattvas are known as vidya tattvas and should not be confused with the suddha (pure) vidya tattvas in the pure maya (or Siva tattva) sphere. These seven are: (i)kala; (ii)niyati; (iv)vidya or bodha; (v) raga; (vi) and (vii)purusha.

These 12 tattvas (S plus 7) are above the 24 prakriti or atma tattvas. Of these, seven belong to the lower strata (vidya tattvas) and five to the upper strata (Siva tattva).`,
    elaborationTamil: `(மேற்கூறிய இருவகைத் தத்துவங்களையும் கூட்டித் தொகை காணின்) 'சிவம், சத்தி, சதாசிவம், ஈசுரம், சுத்த வித்தை, கலை, காலம், நியதி, வித்தை, அராகம், புருடன், மாயை' - எனப் பன்னிரண்டாம். இவற்றுள் 'புருடன்' என்பது ஏனையபோல ஒரு தத்துவம் அன்று. கலை முதலிய ஐந்தனோடும் கூடி நிற்கும் ஆன்மாவே.`,
  },
  {
    id: 2193, tantraId: 8, verseNumber: 2192,
    tamil: `ஆணவம் மாயையும் கன்மமும் ஆம்மலம்
காணும் முளைக்குத் தவிடுஉமி ஆன்மாவும்
தாணுவை ஒவ்வாமல் தண்டுலமாய் நிற்கும்
பேணுவாய் மற்றுநின் பாசம் பிரித்தே`,
    transliteration: `āṇavam māyaiyum kaṉmamum āmmalam
kāṇum muḷaikkut taviṭuumi āṉmāvum
tāṇuvai ovvāmal taṇṭulamāy niṟkum
pēṇuvāy maṟṟuniṉ pācam pirittē`,
    english: `2192: Malas Inherent to Jiva
These the Malas (Impurities) are;
They are like the embryo, the bran and the husk
Are unto the grain of rice;
They touch not the Lord, but apart stand;
Be rid of your Pasas one by one,
And adore the Lord.`,
    elaborationEnglish: ``,
    elaborationTamil: `'ஆணவம், மாயை, கன்மம்' - என மலங்கள் மூன்றாம். அவற்றை எதிர்நிரல் நிறையாக வைத்து, அரிசிக்கு முளை, தவிடு, உமி - இவைபோல்வனவாக உணர்க. ஆன்மாவும் சிவனைப் போலச் சித்துப் பொருளேயாயினும், அரிசி போன்ற ஒரு தன்மையை அஃது உடைமையால் அரிசிக்கு உமி முதலிய குற்றங்கள் அநாதியாக இருத்தல் போல, ஆணவம் முதலிய குற்றங்கள் அநாதியே உளவாக, அது சிவனைப் போலப் பதியாகாது, பசுவேயாய் நின்றது. உனது தன்மையை இங்ஙனம் நீ உள்ளவாறு உணர்ந்து, பாசங்களில் பற்றுக் கொள்ளாது விடுத்துப் பதியாகிய சிவனைப் பற்றி இன்புறுவாயாக.`,
  },
  {
    id: 2194, tantraId: 8, verseNumber: 2193,
    tamil: `பசுக்கள் பலவண்ணம் பாலொரு வண்ணம்
பசுக்களை மேய்க்கின்ற ஆயன் ஒருவண்ணம்
பசுக்களை மேய்க்கின்ற ஆயன்கோல் போடில்
பசுக்கள் தலைவனைப் பற்றி விடாவே`,
    transliteration: `pacukkaḷ palavaṇṇam pāloru vaṇṇam
pacukkaḷai mēykkiṉṟa āyaṉ oruvaṇṇam
pacukkaḷai mēykkiṉṟa āyaṉkōl pōṭil
pacukkaḷ talaivaṉaip paṟṟi viṭāvē`,
    english: `2193: Lord is the Cow-Herd (Pasupati); Jiva the Cow (Pasu)
Many the color of cows,
But one the color of milk;
And of peerless hue
Is Lord, the cowherd;
When the cowherd
Who tends the cows
His guiding staff shows,
The cows will not their Master leave.`,
    elaborationTamil: `உலகில் பாலைத் தரும் பசுக்கள்யாவும் ஒரே நிறம் உடையன அல்ல; பல நிறம் உடையன. (அது போல, சீவர்களாகிய பசுக்களும், 'பசுத்துவம்' எனப்படும் பந்தத்தைத் ஒரே வகையாக உடையன அல்ல; ஒரே வகையை உடையனவாயின், பந்தத்தினின்றும் விடுபடுதலும் எல்லாப் பசுக்களுக்கும் ஒரு காலத்திலே நிகழ்தல் வேண்டும். அவ்வாறில்லாமையால், பந்த வேறுபாடு பலதிறப் பட்ட தாம்.) ஆயினும், பசுக்கள் தரும் பயனாகிய பால் ஒரு நிறமேயாம். (அது போல அவை அடையும் வீடுபேறு ஒருதன்மையுடையதே.) இனிப் பசுக்களை மேய்க்கின்ற ஆயன் ஒருவன். (ஆகவே, அவன் ஒரு தன்மையனேயன்றிப் பல தன்மை உடையவன் அல்லன். (அதுபோலச் சீவர்களை, 'பெத்தம், முத்தி' என்னும் இரு நிலைகளிலும் உடன்நின்று நடாத்தும் பதி ஒருவனே, ஆகையால் அவன் பதித்தன்மை ஒன்றே உடையனன்றிப் பசுக்கள் போலச் சார்த்ததன் வண்ணமாய்த் தன்மை வேறுபடுபவனல்லன்.)
ஆயன் பசுக்களை மேய்க்காமல் அவற்றின் இச்சைப்படி விட்டு விடுவானேயானால் இவை ஆயனைச் சென்று சேராமல், காட்டில் திரிந்து அல்லற்பட்டே ஒழியும். (அதுபோல, சிவன் சீவர்களைக் கண் ணெடுத்துப் பார்க்காமல் விட்டுவிடுவானேயானால், அவை அவனை அறிந்து இன்புற மாட்டா, பந்தத்தால் விளையும் துன்பத்தில் கிடக்கும்.
''மேய்ப்பாரும் உண்டாய், வெறியும் அடங்கினால்
பார்ப்பான் பசுஐந்தும் பாலாய்ப் பொழியுமே''
எனப் பின்னரும் பசுக்களுக்கு மேய்ப்பான் இருத்தல் இன்றியமையாது எனக் கூறுவார்.)`,
  },
  {
    id: 2195, tantraId: 8, verseNumber: 2194,
    tamil: `உடல்இந் தியம்மனம் ஒண்புத்தி சித்தம்
அடலொன்று அகந்தை அறியாமை மன்னிக்
கெடும்அவ் வுயிர்மயல் மேலும் கிளைத்தால்
அடைவது தான்ஏழ் நரகத்து ளாயே`,
    transliteration: `uṭalin tiyammaṉam oṇputti cittam
aṭaloṉṟu akantai aṟiyāmai maṉṉik
keṭumav vuyirmayal mēlum kiḷaittāl
aṭaivatu tāṉēḻ narakattu ḷāyē`,
    english: `2194: Jiva a Prey to Tattvas and Pasas
The body, indriyas, mind
The intellect, will, egoity and ignorance
To these the Soul a prey falls;
If the Pasas further sprout in him,
To hell, he speeds fast.`,
    elaborationTamil: `தாத்துவிகங்களாகிய உடம்பு, அதில் கரணங் களாய்ப் பொருந்தியுள்ள ஞானேந்திரியங்கள், கன்மேந்திரியங்கள், அந்தக் கரணங்கள் ஆகிய இவற்றின் இயல்பினை அறியாமையால் அவை களையே 'தான்' என மயங்கிக் கெடுகின்ற அந்த உயிர், (அந்த அறியா மையை நீக்கிக் கொள்ள முயலாமல்) மேலும் மேலும் அந்த அறியா மையையே வளர்த்துக் கொண்டிருக்குமானால், அது அடைவது ஏழு நரகங்களிலும் சென்று வீழ்ந்து அங்குள்ள துன்பத்தைத்தான்.`,
  },
  {
    id: 2196, tantraId: 8, verseNumber: 2195,
    tamil: `தன்தெரியாத அதீதம்தற்கு ஆணவம்
சொல்தெரி கின்ற துரியம்சொல் காமியம்
பெற்ற சுழுத்திப்பின் பேசுறும் காதலாம்
மற்றது உண்டிக் கனவுநன வாதலே`,
    transliteration: `taṉteriyāta atītamtaṟku āṇavam
colteri kiṉṟa turiyamcol kāmiyam
peṟṟa cuḻuttippiṉ pēcuṟum kātalām
maṟṟatu uṇṭik kaṉavunaṉa vātalē`,
    english: `2195: Limitations of Experiences in the Five States of
Awareness
In Turiyatita State
The Consciousness of the Self is not;
In Turiya State
The Consciousness of the Self
Through spoken word comprehended
Still burns;
In the Sushupti State that is Maya bound,
The Desire-potency to speak afterward exists;
In the Waking State and the Dream State
Experiences in ways diverse.`,
    elaborationEnglish: `The consciousness of the self ceases in the turiyatita state. In the turiya state, consciousness of the~-self still burns, through comprehension of the spoken word. In the sushupti state, which is maya bound, desire exists; and disparate experiences are undergone in the waking and dream states.`,
    elaborationTamil: `'கேவலம், சகலம், சுத்தம்' - என்னும், காரண அவத்தை மூன்றனுள் கேவலத்தில் துரியாதீதம், உயிர், 'நான்' என் -கின்ற தன்னுணர்வும் இன்றி, ஆணவத்தில் அழுந்தி அதுவேயாய்க் கிடந்த நிலை 'யான்' என்னும் உணர்வு முகிழ்க்கின்ற கேவலத்தில் துரியம், மேற் குறித்த நிலையில் இறைவன் அவ்வுயிருக்கு மூலகன் மத்தைக் கூட்டு வித்த நிலை. கேவலத்தில் சுழுத்தி, மூலகன்மத்தோடு காரண சரீரமாகிய மாயா தத்துவத்தைக் கூட்டிய நிலை. இவைகளில் ஆன்மாவிற்கு வினையை ஈட்டுதல் நுகர்தல்கள் இல்லை, கேவலத்தில் சொப்பனம் கால நியதிகளைக் காட்டுவித்த நிலை. சாக்கிரம் கலை வித்தை அகாரகங் களைக் கூட்டிய நிலை. இந்தச் சொப்பன சாக்கிரங்களில் தான் உயிர் வினைகளை ஈட்டுதலும் நுகர்தலும் நிகழும்.`,
  },
  {
    id: 2197, tantraId: 8, verseNumber: 2196,
    tamil: `நனவில் கனவுஇல்லை ஐந்து நனவில்
கனவிலாச் சூக்குமம் காணும் சுழுத்தி
தனலுண் பகுதியே தற்கூட்டும் மாயை
நனவில் துரியம் அதீதம் தலைவந்தே`,
    transliteration: `naṉavil kaṉavuillai aintu naṉavil
kaṉavilāc cūkkumam kāṇum cuḻutti
taṉaluṇ pakutiyē taṟkūṭṭum māyai
naṉavil turiyam atītam talaivantē`,
    english: `2196: Turiyatita State Inner Divisions--Jagra and Sushupti;
In the five states of Consciousness,
In the Waking State of Turiyatita no dream,
The Subtle body sees;
In the Sushupti State there,
The self experiences the Self (Consciousness withdrawn);
In the Jagra State of Turiyatita
Maya still is.`,
    elaborationEnglish: `Turiyatita state has inner divisions, such as turiyatita-jagrat and turiyatita-sushupti. In turiyatita-sushupti state the self experiences the Self, and in turiyatita-jagrat-state maya still lingers; but turiyatita has no dream state.`,
    elaborationTamil: `நனவில் கனவு இல்லாமைபோலக் கனவிலும் நனவு இல்லையாதலின், சுழுத்தியில், சுழுத்தி முதலிய மூன்று நுட்ப அவத் -தைகள் மட்டுமே உள்ளனவாம். (அவைகளை 'சுழுத்தியிற் சுழுத்தி, சுழுத்தியில் துரியம், சுழுத்தியில் துரியா தீதம்' எனக் கூறிக் காண்க.)
இங்ஙனம் கூறியதனானே, சொப்பனத்தில் சாக்கிரம் ஒழிந்த நான்கும் உளவாதல் பெறப்பட்டது.
நனவில் சொல்லப்படும் துரியமும், துரியாதீதமும் தாமே தனித்து நிகழும் நிலையில் துரியத்தில் இரண்டும், துரியாதீதத்தில் அஃது ஒன்றுமாகவே நிகழும். (அவை, 'துரியத்தில் துரியம்' துரியத்தில் துரியாதீதம்' எனவும், 'துரியாதீதத்தில் துரியாதீதம், எனவும் சொல்லப்படும்.)
''ஐந்துசாக்கிரத்தில்; நான்கு கனவினில்'' என்னும் சிவஞான சித்திச் செய்யுளுக்கு இதுவும் பொருளாமாறு அறிந்து கொள்க.`,
  },
  {
    id: 2198, tantraId: 8, verseNumber: 2197,
    tamil: `ஆறாறில் ஐஐந்து அகல நனாநனா
ஆறாம் அவைவிட ஆகும் நனாக்கனா
வேறான ஐந்தும் விடவே நனாவினில்
ஈறாம் சுழுத்தி இதில்மாயை தானே`,
    transliteration: `āṟāṟil aiaintu akala naṉānaṉā
āṟām avaiviṭa ākum naṉākkaṉā
vēṟāṉa aintum viṭavē naṉāviṉil
īṟām cuḻutti itilmāyai tāṉē`,
    english: `2197: Tattvas Acting in Waking, Dream and Deep Sleep States
In the Waking State within the Waking State
Are Tattvas, five times five
Out of six times six;
When six out of Tattvas in Waking State leave,
Then is Dream State in Waking;
When further beyond five Tattvas leave,
Then ensues Sushupti
Where the Maya functions.`,
    elaborationEnglish: `When six tattvas out of the twenty-five in the waking state within-waking state leave, that is dream state-in-waking. In sushupti-in-waking state, five more tattvas leave, and maya functions. Lorene US YGLor gHNwsHov HUW (penmalt 1 gaybsr crstmnAs GewGs amas giaGsaus Oesormsaned Au seyaler Uwefleerce wrGw. 2198`,
    elaborationTamil: `தத்துவம் முப்பத்தாறில் ஆன்ம தத்துவம் இருபத்து நான்கும், வித்தியா தத்துவத்தில் புருடன் ஒன்றும் ஆக இருபத்தைந்து தத்துவங்களை ஆன்மாத் தன்னின் வேறாகக் கண்டு நீங்குதலே சகலத்தில் சுத்த சாக்கிரமாகும்.
பின்னர், வித்தியா தத்துவத்தில் எஞ்சியுள்ள ஆறு தத்துவங் களையும் அவ்வாறு கண்டு நீங்குதலே சகலத்தில் சுத்த சொப்பனமாகும்.
பின்னர், சிவ தத்துவம் ஐந்தனையும், 'இவை பிரளயாகலர் சகலர்கட்கு பிரேரக மாத்திரையாயும், விஞ்ஞானகலருக்குத் தனு கரண புவன போகங்களாயும் பயன்பட்டுத் தோற்றமும் அழிவும் உடைய அநித்தியப் பொருள்களேயன்றி, இவை தாமே சிவனது இலய போக அதிகாரத் திருமேனிகளாகிய நித்தியப் பொருள்கள் அல்ல; அத் திரு மேனிகள் இவற்றின் வேறாய்ச் சத்தி வடிவாவனவே' எனத் தெளிந்து, அவை பற்றியிருந்த மயக்கத்தின் நீங்குதலே சகலத்தில் சுத்த சுழுத்தி யாகும். இவற்றிற்குப் பின் எஞ்சி நிற்பது காரண நிலையில் உள்ள சுத்த மாயையே,`,
  },
  {
    id: 2199, tantraId: 8, verseNumber: 2198,
    tamil: `மாயையில் வந்த புருடன் துரியத்தில்
ஆய முறைவிட்டு அதுவும்தான் அன்றாகிச்
சேயதே வலவித் துடன் செல்லச் சென்றக்கால்
ஆய தனுவின் பயனில்லை யாமே`,
    transliteration: `māyaiyil vanta puruṭaṉ turiyattil
āya muṟaiviṭṭu atuvumtāṉ aṉṟākic
cēyatē valavit tuṭaṉ cellac ceṉṟakkāl
āya taṉuviṉ payaṉillai yāmē`,
    english: `2198: In Turiya Maya Leaves and Jiva Merges in Bindu
The Purusha (Experient Soul) of Sushupti
When reaches Turiya State
The Maya too leaves,
And if one with Kevala (Primordial) Bindu comes;
Then no more the body its uses has.`,
    elaborationEnglish: `In turiyd state maya too leaves, and jiva merges in primordial bindu. Then the body will be of no use.`,
    elaborationTamil: `(முன்னை மந்திரத்திற் கூறியவாறு) உயிர் மாயா காரியங்களையெல்லாம் கடந்து எஞ்சி நின்ற காரண நிலையில் உள்ள சுத்த மாயை தாரகமாகச் சிவத்தை உணர்ந்து நிற்றலே சகல சாக்கிரத்தில் சுத்த துரியமாகும். பின்னர் ஆன்மா அந்த நிலையிலும் நில்லாமல் விட்டு நீங்கி, அந்தக் காரணமாயையும் தொடர்பின்றி நிற்கச் சிவமே தாரகமாக அதனை உணர்ந்து நிற்றல் சகல சாக்கிரத்தில் சுத்த துரியாதீதமாகும். இந்நிலையில் உடம்பு இருந்தும் இல்லாததேயாம்.`,
  },
  {
    id: 2200, tantraId: 8, verseNumber: 2199,
    tamil: `அதீதத் துரியத்து அறிவனாம் ஆன்மா
அதீதத் துரியம் அதனால் புரிந்தால்
அதீதத்து எழுந்து அறிவாகிய மானன்
முதிய அனலில் துரியத்து முற்றுமே`,
    transliteration: `atītat turiyattu aṟivaṉām āṉmā
atītat turiyam ataṉāl purintāl
atītattu eḻuntu aṟivākiya māṉaṉ
mutiya aṉalil turiyattu muṟṟumē`,
    english: `2199: In Turiyatita Jiva Becomes Knower and Passes Beyond
to Luminous Siva Turiya State
In that Turiyatita State,
The Soul is the Knower verily;
When he passes beyond
From that Turiyatita State
Where Jiva the Knower is
He merges into Luminous Turiya (Siva Turiya)
That the ultimate state is.`,
    elaborationEnglish: `In the turiyatita states the soul is the knower. Passing that state, jiva merges into “‘luminous turiya’’ (Siva turiya) that is the. ultimate state.`,
    elaborationTamil: `நின்மல துரியாதீத நிலையில் சிவனையன்றிப் பிறி தொன்றையும் தாரகமாகக் கொள்ளாமையால், சடத்தன்மை சிறிதும் இன்றித் தூய அறிவேயாய் நிற்கின்ற ஆன்மா, அந்நிலையில், பழஞ் சுடராகிய சிவனது அவ்வருள் வழியே, தொடர்ந்து அவனையே உணர்ந்துநிற்குமாயின், அவ் வருளால் தனது தூய்மை கெடாது, என்றும் அந்நிலையிலே நிற்கும் நிலை கைகூடுவதாகும்.`,
  },
  {
    id: 2201, tantraId: 8, verseNumber: 2200,
    tamil: `ஐஐந்து பத்துடன் ஆனது சாக்கிரம்
கைகண்ட ஐஐந்தில் கண்டம் கனாஎன்பர்
பொய்கண்ட மூவர் புருடன் சுழுனையின்
மெய்கண்டவன்உந்தி மேவல் இருவரே`,
    transliteration: `aiaintu pattuṭaṉ āṉatu cākkiram
kaikaṇṭa aiaintil kaṇṭam kaṉāeṉpar
poykaṇṭa mūvar puruṭaṉ cuḻuṉaiyiṉ
meykaṇṭavaṉunti mēval iruvarē`,
    english: `2200: Tattvas and Their Centers of Action
Tattvas five and twenty and ten to add,
Are the instruments thirty and five
In Jagra;
With instruments five and twenty
In the Throat-Center
Is Dream State;
With three
The Purusha is in Sushupti;
When the two (Purusha and Prana)
The Navel-Center reaches
Then is the Turiya State true.`,
    elaborationEnglish: `1)In the jagrat (waking) state, purusha, the experient soul, functions with 35 tattvas in the eyebrow centre. These 35 are: five jnanendriyas (sense organs); five karmendriyas (motor organs); four antahkarands (inner intelligence organs); ten vayus (airs); five vaks (sounds); one jiva (purusha)—in all 35 tattvas functions in the eyebrow centre. Vide—‘‘Saiva

Jagrat-in-jagrat is functioning with the senses; svapna-in-jagrat is thinking and forgetting; seeking inward is sushupti-in-jagrat; turiya-in-jagrat is abstaining from seeking. Nandi is truly in

Siddhanta Kattalaigal,’’ edited by K. Narayanasami Naidu, p-30.

2)In the dream state, the five sensoria, and the five motoria are left behind in the eyebrow centre, and the rest of the 25 tattvas stand in the throat centre—op.cit.

3)In the deep sleep state (sushupti), chitta, prana, and jiva stand in the heart centre—op.cit.`,
    elaborationTamil: `பிரிந்தும், கூடியும் வரும் கருவிகளில் முப்பத் தைந்து கருவிகள் மட்டுமே கூடிச் செயற்படுவது கேவல சாக்கிரம். (இதுவும் சகல சாக்கிரம்போலப் புருவநடுவில் நிகழும்' என்பது மேற் பல இடங்களில் கூறப்பட்டது.)
சிவ தத்துவம் ஐந்தும், வித்தியா தத்துவம் ஏழும் ஆகப் பன்னிரண்டு தத்துவங்களும் ஆன்மாவை எப்பொழுதும் விட்டுக் நீங்குவன அல்ல, அதனால், 'புருடன்' என ஒன்றுபோலக் கூறுமிடம் எல்லாம் அவத்தை பேதத்தில் இப்பன்னிரண்டு தத்துவங்களும் கொள்ளப்படும். 'அவற்றுள் முப்பத்தைந்து கருவிகள் மட்டுமே கேவல சாக்கிரத்தில் தொழிற்படும்' என்றமையாலும், அவற்றுள் 'புருடன்' என்பது, மற்றும் பதினொரு கருவிகள் கூடியது ஆகையாலும், நாற்பத்தாறு கருவிகள் கேவல சாக்கிரத்தில் தொழிற்படும்.
கேவலசாக்கிரத்தில் செயற்படும் நாற்பத்தாறு கருவிகளாவன; ஞானேந்திரியம் ஐந்து, கன்மேந்திரியம் ஐந்து, ஞானேந்திரிய விடய மாகிய சத்தாதி ஐந்து, கன்மேந்திரிய விடயமாகிய வசனாதி ஐந்து, அந்தக் கரணம் நான்கு, புருடன் ஒன்று, பிரணாதி வாயுக்கள் பத்து என்பன, ''புருடன்' என்பது பன்னிரண்டு கருவிகளை அடக்கியது - என்பது மேலே கூறப்பட்டது.
ஆன்மா புருவ மத்தியிலே நிற்பினும் தொண்ணூற்றாறு கருவிகளும் செயற்படின் சகல சாக்கிரமும், அவற்றுள் ஐம்பது கருவிகள் நீங்க, கேவல சாக்கிரமும் நிகழும் என்க.
சகல சாக்கிரத்தில் ஆன்மா புலன்களை அறிவதில் தீவிரமாய், நன்குணர்ந்து நிற்கும். கேவல சாக்கிரத்தில் ஆன்மாப் புலன்களை அறிந்தும் அறியாதது போன்ற மந்த உணர்வு உடையதாய் இருக்கும். இவை அவ்விரு சாக்கிரத்திற்கும் இடையேயுள்ள வேறுபாடு.
முப்பத்தைந்து கருவிகளில் ஞானேந்திரியம் ஐந்தும், கன் மேந்திரியம் ஐந்தும் ஆகப் பத்துக் கருவிகள் நீங்க, ஏனை இருபத் -தைந்து கருவிகள் மட்டும் செயற்படுவது கேவல சொப்பனம். இந்நிலையில் ஆன்மாக் கண்டத் தானத்தில் நிற்கும். கைகண்ட - சாக்கிரத்தில் நன்கு துய்க்கப்பட்ட.
அவ்விருபத்தைந்தில் சித்தம், பிராணன், புருடன் - ஆகிய மூன்று கருவிகள் மட்டுமே செயற்படுவது கேவல சுழுத்தி. (பொய் என்றது ஐம்புலன்களை. 'சுழுனையில் பொய்கண்ட மூவர் உளர்' என இயைத்துக் கொள்க. 'இவருள் புருடனும் ஒருவன்' என்பதாம்.) 'சுழுத்தி நிகழும் இடம் இருதயம்' என்க.
பொருள்களை உணரும் ஆற்றல் உடைய புருடன் இரு -தயத்தை விட்டு உந்தியை அடைந்தால் அந்நிலை கேவல துரியமாம். அப்பொழுது பிராணன் மட்டுமே உளதாக இருவரே இருப்பர். (இரு கருவிகள் மட்டுமே அவ்விடத்தில் செயற்படும்' என்றபடி.) இங்குப் புருட தத்துவத்தையே உயிராக உபசரித்தார். 'உந்தி மேவில்' என்றதனால் முன்பு இருதயத்தில் நின்றமை பெறப்பட்டது.`,
  },
  {
    id: 2202, tantraId: 8, verseNumber: 2201,
    tamil: `புரியட் டகமே பொருந்தல் நனவு
புரியட் டகந்தன்னில் மூன்று கனவு
புரியட் டகத்தில் இரண்டு கழுத்தி
புரியட் டகத்தொன்று புக்கல் துரியமே`,
    transliteration: `puriyaṭ ṭakamē poruntal naṉavu
puriyaṭ ṭakantaṉṉil mūṉṟu kaṉavu
puriyaṭ ṭakattil iraṇṭu kaḻutti
puriyaṭ ṭakattoṉṟu pukkal turiyamē`,
    english: `2201: Tattvas of the Subtle Body in the Five States of
Consciousness
In Jagra State
All the eight Tattvas
Of the Puriyashta (Subtle) body are;
In Dream State
The three Tattvas
Of the Subtle Body are;
In Sushupti State,
Two of the Subtle Body remain;
In Turiya State,
Only one is behind left,
With Purusha.`,
    elaborationEnglish: `In the jagrat state the subtle body has eight tattvas. In the dream state it has three; in the sushupti state, two. Only one is left behind in the turiya state with purusha.

1)Sound, touch, shape, taste, smell, intellect, mind and egoity—vide Mantra 2123 supra.

2)Intellect, mind and egoity.

3)Intellect and egoity.

4)Egoity.`,
    elaborationTamil: `('புரியட்டக சரீரம்' - என்பது பெரும்பான்மையும் சூக்குமசரீரத்தையும், சிறுபான்மை பரசரீரத்தையும் குறிக்கும். இது சிவஞான போத இரண்டாம் சூத்திரத்து இரண்டாம் அதிகரண சிவஞான மாபாடியத்தாலும் விளங்கும்.)
தன்மாத்திரை ஐந்தும், அந்தக் கரணம் மூன்றும் ஆக எட்டும் கூடியது சூக்கும சரீரம். இவ்விடத்தில் சித்தம் பிரகிருதியில் அடங்கும்.
மூலப் பிரகிருதி ஒன்றும், வித்தியா தத்துவம் ஏழும் ஆக எட்டும் கூடியது பர சரீரம்.
எனவே, 'புரியட்டகம்' என்பது இவ்விரு சரீரங்கட்கும் பெயராதல் விளங்கும். (இவை இரண்டுமே இம் மந்திரத்திற் குறிக்கப்படுகின்றன.)
இரு புரியட்டக சரீரங்களும் தூல சரீரத்தோடு பொருந்தி நிற்கும் நிலையே இருவகைச் சாக்கிராவத்தையாகும். (இருவகை சகலமும், கேவலமும், இவ்வாறு சுருங்கக் கூறினாராயினும் கேவல சாக்கிரத்திலும் கனவிற் போலவே புரியட்டக சரீரம் நிற்கும் என்க.) சத்தாதி ஐந்தும், வசனாதி ஐந்தும், பிராணாதி பத்தும் ஆக இருபதும் தாத்துவிகங்கள். ஆகையால் அவற்றை எண்ணாமல் விடுக்கச் சூக்கும சரீரத்தில் மூன்று அந்தக்கரணங்கள் மட்டுமே செயற்படும் நிலை கேவல சொப்பனமாம். கேவல சாக்கிரத்தல் இருவகை இந்திரியங்கள் செயற்படும். கேவல சொப்பனத்தில் அவை செயற்படா. (இங்குப் பரசரீரம் கருத்தில் கொள்ளப்படவில்லை.) பரசரீரத்தில் 'பிரகிருதி, புருடன்' என்னும் இரண்டு மட்டுமே தொழிற்படும் நிலை கேவல சுழுத்தியாம். (இங்கும் பிராணன் எண்ணப்படவில்லை.) பரசரீரத்தில் புருடன் ஒன்று மட்டுமே செயற்படும் நிலை கேவல துரியமாம். (இங்கும் பிராணன் எண்ணப்பட வில்லை. ஒரு கருவியும் இன்றி ஆணவ மாத்திரம் இருத்தலே கேவல துரியாதீதம்' என்பது கருத்து.)`,
  },
  {
    id: 2203, tantraId: 8, verseNumber: 2202,
    tamil: `நனவில் நனவு புனலில் வழக்கம்
நனவிற் கனவு நினைத்தல் மறத்தல்
நனவிற் சுழுத்திஉள் நாடல் இலாமை
நனவில் துரியம் அதீதத்து நந்தியே`,
    transliteration: `naṉavil naṉavu puṉalil vaḻakkam
naṉaviṟ kaṉavu niṉaittal maṟattal
naṉaviṟ cuḻuttiuḷ nāṭal ilāmai
naṉavil turiyam atītattu nantiyē`,
    english: `2202: Experiences in the Five States of Consciousness Within
Jagra
Jagra in Jagra
Pertains to Senses;
Svapna in Jagra
Is of thinking and forgetting;
Sushupti in Jagra
Is seeking inward;
Turiya in Jagra
Is abstaining from seeking;
In the state of Turiyatita
Is Nandi verily.`,
    elaborationEnglish: `To vision in dream As in Jagrat, Is Jagrat-in-Dream State; To vision and forget In Dream Is Dream-in-Dream State, To vision and non-vision Is Sushupti-in-Dream State To infer events Is Turiya in Dream State.`,
    elaborationTamil: `சாக்கிரத்தில் சாக்கிரமாவது உயிர் பொறிகளின் வழியாகப் புறத்தே உலாவிப் புலன்களைப் புதிது புதிதாக உணரும் நிலை.
சாக்கிரத்தில் சொப்பனமாவது, புறத்துச் சென்று புதிய காட்சி -களைக் காணாது முன்பு கண்டவற்றைப் பற்றியே நினைந்திருத்தல்.
சாக்கிரத்தில் சுழுத்தியாவது, முன்பு கண்ட காட்சிகளை நினைதலையும் விடுத்துப் பொதுமையின் நிற்றல்.
சாக்கிரத்தில் துரியமாவது, புறப்பொருள்களால் விளைந்தது துன்பமாயின் அதனைப் போக்கவும், இன்பமாயின் அதனைக் காக்கவும் ஆன வழிகளைப் பலவாக எண்ணுதல்.
சாக்கிரத்தில் துரியாதீதமாவது, அவ்வாறு எண்ணுதல் இன்றி, துன்பம், அல்லது இன்பத்திலே மூழ்கித் தன்னை மறத்தல்.`,
  },
  {
    id: 2204, tantraId: 8, verseNumber: 2203,
    tamil: `கனவில் நனவுபோல் காண்டல் நனவாம்
கனவினில் கண்டு மறத்தல் கனவாம்
கனவில் சுழுத்தியும் காணாமை காணல்
அனுமாதி செய்தலில் ஆன துரியமே`,
    transliteration: `kaṉavil naṉavupōl kāṇṭal naṉavām
kaṉaviṉil kaṇṭu maṟattal kaṉavām
kaṉavil cuḻuttiyum kāṇāmai kāṇal
aṉumāti ceytalil āṉa turiyamē`,
    english: `2203: Four Inner States of the Dream State
To vision in dream
As in Jagra,
Is Jagra-in-Dream State;
To vision and forget
In Dream
Is Dream-in-Dream State.
To vision and non-vision
Is Sushupti-in-Dream State
To infer events
Is Turiya in Dream State.`,
    elaborationEnglish: `The four inner states of the dream state are jagrat in-dream state, dream-in-dream state, sushupti-in-dream state and turiya-in-dream state.`,
    elaborationTamil: `(மேல், 'நனவிற் கனவில்லை' என வந்த மந்திரத்தில் சித்தாந்தம் கூறிய நாயனார். இது முதல் மூன்று மந்திரங்களால் சில பூர்வ பக்கம் கூறுகின்றார்.)
கனவு நனவுபோல மிகத் தெளிவாக நிகழ்தல் சொப்பனத்தில் சாக்கிரம். (இதுவே, 'சொப்பனத்தில் சொப்பனம்' என்பது சித்தாந்தம்.)
கனவு தெளிவாக அன்றி, மந்தமாக நிகழ்தல் சொப்பனத்தில் சொப்பனம். (இது வேறன்று என்பது சித்தாந்தம்.)
கனவில் காட்சியாகக் காணாது, கருத்தாக மட்டும் சிலவற்றை உணர்தல் சொப்பனத்தில் சுழுத்தி. அந்த உணர்வும் இன்றி இருத்தல் சொப்பனத்தில் துரியம் (இதனானே, 'உணர்வு கனவில் உண்டாகும் இன்பத்துன்பங்களிலே அது அதுவாக அழுந்துதலே சொப்பனத்தில் துரியாதீதம்' - என்பது பெறப்படும்.)`,
  },
  {
    id: 2205, tantraId: 8, verseNumber: 2204,
    tamil: `சுழுத்தி நனவுஒன்றும் தோன்றாமை தோன்றல்
சுழுத்தி கனவுஅதன் உண்மை சுழுத்தியில்
சுழுத்தி அறிவுஅறி வாலே அழிகை
சுழுத்தித் துரியமாம் சொல்லறும் பாழே`,
    transliteration: `cuḻutti naṉavuoṉṟum tōṉṟāmai tōṉṟal
cuḻutti kaṉavuataṉ uṇmai cuḻuttiyil
cuḻutti aṟivuaṟi vālē aḻikai
cuḻuttit turiyamām collaṟum pāḻē`,
    english: `2204: Sushupti and Its Inner Divisions
Jagra-in-Sushupti
Is to vision it as non-vision;
Dream-in-Sushupti
Is to know it as dream;
Sushupti-in-Sushupti
Is to know that there is no knowledge of it;
Turiya in Sushupti
Is inexplicable Void.`,
    elaborationEnglish: `Of the four inner divisions of sushupti, jagrat-in-sushupti is to vision and not vision at all; dream-in-sushupti is to know it as dream; sushupti-in-sushupti is to have the knowledge of it. The inexplicable void is turiya-in-susuhpti.`,
    elaborationTamil: `சுழுத்தியில் ஒருகால், 'இது நல்ல உறக்கம்' என அதனை உணர்தல் சுழுத்தியில் சாக்கிரம். சுழுத்தியில் 'நாம் நன்கு உறங்குகின்றோம்' எனத் தன்னை உணர்தல் சுழுத்தியில் சொப்பனம். (இவை இரண்டும் நிகழில் சுழுத்தி யில்லையாம் என்பது சித்தாந்தம்.)`,
  },
  {
    id: 2206, tantraId: 8, verseNumber: 2205,
    tamil: `துரிய நனவாம் இதமுணர் போதம்
துரியக் கனவாம் அகமுணர் போதம்
துரியச் சுழுத்தி வியோமம் துரியம்
துரியம் பரமெனத் கோன்றிடும் தானே`,
    transliteration: `turiya naṉavām itamuṇar pōtam
turiyak kaṉavām akamuṇar pōtam
turiyac cuḻutti viyōmam turiyam
turiyam parameṉat kōṉṟiṭum tāṉē`,
    english: `2205: Turiya and Its Inner Divisions7Jagra-in-Turiya
Is (God) Consciousness, external;
Svapna-in-Turiya
Is (God) Consciousness internal;
Sushupti-in-Turiya
Is Void inexplicable;
Turiya-in-Turiya
Is to vision Param Supreme.`,
    elaborationEnglish: ``,
    elaborationTamil: `துரியத்தில் பேருறக்கத்தில் விளைகின்ற மிக்க இன்பத்தினைக் காலத்தொடு ஒட்டி நெடிதுணர்தல் துரியத்தில் சாக்கிரம். அவ்வின்பத்தை உணராது தன்நிலையை உணர்தல் துரியத் தில் சொப்பனம். துரியத்தில் திருவருள் உணர்வு தோன்றல் துரியத்தில் சுழுத்தி. துரியத்தில் திருவருட்கு முதலாகிய சிவத்தை உணர்தல் துரியத் தில் துரியம். (இதனால், சிவத்தில் ஒடுங்கல் துரியத்தில் துரியாதீத மாதல் கொள்ளப்படும்.)
(இவற்றுள், 'முதற்கண் கூறிய நிலையே துரியத்தில் துரியம்' என்பதும், அவ்வின்பத்தில் தோய்ந்து, அதுவேயாய்க் கிடத்தலே துரியத்தில் துரியாதீதம்' என்பதும், 'பிறவெல்லாம் கீழாலவத்தைக் கண் நிகழா' என்பதுமே சித்தாந்தம்.)
ஏகான்ம வாதிகள், 'கீழாலவத்தையில் நிகழும் சுழுத்தியில் சீவன் பிரமமாய்விடும்' எனவும், 'அதனால் அங்கு நிகழ்வது பிரமானந்தமே' எனவும் கூறுவர். இம்மந்திரத்திற் கூறிய பூர்வ பக்கமும் அவர்களது கொள்கையோடு ஓராற்றான் ஒத்துள்ளன்.
இனி 'இங்குக் கூறப்பட்ட துரியம் பரதுரியமே' எனக் கொள்வாரும் உளர்.
துரியாதீத நிலை இங்குக் கூறப்படாமையால், அதில், 'சித் தாந்தத்திற்கு வேறாய்ச் சொல்லப்படுவன இல்லை' என்பதாகின்றது.`,
  },
  {
    id: 2207, tantraId: 8, verseNumber: 2206,
    tamil: `அறிவுஅறி கின்ற அறிவு நனவாம்
அறிவுஅறி யாமை அடையக் கனவாம்
அறிவுஅறி அவ்அறி யாமை சுழுத்தி
அறிவுஅறி வாகும் ஆன துரியமே`,
    transliteration: `aṟivuaṟi kiṉṟa aṟivu naṉavām
aṟivuaṟi yāmai aṭaiyak kaṉavām
aṟivuaṟi avaṟi yāmai cuḻutti
aṟivuaṟi vākum āṉa turiyamē`,
    english: `2206: Jiva-Knowledge in Relation to Para-Knowledge in the
Jiva-knowledge cognising-ceasing is Dream;
Jiva-knowledge cognising,
Yet knowing it not, is Sushupti;
Jiva-knowledge merging in Para-Knowledge
Is Turiya verily.`,
    elaborationTamil: `ஆன்மாத் தத்துவங்களின் இயல்பை அறியுமுகத் தானே தன்னியல்பை அனுமித்தறியும் நிலை சகலத்தில் சுத்த சாக்கிரம். (இதனை, 'ஆன்மரூபம்' என்க.) தத்துவங்களின் இயல்பை உணரும் முகத்தால் அவற்றால் தனக்கு உண்டாகும் பாச அறிவை நீக்கி நிற்கும் நிலை சகலத்தில் சுத்த சொப்பனம். (இதனை, 'தத்துவ சுத்தி' என்க.) பாச அறிவை நீக்கிய ஆன்மாப் பதியறிவை நாடி அது தோன்றாது நிற்கும் நிலை சகலத்தில் சுத்த சுழுத்தி. (இதனை, 'ஆன்ம தரிசனம்' என்க. 'சிவரூபம்' இங்கு உடன் நிகழும்.) பதியறிவை நாடி அதனை அறிந்த ஆன்மா, அந்த அறிவில் தனது அறிவு ஒடுங்கத் தான் தோன்றாது அது வேயாய் நிற்கும் நிலை சகலத்தில் சுத்த துரியமாம். (இதுவே, ஆன்ம சுத்தியும், சிவதரிசனமும், சிவயோக மும் என்க.) இதற்கு மேல் ஆன்மாத் தன்னால் பற்றப்பட்ட சிவம் விளைக்கின்ற ஆனந்தத்தில் மூழ்கிப் பிறிதொன்றையும் அறியாது நிற்றலே சகலத்தில் சுத்த துரியாதீதம் என்பது குறிப்பால் கொள்ளக்கிடந்தது. அதுவே 'ஆன்ம லாபம்' என்க.`,
  },
  {
    id: 2208, tantraId: 8, verseNumber: 2207,
    tamil: `தான் எங்கும் ஆயவன் ஐம்மலம் தான்விட்டு
ஞானம் தனதுரு வாகி நயந்தபின்
தான்எங்கு மாய்நெறி நின்றது தான்விட்டு
மேல்நந்தச் சூக்கம் அவைவண்ணம் மேலிட்டே`,
    transliteration: `tāṉ eṅkum āyavaṉ aimmalam tāṉviṭṭu
ñāṉam taṉaturu vāki nayantapiṉ
tāṉeṅku māyneṟi niṉṟatu tāṉviṭṭu
mēlnantac cūkkam avaivaṇṇam mēliṭṭē`,
    english: `2207: Jiva's Experiences in Turiya State
He (Jiva) then pervasive becomes;
Shedding Malas five,
He takes the Form of Jnana;
Experiencing that,
Abandoning his pervasiveness,
He ascends higher,
The Subtle Form of Pranava (Aum)
To assume.`,
    elaborationTamil: `வியாபகப் பொருளாகிய ஆன்மா, அந்த வியா பகத்தைத் தடுத்து அணுத்தன்மைப் படுத்திய ஆணவாதி பாசம் ஐந்தி னின்றும் நீங்கித் தனது வியாபகத்தைத் தலைப்பட்ட நிலை உண்மைச் சுத்த சாக்கிரம். (இதுவே சீவன் முத்தியாம்.)
சீவன் முத்தியில் மாயையாகிய உடம்பு இருத்தலால், அது வழியாக ஏனைப் பாசங்களின் வாசனைகளும் உளவாம். அவ் வாசனைகள் பெரும்பான்மையும் நீங்கி, அதிகார மலவாசனை நின்ற விடத்து, அனந்தேசுராதி பதங்களில் விருப்பம் உண்டாகும். அவ் வாற்றால் அப்பதங்களில் இருத்தல் உண்மைச் சுத்த சொப்பனம் (இஃது அதிகார முத்தியாம்.)
பின்பு அதிகாரமலம் நீங்கிப்போக மல வாசனை நின்ற விடத்து நிவிர்த்தி முதலிய நான்கு கலைகளையும் உள்ளடக்கிப் பெரு வியாபகமாய் நிற்கின்ற சாந்தி யதீத கலையில் சத்தி தத்துவத்தில் உள்ள புவனங்களில் உள்ள போகங்களை நுகர்வதில் விருப்பம் உண்டாகும். அவ்வாற்றால் அவற்றை அடைந்திருத்தல் உண்மைச் சுத்த சுழுத்தி. (இது போக முத்தியாம்.)
போக மல வாசனை நீங்கி, இலய மல வாசனை நின்றவிடத்து, அச்சாந்தியதீத கலையில் உள்ள சிவதத்துவ புவனங்களில் உள்ள போகங்களை நுகர்வதில் விருப்பம் உண்டாகும். அவ்வாற்றால் அவற்றை அடைந்திருத்தல் உண்மைச் சுத்த துரியம். (இஃது இலய முத்தியாகும்)
(சாந்தி கலையில் சாதாக்கிய தத்துவ புவனத்தை அடைந் தவர்களும், சாந்தியதீத கலையில் உள்ள புவனங்களை அடைந் தவர்களும், 'அணு சதாசிவர்கள்' எனப்படுவர். சுத்த வித்தை, ஈசுரம் ஆகிய தத்துவ புவனங்களை அடைந்தவர்கள் 'வித்தையேசுரர்கள்' என்றும், 'மந்திர மகேசுரர்கள்' என்றும் இருவகையினராய் இருப்பர்.)
(இலய முத்தி 'உண்மைச் சுத்த துரியம்' என்றதனானே, ஆன்மா அனைத்து மல வாசனைகளும் சிறிதும் இன்றி நீங்கப் பரம சிவனோடு இரண்டறக் கலக்கும் சாயுசச்ச நிலை உண்மைச் சுத்த துரியாதீதம் ஆதல் விளங்கும்.)
இவையெல்லாம் பராவத்தைகளாம்.)`,
  },
  {
    id: 2209, tantraId: 8, verseNumber: 2208,
    tamil: `ஐஐந்தும் ஆறும்ஓர் ஐந்தும் நனாவினில்
எய்யும் நனவு கனவு சுழுத்தியாம்
மெய்யும்பின் சூக்கமும் மெய்ப்பகுதி மாயை
ஐயமும் தான்அவன் அத்துரி யத்தனே`,
    transliteration: `aiaintum āṟumōr aintum naṉāviṉil
eyyum naṉavu kaṉavu cuḻuttiyām
meyyumpiṉ cūkkamum meyppakuti māyai
aiyamum tāṉavaṉ atturi yattaṉē`,
    english: `2208: Tattvas in the Inner Divisions of Turiya State
Thirty and Six are Tattvas
In Jagra-in-Turiya;
In Svapna in that Turiya;
And in Sushupti-in-Turiya
In Turiya-in-Turiya
The Body Gross and the Body Subtle
To the Suddha Maya belong;
He who that Turiya-in-Turiya State attains
Master, indeed, Becomes.`,
    elaborationEnglish: ``,
    elaborationTamil: `சகலசாக்கிரத்தில் முப்பத்தாறு கருவிகளும் குறைவின்றிச் செயற்படும். அந்தச் சாக்கிரத்திற்குப் பின்னர் அதிலே, 'சொப்பனம், சுழுத்தி' என்பவையும் நிகழும். அவைகளில் இளைத்து மடங்கும் கருவிகள் அசுத்த மாயையின் காரியங்களாம். அவை காலம், நியதி முதலியன. அவை செயற்படுதல் சிவதத்துவங்கள் செலுத்துதலினாலேயாகலின், 'அவை செயற்படா. எனவே, சிவ தத்துவங்களும்செயற்படாமை பெறப்பட்டது. சிவதத்துவங்கள் ஐந்தில் சுத்த வித்தை, ஈசுரம், சாதாக்கியம், சத்தி என்பவை முறையே ஒவ்வொன்றாகக் குறைந்து கொண்டே போவதால், சகலத்தில் சொப்பனம், சுழுத்தி, துரியம், துரியாதீதம் என்பவை நிகழும் என்க. 'உளனோ, இலனோ' - என்னும் ஐயம் நிகழுமாறு உயிர்ப்பின்றிக் கிடப்பது, அதற்குமுன் துரியநிலையில் இருந்த அந்த ஆன்மாவேயாம். (எனவே, விழிப்பு நிலையிலே உயிர்ப்பின்றி மூர்ச்சித்துக் கிடத்தலே சகலத்தில் துரியாதீத மாயிற்று.)`,
  },
  {
    id: 2210, tantraId: 8, verseNumber: 2209,
    tamil: `ஈதென்று அறிந்திலன் இத்தனை காலமும்
ஈதென்று அறிந்தபின் ஏதும் அறிந்திலேன்
ஈதென்று அறியும் அறிவை அறிந்தபின்
ஈதென்று அறியும் இயல்புடை யோனே`,
    transliteration: `īteṉṟu aṟintilaṉ ittaṉai kālamum
īteṉṟu aṟintapiṉ ētum aṟintilēṉ
īteṉṟu aṟiyum aṟivai aṟintapiṉ
īteṉṟu aṟiyum iyalpuṭai yōṉē`,
    english: `2209: New Knowledge
This I knew not,
All these days;
This when I know,
Nothing else I knew;
When I knew,
This the Truth
Then I Knew I am It.`,
    elaborationTamil: `(சுருதியும், குரு மொழியும் ''ஒன்று அவன்தானே'' என்றபடி,* 'தன்னோடு ஒப்பவைத்து எண்ணுதற்கு மற்றொரு பொருள் இன்றித் தான்ஒன்றேயாய தனிமுதற் பொருள் ஒன்று உண்டு' என வலியுறுத்திக் கூறுகின்ற அப்பொருளை) மத்தியாலவத்தை கீழா லவத்தைகளில் மட்டுமே அகப்பட்டு உழன்ற இவ்வளவு காலமும், 'இது' என்று நான் உணரவில்லை (யோகாவத்தையை அடைந்த பொழுது அதனைச் சிறிதே உணர்ந்தேன்.) நின்மலாவத்தையை அடைந்தபின் அதனைத் தெளிவாக உணர்ந்தேன். அதனை அவ் வாறுணர்ந்த பின் பிறிதொன்றையும் அரிய முயல்கின்றிலேன். ('அதனையே அறிந்து நின்றேன்' என்பதாம்.) அவ்வாறு அதனை உணரும் உணர்வை எய்திய பின்புதான் நான் மெய்யுணர் வுடையேனாயினேன்.`,
  },
  {
    id: 2211, tantraId: 8, verseNumber: 2210,
    tamil: `உயிர்க்குஉயி ராகி உருவாய் அருவாய்
அயல்புணர் வாகி அறிவாய்ச் செறிவாய்
நயப்புறு சத்தியும் நாதன் உலகாதி
இயற்பின்றி எல்லாம் இருண்மூட மாமே`,
    transliteration: `uyirkkuuyi rāki uruvāy aruvāy
ayalpuṇar vāki aṟivāyc ceṟivāy
nayappuṟu cattiyum nātaṉ ulakāti
iyaṟpiṉṟi ellām iruṇmūṭa māmē`,
    english: `2210: Immanence of Sakti and Siva
As Life of Life,
As Form and Formless,
As Jiva-Sentience and Knowledge-Divine
All pervasive, He stands;
If Sakti and Siva
In world immanent are not,
Verily, verily, all is inert darkness,
In ignorance entire steeped.`,
    elaborationTamil: `உலகிற்கு முதல்வனாகிய இறைவன் அறிவுடைப் பொருளாகிய உயிர்களில் அவற்றுக்கு உயிராகியும், அறிவில்லாத உருவமும், அருவமும் ஆகிய பொருள்களில் அவையேயாகியும் இவ்வாறு கலப்பினால் ஒன்றாயும், பொருள் தன்மையால் அவை யனைத்தினும் தான் வேறாவதோர் திறம் உடையனாயும், உயிர்களின் அறிவு ஒன்றை அறியுமிடத்துத் தானும் அவ்வாறு அப்பொருளை அறிகின்ற அறிவாய் உடனாயும் 'சத்தியும், சிவமும்' என்னும் இரு திறத்தால் இயக்காவிடின் உயிர்கள் முழு மூடங்களாயும், உயிரல் பொருள்கள் சூனியமாயும் ஒழிவனவாம்.`,
  },
  {
    id: 2212, tantraId: 8, verseNumber: 2211,
    tamil: `சத்தி இராகத்தில் தான்நல் உயிராகி
ஒத்துறி பாச மலம்ஐந்தோடு ஆறாறு
தத்துவ பேதம் சமைத்துக் கருவியும்
வைத்தனன் ஈசன் மலம்அறு மாறே`,
    transliteration: `catti irākattil tāṉnal uyirāki
ottuṟi pāca malamaintōṭu āṟāṟu
tattuva pētam camaittuk karuviyum
vaittaṉaṉ īcaṉ malamaṟu māṟē`,
    english: `2211: Raison D'Etre of Creation
In endearment wondrous
The Lord moved Sakti into Creative activity;
And to primordial Pasas five,
Conjoined Tattvas thirty and six
And fashioned the body organs too,
--That your Malas sundered be.`,
    elaborationTamil: `சிவன், 'இச்சை, ஞானம், கிரியை' என்னும் தனது மூன்று சத்திகளில், 'உயிர்களை உய்விக்க வேண்டும்' என விரும்பும் இச்சா சத்தியினால் உயிர்களில் எல்லாம் தான் நல் உயிராய்க் கலந்து, அநாதியே உயிர்களில் தன்னைப் போலவே பொருந்தியுள்ள பாசம், 'அஃது ஒன்றே' யாகாது 'ஐந்து' என்னும் படி முதல் மலத்தொடு நான்கு மலங்களைக் கூட்டியதனானே அம்முதல் மலம் முற்றிலும் அற் றொழிதற் பொருட்டுத் தத்துவ வகை முப்பத்தாறினையும் உண்டாக்கி, அம்முப்பத்தாறின் கூறுகளாக மற்றும் அறுபத்தாறு கருவிகளையும் தோற்றுவிக்து வைத்தான்.`,
  },
  {
    id: 2213, tantraId: 8, verseNumber: 2212,
    tamil: `சாக்கிரா தீதத்தில் ஆணவம் தன்னுண்மை
சாக்கிரா தீதம் துரியத்தில் தானுறச்
சாக்கிரா தீதத்தில் ஆணவம் தான்விடாச்
சாக்கிரா தீதம் பரன்உண்மை தங்குமே`,
    transliteration: `cākkirā tītattil āṇavam taṉṉuṇmai
cākkirā tītam turiyattil tāṉuṟac
cākkirā tītattil āṇavam tāṉviṭāc
cākkirā tītam paraṉuṇmai taṅkumē`,
    english: `2212: Jagrat-atita State Leads to Turiya-In-Turiya (Para Turiya)
In Jagrat-atita State
Anava (Egoity), forsooth, is;
Even when the Soul enters
The Turiya state in Jagrat-atita (Turiya-in-Turiya State)
Anava still is of Jagrat-atita state;
Jagrat-atita is,
Where Truth of Para is.`,
    elaborationTamil: `சகல சாக்கிரத்தில் சாக்கிரம் முதலியன நிகழுங் கால் இறுதியில் நிகழும் துரியாதீதத்தில் ஆன்மாத் தன்னையும், பிறிதை -யும் உணர்தல் இன்றி, ஆணவத்தால் விளையும் பேரிடரிலே மூழ்கி யிருக்கும். இது 'தன்னுண்மை' எனப்படும். (இந்நிலை அநாதி கேவலத்தொடு ஒத்ததாகும்.)
நின்மல சாக்கிரத்தில் நிகழும் துரியாதீதத்தில் ஆணவம் இன்மையான், அதில் ஆன்மாச் சிவனால் தரப்படும் பேரின்பத்தில் மூழ்கித் தன்னையும் அறியா நிலையில் இருக்கும். (இஃது ஆன்மா இறுதியில் அடையும் சாயுச்ச நிலையோடு ஒத்ததாகும். இதுவே முன்பு ஆணவத்தோடு அத்துவிதமாய் நின்றதுபோலப் பின்பு மெய்ஞ்ஞானத் தாணுவினோடு அத்துவிதமாய் நிற்கும் நிலை.)
இங்குக் கூறிய இருவகைச் சாக்கிரத்திலும் துரியாதீதத்திற்கு முன்னாதல், பின்னாதல் நிகழும் துரியத்தில் ஆன்மாத் தனக்கு உளவாகும் இன்பத் துன்பங்களை அறிவதாய் இருக்கும்.`,
  },
  {
    id: 2214, tantraId: 8, verseNumber: 2213,
    tamil: `மலக்கலப் பாலே மறைந்தது சத்தி
மலக்கலப் பாலே மறைந்தது ஞானம்
மலக்கலப் பாலே மறைந்தனன் தாணு
மலக்கலப்பு அற்றால் மதியொளி யாமே`,
    transliteration: `malakkalap pālē maṟaintatu catti
malakkalap pālē maṟaintatu ñāṉam
malakkalap pālē maṟaintaṉaṉ tāṇu
malakkalappu aṟṟāl matiyoḷi yāmē`,
    english: `2213: Mala-Contamination is Root of All Evil
By Mala-Contamination
Was Sakti obscured;
By Mala-Contamination
Was Jnana obscured;
By Mala-Contamination
Was Param obscured;
He who is freed
Of Mala-Contamination
Is verily the Enlightened One.`,
    elaborationTamil: `(இதன் பொருள் வெளிப்படை.)`,
  },
  {
    id: 2215, tantraId: 8, verseNumber: 2214,
    tamil: `திகைக்கின்ற சிந்தையுள் சிங்கங்கள் மூன்று
நகைக்கின்ற நெஞ்சுள் நரிக்குட்டி நான்கு
வகைக்கின்ற நெஞ்சினுள் ஆனைக்கன்று ஐந்து
பகைக்கின்ற நெஞ்சுக்குப் பாலிரண் டாமே`,
    transliteration: `tikaikkiṉṟa cintaiyuḷ ciṅkaṅkaḷ mūṉṟu
nakaikkiṉṟa neñcuḷ narikkuṭṭi nāṉku
vakaikkiṉṟa neñciṉuḷ āṉaikkaṉṟu aintu
pakaikkiṉṟa neñcukkup pāliraṇ ṭāmē`,
    english: `2214: Enemies of Thought For God
In their bewildered thoughts
Are the lions three (lust, anger and ignorance);
In their bouncing thoughts
Are the jackals four (mind, intellect, will and egoity)
In their sensory thoughts
Are the elephants five (taste, sight, touch, sound,
smell)
These the foes (internal and external)
Of the contending mind.`,
    elaborationTamil: `கீழாலவத்தைச் சுழுத்தியில் காட்சி எதனையும் காணுதல் இன்றித் தெளிவில்லாதிருக்கின்ற ஆன்ம அறிவில், சிங்கங்கள் போன்ற கொடிய குணங்கள் மூன்று விளங்கி நிற்கும். (அவை, 'காமம், வெகுளி, மயக்கம்' - என்பன. 'இவற்றின் விரியே பஞ்சக்கிலேசம்' என்பர். பஞ்சக்கிலேசமாவன, 'அவிச்சை, அகங்காரம், அவா, ஆசை, கோபம்' - என்பன. இவை, கொடுமை மிகுதி பற்றிச் சிங்கங்களோடு உவமிக்கப்பட்டன.)
அச் சுழுத்தியினின்றும் மேல் ஏறிச் சொப்பனத்தை அடைந்த ஆன்ம அறிவில் நான்கு நரிக்குட்டிகள் போன்ற சூழ்ச்சி வல்ல நான்கு கருவிகள் விளங்கி நிற்கும். (அவை, 'சித்தம், புத்தி, அகங்காரம், மனம்' என்பன, இவை சூழ்ச்சிக் கருவிகள் ஆதலின், நரிக் குட்டிகளோடு உவமிக்கப்பட்டன. 'நரிகள் சூழ்ச்சி வல்ல பிராணிகள்' என்பர்.
அச்சொப்பனத்தினின்றும் மேல் ஏறிச்சாக்கிரத்தை அடைந்த ஆன்ம அறிவினுள் பின்பு மதங்கொள்ளும் ஐந்து ஆனைக்கன்றுகள் போன்ற ஐந்து கருவிகள் விளங்கி நிற்கும். (அவை, செவி முதலிய ஞானேந்திரியங்கள். மத்தியாலவத்தைச் சாக்கிரத்தில் இவை வளர்ந்து மதம் மிக்க யானைகள் போல் ஆய்விடும்.)
(கீழாலவத்தையை விட்டு, மத்தியாலவத்தையை அடைந்த ஆன்ம அறிவு, மேற்கூறிய யானைக் கன்றுகள் வளர்ந்து, மதம் மிக்கு, ஒன்றோடொன்று மாறுபட்டு நிற்றற்கு இடமாய், இரு நிலைகளை யுடையதாம்; ஒன்று, அவ் யானைகளால் ஈர்ப்புண்டல். மற்றொன்று, அவற்றை அடக்கி ஒடுக்குதல்.)`,
  },
  {
    id: 2216, tantraId: 8, verseNumber: 2215,
    tamil: `கதறு பதினெட்டுக் கண்களும் போகச்
சிதறி எழுந்திடுஞ் சிந்தையை நீரும்
விதறு படாமுன்னம் மெய்வழி நின்றால்
அதிர வருவதோர் ஆனையும் ஆமே`,
    transliteration: `kataṟu patiṉeṭṭuk kaṇkaḷum pōkac
citaṟi eḻuntiṭuñ cintaiyai nīrum
vitaṟu paṭāmuṉṉam meyvaḻi niṉṟāl
atira varuvatōr āṉaiyum āmē`,
    english: `2215: Give Up Distractions and Take to the True Way
With streaming eyes eighteen
Your thoughts in distraction wander;
Before you tremble in death,
Take to the True Way;
You shall indeed meet
The mighty Lord of your soul.`,
    elaborationEnglish: `. The five sensoria, the five motoria, the five tanmatras, and the three — these eight distract you from God. Give up distractions and take to the true way.`,
    elaborationTamil: `துன்பத்தால் அலறிக் கொண்டு, ஒரு வழிபடாது பதினெட்டு வழிகளில் போவதற்குப் பலமுகமாய் எழுகின்ற மனத்தை, நீவிர், நும் வாழ்நாள் முடிவதற்கு முன்னே மெய்ந்நெறியில் நிறுத்தினால், முன் மந்திரத்தில் கூறிய அந்த ஆனைகள் ஐந்தும் நடுங்கும்படி ஒப்பற்ற ஒரு பெரிய யானை உங்கள் அருகில் வந்து உங்களை எடுத்துச் செல்லும்.`,
  },
  {
    id: 2217, tantraId: 8, verseNumber: 2216,
    tamil: `நனவகத் தேயொரு நாலைந்தும் வீடக்
கனவகத் தேஉள் கரணங்க ளோடு
முனவகத் தேநின்று உதறியுட் புக்கு
நினைவகத்து இன்றிச் சுழுத்திநின் றானே`,
    transliteration: `naṉavakat tēyoru nālaintum vīṭak
kaṉavakat tēuḷ karaṇaṅka ḷōṭu
muṉavakat tēniṉṟu utaṟiyuṭ pukku
niṉaivakattu iṉṟic cuḻuttiniṉ ṟāṉē`,
    english: `2216: Jiva Devoid of Thought in Sushupti
Of the Tattvas in Waking State
Four times five are behind left;
The Tattvas four that Antahkaranas form
In Dream State are;
--These you shake off
And into yourself enter;
Then thoughts devoid
The Soul in Sushupti Stands.`,
    elaborationTamil: `(கனவிலும் பிராணாதி வாயுக்கள் பத்தும் செயற் படுதலால், அந்தக் கரணங்களும் செயற்படவே செய்யும் - அதனால்,) நனவிற்போலக் கனவிலும், மேல் 'ஆனைகள் ஐந்து' எனப்பட்ட ஞானேந்திரியப் புலனகள் ஐந்தோடு, கன்மேந்திரியப் புலன்கள் ஐந்தும், இன்னும் பிராணாதி வாயுக்கள் பத்தும் கூடி ஆன்மா அமைதி யுற்றிராதபடி தொல்லையுறவே செய்யும். இந்நிலையில் நிற்கும் ஆன்மா, ஒருமுகப்பட்ட சிந்தனையை விரும்புதலால், புலன்களை யெல்லாம் உதறித்தள்ளி, இருதயத்துட்புகுந்து சுழுத்தியில் நிற்கும்,`,
  },
  {
    id: 2218, tantraId: 8, verseNumber: 2217,
    tamil: `நின்றவன் ஆசான் நிகழ்துரி யத்தனாய்
ஒன்றி உலகின் நியமாதிகள் உற்றுச்
சென்று துரியாதீ தத்தே சிலகாலம்
நின்று பரனாய் நின்மல னாமே`,
    transliteration: `niṉṟavaṉ ācāṉ nikaḻturi yattaṉāy
oṉṟi ulakiṉ niyamātikaḷ uṟṟuc
ceṉṟu turiyātī tattē cilakālam
niṉṟu paraṉāy niṉmala ṉāmē`,
    english: `2217: Evolution of Jiva to Para State
The Soul who thus stood
Has verily a Master become;
He enters the Turiya State
And remains in the Eight-fold Yoga;
He then attains Turiyatita State;
And further a while after
He becomes Para the Pure.`,
    elaborationTamil: `மேற்கூறிய சுழுத்தியில் அமைதியை உற்றுணர்ந் தவன், அஃது அறியாமையாகிய இருளால் விளையும் அமைதியே யாதலைத் தெரிந்து, அவ்விருள் நீங்கி, ஒளியில் விளையும் அமைதியை அடையவிரும்பி, ஆசானிடத்துச் சென்று அவன் உணர்த் தியவாறே, உலகியலிற்றானே இயம நியமாதிகளை மேற்கொள்ளும் யோகத்தில் பொருந்தி நின்று, அவ்யோகத்தில் துரியமாகிய தியானத் -தில் முதிர்ந்தவனாய், அதற்கு மேற்சென்று, அதன்கண் துரியாதீத மாகிய சமாதியில் சில காலம் நின்று, அதன் பின் பராவத்தையாகிய ஞானாவத்தைகளை அடைந்து, அதனால் பாசங்கள் முற்றிலும் நீங்கப் பெற்று முத்தனாவான்.`,
  },
  {
    id: 2219, tantraId: 8, verseNumber: 2218,
    tamil: `ஆனஅவ் ஈசன் அதீதத்தில் வித்தையாத்
தான்உலகு உண்டு சதாசிவ மாசத்தி
மேனிகள் ஐந்தும்போல் விட்டுச் சிவமாகி
மோனம் அடைந்தொளி மூலத் னாமே`,
    transliteration: `āṉaav īcaṉ atītattil vittaiyāt
tāṉulaku uṇṭu catāciva mācatti
mēṉikaḷ aintumpōl viṭṭuc civamāki
mōṉam aṭaintoḷi mūlat ṉāmē`,
    english: `2218: Further Evolution to Primal Light
He who thus Isa Became
Reaching Turiyatita State,
As Pure Jnana comprehends worlds all;
Then He further attains the Five Forms,
Sadasiva, Mahesvara, Rudra, Hari and Brahma;
Having experienced those stages,
Jiva becomes Siva;
Then, further attaining Mauna (Divine Silentless) State,
He merges in the Primal Light.`,
    elaborationTamil: `பராவத்தை உண்மைச் சுத்தாவத்தையே யாயினும் துரியாதீதம், துரியம் ஒழிந்த மற்றை மூன்றாகிய சிவன் முத்தி, அதிகார முத்தி, போகமுத்திகளில் ஆன்மாஉலகபோகத்தை நுகரும். ஏனெனில், சுழுத்தி சொப்பனங்களில், தோற்ற முறையில் சாதாக்கியம் முதல் ஐந்து தத்துவ உடம்புகள் இருத்தலாலும் சாக்கிரத்தில் மாயா உடம்பு இருத்தலாலும் அவ்வாறு அதுகாறும் போகத்தை நுகர்ந்த ஆன்மா, இலயமுத்தியல் சத்திதத்துவத்தைக் கடந்து, சிவதத்துவத்தில் தடத்த சிவமாய்ப் புறப் பொருளுணர்ச்சி யின்றிச் சிவ உணர்வே மிக்கிருக்கும். அந்நிலையில் சூக்கும வாக்கை அது பற்றி நிற்கும். ஆகவே, பர துரியாதீதத்தை அடைந்த பொழுதுதான் ஆன்மாச் சிவஞானம் ஒன்றையன்றிப் பிறிதொரு பற்றும் இல்லாமல், சிவத்தை முழுமையாக அனுபவிக்கும்.`,
  },
  {
    id: 2220, tantraId: 8, verseNumber: 2219,
    tamil: `மண்டலம் மூன்றினுள் மாயநன் நாடனைக்
கண்டுகொண்டு உள்ளே கருதிக் கழிகின்ற
விண்டவர் தாமரை மேலொன்றும் கீழாக
அண்டமும் தானாய் அகத்தினுள் ஆமே`,
    transliteration: `maṇṭalam mūṉṟiṉuḷ māyanaṉ nāṭaṉaik
kaṇṭukoṇṭu uḷḷē karutik kaḻikiṉṟa
viṇṭavar tāmarai mēloṉṟum kīḻāka
aṇṭamum tāṉāy akattiṉuḷ āmē`,
    english: `2219: Lord is Within
He is the Lord of Maya Land,
Where the Spheres Three within are;
He is the One whom I see within
And pine incessant for;
He is the Lotus that blooms in the cranium,
With its stalk stemming deep in my heart.`,
    elaborationEnglish: `He is the Lord of maya land with the three spheres — sun, moon and fire within. He is immanent in me. The Lord is also the lotus that blooms in the cranium with its stem, deep in my heart. He is the One whom I pine for.`,
    elaborationTamil: `அண்டத்தில் 'தீ, ஞாயிறு, திங்கள்' என்னும் மூன்று மண்டலங்களில் விளங்கும் முதல்வனைப் பிண்டத்திலே அம்மூன்று மண்டலங்களில் வைத்துக் கண்டு மேல் எழுதற்கு ஏதுவாய், உடம்பிற்குள்ளே மேல் ஒன்றும், கீழ் ஒன்றுமாக நாளத்தையும் உடையவாய், நன்கு மலர்ந்த தாமரை மலர்கள் உள்ளன.`,
  },
  {
    id: 2221, tantraId: 8, verseNumber: 2220,
    tamil: `போதறி யாது புலம்பின புள்ளினம்
மாது அறி யாவகை நின்று மயங்கின
வேதுஅறி யாவணம் நின்றனன் எம்இறை
சூதறி வாருச்சி சூடிநின் றாரே`,
    transliteration: `pōtaṟi yātu pulampiṉa puḷḷiṉam
mātu aṟi yāvakai niṉṟu mayaṅkiṉa
vētuaṟi yāvaṇam niṉṟaṉaṉ emiṟai
cūtaṟi vārucci cūṭiniṉ ṟārē`,
    english: `2220: The Dawn of Light Within in Yoga
The birds (Malas) shrilled
Unaware of the shimmering dawn;
Bewildered were they,
Their mother (Sakti) unrecognising;
Beyond Vedas stood He my Lord;
They who knew the Mystic Way (of Yoga)
Reached to Him inside their very head.`,
    elaborationEnglish: ``,
    elaborationTamil: `விடியல் வாராத பொழுதும் வந்ததாகக் கருதி நள்ளிரவிலே ஆரவாரித்த சில பறவைகளைப் போன்ற உயிர்கள், திருவருள் தம்மை நோக்குதல் இல்லாத நிலையிலே நின்று, பொய்யை 'மெய்' எனக் கொண்டு மயங்குகின்றன. ஆதனால், எங்கள் இறைவனாகிய சிவனும் செம்பைப் பொன்னாக்கும் வித்தையை அறிந்தும் அறியாதவன் போல இருக்கின்றான். இச் சூழ்ச்சியை அறிந்த பெரியோர்கள், நீராதார யோகத்தாலும், சுத்த துரியத்தாலும் அவனது அருளில் தோய்ந்திருப்பர்.`,
  },
  {
    id: 2222, tantraId: 8, verseNumber: 2221,
    tamil: `கருத்தறிந்து ஒன்பது கண்டமும் ஆங்கே
பொருந்தறிந் தேன்புவ னாபதி நாடித்
திருத்தறிந் தேன்மிகு தேவர் பிரானை
பருத்தறிந் தேன்மனம் மன்னிநின் றேனே`,
    transliteration: `karuttaṟintu oṉpatu kaṇṭamum āṅkē
poruntaṟin tēṉpuva ṉāpati nāṭit
tiruttaṟin tēṉmiku tēvar pirāṉai
paruttaṟin tēṉmaṉam maṉṉiniṉ ṟēṉē`,
    english: `2221: I Saw Him Within In the Nine Centres
In contemplation deep I sought
The Lord of worlds all,
In the Nine Centres within;
Distinct I saw Him,
He, the Lord of Celestials all;
Intense I sought Him,
And He in my thoughts unfailing stood.`,
    elaborationTamil: `(சுருதி உத்தி அனுபவங்களால்) அறிய வேண்டு -வதை அறிந்து, அதனால், 'உலக முதல்வன் யாவன்' என ஆராய்ந்து, 'அம்முதல்வன் சிவபிரானே' என நான் நன்குணர்ந்தேன். பின்பு அவனை என்பால் வருவிக்கும் வழியறிந்து வருவித்தேன். அவன் அவ்வாறே வந்து என் மனத்தில் நிலையாக நின்றுவிட்டான்.`,
  },
  {
    id: 2223, tantraId: 8, verseNumber: 2222,
    tamil: `ஆன விளக்கொளி தூண்டும் அவன் என்னத்
தான விளக்கொளி யாம்மூல சாதனத்து
ஆன விதிமூலத் தானத்தில் அவ்விளக்கு
ஏனை மதிமண்ட லம்கொண்டு எரியுமே`,
    transliteration: `āṉa viḷakkoḷi tūṇṭum avaṉ eṉṉat
tāṉa viḷakkoḷi yāmmūla cātaṉattu
āṉa vitimūlat tāṉattil avviḷakku
ēṉai matimaṇṭa lamkoṇṭu eriyumē`,
    english: `2222: Kundalini Yoga Experience
As one that kindles the lamp's flame,
So do you,
The Lamp's Flame in Muladhara kindle;
That Lamp in Muladhara lighted,
Encompassing the Sphere of Moon, glows.`,
    elaborationTamil: `ஓரிடத்தில் ஏற்றி வைக்கப்பட்ட விளக்கு மற்றை யிடங்களிலும் வியாபித்து நிற்றல் போல, மூலாதாரமாகிய இடத்தில் உள்ள அந்த விளக்கினை அதனை ஏற்ற வேண்டிய முறையை யறிந்து அவ்விடத்திற்றானே மேலே நிலாமண்டலங்காறும் உள்ள இடங் -களில் வியாபிக்கும்படி, இடையே அணைந்துவிடாதபடி எரியுங்கள்.`,
  },
  {
    id: 2224, tantraId: 8, verseNumber: 2223,
    tamil: `உள்நாடும் ஐவர்க்கு மண்டை ஓதுங்கிய
விண்நாட நின்ற வெளியை வினவுறில்
அண்ணாந்து பார்த்துஐவர் கூடிய சந்தியில்
கண்நாடி காணும் கருத்ததுஎன் றானே`,
    transliteration: `uḷnāṭum aivarkku maṇṭai ōtuṅkiya
viṇnāṭa niṉṟa veḷiyai viṉavuṟil
aṇṇāntu pārttuaivar kūṭiya cantiyil
kaṇnāṭi kāṇum karuttatueṉ ṟāṉē`,
    english: `2223: God is Inward Where the Five Sense Controlled Meet
If you ask,
How the Heavenly Space within the cranium is,
Where the inward looking Five abide,
Verily it is,
Unto gazing upward into a mirror
(Seeing the self-reflected in crystal purity)
At a junction
Where the Five, in control, meet.`,
    elaborationTamil: `(கண் முதலியனபோல வெளியிலே கண்டறியப் படாமல்) 'உள்ளே கருதியறியப்படுகின்ற ஐம்புல ஆசைகளின் களியாட்டம் ஒழிதற் பொருட்டு யோகாவத்தையை நிகழ்த்துதற்குரிய இடங்கள் யாவை என ஆராயின், இருதயத்தினின்றும கீழே நோக்காமல், மேலே நோக்கினால், அந்த ஐம்புல ஆசைகளும் ஒருங்கு கூடி வந்து ஒடுங்கும் இடம் ஒன்று உண்டு. அந்த இடத்திலே நின்று, மேலும் ஆராய்க. அதுவே சிவனைப் புலப்படக் காணும் வழி' என்று எம் ஆசிரியர் நந்திபெருமான் எங்கட்கு அறிவுறுத்தார்.`,
  },
  {
    id: 2225, tantraId: 8, verseNumber: 2224,
    tamil: `அறியாத வற்றை அறிவான் அறிவான்
அறிவான் அறியாதான் தன்னறிவு ஆகான்
அறியா தவத்தை அறிவானைக் கூட்டி
அறியாது அறிவானை யார்அறிவாரே`,
    transliteration: `aṟiyāta vaṟṟai aṟivāṉ aṟivāṉ
aṟivāṉ aṟiyātāṉ taṉṉaṟivu ākāṉ
aṟiyā tavattai aṟivāṉaik kūṭṭi
aṟiyātu aṟivāṉai yāraṟivārē`,
    english: `2224: Lord is the Knower; He makes the Jiva Experience
the Five States of Awareness
The knower he is,
Who things unknown knows;
The knower,
Who the Self knows not,
Is knower none;
The Jiva the Five Avastas knows not;
He, Lord, makes him know
To none beknown;
Who indeed does Him know?`,
    elaborationTamil: `அறிவில்லாத சடங்களாகிய பாசங்களை அப்பாச அறிவினால் அறிகின்ற ஆன்மா அந்தப் பாச அறிவைக் கொண்டு அறியவாராத பதி, அப்பாசங்களின் நீங்கியவழியும் பசு அறிவாலும் அறியவாரான். ஆகவே, அறிவில்லாத சடங்களாகிய பாசங்களையும், அறிவுடைய சித்தாகிய ஆன்மாவையும் ஒன்று கூட்டி அவற்றின் செயற்பாடுகளை அறியாதறிபவனாகிய பதியை அறியவல்லார் யாவர்? (ஒருவரும் இல்லை.)`,
  },
  {
    id: 2226, tantraId: 8, verseNumber: 2225,
    tamil: `துரிய தரிசனம் சொற்றோம் வியோமம்
அரியன தூடணம் அந்தண வாதி
பெரியன கால பரம்பின் துரியம்
அரிய அதீதம் அதீதத்த தாமே`,
    transliteration: `turiya taricaṉam coṟṟōm viyōmam
ariyaṉa tūṭaṇam antaṇa vāti
periyaṉa kāla parampiṉ turiyam
ariya atītam atītatta tāmē`,
    english: `2225: Turiya in Turiya is Para Turiya; Beyond is Turiyatita
We thus far spoke of;
The Void of Turiya State
Is state rare;
Unimportant indeed,
Are the states Jagra and the rest;
Great, great, by far
Is the Timeless Para Turiya;
Transcending it is Turiyatita;
Rarer even far that State is.`,
    elaborationTamil: `'பரவெளி' எனப்படுகின்ற திருவருள் வழி நிகழ் கின்ற நின்மலாவத்தைகளில், 'பேருறக்கம்' என்னும் நிலையை அடைதலையே சிறந்ததாகக் கூறினோம். அதற்குக் கீழ் உள்ள நனவு, கனவு, உறக்கம், என்பவைகளும் எல்லார்க்கும் எளியன அல்ல. எனினும் நின்மலாவத்தையும் காலத்தொடு பட்டு நிகழ்வனவாகலின் அவை கழித்தற்குரியனவே. காலத்தைக் கடந்து எல்லையற்று நிகழ்வன பராவத்தைகள். அவைகளில் ஈற்றில் உள்ளது துரியம். அரிதாகிய, துரியத்தையும் கடந்த நிலை துரியா தீத நிலையாகும்.`,
  },
  {
    id: 2227, tantraId: 8, verseNumber: 2226,
    tamil: `மாயையிற் சேதனன் மன்னும் பகுதியோன்
மாயையின் மற்றது நீவுதல் மாயையாம்
கேவல மாகும் சகலமா யோனியுள்
தோயும் மனிதர் துரியத்துள் சீவனே`,
    transliteration: `māyaiyiṟ cētaṉaṉ maṉṉum pakutiyōṉ
māyaiyiṉ maṟṟatu nīvutal māyaiyām
kēvala mākum cakalamā yōṉiyuḷ
tōyum maṉitar turiyattuḷ cīvaṉē`,
    english: `2226: Seek Para Turiya and Reach Siva's State
The World of Maya (Prakriti)
Belongs to Jiva;
To leave that Maya
Is to reach Kevala Maya State;
To be born again and again
As diverse life forms,
Is the State--Sakala;
In Para Turiya is Siva State.`,
    elaborationTamil: `அசுத்த மாயையால், ஆணவ மலம் காரணமாக முன்பு சடம் போலக் கிடந்த உயிர் சித்துத் தன்மையை உடையதாம். (அஃதாவது, 'செயற்படாதே கிடந்த, அறிவு இச்சை செயல்கள் செயற்படத் தொடங்கும்' - என்பதாம். இந்நிலை வித்தியா தத்துவங்களின் சேர்க்கையால் நிகழ்வது.)
பின்னர் மூலப் பிரகிருதியால், அந்தச் சித்துத் தன்மை நிலை பெற்று விளங்கும். (அஃதாவது, 'அறிவு இச்சை செயல்கள் நன்கு செயற்பட்டு விளங்கும்' என்பதாம். இந்நிலை ஆன்ம தத்துங்களால் நிகழ்வது.)
'மாயை' என்கின்ற மலத்தினாலே மற்றொரு மலமாகிய ஆணவத்தை இறைவன் கழுவியொழிக்கின்றான் என்பது வியப்பான செய்திதான். 'பொருளியல்புகள் அவ்வாறு அமைந்துள்ளன. 'மலம் மலத்தான் - கழுவுவன் என்று சொன்ன காரணம் என்னை, என ஐயம் எழுப்பி, 'செழுநவ அறுவை சாணி உவர் செறிவித்து அழுக்கை - முழுவதுங் கழிப்பன்'-என விளக்கம் தந்தார் அருணந்தி தேவரும்.*
மாயை சேராத பொழுது ஆன்மாத் தனிமையுடையதாகும்' மாயை சேர்ந்த பொழுது கலையோடு கூடியதாகும். அதுவே நிலையில்லாத பல்வேறு பிறப்புக்களில் புகும் பிறவிநிலை. இனி, 'மாயை, ஆணவம்' என்னும் இரண்டையும் கடந்து நிற்கும் நிலையும் உயிருக்கு உண்டு. (அதுவே சுத்தம்.)`,
  },
  {
    id: 2228, tantraId: 8, verseNumber: 2227,
    tamil: `தன்னை அறிசுத்தன் தற்கேவ லன்தானும்
பின்னம் உறநின்ற பேத சகலனும்
மன்னிய சத்தசத் துச்சத சத்துடன்
துன்னவர் தத்தம் தொழில்கள் வாகவே`,
    transliteration: `taṉṉai aṟicuttaṉ taṟkēva laṉtāṉum
piṉṉam uṟaniṉṟa pēta cakalaṉum
maṉṉiya cattacat tuccata cattuṭaṉ
tuṉṉavar tattam toḻilkaḷ vākavē`,
    english: `2227: Sat, Asat and Sat-Asat Nature of Suddha, Kevala, Sakala
States
He who cognises the Self
Is in Suddha State;
He who is not
Is in Kevala;
He who cognises in distracting differences
Is in Sakala;
In Sat (Real), Asat (Unreal) and Sat-Asat (Real-Unreal)
They respective conjoin;
Each according to his cognising state.`,
    elaborationTamil: `தத்துவங்களையும், அவற்றின் நீங்கியவழித் தன்னையும் அறிதலை விடுத்துச் சிவத்தை அறிகின்ற சுத்த நிலையை அடைந்தவனும், அவ்வாறின்றி, 'தத்துவம், சிவம்' என்ற இரண்டையும் அறியாது, ஆணவம் ஒன்றிலே மட்டும் அழுந்தி யிருக்கின்ற, தனது அநாதியியல்பை உடையவனும், இவ்விருவரின் வேறாய்த் தத்துவங் -களை அறிந்து நிற்பவனும் தம்தம் ஆற்றலுக்கு ஏற்ப முறையே, சத்து, அசத்து, சதசத்து ஆகிய பொருள்களில் பொருந்தியிருப்பர்.`,
  },
  {
    id: 2229, tantraId: 8, verseNumber: 2228,
    tamil: `தானே தனக்குப் பகைவனும் நட்டானும்
தானே தனக்கு மறுமையும் இம்மையும்
தானே தான்செய்த வினைப்பயன் துய்ப்பானும்
தானே தனக்குத் தலைவனும் ஆமே`,
    transliteration: `tāṉē taṉakkup pakaivaṉum naṭṭāṉum
tāṉē taṉakku maṟumaiyum immaiyum
tāṉē tāṉceyta viṉaippayaṉ tuyppāṉum
tāṉē taṉakkut talaivaṉum āmē`,
    english: `2228: Importance of Self-Cognition-Suddha State
Himself unto himself
Is foe and friend;
Himself unto himself
Is the here and hereafter;
Himself his Karmas
He experiences;
Himself unto himself
His master be.`,
    elaborationTamil: `(இதன் பொருள் வெளிப்படை.)`,
  },
  {
    id: 2230, tantraId: 8, verseNumber: 2229,
    tamil: `ஆமுயிர் கேவலம் மாமாயை யின்நடந்து
ஆம்உயிர் மாயை எறிப்ப அறிவுற்று
காமியம் மாமேய மும்கல வாநிற்பத்
தாம்உறு பாசம் சகலத்து ஆமே`,
    transliteration: `āmuyir kēvalam māmāyai yiṉnaṭantu
āmuyir māyai eṟippa aṟivuṟṟu
kāmiyam māmēya mumkala vāniṟpat
tāmuṟu pācam cakalattu āmē`,
    english: `2229: Evolution of the Sakala State of the Soul
The Soul in Kevala State
Inert reposes;
On it the Mamaya (Asuddha Maya) acts;
By the action
The Soul receives powers of cognition;
And then mixing with Desire (Kamiyam)
And the Objects of Desire (Mayeyam)
In Pasa it full enters;
That the State of Sakala is.`,
    elaborationTamil: `உயிர் மாயை கன்மங்களோடு கூடாது ஆணவத்தோடு மட்டும் இருந்த நிலை கேவலாவத்தை. (இதுவே உயிர்களின் அநாதி நிலை). பின்பு இறைவன் மாயா காரியங்களைக் கூட்டுவிக்க, அவற்றால்சிறிது அறிவைப்பெற்று வினைகளை ஈட்டியும், நுகர்ந்தும் வரும் நிலை சகலாவத்தை.`,
  },
  {
    id: 2231, tantraId: 8, verseNumber: 2230,
    tamil: `சகல அவத்தையில் சார்ந்தோர் சகலர்
புகலும் மலம்மூ வகையும் புணர்ந்தோர்
நிகரில் மலரோன்மால் நீடுபல் தேவர்கள்
நிகழ்நரர் சீடம் அந்தமும் ஆமே`,
    transliteration: `cakala avattaiyil cārntōr cakalar
pukalum malammū vakaiyum puṇarntōr
nikaril malarōṉmāl nīṭupal tēvarkaḷ
nikaḻnarar cīṭam antamum āmē`,
    english: `2230: Who Are the Sakalas?
Sakalas are those
Who in Sakala State are;
Steeped they are in Pasas three;
The peerless Brahma, Hari,
The Celestials numerous,
The humans here below
And all lives unto the tiny worm,
All, all, are Sakalas verily.`,
    elaborationEnglish: `Souls are ranked as vijnanakalas, pralayakalas, and sakalas according to the number of malas they possess. Vijnanakalas possess only anava, but they are inert. Pralayakalas possess maya, in addition anava. They belong to the world of suddha/asuddha maya. The 108 Srikanta Rudras are of to his catergory. The sakalas are the souls soaked in all the three malas — anava, karma and maya`,
    elaborationTamil: `ஆன்மதத்துவங்கள் கூடுதல் குறைதல்களால் நிகழும் அவத்தைகளே சகலாவத்தைகள் ஆதலின், அவைகளை அடைந்தோர் யாவரும் சகல வருக்கத்தினரே. ஏனெனில், அவர்களே முக்குண வடிவாகிய பிரகிருதியுட்பட்டு, மும்மலங்களை உடையவர் -களாய் இருத்தலின். எழுவகைப் பிறவியும் எய்தும் உயிர்கள் யாவும் சகல வருக்கத்தினவாதல் தெளிவு. இனி அவ் உயிர்களின் மேம்பட்டவர்களாக எண்ணப்படுகின்ற 'அயன் மால்' என்பவர்களும் பிரகிருதி புவனத்துள் பிறந்து இறந்தமை புராண இதிகாசங்களில் கேட்கப்படுதலால், அவர்களும் சகல வருக்கத்தினரே.`,
  },
  {
    id: 2232, tantraId: 8, verseNumber: 2231,
    tamil: `தாவிய மாயையில் தங்கும் பிரளயம்
மேவிய மற்றது உடம்பாய்மிக் குள்ளன
ஓவல் இலக்கணர் ஒன்றிய சீகண்டர்
ஆவயின் நூற்றெட்டு உருத்திர ராமே`,
    transliteration: `tāviya māyaiyil taṅkum piraḷayam
mēviya maṟṟatu uṭampāymik kuḷḷaṉa
ōval ilakkaṇar oṉṟiya cīkaṇṭar
āvayiṉ nūṟṟeṭṭu uruttira rāmē`,
    english: `2231: Who Are the Pralayakalas
Pralayakalas in Maya (Asuddha) world abide;
Of Maya their bodies are in main;
Of comeliness eternal are they;
The Srikanta
And the eight and hundred Rudras;
--(These the Pralayakalas are.)`,
    elaborationTamil: `மாயை ஒழிந்த ஏனை இரு மலங்களையுடைய 'பிரளயாகலர்' என்போர் பிரகிருதியைக் கடந்த மாயாதத்துவத்தில் இருப்பர். அதனால் இவர்களது தனு கரணாதிகள் பிராகிருதம் ஆகாது. மாயேயமேயாம். (எனவே, 'மாயையின் நீங்கினார்' என்பது, 'பிரகிருதியின் நீங்கினார்' என்பதேயாம். ஆகவே, இவர்கள் சகலரினும் மேம்பட்டவர்கள், சிவனை ஒரு போதும் அறியாது மயங்குவாரல்லர்.) மாயையின் நீங்கினாராயினும் கன்மம் நீங்கப் பெறாதவர்கள். (இவர்களுக்கு உள்ள கன்மம் சூக்கும கன்மமே.) அனந்த தேவர் வழிநின்று குணமூர்த்திகளை ஏவிப் பிரகிருதி மாயையில் காரியங்களைச் செய்விக்கும் சீகண்ட ருத்திரர், மற்றும் பிரகிருதி தத்துவத்தில் உள்ள நூற்றெட்டுப் புவன ருத்திரர்கள் ஆகியோர் இப்பிரளயாகலர் வருக்கத்தைச் சேர்ந்தவர்களே.`,
  },
  {
    id: 2233, tantraId: 8, verseNumber: 2232,
    tamil: `ஆகின்ற கேவலத்து ஆணவத்து ஆனவர்
ஆகின்ற வித்தேச ராம்அனந் தாதியர்
ஆகின்ற எண்மர் எழுகோடி மந்திரர்
ஆகின்ற ஈசர் அநேகரும் ஆமே`,
    transliteration: `ākiṉṟa kēvalattu āṇavattu āṉavar
ākiṉṟa vittēca rāmaṉan tātiyar
ākiṉṟa eṇmar eḻukōṭi mantirar
ākiṉṟa īcar anēkarum āmē`,
    english: `2232: Who Are the Vijnanakalas
Vijnanakalas are souls, other numerous,
They reside in the State of Kevala;
They are possessed of Anava (mala)--alone;
The eight Vidyesvaras beginning with Ananta
The (Maha) Mantraresvaras that seven crore number,
--(These the Vijnanakalas are.)`,
    elaborationTamil: `எல்லார்க்கும் உரித்தாகின்ற கேவலாவத்தையைத் தாங்களும் உடையவர்களாய், ஆயினும் கன்மமும், மாயையும் இன்றி, ஆணவம் ஒன்றை மட்டும் உடையவர்களில் பக்குவம் பெற்றோர் அனந்தர் முதலிய அட்ட வித்தியேசுரர்களும், சத்த கோடி மகாமந்திரேசுரர்களும் ஆவர். அபக்குவரோஅநேகர்.`,
  },
  {
    id: 2234, tantraId: 8, verseNumber: 2233,
    tamil: `ஆம்அவ ரில்சிவ னார்அருள் பெற்றுளோர்
போம்மலந் தன்னால் புகழ்விந்து நாதம்விட்டு
ஒம்மய மாகி ஒடுங்கலின் நின்மலம்
தோம்அறும் சுத்த அவத்தைத் தொழிலே`,
    transliteration: `āmava rilciva ṉāraruḷ peṟṟuḷōr
pōmmalan taṉṉāl pukaḻvintu nātamviṭṭu
ommaya māki oṭuṅkaliṉ niṉmalam
tōmaṟum cutta avattait toḻilē`,
    english: `2233: Suddha or Pure State
Of them,
Those who receive Siva's Grace
From Anava mala get liberated;
Transcending the states of Bindu (light) and Nada (sound)
As Aum (Pranava) they become;
And in Siva Pure they merge;
That verily is the Suddha (Pure) State (Avasta).`,
    elaborationTamil: `மேல், 'ஒருமலம் உடையார்' எனக் கூறப்பட்ட -வர்களில், பெறுதற்கரிய சிவனது திருவருளை நிரம்பப் பெற்ற சிலர் அதிகார மல வாசனை, போக மல வாசனை ஆகியவைகள் நீங்கப் பெற்று, இலய மல வாசனை மட்டுமே உடையவர் ஆவர். ஆகவே, அவர்கள் மலம் முற்றும் நீங்கிய முத்தர்களாகவே கருதப்படுவர். (அதனால் அவர்கட்குக் கேவல நிலை உள்ளதாகவும் கருதுதல் கூடாது. அவர்கள் வாழ்வது அபர விந்து அபர நாதங்களைக் கடந்த பரவிந்து பர நாதங்களிலாம். ஆகவே, அவர்கள் சூக்குமை வாக்கு ஒன்றை மட்டுமே உடையவர் ஆவர். அவ்வாற்றால் அவர்கள், சுத்தாவத்தை ஒன்றை மட்டுமே அடைபவராகக் கருதப்படுவர்.`,
  },
  {
    id: 2235, tantraId: 8, verseNumber: 2234,
    tamil: `ஒரினும் மூவகை நால்வகை யும்உள
தேரில் இவைகே வலம்மாயை சேர்இச்சை
சார்இய லாயவை தாமே தணப்பவை
வாரிவைத்து ஈசன் மலம்அறுத் தானே`,
    transliteration: `oriṉum mūvakai nālvakai yumuḷa
tēril ivaikē valammāyai cēriccai
cāriya lāyavai tāmē taṇappavai
vārivaittu īcaṉ malamaṟut tāṉē`,
    english: `2234: Four Divisions of Vijnanakalas
When you think of it,
Of these Souls in gradation three,
Vijnanakalas have divisions four.
They are shrouded in Kevala (Asuddha) Maya;
Inclined are they to be gripped by Desire,
Yet, of themselves they leave all;
When the Lord His Grace bestows;
And together the Malas sunders.`,
    elaborationEnglish: `There are. four divisions of vijnanakalas, all shrouded in kevala State. "Some are in pure kevala (kevala-kevala), some more evolved are in kevala-sakala by the power of bindu; some even more evolved are in kevala-suddha, and the furthest evolved, having totally merged in Siva are in Arul-kevala state. Albeit, gripped by mayaic desire, they are freed by the Grace of God and with that they sever the malas.`,
  },
  {
    id: 2236, tantraId: 8, verseNumber: 2235,
    tamil: `பொய்யான போதாந்தம் ஆறாறும் விட்டகன்று
எய்யாமை நீங்கவே எய்தவன் தானாகி
மெய்யாம் சராசர மாய்வெளி தன்னுட்புக்கு
எய்தாமல் எய்தும்சுத் தாவத்தை என்பதே`,
    transliteration: `poyyāṉa pōtāntam āṟāṟum viṭṭakaṉṟu
eyyāmai nīṅkavē eytavaṉ tāṉāki
meyyām carācara māyveḷi taṉṉuṭpukku
eytāmal eytumcut tāvattai eṉpatē`,
    english: `2235: When is Suddha State Reached?
Abandoning the illusory Tattvas
Six times six;
Rid of ignorance
The Jiva becomes Siva Himself;
And pervading all Creation
He enters the Void true;
This the Suddha State,
That of himself the Jiva reaches.`,
    elaborationTamil: `உண்மையான சுத்தாவத்தையாவது, விபரீத ஞானத்தையே தருகின்றவைகளாகிய கருவிகள் முப்பத்தாறினின்றும் விடுபட்டு அப்பாற்போய், அங்ஙனம் போயதனால் அறியா -மையையே தருவதாகிய ஆணவமலம் வந்து பற்றுதலாகிய அந் நிலையும் தோன்றாதொழிய, யாதொன்றனையும் உண்மையாகவே அறியும் அறிவை யுடையவனாய், அந்த அறிவால் சரம், அசரம் ஆகிய அனைத்தையும் ஒருகாலத்திலே ஒருங்கே உணரும் நிலையை உடையனாய், அத்தன்மைத்தாய் விளங்கும் பராகாயமாகிய அருள் வெளியுட் பகுந்து, அவ்வெளிக்குள் உள்ள சிவனை, அடையாமல் அடைந்திருப்பதாகும்.`,
  },
  {
    id: 2237, tantraId: 8, verseNumber: 2236,
    tamil: `அனாதி பசுவியாத்தி யாகும் இவனை
அனாதியில் வந்த மலம்ஐந்தால் ஆட்டி
அனாதியில் கேவலம் அச்சக லத்திட்டு
அனாதி பிறப்புறச் சுத்தத்துள் ஆகுமே`,
    transliteration: `aṉāti pacuviyātti yākum ivaṉai
aṉātiyil vanta malamaintāl āṭṭi
aṉātiyil kēvalam accaka lattiṭṭu
aṉāti piṟappuṟac cuttattuḷ ākumē`,
    english: `2236: How Suddha State is Reached
Eternal is he, Jiva; pervasive too is he;
Immersing him in Eternal Malas five,
The Lord lifts him
From the Primordial Kevala State
And consigns to Sakala State;
Thence,
Freed from unceasing whirl of birth
The Jiva, Suddha State reaches.`,
    elaborationTamil: `அனாதியே பாசத்துட்பட்டுப் பசுத்தன்மை எய்தி நின்ற இந்த உயிரை, அனாதியாயும், ஆதியாயும் வந்த ஐந்து மலங்களால் ஆட்டிப் படைப்பவன் சிவன். அவன் அனாதியில் கேவல நிலையிலிருந்த உயிரை சகல நிலையில் கொணர்ந்துவைத்துப் பின்பு அனாதியாய பிறப்பு ஒழியும்படி சுத்தாவத்தையில் சேர்ப்பான்.`,
  },
  {
    id: 2238, tantraId: 8, verseNumber: 2237,
    tamil: `அந்தரம் சுத்தாவத் தைகே வலத்தாறு
தந்தோர்தம் சுத்தகே வலத்தற்ற தற்பரத்
தின்பால் துரியத் திடையே அறிவுறத்
தன்பால் தனையறி தத்துவந் தானே`,
    transliteration: `antaram cuttāvat taikē valattāṟu
tantōrtam cuttakē valattaṟṟa taṟparat
tiṉpāl turiyat tiṭaiyē aṟivuṟat
taṉpāl taṉaiyaṟi tattuvan tāṉē`,
    english: `2237: Knowledge of Self in Turiya Leads to Suddha State
The Suddha State is the ultimate;
The Jiva that passes through Kevala
When it reachs Turiya
Receives knowledge of Tatpara,
--Who beyond States, Kevala and Suddha, exists--
Thus realizing the Self within.`,
    elaborationTamil: `எல்லாவற்றினும் மேலாய், நிறைவாய் உள்ள உண்மைச் சுத்த துரியாதீதமே, 'சுத்தாவத்தை' என்றற்குப் பெரிதும் ஏற்புடையது. அஃது 'அருட்கேவலம்' எனப்படும் தத்துவ சுத்திக்குப் பின் வாய்ப்பதாகும். அதனை அவ்வாற்றால் சிவனால் தரப்பட்டவர் தனித்த ஒரு சுத்தமாகிய அந்த அதீத நிலையில் யாதொரு பற்றும் இல்லாத சிவமேயாய் இருப்பர். (இதில், 'யான், எனது' என்னும் உணர்வு இல்லையாம்.) இனி அதற்குக் கீழ்நிலையில் உள்ள துரிய நிலையில் ஆன்ம அறிவு சிறிதே நிகழ்தலால், ஆன்மாச் சிவனை அறியும் முகத்தால் தன்னை அறிபவனாக உணரும் நிலை உள்ளதாம்.`,
  },
  {
    id: 2239, tantraId: 8, verseNumber: 2238,
    tamil: `ஐ ஐந்து ஒடுங்கும் ஆன்மாவில் ஆன்மாவும்
மெய்கண்டு சுத்த அவத்தையில் வீடாகும்
துய்யஅவ் வித்தை முதன்மூன்றும் தொல்சத்தி
ஐயன் சிவன்சத்தி யாம்தோற்றம் அவ்வாறே`,
    transliteration: `ai aintu oṭuṅkum āṉmāvil āṉmāvum
meykaṇṭu cutta avattaiyil vīṭākum
tuyyaav vittai mutaṉmūṉṟum tolcatti
aiyaṉ civaṉcatti yāmtōṟṟam avvāṟē`,
    english: `2238: Involution of Tattvas After Jiva Reaches Suddha State
The Tattvas five times five
Will into the Soul involute;
The Soul, having realized Suddha State,
Will in Suddha Vidya Tattva merge;
The first three of this category
(Suddha Vidya, Isvaram and Sadakyam)
Will in Sakti involute;
Beyond the Sakti is Siva
(Of the Siva Tattva)
Thus involuting, the Soul returns to the Beginning;
This the order (in reverse) of evoluting too.`,
    elaborationEnglish: `The twenty-five tattvas then involute into the soul and merge into the six vidya tattvas. From there it passes into the suddha state, merging in suddha vidya tattva. The first three of the pure maya category (suddha vidya, isvaram and sadakyam) involute in Sakti tattva (bindu). Beyond Sakti tattva is Siva tattva (nada). This is the process of the graded involution of the tattvas into the ultimate Siva. The reverse order of this is the devolution of the tattvas.`,
  },
  {
    id: 2240, tantraId: 8, verseNumber: 2239,
    tamil: `ஐஐந்தும் ஆன்மாவில் ஆறோடு அடங்கியும்
மெய்கண்ட மேல்மூன்றும் மேவுமெய் யோகத்தில்
கைகண்ட சத்தி சிவபாகத் தேகாண
எய்யும் படியடங்கும் நாலேழ் எய்தியே`,
    transliteration: `aiaintum āṉmāvil āṟōṭu aṭaṅkiyum
meykaṇṭa mēlmūṉṟum mēvumey yōkattil
kaikaṇṭa catti civapākat tēkāṇa
eyyum paṭiyaṭaṅkum nālēḻ eytiyē`,
    english: `2239: Involution of Tattvas Further Explained
The Tattvvas five times five of Purusha
Into the Six (Vidya Tattvas) involute;
They into the three Siva Tattvas higher above involute,
Who in turn merges into Sakti Bindu
Who with Siva (Nada) stands;
--Thus is the ultimate of involution reached
Into Tattvas four and seven.`,
    elaborationEnglish: `1) 25 prakriti or atma tattvas including the experient soul—purusa. 2) i)suddha vidya; ii)Isvaram; — they belong to the Siva tattvas. 3) Eleven tattvas — six vidya tattvas plus the five Siva tattvas. The Saiva Siddhanta of philosophy postulates ‘thirty-six tattvas. Of these, twenty-five (including jiva) belong to the body (atma tattvas), six to higher knowledge (vidya tattvas); and five to the spirit (Siva tattvas). At the time of involution the twenty-five bodily tattvas involute into the jiva (soul); they do not involute into Siva tattvas. So Tirumular here skips them and enumerates the tattvas that involute into the Siva tattvas as twenty-five only. Of the remaining five Siva tattvas, the important three, namely suddha vidya (spiritual knowledge), Isvaram (Godliness), and Sadakyam (God-equality) involute into Siva. As Sakti stands one with Siva, it is not considered as a separate category. Thus the tattvas are enumerated in the verse as twenty-eight in all.`,
    elaborationTamil: `(மேல், 'நாலாறுடன் புருடன்' - என்னும் மந்திரத்தில் 'வேதாந்தி தத்துவம்'-எனக் கூறப்பட்ட இருபத்தெட்டுத் தத்துவங்களில்) ஒடுக்க முறையில் முதல் இருபத்தைந்து தத்துவங்கள் சீவனில் அடங்கும். இருபத்தாறாம் தத்துவமாகிய ஈசுரன் உட்பட மற்றைய மூன்று தத்துவங்களும் மெயப்பொருளாகிய பரப்பிரமத்தில் சீவன் ஒன்றாகும் பொழுது அதில் அடங்கிவிடும். சுருக்கமாகச் சொல்வதென்றால், 'விவகாரத்திற்குக் காரண சத்தியாகிய மாயை, அதற்கு அதிட்டானமாம் பாரமார்த்திகப் பொருளாகிய பரப்பிரமம் என்னும் அவ்விரண்டிலே எல்லாம் தோன்றுதலால், எல்லாம் ஒடுங்குதலும் அவற்றிலேதான்' எனலாம்.`,
  },
  {
    id: 2241, tantraId: 8, verseNumber: 2240,
    tamil: `ஆணவத் தார்ஒன்று அறியாத கேவலர்
பேணிய மாயைப் பிரளயா கலராகும்
காணும் உருவினர் காணாமை காண்பவே
பூணும் சகலர்முப் பாசமும் புக்கோரே`,
    transliteration: `āṇavat tāroṉṟu aṟiyāta kēvalar
pēṇiya māyaip piraḷayā kalarākum
kāṇum uruviṉar kāṇāmai kāṇpavē
pūṇum cakalarmup pācamum pukkōrē`,
    english: `2240: Souls are Ranked as Vijnanakalas, Pralayakalas, and
The Kevalas (Vijnanakalas) are inert
With Anava alone possessed;
The Pralayakalas have Maya
In addition;
They see with form unseen;
The Sakalas are Souls
In all three Malas steeped.`,
    elaborationTamil: `ஆணவ மலம் ஒன்றையே உடையவராகிய விஞ்ஞானகலர் கேவலாவத்தையை அடையுமிடத்துக் காரிய தத்துவங்களுள் ஒன்றையும் அனுபவியாது, நாதமாத்திரையா யிருப்பர். இரு மலம் உடையவராகிய பிரளயாகலர் கேவலா வத்தையை அடையும் பொழுது வித்தியாதத்துவத்தின் முடிவாகிய மாயாதத்துவம் அவர்கட்கு அனுபவப்பொருளாகும். போக்கிய காண்டமாய்த் தூலமாய் உள்ள பிரகிருதிக் காரியங்களை உடைய சகலர் கேவலாவத்தையை அடையும் பொழுது காரணமாகிய பிர கிருதியையே பற்றிக்கொண்டு, அதன் காரியப் பொருள்களில் ஒன்றையும் அனுபவித்தல் இன்றியிருப்பர், இனிச்சகலாவத்தை சகலர்கட்கே உளதாகும்.`,
  },
  {
    id: 2242, tantraId: 8, verseNumber: 2241,
    tamil: `ஆணவம் ஆகும் விஞ்ஞான கலருக்குப்
பேணிய மாயை பிரளயா கலருக்கே
ஆணவ மாயையும் கன்மம் மூன்றுமே
காணும் சகலர்க்குக் காட்டும் மலங்களே`,
    transliteration: `āṇavam ākum viññāṉa kalarukkup
pēṇiya māyai piraḷayā kalarukkē
āṇava māyaiyum kaṉmam mūṉṟumē
kāṇum cakalarkkuk kāṭṭum malaṅkaḷē`,
    english: `2241: Further explained
The Vijnanakalas possess Anava mala alone;
The Pralayakalas have Maya too;
Anava, Maya, and Karma
--All three the Sakalas have
These their Malas are.`,
  },
  {
    id: 2243, tantraId: 8, verseNumber: 2242,
    tamil: `கேவலம் தன்னில் கிளர்ந்தவிஞ் ஞாகலர்
கேவலம் தன்னில் கிளர்விந்து சத்தியால்
பூவயின் கேவலத்து அச்சக லத்தையும்
மேவிய மந்திர மாமாயை மெய்ம்மையே`,
    transliteration: `kēvalam taṉṉil kiḷarntaviñ ñākalar
kēvalam taṉṉil kiḷarvintu cattiyāl
pūvayiṉ kēvalattu accaka lattaiyum
mēviya mantira māmāyai meymmaiyē`,
    english: `2242: Sakalas in Vijnanakalas
The Vijnanakalas
Who stand in Kevala (inert State)
By the power of Bindu,
That in Kevala is,
Become activated as Sakalas within Kevala;
And so attain the truth of Mamaya
Who the power of Mantra holds.`,
    elaborationTamil: `(ஒன்று இடையிட்டு முன்னை மந்திரத்தில் கூறிய கேவல வகைகளில்) தமக்குரிய கேவலநிலை அடைபவராகக் கூறப்பட்ட விஞ்ஞானகலர், அக்கேவல நிலையினின்றும் எழுச்சி பெறுதல் 'விந்து' எனப்படும் சத்தி தத்துவத்தினாலாம். (எனவே, கேவல நிலையில் அவர்கள்' நாதம்' எனப்படும் சிவதத்துவத்தைப் பற்றியிருந் -தமை பெறப்படும். ) அந்த விந்து சத்தியோடு பிற சுத்த மாயா தத்துவங் -களைப் பற்றிச் செயற்படுதலே அவர்களது சகல நிலை யாகும். (ஆகவே சகலருக்குப் போலப் பிரகிருதி தத்துவங்களைப் பற்றும் சகல நிலை அவர்கட்கு இல்லையாம்.) அந்தச் சகல நிலையில் அவர்களுடைய தனு கரணங்கள், மந்திர வடிவாகிய சுத்த மாயையால் ஆயினவேயாம்.`,
  },
  {
    id: 2244, tantraId: 8, verseNumber: 2243,
    tamil: `மாயையில் மன்னும் பிரளயா கலர்வந்து
மாயையும் தோன்றா வகைநிற்க ஆணவ
மாய சகலத்துக் காமிய மாமாயை
ஏயமன் நூற்றெட்டு உருத்திரர் என்பவே`,
    transliteration: `māyaiyil maṉṉum piraḷayā kalarvantu
māyaiyum tōṉṟā vakainiṟka āṇava
māya cakalattuk kāmiya māmāyai
ēyamaṉ nūṟṟeṭṭu uruttirar eṉpavē`,
    english: `2243: Pralayakalas--108 Rudras
The Pralayakalas in Maya (Suddha) reside;
Yet that Maya affects them not;
They stand with Anava;
With Mamaya's (Asuddha) Kamya desires that Sakalas possess;
They verily are the Rudras One Hundred and Eight.`,
    elaborationEnglish: ``,
    elaborationTamil: `வித்தியா தத்துவங்களில் மாயா தத்துவம் மட்டுமே செயற்பட்டு நிற்கும் நிலையில் பிரளயாகலர்பால் அந்த மாயா தத்துவ மும் மெத்தெனவே செயற்படுதலால் ஆணவம் மேற்பட்டு நிற்கும். (அஃதே அவர்க்குக் கேவல நிலையாகும்.) இனி, அவர்கட் குரிய சகலா வத்தைக்கண் சுத்த தத்துவங்கள் செயற்படுதலானே கன்ம மலங் காரியப் படுவதாகும். இந்நிலையில் நிற்பவர்கள், மேல், ''தாவிய மாயை''- என்னும் மந்திரத்தில் (2199) குறிப்பிடப்பட்ட நூற்றெட்டுருத்திரராவர்.`,
  },
  {
    id: 2245, tantraId: 8, verseNumber: 2244,
    tamil: `மும்மலம் கூடி முயங்கி மயங்குவோர்
அம்மெய்ச் சகலத்தர் தேவர் சுரர்நரர்
மெய்ம்மையில் வேதா விரிமிகு கீடாந்தத்து
அம்முறை யோனிபுக்கு ஆர்க்கும் சகலரே`,
    transliteration: `mummalam kūṭi muyaṅki mayaṅkuvōr
ammeyc cakalattar tēvar curarnarar
meymmaiyil vētā virimiku kīṭāntattu
ammuṟai yōṉipukku ārkkum cakalarē`,
    english: `2244: Sakalas Have All Three Malas
They who in Malas three enveloped
In worldly life wallow,
Are the Sakalas per se;
Thus are the Devas, the humans,
And the rest of Brahma's creation numerous
Unto the very worm
That life's womb enters;
--All these are Sakalas that crowd the world.`,
    elaborationTamil: `'மும்மலம்' என்றும், ஐம்மலம்' என்றும் சொல்லப் படுகின்ற அனைத்து மலங்களையும் உடையவர்களாய், 'தமக்குமேல் ஒரு முதற் பொருள் உண்டு' என அறியாது மயங்குகின்றவர்களே உண்மையான சகலாவத்தையை அடைபவர்கள். தேவர்கள், அசுரர்கள், மக்கள், அடி முடி தேடிய காலத்தில் 'முடியைக் கண்டேன்' எனப் பொய் கூறிய பிரமன், வியாபகன்' என்னும் கருத்தால், 'விட்டுணு' என்று அழைக்கப்படுகின்ற மாயோன் இவர்கள் யாவரும் தமக்குக் கீழ் புழுவரையில் உள்ள அனைத்து யோனிகளிலும் புகுந்து ஆரவாரிக்கின்ற சகல வருக்கத்தினரே.`,
  },
  {
    id: 2246, tantraId: 8, verseNumber: 2245,
    tamil: `சுத்த அவத்தையில் தோய்ந்தவர் மும்மலச்
சத்துஅசத்து ஓடத் தனித்தனி பாசமும்
மத்த இருள்சிவ னான கதிராலே
தொத்தற விட்டிடச் சுத்தஆ வார்களே`,
    transliteration: `cutta avattaiyil tōyntavar mummalac
cattuacattu ōṭat taṉittaṉi pācamum
matta iruḷciva ṉāṉa katirālē
tottaṟa viṭṭiṭac cuttaā vārkaḷē`,
    english: `2245: Rid of Malas, Souls Become Suddhas
They who Suddha State reach,
By luminous Grace of Siva
Stand dispelled of Malas triple,
That Sat-Asat are;
And of dark Pasas, one by one;
Having thus rid them entire,
They become Suddhas ever.`,
    elaborationTamil: `'கேவலம், சகலம், சுத்தம்' என்னும் மூன்றனுள் சுத்தவத்தையில் மூழ்கினவர்களே, 'ஆணவம், கன்மம், மாயை' என்னும் மும்மலங்களும் செயல் ஒழிந்து, உண்மை மாத்திரையாய் நிற்றலாலும், அம்மலங்களைச் செயற்படுத்தித் தனியாகி அவறறிற்குத் தலைமை பூண்டு நின்ற திரோதான சத்தியாகிய மலமும் சிவசூரியனது கிரணமாம் அருட் சத்தியால் சற்று விட்டு நீங்குதலாலும் உண்மையில், 'சுத்தர்' எனத் தக்கவர் ஆவர்.`,
  },
  {
    id: 2247, tantraId: 8, verseNumber: 2246,
    tamil: `தற்கே வலம்முத்தி தானே தனிமையாம்
பிற்பால் சகலம் கலாதிப் பிறிவதாம்
சொற்பால் புரிசுத்த கேவலம் சாக்கிரம்
தற்பால் புரிவது தற்சுத்தம் ஆமே`,
    transliteration: `taṟkē valammutti tāṉē taṉimaiyām
piṟpāl cakalam kalātip piṟivatām
coṟpāl puricutta kēvalam cākkiram
taṟpāl purivatu taṟcuttam āmē`,
    english: `2246: Gradations of Suddha States--Suddha-Kevala, Suddha-
Sakala,
Suddha-Jagra, and Suddha-Suddha
In Suddha-Kevala-Mukti State
The Jiva stands alone;
When afterward
The Kalas leave,
Then is Suddha-Sakala-Mukti;
When in sound Aum
The Soul as one stands,
Then is Suddha (Kevala) Jagra Mukti;
Still beyond,
The Soul Itself within Itself stands
Then is Suddha-within-Suddha-Mukti State.`,
    elaborationEnglish: ``,
    elaborationTamil: `உயிர் சிவத்தோடு மட்டுமே பொருந்தி நிற்கின்ற அந்தத் தனிநிலையே பரமுத்தி நிலையாகும். அதுவே உண்மையில் தூய்மை யாகும். (இதனைச் 'சிவகேவலம்' என்றும். 'பர கேவலம்' என்றும் கூறலாம்.) இதற்குக் கீழ்ப்பட்டன எல்லாம் சகலங்களே. (அஃதாவது, மாசொடுபட்டனவே.) அந்நிலையில், சகல வருக்கத்து ஆன்மாக்கள் கலை முதல் மண் ஈறாய் உள்ள தத்துவங்களின் நீங்கி நிற்றல். அவற்றிற்கு மெய்ந்நூல்களில்சொல்லப்படுகின்ற சுத்த கேவல மாகும். (இஃது, 'அருட் கேவலம்' என்பதாகத் துகளறு போதத்தில் சொல்லப்பட்டது. வெண்பா-25) புருவ நடுவிலே நிகழ்வதாகிய சாக்கிராவத்தையிலே புறப்பொருளில் தோய்தல் இன்றி, அறிவுக் கறிவாய் உள்ள சிவத்திலே தோய்ந்திருத்தல் சகலத்தில் சுத்தமாம். (இதுவே, 'சாக்கிரத்தில் அதீதம்' - என்க.)`,
  },
  {
    id: 2248, tantraId: 8, verseNumber: 2247,
    tamil: `அறிவின்றி முத்தன் அராகாதி சேரான்
குறியொன்றி லாநித்தன் கூடான் காலதி
செறியும் செயலிலான் தினங்கற்ற வல்லோன்
கிறியன் மலவியாபி கேவலம் தானே`,
    transliteration: `aṟiviṉṟi muttaṉ arākāti cērāṉ
kuṟiyoṉṟi lānittaṉ kūṭāṉ kālati
ceṟiyum ceyalilāṉ tiṉaṅkaṟṟa vallōṉ
kiṟiyaṉ malaviyāpi kēvalam tāṉē`,
    english: `2247: Suddha-Kevala-Mukti State Described
Inert without knowledge,
Unaffected by desires,
Goal-less, everlasting,
Unattached to Kalas,
Actionless,
Incapable of daily experiences,
By Malas deceitful infused,
--Thus is Jiva in Kevala-Mukti State.`,
    elaborationTamil: `சிவஞான சித்தியாரில்,
''அறிவிலன்; அமூர்த்தன்; நித்தன்;
அராகாதி குணங்க ளோடும்
செறிவிலன்; கலாதி யோடும்
சேர்விலன்; செயல்க ளில்லான்;
குறியிலன்; கருத்தா அல்லன்;
போகத்திற் கொள்கை யில்லான்;
பிறிவிலன் மலத்தி னோடும்
வியாபி - கேவலத்தில் ஆன்மா''l
எனப் போந்த செய்யுளின் உரையை நோக்கி இம்மந்திரத்தின் பொருளை உணர்ந்து கொள்க.`,
  },
  {
    id: 2249, tantraId: 8, verseNumber: 2248,
    tamil: `விந்துவும் மாயையும் மேவும் கிரியையும்
சந்தத ஞான பரையும் தனுச்சுத்தி
விந்துவின் மெய்ஞ்ஞான மேவும் பிரளயர்
வந்த சகலசுத் தான்மாக்கள் வையத்தே`,
    transliteration: `vintuvum māyaiyum mēvum kiriyaiyum
cantata ñāṉa paraiyum taṉuccutti
vintuviṉ meyññāṉa mēvum piraḷayar
vanta cakalacut tāṉmākkaḷ vaiyattē`,
    english: `2248: Pralayakalas That Are Suddhas Among Sakalas
Bindu, Maya and Kriya
They possess;
The power of interminable Jnana Sakti
Is their substrate (Dhanu);
In Bindu they attain Divine Knowledge;
Thus are the Pralayakalas of this world;
Albeit Sakalas,
They are Suddhas here below.`,
    elaborationTamil: `பிரளயாகலர், சகலர், விஞ்ஞானகலர் ஆகிய மூவகை யினராய் விளங்கும் ஆன்மாக்கட்கும் முறையே அசுத்த மாயை, பிரகிருதி மாயை, சுத்த மாயை என்பவற்றால் அவ்வப் புவனங்களில் தனு கரண போகங்கள் உளவாகும். எல்லா உயிர்கட்கும் சுத்த மாயை -யின் காரியமாகிய வாக்குக்களால்தான் சவிகற்ப உணர்வு உண்டாகும்.`,
  },
  {
    id: 2250, tantraId: 8, verseNumber: 2249,
    tamil: `கேவல மாதியின் பேதம் கிளக்குறில்
கேவல மூன்றும் கிளரும் சகலத்துள்
ஆவயின் மூன்று மதிசுத்த மூடவே
ஓவலில் லாஒன்பான் ஒற்றுணர் வோர்கட்கே`,
    transliteration: `kēvala mātiyiṉ pētam kiḷakkuṟil
kēvala mūṉṟum kiḷarum cakalattuḷ
āvayiṉ mūṉṟu maticutta mūṭavē
ōvalil lāoṉpāṉ oṟṟuṇar vōrkaṭkē`,
    english: `2249: Nine Subtle Divisions For the Soul in the Three States
Kevala, Sakala and Suddha
To speak of the subtle divisions
In the three States--Kevala, Sakala and Suddha
It is like this:
Kevala-Kevala, Kevala-Sakala, and Kevala-Suddha,
Sakala-Kevala, Sakala-Sakala, and Sakala-Suddha,
Suddha-Kevala, Suddha-Sakala, and Suddha-Suddha
--Thus are the combinations nine in all
For those in depth see.`,
    elaborationTamil: `காரண அவத்தைகள் 'கேவலம்' முதல் மூன்றாகச் சொல்லப்பட்டாலும் அவற்றுள் ஒவ்வொன்றிலும் உட்பிரிவுகள் உண்டு. அவற்றை எடுத்துச் சொல்லுமிடத்து 'கேவலத்திற் கேவலம், கேவலத்திற் சகலம், கேவலத்திற் சுத்தம்' என்று மூன்றும், 'சகலத்திற் கேவலம், சகலத்திற் சகலம், சகலத்திற் சுத்தம்' என மூன்றும், 'சுத்தத்திற் கேவலம், சுத்தத்திற் சகலம், சுத்தத்திற் சுத்தம்' என மூன்றும் ஆக ஒன்பதாம். இவ்வேறுபாடுகள் நுண்ணுணர்வுடையார்க்கே விளங்கும்.`,
  },
  {
    id: 2251, tantraId: 8, verseNumber: 2250,
    tamil: `கேவலத்தில் கேவலம் அதீதா தீதம்
கேவலத் தில்சகலங்கள் வயிந்தவம்
கேவத் திறசுத்தம் கேடில்விஞ் ஞாகலர்க்கு
ஆவயின் நாதன் அருண்மூர்த்தி தானே`,
    transliteration: `kēvalattil kēvalam atītā tītam
kēvalat tilcakalaṅkaḷ vayintavam
kēvat tiṟacuttam kēṭilviñ ñākalarkku
āvayiṉ nātaṉ aruṇmūrtti tāṉē`,
    english: `2250: Kevala State Subdivisions for Jiva
Kevala-in-Kevala is atita-atita state,
Kevala-Sakala is the Vaindava manifestations in Suddha Maya State;
Kevala-Suddha is the State of holy Vijanankalas,
That State leads Soul to Grace Embodied.`,
    elaborationTamil: `உயிர்கட்கு ஆணவ மல மறைப்பைச் சிறிதே நீக்கிச் சிறிதே அறிவைத் தருவன மாயா கருவிகள். அதனால், அவை ஒடுங்கிய விடத்து ஆணவம் மேற்படுவதே கேவல நிலை. கீழா லவத்தை மத்தியாலவத்தைகளில் எல்லாக் கருவிகளும் நீங்காது, தலை யாய கருவிகள் நீங்கியதே 'அதீதம்' எனப்படுகின்றது. கீழா லவத்தையில் நிகழும் அதீதம் முக்குண வடிவான பிரகிருதி மேம் பட்ட நிலை. மத்தியாலவத்தையில் நிகழும் அதீதத்திலும் சிவ தத்துவமும், கால தத்துவமும் ஒடுங்காதே நிற்க, உயிருக்குப் புலன்கள் மிக்கு நிகழும். இதுவும் அதீதமேயாகும். இவ்விரண்டும் சகலாதீதமாகும்.
சருவ சங்கார காலத்தில் இறைவன் எல்லாக்கருவிகளையும் அழித்துவிட்டு, உயிர்களுக்கு முழு ஒய்வைத் தருதலால், அது பொழுது உயிர், உணர்வு சிறிதுமின்றி, முழுமூடமாய், ஆணவ இருளில் மூழ்கிக் கிடக்கும். இது கேவலாதீதமாகும். இதனையே 'விஞ்ஞான கேவலம்' என்பர். இந்நிலையில், ஒடுக்கிய உயிர்களை இறைவன் மீளத் தோற்றுவிக்க முயலும் நிலையும் கேவலந்தான். அதனையும் 'சகல கேவலம்' - என்றே கூறுவர். அதற்குக் காரணம் அந் நிலையில் இறைவன் சூக்கும ஐந்தொழில் செய்வான் என்பதே. இவை முதலான அவத்தைகள் பலவற்றுள் ஒன்றும் இல்லாது ஆன்மா ஆணவ இருளில் மூழ்கிக் கிடந்த நிலை அனாதி கேவலமாகும். இதனை, 'மருட் கேவலம்' - என்பர். இவற்றுள் இரு சகலாதீதத்திற்கும் அப்பாற்பட்ட விஞ்ஞான கேவலத்தையே, 'அதீதாதீதமாகிய கேவலத்தில் கேவலம்' என்றார். அதீதாதீதம் - அப்பாலைக்கு அப்பால்.
மேற்கூறியவாறு இறைவன் சூக்கும ஐந்தொழில் செய்யும் நிலையாகிய சகல கேவலமே கேவலத்தில் சகலமாம். சூக்கும ஐந் தொழிலாவது சூக்குமை முதலிய நால்வகை வாக்குக்களையும் தோற்று விக்கும் முகத்தால் உயிர்கட்கு உணர்வைப் பொதுவாக நிகழ்வித்தல். சிவதத்துவங்கள், வித்தியா தத்துவங்களைச் செலுத்தியவழியே உயிர் கட்கு அறிவு இச்சை செயல்கள் சிறப்பாக விளங்கும். அஃது இந்நிலை -யில் இல்லாமையாலும், நால்வகை வாக்குக்களும் சுத்த மாயையில் காரியமேயாதலாலும், 'கேவலத்தில் சகலங்கள் வயிந் தவம்' என்றார். வயிந்தவம் (வைந்தவம்) - விந்துவின் காரியம். விந்து- சுத்த மாயை. வாக்குக்கள் பலவாதலால் அவற்றால் தோன்றும் உணர்வுகளும் பலவாதல் பற்றிச் 'சகலங்கள்' எனப் பன்மையாகக் கூறினார்.
சகலரும், பிரளயாகலரும், 'விஞ்ஞானகலர்' என்னும் நிலையை அடைதலே, கேவலத்தில் சுத்தமாகும். அஃதாவது' சகலர் மண் ணாதி கலையந்தம் முப்பத்தொரு தத்துவங்களைக் கடந்து சுத்த தத்துவ பந்தத்தை மட்டும் உடையர் ஆதலும், பிரளயாகலர் வித்தியா தத்துவங் -களைக் கடந்து, சுத்த தத்துவ பந்தத்தை மட்டும் உடையர் ஆதலுமாம்.
இந்நிலையை அடைந்த பிரளயாகலர் சகலர்கட்கும் இறைவன் இயற்கை விஞ்ஞானகலர்க்குப் பக்குவ காலத்தில் உள்நின்றே ஞானத்தை உணர்த்தி, வீடு தந்தருள்வது போலவே அருள்தருவான்.`,
  },
  {
    id: 2252, tantraId: 8, verseNumber: 2251,
    tamil: `சகலத்தில் கேவலம் சாக்கிரா தீதம்
சகல சகலமே சாக்கிர சாக்கிரம்
சகலத்திற் சுத்தமே தற்பரா வத்தை
சகலத்தில் இம்மூன்று தன்மையும் ஆமே`,
    transliteration: `cakalattil kēvalam cākkirā tītam
cakala cakalamē cākkira cākkiram
cakalattiṟ cuttamē taṟparā vattai
cakalattil immūṉṟu taṉmaiyum āmē`,
    english: `2251: Sakala State Subdivisions for Jiva
Sakala-Kevala is the Jagrat-atita State;
Sakala-Sakala is the Jagrat-within-Jagrat State
Sakala-Suddha is the State of Tat-para (self-illumined)
All these in the state of Sakala occur.`,
    elaborationEnglish: `The inner divisions of suddha-sakala state are sakala-kevala; sakala-sakala and sakala-suddha. Sakala-kevala is the state of jagrat-atita; sakala-sakala is jagrat-in-jagrat. Sakala~suddha is the state of Tat-Para (Self-Illumined). These subdivisions are of the suddha-sakala state of the jiva.`,
    elaborationTamil: `மத்தியாலவத்தையில் நிகழும் அதீதமே சகலத்திற் கேவலமாகும். மத்தியாலவத்தையில் நிகழும் சாக்கிரமே சகலத்திற் சகலமாகும். சகலத்தில் சுத்தாவத்தையே சகலத்தில் சுத்தமாகும்.`,
  },
  {
    id: 2253, tantraId: 8, verseNumber: 2252,
    tamil: `சுத்தத்தில் சுத்தமே தொல்சிவ மாகுதல்
சுத்தத்தில் கேவலம் தொல்லுப சாந்தமாம்
சுத்த சகலம் துரிய விலாசமாம்
சுத்தத்தில் இம்மூன்றும் சொல்லலும் ஆமே`,
    transliteration: `cuttattil cuttamē tolciva mākutal
cuttattil kēvalam tollupa cāntamām
cutta cakalam turiya vilācamām
cuttattil immūṉṟum collalum āmē`,
    english: `2252: Suddha State Subdivisions for Jiva
Suddha-Kevala is State of Upasantha
Suddha-Sakala is Turiya expansive state;
Suddha-Suddha is State of Siva-Becoming;`,
    elaborationEnglish: `The inner divisions of suddha-suddha state are: suddha-kevala, suddha-sakala, and suddha-turiya. Suddha-kevala is the state of upasanta; suddha-sakala is the state of expansive turiya. The state of Siva-becoming is suddha-suddha or suddha-turiya. These three states belong to the suddha-suddha state of jiva.`,
    elaborationTamil: `பரமசிவனோடு இரண்டறக் கலந்த நிலையே சுத்தத்தில் சுத்தம். சீவன் முத்தி நிலையில் பிராரத்தத்தால் விளையும் இன்பத் துன்பங்களில் விருப்பு வெறுப்பற்றிருக்கும் நிலையே சுத்தத்தில் கேவலம். சீவன் முத்தி நிலையில் உலகர்பால் இரக்கம் மிக்கு அவர்கட்கு உய்தியை வலிந்து சென்றும் உணர்வித்தலும், அதிகார முத்தி, போக முத்தி, இலய முத்தி இவைகளை அடைந்து அவ்வந் நிலையில் விளையும் சுத்த போகங்களை நுகர்தலும் சுத்தத்தில் சகலம்.`,
  },
  {
    id: 2254, tantraId: 8, verseNumber: 2253,
    tamil: `சாக்கிர சாக்கிரம் தன்னில் கனவொடுஞ்
சாக்கிரம் தன்னில் சுழுத்தி துரியமே
சாக்கிரா தீதம் தனிற்சுகா னந்தமே
ஆக்கு மறையாதி ஐம்மல பாசமே`,
    transliteration: `cākkira cākkiram taṉṉil kaṉavoṭuñ
cākkiram taṉṉil cuḻutti turiyamē
cākkirā tītam taṉiṟcukā ṉantamē
ākku maṟaiyāti aimmala pācamē`,
    english: `2253: Bliss of Jagratatita State
Jagrat-In-Jagrat, Dream-in-Jagrat;
Sushupti-in-Jagrat and the Turiya-in-Jagrat,
Transcending these states all,
Is Jagratatita that confers Bliss Divine;
The Malas primordial that five are,
Away vanish ever and ever.`,
    elaborationEnglish: `The inner divisions of the suddha-jagrat state are: jagrat-in (suddha)- jagrat; dream-in-jagrat; susuphti-in-jagrat. Dream-in-jagrat is jagrat-atita, that, confers divine bliss. Here disappears the five primordial malas forever and ever.`,
    elaborationTamil: `மத்தியாலவத்தையில் நிகழும் சாக்கிரம் முதலிய ஐந்திலும் சொல்லுலகம் முதலாகச் சொல்லப்படுகின்ற ஐந்து மலங்க ளாகிய பாசங்களே உயிருக்கு உலக அனுபவங்களையே தந்து நிற்கும்.`,
  },
  {
    id: 2255, tantraId: 8, verseNumber: 2254,
    tamil: `சாக்கிரா தீதத்தில் தானறும் ஆணவம்
சாக்கிரா தீதம் பிராவத்தை தங்காது
ஆக்கு பரோபதி யாஉப சாந்தத்தை
நோக்கும் மலங்குணம் நோக்குதல் ஆகுமே`,
    transliteration: `cākkirā tītattil tāṉaṟum āṇavam
cākkirā tītam pirāvattai taṅkātu
ākku parōpati yāupa cāntattai
nōkkum malaṅkuṇam nōkkutal ākumē`,
    english: `2254: In Jagratatita State is Upasantha
In the state of Jagratatita
Anava is rooted entire;
Jagratatita, Para-Avasta (Siva) state is not;
But sure it confers Upasantha
That by Para caused;
Will Jiva, thereafter,
Ever look at Malas and Gunas?`,
    elaborationTamil: `('சாக்கிராதீதம்'-என்ற பெயர் சொல்லப்படுவன இரண்டு. ஒன்று ஆணவம் நீங்கிய சாக்கிராதீதம்; மற்றொன்று, ஆணவம் நீங்காத சாக்கிராதீதம்.) அவற்றுள் ஆணவம் நீங்கிய சாக்கிராதீதமும் பராவத்தையில் உயிர் சென்று தங்காதபடி பரோ பாதியை உண்டாக்கும் ஆகையால், பராவத்தையாகிய உபாதியற்ற நிலையை நோக்கியே செல். ஏனெனில், 'உபாதியாயினும் பரோபாதி தானே' என நினைப்பனவெல்லாம் பாசத்தோடு கூடியிருக்க நினைப்பனவேயாகும்.`,
  },
  {
    id: 2256, tantraId: 8, verseNumber: 2255,
    tamil: `பெத்தமும் முத்தியும் பேணும் துரியமும்
சுத்த அதீதமும் தோன்றாமல் தானுணும்
அத்தன் அருள்என்று அருளால் அறிந்தபின்
சித்தமும் இல்லை செயல்இல்லை தானே`,
    transliteration: `pettamum muttiyum pēṇum turiyamum
cutta atītamum tōṉṟāmal tāṉuṇum
attaṉ aruḷeṉṟu aruḷāl aṟintapiṉ
cittamum illai ceyalillai tāṉē`,
    english: `2255: All Higher Experiences Come to Jiva By God's Grace
The states of Bondage (Boddha), of Liberation (Mukti)
Of Turiya, and Suddha-atita
--All these, the Jiva will subtle experience;
By Lord's Grace they come;
And when that knowledge by Grace dawns,
Neither thought nor action
The Jiva any more has.`,
    elaborationTamil: `'பெத்தம், முத்தி' - என்பவற்றையும், 'சாக்கிர சொப்பன சுழுத்திகளுக்கு அப்பாலும், குறைந்த கருவிகளே செயற் படுகின்ற துரியம், ஒரு கருவியும் செயற்படாத துரியாதீதம் ஆகிய அவத்தைகள் உள' என்பதையும் அறியாமலே உயிர், அவத்தைகளை அனுபவித்து வருகின்றது. ஆயினும், 'அவையெல்லாம் சிவனது திருவருளால் இன்ன இன்னவாறு நிகழ்கின்றன' என்பதை அவனது அருளாலே அறிந்த பின், உயிருக்குத் தற்போதம் இல்லை. அஃது இல்லையாகவே, அதற்குத் தனக்கென யாதொரு செயலும் இல்லை.`,
  },
  {
    id: 2257, tantraId: 8, verseNumber: 2256,
    tamil: `எய்திய பெத்தமும் முத்தமும் என்பன
எய்தும் அரன்அரு ளேவிளை யாட்டோ டு
எய்திடு உயிர்சுத்தத் திடுநெறி என்னவே
எய்தும் உயிர்இறை பால்அறி வாமே`,
    transliteration: `eytiya pettamum muttamum eṉpaṉa
eytum araṉaru ḷēviḷai yāṭṭō ṭu
eytiṭu uyircuttat tiṭuneṟi eṉṉavē
eytum uyiriṟai pālaṟi vāmē`,
    english: `2256: Lord's Play Takes Jiva To God-Knowledge
The states of Bondage and Liberation
Of Hara's Grace, they come
It is His play
To take Jiva to Suddha goal;
That it might God-Knowledge receive.`,
    elaborationTamil: `உயிர்கள் அனாதியே அடைந்துள்ள பெத்த நிலையும், பின்பு முடிவில் அடையும் முத்தி நிலையும் சிவன் தனக்கு ஒரு விளையாட்டைப் போல மிக எளிதிற் செய்யும் அருட்செயலே யாகும். 'அச்செயல்களில் அகப்பட்டு வருகின்ற உயிர்கள், இறுதியில் மாசு நீங்கிய நிலையில் இடப்படும்' என்று சொல்லப்படுவதால், அந்நிலையில் அவை சிவனையே அடைந்திருக்கும். அப்பொழுது அவை அறிவே முடிவாய் இருக்கும்.`,
  },
  {
    id: 2258, tantraId: 8, verseNumber: 2257,
    tamil: `ஐம்மலத் தாரும் மதித்த சகலத்தர்
ஐம்மலத் தாரும் அருவினைப் பாசத்தார்
ஐம்மலத் தார்சுவர்க் கந்நெறி யான்பவர்
ஐம்மலத் தார்அர னார்க்குஅறி வோரே`,
    transliteration: `aimmalat tārum matitta cakalattar
aimmalat tārum aruviṉaip pācattār
aimmalat tārcuvark kanneṟi yāṉpavar
aimmalat tārara ṉārkkuaṟi vōrē`,
    english: `2257: Sakalas Can Attain God-Knowledge
They of Five Malas are Sakalas,
They of Five Malas are Pasa bound
They of Five Malas rule
The Celestial world of Svarga
They of Five Malas can (ultimate) attain God-Knowledge.`,
    elaborationTamil: `ஐந்து மலங்களையுடையவர்களாகச் சொல்லப் படுவோர் யாவரும் அதிகமான மாயைத் தொடக்கு உடையவர்கள். அவர்கள் அசுத்த வினையிலும் நீக்குதற்கரிய தூல வினைத் தொடக்குடையவர்கள். அத்தன்மைத்தான வினைத்தொடக்கால் சுவர்க்க நரகங்களை அடைந்து உழல்பவர்கள். ஆகையால், அவர்கள் சிவனை எளிதில் அறியும் அறிவுடையராவாரோ! 'ஆகார்'.`,
  },
  {
    id: 2259, tantraId: 8, verseNumber: 2258,
    tamil: `கருவில் அதீதம் கலப்பிக்கும் மாயை
அரிய துரியம் அதிலுண்ணும் ஆசையும்
உரிய கழுனை முதல்எட்டும் சூக்கத்து
அரிய கனாத்துலம் அந்தன வாமே`,
    transliteration: `karuvil atītam kalappikkum māyai
ariya turiyam atiluṇṇum ācaiyum
uriya kaḻuṉai mutaleṭṭum cūkkattu
ariya kaṉāttulam antaṉa vāmē`,
    english: `2258: Experiences in the Five States of Consciousness
In Jiva's Atita State
Anava is;
In Turiya State
Maya permeates;
In Sushupti State,
Are desires for Maya experiences planted;
In Dream State
Functions the Subtle Body with Tattvas eight;
In the Waking State
Activated is the Body Gross.`,
    elaborationEnglish: `1)Although in the dream state, the subtle body has 18 tattvas, ten of them (the five sense organs and five motor organs) do not function actually. Only the five tanmatras (sense potencies) and the three antahkaranas (cognitive organs) are active.

Maya (pure) that originated from Hara permeates the tunya state. Anava works in jiva’s atita state and there he realises that para kamya sakti (seed of karma) is there in sushupti. Mamaya (illusory perception) or asuddha maya rules the dream state.-Tirodhayi sakti (obscuration) joins in the waking state and activates the gross body. Thus are the five malas attached to the jiva in the sakala state.`,
    elaborationTamil: `(உயிர்கள் யாதானும் ஓர்யோனியிற்புக்குப் பிறந்த பின்பு தான் சாக்கிரம் முதலிய அவத்தைகளை அடையும்' எனக் கருத வேண்டா. அவ்வவ் யோனியிற் புக்கிருக்கும் நிலையிலு ஐந்தவத்தை -களை அடையும். அவை கருவளர் அவத்தைகளாம்.) 
வித்தில் நின்ற உயிரை முளையாகிய உடம்போடு முதற்கண் கலக்கச் செய்வதாகிய 'காரண சரீரம்', அல்லது, 'ஆனந்தமயகோசம்' எனப்படுகின்ற மாயா தத்துவத்தோடு உயிர்தொடர்பு கொள்வதே கருவினில் துரியாதீதம். பின்பு 'கஞ்சுக சரீரம்' அல்லது, 'விஞ்ஞானமய கோசம்' - எனப்படுகின்ற, அராகம் முதலிய ஐந்து தத்துவங்களோடு உயிர் தொடர்பு கொள்வதே கருவினில் துரியம். பின்பு, 'குணசரீரம்', அல்லது, 'மனோமய கோசம்' எனப்படுகின்ற மூலப் பிரகிருதியோடு உயிர் தொடர்பு கொள்வதே கருவினில் சுழுத்தி. பின்பு, 'சூக்கும சரீரம்', அல்லது 'பிராணமய கோசம்' எனப்படுகின்ற சித்தம் ஒழிந்த அந்தக்கரணம் மூன்று, தன்மாத்திரை ஐந்து ஆக எட்டுத் தத்துவங் களோடு உயிர் தொடர்பு கொள்வதே கருவினில் சொப்பனம். (சித்தம் பிரகிருதியில் அடங்கும்.) பின்பு, 'தூல சரீரம்', அல்லது அன்னமய கோசம்' எனப்படுகின்ற ஞானேந்திரியம் ஐந்து, கன்மேந்திரியம் ஐந்து, மாபூதம் ஐந்து ஆகப் பதினைந்து தத்துவங்களோடு உயிர் தொடர்பு கொள்வதே கருவினில் சாக்கிரம்.`,
  },
  {
    id: 2260, tantraId: 8, verseNumber: 2259,
    tamil: `ஆணவம் ஆகும் அதிதம்மேல் மாயையும்
பூணும் துரியம் சுழுத்திபொய்க் காமியம்
பேணும் கனவும் மாமாயை திரோதாயி
காணும் நனவில் மலக்கலப்பு ஆகுமே`,
    transliteration: `āṇavam ākum atitammēl māyaiyum
pūṇum turiyam cuḻuttipoyk kāmiyam
pēṇum kaṉavum māmāyai tirōtāyi
kāṇum naṉavil malakkalappu ākumē`,
    english: `2259: Malas for Jiva in Different States of Consciousness
In (Kevala) Atita State
Anava is;
In Turiya State
Maya too is;
In Sushupti State
Seed of Karma,
Kamya; an addition is;
In Dream State
Mamaya (Illusory perception) also is;
In Waking State
Tirodayi joins (Obfuscations);
Thus are the Five Malas
To Jiva in Sakala State attached.`,
    elaborationTamil: `துரியாதீத நிலையில் உயிருக்கு ஆணவ மலம் மட்டுமே இருக்கும். அதற்குமேலே உள்ள தான துரிய நிலையில் அதனோடு வித்தியா தத்துவங்களில் தோற்ற முறையில் முதலிலே உள்ள மாயா தத்துவம் வந்து பற்றும். அடுத்து நிகழும் சுழுத்திய வத்தையில் நல்லனவும் தீயனவும் ஆகரிய காரிய கன்மங்கள் வந்து பற்றும். (இதனால், கால தத்துவமும், நியதி தத்துவமும் பற்றுதல் பெறப்படும்) அடுத்து நிகழும் சொப்பனத்தில் மேற்கூறிய கன்மங் களுக்கு ஏற்பமாயா காரியங்களான கலை முதல் நிலம் ஈறான ஏனை எல்லாத் தத்துவங்களும் வந்து பற்றும். (ஆகவே, சுத்த தத்துவங்கள் வந்து பற்றுதலும் தானே அமைந்தது.) இறுதியாக நிகழும் சாக்கிரத்தில், முன்பு நான்கு மலங்களும் பற்றிக்கொண்டதனால் அவை அனைத் -தையும் செலுத்துகின்ற திரோதான மலம் வந்து பற்றும். (என்றது, 'அனைத்தையும் முழுமையாக நடத்தும்' என்றபடி.) ஐந்தவத்தை -களிலும் ஐந்து மலங்கள் இம்முறையில் உயிரை வந்து பற்றுவனவாம்.`,
  },
  {
    id: 2261, tantraId: 8, verseNumber: 2260,
    tamil: `அரன்முத லாக அறிவோன் அதீதத்தன்
அரன்முத லாமாயை தங்கிச் சுழுனை
கருமம் உணர்ந்து மாமாயைக் கைகொண்டோ ர்
அருளும் அறைவார் சகலத்துற் றாரே`,
    transliteration: `araṉmuta lāka aṟivōṉ atītattaṉ
araṉmuta lāmāyai taṅkic cuḻuṉai
karumam uṇarntu māmāyaik kaikoṇṭō r
aruḷum aṟaivār cakalattuṟ ṟārē`,
    english: `2260: Malas Restated
The Jiva in Atita State,
Realizes Primal Para;
The Jiva in Turiya stands in Maya (Suddha),
That has its beginning in Hara;
In Sushupti Karma Mala comes in;
In Dream State Mamaya (Asuddha) envelops,
In Waking State comes Tirodayi, that obfuscates
Thus the Jiva in Sakala State stands.`,
    elaborationTamil: `'ஆணவம் அதீதத்தில் பற்றும்' என முன் மந்திரத்தில் கூறினமையால், அந்நிலையை மட்டும் உடையராய் அதிலே நிற்பவர்கள், 'சிவபெருமான் முதல்வன்' என உணரும் உணர்வை இழவார். (இவர்கள் விஞ்ஞான கலரே.) 
'மாயா தத்துவம் துரியத்தில் வந்து பற்றும்' என்றும், 'வித்தியா தத்துவங்களில் காலமும், நியதியும் வந்து பற்றும்' என்றும் முன் மந்திரத்தில் கூறினமையால், அந்த இரண்டில் நிற்பவர்களும் மேற் கூறப்பட்டவர்போல, 'சிவபெருமானே முதல்வன்' என்னும் உணர்வை இழத்தல் இல்லை. (இவர்கள் இருதிறத்தினரும் தம்முட் சிறிது வேறுபாடுடைய பிரளயாகலரே. இவர்களில் பின்னவர் புருட தத்துவத்திற்குச் சிறப்பு ஏதுவாய் நிற்கும் கலை, வித்தை, அராகங்களைப் பொதுமையாக அன்றிச் சிறப்பாக உடையராகார் என்பது நாயனார் கருத்து - என்க. 'கருவில் அதீதம்' என்னும் மந்திரத்திற் கூறியவற்றிற்கும், அடுத்து முன் மந்திரத்திற் கூறிய வற்றிற்கும் சிறிது வேறுபாடு உண்டென்க.) 
'கலை முதலிய ஏனை எல்லாத் தத்துவங்களும் சொப்பனத்தில் வந்து பற்றும்' - என்று முன் மந்திரத்தில் கூறப் பட்டமையால், அவர்கள், 'தமக்கொரு தலைவன் உளன்' என்பதையே அறியார். இவர்கள் சகல வருக்கத்தினரே.`,
  },
  {
    id: 2262, tantraId: 8, verseNumber: 2261,
    tamil: `உருவுற்றுப் போகமே போக்கியம் துற்று
மருவுற்றுப் பூதம னாதியான் மன்னி
வரும்அச் செயல்பற்றிச் சத்தாதி வைகிக்
கருவுற் றிடுஞ் சீவன் காணும் சகலத்தே`,
    transliteration: `uruvuṟṟup pōkamē pōkkiyam tuṟṟu
maruvuṟṟup pūtama ṉātiyāṉ maṉṉi
varumac ceyalpaṟṟic cattāti vaikik
karuvuṟ ṟiṭuñ cīvaṉ kāṇum cakalattē`,
    english: `2261: Condition of Sakala State
They get body-form
And experience enjoyments diverse;
They are by elements pervaded
And conjoined to Mind and rest of cognitive organs;
They get attached to Karmas
They abide in Tanmatras
Thus are they born
--These Jivas in Sakala State.`,
    elaborationTamil: `'கருவில் அதீதம்'l என்னும் மந்திரத்திற் கூறியபடி கருவிலேயே பல அவத்தைகளை அடைந்த உயிர், பின்பு பலருங்காணப் பிறந்து, சகலாவத்தையில் பூதம் முதலிய புறக் கருவிகளாலும், மனம் முதலிய அகக் கருவிகளாலும் செய்தற் குரிய செயல்களை மேற்கொண்டு, பல போக்கியப் பொருள்களில் பொருந்தி, ஓசை முதலிய புலன்களில் மூழ்கிப் பலவகை அனுபவங்களை அனுபவிப்பதாய்க் காணப்படும்.`,
  },
  {
    id: 2263, tantraId: 8, verseNumber: 2262,
    tamil: `இருவிடை ஒத்திட இன்னருள் சத்தி
மருவிட ஞானத்தில் ஆதனம் மன்னிக்
குருவினைக்கொண்டருள் சத்திமுன் கூட்டிப்
பெருமலம் நீங்கிப் பிறவாமை சுத்தமே`,
    transliteration: `iruviṭai ottiṭa iṉṉaruḷ catti
maruviṭa ñāṉattil ātaṉam maṉṉik
kuruviṉaikkoṇṭaruḷ cattimuṉ kūṭṭip
perumalam nīṅkip piṟavāmai cuttamē`,
    english: `2262: Sakala Jiva'a Journey to Suddha State
They reach the State
When deeds good and bad
Equable become (Iruvinai Oppu);
When Sakti's Grace
On them descends (Sathini Padam);
When on the pedestal of Grace
They thus get seated,
Then with the aid of Guru Holy
They reach the Presence of Sakti's Grace;
Finally rid of the Primordial Mala (Anava)
They reach the State of Suddha
That no birth thereafter gives.`,
    elaborationTamil: `உயிர்கள் தமக்கு இருவினையொப்பு வாய்க்கப் பெற்ற பொழுது சிவனது சத்தி முன்பு பிறவித் துன்பத்தைத் தரும் திரோதான சத்தியாய் இருந்த நிலைமை மாறி, வீட்டின்பத்தைத் தரும் அருட்சத்தியாகித் தங்கள் அறிவில் பதியப் பெற்று, அதனானே மெய்யுணர்வு வேட்கை நிலைத்து நிற்க அவ்வேட்கை மிகுதியால் ஞான குருவை அடைந்து அவர் உபதேசித்த முறைப்படி தம்மைச் சிவனது அருட்சத்தியின் வழிப்படுத்திக் கொண்டு, அதனாலே எல்லா மலங்களும் நீங்கப் பெற்று, மீட்டும் பிறவா நிலையில் நிற்பதே சுத்தாவத்தையாம்.`,
  },
  {
    id: 2264, tantraId: 8, verseNumber: 2263,
    tamil: `ஆறாறும் ஆறதின் ஐ ஐந்து அவத்தையோடு
ஈறாம் அதீதத் துரியத்து இவன்எய்தப்
பேறான ஐவரும் போம்பிர காசத்து
நீறார் பரம்சிவம் ஆதேய மாகுமே`,
    transliteration: `āṟāṟum āṟatiṉ ai aintu avattaiyōṭu
īṟām atītat turiyattu ivaṉeytap
pēṟāṉa aivarum pōmpira kācattu
nīṟār paramcivam ātēya mākumē`,
    english: `2263: Turiyatita is the State Ultimate
With Tattvas six times six
And Avastas of ten states
He, Jiva, enters the final state
Of Turiyatita,
Then will the Divine Gift be (Mukti);
And Jiva merges into the Light Resplendent;
Which the Five Gods reach;
There, the Siva of Holy Ashes,
Jiva's Refuge Final are.`,
    elaborationTamil: `முப்பத்தாறாகச் சொல்லப்படுகின்ற கருவிகளே அவத்தை வேறுபாடுகட்குக் காரணம். அந்தக் காரணத்தின்வழிக் காரியமாய் நிகழும் அவத்தைகள் இருபத்தைந்து. (கேவலம், சகலத்திற் கேவலம், சகலத்திற் சகலம், சகலத்தில் சுத்தம், நின்மலம் ஆகிய ஐந்தில் ஒவ்வொன்றிலும் சாக்கிரம் முதலிய ஐந்து.) அந்த இருபத்தைந்தில் முடிவாய் உள்ளது சுத்த துரியாதீதம். அதனை உயிர் அடைந்த பொழுது, ஐந்தொழில் தலைவர்களாகிய ஐவரும் அதனைத் தடை செய்யாது இருக்க, அவ்விடத்து மிக்கு விளங்கும் அருள் ஞான ஒளியினால், அனைத்துயிர்கட்கும் முடிவான புகலிடமாய் உள்ள பரசிவனது பேரின்பம் அதன் அறிவினுள்ளே பொங்கித் ததும்பும்.`,
  },
  {
    id: 2265, tantraId: 8, verseNumber: 2264,
    tamil: `தன்னை அறியாது உடலைமுன் தான்என்றான்
தன்னைமுன் கண்டான் துரியம் தனைக்கண்டான்
உன்னும் துரியமும் ஈசனோடு ஒன்றாக்கால்
பின்னையும் வந்து பிறந்திடும் தானே`,
    transliteration: `taṉṉai aṟiyātu uṭalaimuṉ tāṉeṉṟāṉ
taṉṉaimuṉ kaṇṭāṉ turiyam taṉaikkaṇṭāṉ
uṉṉum turiyamum īcaṉōṭu oṉṟākkāl
piṉṉaiyum vantu piṟantiṭum tāṉē`,
    english: `2264: Self-Realization Only in Turiya State--It Is Not Ultimate
Knowing not the Self,
Jiva deemed body as the Self;
When he saw the Real Self;
He attained Turiya State;
But even in that Turiya State,
If he, Jiva, with Lord united not,
He will again born be, here below.`,
    elaborationTamil: `சகலாவத்தையில் தன்னை உடம்பின் வேறாக உணராமல், உடம்பையே ''தான்'' என உணர்ந்து நின்றவன், சுத்தா வத்தையை ஓரளவேனும் அடைந்த பின்பே தன்னை உடம்பின் வேறு பட்ட பொருளாக உணர்ந்தான். பின்பு சுத்தத்தில் துரிய நிலையை அடைந்து, சிவனது அருளை உணர்ந்தான். ஆயினும் அதனையும் கடந்த சுத்த துரியாதீதத்தை அடைந்து சிவனை உணர்ந்து அவனோடு இரண்டறக் கலவாது, துரியத்திலேயே அவன் இருந்துவிடுவானாயின், உடம்பு நீங்கிய பின், மீளவேறோர் உடம்பை எடுத்தலும் கூடும்.`,
  },
  {
    id: 2266, tantraId: 8, verseNumber: 2265,
    tamil: `சாக்கிரத் தன்னில் அதீதம் தலைப்படில்
ஆக்கிய அந்த வயிந்தவம் ஆனந்தம்
நோக்கும் பிறப்புஅறும் நோன்முத்தி சித்தியாம்
வாக்கும் மனமும் மருவல்செய் யாவே`,
    transliteration: `cākkirat taṉṉil atītam talaippaṭil
ākkiya anta vayintavam āṉantam
nōkkum piṟappuaṟum nōṉmutti cittiyām
vākkum maṉamum maruvalcey yāvē`,
    english: `2265: Only With Turiyatita State Birth Cycle Ends
If in Waking State
The Jiva realizes the Atita State
The Vaindavas (the Tattvas) that Maya caused
Will their malevolence shed;
The birth's whirl will cease;
Goodly Mukti and Siddhi then attained;
Speech and thought cease to be.`,
    elaborationTamil: `புருவ நடுவிற்றானே திருவருளால் சிவத்தைத் தலைப்படும் சாக்கிரம் முதலிய அவத்தைகளில் முடிவான அதீத நிலை கைகூடுமாயின், பாச ஞானத்தை உண்டாக்க வந்த வாக்காகிய மயக்கும் பொருள் கெடும். அது கெடவே, 'இனியும் வருங்கொல்' என எதிர்நோக்கி அஞ்சப் படுவதாகிய பிறப்பு, வாராதே ஒழியும். அதனால் பரமுத்தி நிலை கிடைக்கும். எவ்வாறெனில் அவ்விடத்தில் பாச ஞான பசு ஞானங்கள் தோன்ற மாட்டா ஆகையால்,`,
  },
  {
    id: 2267, tantraId: 8, verseNumber: 2266,
    tamil: `அப்பும் அனலும் அகலத்து ளேவரும்
அப்பும் அனலும் அகலத்து ளேவாரா
அப்பும் அனலும் அகலத்துள் ஏதெனில்
அப்பும் அனலும் கலந்ததுஅவ் வாறே`,
    transliteration: `appum aṉalum akalattu ḷēvarum
appum aṉalum akalattu ḷēvārā
appum aṉalum akalattuḷ ēteṉil
appum aṉalum kalantatuav vāṟē`,
    english: `2266: Beyond Turiyatita is Void
In the void beyond the Atita State,
Sakti (Water) and Siva (Fire) will appear,
Water and Fire do not together in space appear,
How then does Water and Fire in Void appear?
That way are they mingled
Sakti (Water) and Siva (Fire), there.`,
    elaborationTamil: `'இன்பம், துன்பம்' என்னும் இரண்டும் உலக உணர்வே நிகழும் சகலாவத்தையில் நிலையின்றி, மாறி மாறித் தோன்றும். அகலாவத்தையாகிய சுத்தாவத்தையில் அவை தோன்றவேமாட்டா. 'சகலாவத்தையில் அவை தோன்றுதல் ஏன்' எனில், இன்பம், துன்பம் இரண்டும் கலந்ததுதான் சகலாவத்தை.`,
  },
  {
    id: 2268, tantraId: 8, verseNumber: 2267,
    tamil: `அறுநான்கு அசுத்தம் அதிசுத்தா சுத்தம்
உறும்ஏழு மாயை உடன்ஐந்தே சுத்தம்
பெறுமாறு இவைமூன்றும் கண்டத்தால் பேதித்து
உறும்மாயை மாமாயை ஆன்மாவி னோடே`,
    transliteration: `aṟunāṉku acuttam aticuttā cuttam
uṟumēḻu māyai uṭaṉaintē cuttam
peṟumāṟu ivaimūṉṟum kaṇṭattāl pētittu
uṟummāyai māmāyai āṉmāvi ṉōṭē`,
    english: `2267: 36 Tattvas Reckoned as (5) Pure, (7) Pure-Impure and (24) Impure
Of Tattvas,
Six times four are Asuddha (Impure)
Seven are Suddha-Asuddha (Misra or Pure-Impure)
Five with Pure Maya are Suddha (Pure)
These in three divisions are thus parted
As Suddha (Pure), Suddha-Asuddha (Pure-Impure), and Asuddha (Impure)
All these with Jiva at appropriate stages stand.`,
    elaborationEnglish: `Out of the 36 tattvas enumerated in the Saiva Siddhanta school of philosophy, 24 are considered as atma tattvas. They belong to this world and are pervaded by prakriti maya.

Purusa, the experient sol, is considered as another tattva. Here he is counted -with the next category of vidya tattvas, which are six in number. They belong to higher knowledge, and are under the influence of misra (mixed) or pure/impure maya. In all; the tattvas in this sphere are numbered here as seven.

The next five tattvas are known as Siva tattvas. They are pervaded’ by pure maya. They are of the spiritual sphere, par-excellence. Paraparam, or the Supreme, is above the 36 tattvas.

Tattvas are universal principles evoluted from maya — pure, pure/impure, and impure — which may affect the soul in its journey to God.`,
    elaborationTamil: `முப்பத்தாறு தத்துவங்களில் கீழ் உள் ஆன்ம தத்துவம் இருபத்து நான்கும் அசுத்த தத்துவங்களாகும். அவை அவ் வியத்தமாகிய மூலப்பிரகிருதியினின்றும் நோறி ஒடுங்கும். இடையில் உள்ள வித்தியா தத்துவம் ஏழும் மிச்சிர தத்துதவமாகும். அவை அசுத்த மாயையினின்றும் தோன்றி ஓடுங்கும். மேலே உள்ள சிவ தத்துவம் ஐந்தும் சுத்த தத்துவங்களாகும். அவை சுத்த மாயை யினின்றும் தோன்றி ஒடுங்கும். இம் மூவகைத் தத்துவங்களும் மூன்று காண்டங்களாய்ப் பிரிந்து ஆன்மாவோடு கூடி, அதற்கு அறிவிச்சை செயல்கள் நிகழக் கருவிகளாய் நிற்கும்.`,
  },
  {
    id: 2269, tantraId: 8, verseNumber: 2268,
    tamil: `மாயைகைத் தாயாக மாமாயை ஈன்றிட
ஆய பரசிவன் தந்தையாய் நிற்கவே
ஏயும் உயிர்க்கே வலசகலத்து எய்தி
ஆய்தரு சுத்தமும் தான்வந்து அடையுமே`,
    transliteration: `māyaikait tāyāka māmāyai īṉṟiṭa
āya paracivaṉ tantaiyāy niṟkavē
ēyum uyirkkē valacakalattu eyti
āytaru cuttamum tāṉvantu aṭaiyumē`,
    english: `2268: The Journey from Kevala to Suddha Through Sakala States
Siva as Father, Maya (Pure) as Mother and Mamaya (Impure) as Nurse
Parasiva for father;
Maya (Pure) for mother;
Mamaya (Impure) for nurse;
Thus does Jiva
Its birth take,
And journeying the states of Kevala, and Sakala
Final reaches the Suddha State.`,
    elaborationTamil: `சிவனே எல்லாம் செய்பவன் ஆகையால், உலக மாகிய மகவிற்கு அவனை, 'தந்தை' எனலாம். உலகிற்கு முதற் காரணமான 'சுத்த மாயை, அசுத்த மாயை' என்னும் இரு மாயைகளுள் சுத்த மாயையையே சிவன் தான் நேரே பற்றிச் செயற்படுத்துதலால் அதனைச் சிவனோடு புணர்ந்து உலகமாகிய மகவை ஈன்ற, 'நற்றாய்' எனலாம்; அசுத்த மாயையைச் சிவன் தான் நேரே பற்றிச் செயற் படுத்தாமல், அனந்த தேவரைக் கொண்டும், அவர்வழியாகச் சீகண்ட உருத்திரரைக் கொண்டும் செயற்படுத்துதலால் அதனை, உலகமாகிய மகவை வளர்க்கும் 'செவிலித் தாய்' எனலாம். எனவே, சுத்த மாயை, அசுத்த மாயை என்னும் இரு முதற் காரணங்களாலும், சிவனாகிய கருத்தாவினாலும் உலகம் தோன்றி நிலை பெற, உயிர்கள் அவ் வுலகத்தைப் பற்றி நின்று, 'சகலம், கேவலம்' என்னும் இருநிலைகளில் மாறி மாறி உழன்று, முடிவில் சிவனது அருளாலே ஞானத்தைப் பெற்று, அவற்றினினின்றும் விடுதலை அடைந்து சுத்த நிலையை அடையும்.`,
  },
  {
    id: 2270, tantraId: 8, verseNumber: 2269,
    tamil: `அஞ்சும் கடந்த அனாதி பரன்தெய்வம்
நெஞ்சம தாய நிமலன் பிறப்பிலி
விஞ்சும் உடலுயிர் வேறு படுத்திட
வஞ்சத் திருந்த வகையறிந் தேனே`,
    transliteration: `añcum kaṭanta aṉāti paraṉteyvam
neñcama tāya nimalaṉ piṟappili
viñcum uṭaluyir vēṟu paṭuttiṭa
vañcat tirunta vakaiyaṟin tēṉē`,
    english: `2269: Mystery of Parting Life From Body
The Lord is the Para;
He is beginningless;
He is beyond five states of experience,
He is the Pure One,
Seated within the heart;
He is birthless;
Why this lovely body and life
He parts--
That mystery, I knew.`,
    elaborationTamil: `உருவம் இரண்டு, (வித்தை, ஈசுரன்) உருவாருவம் ஒன்று, (சதாசிவன்) அருவம் இரண்டு (சத்தி, சிவன்) ஆகமுத்திறத்து ஐந்துநிலைகளையும் கடந்து, தன்னியல்பில் நிற்கும் பரசிவனே சுத்த சிவன். (மேற்கூறிய ஐந்தும் அபர சிவங்களாம்.) பரசிவன் - மனத்தையும் கடந்தவன். இயல்பாகவே மலங்கள் இல்லாதவன். எனவே, மாயா சரீரங்களை எடாதவன். ஆகவே, அவன் (தனது திருவருள் காரணமாக) மலங்களுட் பட்டனவாயினும் உண்மையில் அவற்றினும் மேற்பட்ட உயிர்களை முன்னர் மாயாகாரியமாகிய உடலோடு ஒன்று படுத்திப் பின்பு அதனினின்றும் வேறுபடுத்தி உய்வித்தற் பொருட்டு அவ்வுயிர்கள் தன்னை அறியாதபடி அவற்றின் அறிவினுள்ளே கள்வன் போல ஒளித்திருந்தான். எனினும், அவனது கள்ளத்தை நான் அவன் அருளாலே அறிந்து கொண்டேன்.`,
  },
  {
    id: 2271, tantraId: 8, verseNumber: 2270,
    tamil: `சத்தி பராபரம் சாந்தி தனிலான
சத்தி பரானந்தம் தன்னில் சுடர்விந்து
சத்திய மாயை தனுச்சத்தி ஐந்துடன்
சத்தி பெறுமுயிர் தான்அங்கத்து ஆறுமே`,
    transliteration: `catti parāparam cānti taṉilāṉa
catti parāṉantam taṉṉil cuṭarvintu
cattiya māyai taṉuccatti aintuṭaṉ
catti peṟumuyir tāṉaṅkattu āṟumē`,
    english: `2270: Saktis are Dynamic Aspects of Static Parapara
Sakti in Parapara is Para Sakti;
Sakti in Santhi is Chit Sakti;
Sakti in Paranand is Icca Sakti;
Sakti in luminous Bindu is Jnana Sakti;
Sakti in Maya is Kriya Sakti;
When Jiva these Saktis receive,
Then it reposes integral in the Divine.`,
    elaborationTamil: `(குண குணிகட்குத் தம்முன் வேற்றுமை யின்மையால்,) 'சத்தியே சிவம்' என்று கூறலாம். எனினும், சத்தியை ஆள்வது பொருளேயாதலின், சிவத்தினின்றே சத்தி தோன்றுகின்றது. (அஃதாவது செயற்படுகின்றது.) அதனால் உயிர்கட்கு, அமைதியைத் தருவதும், மேலான ஆனந்தமாய் விளைவதும் பராசத்தியே. இனி அந்தச் சத்தியினால் தான் சுத்தமாயையாகிய சத்தி காரியப்படுகின்றது. அது காரியப்படும் நிலையில் சிவசத்தி, 'பரை, ஆதி, இச்சை, ஞானம், கிரியை' என ஐந்தாய் இருக்கும். அந்த ஐந்துடனும் கூடுவதனாலே தான் உயிர் ஆற்றலைப் பெறுகின்றது. ஆகவே, உயிர் அமைதியை அடைந்து, ஆனந்தத்தைப் பெறுவது பரையாகிய சத்தியிடத்தில்தான்.`,
  },
  {
    id: 2272, tantraId: 8, verseNumber: 2271,
    tamil: `ஆறாறுக்கு அப்பால் அறிவார் அறிபவர்
ஆறாறுக்கு அப்பால் அருளார் பெறுபவர்
ஆறாறுக்கு அப்பால் அறிவாம் அவர்கட்கே
ஆறாறுக்கு அப்பால் அரன்இனி தாமே`,
    transliteration: `āṟāṟukku appāl aṟivār aṟipavar
āṟāṟukku appāl aruḷār peṟupavar
āṟāṟukku appāl aṟivām avarkaṭkē
āṟāṟukku appāl araṉiṉi tāmē`,
    english: `2271: Beyond Tattvas is Divine Bliss
They who know Him
Beyond the Tattvas six times six
Truly know Him;
Beyond the Tattvas six times six
They receive His Grace;
They who have Knowledge True
Beyond the Tattvas six times six
Only to them, is He the Divine Bliss;
He the Hara
That is beyond the Tattvas,
Six times six.`,
    elaborationTamil: `முப்பத்தாறு தத்துவங்களும் சடமேயாதலின் சித்தாகிய பரம்பொருள் அத்தத்துவங்கள் அனைத்திற்கும் அப்பாற் பட்டதாம். (அந்தப் பரம் பொருளை யடைதலே பராவத்தை) இந்தச் சடசித்துக்களைப் பகுத்து, சித்தின் இயல்பை அறிபவரும் அரியர். அந்தச் சித்துப் பொருளின் குணமே அருள் ஆதலின், அப்பொருளை அறிந்து அருளைப் பெறுபவரும் அரியர். உயிர் சார்ந்ததன் வண்ணமாம் இயல்புடையது. ஆகலின், அறிவே வடிவான பரம் பொருளைச் சார்ந்து அறிவே வடிவாய்விட்ட அவர்கட்குத்தான் சிவன் அளவிலா இன்பப் பொருளாய் இன்புறுத்துவான்.`,
  },
  {
    id: 2273, tantraId: 8, verseNumber: 2272,
    tamil: `அஞ்சொடு நான்கும் கடந்துஅக மேபுக்குப்
பஞ்சணி காலத்துப் பள்ளி துயில்கின்ற
விஞ்சையர் வேந்தனும் மெல்லிய லாளொடு
நஞ்சுற நாடி நயம்செய்யு மாறே`,
    transliteration: `añcoṭu nāṉkum kaṭantuaka mēpukkup
pañcaṇi kālattup paḷḷi tuyilkiṉṟa
viñcaiyar vēntaṉum melliya lāḷoṭu
nañcuṟa nāṭi nayamceyyu māṟē`,
    english: `2272: When Jiva is Rid of Malas by Siva-Sakti
Transcending the organs five (external)
And the four (internal),
In the (union) within of five (states) avastas,
The Jiva slumbers;
Then does the wondrous Lord
Appearing with Sakti of slender Form
Rid the Jiva of its poisons (Malas),
Forever to rejoice.`,
    elaborationTamil: `வித்தியா தத்துவங்கட்கு முதற் காரணமாய் உள்ள அசுத்த மாயையைக் கடந்து சிவத்துவத்தை அடைந்தமையால் 'வித்தியாதரர்கட்குத் தலைவன்' எனச் சொல்லுதற்குரியசாதகன், பிராசாதகலைகளில் ஒன்பதைக் கடத்தலால், சுத்த மாயாகாரியங் களையும் கடந்த ஒருநிலையைப் பெற்றுப் பத்தாம் கலையாகிய வியாபினி கலையில் நின்று, அருட் சத்தியை வஞ்சம் அற்ற நெஞ்சுடன் நாடுவானாயின் அஃது, ஒன்பது அடுக்குக்களுக்கு மேல் உள்ள பத்தாவது மாடியில், காலில் செம்பஞ்சு ஊட்டுதல் முதலிய ஒப்பனை களுடன் கட்டிலில் உறங்குகின்ற தலைவியைத் தலைவன் அடைந்து, அவளோடு இனிய சொற்களைக் கூறுவது போன்றதாகும்.`,
  },
  {
    id: 2274, tantraId: 8, verseNumber: 2273,
    tamil: `உரிய நனாத்துரி யத்தில் இவளாம்
அரிய துரிய நனவாதி மூன்றில்
பரிய பரதுரி யத்தில் பரனாம்
திரிய வரும்துரி யத்தில் சிவமே`,
    transliteration: `uriya naṉātturi yattil ivaḷām
ariya turiya naṉavāti mūṉṟil
pariya paraturi yattil paraṉām
tiriya varumturi yattil civamē`,
    english: `2273: Beyond Turiya is Turiya-Turiya or Para Turiya; and Para-
atita Turiya
is Further Beyond
In Jagra-Turiya State
The Jiva realizes Self;
Then beyond are States
Turiya-Jagrat, Turiya Svapna, Turiya Sushupti, and Turiya-Turiya
In that Para Turiya State the Jiva is Para;
In the Turiya State still beyond, (Para-Turiya-atita)
Jiva becomes Siva.`,
    elaborationTamil: `எளிதில் இயல்பாக நிகழும் சகல சாக்கிர துரியம் போலவே, அரிதில் சாதித்து அடைவதாகிய நின்மல துரியத்திலும் ஆன்மா, ஆன்மாவாய்த்தான் இருக்கும். ஆயினும், வியாபகமாகிய பர துரியத்தில் அது மேல்நிலையை அடையும். அந்தத் துரியம் வேறுபட நிகழ்கின்ற பரதுரியாதீதத்தில் தான் ஆன்மாச் சிவமாம் தன்மையை அடையும்.`,
  },
  {
    id: 2275, tantraId: 8, verseNumber: 2274,
    tamil: `பரமாம் அதீதமே பற்றறப் பற்றப்
பரமாம் அதீதம் பயிலப் பயிலப்
பரமாம் அதீதம் பயிலாத் தபோதனார்
பரமாகார் பாசமும் பற்றொன்றுஅ றாதே`,
    transliteration: `paramām atītamē paṟṟaṟap paṟṟap
paramām atītam payilap payilap
paramām atītam payilāt tapōtaṉār
paramākār pācamum paṟṟoṉṟua ṟātē`,
    english: `2274: In Para-atita Turiya State Jiva Becomes Beyond-Param
In desire bereft of desires,
As Jiva aspires to Para-atita-turiya State
And steadfast perseveres in it,
He becomes Beyond-Param (Siva);
The tapasvins who practise not
Will never Param become;
They are forever fettered
In Pasas several.`,
    elaborationTamil: `'பராவத்தையிலும் அதன் முடிநிலையாகிய அதீதத்தை அடைதல் வேண்டும்' எனக் கூறுதல், சிறிதே எஞ்சி நிற்கும் மலவாசனை நீங்குதற் பொருட்டாம். (வாசனை, 'இலய மலவாசனை' என்க.) இனி அந்த அதீதத்தைத் தலைப்பட்ட பின்பும் விடாது தொடர்ந்து அதிற்றானே பழகிப் பழகியிருந்தால்தான், ஆன்மாச் சிவமாம் தன்மையைப் பெறும். ஆகவே, அதில் அவ்வாறு தொடர்ந்து பழகா தவர்கள் எத்துணைச் சாதகங்களைச் செய்தவராயினும் அவர் சிவமாம் தன்மையை அடையார். அத்தன்மையை அடையாமையால், சிறிதளவு எஞ்சி நின்ற பாசமும் நீங்காமல் இருந்துக் கொண்டேயிருக்கும்.`,
  },
  {
    id: 2276, tantraId: 8, verseNumber: 2275,
    tamil: `ஆயும்பொய்ம் மாயை அகம்புற மாய்நிற்கும்
வாயு மனமும் கடந்துஅம் மயக்கறின்
தூய அறிவு சிவானந்த மாகிப்போய்
வேயும் பொருளாய் விளைந்தது தானே`,
    transliteration: `āyumpoym māyai akampuṟa māyniṟkum
vāyu maṉamum kaṭantuam mayakkaṟiṉ
tūya aṟivu civāṉanta mākippōy
vēyum poruḷāy viḷaintatu tāṉē`,
    english: `2275: Freed of Maya, Jnana Dawns and Bliss Ensues
The Maya we seek to understand
Envelops Soul, inside and out;
The hypnosis it creates baffles thought and word;
When you are freed from it,
Your knowledge becomes purified;
It is transmuted into Sivananda
And becomes a protective roof over you.`,
    elaborationTamil: `பல சமயத்தாராலும், 'எத்தன்மைத்து' என ஆராயப் படுவதாய், அருவமாய் நிற்கும்மாயை, சிவத்திற்கு வேறும் ஆகாமல், ஒன்றும் ஆகாமல் இடைப்பட்டதாய் இருக்கும். அதனால், வாக்கு மனங்கள் நீங்கிய பின்பும் வாசனை யளவாய் நிற்கின்ற அந்த மாயை அறவே நீங்கினால், அறிவு முழுத் தூய்மை அடைந்து, அதனால் சிவானந்த மயமாகிப் பின்பு அந்தச் சிவானந்தத்தால் விழுங்கப்பட்ட பொருளாகிவிடும்.`,
  },
  {
    id: 2277, tantraId: 8, verseNumber: 2276,
    tamil: `துரியப் பரியில் இருந்தஅச் சீவனைப்
பெரிய வியாக்கிரத் துள்ளே புகவிட்டு
நரிகளை ஓடத் துரத்திய நாதர்க்கு
உரிய வினைகள் நின்று ஓலமிட் டன்றே`,
    transliteration: `turiyap pariyil iruntaac cīvaṉaip
periya viyākkirat tuḷḷē pukaviṭṭu
narikaḷai ōṭat turattiya nātarkku
uriya viṉaikaḷ niṉṟu ōlamiṭ ṭaṉṟē`,
    english: `2276: From Turiya to Turiyatita
The Jiva was in Turiya State;
Unto a swift steed
Was into the Turiyatita Jagra State led;
The Master
Thus had the (Karmic) jackals chased away;
And the Karmas stood howling,
Disappointed sore.`,
    elaborationEnglish: ``,
    elaborationTamil: `பர துரியமாகிய குதிரைமேல் ஏறிய ஆன்மா, அதனை விடுத்து, அதற்குமேல் உள்ள அதீதமாகிய புலிக்குள் தன்னைப் புகவிடுமாயின், புலியால் கௌவிக் கொள்ளப்பட்ட ஆட்டினை நரிகள் பற்ற மாட்டாது அஞ்சி ஒடிவிடுதல் போல, அந்த ஆன்மாவை மாயாகாரியங்களாகிய தத்துவங்கள் அணுகமாட்டாது நீங்கிவிடும். (அஃதாவது, 'செயல் இழந்துவிடும்' என்பதாம்) மாயா கருவிகள் நீங்கினமையால் பிராரத்த கன்மம் வந்து பற்றமாட்டாது ஒழியும்.`,
  },
  {
    id: 2278, tantraId: 8, verseNumber: 2277,
    tamil: `நின்றஇச் சாக்கிர நீள்துரி யத்தினின்
மன்றனும் அங்கே மணம்செய்ய நின்றிடும்
மன்றன் மணம்செய்ய மாயை மறைந்திடும்
அன்றே இவனும் அவன்வடி வாமே`,
    transliteration: `niṉṟaic cākkira nīḷturi yattiṉiṉ
maṉṟaṉum aṅkē maṇamceyya niṉṟiṭum
maṉṟaṉ maṇamceyya māyai maṟaintiṭum
aṉṟē ivaṉum avaṉvaṭi vāmē`,
    english: `2277: In Turiyatita State Jiva Becomes Siva
In this Turiyatita Jagrat State
The Lord of Dance with Jiva in union stands
When that union takes place
Maya vanishes away;
That very day Jiva attains Siva Form.`,
    elaborationTamil: `இங்குச் சொல்லிவாராநின்ற இந்தச் சாக்கிரமுதலிய அவத்தைகளில் துரியத்தை அடைந்த போதிலும் சிவன் அனைத்தும் கடந்த வெற்ற வெளியான அதீத நிலையில் இருப்பவன் ஆதலால், அவ்விடத்திலே உயிரைக் கூட இருப்பான். (துரியத்தில் வந்துகூட மாட்டான்.) அவன் உயிரைக் கூடினால்தான் உயிர்க்கு உலக உணர்வு மறையும். அப்பொழுது அது சிவ உணர்வு ஒன்றேயுடையதாய்ச் சிவமாகும். (எனவே 'உயிர் அதீத நிலையை அடைதல் வேண்டும்' என்பதாம்.)`,
  },
  {
    id: 2279, tantraId: 8, verseNumber: 2278,
    tamil: `விரிந்திடில் சாக்கிரம் மேவும் விளக்காய்
இருந்த இடத்திடை ஈடான மாயை
பொருந்தும் துரியம் புரியல்தா னாகும்
தெரிந்த துரியத்துத் தீதுஅக லாதே`,
    transliteration: `virintiṭil cākkiram mēvum viḷakkāy
irunta iṭattiṭai īṭāṉa māyai
poruntum turiyam puriyaltā ṉākum
terinta turiyattut tītuaka lātē`,
    english: `2278: Maya Lights the Path to Turiyya and There Remains
If in Jagra State
Where Jiva is,
He upward, ascends,
Well may Maya serve
A lamp to light his path;
Then, when he reaches Turiya State,
He his Self realizes;
Albeit in that Turiya State
Maya will still be.
(The Soul should further ascend to the Turiyatita
State.)`,
    elaborationTamil: `சிவத்திற்கும், ஆன்மாவிற்கும் இடையே நிற்பதாகிய மாயை தனது நிலையினின்று விருத்திப் படுமாயின் ஆணவ இருளில் உள்ள உயிர்கட்கு விளக்குப் போல உதவும். அதனாலேயே மத்தியாலவத்தை நிகழும் துரியத்தில் ஆன்மாப் பாசத்தினின்றும் நீங்காது அழுந்திநிற்கும். (ஆதலின் அஃது ஆன்மா அடைதற்குரிய துரியம் அன்று.) அஃது அடைதற்குரிய துரியம் பரதுரியமே. அதனை அடைந்தால் அது பாசங்கள் நீங்கித் தூயதாம்.`,
  },
  {
    id: 2280, tantraId: 8, verseNumber: 2279,
    tamil: `உன்னை அறியாது உடலைமுன் நான்ஒன்றாய்
உன்னை அறிந்து துரியத்து உறநின்றாய்
தன்னை அறிந்தும் பிறவி தணவாதால்
அன்ன வியாத்தன் அமலன் என்று அறிதியே`,
    transliteration: `uṉṉai aṟiyātu uṭalaimuṉ nāṉoṉṟāy
uṉṉai aṟintu turiyattu uṟaniṉṟāy
taṉṉai aṟintum piṟavi taṇavātāl
aṉṉa viyāttaṉ amalaṉ eṉṟu aṟitiyē`,
    english: `2279: Self-Realization in Turiya State is not the End
Knowing not your Self
You deemed body as Self;
When in Turiya you entered,
You realized the Self;
Even though you realized Self,
Birth's cycle will leave you not;
(Therefore, ascend further upward
Into the Turiyatita State)
And unite in Lord,
Pervasive and Pure.`,
    elaborationTamil: `மாணவனே, நீ கீழாலவத்தை மத்தியாலவத்தை -களில் நின்ற பொழுது உன்னையே நீ, 'யார்' என்று அறிந்து கொள்ளாது, உடம்பையே, 'நான்' என்று சொல்லிக் கொண்டிருந்தாய். பின்பு, நின்மலாவத்தையை அடைந்தபொழுது உன்னை நீ, 'சடமாகிய உடம்பின் வேறாகிய சித்துப் பொருள்' என அறிந்து, அதன்கண் துரிய நிலையிலே சிவன் உன்னையே தானாகக் கொண்டு நிற்கும்படி அவனது அருள் வழியில் நின்றாய், எனினும் ஆன்மாத் தன்னையும், தலைவனையும் அறிந்து அவனது அருள் வழியில் நின்ற அளவிலே அதற்குப் பிறவி நீங்கி விடாது. 'சிவன் எல்லாப் பொருளிலும் நீக்கமற நிறைந்து நின்றானாயினும், அவனது உண்மை நிலை பிறிதொன் றோடும் கூடாது அனைத்தினும் வேறாய் நிற்கு தூய்மையே' என்பதை அறிந்து, அவனை அந்நிலையிலே சென்று தலைப்படமுயல்.`,
  },
  {
    id: 2281, tantraId: 8, verseNumber: 2280,
    tamil: `கருவரம்பு ஆகிய காயம் துரியம்
இருவரும் கண்டீர் பிறப்புஇறப்பு உற்றார்
குருவரம் பெற்றவர் கூடிய பின்னை
இருவரும் இன்றிஒன் றாகி நின் றாரே`,
    transliteration: `karuvarampu ākiya kāyam turiyam
iruvarum kaṇṭīr piṟappuiṟappu uṟṟār
kuruvaram peṟṟavar kūṭiya piṉṉai
iruvarum iṉṟioṉ ṟāki niṉ ṟārē`,
    english: `2280: Beyond Turiya State is Union in Siva7This body is to
birth subject,
Turiya State belongs to body and Jiva alike;
These subject to birth and death are;
When on them Grace of Holy Guru descends,
Two there is none,
Jiva in Siva unites one.`,
    elaborationTamil: `கருவிற்கு உட்படுதலையுடைய உடம்பில் நிகழ் வதாகிய துரியத்தில் நீயும், சிவனும் ஒருவரை யொருவர் பார்த்துக் கொண்டீர்கள். (அது போதாது; ஏனெனில்,) பிறப்பு இறப்புக்களிற் பட்டு உழல்கின்றவர்கள். ஞான குருவின் அருளைப் பெற்றுச் சிவனும், தாமும் வேறறக் கலந்த பின்பே தாம் சிவனின் வேறாய சீவராய் நில்லாது. சிவமாகி நிற்பர்.`,
  },
  {
    id: 2282, tantraId: 8, verseNumber: 2281,
    tamil: `அணுவின் துரியத்தில் ஆன நனவும்
அணுஅசை வின்கண் ஆனகனவும்
அணுஅசை வில்பரா தீதம் கழுத்தி
பணியில் பரதுரி யம்பர மாமே`,
    transliteration: `aṇuviṉ turiyattil āṉa naṉavum
aṇuacai viṉkaṇ āṉakaṉavum
aṇuacai vilparā tītam kaḻutti
paṇiyil paraturi yampara māmē`,
    english: `2281: Beyond Four States in Turiya is Para Turiya
If Jiva in Turiya State
Having experienced in succession
Jagra, Svapna, Sushupti states within,
Perseveres further,
Then he enters Para Turiya;
There verily Jiva becomes Para.`,
  },
  {
    id: 2283, tantraId: 8, verseNumber: 2282,
    tamil: `பரதுரி யத்து நனவும் பரந்து
விரிசகம் உண்ட கனவும்மெய்ச் சாந்தி
உருவுறு கின்ற சுழுத்தியும் ஓவத்
தெரியும் சிவதுரி யத்தனு மாமே`,
    transliteration: `paraturi yattu naṉavum parantu
viricakam uṇṭa kaṉavummeyc cānti
uruvuṟu kiṉṟa cuḻuttiyum ōvat
teriyum civaturi yattaṉu māmē`,
    english: `2282: End of Para Turiya is Siva Turiya
Succeeding Para Turiya Jagra State
Is the Para Turiya Svapna State
That engrosses the universe entire;
Then is Para Turiya Sushupti State
Where Upasantha (Peace beyond understanding) is;
That transcending, Jiva reaches Siva Turiya State.`,
    elaborationTamil: `('மேலாலவத்தை' என்றும், சகலத்தில் 'சுத்தா வத்தை' என்றும் கீழ் உள்ளவைகளை நோக்கிச் சிறப்பித்துச் சொல்லப் படுகின்ற யோகாவத்தைகள் அது காரணம் பற்றியே 'துரியம்' எனப்படும். (துரியம் - மேற்பட்டது) ஆயினும், அதில் சீவத் தன்மை நீங்காமையால் அவை சீவதுரியமேயாம். அவையே இங்கு 'அணுவின் துரியம்' என்றும் 'அணுவசைவு' என்றும் சொல்லப்படுகின்றன.
சீவ துரியமாகிய யோகாவத்தையில் உள்ள, 'சாக்கிரம், சொப்பனம், சுழுத்தி, துரியம், துரியாதீதம்' என்பன தாழ்வுடையனவே - என அறியப்பட்டால், அதன் பின்பே பராவத்தை உளதாகும். அந்தப் பராவத்தையே அவத்தைகளில் எல்லாம் மேலான அவத்தை.`,
  },
  {
    id: 2284, tantraId: 8, verseNumber: 2283,
    tamil: `பரமா நனவின்பின் பால்சக முண்ட
திரமார் கனவும் சிறந்த சுழுத்தி
உரமாம் உபசாந்தம் உற்றல் துறவே
தரனாம் சிவதுரி யத்தனும் ஆமே`,
    transliteration: `paramā naṉaviṉpiṉ pālcaka muṇṭa
tiramār kaṉavum ciṟanta cuḻutti
uramām upacāntam uṟṟal tuṟavē
taraṉām civaturi yattaṉum āmē`,
    english: `2283: End of Para Turiya is Siva Turiya
Succeeding Para Turiya Jagra State
Is the Para Turiya Svapna State
That engrosses the universe entire;
Then is Para Turiya Sushupti State
Where Upasantha (Peace beyond understanding) is;
That transcending, Jiva reaches Siva Turiya State.`,
    elaborationTamil: `பராவத்தையில் சாக்கிரம் சீவன் முத்தி அதில் உலக அனுபவம் சிவானுபவமாய் நிகழும், (அதுவே,
'பெற்றசிற் றின்பமே பேரின்பமாம்'l
எனக் கூறப்பட்டது.) அந்த அனுபவம் அதிகார முத்தியில் பழக்க வாசனையாய் நிகழும். அதுவே பர சொப்பனம். போக முத்தியில் அந்த வாசனையும் தாக்கமாட்டாது நீங்கும். அதுவே பர சுழுத்தி. (இதில் சுத்த தத்துவ போகத்தில் இச்சையுண்டாம்) அந்த இச்சையும், அதனால் வரும் அந்தப் போகமும் அடங்கி நிற்றலே 'உபசாந்தம்' எனப்படும். அது பர துரியம். அதை அடைந்தவன் மேல்நிலையை அடைந்தவனாவன். 'சிவ துரியம்' எனப்படுகின்ற நின்மலத் துரியத்தை அடைந்தவனும் இந்நிலையை அடைந்தே உயர்வு பெறுதற்குரியன்.`,
  },
  {
    id: 2285, tantraId: 8, verseNumber: 2284,
    tamil: `சீவன் துரியம் முதலாகச் சீரான
ஆவ சிவன்துரி யாந்தம் அவத்தைபத்தும்
ஓவும் பராநந்தி உண்மைக்குள் வைகியே
மேவிய நாலேழ் விடுவித்துநின் றானே`,
    transliteration: `cīvaṉ turiyam mutalākac cīrāṉa
āva civaṉturi yāntam avattaipattum
ōvum parānanti uṇmaikkuḷ vaikiyē
mēviya nālēḻ viṭuvittuniṉ ṟāṉē`,
    english: `2284: Beyond the Ten Avastas in Jiva Turiya, Para Turiya and
Siva Turiya is the Eleventh State of Consciousness of Para Nandi (Siva)
Thus Jiva, who has Para become,
From Jiva Turiya onward
Up to Siva Turiya,
Ten avastas (States) experiences;
Then enters the State Eleventh
Where he merges into Truth of Para Nandi (Siva)
And finally goes beyond,
All eleven States thus ensured.`,
    elaborationEnglish: `Thus Jiva, who has Para become, From Jiva Turiya onward Up to Siva Turiya, Ten avastas (States) experiences; Then enters the State Eleventh Where he merges into Truth of Para Nandi (Siva) And finally goes beyond, All eleven States thus ensured.`,
    elaborationTamil: `'சிவதுரியம்' எனப்படுவது, யோகாவத்தையில் இமயம் முதலிய எட்டில் ஏழாவதாகிய 'தியானம்' என்பது. 'சிவ துரியம்' எனப்படுவது, தசகாரியத்துள் ஒன்பதாவதாகிய சிவயோகம். இவ்வொன்பதில் ஆன்ம சுத்தி சிவ தரிசன சிவயோகங்களில் அடங்கிவிடுதலால், எஞ்சிய எட்டோடு, யோகாவத்தையில் 'தியானம் சமாதி' - என்னும் இரண்டைக் கூட்ட, சீவதுரியம் முதலாகச் சிவ துரியம் ஈறாக உள்ள அவத்தைகள் பத்தாம். ஆகவே, இந்தப் பத்த வத்தைகளையும் கடந்து, சிவானந்தந் தருவதாகிய உண்மைச் சுத்தா வத்தை அடைந்தவனே, தான் முன்பு கட்டுண்டிருந்த அனைத்துத் தத்துவங்களினின்றும் நீங்கினவனாவன்.`,
  },
  {
    id: 2286, tantraId: 8, verseNumber: 2285,
    tamil: `பரம்சிவன் மேலாம் பரமம் பரத்தில்
பரம்சிவன் மேலாம் பரநனவாக
விரிந்த கனாவிடர் வீட்டும் கழுமுனை
உரந்தரும் மாநந்தி யாம்உண்மை தானே`,
    transliteration: `paramcivaṉ mēlām paramam parattil
paramcivaṉ mēlām paranaṉavāka
virinta kaṉāviṭar vīṭṭum kaḻumuṉai
urantarum mānanti yāmuṇmai tāṉē`,
    english: `2285: Further Beyond Para Siva State is Paramam (Brahmam),
Paramparam and Para Maha Sivam
Beyond Para Siva is Paramam (Brahmam);
Beyond Paramam is Paramparam (Para Brahmam);
Thus are states ascending;
From Para Siva Jagra, to Para Siva Svapna, and to Para Siva Sushupti
The Jiva that has Para Siva become reaches
The Finite Truth that is Para Nandi.`,
    elaborationTamil: `'பரம்' என்பது 'மேல்' என்னும் பொருளது ஆதலின், 'எங்கும் பரன் என்று சொல்லப்படுகின்ற சிவன், மேலானவன்' - என்பது போதரும். இனி, 'பரமம்' என்பது பரத்தினும் உயர்ந்த மேன்மையைக் குறிக்கும். ஆகவே, 'பரம்பரன்' என்று சொல்லப்படுகின்ற சிவனே மேலான சிவன். அவனைத் தலைப்படும சீவன் முத்திநிலையே பரசாக்கிரம். (அதில் பிராரத்தம் உயிரைத் தாக்காவிடினும் உடலூழாய் வந்து போகும்.) 'பர சொப்பனம்' எனப் படுகின்ற அதிகார முத்தியில் பிராரத்துவத் தொடர்பு உண்டாகாது. பர சுழுத்தியாகிய போக முத்தியிலும், பர துரியமாகிய இலய முத்தியிலும் ஞானம் முற்றி நிற்கும். பரதுரியாதீதமாகிய பரமுத்தியில் சிவானந்தப் பெருக்கு உளதாம். இவையே உண்மைச் சுத்தாவத்தைகளாம்.`,
  },
  {
    id: 2287, tantraId: 8, verseNumber: 2286,
    tamil: `சார்வாம் பரம்சிவன் சத்தி பரநாதம்
மேலாய விந்து சதாசிவம் மிக்கோங்கிப்
பாலாய்ப் பிரமன் அரிஅம ராபதி
தேவாம் உருத்திரன் ஈசனாம் காணிலே`,
    transliteration: `cārvām paramcivaṉ catti paranātam
mēlāya vintu catācivam mikkōṅkip
pālāyp piramaṉ ariama rāpati
tēvām uruttiraṉ īcaṉām kāṇilē`,
    english: `2286: Nine Manifestations of Para Siva
Are the (Para) Sakti,
Para Nada and Para Bindu;
And Sadasiva, Brahma, and Hari;
Rudra the Lord of Devas,
And Mahesvara to count.`,
    elaborationTamil: `தத்துவங்களை ஆராயுமிடத்து, எல்லா உயிர் களும் முடிவில் அடையும் இடமாய் உள்ள பரமசிவனும், பரா சத்தியும் முதற்கண் முறையே பர நாத மூர்த்தியும் பரவிந்து சத்தியுமாய் நிற்க பின்பு பரவிந்து சத்தியினின்று அபர நாத மூர்த்தியும், அவனிடத் தினின்று அபரவிந்து சத்தியும் தோன்ற, அதன்பின் அபரவிந்து சத்தியினின்று சதாசிவன், மகேசுரன், உரூத்திரன், மால், அயன், என்போர் முறையே ஒருவரினின்று மற்றொருவர் தோன்றுவர்.`,
  },
  {
    id: 2288, tantraId: 8, verseNumber: 2287,
    tamil: `கலப்புஅறி யார்கடல் சூழ்உல கேழும்
உலப்புஅறி யார்உட லோடுஉயிர் தன்மை
அலப்புஅறிந்து இங்குஅர சாளகி லாதார்
குறிப்பது கோலம் அடலது வாமே`,
    transliteration: `kalappuaṟi yārkaṭal cūḻula kēḻum
ulappuaṟi yāruṭa lōṭuuyir taṉmai
alappuaṟintu iṅkuara cāḷaki lātār
kuṟippatu kōlam aṭalatu vāmē`,
    english: `2287: True Knowledge
Knowing that not
They rule not the (Spiritual) Kingdom;
In pomp and vanity they indulge;
That indeed is sorrow;
They know not, He pervades all;
They know not
The sea-girt seven Worlds
Will a shamble be;
They know not
That Siva with Jiva and Body
Commingling stands.`,
    elaborationTamil: `சிவன் தமது அறிவினுள் அறிவாய்க் கலந்திருத் தலையும், 'பூவுலகம் முழுதும் ஒரு காலத்தில் முற்று அழிந்தொழியும்' என்பதையும் அறியாதமடவோர், உடலோடு கலப்பினால் ஒன்றாய் இருக்கின்ற உயிர் பொருளால் வேறாதலை உணர்ந்து உடம்பையே தாமாகப் பற்றி நின்று, அதனால் இவ்வுலகத்திற்றானே அருளரசு ஆள மாட்டுவாரல்லர். அவர் அத்தகைய நிலையை அடைய வேண்டின், அவர்கள் குறிக்கொளத் தக்கது சிவனது தடத்தத் திருமேனிகளை எழுதி வைக்கும் உள்ளமாகிய கிழியேயாம்.`,
  },
  {
    id: 2289, tantraId: 8, verseNumber: 2288,
    tamil: `பின்னை அறியும் பெருந்தவத்து உண்மைசெய்
தன்னை அறியில் தயாபரன் எம்இறை
முன்னை அறிவு முடிகின்ற காலமும்
என்னை அறியலுற்று இன்புற்ற வாறே`,
    transliteration: `piṉṉai aṟiyum peruntavattu uṇmaicey
taṉṉai aṟiyil tayāparaṉ emiṟai
muṉṉai aṟivu muṭikiṉṟa kālamum
eṉṉai aṟiyaluṟṟu iṉpuṟṟa vāṟē`,
    english: `2288: End Ego-Awareness; Self is Realized;
Perform penances true
That your Future holds;
Know thyself,
And the merciful Lord
His Grace confers;
When my ego awareness ended,
Then I knew my Self;
And bliss am I.`,
    elaborationTamil: `சிறு தவங்களையெல்லாம் செய்து அலுத்துவிட்ட பின்பு நல்லறிவு பிறந்து செய்கின்ற பெருந்தவந்தின் வழியாக உயிர்களைப் பராவத்தையில் சேர்க்கின்ற தனது இயல்பை ஒருவன் அறிந்து தன்னை அடைய விரும்பினால் எங்கள் இறைவனாகிய சிவன் உடனே அவன் முன் தோன்றுவான். ஏனெனில் அவன் பெருங் கருணையாளன். அம்முறையில் யான் எனது பழைய சிற்றறிவு முடியும் காலத்தையும் அறிந்தேன் அதனால் சிவனது பேரறிவாலே என்னையும் அறிந்தேன். யான் இது பொழுது இன்புற்றிருக்குமாறு இவ்வாறாம்.`,
  },
  {
    id: 2290, tantraId: 8, verseNumber: 2289,
    tamil: `பொன்னை மறைத்தது பொன்னணி பூடணம்
பொன்னின் மறைந்தது பொன்னணி பூடணம்
தன்னை மறைத்தது தன்கர ணங்களாம்
தன்னின் மறைந்தது தன்கர ணங்களே`,
    transliteration: `poṉṉai maṟaittatu poṉṉaṇi pūṭaṇam
poṉṉiṉ maṟaintatu poṉṉaṇi pūṭaṇam
taṉṉai maṟaittatu taṉkara ṇaṅkaḷām
taṉṉiṉ maṟaintatu taṉkara ṇaṅkaḷē`,
    english: `2289: Way of Self-Realization Through Thought Process
Think of gold jewellery,
Thought of gold metal is not;
Think of gold metal
Thought of jewellery is not;
Think of sense organs, Self is not;
Think of Self, sense organs are not.`,
    elaborationTamil: `பொன்னால் செய்யப்பட்ட அழகிய அணி கலன்கள் தம்மிடத்துப் பொன் உள்ளதாயினும் அதனை உரைச் செய்யாது மறைத்துத் தமது அழகினையே உணரப் பண்ணி மக்களை மயக்குகின்றது. ஆயினும் அந்த அணிகலன்களின் செயற்கை நலன்களை அழித்துவிட்டால், அணிகலனாய் இருந்த பொருள்கள் அழியாதிருப்பினும் அவை பொன்னாகி விட்ட அதனுள்ளே மறைந்து விடும். அவைபோல, சார்ந்ததன் வண்ணம் ஆகின்ற ஆன்மாவைப் பெத்தகாலத்தில் அதனுடைய தனு கரணங்கள் தம் வயப்படுத்தித் தம்மயம் ஆகச் செய்து, ஆன்மாத் தன்னைத் தான் அறியாதபடி மறைத்து அதனைத் தாமென்றே மயங்கிச் செய்துவிடுகின்றன. ஆயினும், ஆன்மாக் குருவருளால் ஞானத்தைப் பெற்ற முத்தி காலத்தில் உண்மை ஞானம் பொது ஞானத்தை அழித்துவிடுதலால், ஆன்மாவில் வியாப்பியமாய்த் தமக்கெனச் சுதந்திரமின்றி ஆன்மாவின் வழியே செயற்படுகின்ற தனு கரணங்கள் தாம் அழிந் தொழியாது ஆவ்வான்மாவின் வயப்பட்டு முன்போல மருள் வழியில் இயங்காமல், ஆன்மாவைப் போலவே அருள் வழியில் இயங்கும்.`,
  },
  {
    id: 2291, tantraId: 8, verseNumber: 2290,
    tamil: `மரத்தை மறைத்தது மாமத யானை
மரத்தின் மறைந்தது மாமத யானை
பரத்தை மறைத்தது பார்முதல் பூதம்
பரத்தை மறைந்தது பார்முதல் பூதமே`,
    transliteration: `marattai maṟaittatu māmata yāṉai
marattiṉ maṟaintatu māmata yāṉai
parattai maṟaittatu pārmutal pūtam
parattai maṟaintatu pārmutal pūtamē`,
    english: `2290: Sublimation of Thought
Think of wood
Image of toy-elephant recedes;
Think of toy-elephant
Image of wood recedes;
Think of elements five
Thought of Param recedes
Think of Param,
Thought of elements recedes.`,
    elaborationTamil: `மரத்தால் செய்யப்பட்ட பெரிய மதயானை உருவம் சிற்பியின் கைவண்ணத்தால் மரத்தை உணர ஒட்டாமல் மறைத்து, மக்களை மயக்குகின்றது. ஆயினும் சிற்பியினது வேலைப் பாடுகளை அழித்து விட்டால், அந்த மத யானையாய் இருந்த பொருள் அழியாதிருப்பினும் மரத்தினுள்ளே மறைந்துவிடும். அது போல, பரம்பொருளால் இயங்குகின்ற உலகம், ஆன்மாவின் பெத்த காலத்தில் தானே சுதந்திரமாய் இயங்குவனவாய் அதற்குக் காட்சியளிக்கும். ஆயினும் குருவருளால் ஞானத்தைப் பெற்ற முத்தி காலத்தில் உண்மை ஞானம் பொது ஞானத்தை அழித்துவிடுவதால், உலகம் சுதந்திரம் அற்றொழியப் பெரும் பொருளின் இயக்குதலே விளங்கி நிற்கும்.`,
  },
  {
    id: 2292, tantraId: 8, verseNumber: 2291,
    tamil: `ஆறாறு ஆகன்று நமவிட்டு அறிவாகி
வேறான தானே யகாரமாய் மிக்கோங்கி
ஈறார் பரையின் இருளற்ற தற்பரன்
பேறார் சிவாய அடங்கும் பின் முத்தியே`,
    transliteration: `āṟāṟu ākaṉṟu namaviṭṭu aṟivāki
vēṟāṉa tāṉē yakāramāy mikkōṅki
īṟār paraiyiṉ iruḷaṟṟa taṟparaṉ
pēṟār civāya aṭaṅkum piṉ muttiyē`,
    english: `2291: Knowledge of Siva, Sakti and Jiva (Si-Va-Ya) is Liberation
Transcending Tattvas
Six times six,
Abandoning
The letters "Na" and "Ma"
Knowledge Becoming,
Jiva thus liberated rises,
As letter "Ya;"
Merging in letter "Va" denoting Sakti
And in letter "Si" denoting Siva
Jiva ("Ya") becomes Si Va Ya
That Mukti is.`,
    elaborationTamil: ``,
  },
  {
    id: 2293, tantraId: 8, verseNumber: 2292,
    tamil: `துரியத்தில் ஓரைந்தும் சொல்அக ராதி
விரியப் பரையில் மிகும்நாதம் அந்தம்
புரியப் பரையில் பராவத்தா போதம்
திரிய பரமம் துரியம் தெரியவே`,
    transliteration: `turiyattil ōraintum colaka rāti
viriyap paraiyil mikumnātam antam
puriyap paraiyil parāvattā pōtam
tiriya paramam turiyam teriyavē`,
    english: `2292: Experiences in Para Turiya
The Turiya State holds
The Letters-Five (Panchakshara);
In the Para Turiya Jagra State
Are the letters Fifty and One;
In the Para Turiya Svapna State
Is Nada;
In the Para Turiya Sushupti State
Is Bodha;
Beyond appears Paramam (Brahmam).
In Para Turiya-Turiya State.`,
    elaborationEnglish: `1)Jiva turiya—Panchakshara PARA TURIYA AVASTA 1.Para turiya jagrat—Fifty-One Letters 2.Para turiya svapna—nada - 3.Para turiya sushupti—bodha 4.Para turiya turiya—Paramam (Siva turiya beginning of jagrat).`,
    elaborationTamil: `சகலத்திற் சுத்தமாகிய நின்மலாவத்தை ஐந்திலும் வாக்குக்கண் அகாரம் முதலிய ஐந்து அக்கரங்களாய், (அ, உ, ம, விந்து, நாதம் - என்பனவாய்)த் தூலமாய் நிகழும். (எனவே, அவ்விடத்து உலக வாசனை இருக்கவே செய்யும் என்பதாம்.) நின்மலா வத்தைக்கு மேலான உண்மைச் சுத்தாவத்தையில் அவ்வாக்குக்கள் சூக்குமமாய் நிகழும். (அதனால், உலக வாசனை தோன்றாவிடினும், 'யான்' எனது என்னும் உணர்வினால் ஞாதுரு ஞான ஞேய வேற்றுமை நிகழவே செய்யும்.) அந்த வேற்றுமையும் அறுவது பர துரியத்திலாம். (அவ்விடத்தில் ஆன்மா அருள்மயமாய் நிற்கும்.) அதன் பின்பு மேலானதாய அதீதம் தோன்றும். (அதில் ஆன்மா ஆனந்தமயமாய் இருக்கும்.)`,
  },
  {
    id: 2294, tantraId: 8, verseNumber: 2293,
    tamil: `ஐந்தும் சகலத்து அருளால் புரிவற்றுப்
பந்திடும் சுத்த அவத்தைப் பதைப்பினில்
நந்தி பராவத்தை நாடச் சுடர்முனம்
அந்தி இருள்போலும் ஐம்மலம் மாறுமே`,
    transliteration: `aintum cakalattu aruḷāl purivaṟṟup
pantiṭum cutta avattaip pataippiṉil
nanti parāvattai nāṭac cuṭarmuṉam
anti iruḷpōlum aimmalam māṟumē`,
    english: `2293: Pure (Suddha) Experience and Supreme (Para) Experience
In Sakala condition of Jiva,
These five experiences are by Grace attained;
Then follows the Suddha Avasta (Pure Experience) State;
That in intensity experiencing,
The Para Avasta (Supreme Experience) of Nandi is attained;
Then, as before light darkness flees;
The Five Malas for ever vanish.`,
    elaborationEnglish: `1)Sakala avasta (existential experience) Suddha avasta (pure experience) Para avasta (Supreme experience—malas vanish)`,
    elaborationTamil: `சாக்கிரம் முதலிய ஐந்தவத்தைகளையும் சகலத்தில் மாயா கருவிகளால் அடையாது, திருவருளால் அடைந்து, (எனவே, 'மேலா லவத்தையையும் கடந்து நின்மலாவத்தையை அடைந்து' என்றதாம்.) சகலத்திற் சுத்தமாகிய அந்த அவத்தைகளில் மேலே பாய்ந்தும், கீழே வீழ்ந்தும் பந்துபோல அலைகின்ற அலைவினால் அவ்வலைவு நீங்கப் பெறுகின்ற உண்மைச் சுத்தமாகிய பராவத்தையில் நாட்டம் உண்டாகுமானால், அந்த நாட்டத்தின் முன் ஐந்து மலங்களும் அந்திக் காலத்தில் விளக்கின்முன் இருள் நில்லாது நீங்குதல் போல நில்லாது நீங்கும்.`,
  },
  {
    id: 2295, tantraId: 8, verseNumber: 2294,
    tamil: `ஐஐந்து மட்டுப் பகுதியும் மாயையும்
பொய்கண்ட மாமாயை தானும் புருடன்கண்டு
எய்யும் படியாய் எவற்றுமாய் அன்றாகி
உய்யும் பராவத்தை உள்ளுதல் சுத்தமே`,
    transliteration: `aiaintu maṭṭup pakutiyum māyaiyum
poykaṇṭa māmāyai tāṉum puruṭaṉkaṇṭu
eyyum paṭiyāy evaṟṟumāy aṉṟāki
uyyum parāvattai uḷḷutal cuttamē`,
    english: `2294: State of Suddha Avasta (Pure Experience)
The limited sphere of Tattvas
Five times Five,
And Maya Impure,
--Unreal are they;
Leaving them,
Let Jiva ascend
Into the Sphere of Mamaya (Pure-Impure);
Penetrating it,
Further beyond
In the State of Para-Avasta, (Pure Experience)
That is Pure (Suddha);
There the Soul is All-Existence
And Non-Existence at once.`,
    elaborationEnglish: ``,
    elaborationTamil: `'இருபத்தைந்து' எனத் தொகை பெற்று நிற்கின்ற தத்துவங்களாய் உள்ள மூலப் பிரகிருதியில் இயல்பையும், 'மாயேயம்' எனப்படுகின்ற வித்தியா தத்துவங்களாய் உள்ள அசுத்தமாயையின் இயல்பையும் சாதகன் உள்ளவாறு உணர்ந்து தத்துவ ஞானியாய், எல்லாப் பொருளிலும் கலப்பினால் ஒன்றாகியும், பொருள் தன்மையால் வேறாகியும் நிற்கின்ற சிவமாகிப் பிறவியினின்றும் நீங்கி நிற்கும் பராவத்தையை அடைதலே உண்மைச் சுத்தாவத்தையாகும்.`,
  },
  {
    id: 2296, tantraId: 8, verseNumber: 2295,
    tamil: `நின்றான் அருளும் பரமும்முன் நேயமும்
ஒன்றாய் மருவும் உருவும் உபாதியும்
சென்றான் எனைவிடுத்து ஆங்கிச் செல்லாமையும்
நன்றான ஞானத்தின் நாதப் பிரானே`,
    transliteration: `niṉṟāṉ aruḷum paramummuṉ nēyamum
oṉṟāy maruvum uruvum upātiyum
ceṉṟāṉ eṉaiviṭuttu āṅkic cellāmaiyum
naṉṟāṉa ñāṉattiṉ nātap pirāṉē`,
    english: `2295: Lord As Guru Guides the Soul's Journey
As Grace, He stood
As Param, He stood
As Love, He stood;
As one Form merged,
He stood;
He transcended experiences all,
But abandoned me not
He, the Lordly Guru, the Natha,
Of Divine Jnana.`,
    elaborationTamil: `பரம்பொருளை அறிய அவாவிநிற்கின்ற சுத்தான் மாவும், அதற்கு அதனை அறிதற்குத் துணைபுரிந்து அதன் அறிவுக்கு அறிவாய் நிற்கின்ற திருவருளும், அவ்வருளின் துணையால் அந்த ஆன்மாவால் அறியப்படுகின்ற பரம் பொருளும் ஆகிய மூன்று உயர் பொருள்களும், ஆன்மாவினிடத்து மூவகை உடம்புகளாய் நிற்கின்ற தத்துவங்களும், அவற்றைச் செலுத்துகின்ற திரோதான சத்தியும் நீங்கினவிடத்து ஒன்றாய்ப் பொருந்திவிடும். அஃதன்றியும், சிவன் பின்னர் அந்த ஆன்மாவைவிட்டுப் பிரியாத நிலைமையும் உண்டாகும்.`,
  },
  {
    id: 2297, tantraId: 8, verseNumber: 2296,
    tamil: `சாத்திகம் எய்தும் நனவெனச் சாற்றுங்கால்
வாய்ந்த இராசதம் மன்னும் கனவென்ப
ஒய்த்திடும் தாமதம் உற்ற சுழுத்தியாம்
மாய்த்திடும் நிற்குணம் மாசில் துரியமே`,
    transliteration: `cāttikam eytum naṉaveṉac cāṟṟuṅkāl
vāynta irācatam maṉṉum kaṉaveṉpa
oyttiṭum tāmatam uṟṟa cuḻuttiyām
māyttiṭum niṟkuṇam mācil turiyamē`,
    english: `2296: Gunas experiences in States of Consciousness
Sattvic is Guna in the Waking State,
Rajas in Dream State,
Tamas in Deep Sleep State,
Nirguna, that other three Gunas destroys,
Is attribute of Turiya State Pure.`,
    elaborationEnglish: ``,
    elaborationTamil: `சாக்கிரம் பொருள்களை நன்குணரும் நிலையாகலின் அது, 'சாத்துவிக குணத்தின் காரியம்' என்றும், சொப்பனம் பொருள்களைச் சாக்கிரத்தில் அனுபவித்த வாசனையளவாய் நிற்கும் நிலையாதலின் அது மெய்ம்மைக்கு எதிரான போலி அனுபவம் ஆதல் பற்றிச் சாத்துவிகத்திற்கு எதிரான, 'இராசதகுணத்தின்காரியம்' என்றும், சுழுத்தி, யாதும் உணராத நிலையாதலின் அஃது, இருள் மயமான 'தாமத குணத்தின் காரியம்' என்றும் சொல்லப்படும். துரியம் இம்மூன்றையும் கடந்ததாகலின் அது 'நிர்க்குணமாய் நிகழ்வது' என்றும் சொல்லப்படும்.`,
  },
  {
    id: 2298, tantraId: 8, verseNumber: 2297,
    tamil: `பெறுபகி ரண்டம் பேதித்த அண்டம்
எறிகடல் ஏழின் மணல்அள வாகப்
பொறியொளி பொன்னணி யென்ன விளங்கிச்
செறியும் அண் டாசனத் தேவர் பிரானே`,
    transliteration: `peṟupaki raṇṭam pētitta aṇṭam
eṟikaṭal ēḻiṉ maṇalaḷa vākap
poṟiyoḷi poṉṉaṇi yeṉṉa viḷaṅkic
ceṟiyum aṇ ṭācaṉat tēvar pirāṉē`,
    english: `2297: Cosmic Space is God's Seat of Throne
In the vast spaces of Cosmos
Are universes numberless
That evolved and separated;
Countless are they
Unto the sands that are
On the shores of seven seas;
Sparkling as a jewel of gold
That dazzles
They form His Seat of Throne
--For Him, the Lord of Celestials.`,
    elaborationTamil: `அண்டங்களை ஆசனமாகக் கொண்டு, அவற்றிற்கு மேலே விளங்குகின்ற சிவபெருமான், உயிர்களால் பற்றப்பட்டுப் புறமும், அகமுமாய்ப் பல்வேறு வகையில் அமைந்துள்ள அண்டங்கள் எண்ணிலவாய் நிற்க, அவை அனைத்திலும், கட்பொறிக்குப் புலனாகின்ற மாற்றொளியையுடைய, பொன்னால் ஆகிய அணிகலன்போல அவற்றினுள் நிறைந்திருக்கின்றான்.`,
  },
  {
    id: 2299, tantraId: 8, verseNumber: 2298,
    tamil: `ஆனந்த தத்துவம் அண்டா சலத்தின்மேல்
மேனிஐந்தாக வியாத்தம்முப் பத்தாறாய்க்
தான்அந்த மில்லாத தத்துவம் ஆனவை
ஈனமி லா அண்டத்து எண்மடங்கு ஆமே.`,
    transliteration: `āṉanta tattuvam aṇṭā calattiṉmēl
mēṉiaintāka viyāttammup pattāṟāyk
tāṉanta millāta tattuvam āṉavai
īṉami lā aṇṭattu eṇmaṭaṅku āmē.`,
    english: `2298: God is Principle of Bliss Beyond Tattvas
On that Seat of Throne
He sits as Bliss-Principle (Tattva)
Five, His Forms
Thirty-six the Tattvas He pervades;
Nay,
The Tattvas He pervades
Are eight times by far as numerous
As universes in spaces Vast,
Himself beyond Tattvas' end.`,
    elaborationTamil: `அண்டங்களாகிய ஆசனத்தின்மேல் ஆனந்தமாய் உள்ள மெய்ப்பொருள்தான் (வடிவமற்றதாயினும்) அருவம் இரண்டு, அருவுருவம் ஒன்று, உருவம் இரண்டு ஆகிய ஐந்துவடிவங்களைக் கொண்டு விளங்குதலால், அதனால் வியாபிக்கப்பட்ட முப்பத்தாறு முதனிலைப் பொருள்கள் தோன்றி, அழிவின்றி நிற்பனவே 'தத்து வங்கள்' எனப்படுகின்றன. அவையே குறைவில்லாத அண்டங் களாய்க் காரியப்பட்டு, அளவிறந்து நிற்கின்றன.`,
  },
  {
    id: 2300, tantraId: 8, verseNumber: 2299,
    tamil: `அஞ்சில் அமுதும்ஓர் ஏழின்கண் ஆனந்தம்
முஞ்சில்ஓங் காரம் ஓர் ஒன்பான் பதினொன்றில்
வஞ்சக மேநின்று வைத்திடில் காயமாம்
கிஞ்சுகக் செவ்வாய்க் கிளிமொழி கேளே`,
    transliteration: `añcil amutumōr ēḻiṉkaṇ āṉantam
muñcilōṅ kāram ōr oṉpāṉ patiṉoṉṟil
vañcaka mēniṉṟu vaittiṭil kāyamām
kiñcukak cevvāyk kiḷimoḻi kēḷē`,
    english: `2299: Attainments in Higher Experience (Para Avasta)
In the Fifth State (Jiva Turiyatita) is Ambrosia;
In the Seventh State (ParaTuriya-Jagrat) is Bliss;
Above in Ninth State (ParaTuriya-Sushupti) is Aum;
In the Eleventh State (Siva Turiya)
Illumined the Jiva standeth;
Abiding there He the (Divine) Body, attains;
Listen damsel that is red-mouthed as parrot!
--These the attainments of the Higher States (of Jiva) are.`,
    elaborationTamil: `கெடுதல் இல்லாத ஓங்காரத்தின் கலைகள் பனி -ரண்டில் 'அ, உ, ம, விந்து' என்னும் நான்கிற்கு அப்பால் ஐந்தாவதாய் உள்ள அர்த்த சந்திர கலையை அடைந்தால் ஓர் அமுததாரை ஒழுகும் (அஃது உடல் எங்கும் உள்ள நாடிகளில் பாய்ந்து உடலை உறுதிப் படுத்தும். இந்த இடம் புருவநடுவிற்குச் சற்றுமேல், 'நெற்றி நடு' என்னலாம்) பின்பு நிரோதினியைத் தாண்டி ஏழாவதாய் உள்ள நாத கலையை அடைந்தால் அவ்விடத்து ஓர் ஆனந்தம் தோன்றும் (அந்த ஆனந்தம் சிறையில் உள்ளவனுக்கு, 'விடுதலை தோன்றி விட்டது' என்பது தெரிந்தவுடன் உண்டாகின்ற ஆனந்தம் போல்வதேயாகும். இந்த இடம் பிரமரந்திரத்திற்குப் பின்) அதனைக் கடந்து நாதாந் தத்தைத்தாண்டி, ஒன்பதாவதாய் உள்ள சத்திகலையிலும் அதனைக் கடந்து வியாபினி கலையைத் தாண்டிப் பதினொன்றாவதாய் உள்ள சமனா கலையிலும் சென்று உள்ளத்தை அசையாதிருக்கச் செய்தால், அத்தகையோர் இவ்வுலகத்திலே இருப்பினும் உமைகேள்வனாகிய சிவன், 'ஊனே, ஊனின் உள்ளமே, உள்ளத்தின் உள்ளே நின்ற கருவே'' 3 என அருளிச்செய்தபடி அவர்கள் உடம்பிற்குள்ளே இனிது வெளிப்பட்டு நின்று, ''வாக்கிறந்த அமுதம் மயிர்க்கால்தோறும் - தேக்கிடச் செய்து''8 (அஃதாவது பேரானந்தத்தை விளைத்து) நிற்பான்.`,
  },
  {
    id: 2301, tantraId: 8, verseNumber: 2300,
    tamil: `புருட னுடனே பொருந்திய சித்தம்
அருவமொ டாறும் அதீதத் துரியம்
விரியும் சுழுத்தியின் மிக்குள்ள எட்டும்
அரிய பதினொன்று மாம்அவ் அவத்தையே`,
    transliteration: `puruṭa ṉuṭaṉē poruntiya cittam
aruvamo ṭāṟum atītat turiyam
viriyum cuḻuttiyiṉ mikkuḷḷa eṭṭum
ariya patiṉoṉṟu māmav avattaiyē`,
    english: `2300: Tattvas Fade in the Finite Stage
Even in the Atita Turiya State
Six Tattvas formless abide
--The Purusha cum Chitta, and Five formless Tattvas;
In the Sushupti State of Atita Turiya,
The rest eight are;
Only in the Eleventh State, nothing of Tattvas is.`,
    elaborationEnglish: `Section 13 (verses 2304 to 2354) describes the state of Pure Avasta which is totally devoid of Malas. The role of Grace in achieving this State, and the attainment of Pure Knowledge, Jnana, the actions of Siva who is seated within the Jiva, etc., are other topics of these verses. Verses 2326 pronounces a Maha Vakyam which conveys the message of the Jnana enjoyed in the Samadhi State. The topic of Jnana is further dwelt upon in verses 2355 to 2369. Elsewhere Tirumular repeatedly talks of the Six Ends (antas), namely Vedanta, Siddhanta, Nadanta, Bodhanta, Yoganta and Kalanta in general terms. In Section 15 (verses 2370 to 2404), the subject is discussed at length, providing an insight into the various aspects of these 6 antas, which all lead in different ways to the complete eliminatiqn of Malas (2371). Verse 2372 is interesting in that it makes clear one of the fundamental differences between Vedanta and Siddhanta. “‘I am the Supreme One’’, Says the former, whereas the latter hold: ‘‘f shall become the’ Supreme One’’, that is to say, Siddhanta more clearly lays out a simple path for the soul’s journey. Verses 2374 to 2377 deal with Nadanta, Bodhanta, Yoganta and Kalanta. There are, says 2378, five other ways ‘‘dear to Siva’. They are Mantra, Tantra, Serenity (Samadhi Yoga), Upadesa anti Jnana. and 2379 gives some details of these. They are to be found, in Agamas (also called Vedas), according to which Tantra preaches action, Mantra is in th mind and beyond the body and Upadesa is`,
    elaborationTamil: `[சகலத்தில் சுத்தமாகிய யோக வகைகளில் பிராசாத யோகத்தில் ஒருவகையான பராவத்தை நின்மலாவத்தைகள் சொல்லப் படுகின்றன. அவை மேற்கூறிய சுத்தத்தில் சுத்தாவத்தைகளாகிய பரா வத்தையும், இனிக்கூறப்படும் நின்மலாவத்தைகளும் அல்ல.* அந்த அவத்தைகளில் தத்துவங்களின் நீக்கமும் சொல்லப்படுகின்றது. அவற்றுள் அமைந்த நின்மலாவத்தையை இம்மந்திரம் குறிப் பிடுகின்றது.] 
புருடதத்துவமும், அதற்குக்கீழேபொருந்தியுள்ள சித்தமும் சூக்குமமாகிய நாதவிந்து கலைகளிலே ஒடுங்கும். அவ்வொடுக் கங்கள் முறையே யோகத்தில் நின்மலாதீதமும், யோகத்தில் நின்மல துரியமும் ஆகும். சித்தத்திற்குக் கீழ் உள்ள புத்தி, அகங்காரம், மனம் ஆகிய மூன்று அந்தக்கரணங்களும், தன்மாத்திரைகள் ஐந்தும் ஆகிய எட்டும் யோகத்தில் நின்மல சுழுத்தி முதலியவற்றில் விரிந்துநிற்கும். இங்ஙனமாகவே ஞானவத்தைகளை நோக்க, மேற்கூறிய பதினொன்றாந் தானமாகிய சமனா கலையும் யோகாவத்தைத் தானமேயாம். ('ஏனெனில், அவ்விடத்தும் சுத்த மாயைத் தொடர்பு இருத்தலின்' என்பது கருத்து).`,
  },
  {
    id: 2302, tantraId: 8, verseNumber: 2301,
    tamil: `காட்டும் பதினொன்றும் கைகலந் தால்உடல்
நாட்டி அழுத்திடின் நந்திஅல்லால் இல்லை
ஆட்டம்செய் யாத அதுவிதி யேநினை
ஈட்டு மதுதிடம் எண்ணலும் ஆமே`,
    transliteration: `kāṭṭum patiṉoṉṟum kaikalan tāluṭal
nāṭṭi aḻuttiṭiṉ nantiallāl illai
āṭṭamcey yāta atuviti yēniṉai
īṭṭu matutiṭam eṇṇalum āmē`,
    english: `2301: There Nandi Alone Is
When the eleven States are thus cognised,
And the Jiva fixes firm in the Jnana Body
There is none but Nandi;
That Being Immutable
Contemplate in order;
Sure believe, you can the Goal reach.`,
    elaborationTamil: `முன் மந்திரத்தில் சொல்லப்பட்டபடி சிவாகமங்கள் கூறுகின்ற அந்தத்தானங்கள் பதினொன்றிலும் சென்று நின்றால் உடம்பு விரைவில் அழியாது நெடுங்காலத்திற்கு நிலைபெறும் வகையில் உறுதியடையும். அந்நிலையில் அவ்வுடலில் உள்ள உயிருக்குச் சிவனைத் தவிரத் துணையாவார் வேறு ஒருவரும் இலராவர். (அஃதாவது, 'அவ்வுண்மை அவ்வுயிருக்கு நன்கு விளங்கி நிற்கும்' என்பதாம்) அதனால் உனது மனம்போனபடி நீ போய் அலைந்துகொண்டிருந்த அலைவுகளையெல்லாம் விடுத்து அமைதியுற்றிருந்த அந்த அமைதியே வழியாகச் சிவன் தன் அடியார்களோடு கூட்டுதல் உறுதி. இந்த உறுதியும் உனக்கு அந்நிலையில் விளங்குவதாகும்.`,
  },
  {
    id: 2303, tantraId: 8, verseNumber: 2302,
    tamil: `கேவலம் தன்னில் கலவச் சகலத்தின்
மேவும் செலவு விடவரு நீக்கத்துப்
பாவும் தனைக்கண்டால் மூன்றும் படர்வற்ற
தீதறு சாக்கிரா தீதத்தில் சுத்தமே`,
    transliteration: `kēvalam taṉṉil kalavac cakalattiṉ
mēvum celavu viṭavaru nīkkattup
pāvum taṉaikkaṇṭāl mūṉṟum paṭarvaṟṟa
tītaṟu cākkirā tītattil cuttamē`,
    english: `2302: Beyond Kevala, Sakala and Self-Realization States is
Suddha Avasta
The Jiva in its primal condition
Is in the Kevala State;
When it mixes with Tattvas
It departs and enters the Sakala State;
Released from there,
It realizes the Self;
When it transcends all the states three,
It enters the Jagratatita State;`,
    elaborationEnglish: ``,
    elaborationTamil: `கேவலாவத்தைக்குப் பின்பு ஆன்மாச் சகலத்தை அடைதலே கலவு நிலையாகும். (கலத்தல்மலத்தோடேயாகையால், இக்கலப்பு அசுத்தமேயாம். எனவே, கேவலத்திலிருந்த அசுத்தம் போய்விடவில்லையாம். முன்னை அசுத்தமே பின்னை அசுத்தத் திற்குக் காரணம் ஆகையால்) விடாது பற்றியுள்ள முதல் அசுத்தமாகிய இருள் நீங்கும் சமையத்தில் ஆன்மாச் சகல நிலையினின்றும் சிறிது சிறிதாக விலகி அப்பாற் செல்லுதலே செலவு நிலையாகும். (இது மலங்களினின்றும் நீங்கும் நிலையாகலின், 'நின்மலாவத்தை' எனப்படும்) இந்நிலையில் ஆன்மாத் தன்னைக் காணுதல், பின் திரு வருளைக் காணுதல், பின் திருவருளைக் காணுதல், பின் பராசத்தியைக் காணுதல் இவை மூன்றும் முறையே நிகழ்ந்து நீங்கினால் சாக்கிராதீதம் வாய்க்கும். அதன் பின்பே நின்மலாவத்தை முடிவுபெறும்.`,
  },
  {
    id: 2304, tantraId: 8, verseNumber: 2303,
    tamil: `வெல்லும் அளவில் விடுமின் வெகுளியைச்
செல்லும் அளவும் செலுத்துமிஹ் சிந்தையை
அல்லும் பகலும் அருளுடன் தூங்கினால்
கல்லும் பிளந்து கடுவெளி யாமே`,
    transliteration: `vellum aḷavil viṭumiṉ vekuḷiyaic
cellum aḷavum celuttumih cintaiyai
allum pakalum aruḷuṭaṉ tūṅkiṉāl
kallum piḷantu kaṭuveḷi yāmē`,
    english: `2303: Vision of Void
Give up anger (Egoity)
As far as you can;
Direct your thoughts (Godward)
As far as it goes;
If with Lord's Grace
You slumber (in contemplation)
Day and night,
Even mountains will break;
And you shall vision the Void interminable.`,
    elaborationEnglish: ``,
    elaborationTamil: `எந்தப் பொருள் மேலும் எழுகின்ற விருப்பத்தை வெல்லுங்கள்; வெறுப்பை ஒழியுங்கள்; உள்ளம் தூய்மையாகும். ஆனபின் அதனை இயன்ற அளவு திருவருளைப் பற்றியே இயங்கச் செய்யுங்கள். பின்பு அஃது அல்லும், பகலும் திருவருளையே சார்ந்து அமைதியுற்றிருக்கும். அப்பொழுது மலைக் குகையுள் அடைக்கப் பட்டவனுக்கு அந்தக் குகை வெடித்துப் பெரிய விடுதலை கிடைத்தது போன்ற ஒருநிலை உண்டாகும்.`,
  },
  {
    id: 2305, tantraId: 8, verseNumber: 2304,
    tamil: `ஊமைக் கிணற்றகத் துள்ளே உறைவதோர்
ஆமையின் உள்ளே அழுவைகள் ஐந்துள
வாய்மையின் உள்ளே வழுவாது ஒடுங்குமேல்
ஆமையின் மேலும்ஓர் ஆயிரத்து ஆண்டே`,
    transliteration: `ūmaik kiṇaṟṟakat tuḷḷē uṟaivatōr
āmaiyiṉ uḷḷē aḻuvaikaḷ aintuḷa
vāymaiyiṉ uḷḷē vaḻuvātu oṭuṅkumēl
āmaiyiṉ mēlumōr āyirattu āṇṭē`,
    english: `2304: Merge in Silentness, Senses Withdrawn
Deep in the Well of Silentness (Mauna)
Is a turtle--Jiva--(with Malas Five withdrawn)
If from Truth you deviate not,
And in (It) merge entire,
You shall indeed live
A thousand years beyond the turtle.`,
    elaborationTamil: `[இம்மந்திரம் ஒட்டணி பெற்றது.] 
ஊமைக் கிணறு - வாய் இல்லாத கிணறு. அஃதாவது, தோண்டப்படாமல் நிலத்தினுள்ளே கிடக்கின்ற நீர்நிலை. என்றது கேவல நிலையை. ஆமை, கேவலத்தில் கிடக்கும் ஆன்மா. அழுவை - அழுவம்; பள்ளம். பள்ளங்கள் ஐந்தாவன, கேவலம், சகலத்திற் கேவலம், சகலத்திற் சகலம், சகலத்தில் யோகம், சகலத்தில்ஞானம்' என்னும் காரண அவத்தைகள், அவற்றுள், 'வாய்மை' என்னும் பள்ளம் சகலத்தில் ஞானம். இதுவே நின்மலாவத்தை. இதனை அடைந்த ஆன்மா நித்தியமாம் தன்மையைப் பெறும்.`,
  },
  {
    id: 2306, tantraId: 8, verseNumber: 2305,
    tamil: `காலங்கி நீர்பூக் கலந்தஆ காயம்
மாலங்கி ஈசன் பிரமன் சதாசிவன்
மேலஞ்சும் ஓடி விரவவல் லார்கட்குக்
காலனும் இல்லை கருத்தில்லை தானே`,
    transliteration: `kālaṅki nīrpūk kalantaā kāyam
mālaṅki īcaṉ piramaṉ catācivaṉ
mēlañcum ōṭi viravaval lārkaṭkuk
kālaṉum illai karuttillai tāṉē`,
    english: `2305: Experience of Higher States Brings Immortality
Air, fire, water, earth and space,
Hari, Rudra, Mahesvara, Brahma and Sadasiva,
They who transcend these elements and Gods five
And into Higher States enter,
Will never death see;
Thoughts none other will they have
Except be of God.`,
    elaborationTamil: `'நிலம், நீர், தீ, காற்று, வானம்' என்னும் ஐம்பூதங் களும் முறையே பிரமன், மால், உருத்திரன், மகேசுரன், சதாசிவன் என்னும் ஐவர்களாலேதான் தொழிற்படுகின்றன. ஆகவே அந்த ஐவரையும் ஆதார யோகத்தால் 'சுவாதிட்டானம், மணிபூரகம், அனாகதம், விசுத்தி, ஆஞ்ஞை' என்னும் ஆதாரங்களில் முறையாகக் கண்டு, பின்நிராதாரத்தை அடைய வல்லவர்கட்கு இறப்பும் இல்லை. வாழ்வில் உணர்வும் இல்லையாம்.`,
  },
  {
    id: 2307, tantraId: 8, verseNumber: 2306,
    tamil: `ஆன்மாவே மைந்தன் ஆயினன் என்பது
தான்மா மறையறை தன்மை அறிகிலர்
ஆன்மாவே மைந்தன் அரனுக்கு இவன்என்றால்
ஆன்மாவும் இல்லையால் ஐஐந்தும் இல்லையே`,
    transliteration: `āṉmāvē maintaṉ āyiṉaṉ eṉpatu
tāṉmā maṟaiyaṟai taṉmai aṟikilar
āṉmāvē maintaṉ araṉukku ivaṉeṉṟāl
āṉmāvum illaiyāl aiaintum illaiyē`,
    english: `2306: Jiva Son of Siva
Jiva is the son,
All the hoary scriptures thus say;
That they know not
The Jiva indeed is the Son of Hara;
For, without Jiva,
None the Tattvas five times five be.`,
    elaborationTamil: `'உயிர்கள் அனைத்திற்கும் சிவன் தந்தை' என்பதும், 'சித்தி தாய்' என்பதும் வேதாகமங்களில் எங்கும் முழங்கும் முழக்க மாதலை அறியாது சிலர் ஆன்மாவை, 'தாயும் இலி; தந்தையிலி' என்கின்றார்கள். அஃது உண்மையாயின், சடப்பொருள்களாகிய தத்துவங்களும், அவற்றைக்கொண்டு ஆன்மாக்கள் உலகில் பிறந்து வினைகளை நுகர்ந்தும் ஈட்டியும், பின்பு இறந்தும் செல்லும்நிலை இல்லையாகவேண்டும்.`,
  },
  {
    id: 2308, tantraId: 8, verseNumber: 2307,
    tamil: `உதயம் அழுங்கில் ஒடுங்கல்இம் மூன்றின்
கதிசாக் கிரங்கன வாதி சுழுத்தி
பதிதரு சேதனன் பற்றாம் துரியத்து
அதிசுப னாய்அனந் தான் அந்தி யாகுமே`,
    transliteration: `utayam aḻuṅkil oṭuṅkalim mūṉṟiṉ
katicāk kiraṅkaṉa vāti cuḻutti
patitaru cētaṉaṉ paṟṟām turiyattu
aticupa ṉāyaṉan tāṉ anti yākumē`,
    english: `2307: In Turiya is bliss Exceeding
Unto being born, living, and dying
Are the experiences three
Of Waking, Dreaming and Deep Sleep States;
When Jiva reaches Turiya State,
And there abides,
Exceeding Pure he becomes,
And infinite bliss he enjoys.`,
    elaborationTamil: `அறிவு உதயசூரியன் போலத் தோன்றி விளங் குதலும், அவ்வாறின்றி மேகங்களால் மறைக்கப்பட்ட சூரியனைப் போல மழுங்கி நிற்றலும், அத்தமித்த சூரியன்போல ஒடுங்கி யிருத்தலும் ஆகிய இவையே பெத்தத்தில் நிகழும் சாக்கிர சொப்பன துரியங்களாகும். ஆகவே, 'அவற்றின்பின் நிகழும் துரியமும் அறிவுசெயற்படாது அடங்கிக் கிடக்கும் நிலை' என்பது சொல்ல வேண்டா. இந்தப் பெத்தநிலை அவத்தைகளை விடுத்துச் சுத்தநிலை அவத்தையை ஒருவன் எய்துவானாயின்' அவன் மிக நன்மையை அடைந்தவனாய், எல்லையில்லாத ஆனந்தத்தையுடையவனாவான்.`,
  },
  {
    id: 2309, tantraId: 8, verseNumber: 2308,
    tamil: `எல்லாம்தன் னுட்புக யாவுளும் தானாகி
நல்லாம் துரியம் புரிந்தக்கால் நல்லுயிர்
பொல்லாத ஆறாறுள் போகாது போதமாய்ச்
செல்லாச் சிவகதி சென்றுஎய்தும் அன்றே`,
    transliteration: `ellāmtaṉ ṉuṭpuka yāvuḷum tāṉāki
nallām turiyam purintakkāl nalluyir
pollāta āṟāṟuḷ pōkātu pōtamāyc
cellāc civakati ceṉṟueytum aṉṟē`,
    english: `2308: From Turiya State No Return to Tattvas
All within him (Jiva),
And he in all without;
Thus if Jiva
The Turiya State experiences,
No more shall it return
To Tattvas six times six;
Divine Knowledge (Bodha)
It will attain;
And so reach Siva-State.`,
    elaborationTamil: `சட உலகங்கள் யாவும் தனக்குள் அடங்கியிருக்க, சிவஞானத்தால் எல்லாப் பொருளையும் ஒருங்கேயறியும் தன்மை யுடையவன் ஆகின்ற அத்தகைய நல்ல துரியத்திலே தங்கும் நிலையை ஓருயிர் அடைந்துவிட்டால் அது நல்ல உயிராகும், பின்பு அது பிறவி யாகிய தீமையை விளைவிக்கின்ற முப்பத்தாறு தத்துவங்களில் செல்லாது. முன்பெல்லாம் சடங்களாகிய அவற்றிற்சென்று அவையே யாய் இருந்ததுபோல் இல்லாமல் அவற்றின் நீங்கி அறிவுப் பொருளாய், செல்லாது செல்வதாகிய சிவகதியை அடையும்.`,
  },
  {
    id: 2310, tantraId: 8, verseNumber: 2309,
    tamil: `காய்ந்த இரும்பு கனலை அகன்றாலும்
வாய்ந்த கனலென வாதனை நின்றாற்போல்
ஏய்ந்த கரணம் இறந்த துரியத்துத்
தோய்ந்த கருமத் துரிசுஅக லாதே`,
    transliteration: `kāynta irumpu kaṉalai akaṉṟālum
vāynta kaṉaleṉa vātaṉai niṉṟāṟpōl
ēynta karaṇam iṟanta turiyattut
tōynta karumat turicuaka lātē`,
    english: `2309: Yet in Turiya, Karmic Effects Are
Well may you iron
From fire remove;
The iron still retains
The effect of fire (experience);
So too,
Even if sense organs
Are in Turiya State extinguished
The impure effect of Karmic acts
Will still there be.`,
    elaborationTamil: `நெருப்பில் காய்ந்து நெருப்பாகவே இருந்த இரும்பு நெருப்பை விட்டு நீங்கினால் நெருப்பாய் இராமல் இரும்பாகவே யிருக்கும். இருப்பின் நெருப்பின் சூடு விரைவில் ஆறிவிடாது; இருக்கவே செய்யும். அதுபோல நின்மல சாக்கிர சொப்பன சுழுத்தி -களோடு தத்துவங்களின்றும் ஆன்மா நீங்கியபோதிலும் துரியத்திலும் அவற்றில் முன்பு மூழ்கியிருந்த வாசனை இருக்கவே செய்யும்.`,
  },
  {
    id: 2311, tantraId: 8, verseNumber: 2310,
    tamil: `ஆன மறையாதி யாம் உரு நந்திவந்து
ஏனை அருள்செய் தெரிநனா அவத்தையில்
ஆன வகையை விடும்அடைத் தாய்விட
ஆன மாலதீதம் அப்பரந் தானே`,
    transliteration: `āṉa maṟaiyāti yām uru nantivantu
ēṉai aruḷcey terinaṉā avattaiyil
āṉa vakaiyai viṭumaṭait tāyviṭa
āṉa mālatītam apparan tāṉē`,
    english: `2310: In Turiyatita State All Malas Disappear Entire
In the burning state of Jagra avasta
Diverse are the (Jiva's) experiences;
Give them up, give them up entire;
And with Grace of Nandi
That is Veda embodied,
You shall reach the Atita State
Bereft of Malas;
Then shall you the very Para be.`,
    elaborationTamil: `வேதம் முதலாகிய சொல்லுலகங்களையும், மற்றும் பொருள் உலகங்களையும் தனது வடிவமாகக் கொண்டுள்ள சிவன் புலப்பட்டு நின்று, தனது திருவருளாகிய தேனை வழங்குகின்ற நின்மலாவத்தையில் கடக்க வேண்டிய சாக்கிரம் முதல் நான்கையும் கடந்து முடிந்தபின் துரியாதீதமே பாரவத்தையாய் விளங்கும்.`,
  },
  {
    id: 2312, tantraId: 8, verseNumber: 2311,
    tamil: `சுத்த அதீதம் சகலத்தில் தோய்வுறில்
அத்தன் அருள்நீங்கா ஆங்கணில் தானாகச்
சித்த சுகத்தைத் தீண்டாச் சமாதிசெய்து
அத்தனோடு ஒன்றற்கு அருள்முத லாமே`,
    transliteration: `cutta atītam cakalattil tōyvuṟil
attaṉ aruḷnīṅkā āṅkaṇil tāṉākac
citta cukattait tīṇṭāc camāticeytu
attaṉōṭu oṉṟaṟku aruḷmuta lāmē`,
    english: `2311: Relapse Into Sakala State and Redemption by Grace
Those who have reached
The Suddha Atita-State
If to the Sakala State relapse,
Lord's Grace, them leave not;
Still standing close to Lord,
They enjoy not pleasures of world;
And at the end, Samadhi entering,
They in Lord as one unite;
--All these by Grace ultimate.`,
    elaborationTamil: `மத்தியாலவத்தையிற்றானே நின்மல துரியாதீத நிலை (இதுவே 'சாக்கிரத்தில் அதீதம்' எனப்படுவது) தோன்ற, ஆன்மா அதிலே நிலைத்திருக்குமாயின், சிவனது திருவருள் அதனை விட்டு நீங்காது. அந்நிலையில் நீ பராவத்தையை அடைவதற்குச் சித்த சலனத்தால் பற்றக்கூடிய உலகியல் நிலை வந்து சிறிதும் தீண்டாதபடி சமாதி நிலையில் நில். அப்பொழுது முன் சொன்ன திருவருள் உன்னைச் சிவனோடு ஒன்றுபடுத்தும்.`,
  },
  {
    id: 2313, tantraId: 8, verseNumber: 2312,
    tamil: `வேறுசெய் தான்இரு பாதியின் மெய்த்தொகை
வேறுசெய் தான்என்னை எங்கணும் விட்டுய்த்தான்
வேறுசெய் யாஅருள் கேவலத் தேவிட்டு
வேறுசெய் யாஅத்தன் மேவிநின் றானே`,
    transliteration: `vēṟucey tāṉiru pātiyiṉ meyttokai
vēṟucey tāṉeṉṉai eṅkaṇum viṭṭuyttāṉ
vēṟucey yāaruḷ kēvalat tēviṭṭu
vēṟucey yāattaṉ mēviniṉ ṟāṉē`,
    english: `2312: All Are Acts of Grace
He parted Himself
In halves two;
He created the cluster of Tattvas
That to body pertain;
He let me be into births and places several;
He took me into inert Arul Kevala State,
And there left me,
The Lord in me uniting.`,
    elaborationTamil: `எவ்வுயுரினின்றும் தன்னை வேறுபடுத்திக் கொள்ளாது, அதனோடு ஒன்றாகியே, அதற்கு அப்பனாகியும் இருக்கின்ற சிவன். எவ்வுலகிலும் உள்ள உடற்கூட்டத்தை 'ஆண், பெண்' என இருசமபாதிகளாகப் பிரித்து வைத்துள்ளான். என்னையும் தன்னினின்றும் வேறுபடுத்தி, அத்தகையனவாகிய உடம்புகள் உள்ள அனைத்திடங்களிலும் செல்லவிடுத்து, அந்த உடம்புகளுக்குள்ளே புகுத்தினான். பின்பு தன்னினின்றும் என்னை வேறுபடுத்தாது ஒன்றாக்கிக் கொள்கின்ற அருட்கேவலத்திலே செலுத்தி, என்னோடு பொருந்தி நிற்கின்றான்.`,
  },
  {
    id: 2314, tantraId: 8, verseNumber: 2313,
    tamil: `கறங்குஓலை கொள்ளிவட் டம்கட லில்திரை
நிறஞ்சேர் ததிமத்தன் மலத்தே நின்றங்கு
அறங்காண் சுவர்க்க நரகம் புவிசேர்த்து
கிரங்கா உயிர்அரு ளால்இவை நீங்குமே`,
    transliteration: `kaṟaṅkuōlai koḷḷivaṭ ṭamkaṭa liltirai
niṟañcēr tatimattaṉ malattē niṉṟaṅku
aṟaṅkāṇ cuvarkka narakam puvicērttu
kiraṅkā uyiraru ḷālivai nīṅkumē`,
    english: `2313: Power of Grace
The fire wheel of torches made,
The billowy waves of the blue sea,
The curd that stands with the churn
--All these are by some other force moved;
So too, the Jiva pushed by Malas,
Enter hell, heaven and earth
And stand sore troubled;
--All these away vanished
When Grace does descend.`,
    elaborationTamil: `உயிர்கள் காற்றாடியில் உள்ள ஓலைகளைப் போலவும் கொள்ளியைச் சுழற்றுங்காலத்தில் தோன்றுகின்ற வட்ட வடிவுபோலவும், கடலில் அலைகள் போலவும், தயிரைக்கடையும் மத்தைப் போலவும் 'மேல், கீழ், நடு' என்னும் மூன்றுலகங்களிலும் விரையச் சென்று மீண்டு மீண்டு, ஆழ்குழிப்பட்டுத்துன்புற்று, சிவன் அருள்புரிந்தபொழுது அவ்வருளால் ஆழ்குழிகளாகிய இவற்றி னின்றும் மீண்டு கரையேறி, அவனை அடைந்து இன்புறும்.`,
  },
  {
    id: 2315, tantraId: 8, verseNumber: 2314,
    tamil: `தானே சிவமான தன்மை தலைப்பட
ஆன மலமும்அப் பாச பேதமும்
ஆன குணமும் பரான்மா உபாதியும்
பானுவின் முன்மதி போல்பலராவே`,
    transliteration: `tāṉē civamāṉa taṉmai talaippaṭa
āṉa malamumap pāca pētamum
āṉa kuṇamum parāṉmā upātiyum
pāṉuviṉ muṉmati pōlpalarāvē`,
    english: `2314: In Jiva-Siva Union All Fade
When that State is attained,
Where the Self becomes Siva,
The Malas, the Pasas diverse,
Gunas and experiences
That arose for the estranged Jiva,
Will all, all, fade,
Even as does the beams of the moon
In the presence of the rising sun.`,
    elaborationEnglish: ``,
    elaborationTamil: `'ஆன்மாவே சிவம்' என்று சொல்லத்தக்க நிலையை ஆன்மா அடைந்தபின், அநாதியே பொருந்திய சகசமலமாகிய ஆணவமும், அதனை முன்னிட்டு வந்த, 'மாயை' கன்மம், மாயேயம், திரோதாயி, என்னும் பாசவேறுபாடுகளும் அவற்றிற்கு உரியவாய் ஆன்மாவினிடத்து விளங்கிய இழிகுணங் களும், இவை நீங்கினாலும் நீங்கப் பெற்ற சுத்தான்மா விடத்திலும் பின்னும் நிற்கின்ற இவற்றின் வாசனைகளும் சூரியன்முன் சந்திரன் போல அடங்கி ஒடுங்கிவிடும். (வாதிக்கமாட்டா' என்றபடி).`,
  },
  {
    id: 2316, tantraId: 8, verseNumber: 2315,
    tamil: `நெருப்புண்டு நீருண்டு வாயுவும் உண்டங்கு
அருக்கனும் சோமனும் அங்கே அமரும்
திருத்தக்க மாலும் திசைமுகன் தானும்
உருத்திர சோதியும் உள்ளத்து ளாரே`,
    transliteration: `neruppuṇṭu nīruṇṭu vāyuvum uṇṭaṅku
arukkaṉum cōmaṉum aṅkē amarum
tiruttakka mālum ticaimukaṉ tāṉum
uruttira cōtiyum uḷḷattu ḷārē`,
    english: `2315: When Jiva Becomes Pervasive as Siva
Within them,
(Who have attained Siva-State,)
There is fire, water and air;
The sun and the moon are there seated;
Hari, Brahma and Rudra
Are also in their heart.`,
    elaborationTamil: `[இதன்பொருள் வெளிப்படை]`,
  },
  {
    id: 2317, tantraId: 8, verseNumber: 2316,
    tamil: `ஆனைகள் ஐந்தம் அடங்கி அறிவென்னும்
ஞானத் திரியைக் கொளுவி அதனுட்புக்கு
ஊனை இருளற நோக்கும் ஒருவற்கு
வானகம் ஏற வழிஎளி தாமே`,
    transliteration: `āṉaikaḷ aintam aṭaṅki aṟiveṉṉum
ñāṉat tiriyaik koḷuvi ataṉuṭpukku
ūṉai iruḷaṟa nōkkum oruvaṟku
vāṉakam ēṟa vaḻieḷi tāmē`,
    english: `2316: Attain Jnana and Enter Heavenly Home
He who, the elephants of senses five subdues,
Lights the lamp of Jnana
And entering its radiance,
Drives the darkness within;
For him
It is easy
To ascend the Heavenly Home (Siva Loka).`,
    elaborationTamil: `(இதன் பொருளும் வெளிப்படை)`,
  },
  {
    id: 2318, tantraId: 8, verseNumber: 2317,
    tamil: `ஆடிய காலில் அசைக்கின்ற வாயுவும்
தாடித் தெழுந்த தமருக ஓசையும்
பாடி எழுகின்ற வேதாக மங்களும்
நாடியின் உள்ளாக நான்கண்ட வாறே`,
    transliteration: `āṭiya kālil acaikkiṉṟa vāyuvum
tāṭit teḻunta tamaruka ōcaiyum
pāṭi eḻukiṉṟa vētāka maṅkaḷum
nāṭiyiṉ uḷḷāka nāṉkaṇṭa vāṟē`,
    english: `2317: Dance of Siva Seen Within
The moving breeze
That the Dancing Feet wafts;
The vibrant sound
That the Damaruka drum emitts;
The celestial music,
That the chanting Vedas and Agamas produces;
All these in nadis within I experienced.`,
    elaborationTamil: `நான் எனது விருப்பப்படியேவிட்டும், வாங்கியும் இயக்குகின்ற பிராணவாயுவையும், மிகுத்தெழுக்கின்றதமருக ஓசையையும், வல்லுநர்கள் பாடுதலால் எழுகின்ற வேதாகம ஒலிகளையும், நான் கண்ட முறை, சுழுமுனா நாடியினுள்ளாக, நடனத்தில் தூக்கிய காலின் கீழாம்.`,
  },
  {
    id: 2319, tantraId: 8, verseNumber: 2318,
    tamil: `முன்னை அறிவினில் செய்த முதுதவம்
பின்னை அறிவினைப் பெற்றால் அறியலாம்
தன்னை அறிவது அறிவாம் அஃ தன்றிப்
பின்னை அறிவது பேயறி வாகுமே`,
    transliteration: `muṉṉai aṟiviṉil ceyta mututavam
piṉṉai aṟiviṉaip peṟṟāl aṟiyalām
taṉṉai aṟivatu aṟivām aஃ taṉṟip
piṉṉai aṟivatu pēyaṟi vākumē`,
    english: `2318: Self-Knowledge is True Knowledge
The effect of goodly tapas
In past performed,
Can with knowledge
In present be discerned;
Self-knowledge is knowledge true,
The rest is but knowledge demented.`,
    elaborationEnglish: `Insight into the past results from true knowledge. Self-Knowledge is true knowledge. The rest is but false and demented.`,
    elaborationTamil: `முதலில் நிகழும் அறிவு பெரிய தவ அறிவாயும், பின்னர் நிகழும் அறிவு அந்தத்தவத்தால் வரும் மெய்யறிவாயும் நிகழ்தல் வேண்டும். பின்னை அறிவு மெய்யறிவாய் நிகழ்ந்தவழியே முன்னை அறிவு தவ அறிவாய் நிகழ்ந்தமை அறியப்படும், இல்லையேல், அது வெற்றறிவாக அறியப்படும். முதல் அறிவால் நிகழ்ந்த தவத்தால் பெறத்தக்க அறிவாவது, தன்னை உள்ளவாறு அறியும் அறிவே தன்னை உள்ளவாறு அறியாமல் பிறவற்றை அறியும் அறிவுகள் எல்லாம் மருள் அறிவுகளேயாம்.`,
  },
  {
    id: 2320, tantraId: 8, verseNumber: 2319,
    tamil: `செயலற் றிருக்கச் சிவானந்த மாகும்
செயலற் றிருப்பார் சிவயோகம் தேடார்
செயலற் றிருப்பார் செகத்தோடுங் கூடார்
செயலற் றிருப்பார்க்கே செய்தியுண் டாமே`,
    transliteration: `ceyalaṟ ṟirukkac civāṉanta mākum
ceyalaṟ ṟiruppār civayōkam tēṭār
ceyalaṟ ṟiruppār cekattōṭuṅ kūṭār
ceyalaṟ ṟiruppārkkē ceytiyuṇ ṭāmē`,
    english: `2319: In Actionless Contemplation Divine Message Comes
To be actionless is Siva's bliss;
They who are actionless
Seek not Siva Yoga;
They who are actionless
Will not in world merge;
Only to them who are actionless
Is the Divine message to be.`,
    elaborationTamil: `நின்மல துரியத்தை அடைந்தவர்கட்கே, அதன் பின்னர் ஆனந்த நிலையாகிய அதீத நிலை வாய்க்கும். அதனால் அவர் அந்த அதீத நிலையை அடையமுயலுதலன்றி, முன் சொன்ன சிவ யோகத்தைப் புரிய எண்ணமாட்டார்கள். அவ்யோகத்தைப் புரியாமை -யால், அவர்கள் உலகப்பற்றில் வீழ்ந்துவிடமாட்டார்கள். ஆகவே, சிவானுபவமாகிய செயல் ஞான துரியாதீதத்தை அடைந்தவர்கட் கல்லது. ஏனைச் சிவயோகிகட்கு உண்டாகமாட்டாது.`,
  },
  {
    id: 2321, tantraId: 8, verseNumber: 2320,
    tamil: `தான்அவ னாகும் சமாதிகை கூடினால்
ஆன மலம்அறும் அப்பசுத் தன்மைபோம்
ஈனமில் காயம் இருக்கும் இருநிலத்து
ஊனங்கள் எட்டும் ஒழித்தொன்று வோர்கட்கே`,
    transliteration: `tāṉava ṉākum camātikai kūṭiṉāl
āṉa malamaṟum appacut taṉmaipōm
īṉamil kāyam irukkum irunilattu
ūṉaṅkaḷ eṭṭum oḻittoṉṟu vōrkaṭkē`,
    english: `2320: In Samadhi Jiva Unites in Siva
They who attain Samadhi
They and He one become;
Sundered will be Malas,
Vanished the Jiva-State;
Their body (as Divine Light)
Will in Siva's World be;
They in Siva unite
Devoid of blemishes eight.`,
    elaborationTamil: `[கீழாலவத்தை மத்தியாலவத்தைகளை நோக்க, மேலாலவத்தையாகிய யோகாவத்தை நிறைவுடையதேயாம். எனினும், ஞானாவத்தையை நோக்கின் அது குறைவுடையதேயாகும். ஆகையால்] இயமம், நியமம் முதலாக உள்ள அந்த எட்டுறுப்புக் களையும் (சமாதி உட்படக்) கடந்து, நின்மல துரிய நிலையில் ''அவனே தானே ஆகிய அந்நெறி ஏகனாகி நிற்றலாகிய''8 அந்தச் சமாதி கைவந்தால்தான் அநாதி தொட்டே பற்றியுள்ள ஆணவமலம் வாசனையும் இன்றி நீங்கும். (அப்பொழுது பின் வந்த மாயை கன்மங் களாகிய பாசங்களும் அவ்வாறாம். ஆகவே, அப்பொழுதுதான்) ஆன்ம, 'பசு' என்கின்ற நிலைமை நீங்கப்பெற்று, 'சிவம்' எனப்படும் நிலையை எய்தும்.`,
  },
  {
    id: 2322, tantraId: 8, verseNumber: 2321,
    tamil: `தொலையா அரனடி தோன்றும் அம் சத்தி
தொலையா இருளொளி தோற்ற அணுவும்
தொலையாத் தொழின்ஞானம் தொன்மையில் நண்ணித்
தொலையாத பெத்தம்முத் திக்கிடை தோயுமே`,
    transliteration: `tolaiyā araṉaṭi tōṉṟum am catti
tolaiyā iruḷoḷi tōṟṟa aṇuvum
tolaiyāt toḻiṉñāṉam toṉmaiyil naṇṇit
tolaiyāta pettammut tikkiṭai tōyumē`,
    english: `2321: Pedda or Jiva Mukti
At the eternal Feet of Hara,
The Sakti appears;
And as it appears
The interminable darkness
Of Jiva disappears,
And Light dawns;
And Jiva perserveres incessant
In the way of time-honoured Jnana
And thus reaches the State of Pedda (Jiva) Mukti.`,
    elaborationEnglish: ``,
    elaborationTamil: `(இருவினையொப்பு மலபரி பாகம்வந்த பொழுது ஆன்ம அறிவில் பதிகின்ற அருட்சத்தியை மந்ததரம், மந்தம், தீவிரம், தீவிரதரம் என அதன் தன்மை பற்றி வழங்கப்படுமாயினும் அவை 'நிவிர்த்தி, பிரதிட்டை, வித்தை, சாந்தி, சாந்தியதீதை' என்னும் சக்தி களின் வகையாகவே சொல்லப்படுகின்றது.l அந்த ஐந்து சக்திகளும் சிவனது திருவடியேயாம். (அருளை 'அடி' எனக் கூறுதல் மரபு. அதனால், சத்தி நிபாதத்தில் உண்டாகின்ற ஞானமும் 'திருவடி ஞானம்' என்றே கூறப்படும்). அந்த ஞான ஒளி தோன்றியவுடன், அநாதி தொட்டு விடாது பற்றி நிற்கின்ற ஆணவ இருள் நீங்கும். அது நீங்கவே, ஆன்மாவிற்கு இயல்பாய் உள்ள இச்சாஞானக்கிரியா சத்திகள் (ஆணவத்தால் தடுக்கப்பட்டிருந்தனவேயன்றி, அழிக்கப் படாமையால்) விளக்கம் பெற்று ஆன்மாத் தனது இயற்கை நிலையை அடையும். அடைந்த பொழுது முதற்கண் முற்றும் நீங்காத பெத்தமும் அது முற்றும் நீங்கிய முத்தியும் என்னும் இரண்டற்கும் இடைநிலையில் ஆன்மா இருக்கும்.`,
  },
  {
    id: 2323, tantraId: 8, verseNumber: 2322,
    tamil: `தோன்றிய பெத்தமும் முத்தியும் சூழ்சத்தி
மான்றும் தெருண்டும் உயிர்பெறும் மற்றவை
தான்தரு ஞானம் தன் சத்திக்குச் சாதனாம்
ஊன்றல்இல் லாஉள் ளொளிக்கு ஒளி யாமே`,
    transliteration: `tōṉṟiya pettamum muttiyum cūḻcatti
māṉṟum teruṇṭum uyirpeṟum maṟṟavai
tāṉtaru ñāṉam taṉ cattikkuc cātaṉām
ūṉṟalil lāuḷ ḷoḷikku oḷi yāmē`,
    english: `2322: Jiva Knowledge is Doubt-Tossed; Siva Knowledge is
Light Divine
As the Sakti aids the Jiva
In Boddha as well as Mukti
Jiva that is doubt-tossed in the first,
Becomes doubt-free in the second;
And in that condition
Sakti grants its divine instrument
Of Jnana to Jiva;
That verily is the abiding Light
That transcends Jiva's flickering light.`,
    elaborationEnglish: `Jiva that is doubt-tossed in peddha is liberated in mukti. In that condition Sakti grants her divine instrument of jnana to him. That is the everlasting light that swallows the jiva’s flickering light.`,
    elaborationTamil: `உயிர்கள் அவற்றைச் செலுத்துகின்ற சிவசத்தியின் தன்மைக்கு ஏற்ப மயக்க உணர்வைப் பெற்றுப் பெத்தத்தையும், மெய் உணர்வைப் பெற்று முத்தியையும் ஏனெனில், அந்த 'மயக்கம், மெய்' என்னும் இரண்டையும் உயிர்கட்குத் தருகின்ற ஞானமாகிய தன் சத்திக்குச் சத்தனாய் உள்ள சிவன், ஒரு பெற்றியில் நில்லாது இருவேறாய் நிற்கின்ற அந்தச் சத்திக்கு உயிராய் நின்று அதனைச் செலுத்துவன் ஆதலின்.`,
  },
  {
    id: 2324, tantraId: 8, verseNumber: 2323,
    tamil: `அறிகின்றி லாதன ஐஏழும் ஒன்றும்
அறிகின்ற என்னை அறியா திருந்தேன்
அறிகின்றாய் நீயென்று அருள்செய்தான் நந்தி
அறிகின்ற நானென்று அறிந்துகொண் டேனே`,
    transliteration: `aṟikiṉṟi lātaṉa aiēḻum oṉṟum
aṟikiṉṟa eṉṉai aṟiyā tiruntēṉ
aṟikiṉṟāy nīyeṉṟu aruḷceytāṉ nanti
aṟikiṉṟa nāṉeṉṟu aṟintukoṇ ṭēṉē`,
    english: `2323: By Grace Jiva Becomes Knower
Devoid of knowledge
Are Tattvas thirty and six;
The Self that knows
I know not;
"You shall know"
Thus blessed Nandi;
Then I knew
That I am the Knower.`,
    elaborationTamil: `தத்துவங்கள் முப்பத்தாறினையும், அவை தாமே அறிந்தும், செய்தும் வருவனவாக மயங்கி, உண்மையில், 'அவற்றைக் கருவிகளாகக்கொண்டு அறிபவனும்' செய்பவனும் நான்தான்' என்பதையான் பெத்த காலத்தில் அறிந்து கொள்ளாமலே மயங்கி யிருந்தேன். பின்பு நந்திபெருமான், மேற்குறித்த உண்மையை எனக்கு அறிவுறுத்தருளினார். அந்த உண்மையை அங்ஙனமே அறிந்து கொண்டமையால், முத்தனாயினேன்.`,
  },
  {
    id: 2325, tantraId: 8, verseNumber: 2324,
    tamil: `தான்அவ னாகிய ஞானத் தலைவனை
வானவ ராதியை மாமணிச் சோதியை
ஈனமில் ஞானத்து இன்னருள் சத்தியை
ஊனமிலாள்தன்னை ஊனிடைக் கண்டதே`,
    transliteration: `tāṉava ṉākiya ñāṉat talaivaṉai
vāṉava rātiyai māmaṇic cōtiyai
īṉamil ñāṉattu iṉṉaruḷ cattiyai
ūṉamilāḷtaṉṉai ūṉiṭaik kaṇṭatē`,
    english: `2324: Jnana Siva and Jnana Sakti Appeared
He who transformed me into Himself,
He, the Lord of Jnana,
The First of Celestials,
The peerless gem's
Light Resplendent;
And She, Sakti-Grace
Of Jnana Pure,
She, the Immaculate
--Them I saw in this fleshly body.`,
    elaborationTamil: `தான் 'சீவன்' என்கின்ற நிலைமை நீங்கி, 'சிவன்' என்கின்ற நிலைமையை அடைந்த பெரியோன் சிவன் சத்தி இருவனாயும் நேரே கண்டது தன்னுடையே உடம்பிற்குள்ளேயாகும்.`,
  },
  {
    id: 2326, tantraId: 8, verseNumber: 2325,
    tamil: `ஒளியும் இருளும் பரையும் பரையுள்
அளியது எனலாகும் ஆன்மாவை யன்றி
அளியும் அருளும் தெருளும் கடந்து
தெளிய அருளே சிவானந்த மாமே`,
    transliteration: `oḷiyum iruḷum paraiyum paraiyuḷ
aḷiyatu eṉalākum āṉmāvai yaṉṟi
aḷiyum aruḷum teruḷum kaṭantu
teḷiya aruḷē civāṉanta māmē`,
    english: `2325: Love, Jnana, and Bliss of Siva-Sakti
Light and Darkness
Are Parai (Sakti), and the Love within Parai;
Transcend the Self;
Beyond is Love that is Grace,
Transcend the Mala Darkness
Beyond is Light that is Jnana;
Transcend them too;
Then is the Gift that is Siva's-Bliss.`,
    elaborationTamil: `ஆணவ இருளைச் சிறிதே நீக்குவனவாகிய மாயா காரியக் கருவிகளும் அவற்றால் சிறிதே நீக்கப்படுகின்ற ஆணவ இருளும், அதனை நீக்க உதவுகின்ற சிவசத்தியும் அச்சத்தியால் காப்பாற்றப்படும் ஆன்மாவும் ஆகிய இவைகளை முறையாக முன்னர் உணர்தல் வேண்டும். (அவ்வாறு உணர்தலே அரிது. ஆயினும்) அதன்பின் அவற்றோடு நில்லாது ஆன்மாவின் எளிய நிலையையும், அந்நிலையை உணர்ந்து சிவன் அதன்மேல் கொள்ளும் இரக்கத்தையும், அவ்விரக்கத்தால் ஆன்மாவிற்கு உண்டாகின்ற அனைத்துப் பொருள்களையும் பற்றிய உண்மையான உணர்வின் சிறப்பையும் உணர்ந்து, பின் பல பொருள் உணர்வை விடுத்துச் சிவன் ஒருவனையே உணர்கின்ற உணர்வு உண்டாகுமானால், அதன் பின்பே சிவனது பேரின்பம் ஆன்மாவிற்கு உளதாகும்.`,
  },
  {
    id: 2327, tantraId: 8, verseNumber: 2326,
    tamil: `ஆனந்த மாகும் அரனருட் சத்தியில்
தான் அந்த மாம்உயிர் தானே சமாதிசெய்து
ஊன்அந்த மாய் உணர் வாய்உள் உணர்வுறில்
கோன்அந்தம் வாய்க்கும் மகாவா கியமாமே`,
    transliteration: `āṉanta mākum araṉaruṭ cattiyil
tāṉ anta māmuyir tāṉē camāticeytu
ūṉanta māy uṇar vāyuḷ uṇarvuṟil
kōṉantam vāykkum makāvā kiyamāmē`,
    english: `2326 Mahavakyam--Samadhi Jnana Finite
In the Bliss of Grace
That Siva-Sakti confers,
Let Jiva
In final Samadhi enter;
If thus as the end of fleshly body
Jiva realizes the inner awareness,
It shall attain the finite Lordly (Siva) State;
--This, the Word Exalted (Mahavakyam).`,
    elaborationEnglish: ``,
    elaborationTamil: `'சிவானந்தம்' என்பதும் சிவனது அருட் குணங்களில் ஒன்றேயாம். (வரம்பில் இன்பம்) ஆகவே, அச்சத்தி வழியாக ஞான நிலைகளில் முடிநிலையை அடைந்த உயிர் பின் சிவத்திலே அழுந்தி, ஐவகை உடம்புகளினின்றும் நீங்கி, அறிவே வடிவாய், அந்த அறிவுக்கு அறிவாய் உள்ள சிவத்திலேயே பிரிதல் இன்றி நிற்குமாயின் சிவனை முற்றும் பெறுதலாகிய மிகப்பெரிய பேறு உளதாகும்.`,
  },
  {
    id: 2328, tantraId: 8, verseNumber: 2327,
    tamil: `அறிவிக்க வேண்டாம் அறிவற்று அயர்வோர்க்கும்
அறிவிக்க வேண்டாம் அறிவிற் செறிவோர்க்கும்
அறிவுற்று அறியாமை எய்திநிற் போர்க்கே
அறிவிக்கத் தம்அறி வார்அறி வோரே`,
    transliteration: `aṟivikka vēṇṭām aṟivaṟṟu ayarvōrkkum
aṟivikka vēṇṭām aṟiviṟ ceṟivōrkkum
aṟivuṟṟu aṟiyāmai eytiniṟ pōrkkē
aṟivikkat tamaṟi vāraṟi vōrē`,
    english: `2327: Tell Them, Who Know and Yet Know Not
No use telling
Those who are in ignorance steeped;
No use telling
Those who are in Jnana filled;
Tell only them
Who know and yet know not;
Then will they know
And Self-realize.`,
    elaborationTamil: `அறிவித்தாலும் அறியும் தன்மையில்லாத அபக்குவர்க்கும் குருவின் உபதேசம் ஏற்புடையதன்று; (பயன் இன்மையால்) முற்பிறவியிலே கேட்டுச் சிந்தித்துத் தெளிந்தும் நிட்டை கூடாது விட்டமையால் கருவிலே திருஉடையவராய்ப் பிறந்து, ஞானத்தின் திருவுருவாயே நிட்டையை வேண்டி நிற்பவர்க்கும் குருஉபதேசம் வேண்டுவதன்று. எனவே அறிவித்தால் அறியும் பக்குவம் உடையவராய் அறிவிப்பாரை நாடிநிற்கும் அவர்கட்கே ஞான குரவர் உபதேசத்தைச் செய்வராக. பக்குவம் வாய்ப்பினும் தம்மையும், தலைவனையும் குருஉபதேசத்தாலன்றித் தாமாகவே அறிபவர் உலகில் யார் இருக்கின்றார்கள்? (ஒருவரும் இல்லை).`,
  },
  {
    id: 2329, tantraId: 8, verseNumber: 2328,
    tamil: `சத்தும் அசத்தும் சதசத்தும் தான்கூடிச்
சித்தும் அசித்தும் சிவசித்த தாய்நிற்கும்
சுத்தம் அசுத்தம் தொடங்காத துரியத்துச்
சுத்தரா மூன்றுடன் சொல்லற் றவர்களே`,
    transliteration: `cattum acattum catacattum tāṉkūṭic
cittum acittum civacitta tāyniṟkum
cuttam acuttam toṭaṅkāta turiyattuc
cuttarā mūṉṟuṭaṉ collaṟ ṟavarkaḷē`,
    english: `2328: Suddhas Reach Mauna State
Espousing,
The Sat, Asat, and Sat-Asat,
The Jiva becomes
The Chit, Achit, and Siva-Chit;
Those that reach that Turiya State
Where neither Suddha (Pure) or Asuddha (Impure) Maya is,
They verily are the Suddhas (Pure ones);
Transcending the States three,
(Sat, Asat and Sat-Asat)
They reach Silentness, surpassing.`,
    elaborationEnglish: ``,
    elaborationTamil: `சகலத்தில் சுத்தமாகிய மேலாலவத்தையும், (யோகாவத்தையும்) சகலத்திற் சகலமாகிய மத்தியாலவத்தையும், சகலத்தில் கேவலமாகிய கீழாலவத்தையும் ஆகிய இவைகளின் தொடர்புகள் சிறிதும் இல்லாது நீங்கிய நின்மல துரியத்தில் நிற்றலால் சுத்தான்மாக்களாய், சொல் நிகழ்ச்சி அத்துரியத்திற்கு முற்பட்ட, 'சாக்கிரம், சொப்பனம், சுழுத்தி' என்னும் மூன்றோடே நீங்கப் பெற்றவர்கட்கு, சத்தாய் உள்ள சிவமும், அசத்தாய் உள்ள பாசங்களும், சதசத்தாய் உள்ள ஆன்மாவும் முறையே சித்தும், அசித்தும், சிதசித்தும் ஆதல் முற்ற அனுபவமாய் விளங்கும்.`,
  },
  {
    id: 2330, tantraId: 8, verseNumber: 2329,
    tamil: `தானே அறியான் அறிவிலோன் தானல்லன்
தானே அறிவான் அறிவு சதசத்தென்று
ஆனால் இரண்டும் அரனரு ளாய்நிற்கத்
தானே அறிந்து சிவத்துடன் தங்குமே`,
    transliteration: `tāṉē aṟiyāṉ aṟivilōṉ tāṉallaṉ
tāṉē aṟivāṉ aṟivu catacatteṉṟu
āṉāl iraṇṭum araṉaru ḷāyniṟkat
tāṉē aṟintu civattuṭaṉ taṅkumē`,
    english: `2329: Higher Knowledge is Beyond Self-Knowledge
By himself Jiva knows not;
Yet is he not without (Higher) knowledge;
The knowledge he himself has
Is Sat-Asat;
When the two as Grace descend
Then he knows himself,
And with Siva one becomes.`,
    elaborationEnglish: `When the two, Siva and Sakti, descend as Grace, jiva knows both himself and the Lord.`,
    elaborationTamil: `புருடன், (ஆன்மா) பிறிதொரு பொருள் அறிவியாமல் தானாகவே ஒன்றையும் அறியும் தன்மையுடைய னல்லன்; அதனால், அவன் அறிவில்லாத சடப்பொருளும் அல்லன். ('அறிவித்தால் அறிவான்' என்றபடி). இத்தன்மை உடைய இவன், பிறர் அறிவிக்க வேண்டாது, தானே எல்லாவற்றையும் அறிபவனாகிய சிவனது அறிவைக்கொண்டு தன்னை முன்மந்திரத்திற் கூறியவாறு, 'சதசத்து' என அறிவானாயின்' அப்பொழுது இவனும், இவனால் சாரப்பட்ட கருவித்தொகுதியும் சிவனது அருளாகியே நிற்கும். ('இவனும் சிவமாகி, இவனது கரணங்களும் சிவகரணமாய்விடும்' என்றபடி). அங்ஙனம் நிற்கவே, முன்பு அசித்தோடு கூடி அசித்தாய் இருந்த, அல்லது ஏகதேசமாய் அறியும் சிற்றறிவை உடையவனாய் இருந்த இவனே, எல்லாவற்றையும் அறியும் அறிவுடையவனாகிச் சிவத்தோடே கூடி இரண்டற்றிருப்பான்.`,
  },
  {
    id: 2331, tantraId: 8, verseNumber: 2330,
    tamil: `தத்துவ ஞானம் தலைப்பட் டவர்க்கே
தத்துவ ஞானம் தலைப்பட லாய்நிற்கும்
தத்துவ ஞானத்துத் தான்அவ னாகவே
தத்துவ ஞானானந் தந்தான் தொடங்குமே`,
    transliteration: `tattuva ñāṉam talaippaṭ ṭavarkkē
tattuva ñāṉam talaippaṭa lāyniṟkum
tattuva ñāṉattut tāṉava ṉākavē
tattuva ñāṉāṉan tantāṉ toṭaṅkumē`,
    english: `2330: Master Tattva-Knowledge and Attain God-Knowledge
Only for them who master
The knowledge of Tattvas, (Tattva-Jnana)
Will the Higher Knowledge (God-Knowledge) be;
In that Higher Knowledge,
The Self with Siva one becomes;
Then has begun the Bliss of God-Knowledge.`,
    elaborationTamil: `மாயாகாரியங்களாகிய கருவிகளின் உண்மையை உணர்ந்தவர்கட்கே மெய்ப்பொருளாகிய சிவத்தை உணரும் உணர்வு கிடைக்கும். அந்த உணர்வானே ஆன்மாச் சிவமாம் தன்மையை அடையும். அதனை அடையவே, அந்தச் சிவஞானமே சிவபத்தி -யாய்ப் பரிணமிக்க, அந்தப் பத்தியால் சிவானந்தம் விளைவதாகும்.`,
  },
  {
    id: 2332, tantraId: 8, verseNumber: 2331,
    tamil: `தன்னை அறிந்து சிவனுடன் தானாக
மன்னும் மலம்குணம் மாளும் பிறப்பறும்
பின்அது சன்முத்தி சன்மார்க்கப் பேரொளி
நன்னது ஞானத்து முத்திரை நண்ணுமே`,
    transliteration: `taṉṉai aṟintu civaṉuṭaṉ tāṉāka
maṉṉum malamkuṇam māḷum piṟappaṟum
piṉatu caṉmutti caṉmārkkap pēroḷi
naṉṉatu ñāṉattu muttirai naṇṇumē`,
    english: `2331: Self-Knowledge Leads to Jnana-Mudra
When Jiva attains Self-Knowledge,
Then he one with Siva becomes;
The Malas perish;
Birth's cycle ends;
Then will goodly Mukti be;
The lustrous light of Jnana;
And the Impress of Divine Knowledge too (Chin Mudra).`,
    elaborationTamil: `ஆன்மாத் தனது இயல்பை உள்ளவாறறிந்தால் தான் பாசத்துடன் நில்லாது சிவத்துடனே நிற்கும். அவ்வாறு நிற்கும் பொழுதுதான் மலங்களின் சேட்டை ஒழியும். பாசங்களின் சேட்டை ஒழிவே பிறப்பின் ஒழிவாகும். எவ்வாற்றானும் மீண்டும் பிறவி எய்தாத நிலையே முடிநிலைப் பரமுத்தியாகும். மற்றும் அதுவே நன்னெறியாகிய ஞானத்தால் அடையப்படும் பேரறிவுப் பொருளும் ஆகும். அது சின்முத்திரை வழியாகக் கிடைக்கும்.`,
  },
  {
    id: 2333, tantraId: 8, verseNumber: 2332,
    tamil: `ஞானம்தன் மேனி கிரியை நடுஅங்கம்
தானுறும் இச்சை உயிராகத் தற்பரன்
மேனிகொண்டு ஐங்கரு மத்தவித் தாதலான்
மோனிகள் ஞானத்து முத்திரை பெற் றார்களே`,
    transliteration: `ñāṉamtaṉ mēṉi kiriyai naṭuaṅkam
tāṉuṟum iccai uyirākat taṟparaṉ
mēṉikoṇṭu aiṅkaru mattavit tātalāṉ
mōṉikaḷ ñāṉattu muttirai peṟ ṟārkaḷē`,
    english: `2332: Maunis Receive Jnana Mudra
Jnana (Knowledge) is His Form;
Kriya (Action) is His middle part;
Ichcha (Desire) is His life beat;
--Thus is His Aspect
Of the Uncreated Being (Tatpara);
He is as the seed of
The five acts He performs
(Of creation, preservation, dissolution, obfuscation and redemption)
And so,
The Maunis (in silentness seated) received
The Mudra (Impress of God-Knowledge) that is Jnana.`,
    elaborationTamil: `(சிவனுக்கு வடிவமாய் அமைவது. அவனது சத்தியே. அதனை, ''காயமோமாயை அன்று; காண்பது சத்தி தன்னால்l என்னும் சிவஞான சித்தியால் அறியலாம். 'அரிதரு கண்ணியாணை ஒருபாகமாக அருள் காரணத்தில் வருவார்''3 என அருளிச் செய்ததும் இதனையே. அவ்வாறு ஆகுமிடத்து.)
ஞானசத்தியே உடல். கிரியாசத்தியே உடலில் உள்ள பல உறுப்புக்கள். இச்சாசத்தியே 'உயிர்களை உய்விக்கவேண்டும்' என்னும் கருணையாய் உள்ளிருந்து உந்துவதாய் மேற்கூறியவைகளை இயக்கும் உயிராகும். இவைகளையெல்லாம் கொண்டு அவன் செய்யும் தொழில்கள் ஐந்து. (படைத்தல், காத்தல், அழித்தல், மறைத்தல், அருளல்). இங்ஙனம் ஆகலின் அவ்வைந்தொழிலில் இறுதிக்கண்ணதாகிய அருளலை தற்போதம் அற்றிருந்தவர்கள் மட்டுமே பெற்றார்கள் ('பிறரெல்லாம் ஏனை நான்கையே பெறுகின்றனர்' என்பதாம்).`,
  },
  {
    id: 2334, tantraId: 8, verseNumber: 2333,
    tamil: `உயிர்க்குஅறி உண்மை உயிர்இச்சை மானம்
உயிர்க்குக் கிரியை உயிர்மாயை சூக்கம்
உயிர்க்குஇவை ஊட்டுவோன் ஊட்டும் அவனே
உயிர்ச்சொல் அன்றி அவ்வுளத்து ளானே`,
    transliteration: `uyirkkuaṟi uṇmai uyiriccai māṉam
uyirkkuk kiriyai uyirmāyai cūkkam
uyirkkuivai ūṭṭuvōṉ ūṭṭum avaṉē
uyirccol aṉṟi avvuḷattu ḷāṉē`,
    english: `2333: Lord Acts From Within Jiva
For Jiva,
Jnana Sakti gives Knowledge
Ichcha Sakti gives Desire
Kriya Sakti gives Action
All these are subtle;
He who grants these to Jiva
Is Lord Himself,
And not Jiva;
It is Lord that acts from within Jiva.`,
    elaborationTamil: `[முன்மந்திரத்தில் சிவனுக்கு உள்ளனவாகக் கூறிய ஞான சத்தி இச்சா சத்தி கிரியா சத்திகள் உயிர்கட்கும் உள்ளன, அஃது எவ்வாறு பெறப்படுகின்றது எனின்,], 'சடப்பொருள்கட்கு வேறாய் உயிர் உண்டு' என உணரவைப்பதே உயிரினது ஞான சத்திதான், (அஃதாவது, எங்கே அறிவு நிகழ்கின்றதோ அங்கெல்லாம் 'உயிர் உள்ளது' என உணரப்படுகின்றது என்பதாம்). இனி, அந்த அறிவு 'யான்' எனத் தன்னைப் பற்றியும், 'எனதும்' எனப் பிற பொருளைப் பற்றியும் கொள்கின்ற பற்றும் இச்சாசத்தியின் செயலேயாகும், அந்தப் பற்றுக் காரணமாக உயிர் பலவான மாயா காரியப் பொருள்களைச் செயற்படுத்தி, அவற்றால் பயன் உறுவது கிரியா சத்தியின் செயற் பாடே. இவ்வாறு இவை நுட்பமாக ஓர்ந்துணரத்தக்கன. (அங்ஙனம் உணராமல், 'உயிர்கட்கு இந்தச் சத்திகள் இல்லை' என்று கருதிவிடுதல் கூடாது). எனினும், உயிர்கட்கு அவற்றின் வினைப்பயன்களை ஊட்டுவிக்கின்ற சிவன் செயற்படுத்தவே இச்சத்திகள் செயற்படும். ஆகையால், உயிர்கள் செய்யும் செயல்கள் அவைகளே தனி நின்று செய்யும் செயல்கள் ஆகாது, அவற்றுள் உயிர்க்கு உயிராய் நிறைந்து நிற்கும் சிவன் செயல்களே ஆகின்றன.`,
  },
  {
    id: 2335, tantraId: 8, verseNumber: 2334,
    tamil: `தொழில்இச்சை ஞானங்கள் தொல்சிவசீவர்
கழிவற்ற மாமாயை மாயையின் ஆகும்
பழியற்ற காரண காரியம் பாழ்விட்டு
அழிவற்ற சாந்தாதீ தன்சிவ னாமே`,
    transliteration: `toḻiliccai ñāṉaṅkaḷ tolcivacīvar
kaḻivaṟṟa māmāyai māyaiyiṉ ākum
paḻiyaṟṟa kāraṇa kāriyam pāḻviṭṭu
aḻivaṟṟa cāntātī taṉciva ṉāmē`,
    english: `2334: Siva Acting Through Mayas is Eternal and Beyond
Action, Desire and Jnana of Jivas
With Siva acting within
Are work of Mamaya and Maya (Impure and Pure);
But beyond the Void of Cause-Effect,
Is Siva,
Eternal and of Peace Exceeding (Santa-atita).`,
    elaborationTamil: `'கிரியை, இச்சை, ஞானம்' என்பன சிவனுக்கு என்றும் இயல்பாகவே விளங்கி நிற்கின்றன. 'உயிர்கட்கோ' எனின், அவை அனாதியே ஆணவ மலத்தால் மறைக்கப்பட்டுப் பின்பு சிவனால் கூட்டப் பெறுகின்ற சுத்தமாயை அசுத்த மாயைகளின் காரியங்களில் அவை சிறிதே விளங்குகின்றன. சிவன் இந்த மாயைகள், அவற்றின் காரியங்கள், ஆணவம் ஆகிய அனைத்தையும் கடந்து, நிலைத்து நிற்பதாகிய துரியாதீத நிலையில் இருக்கின்றான்.`,
  },
  {
    id: 2336, tantraId: 8, verseNumber: 2335,
    tamil: `இல்லதும் உள்ளதும் யாவையும் தானாகி
இல்லதம் உள்ளது மாய்அன்றாம் அண்ணலைச்
சொல்வது சொல்லிடில் தூராகி தூரமென்று
ஒல்லை உணர்ந்தால் உயிர்க்குயி ராகுமே`,
    transliteration: `illatum uḷḷatum yāvaiyum tāṉāki
illatam uḷḷatu māyaṉṟām aṇṇalaic
colvatu colliṭil tūrāki tūrameṉṟu
ollai uṇarntāl uyirkkuyi rākumē`,
    english: `2335: Lord Who is Beyond-Beyond is Yet Life of Life
Immanent is He
In Real, the Unreal and all;
He is Lord
That is the Real, Unreal and Real-Unreal;
Beyond, beyond speech is He;
Hasten and realize,
He will be the Life of your life.`,
    elaborationTamil: `உணருமாற்றால் உணராதவர்களால், 'இல்லை' என மறுத்துக் கூறப்படும் பொருளாய் உள்ளவனும், உணருமாற்றால் உணர்ந்தவர்களால், 'உண்டு' என நிறுவப்படும் பொருளாய் உள்ளவனும், உலகின்கண், 'சூக்குமம், தூலம்' என்னும் இருவகைப் பட்ட எல்லாப் பொருள்களிலும் ''அவையே தானாய்''க்* கலந்து நிற்பினும், அவற்றின் தன்மையைத் தான் எய்தாமையால் அவற்றின் வேறாய் உள்ளவனும் ஆகிய முதல்வனாம் சிவனை வாக்குக் குறிப்பிட முயலுமாயின் அதற்கு எட்டாத நெடுந்தொலைவில் உளன். இவ்வுண்மையை உயிர் எவ்வளவு விரைவாக அவ்வளவு விரைவில் அதன் உள்ளுயிராய் விளங்கி நிற்பான்.`,
  },
  {
    id: 2337, tantraId: 8, verseNumber: 2336,
    tamil: `உயிரிச்சை யூட்டி உழிதரும் சத்தி
உயிரிச்சை வாட்டி ஒழித்திடும் ஞானம்
உயிரிச்சை யூட்டி யுடனுறலாலே
உயிரிச்சை வாட்டி உயர்பதஞ் சேருமே`,
    transliteration: `uyiriccai yūṭṭi uḻitarum catti
uyiriccai vāṭṭi oḻittiṭum ñāṉam
uyiriccai yūṭṭi yuṭaṉuṟalālē
uyiriccai vāṭṭi uyarpatañ cērumē`,
    english: `2336: Scorch Desires Worldly
Sakti (Ichcha) infuses desires
And haresses Jiva;
Jnana (Sakti) scorches them
And destroys them;
As She who infuses desires into Jiva
Is within,
Do you scorch your worldly desires,
And attain the State Exalted.`,
    elaborationTamil: `சிவனது சத்தி (உயிர்கள் பக்குவம் எய்தாத பொழுது) அவற்றுக்கு உலகின்மேல் ஆசையை உண்டாக்குதலும், (பக்குவம் எய்திய பொழுது) அவற்றுக்கு அவ்வாசையைப் போக்குதலும் ஆகிய இரு செயல்களைச் செய்யும். (முன்னை நிலையில் திரோதான சத்தியாயும், பின்னை நிலையில் அருட் சத்தியாயும் அது நிற்கும். திரோதானசத்தி, 'ஆதி சத்தி' என்றும் சொல்லப்படும்) உயிருக்கும் உலக ஆசை நீங்கிய பொழுது அருட் சத்தி உயிரை அசத்தை விடுத்து சத்தினை நாடுதலில் விருப்பம் உண்டாக்கி, இவ்வாறு அதனுடன் என்றும் உடனாய் நிற்றலால்தான் உயிர் உலகப் பற்றினை ஒழித்து, மேலான வீட்டினைச் சேர்வதாகின்றது.`,
  },
  {
    id: 2338, tantraId: 8, verseNumber: 2337,
    tamil: `சேரும் சிவமானார் ஐம்மலம் தீர்ந்தவர்
ஓர்ஒன்றி லார் ஐம் மலஇருள் உற்றவர்
பாரின்கண் விண்நர கம்புகும் பான்மையர்
ஆருங்கண் டோ ரார் அவையருள் என்றே`,
    transliteration: `cērum civamāṉār aimmalam tīrntavar
ōroṉṟi lār aim malairuḷ uṟṟavar
pāriṉkaṇ viṇnara kampukum pāṉmaiyar
āruṅkaṇ ṭō rār avaiyaruḷ eṉṟē`,
    english: `2337: Rid of Malas
They who with Siva unite
Are of Malas Five rid;
They who do not unite thus
Are of dark Malas Five possessed;
Destined are they to be born
On Earth, Heaven and Hell;
None know,
All these from His Grace results.`,
    elaborationTamil: `'மலம்' எனப்படும் ஐந்தும் நீங்கப் பெற்றவர்களே சிவமாந்தன்மையைப் பெற்றார்கள். அவற்றுள் ஒன்று ஒன்று நீங்கப் பெற்றவர்களும், ஒருமலமேனும் நீங்கப் பெறாதவர்களும் நிலத்திற் பிறந்து, பின் சுவர்க்கத்திலும், நரகத்திலும், புகும் பகுதியினரேயாவர். ஆயினும், 'இவ்விருவகை நிலைகளும் சிவனது கருணை காரணமாக அவனது சத்தியாலே நிகழ்வன' என்பதை அறிபவர் உலகத்தில் அரியர்.`,
  },
  {
    id: 2339, tantraId: 8, verseNumber: 2338,
    tamil: `எய்தினர் செய்யும் இருமாயா சத்தியின்
எய்தினர் செய்யும் இருஞான சத்தியின்
எய்தினர் செய்யும் இருஞால சத்தியின்
எய்தினர் செய்யும் இறையருள் தானே`,
    transliteration: `eytiṉar ceyyum irumāyā cattiyiṉ
eytiṉar ceyyum iruñāṉa cattiyiṉ
eytiṉar ceyyum iruñāla cattiyiṉ
eytiṉar ceyyum iṟaiyaruḷ tāṉē`,
    english: `2338: All Acts Are of Lord's Grace
They who are caught
By forces of Maya twine (Pure and Impure)
Do things according;
They who are caught
By forces of Jnana
Act appropriate;
They who are caught
By forces of world desires
Behave that way;
--All these they do
Are acts of Lord's Grace.`,
    elaborationTamil: `ஏற்புடைய செயல்களை ஏற்குமாற்றால் செய்யும் இறைவனுடைய கருணை பரிக்கிரக சத்தியாகிய 'சுத்த மாயை, அசுத்த மாயை' என்னும் இரு மாயைகளின் ஆற்றலைக் கொண்டும், 'மந்தம, தீவிரம்' என்னும் இருவகை அருட் சத்தியைக் கொண்டும், கன்மத்தின் வழியாக, 'இன்பம், துன்பம்' என்னும் இரண்டை ஊட்டுகின்ற திரோ தான சத்தியைக் கொண்டும் அவ்வப்பொழுது ஏற்புடையவற்றைச் செய்யும்.`,
  },
  {
    id: 2340, tantraId: 8, verseNumber: 2339,
    tamil: `திருந்தினர் விட்டார் திருவில் நரகம்
திருந்தினர் விட்டார் திருவார் சுவர்க்கம்
திருந்தினர் விட்டார் செறிமலர் கூட்டம்
திருந்தினர் விட்டார் சிவமாய் அவமே`,
    transliteration: `tiruntiṉar viṭṭār tiruvil narakam
tiruntiṉar viṭṭār tiruvār cuvarkkam
tiruntiṉar viṭṭār ceṟimalar kūṭṭam
tiruntiṉar viṭṭār civamāy avamē`,
    english: `2339: Wealth of Holiness Leads to Union in Siva
They that are possessed of wealth of Holiness
Are not for dark Hell destined;
They that are possessed of wealth of Holiness
Are not for delicious heaven too;
They that are possessed of wealth of Holiness
Depart from Mala's huddle;
They that are possessed of wealth of Holiness
Depart from all things unworthy;
And so Siva become.`,
    elaborationTamil: `ஆணவ மலத்தால் வளைக்கப்பட்ட கோணல் நீங்கி நேரான நிலையை அடைந்தோர் சிவமே ஆயினமையால், சுவர்க்கத்தை விரும்புதல், நரகத்திற்புகுதல், மாயை கன்மங்களின் குழாத்துள் இருத்தல், அவற்றால் பிறந்து இறந்தும், இறந்துபின் பிறந்து உழல்வதாகிய பயனில் செயல்களை உடையராதல் ஆகிய இவை அனைத்தையும் விட்டு நலம் பெற்றார்கள்.`,
  },
  {
    id: 2341, tantraId: 8, verseNumber: 2340,
    tamil: `அவமும் சிவமும் அறியார் அறியார்
அவமும் சிவமும் அறிவார் அறிவார்
அவமும் சிவமும் அருளால் அறிந்தால்
அவமும் சிவமும் அவனரு ளாமே`,
    transliteration: `avamum civamum aṟiyār aṟiyār
avamum civamum aṟivār aṟivār
avamum civamum aruḷāl aṟintāl
avamum civamum avaṉaru ḷāmē`,
    english: `2340: Knowledge of What is God's, What is World's Comes from
Grace
Ignorant are they
Who do not know
What is God's
And what is World's;
Only they are wise
Who both these know;
When both these they know,
By His Grace,
They shall of His Grace know;
Both these are.`,
    elaborationEnglish: ``,
    elaborationTamil: `அவம் - பயன் இன்மை. பயனாவது நன்மையே, எனவே, ''அவம்'' என்றது, 'நன்மை இன்மை' என்றபடி. அது தீமை உடையதாகவும் இருக்கலாம். சிவம் - நன்மை. 
பகுத்தறிவில்லாதவர், 'இஃது அவம், இது சிவம்' எனப்பகுத் துணர மாட்டார். (ஆகவே, 'அவர் அவத்தைச் சிவமாக எண்ணி, அதனைப் பற்றிக்கொண்டு உழல்வர்' என்பதாம்). பகுத்தறி வுடையவர் அவற்றை நன்கு பகுத்துணர்வார். (ஆகவே 'அவர் அவத்தை விடுத்துச் சிவத்தைப் பற்றி நன்மையடைவர்' என்பதாம்). பகுத்தறிவு திருவருளால் வாய்ப்பது. அங்ஙனம் வாய்க்கப்பெற்று, அவத்தினையும், சிவத்தினையும் உள்ளவாறு உணர்ந்தால், பகுத்தறிவு இல்லாத பொழுது, 'உயிர் அவத்தில் உழன்றதும் சிவனது அருளால்தான் பின்பு அதனைவிடுத்துச் சிவத்தைப் பற்றியதும் சிவனது அருளால்தான் என்பது அனுபவமாய் விளங்கிவிடும்.`,
  },
  {
    id: 2342, tantraId: 8, verseNumber: 2341,
    tamil: `அருளான சத்தி அனல் வெம்மை போல
பொருள் அவனாகத்தான் போதம் புணரும்
இருள் ஒளியாய் மீண்டு மும்மல மாகும்
திருவருள் ஆனந்தி செம்பொருளாமே`,
    transliteration: `aruḷāṉa catti aṉal vemmai pōla
poruḷ avaṉākattāṉ pōtam puṇarum
iruḷ oḷiyāy mīṇṭu mummala mākum
tiruvaruḷ āṉanti cemporuḷāmē`,
    english: `2341: Grace of Sakti Leads to Siva
As fire and heat
Are Siva and Sakti;
With Him as Substance
She, Jiva's awareness espouses;
Darkness and Light She is;
She pervades too Malas Three;
And then by Light of Grace
She makes Jiva the very Siva.`,
    elaborationEnglish: `Siva and Sakti are like fire and heat. She is with Him, espousing divine awareness. She is darkness (obfuscation) and light (Revealing Grace). As darkness She pervades the three malas. Then by the light of Grace She liberates the jiva and aids him to become Siva — the Nandi that is Pure Truth.`,
    elaborationTamil: `['சிவன் அருள்' என்றும், 'சிவனது சத்தி' என்றும் சொல்லப்படுவது ஒருபொருளேயாகும். அதனால்,] அருளாகிய சத்தி, தீ பொருளாய் இருக்க, சூடு அதன் பண்பாய் அதன்கண் வேற்றுமையின்றியிருத்தல்போல, சிவம் பொருளாய் இருக்க, தான் அதன் பண்பாய் அதன்கண் வேற்றுமையின்றி யிருக்கும். அங்ஙனம் இருக்கும்பொழுது அறிவாகியேயிருக்கும். (இது சத்தியின் 'உண்மை' எனப்படும் சொரூபம்) அதுவே, 'ஆணவம், மாயை, கன்மம்' என்னும் மும் மலங்களாயும் நின்று (உயிர்கள் சிவனை அறியாதபடி மறைக்கும். இந்நிலையில் அது, 'திரோதனகரி, திரோதாயி' - என்னும் பெயர்களைப் பெறும். இஃது அதன், 'பொது' எனப்படும் தடத்தம்) பின்பு அதுவே தனது உண்மையான அருளாகும்பொழுது, சிவன் உயிர்களுக்கு முன்போல மறைந்து நில்லாமல், இனிது விளங்கும் பொருளாய்த் திகழ்வான்.`,
  },
  {
    id: 2343, tantraId: 8, verseNumber: 2342,
    tamil: `ஆதித்தன் தோன்ற வரும்பது மாதிகள்
பேதித்த தவ்வினை யாற்செயல் சேதிப்ப
ஆதித்தன் தன்கதி ரால்அவை சேட்டிப்பப்
பேதித்தப் பேதியா வாறுஅருட் பேதமே`,
    transliteration: `ātittaṉ tōṉṟa varumpatu mātikaḷ
pētitta tavviṉai yāṟceyal cētippa
ātittaṉ taṉkati rālavai cēṭṭippap
pētittap pētiyā vāṟuaruṭ pētamē`,
    english: `2342: States of Grace-Receiving Differ7As the sun rises,
As the sun rises,
The lotuses wake;
But some bloom,
And some do not;
That happens
As their differing conditions are;
Even though sun's beams
Alike strike them,
The differing effects
Are result of
Differing states of Grace.`,
    elaborationEnglish: `The yogi then beholds in this fleshy body Jnana Siva—the beginning of celestials and the peerless gem-light that shines effulgent — and the immaculate jnana sakti of Grace too.`,
    elaborationTamil: `'படைக்கும் சத்தி, காக்கும் சத்தி, அழிக்கும் சத்தி' என இவ்வாறு சத்திகள் வேறு வேறாகச் சொல்லப்படினும், உண்மையில், அவை அனைத்தும ஒரு சத்தியின் பேதங்களே. அஃது எவ்வாறெனி ல் பூக்கள் அனைத்தும் ஒரு நிலையையே அடையாமல் பல நிலைகளை அடைகின்றன. (சில அரும்பாகவும், சில போதுக ளாகவும், சில மலர்களாகவும்,சில வாட்லகளாகவும் ஆகின்றன) அந்த வேறுபட்ட நிலைகள் அனைத்திற்கும் ஏற்பச் சூரியனது கதிர்கள்' என்னும் வகையில் ஒன்றேயாவது போல்வதாம்.`,
  },
  {
    id: 2344, tantraId: 8, verseNumber: 2343,
    tamil: `பேதம் அபேதம் பிறழ்பேதா பேதமும்
போதம் புணர்போதம் போதமும் நாதமும்
நாத முடன்நாக நாதாதி நாதமும்
ஆதன் அருளின் அருள்இச்சை யாமே`,
    transliteration: `pētam apētam piṟaḻpētā pētamum
pōtam puṇarpōtam pōtamum nātamum
nāta muṭaṉnāka nātāti nātamum
ātaṉ aruḷiṉ aruḷiccai yāmē`,
    english: `2343: All Forms of Knowledge Proceed From Grace
Bheda (Difference), Abheda (Non-difference)
And Bheda-Abheda (Difference-Non-difference),
Knowledge native,
Knowledge that comes of learning,
And God-Knowledge;
Nada, (Sound)
And the Nada-Beyond-Nada, (the Nadanta that is Beyond-Beyond Sound)
All these come by Grace of the Holy One.`,
    elaborationTamil: `'சிவனது அருள்' எனப்படும் சத்தி, உலகுயிர் களோடு பொருள் தன்மையால் வேறாய் நின்று அவற்றை அறிவித்தும், இயக்கியும் நிற்றல், அவ்வாறு நிற்பினும் தான் அவற்றின் வேறாய்த் தோன்றாது ஒன்றேயாய் நிற்றல் என்னும் இவ்வகைகளால் ஒரு வகையில் பேதமாயும், பிறிதொரு வகையில் அபேதமாயும் இருத்தலும், மலங்களை நீக்குதலால் உயிர்களின் அறிவை விளக்கு தலால் அறிவாயும், மலங்களைச் செலுத்துதலால் அவற்றின் அறிவை மறைத்து அறியாமையாயும் இவ்வகைகளால் ஒருவகையில் அறிவாயும், பிறிதொரு வகையில் அறியாமையாயும், நாதத்தை எழுப்புதலால் நாத மாயும், அதனை ஒடுக்குதலால் நாதம் இல்லதாயும் இவ் வகை களால் ஒரு வகையில் நாதமாயும், பிறிதொரு வகையில் நாதம் இல்ல தாயும் இவ்வாறெல்லாம் பேதப்பட்டு நிற்றல் அதன் இச்சையாலேயாம்.`,
  },
  {
    id: 2345, tantraId: 8, verseNumber: 2344,
    tamil: `மேவிய பொய்க்கரி யாட்டும் வினையெனப்
பாவிய பூதம்கொண்டு ஆட்டிப் படைப்பாதி
பூவியல் கூட்டத்தால் போதம் புரிந்தருள்
ஆவியை நாட்டும் அரன்அரு ளாமே`,
    transliteration: `mēviya poykkari yāṭṭum viṉaiyeṉap
pāviya pūtamkoṇṭu āṭṭip paṭaippāti
pūviyal kūṭṭattāl pōtam purintaruḷ
āviyai nāṭṭum araṉaru ḷāmē`,
    english: `2344: Play of Hara's Grace
Unto the artificial elephant
On stilt played,
Is the play of Hara's Grace;
With the aid of elements (Tattvas), it sways Jiva,
And makes it dance this way and that,
And consigning it to life and worldly ways,
Infuses the Light of Jnana
And finally plants it (Jiva) in Life of Grace;
All, all, the work of Grace.`,
    elaborationTamil: `மனிதன் ஒருவன், யானைபோலப் பொய்யாகச் செய்யப்பட்ட பொறியினுட் புகுந்து மறைந்து கொண்டு, அதனை உயிருடையது போலப் பலவகையில் இயங்கச் செய்யும் செயல்போல, அருள் மாயையின் காரியமாய்ப் பரந்து விரிந்த உலகினுள் மறைந்து நின்று அதனைப் பலவகையாக இயங்கச்செய்து, அதனானே உயிரினது அறிவைப் படைத்தல் முதலிய தொழில்களால் பலவாறாக விளங்குவித்து, அவ் இயக்கத்துட்பட்டு அலமரச் செய்யும். 'அருள்' எனப்படுவது சிவனது அருளே.`,
  },
  {
    id: 2346, tantraId: 8, verseNumber: 2345,
    tamil: `ஆறாது அகன்று தனையறிந் தானவன்
ஈறாகி யாவினும் இயலாவும் தனில்எய்த
வேறாய் வெளிபுக்கு வீடுற்றான் அம்மருள்
தேறாத் தெளிவுற்றுத் தீண்டச் சிவமாமே`,
    transliteration: `āṟātu akaṉṟu taṉaiyaṟin tāṉavaṉ
īṟāki yāviṉum iyalāvum taṉileyta
vēṟāy veḷipukku vīṭuṟṟāṉ ammaruḷ
tēṟāt teḷivuṟṟut tīṇṭac civamāmē`,
    english: `2345: When Tattvas Are Transcended, Grace Descends and
He, Jiva,
Abandoning Tattvas six times six
Realized the Self;
He the Finite became
And pervaded,
He (Jiva) in them (Tattvas) and they in him;
Yet transcending them
He passed into the Beyond;
And as Grace descends on him
He doubt-free Jnana attained
And Siva became.`,
    elaborationTamil: `'தத்துவம் முப்பத்தாறினுள் ஒன்றேனும் தான் அல்லன்' எனத் தெளிந்து, அவைகளை, 'தான்' என மயங்கும் மயக்கத்தினுள் நீங்கினவன் எவனோ அவனே, அவற்றிற்கு வேறாகி, மேலே உள்ள பரவெளியை அடைந்து வீடு பெற்றவனாவன் அந் நிலையில் முன்பு இருந்த மயக்கம் நீங்கித் தெளிவு பெற்று, எளிதில் அணுக இயலாத சிவத்தை அடைந்து அதுவேயாவன், அதுவே அவன் அடையவேண்டிய இறுதி நிலையாகும். அந்நிலையில் சிவனைப்போல இவனும் வியாபகமாய், ஏனை எல்லாப் பொருள்களும் தன்னில் வியாப்பியமாய் நிற்க விளங்குவான்.`,
  },
  {
    id: 2347, tantraId: 8, verseNumber: 2346,
    tamil: `தீண்டற்குரிய அரிய திருவடி நேயத்தை
மீண்டுற்று அருளால் விதிவழியே சென்று
தூண்டிச் சிவஞான மாவினைத் தானேறித்
தாண்டிச் சிவனுடன் சாரலும் ஆமே`,
    transliteration: `tīṇṭaṟkuriya ariya tiruvaṭi nēyattai
mīṇṭuṟṟu aruḷāl vitivaḻiyē ceṉṟu
tūṇṭic civañāṉa māviṉait tāṉēṟit
tāṇṭic civaṉuṭaṉ cāralum āmē`,
    english: `2346: Mount the Steed of Sivajnana and Reach God
The love of Holy Feet
That is beyond reach,
By Grace he reaches;
Then by way appropriate journeying,
He rouses the mighty steed of Sivajnana
And mounting it passes beyond,
And so reaching Siva Himself.`,
    elaborationTamil: `அடைதற்கரிய சிவபத்தியைப் பொதுவாகத்தான் அறிந்த முறையில் அடைந்து ஒழுகிய ஒருவன் பின்பு கிரியா குருவின் அருளால் சிறப்பாக அதனை அடைந்து, அவர் அறிவுறுத்த முறை யிலே சிவதன்மத்தில் ஒழுகிச் சிவயோகத்திலும் பயின்று, அதன் பயனாகப் பின்பு சிவஞானமாகிய யானையின்மீது ஏறிச் செலுத்தி, மும்மாயை களையும் தாண்டிச் சென்று, அப்பால் உள்ள சிவனோடு கூடுதலும் கூடும்.`,
  },
  {
    id: 2348, tantraId: 8, verseNumber: 2347,
    tamil: `சார்ந்தவர் சாரணர் சித்தர் சமாதியர்
சார்ந்தவர் மெய்ஞ்ஞான தத்துவ சாத்தியர்
சார்ந்தவர் நேயந் தலைப்ட்ட ஆனந்தர்
சார்ந்தவர் சத்த அருள்தன்மை யாரே`,
    transliteration: `cārntavar cāraṇar cittar camātiyar
cārntavar meyññāṉa tattuva cāttiyar
cārntavar nēyan talaipṭṭa āṉantar
cārntavar catta aruḷtaṉmai yārē`,
    english: `2347: The Evolved Souls Who Reached Siva's Grace
Those who reached Siva
Are the Charanars, Siddhas, and Samadhi Yogis
The Jnanis who in God-Truth stood,
The Anandas who in love adored,
And Nathas--all, blessed of Grace Divine.`,
    elaborationTamil: `முன் மந்திரத்தில், ''சிவனுடன் சாரலும் ஆமே'' எனக்கூறிய சார்ச்சி, 'சரியை, கிரியை, யோகம், ஞானம்' என நால்வகைப் படுதலால், அவ்வம்முறையால் சிவனைச் சார்ந்தவர் முறையே. 'சாரணர், சித்தர், சமாதியர், சாத்தியர்' என நிற்பர். எனினும் இறுதியில் சொல்லப்பட்ட சமாதியரே சிவானந்தத்தை அடைந்தவர். அவரே நிலையான அருள் தன்மையைப் பெற்றவரும் ஆவர்.`,
  },
  {
    id: 2349, tantraId: 8, verseNumber: 2348,
    tamil: `தான்என்று அவன்என்று இரண்டென்பர் தத்துவம்
தான்என்று அவன்என்று இரண்டற்ற தன்மையத்
தான்என்று இரண்டுஉன்னார் கேவலத் தானவர்
தான்இன்றித் தானாகத் தத்துவ சுத்தமே`,
    transliteration: `tāṉeṉṟu avaṉeṉṟu iraṇṭeṉpar tattuvam
tāṉeṉṟu avaṉeṉṟu iraṇṭaṟṟa taṉmaiyat
tāṉeṉṟu iraṇṭuuṉṉār kēvalat tāṉavar
tāṉiṉṟit tāṉākat tattuva cuttamē`,
    english: `2348: Suddha State Knows No "I" and "He" Difference
They speak of States two,
"I" and "He"
But there is a State
Where "I" and "He" are undifferentiated;
Those who are in the Higher Kevala (inert) State
Will not the difference cognise;
Effacing Self,
And He and Self as one uniting,
Is the State of Suddha (Pure).`,
    elaborationTamil: `(உண்மையுணர்ந்தோர்) 'அறிபவனும், அறியப் படுபவனும் - என உள்பொருள் இரண்டு' எனக்கூறுவர் ஆயினும் அவ்விரண்டு பொருளும் எஞ்ஞான்றும் வேறுநில்லாது உடலும், உயிரும் போல ஒன்றாகியேயிருத்தலால், பாசமாகிய அசுத்தத்தின் நீங்கினோர், அறியப்படுபவனை யறிதலோடு அறிபவனையும் அறிதலாகிய இரண்டறிவையுடையராகாது, அறியப்படுபவனை மட்டுமே அறிதலாகிய அந்த ஓர் அறிவை மட்டுமே உடையவராய் இருப்பர் அவ்வாறிருத்லே நிறைவான சுத்த நிலையாகும்.`,
  },
  {
    id: 2350, tantraId: 8, verseNumber: 2349,
    tamil: `தன்னினில் தன்னை அறியும் தலைமகன்
தன்னினில் தன் ஐ அறியத் தலைப்படும்
தன்னினில் தன்னைச் சார்கிலன் ஆகில்
தன்னினில் தன்ஐயும் சார்தற்கு அரியவே`,
    transliteration: `taṉṉiṉil taṉṉai aṟiyum talaimakaṉ
taṉṉiṉil taṉ ai aṟiyat talaippaṭum
taṉṉiṉil taṉṉaic cārkilaṉ ākil
taṉṉiṉil taṉaiyum cārtaṟku ariyavē`,
    english: `2349: Seek Siva Within the Self
The Great souls that realize Siva
That is Self within,
Will seek forth Siva in the Self;
They who do not reach Siva in the Self,
Will reach Siva never.`,
    elaborationTamil: `('என்னை உடையானாகிய தலைவன் எங்குளன்' எனப்புறத்தே பலவிடத்துத் ''தேடியும் தேடொணாத் தேவனாய்'' உள்ள சிவனை, 'இனி என்னுள்ளேதான் நான்தேட வேண்டும்' என உணர்ந்து, அவ்வாறே) அவனைத் தன்னுள்ளே அறிய முயல்கின்ற பெருமகன் அம்முயற்சியில் உறைத்து நிற்பனாயின், அவனைத்தான் அடைந்துவிடுவான். அம்முறையில் அவன் தன்னுள்ளே தேட முயலாது, புறத்திற்றானே தேடிக் கொண்டிருப்பானாயின், அவன் சிவனைத் தன்னுள்ளேயும் அடைதற்கு அறியவனாகியேயிருப்பான்.`,
  },
  {
    id: 2351, tantraId: 8, verseNumber: 2350,
    tamil: `அறியகி லேன்என்று அரற்றாதே நீயும்
நெறிவழி யேசென்ற நேர்பட்ட பின்னை
இருசுட ராகி இயற்றவல் லானும்
ஒருசுட ராவந்துஎன் உள்ளத்துள் ஆமே`,
    transliteration: `aṟiyaki lēṉeṉṟu araṟṟātē nīyum
neṟivaḻi yēceṉṟa nērpaṭṭa piṉṉai
irucuṭa rāki iyaṟṟaval lāṉum
orucuṭa rāvantueṉ uḷḷattuḷ āmē`,
    english: `2350: Go and Seek Siva in the Proper Way
Lament not
That you know Him not;
Go the proper way
And you shall meet Him;
He who as Lights twine (Sakti and Siva)
Creates all,
As one Light in my heart is united.`,
    elaborationEnglish: ``,
    elaborationTamil: `மாணவகனே, குருவருள் பெறாத மற்றவர் -களைப்போல நீயும் இராக் கதிரிபோலச் சிறிதறிவைத் தருபவனாயும், பகற் கதிர்போலப் பேரறிவைத் தருபவனாயும் இருந்து எல்லா வற்றையும் செய்கின்ற சிவனைப் புறத்தெல்லாம் தேடி, 'ஐயோ!' சிவனைக் காணமுடியவில்லையே' என்று கதறி அழாதே. ஏன் எனில், அவனை அகத்தே அறிதலாகிய அந்த நெறியைப் பற்றி, அதிலே சென்ற பொழுது அவன் எனக்குக் கிடைத்தான். அதன்பின் அவன் முன்போல இருசுடராய் இல்லாமல் பகற் கதிராகிய ஒரு சுடரேபோலத் தோன்றி, அந்நிலையினின்றும் மாற்றம் சிறிதும் இன்றி, என் உள்ளத்துள் நீங்காதிருக்கின்றான்.`,
  },
  {
    id: 2352, tantraId: 8, verseNumber: 2351,
    tamil: `மண்ஒன்று தான்பல நற்கலன் ஆயிடும்
உள்கின்ற யோனிகட்டு எல்லாம் ஒருவனே
கண்ஒன்று தான்பல காணும் தனைக்காணா
அண்ணலும் அவ்வண்ணம் ஆகிநின்றானே`,
    transliteration: `maṇoṉṟu tāṉpala naṟkalaṉ āyiṭum
uḷkiṉṟa yōṉikaṭṭu ellām oruvaṉē
kaṇoṉṟu tāṉpala kāṇum taṉaikkāṇā
aṇṇalum avvaṇṇam ākiniṉṟāṉē`,
    english: `2351: God is Immanent and Yet Jiva Sees not
One the clay,
Many the pots made of it;
One the Lord,
Immanent in Creation all;
The eyes see things diverse,
But they see not the eyes;
So too is Lord to Jiva.`,
    elaborationEnglish: `Though the pots are different, the clay is one Similarly the Lord is the One pervading all His creations. The eyes behold diverse objects; but the objects do not see the eyes. So too is Siva for jiva. God is immanent and omnipresent; yet jiva does not see Him.`,
    elaborationTamil: `குடம், சால், சாடி முகலாகக்கலங்கள் பல வகையால் இருப்பினும் அவை அனைத்திலும் ஒருமண்ணே பொருந்தியிருத்தல் போலப் பிறப்பு வகையால் உயிர்களின் அறிவு பல்வேறு வகைப்பட்டிருப்பினும் ஒரு பேரறிவாகிய சிவன் அவை அனைத்தின் அறிவினுள்ளும் இருக்கின்றான், அங்ஙனமாயினும், கண் எல்லாப் பொருளையும் பார்க்க. பார்க்கப்பட்ட பொருள்கள் கண்ணைப் பாராததுபோல, அறிவுக்கறிவாய் உள்ள சிவன் அனைத்துயிர்களையும அறியினும் அவ்வுயிர்களுள் ஒன்றேனும் அவனை அறிதல் இல்லை.`,
  },
  {
    id: 2353, tantraId: 8, verseNumber: 2352,
    tamil: `ஓம்புகின் றான்உலகு ஏழையும் உள்நின்று
கூம்புகின் றார்குணத் தின்னொடும் கூறுவர்
தேம்புகின்றார்சிவன் சிந்தைசெய் யாதவர்
கூம்பகில் லார்வந்து கொள்ளலும் ஆமே`,
    transliteration: `ōmpukiṉ ṟāṉulaku ēḻaiyum uḷniṉṟu
kūmpukiṉ ṟārkuṇat tiṉṉoṭum kūṟuvar
tēmpukiṉṟārcivaṉ cintaicey yātavar
kūmpakil lārvantu koḷḷalum āmē`,
    english: `2352: Think of Siva and Draw Unto Him
Standing within,
He protects the worlds seven;
The goodly one who in love praises Him,
Close upon Him;
They who think not of Siva
Loud sob in distress;
How can those
Who center not their thoughts in Him
Ever, ever reach Him?`,
    elaborationTamil: `ஏழுலகத்தில் உள்ள உயிர்களையும் சிவன் ஒப்ப நோக்கித்தான் அவற்றின் உள்நின்று காத்து வருகின்றான். (என்றாலும், சிலரே அதனை யுணர்ந்து, ஏனையவற்றைப் பற்றாது விடுத்து அவனிடத்திலே சென்று அடங்குகின்றனர். அங்ஙனம் அடங்கினவர்கள் சிவனது எண்குணங்களையும் தாங்களும் உடையவராவர். பலர் அவ்வாறு உணர்ந்து சிவனை அடைதல் இல்லை. அங்ஙனம் அடையாதவர்கள் உலகியலில் சிக்கித் துன்புறுகின்றனர். சிவனை அடைந்து அடங்காதவர்கள் சிவனது குணத்தைப் பெறுதலும் கூடுமோ! (கூடாது).`,
  },
  {
    id: 2354, tantraId: 8, verseNumber: 2353,
    tamil: `குறிஅறி யார்கள் குறிகாண மாட்டார்
குறிஅறி யார்கடம் கூடல் பெரிது
குறிஅறி யாவகை கூடுமின் கூடி
அறிவறி யாஇருந்து அன்னமும் ஆமே`,
    transliteration: `kuṟiaṟi yārkaḷ kuṟikāṇa māṭṭār
kuṟiaṟi yārkaṭam kūṭal peritu
kuṟiaṟi yāvakai kūṭumiṉ kūṭi
aṟivaṟi yāiruntu aṉṉamum āmē`,
    english: `2353: Divine Swan Becoming
They who see not the Self within
Will see not the Goal without;
They who see not the Self within
Will incarnate bodies several;
Unite in Lord, the Self effacing;
And in knowledge undifferentiated
You the Divine Swan (I-and-He united) became.`,
    elaborationTamil: `'குறிக்கொளத் தக்கது இது' என அறியாதவர்கள் அதனை அடைதல் எங்ஙனம் கூடும்? (கூடாது) அவர் உடம்பிற் கட்டுண்டு நிற்குங் காலம் பெரிதாகும். ஆகையால், நீவிர், 'குறிக்கொள்ளத் தக்க பொருள் இது' என்பதை அறிந்து, பின்பு அதுவே யாகும்படி பொருந்தி நில்லுங்கள். நின்றால், உங்களுடைய அறிவு அறிவாய் இருக்கும். வீட்டின்பமும் சித்திக்கும்.`,
  },
  {
    id: 2355, tantraId: 8, verseNumber: 2354,
    tamil: `ஊனோ உயிரோ உறுகின்றது ஏதுஇன்பம்
வானோர் தலைவி மயக்கத்து உறநிற்கத்
தானோ பெரிதுஅறி வோம் என்னும் மானுடர்
தானே பிறப்போடு இறப்பறி யாரே`,
    transliteration: `ūṉō uyirō uṟukiṉṟatu ētuiṉpam
vāṉōr talaivi mayakkattu uṟaniṟkat
tāṉō perituaṟi vōm eṉṉum māṉuṭar
tāṉē piṟappōṭu iṟappaṟi yārē`,
    english: `2354: Limits of Human Knowledge
When the Lady of Celestials (Sakti)
In Maya stands,
Is it body or soul
That joys in the bliss?
The men who think they know all,
Know not why they are born, and why they die.`,
    elaborationTamil: `உயிர் உடம்பொடு கூடி நிற்கும் நிலையில் வருகின்ற இன்பத் துன்பங்களை நுகர்வது உடம்பா? உயிரா? இதனை எண்ணிப் பார்த்து உண்மையை உணரமாட்டாமல் திரோதான சத்தியால் வரும் மயக்கத்திலே இருந்து கொண்டு, 'யான் உண்மையைநன்கறிவேன்' என்றுசொல்கின்ற மனிதன்தான் பிறந்ததாகிய 'பிறப்பு' என்பதும், பின்பு இறக்கப்போவதாகிய 'இறப்பு' என்பதையுமே 'இன்ன' என அறியமாட்டான்.`,
  },
  {
    id: 2356, tantraId: 8, verseNumber: 2355,
    tamil: `தன்னை அறியத் தனக்கொரு கேடில்லை
தன்னை அறியாமல் தானே கெடுகின்றான்
தன்னை அறியும் அறிவை அறிந்தபின்
தன்னையே அர்ச்சிக்கத் தானிருந் தானே`,
    transliteration: `taṉṉai aṟiyat taṉakkoru kēṭillai
taṉṉai aṟiyāmal tāṉē keṭukiṉṟāṉ
taṉṉai aṟiyum aṟivai aṟintapiṉ
taṉṉaiyē arccikkat tāṉirun tāṉē`,
    english: `2355: Importance of Self-Knowledge
With knowledge of Self
No harm there be;
Without knowledge of Self
Himself His (Jiva) harm be;
When knowledge
That knows the Self dawns,
Yourself Siva becomes,
Worshipped high.`,
    elaborationTamil: `ஒருவன் பொருள் இயல்புகளை உள்ளவாறு அறியப் புகும்பொழுது தன்னுடைய இயல்பை முதற்கண் உள்ளவாறு அறிவானாயின், அதன்பின்பு அவனது அறிவு பொய்யறிவாகிக் கெடாது; தானும் எந்தக் கேட்டினையும் எய்தான். ஆகவே, மனிதன் முதலில் தன்னுடைய இயல்பை அறிய முயலாமல், பிற பொருள்களின் இயல்பை அறிய முற்படுவதால், அறிவுகெட்டு அலைகின்றான். அதனால், ஒருவன் முதலில் தனது இயல்பை உள்ளவாறு அறியும் அறிவைப் பெற்றுவிடுவானாயின், அவன் தன்னையே பிறர் வழிபடும் அளவிற்கு உயர்ந்து நிற்பான்.`,
  },
  {
    id: 2357, tantraId: 8, verseNumber: 2356,
    tamil: `அங்கே அடற்பெரும் தேவரெல் லாம்தொழச்
சிங்கா தனத்தே சிவன்இருந் தானென்று
சங்குஆர் வளையும் சிலம்பும் சரேலெனப்
பொங்குஆர் குழலியும் போற்றிஎன் றாளே`,
    transliteration: `aṅkē aṭaṟperum tēvarel lāmtoḻac
ciṅkā taṉattē civaṉirun tāṉeṉṟu
caṅkuār vaḷaiyum cilampum carēleṉap
poṅkuār kuḻaliyum pōṟṟieṉ ṟāḷē`,
    english: `2356: Lord on His Celestial Throne
There on the Throne leonine,
Adored by the mighty Celestials,
Was Siva Seated;
And the Lady of tresses exuberant,
With bangles of conch-shell
And anklets resounding
Sang "Hail My Lord."`,
    elaborationTamil: `'எந்த உயிருக்கு மல பரிபாகம் வந்ததோ, அந்த உயிரின் உள்ளத்திலே சிவபெருமான், வலிமையும், பெருமையும் உடைய அனைத்துத் தேவர்களும் தொழும்படி வீற்றிருக்கின்றான்' என்பதை உணர்தலால், அருட்சத்தியாகிய தேவியும் அங்கே மகிழ்ச்சியோடு விரைவில் சென்று அப்பெருமானை வணங்குவாள்.`,
  },
  {
    id: 2358, tantraId: 8, verseNumber: 2357,
    tamil: `அறிவு வடிவென்று அறியாத என்னை
அறிவு வடிவென்று அருள்செய்தான் நந்தி
அறிவு வடிவென்று அருளால் உணர்ந்தே
அறிவு வடிவென்று அருந்திருந் தானே`,
    transliteration: `aṟivu vaṭiveṉṟu aṟiyāta eṉṉai
aṟivu vaṭiveṉṟu aruḷceytāṉ nanti
aṟivu vaṭiveṉṟu aruḷāl uṇarntē
aṟivu vaṭiveṉṟu aruntirun tāṉē`,
    english: `2357: Siva's Form is Jnana
I knew not,
Siva's Form is Jnana;
Nandi by His Grace taught me
Siva's Form is Jnana,
I sought Jnana's Form
And in that knowledge
I remained.`,
    elaborationTamil: `மேற் கூறியவாறு, ''வானோர் தலைவி'' தந்த மயக்கத்தால், 'எனது வடிவம் அறிவு' என்னும் உண்மையை அறியாது. 'உடம்பே' என்று மயங்கியிருந்த என்னை, நந்திபெருமான் தோன்றி அம்மயக்கத்தை நீக்கி, 'உனது வடிவம் உடம்பன்று; அறிவு' என அருளிச்செய்து உண்மையை உணரப் பண்ணினார். அவரது திருவுளக் கருணையால் அடியேனுக்கு அறிவு உதயமாயிற்று. அதனால், 'உடம்பு எனது வடிவம் அன்று' என உணர்ந்து அதனின் நீங்கியிருக்கின்றேன்.`,
  },
  {
    id: 2359, tantraId: 8, verseNumber: 2358,
    tamil: `அறிவுக்கு அழிவில்ல ஆக்கமும் இல்லை
அறிவுக்கு அறிவல்லது ஆதாரம் இல்லை
அறிவே அறிவை அறிகின்றது என்றிட்டு
அறைகின் றனமறை ஈறுகள் தாமே`,
    transliteration: `aṟivukku aḻivilla ākkamum illai
aṟivukku aṟivallatu ātāram illai
aṟivē aṟivai aṟikiṉṟatu eṉṟiṭṭu
aṟaikiṉ ṟaṉamaṟai īṟukaḷ tāmē`,
    english: `2358: Jnana Alone Knows Jnana
Jnana has no death, nor birth;
Jnana has ground none but Jnana;
It is Jnana that knows Jnana
Thus they conclude, in the ultimate, Vedas all.`,
    elaborationTamil: `தோற்றமும், கேடும் சடத்துக்கன்றிச் சித்துக்கில்லை. சித்துக்குப் பற்றுக்கோடு சித்தேயன்றிச் சடம் அன்று. அவ்வாறே சித்தை யறிவதும் சித்தன்றிச் சடம் அன்று. இவ்வாறு, 'வேத முடிபுகள்' எனப்படுகின்ற உபநிடதங்கள் யாவும் கூறுகின்றன.`,
  },
  {
    id: 2360, tantraId: 8, verseNumber: 2359,
    tamil: `ஆயு மலரின் அணிமலர் தன்மேலே
பாய இதழ்கள் பதினாறும் அங்குள
தூய அறிவு சிவானந்த மாகியே
போய அறிவாய்ப் புணர்ந்திருந் தானே`,
    transliteration: `āyu malariṉ aṇimalar taṉmēlē
pāya itaḻkaḷ patiṉāṟum aṅkuḷa
tūya aṟivu civāṉanta mākiyē
pōya aṟivāyp puṇarntirun tāṉē`,
    english: `2359: Seat of Jnana Within
Above the flower of the heart, (Visuddha Adhara)
Is a flower of petal sixteen,
There is Jnana Pure,
Sivananda (Siva-Bliss) it is;
When jnana of Self
In it merged
Jiva united in Siva
And as one remained.`,
  },
  {
    id: 2361, tantraId: 8, verseNumber: 2360,
    tamil: `மன்னிநின் றாரிடை வந்தருள் மாயத்து
முன்னிநின் றாமை மொழிந்தேன் முதல்வனும்
பொன்னின்வந் தானோர் புகழ்திரு மேனியைப்
பின்னிநின் றேன்நீ பெரியையென் றானே`,
    transliteration: `maṉṉiniṉ ṟāriṭai vantaruḷ māyattu
muṉṉiniṉ ṟāmai moḻintēṉ mutalvaṉum
poṉṉiṉvan tāṉōr pukaḻtiru mēṉiyaip
piṉṉiniṉ ṟēṉnī periyaiyeṉ ṟāṉē`,
    english: `2360: Lord Blessed Me
To them that firm-fixed Him in thought
As Grace of Sakti
He hastened;
I praised Him;
The Lord too appeared
His Golden Form revealing;
I held fast to Him knowing Jiva Jnana,
Then are Anima and other Siddhis (eight);
Nandi thus knew
Jiva Jnana as Siva Jnana.`,
    elaborationTamil: `'உலகத்தில் பலராய்க் குழுமி வாழ்கின்ற அனைத்து மக்களிடையே தானும் ஒரு மகன்போல வந்து அருள்செய்ய வேண்டும்' என்கின்ற சூழ்ச்சியைத் திருவுளத்து எண்ணி, அவ்வாறு வந்து என்முன் நின்ற சிவனை யான் 'சிவன்' என்று அறிந்துகொண்டு போற்றினேன். பின்னும் அங்ஙனம் அவன் வந்து நின்ற திருமேனியை விடாது பற்றிக்கொண்டு திரிந்தேன். அதைக் கண்டு அவனே வியந்து, 'அப்பா' நீ மிகப் பெரியை' என்று கூறினான்.`,
  },
  {
    id: 2362, tantraId: 8, verseNumber: 2361,
    tamil: `அறிவுஅறி வாக அறிந்துஅன்பு செய்மின்
அறிவுஅறி வாக அறியும்இவ் வண்ணம்
அறிவுஅறி வாக அணிமாதி சித்தி
அறிவுஅறி வாக அறிந்தணன் நந்தியே`,
    transliteration: `aṟivuaṟi vāka aṟintuaṉpu ceymiṉ
aṟivuaṟi vāka aṟiyumiv vaṇṇam
aṟivuaṟi vāka aṇimāti citti
aṟivuaṟi vāka aṟintaṇaṉ nantiyē`,
    english: `2361: Realizing this, adore Him
And through Jiva jnana know Siva jnana
Thus anima and the rest of the eight siddhis are attained
Thus did Nandi know jiva jnana as Siva jnana.`,
    elaborationEnglish: `1) Siddhis are miraculous occult powers that come in the wake of yoga practice. They are cight: anima, mahima, garima, laghuma, prapti, prakamayam, isatvam, and vasitvam.

i) Anima is to becomes as tiny as jiva, which is atomic in size. (Immanence)

ii) Mahima is to becomes as great as infinity.

Garima is to materialise whole objects (pervasiveness) from diverse fragments.

iv) Laghuma is to become weightless.

v) Prapti is to attain all that is wished for.

vi) Prakamyam is to become all-weight.

Vii) Isatvam is to attain vast regal powers.

Vasitvam is to attain powers of total attraction.

For a fuller discussion of the eight siddhis, vide Tantra Three supra.`,
    elaborationTamil: `மெய்யறிவு வேண்டுவீர், உமது வேட்கை நிரம்ப வேண்டுமாயின் நீவிர் சிவனையே பொருளாக உணர்ந்து அவனிடம் அன்புசெய்யுங்கள் (பிறரைப் பொருளாக அறியும் அறிவுகள் எல்லாம் போலியறிவே.) யான் சிவனை உணர்ந்து பயன் பெற்றேன். (''நான் பெற்ற இன்பம் பெறுக இவ்வையகம்'') இவ்வாற்றால் உமது அறிவு உண்மை மெய்யறிவாயின், அதனைச் சிவனும் அறிந்து, பயன் தருவான். அதனால் அத்தகைய அறிவால் நிலையான வீடுபேறே யன்றி, இடையில் அணிமாதி சித்திகளும் தாமே வந்து வாய்க்கும்.`,
  },
  {
    id: 2363, tantraId: 8, verseNumber: 2362,
    tamil: `அறிவுஅறி வென்று அங்கு அரற்றும் உலகம்
அறிவுஅறி யாமை யாரும் அறியார்
அறிவுஅறி யாமை கடந்துஅறி வானால்
அறிவுஅறி யாமை அழகிய வாறே`,
    transliteration: `aṟivuaṟi veṉṟu aṅku araṟṟum ulakam
aṟivuaṟi yāmai yārum aṟiyār
aṟivuaṟi yāmai kaṭantuaṟi vāṉāl
aṟivuaṟi yāmai aḻakiya vāṟē`,
    english: `2362: Dividing Line Between Knowledge and Ignorance
"Jnana, Jnana," thus laments this world,
They know not,
Jnana of Jiva is Jnana none; but ignorance;
When Divine Jnana overlays Jiva Jnana,
They both Pure Jnana are;
Thus much is it after all,
Between Knowledge and Ignorance.`,
    elaborationTamil: `உலகினர், 'எமக்கு அறிவு வேண்டும், அறிவு வேண்டும்' என்று கூப்பாடு போடுகின்றனர். 'ஆயினும், அங்ஙனம் கூப்பாடு போட்டுப் பெற்ற அறிவு அறியாமையாய் இருத்தலை ஒருவரும் அறியார், அங்ஙனம் ஒருவராலும் அறியப்படாதிருக்கின்ற அந்த அறியாமை நீங்கி, அறிவு அறிவாகுமானால், முன்பு 'அறிவு' என்று நினைக்கப்பட்டது அறியாமையாய் இருந்த அழுகு வெளிப்பட நகைப்பு உண்டாகும்.`,
  },
  {
    id: 2364, tantraId: 8, verseNumber: 2363,
    tamil: `அறிவுஅறி யாமையை நீவி யவனே
பொறிவாய் ஒழிந்துஎங்கும் தானான போது
அறிவாய் அவற்றினுள் தானாய் அறிவின்
செறிவாகி நின்றவன் சிவனும் ஆமே`,
    transliteration: `aṟivuaṟi yāmaiyai nīvi yavaṉē
poṟivāy oḻintueṅkum tāṉāṉa pōtu
aṟivāy avaṟṟiṉuḷ tāṉāy aṟiviṉ
ceṟivāki niṉṟavaṉ civaṉum āmē`,
    english: `2363: Transcend Knowledge and Ignorance and Reach Siva
Jnana
Knowledge and Ignorance
Both transcending,
Abandoning senses five,
And immanent becoming,
Himself as Jnana,
And Jnana's pervasiveness
Jiva stands.`,
    elaborationTamil: `அறிவு அறியாமையாய் இருந்த நிலையினின்றும் நீங்கி, அறிவேயாய் நிற்கப் பெற்றவனே, புற இந்திரியம் முதலிய கருவிகளில் அவையேதானாய் ஒன்றி, அவற்றின் அளவாய் நின்ற ஏகதேச நிலை நீங்கி, எங்கும் தானாம் வியாபக நிலையைப் பெறுவான். அந்நிலையைப் பெற்றபொழுதுதான். சடமேயாயினும் சித்துப் போலத்தோன்றிய கரணங்களில் அறிவாய் உள்ளவனும், அவற்றால் சீவனாய் இருந்தவனும் தானே ஆதல் அவனுக்கு விளங்கும்.`,
  },
  {
    id: 2365, tantraId: 8, verseNumber: 2364,
    tamil: `அறிவுடை யார்நெஞ்சு அகலிடம் ஆவது
அறிவுடை யார்நெஞ்ச அருந்தவம் ஆவது
அறிவுடை யார்நெஞ்சொடு ஆதிப் பிரானும்
அறிவுடை யார்நெஞ்சத்து அங்குநின் றானே`,
    transliteration: `aṟivuṭai yārneñcu akaliṭam āvatu
aṟivuṭai yārneñca aruntavam āvatu
aṟivuṭai yārneñcoṭu ātip pirāṉum
aṟivuṭai yārneñcattu aṅkuniṉ ṟāṉē`,
    english: `2364: Heart of Jnani
The heart of Jnani is Expanse Vast;
The heart of Jnani is Tapas rare;
The heart of Jnani is Lord's abode;
There He stood, in the heart of Jnanis.`,
    elaborationTamil: `மெய்யறிவை அடைந்தோரது உள்ளங்கள் அனைத்துலகங்களையும் உட்கொள்ளவல்லன; செய்தற்கரிய சரியை கிரியா யோகங்களில் பழகிப் பழுத்தன. அதனால், முதற்கடவுளாகிய சிவபிரானும் அவரது உள்ளங்களையே தானாகச் செய்து, அவற்றின் கண் நீங்காமலும் நிற்கின்றான்.`,
  },
  {
    id: 2366, tantraId: 8, verseNumber: 2365,
    tamil: `மாயனும் ஆகி மலரோன் இறையுமாய்க்
காயநன் னாட்டுக் கருமுதல் ஆனவன்
சேயன் அணியன் தித்திக்கும் தீங்கரும்
பாய்அமு தாகிநின்று அண்ணிக்கின் றானே`,
    transliteration: `māyaṉum āki malarōṉ iṟaiyumāyk
kāyanaṉ ṉāṭṭuk karumutal āṉavaṉ
cēyaṉ aṇiyaṉ tittikkum tīṅkarum
pāyamu tākiniṉṟu aṇṇikkiṉ ṟāṉē`,
    english: `2365: Siva Stands Close to Jiva
The Lord He is
Hari, Brahma and Rudra;
He is the Seed
Of the corporeal world;
Distant, and near is He;
He is sugar cane-sweet and ambrosia divine;
Thus He stands close to Jiva.`,
    elaborationTamil: `உடம்பும், உலகமும் ஆகிய இவற்றின் அடிநிலைப் பொருளாகிய மாயைக்குத் தலைவனாய் உள்ள சிவன், உயிர்களின் பெத்த காலத்தில், 'அயன், மால், அரன்' என மூவராய் நின்று அவைகளை முத்தொழிலில் அகப்படுத்தி, அவைகளால் அணுகுதற்கு அரியனாய்ச் சேய்மையில் நின்றவன், முத்தி காலத்தில் அம்மூவர்க்கும் மேலாய மூர்த்தியாய் வெளிப்பட்டு அருகில் விளங்கி கரும்பு போலவும், அமுதம் போலவும் இனிப்பவன் ஆகின்றான்.`,
  },
  {
    id: 2367, tantraId: 8, verseNumber: 2366,
    tamil: `என்னை அறிந்திலேன் இத்தனை காலமும்
என்னை அறிந்தபின் ஏதும் அறிந்திலேன்
என்னை அறிந்திட்டு இருத்தலும் கைவிடாது
என்னையிட்டு என்னை உசாவுகின் றானே`,
    transliteration: `eṉṉai aṟintilēṉ ittaṉai kālamum
eṉṉai aṟintapiṉ ētum aṟintilēṉ
eṉṉai aṟintiṭṭu iruttalum kaiviṭātu
eṉṉaiyiṭṭu eṉṉai ucāvukiṉ ṟāṉē`,
    english: `2366: Know Self and Be With God
All these days,
I knew not the Self;
When I knew the Self,
Nothing else I knew;
When I knew the Self,
He left me not
And within me He enquires
Of my welfare in loving care.`,
    elaborationEnglish: ``,
    elaborationTamil: `இவ்வளவு காலமும் யான் என்னையறியாமல், என்னின் வேறாகிய பொருள்களையே யானாக எண்ணியிருந்தேன். (அதனால் அவற்றில் அழுந்தி, அவையேயாய் இருந்தேன்.) நந்தி பெருமானது அருளால் என்னை யான் அவற்றின் வேறான பொருளாக அறிந்தபின் அந்தநிலை சிறிதும் இல்லை. மேலும் யான் யானாகிய நிலையை நழுவ விடாமல் உறுதியாகப்பற்றி, என்னையே ஏதுவாகப் பற்றி, எனது இயல்பை யான் நன்கு ஆராய்ந்து வருகின்றேன்.`,
  },
  {
    id: 2368, tantraId: 8, verseNumber: 2367,
    tamil: `மாய விளக்கது நின்று மறைந்திடும்
தூய விளக்கது நின்று சுடர்விடும்
காய விளக்கது நின்று கனன்றிடும்
சேய விளக்கினைத் தேடுகின் றேனை`,
    transliteration: `māya viḷakkatu niṉṟu maṟaintiṭum
tūya viḷakkatu niṉṟu cuṭarviṭum
kāya viḷakkatu niṉṟu kaṉaṉṟiṭum
cēya viḷakkiṉait tēṭukiṉ ṟēṉai`,
    english: `2367: Seek Pure Lamp
The Maya's Lamp is flickering,
It burns and dies;
The Pure Lamp steadily burning;
The body's Lamp within heats;
The Distant Lamp I seek.`,
    elaborationTamil: `நம் கையில் உள்ளது உடம்பாகிய ஒரு விளக்கு, அது நிலையற்றது; சிறிதுபோதுநின்று மறைந்து விடும் என்பது நம் போன்றவர்களை விட்டு அது மறைந்தமையால் அறிந்தேன். மேலும் இது முடைநாற்றம் வீசுவதாயும், பசி, நோய் முதலியவற்றால் வருத்துவதாயும் உள்ளது. இனித் திருவருளாகிய மற்றொரு விளக்கு மிகச் சேய்மையில் உள்ளதாகப் பெரியோர்கள் சொல்வதால் அறிகின்றேன். அந்த விளக்கு எப்பொழுதுமே நம்மை விட்டு நீங்காமல் ஒளிவீசிக் கொண்டே யிருக்குமாம். மேலும் அது தூய்மையானதாயும், தனி ஓர் இன்பத்தைத் தருவதாயும் இருக்குமாம். அதனை அடையத்தான் நான் அலைந்து கொண்டிருக்கின்றேன்.`,
  },
  {
    id: 2369, tantraId: 8, verseNumber: 2368,
    tamil: `தேடுகின் றேன்திசை எட்டோ டு இரண்டையும்
நாடுகின் றேன்நல மேஉடை யானடி
பாடுகின் றேன்பர மேதுணை யாமெனக்
கூடுகின் றேன்குறை யாமனைத் தாலே`,
    transliteration: `tēṭukiṉ ṟēṉticai eṭṭō ṭu iraṇṭaiyum
nāṭukiṉ ṟēṉnala mēuṭai yāṉaṭi
pāṭukiṉ ṟēṉpara mētuṇai yāmeṉak
kūṭukiṉ ṟēṉkuṟai yāmaṉait tālē`,
    english: `2368: Seek God
I seek in directions eight and two,
I seek, in goodness, the Feet of Lord
I sing, "Param is my Refuge"
I unite in Him, in mind's fulness.`,
    elaborationEnglish: ``,
    elaborationTamil: `'நன்றேயுடையனாயும், தீதேயில்லாதவனாயும் உள்ள சிவனது அருளே எல்லாவற்றினும் மேலான துணையாம்' என்று துணிந்து அதனையே பெற விரும்புகின்றேன். விரும்பி அதனை எல்லாத் திசைகளிலும் சென்று தேடுகின்றேன். அதனைத் துதிக்கின்றேன். இவ் வகையில் யான் அதனை நினைவளவில் பெற்றுவிட்டேன்.`,
  },
  {
    id: 2370, tantraId: 8, verseNumber: 2369,
    tamil: `முன்னை முதல்விளை யாட்டத்து முன்வந்தோர்
பின்னை பெருமலம் வந்தவர் பேர்த்திட்டுத்
தன்னைத் தெரிந்துதன் பண்டைத் தலைவன்தன்
மன்னிச் சிவமாக வாரா பிறப்பே`,
    transliteration: `muṉṉai mutalviḷai yāṭṭattu muṉvantōr
piṉṉai perumalam vantavar pērttiṭṭut
taṉṉait terintutaṉ paṇṭait talaivaṉtaṉ
maṉṉic civamāka vārā piṟappē`,
    english: `2369: Jiva's Journey to Liberation is Lord's Play
In the Primal Play of Lord
Were Jivas created;
Enveloped in mighty Malas were they;
Discarding them,
They realized the Self,
And besought the Feet
Of their hoary Lord;
Thus, they Siva became
With birth no more to be.`,
    elaborationEnglish: `Jivas in Saiva Siddhanta philosophy are as eternal as God. By’ what is meant here is that they were ‘activated’ from the primordial (kevala state) inert condition by Siva acting on Sakti, and given the milieu and instruments for development, such as thanu (body), karana (organs), bhuvana (world), and bhoga (experience).`,
    elaborationTamil: `முன்னைப் பழம் பொருட்கும் முன்னைப் பழம் பொருளாய்8 உள்ள முதல்வனாகிய சிவபெருமானது விளை -யாடலால் முதற்கண் இயல்பாய் உள்ள ஒரு மலமாகிய ஆணவமும், அது பற்றிப் பின் வந்து பெருகிய மலங்களாகிய மாயை கன்மங்களும் அவை வந்தவழியே ஒருவன் போகச் செய்து, அநாதியே அடியவ னாகிய தன்னையும், தனக்கு அநாதியே தலைவனாய் உள்ள அப்பெருமானையும் உணர்ந்து, பாசங்களை விட்டு அவனது திருவடியை அடைந்து அவனே ஆயினால், பின்பு அவனுக்குப் பிறவிகள் வாரா.`,
  },
  {
    id: 2371, tantraId: 8, verseNumber: 2370,
    tamil: `வேதத்தின் அந்தமும் மிக்கசித் தாந்தமும்
நாதத்தின் அந்தமும் நற்போத அந்தமும்
ஓதத் தகும்எட்டு யோகாநந்த அந்தமும்
ஆதிக்க லாந்தமும் ஆறந்தம் ஆமே`,
    transliteration: `vētattiṉ antamum mikkacit tāntamum
nātattiṉ antamum naṟpōta antamum
ōtat takumeṭṭu yōkānanta antamum
ātikka lāntamum āṟantam āmē`,
    english: `2370: Six Ends Ultimate
The End of Veda (Vedanta)
The End of Siddhanta Exalted,
The End of Nada (Nadanta),
The End of Bodha (Bodhanta)
The End of Yoga (Yoganta)
Of branches eight,
The End of Kalas (Kalanta)
--These the Ends Six, the Ultimates
Finale.`,
    elaborationTamil: `அந்தங்கள், அவையாவன சமயநூல்களின் முடிவுகள் ஆறு. அவை, 'வேதாந்தம், சித்தாந்தம், நாதாந்தம், போதாந்தம், யோகாந்தம், கலாந்தம்' - என்பன.`,
  },
  {
    id: 2372, tantraId: 8, verseNumber: 2371,
    tamil: `அந்தம்ஓர் ஆறும் அறிவார் அதிசுத்தர்
அந்தம்ஒர் ஆறும் அறிவார் அமலத்தர்
அந்தம்ஓர் ஆறும் அறியார் அவர்தமக்கு
அந்தமோடு ஆதி அறியஒண் ணாதே`,
    transliteration: `antamōr āṟum aṟivār aticuttar
antamor āṟum aṟivār amalattar
antamōr āṟum aṟiyār avartamakku
antamōṭu āti aṟiyaoṇ ṇātē`,
    english: `2371: Souls Rid of Malas Will Know the Six Ends
The Pure ones of Malas rid
Will the Ends six know;
The Impure ones in Malas bound
Will the Ends Six know not;
They who know not the Ends Six
Will not know Lord,
He that is End and Beginning.`,
    elaborationTamil: `(ஒரு பொருளை உடன்பாட்டினும், எதிர் மறையினும் ஆய்ந்து உணர்பவரே உண்மை உணர்பவர் ஆதலால்), மேற்கூறிய ஆறு அந்தங்களையும் அறிந்தவரே அறிவர் ஆவர். அவற்றை அறியாதவர் அறிவர் ஆகார்.`,
  },
  {
    id: 2373, tantraId: 8, verseNumber: 2372,
    tamil: `தானான வேதாந்தம் தான்என்னும் சித்தாந்தம்
ஆனாத் துரியத்து அணுவன் தனைக்கண்டு
தேனார் பராபரம் சேர்சிவ யோகமாய்
ஆனா மலமற்று அரும்சித்தி யாதலே`,
    transliteration: `tāṉāṉa vētāntam tāṉeṉṉum cittāntam
āṉāt turiyattu aṇuvaṉ taṉaikkaṇṭu
tēṉār parāparam cērciva yōkamāy
āṉā malamaṟṟu arumcitti yātalē`,
    english: `2372: Ends of Vedanta and Siddhanta
"I am the Supreme One," says Vedanta,
"I shall become the Supreme One," says Siddhanta;
In Turiya State they realize the Self
And in Siva Yoga they unite in Parapara Sweet;
Rid of Malas
They the Rare Goal attain.`,
    elaborationTamil: `பிறிதொரு நூலால் அன்றித் தன்னாலேதான் பிரமாண மாகின்ற வேதத்தின் முடிவுதான் எக்காலத்தும் சிவாகமங் களின் முடிவு. அவ்விரண்டிலும் கூறப்படுவது, நின்மலாவத்தையில் நிகழும் சாக்கிரம் முதலிய ஐந்தவத்தைகளுள் சிவனின் நீங்கி நில்லாத துரியாவத்தையில் ஆன்மா, தன்னை முதற்கண் உள்ளவாறுணர்ந்து, தேன்போல இனிக் -கின்ற பரம்பொருளை அடைதற்கு வழியாகிய சிவோகம் பாவனையில் நின்று, அதனானே அனாதிதொட்டு நீங்காது பற்றி வருகின்ற மலம் முற்றும் நீங்கப்பெற்று, பெறுதற்கரிய பேற்றைப் பெறுதலேயாம்.`,
  },
  {
    id: 2374, tantraId: 8, verseNumber: 2373,
    tamil: `நித்தம் பரனோடு உயிருற்று நீள்மனம்
சத்தம் முதல்ஐந்தும் தத்துவத் தால்நீங்கச்
சுத்தம் அசுத்தம் தொடரா வகைநினைந்து
அத்தன் பரன்பால் அடைதல்சித் தாந்தமே`,
    transliteration: `nittam paraṉōṭu uyiruṟṟu nīḷmaṉam
cattam mutalaintum tattuvat tālnīṅkac
cuttam acuttam toṭarā vakainiṉaintu
attaṉ paraṉpāl aṭaitalcit tāntamē`,
    english: `2373: Truth of Siddhanta
Daily living in Para's thought,
Freed from Tattvas
Beginning with the Five (Sound, taste, smell, touch and sight);
Contemplating beyond
Where the Suddha and Asuddha (Mayas) pursue not,
Reaching thus Para that is Lord,
That, verily, is the Truth of Siddhanta.`,
    elaborationTamil: `'பரனே யன்றிச் சீவனும் அவன் போலவே என்றும் உள்ள அனாதி நித்தப்பொருள்' என்னும் கொள்கையை முதலிற் கொண்டு, (சீவன் அனாதியே பந்தப்பட்டு நிற்றலாம்), அது சுத்த மாயை, அசுத்தமாயை இரண்டும் பின்னர் வந்து பற்றாதவாறு விலகுதற்குரிய வழியை அறிந்து, அவ்வழியால் பந்தத்தினின்றும் நீங்கி, தந்தையாகிய சிவனை அடைதலே 'சித்தாந்தம்' என்னும் தத்துவமாகும்.`,
  },
  {
    id: 2375, tantraId: 8, verseNumber: 2374,
    tamil: `மேவும் பிரமனே விண்டு உருத்திரன்
மேவுசெய் ஈசன் சதாசிவன் மிக்கு அப்பால்
மேவும் பரவிந்து நாதம் விடாஆறாறு
ஓவும் பொழுதுஅணு ஒன்றுஉள தாமே`,
    transliteration: `mēvum piramaṉē viṇṭu uruttiraṉ
mēvucey īcaṉ catācivaṉ mikku appāl
mēvum paravintu nātam viṭāāṟāṟu
ōvum poḻutuaṇu oṉṟuuḷa tāmē`,
    english: `2374: The Ultimate State in Jiva's Journey
Jiva's Journey
Beyond Brahma, Vishnu and Rudra,
Beyond Maheswara and Sadasiva,
Beyond Para Bindu and Para Nada,
Beyond Tattvas Thirty and Six,
When all these are transcended,
The Jiva is left alone with Siva.`,
    elaborationEnglish: ``,
    elaborationTamil: `பஞ்ச கலைகட்கு அதிதேவராகப் பொருந்துபவருள் பிரமனது அதிகாரத்திற்கு உட்பட்டது. நிவிர்த்தி கலை. இது 'பிருதிவி' என்னும் தத்துவத்தைத் தன்னுட் கொண்டது. இதற்குமேல் இதனை உள்ளடக்கிப் பரந்திருப்பது பிரதிட்டா கலை. இஃது அப்பு முதல் பிரகிருதி முடிவாக உள்ள இருபத்து மூன்று தத்துவங்களைத் தன்னுட் கொண்டது. இதற்கு மேல் இதனை உள்ளடக்கிப் பரந்திருப்பது வித்தியா கலை. இதற்கு அதிதேவன் மாயோன். இதற்குமேல் இதனை உள்ளடக்கிப் பரந்திருப்பது வித்தியா கலை. இது வித்தியா தத்துவம் ஏழினையும் தன்னுட்கொண்டது. இதற்கு அதிதேவன் உருத்திரன். இதற்கு மேல் இதனை உள்ளடக்கிப் பரந்திருப்பது சாந்தி கலை. இது சிவதத்துவங்களில் கீழ் உள்ள சுத்த வித்தை, ஈசுரம், சாதாக்கியம் என்னும் மூன்று தத்துவங்களைத் தன்னுட் கொண்டது. இதற்கு அதிதேவன் மகேசுரன். இதற்குமேல் இதனை உள்ளடக்கிப் பரந்திருப் -பது சாந்தி யதீத கலை. இது சிவதத்துவங்களுள் எஞ்சி நின்ற, 'சத்தி, சிவம்' என்னும் இரண்டு தத்துவங்களைத் தன்னுட் கொண்டது. இதற்கு அதிதேவன் சதாசிவன். இங்குக் கூறிவந்த தத்துவங்களில் இறுதியாக எல்லாவற்றிற்கும் மேலே உள்ளனவாகச் சொல்லப்பட்ட 'சத்தி, சிவம்' - என்னும் தத்துவங்களே 'விந்து, நாதம்' என்றும் சொல்லப்படும். ஆகவே, இவைகளையும் கடந்தால்தான் முப்பத்தாறு தத்துவங் -களையும் கடந்தததாகும். அவ்வாறு கடந்தபொழுதுதான் கருவி கரணங்களின் வேறாய், 'ஆன்மா' என ஒன்று உளதாதல் விளங்கும்.`,
  },
  {
    id: 2376, tantraId: 8, verseNumber: 2375,
    tamil: `உள்ள உயிர்ஆறாற தாகும் உபாதியைத்
தெள்ளி அகன்றுநா தாந்தத்தைச் செற்றுமேல்
உள்ள இருள்நீங்க ஓருணர் வாகுமேல்
எள்ளலின் நாதாந்தத்து எய்திடும் போதமே`,
    transliteration: `uḷḷa uyirāṟāṟa tākum upātiyait
teḷḷi akaṉṟunā tāntattaic ceṟṟumēl
uḷḷa iruḷnīṅka ōruṇar vākumēl
eḷḷaliṉ nātāntattu eytiṭum pōtamē`,
    english: `2375: Nadanta Bodhanta States
Jiva transcending
The tribulations of Tattvas
Six times six,
Reaches the Nadanta;
Ascending still beyond,
It encounters darkness of Anava;
When that is dispelled,
The peerless Divine Jnana dawns;
That indeed is Jnana (Bodha)
That Nadanta beyond reached.`,
    elaborationTamil: `முன் மந்திரத்தில் கூறியவாறு, தத்துவம் முப்பத் தாறனையும் கடந்த நிலையில் 'தான்' என ஒரு பொருள் அவற்றின் வேறாய் உளதாதலை உணர்ந்த ஆன்மா, தனக்கு உபாதியாய் (குற்றமாய்)ச் சேர்ந்த அவற்றினது சடத்தன்மையையும், தனது சித்துத் தன்மையையும் தெள்ளியவாக ஆராய்ந்து, அதனானே, அவற்றி -னின்றும் அறவே நீங்கி, அவ்விடத்தில் உள்ள தன்னை மறைக்கின்ற ஆணவ இருளும் சிவனது அருளால் நீங்க, அவனது உணர்வாகிய சிவஞானத்தோடு கூடி, அதுவாகி நிற்குமாயின், அவ்விடத்தில், 'போதம்' எனப்படுகின்ற ஞானம் உண்டாகும்.`,
  },
  {
    id: 2377, tantraId: 8, verseNumber: 2376,
    tamil: `தேடும் இயம நியமாதி சென்றகன்று
ஊடும் சமாதியில் உற்றுப் படர்சிவன்
பாடுறச் சீவன் பரமாகப் பற்றறக்
கூடும் உபசாந்தம் யோகாந்தக் கொள்கையே`,
    transliteration: `tēṭum iyama niyamāti ceṉṟakaṉṟu
ūṭum camātiyil uṟṟup paṭarcivaṉ
pāṭuṟac cīvaṉ paramākap paṟṟaṟak
kūṭum upacāntam yōkāntak koḷkaiyē`,
    english: `2376: Yoganta State
Seeking Iyama and Niyama
And then going beyond
Enter into Samadhi;
There Jiva reaches Para Siva;
And Param becoming
All desires abandoned,
Realizes Upasantha
That verily is the Truth of Yoganta.`,
    elaborationTamil: `இயமம், நியமம் முதலிய எட்டுறுப்புக்களையும் மேற்கொள்ளப் புகுந்து, அவ்வாறே படிமுறையால் மேல் ஏறி, முடிவான 'சமாதி' என்னும் நிலையை எய்திச் சிவனுக்கு அணுக்கமாகி நிற்கச் சீவன் சிவனாய்விடும். அந்நிலையில் உலகத்தாக்கம் ஒழிய ஓர் அமைதி நிலை தோன்றும். அதுவே உயிர் பெறத்தக்க பேறு - என்னும் இதுவே யோக நூலின் முடிவான கொள்கை.`,
  },
  {
    id: 2378, tantraId: 8, verseNumber: 2377,
    tamil: `கொள்கையில் ஆன கலாந்தம் குறிக்கொள்ளில்
விள்கையில் ஆன நிவிர்த்தாதி மேதாதிக்கு
உள்ளன வாம்விந்து உள்ளே ஓடுங்கலும்
தெள்ளி அதனைத் தெளிதலும் ஆமே`,
    transliteration: `koḷkaiyil āṉa kalāntam kuṟikkoḷḷil
viḷkaiyil āṉa nivirttāti mētātikku
uḷḷaṉa vāmvintu uḷḷē ōṭuṅkalum
teḷḷi ataṉait teḷitalum āmē`,
    english: `2377: Kalanta State
When the goal is Truth of Kalanta,
This then is the way:
Ascend Kalas (five) Nivritti, and the rest
And Medha and the rest ten and six;
There encounter Bindu;
In it do merge and vivid know
The Truth of Kalanta.`,
    elaborationEnglish: `1)These five are in Siva tattvas; nivritti, prastista, vidya, santi, and santyatita.

2)16 kalas

Medha, Arghisa, Vida, Bindu, Artha candra, Nirodpini, Nada, Nadanta, Sakti, Vyapini, Vyomaupini, Ananthai, Anathai, Anasiruthai, Samanai, Unmanai,

The sixteen kalas within. belong to the sixteen saktis in the sixteen-petalled-flower of the visuddhi adhara. The realisation of these sixteen kalas is known as ‘sodasa kala prasada.’`,
    elaborationTamil: `'ஆறந்தம்' எனப்படுகின்ற கொள்கைகளில் ஒன்றான, 'கலாந்தமாவது யாது' என அறிந்து கொள்ளப்புகின், உயிர் பாசங்களினின்றும் நீங்குதற்கண் துணையாய் உள்ள நிவிர்த்தி முதலிய சத்திகட்கு இடமாய் நிவிர்த்தி முதலிய கலைகளும், மற்றும் பிராசாத மந்திரத்தின் மேதா முதலிய கலைகளும் சுத்த மாயையிலே தோன்றிச் சுத்த மாயையிலே ஒடுங்குமாற்றை ஆராய்ந்து தெளிதலே கலாந்தமாம்.`,
  },
  {
    id: 2379, tantraId: 8, verseNumber: 2378,
    tamil: `தெளியும் இவையன்றித் தேர்ஐங் கலைவேறு
ஒளியுள் அமைந்துள்ளது ஓரவல் லார்கட்கு
அளியவ னாகிய மந்திரம் தந்திரம்
தெளிஉப தேசஞா னத்தொடுஐந் தாமே`,
    transliteration: `teḷiyum ivaiyaṉṟit tēraiṅ kalaivēṟu
oḷiyuḷ amaintuḷḷatu ōraval lārkaṭku
aḷiyava ṉākiya mantiram tantiram
teḷiupa tēcañā ṉattoṭuain tāmē`,
    english: `2378: Five Other Ways Dear to Siva
Siva
These paths apart,
There are five other,
That lead to the Light
For them who seek;
Dear unto Siva are the Five
--Mantra, Tantra, Serenity (Samadhi
Yoga), Upadesa and Jnana.`,
    elaborationTamil: `(முன் மந்திரத்தில் கூறப்பட்ட கலாந்தம் ஒழுக்கம் பற்றியது. இனி), நூல் அறிவு பற்றி நோக்குங்கால் உள்ள கலாந்தம் வேறு ஐந்தாகும். அவை, 'மந்திர கலாந்தம், தந்திர கலாந்தம், தெளிவுக் கலாந்தம், ஞான கலாந்தம். உபதேச கலாந்தம்' என்பன. அவையும் ஞானப் பகுதிகளேயாம். அவை ஆராய்ச்சியில் வேட்கை உடையவர்கட்கு ஆவனவாம்.`,
  },
  {
    id: 2380, tantraId: 8, verseNumber: 2379,
    tamil: `ஆகும் அனாதி கலைஆ கமவேதம்
ஆகும்அத் தந்திரம் அந்நூல் வழிநிற்றல்
ஆகும் அனாதி உடல்அல்லா மந்திரம்
ஆகும் சிவபோ தகம்உப தேசமே`,
    transliteration: `ākum aṉāti kalaiā kamavētam
ākumat tantiram annūl vaḻiniṟṟal
ākum aṉāti uṭalallā mantiram
ākum civapō takamupa tēcamē`,
    english: `2379: Tantra, Mantra Upadesa
Beginningless are AgamaVedas
Tantra is to act their way,
Mantras are of the mind and beyond the body;
Upadesa is the teaching of Siva-Jnana.`,
    elaborationTamil: `அநாதியே உள்ளவனால் செய்யப்பட்டமையின், 'அநாதி நூல்' எனப்படுகின்ற ஆகமங்களையும், வேதங்களையும் ஓதி, ஐயம் திரிபு அற உணர்தல் மந்திரகலாந்தம். ஏனைப் பாசுபதம் முதலிய தந்திரங்களை அவ்வாறு உணர்தல் தந்திர கலாந்தம். அவ்வாறு உணரப் பட்ட அந்நூல்களில் கண்டவாறு ஒழுகும் ஒழுக்கத்தில் மேம்படுதல் தெளிவுக் கலாந்தம். திருவைந்தெழுத்தைத் தத்தமக்கு உரியமுறையில் மனம் முதலிய அந்தக் கரணங்களால் அன்றி, அறிவால் சுத்தமான -தாகப் பெரிய அளவில் கணித்தல் ஞான கலாந்தம். குரு உபதேசத்தை நன்கு சிந்தித்துத் தெரிந்தபின் நிட்டையில் நிற்றல் உபதேச கலாந்தமாம்.`,
  },
  {
    id: 2381, tantraId: 8, verseNumber: 2380,
    tamil: `தேசார் சிவமாகும் தன்ஞானத் தின்கலை
ஆசார நேய மறையும் கலாந்தத்துப்
பேசா உரையுணர் வற்ற பெருந்தகை
வாசா மகோசர மாநந்தி தானே`,
    transliteration: `tēcār civamākum taṉñāṉat tiṉkalai
ācāra nēya maṟaiyum kalāntattup
pēcā uraiyuṇar vaṟṟa peruntakai
vācā makōcara mānanti tāṉē`,
    english: `2380: Jnana
The way of Self-Jnana
Is to be one with Siva;
In the Kalanta
Devotional love disappears;
Sans speech, sans sentience
Jiva becomes Being Great
Unto Nandi Himself,
That is beyond speech and thought.`,
    elaborationTamil: `ஞான கலாந்தத்தில் சிவம் வெளிப்படும். (என்றாலும் அதன்கண் அன்பு செய்து அழுந்துதல் உபதேச கலாந் தத்தில் உண்டாகும்). தெளிவுக் கலாந்தம் இறைநெறி ஒழுக்கத்தையும், இறையன்பையும் வலுப்படுத்தும். (என்றாலும் அவற்றை அஃது அறிவியல் முறையில் உணர்த்தாது. அவ்வாறு உணர்த்துவது உபதேச கலாந்தமே). வாய் வாளாமைபெற்று, பிறபொருள் உணர்வும், தன்னுணர்வும் அற்ற பெருந்தகையோன் வாக்கு மனங்களைக் கடந்த பரம சிவன் ஆவான்.`,
  },
  {
    id: 2382, tantraId: 8, verseNumber: 2381,
    tamil: `தான்அவ னாகும் சமாதி தலைப்படில்
ஆன கலாந்தநா தாந்தயோ காந்தமும்
ஏனைய போதாந்தம் சித்தாந்த மானது
ஞான மென்ஞேய ஞாதுரு வாகுமே`,
    transliteration: `tāṉava ṉākum camāti talaippaṭil
āṉa kalāntanā tāntayō kāntamum
ēṉaiya pōtāntam cittānta māṉatu
ñāṉa meṉñēya ñāturu vākumē`,
    english: `2381: Serenity in Samadhi
In Samadhi Jiva with Siva
One becomes;
In Kalanta, in Nadanta, in Yoganta
And in Bodhanta and Siddhanta
Is Jnana reached
Of Knowledge, the Known and the Knower
One uniting.`,
    elaborationTamil: `(வேதாந்தம் சித்தாந்தத்துள் அடங்க ஆறந்தங்கள் ஐந்தந்தங்களாகும்). 'ஞாதுரு, ஞானம், ஞேயம்' என்னும் மூன்று பொருள்கள் உள்ளன எனக் கூறுவதில் எந்த அந்தமும் வேறுபட வில்லை. ('ஞானம் ஒன்றே உள்ளது; ஏனையவை இல்லை' - எனக் கூறும் ஏகான்மவாதம் வேதாந்தம் அன்று - என்பது மேலேகூறப் பட்டது), இவற்றுள் ஞாதுருவாகிய ஆன்மாவும், அதன் ஞானமும் சமாதிநிலையில் ஞேயத்திலன்றிப் பிறவற்றிற் செல்லாமையால், ஞாதுருவாகிய ஆன்மாவும் சிவமேயாய்நிற்கும்.`,
  },
  {
    id: 2383, tantraId: 8, verseNumber: 2382,
    tamil: `ஆறந்த மும்சென்று அடங்கும்அந் நேயத்தே
ஆறந்த ஞேயம் அடங்கிடும் ஞாதுரு
கூறிய ஞானக் குறியுடன் வீடவே
தேறிய மோனம் சிவானந்த மாமே`,
    transliteration: `āṟanta mumceṉṟu aṭaṅkuman nēyattē
āṟanta ñēyam aṭaṅkiṭum ñāturu
kūṟiya ñāṉak kuṟiyuṭaṉ vīṭavē
tēṟiya mōṉam civāṉanta māmē`,
    english: `2382: The Six Ends Merge in Jnana
In that Jnana, (Divine Knowledge)
The Six Antas (ends) merge;
That Jnana (Knowledge) in the Knower (Jnani) merges;
When Knowledge in the Knower merges;
Then dawns Mauna (Divine Silentness)
That is Siva-Bliss.`,
    elaborationTamil: `ஆறந்தங்களிலும், 'ஞாதுரு ஞானத்துடன் சென்று, ஞேயத்தில் அடங்குதலைத்தான் முடிநிலையாகக் கூறுகின்றன. ஆகவே, ஞாதுருவும், ஞானமும் ஞேயத்தில் சென்று அடங்குதல்தான் ஆறந்தங்களின் குறிக்கோளும். ஆயினும், 'ஞேயத்தில் அடங்குதல் மட்டுமன்றி, அவ்விடத்தில் எல்லையில்லாததோர் இன்பநுகர்ச்சியில் ஞாதுரு மூழ்கியிருத்தலே உண்மைப்பேறு' எனக் கூறுகின்ற சித்தாந் -தமே ஏனை அந்தங்களினும் வடித்தெடுத்த மோன நிலையாகும்.`,
  },
  {
    id: 2384, tantraId: 8, verseNumber: 2383,
    tamil: `உண்மைக் கலைஆறுஓர் ஐந்தான் அடங்கிடும்
உண்மைக் கலாந்தம் இரண்டுஐந்தோடு ஏழ்அந்தம்
உண்மைக் கலைஒன்றில் ஈறாய நாதாந்தத்து
உண்மைக் கலைசொல்ல ஓர்அந்தம் ஆமே`,
    transliteration: `uṇmaik kalaiāṟuōr aintāṉ aṭaṅkiṭum
uṇmaik kalāntam iraṇṭuaintōṭu ēḻantam
uṇmaik kalaioṉṟil īṟāya nātāntattu
uṇmaik kalaicolla ōrantam āmē`,
    english: `2383: Of the Kalai Sixteen
Unmanai Kala ends in the Sixteenth,
Unmanai Kalanta ends beyond in the Seventeenth;
When Unmanai Kala is reached
Then is Nadanta;
Unmanai Kala is verily a goal great.`,
    elaborationEnglish: ``,
    elaborationTamil: `உண்மையை உணர்த்தும் கலைகள் பலவாகச் சொல்லப்படினும் அவை அனைத்தும் பன்னிரு கலைக்குள் அடங்குவனவாம். இனி, அனைத்துக் கலைகளையும் விடாது கடக்க வேண்டின், பதினாறைத்தாண்டி அப்பால் செல்லுதல் வேண்டும், 'நாதந்தம்' என்பது, இவ்வாறு கூறப்படுவனவற்றின் இடையே நிற்கின்ற ஒன்று. ஆகையால், அதையே 'உண்மை' என்று சொல்லின், அஃது ஏகதேசத்தையே 'முற்று' எனக் கருதுவதாகவே முடியும்.`,
  },
  {
    id: 2385, tantraId: 8, verseNumber: 2384,
    tamil: `ஆவுடை யானை அரன்வந்து கொண்டபின்
தேவுடை யான்எங்கள் சீர்நந்தி தாள்தந்து
வீவற வேதாந்த சித்தாந்த மேன்மையைக்
கூளி யருளிய கோனைக் கருதுமே`,
    transliteration: `āvuṭai yāṉai araṉvantu koṇṭapiṉ
tēvuṭai yāṉeṅkaḷ cīrnanti tāḷtantu
vīvaṟa vētānta cittānta mēṉmaiyaik
kūḷi yaruḷiya kōṉaik karutumē`,
    english: `2384: Lord Revealed Truth of Vedanta-Siddhanta
Having been blessed by Grace of Sakti,
That Siva espoused,
The Holy Nandi, that is Lord of Celestials,
Granted His Feet;
Beckoning me to Him
He revealed the Truth Exalted
Of Vedanta-Siddhanta,
--Him, the Lord, meditate on.`,
    elaborationTamil: `தேவரையெல்லாம் தம் ஆளுகைக்கு உட்படுத்தி ஆட்சி புரிகின்ற, எங்களுடைய புகழ்மிக்க நந்திபெருமானே, நாங்கள் ('வேதாந்தமும், சித்தாந்தமும் வேறு வேறு' எனக் கூறிப்பிணங்குவார் பின் சென்று) கெடாதபடி எங்களை அறைகூவி அழைத்துத் திருவடி தீக்கை செய்து, 'அவ்விரண்டிலும் சொல்லப்படுகின்ற உண்மை ஒன்றே என்பதையும், அவ்வுண்மையின் உயர்வையும் இனிது விளங்க உபதேசித்தருளிய ஞான குருவாவார். பசுக்களாகிய அனைத்துயிர் களையும் அடிமையாக உடைய சத்தி ஆதி சத்தியாய் நின்று ஆட்டிப் புடைக்கும் நிலையில், சிவனும் ஆதிசிவனாகவே அவளுடன் இருந்தவன், அந்நிலையை மாற்றித் தனது இயற்கை நிலையாகிய அநாதி சிவனாம் பரமசிவனாகி வந்து, அவளைத் தழுவிக்கொண்ட பின்பு, ஏனையோர்க்கும் எங்கட்கு அருளியவாறே அருளுமாறு அவன் அந்நந்தி பெருமானைத் திருவுள்ளத்தில் எண்ணுவான்.`,
  },
  {
    id: 2386, tantraId: 8, verseNumber: 2385,
    tamil: `கருதும் அவர்தம் கருத்தினுக்கு ஒப்ப
அரனுரை செய்தருள் ஆகமந் தன்னில்
வருசமயப் புற மாயைமா மாயை
உருவிய வேதாந்த சித்தாந்த உண்மையே`,
    transliteration: `karutum avartam karuttiṉukku oppa
araṉurai ceytaruḷ ākaman taṉṉil
varucamayap puṟa māyaimā māyai
uruviya vētānta cittānta uṇmaiyē`,
    english: `2385: The Truth of Vedanta-Siddhanta is the Truth of Agamas
To each according to his understanding
The Lord reveals Truth of His Agamas;
Beyond and penetrating
The Prakriti Maya (impure) and Mamaya (pure-impure)
--Is the doctrinal Truth of Vedanta-Siddhanta.`,
    elaborationTamil: `கொள்வார் கொள்ளும் வன்மை மென்மைகட்கு ஏற்பச் சிவன் உலகில் பலவகைச் சமய நூல்களை ஆக்கி வைத்திருக் -கின்றான். (அவை ஒன்றோடொன்று முரணுதல் போலத் தோன்றுதல், அவற்றைக் கொள்வாரது பக்குவத்திற்கு ஏற்ப அவை அமைந்ததனாலேதான். அதனால் அவற்றைக் கொள்வோர் தமக்கு விருப்பமானவற்றைக் கொண்டு அமைதல் வேண்டுமன்றிப் பிறருக்கு விருப்பமானவற்றைப் பழித்தல் கூடாது. ஏனெனில் எல்லா நூல்களும் இறைவன் அருளால் தோன்றியவையேயாகலின்) அந்நூல்களின் வழி அமைந்த சமயங்களில் சில, 'புறம்' எனப்படும். மாயை, மகாமாயை இவற்றைக் கொண்டுள்ள சமயங்கள் அகச்சமயங்களாம். அவற்றையும் கடந்து நிற்பன வேதாந்த சித்தாந்தத் தத்துவங்கள்.`,
  },
  {
    id: 2387, tantraId: 8, verseNumber: 2386,
    tamil: `வேதாந்தம் சித்தாந்தம் வேறிலா முத்திரை
போதாந்த ஞானம் யோகாந்தம் பொதுஞேய
நாதாந்தம் ஆனந்தம் சீரோ தயமாகும்
மூதாந்த முத்திரை மோனத்து மூழ்கவே`,
    transliteration: `vētāntam cittāntam vēṟilā muttirai
pōtānta ñāṉam yōkāntam potuñēya
nātāntam āṉantam cīrō tayamākum
mūtānta muttirai mōṉattu mūḻkavē`,
    english: `2386: Vedanta and Siddhanta Know No Differences
In the imprint of Vedanta and Siddhanta,
There is difference none;
Bodhanta is Jnana (Divine Knowledge);
Yoganta is Jneya (the Known)
Nadanta is Dawning of Bliss
The finale imprint
Is in Silentness (Mauna) Immersed-to-be.`,
    elaborationTamil: `ஆறந்தங்களில் வேதாந்தம், சித்தாந்தம் இரண்டும் ஒன்றே எனத்தெளிவான அடையாளங்களைப் பெற்றுள்ளன. 'போதந்தம்' என்பது உயிர் அஞ்ஞானம் நீங்கி, ஞானத்தைப் பெறும் நிலையாகும். 'யோகாந்தம்' என்பது, பொதுப்பட ஒரு பொருளைக் குறியாகக்கொண்டு அதனையே நோக்கிநிற்பது. நாதாந்தம் திரு வருளைத் தலைப்பட்டு, அதனாலே சிவானந்தம் தோன்றப் பெறுவது. இவற்றிற்கு மேலாக முதலிற்கூறிய வேதாந்த சித்தாந்தங்களே முடிந்த அடையாளமாகிய பேசாநிலையைப் பெற்றுச் சிவானந்தத்தில் திளைத்திருக்கலாகும்.`,
  },
  {
    id: 2388, tantraId: 8, verseNumber: 2387,
    tamil: `வேதாந்தம் தன்னில் உபாதிமே வேழ்விட
நாதாந்த பாசம் விடுநல்ல தொம்பதம்
மீதாந்த காரணோ பாதியேழ் மெய்ப்பரன்
போதாந்த தற்பதம் போமசி என்பவே`,
    transliteration: `vētāntam taṉṉil upātimē vēḻviṭa
nātānta pācam viṭunalla tompatam
mītānta kāraṇō pātiyēḻ meypparaṉ
pōtānta taṟpatam pōmaci eṉpavē`,
    english: `2387: Tvampada, Tatpada, Asipada Goals
The seven Upathis (experiences)
(That are the Caused (Kariya);)
Nadanta goal rids of Pasa
And reaches to Thompatha State (Tvam-Pada);
Beyond are Causal (Karana) Upathis seven;
Above which is Tatpada of Para
Real,
That Bodha leads to;
Beyond still is Asipada.`,
    elaborationEnglish: `The Vedanta goal transcends the seven causal expericnces. The Nadanta goal in dissolving the malas reaches to the tvam-pada state. The Bodhanta goal leads to the tatpada state. Beyond, transcending the seven causal experiences is asipada.`,
    elaborationTamil: `வேதாந்தத்தில் சொல்லப்படுவது, 'பிரகிருதியும் அதன் காரியமுமாகிய ஏழுவகைக் குற்றங்களினின்றும் நீங்க வேண்டும்' என்பதே. அவை 1. பூதங்கள், 2. ஞானேந்திரியங்கள், 3. அவற்றின் விடயங்கள், 4. கன்மேந்திரியங்கள், 5. அவற்றின் விடயங்கள், 6. அந்தக் கரணங்கள் என்பனவும், எல்லாவற்றிற்கும் மூலமாகிய 7. பிரகிருதியும் ஆகியவையாம்.
வேதாந்தத்திற்கு மேலேயுள்ள கலாந்தமாகச் சொல்லப் படுவது பிரோக காண்டம் ஆதல் பற்றிக்காரண தத்துவங்களாகச் சொல்லப்படுகின்ற சுத்த தத்துவங்களால் செலுத்தப்படுகின்ற வித்தியா தத்துவங்கள் ஏழும் நீங்குதலாம். இத்தத்துவங்கள் தடத்த சிவனால் செலுத்தப்படுதல் பற்றி, 'பரோபாதி' என்றும் சொல்லப்படும்.
நாதாந்தமாகச் சொல்லப்படுவது, உயிர் உபாதிகள் அனைத்தும் நீங்கி நிற்கின்ற நிலையாம். 'தத்துவமசி' மகா வாக்கியத் -தில் ஆன்மாவைக் குறிப்பதாகிய 'துவம்' பதம் இந்நிலையில் நின்ற ஆன்மாவையே குறிப்பதாம்.
போதாந்தமாகச் சொல்லப்படுவது, உபாதிகளின் நீங்கிய ஆன்மா மல வாசனையால் 'யான், எனது' எனநிற்கின்ற நிலையை விடுத்துச் சிவமாகும் நிலையாம் 'தத்துவமசி' மகாவாக்கியத்தில் 'ஆசி' பதம் ஆன்மா இவ்வாறாகும் நிலையையே குறிப்பதாம். 'தத்' பதம் சிவத்தைக் குறிக்கும்.`,
  },
  {
    id: 2389, tantraId: 8, verseNumber: 2388,
    tamil: `அண்டங்கள் ஏழும் கடந்துஅகன்று அப்பாலும்
உண்டென்ற பேரொளிக் குள்ளாம் உளஒளி
பண்டுறு நின்ற பராசக்தி என்னவே
கொண்டவன் அன்றிநின் றான்தங்கள் கோவே`,
    transliteration: `aṇṭaṅkaḷ ēḻum kaṭantuakaṉṟu appālum
uṇṭeṉṟa pēroḷik kuḷḷām uḷaoḷi
paṇṭuṟu niṉṟa parācakti eṉṉavē
koṇṭavaṉ aṉṟiniṉ ṟāṉtaṅkaḷ kōvē`,
    english: `2388: Transcendental Nature of Siva
Transcending Universes Seven
And the Beyond
Is the Great Light;
Lord is Light of that Light,
Of yore, He with Parasakti stood;
There He stands lofty, all by Himself,
He, Our Lord.`,
    elaborationTamil: `'உலகங்கள் அனைத்தையும் கடந்தாலும் அவற்றிற்கு அப்பாலும் ஒருபேரொளி உள்ளது' என வேதாகமங்கள் கூறுகின்றன. அந்தப் பேரொளிக்குள்ளே உள்ள ஓர் ஒளிதான் எங்கள் சிவபெருமான். அவன் அந்தப்பேரொளியைத் தனக்கு இயல்பாய் உள்ள மேலான ஆற்றலாக உடையவன். எனினும் அந்த ஆற்றலை ஆட்சி செய்கின்ற ஒருவனாகவும் அவன் அதற்குள் இருக்கின்றான்.`,
  },
  {
    id: 2390, tantraId: 8, verseNumber: 2389,
    tamil: `கோஉணர்ந் தும்சத்தி யாலே குறிவைத்துத்
தேவுணர்த் துங்கரு மஞ்செய்தி செய்யவே
பாவனைத் தும்படைத் தர்ச்சனை பாரிப்ப
ஓஅனைத் துண்டுஒழி யாத ஒருவனே`,
    transliteration: `kōuṇarn tumcatti yālē kuṟivaittut
tēvuṇart tuṅkaru mañceyti ceyyavē
pāvaṉait tumpaṭait tarccaṉai pārippa
ōaṉait tuṇṭuoḻi yāta oruvaṉē`,
    english: `2389: Lord Engrosses All Existence
Center on Kundalini in Muladhara
That Guru by his power taught,
Perform acts
That lead to God,
Sing in full His holy praise,
Thus worship Him,
Then shall you meet the Being One
Who, existence interminable, engrosses.`,
    elaborationTamil: `சிவன் தனது சத்தியாலே உயிர்கட்கு அறிவிக்கும் முறையை உணர்ந்து, அந்த வழியிலே குரு உபதேசித்த பணிகளைச் செய் வதாலும், மற்றும் மந்திரங்களைச் சமர்ப்பித்து வழிபாடு செய்வதாலும் பாசங்கள் யாவும் நீங்கும். பின்பு என்றுமே உயிர்க் -குயிராய் நீங்கா -திருக்கின்ற சிவன் ஒருவனே உயிரினிடத்து உள்ள பொருளாவான்.`,
  },
  {
    id: 2391, tantraId: 8, verseNumber: 2390,
    tamil: `ஒருவனை உன்னார் உயிர்தனை உன்னார்
இருவினை உன்னார் இருமாயை உன்னார்
ஒருவனு மேயுள் உணர்ந்திநின் றூட்டி
அருவனு மாகிய ஆதரத் தானே`,
    transliteration: `oruvaṉai uṉṉār uyirtaṉai uṉṉār
iruviṉai uṉṉār irumāyai uṉṉār
oruvaṉu mēyuḷ uṇarntiniṉ ṟūṭṭi
aruvaṉu mākiya ātarat tāṉē`,
    english: `2390: God is One Formless Being
They think not of the Being One,
They think not of the Jiva,
They think not of Karmas two, (Good and Bad)
They think not of Mayas two, (Pure and Impure)
The One Being within
Stands as Sentience and fosters,
Formless is He,
He supports all.`,
    elaborationTamil: `சித்தாந்தம், ''மற்றாருந்தன்னொப்பாரில்லாத'' l தலைவன் ஒருவன் இருக்கின்றான். எனக் கூறுவதையோ, 'அத் தலைவனுக்கு அடிமையாய் உள்ள உயிர்கள் பல உள்ளன' எனக் கூறுவதையோ, 'அவ்வுயிர்கட்கு நல்வினை; தீவினை யென்னும் இருவகை வினைகளும், சுத்த மாயை என்னும் மாயைகளும் ஆகிய கட்டுக்கள் உள்ளன' எனக் கூறுவதையோ சக்திநிபாதம் வாயாதவர் உணர வல்லவராகார். ஆகையால், எக்காலத்திலும் உயிர்களின் அறிவுக் கறிவாய் நின்று அவைகளுக்கு அறிவித்து, வினைப்பயனை நுகர்வித்து, அவற்றிற்கு அவை அறியாமலே ஆதாரமாயும் நிற்கின்ற அந்தத் தலைவனே இருவினை யொப்பு மல பரிபாகங்களின்போது அறி -வித்தால்தான் எவரும் இந்தச் சித்தாந்த உண்மைகளை உணர இயலும்.`,
  },
  {
    id: 2392, tantraId: 8, verseNumber: 2391,
    tamil: `அரன்அன்பர் தானம தாகிச் சிவத்து
வருமவை சத்திகள் முன்னா வகுத்திட்டு
உரனுறு சந்நிதி சேட்டிப்ப என்றும்
திரனுறு தோயாச் சிவாநந்தி யாமே`,
    transliteration: `araṉaṉpar tāṉama tākic civattu
varumavai cattikaḷ muṉṉā vakuttiṭṭu
uraṉuṟu canniti cēṭṭippa eṉṟum
tiraṉuṟu tōyāc civānanti yāmē`,
    english: `2391: Siva's Concern For His Devotees
In His devotees is Siva seated
Into them He brings in
The Saktis that are of Siva
Then in His mighty Presence they (Saktis) act;
There the devotees remain ever
Immersed in Siva Bliss.`,
    elaborationTamil: `சிவன்பால் அன்புள்ளவர்களை இடமாகக் கொண்டு வெளியாகின்ற ஆற்றல்கள் எல்லாம் அவர்களுடைய ஆற்றல்கள் அல்ல; மற்று, சிவனிடத்தினின்றும் வெளியாகின்ற ஆற்றல்களே அந்த ஆற்றல்களின் முன்னிலையில் எல்லாப் பொருள் களையும் சிவன் நிற்க வைத்துச் செயற்படச் செய்தலால், உயிர் நிலையாகச் சிவானந்தத்தில் மூழ்கி, அவ்வானந்தமே மயமாம் நிலையை அடையும்.`,
  },
  {
    id: 2393, tantraId: 8, verseNumber: 2392,
    tamil: `வேதாந்த தொம்பதம் மேவும் பசுஎன்ப
நாதாந்த பாசம் விடநின்ற நன்பதி
போதாந்த தற்பதம் போய்இரண்டு ஐக்கியம்
சாதா ரணம்சிவ சாயுச் சிய மாமே`,
    transliteration: `vētānta tompatam mēvum pacueṉpa
nātānta pācam viṭaniṉṟa naṉpati
pōtānta taṟpatam pōyiraṇṭu aikkiyam
cātā raṇamciva cāyuc ciya māmē`,
    english: `2392: Tvam Pada, Tat Pada, Asi Pada (Sayujya)
In the Vedanta Way
The Jiva (Pasu) reaches Tvam Pada State
(The Two--I and He--together are)
Then follows Nadanta the goodly State
Where Pasa is rid;
Then follows Bodhanta that reaches to Tatpada State
Where I and He in one union is;
Siva Sayujya is the Goal Beyond
That follows.`,
    elaborationTamil: `வேதாந்தப் பொருள் முழுவதையும் மிகச் சுருக்கமாகத் தொகுத்துணர்த்தும், 'ஒருமொழி அல்லது 'பெரும்பெயர்' எனப்படுகின்ற மகாவாக்கியங்கள் சிலவற்றுள், 'தத்துமசி' என்பதே சிறந் தெடுத்துச் சொல்லப்படுவது. (இது சாமவேதவாக்கியம்) இதனுள் 'தத்' என்பது பதியாகிய சிவத்தையும், 'துவம்' என்பது பசுவாகிய உயிரையும், 'அசி' என்பது, உயிரைச் சிவமாக்குகின்ற அருட் சத்தியையும் குறிக்கும். எனினும், 'இவற்றுள் பசுவாகிய உயிர் பஞ்ச பேதங்களை யுடைய (இத்தந்திரத்து முதல் அதிகாரம்) உடலளவில் ஏகதேசமாய உள்ளதன்று; வியாபகமானதே' என்பதை வலியுறுத்தி விளக்குவதே வேதாந்தமாகும். மண்முதல் நாதம் ஈறாகச் சொல்லப் படுகின்ற உபாதி களுள் ஒன்றும் இன்றி, நின்மலமாய் நிற்பது எதுவோ அதுவே பதிப் பொருள்' என வலியுறுத்தி விளக்குவது நாதந்தமாகும் ('உயிர் இவ்வு பாதிகளை உடைமையாலே - பசு - எனப்பட்டது' என்பதும் இதனானே விளங்கும்).
இனி, துவம் பதப்பொருளாகிய உயிர் தத் பதப் பொருளாகிய சிவத்தில் சென்று 'பாலோ டளாயநீர பாலாகு மலலது நீராய் நிறந்தெரிந்து தோன்றாதவாறுபோல''3 சிவமேயாய் வேறு தோன்றாது ஒன்றிவிடுதலை வலியுறுத்தி விளக்குவதே போதாந்தமாகும். (போதம் - சீவபோதம். அந்தம் - அதன் ஒடுக்கம். அஃதாவது கதிரொளியில் விளக்கொளிபோலச் சிவபோதத்தில சீவ போதம் அடங்கியிருத்தல்).
['போதாந்தம் கூறும் நிலையை எய்தி, அவ்விடத்தில உயிர் பேரா இன்பப் பெருவெள்ளத்தில் அழுந்துதலை வலியுறுத்தி விளக்குவதே சித்தாந்தமாகும்' என்பது குறிப்பு.]
'சிவமும், சீவனும் பொருள் இரண்டாமாயின், அவை ஒன்றாதல் எங்ஙனம் கூடும்' எனின், அவ்விரண்டற்கும் இடையே உள்ள பொதுத்தன்மைதான் அவை அங்ஙனம் ஒன்றாதற்குக் காரணம் [அத்தன்மையாவது, இரண்டும் சித்தாய் இருத்தலாம். எனவே, சடத்திற்குச் சிவத்தோடு ஒன்றுதல் கூடாமை விளங்கும்].`,
  },
  {
    id: 2394, tantraId: 8, verseNumber: 2393,
    tamil: `சிவமாதல் வேதாந்த சித்தாந்த மாகும்
அவம்அவம் ஆகும் அவ்வவ் இரண்டும்
சிவமாம் சதாசிவன் செய்துஒன்றான் ஆனால்
நவமான வேதாந்தம் ஞானசித் தாந்தமே`,
    transliteration: `civamātal vētānta cittānta mākum
avamavam ākum avvav iraṇṭum
civamām catācivaṉ ceytuoṉṟāṉ āṉāl
navamāṉa vētāntam ñāṉacit tāntamē`,
    english: `2393: Of the Six Ends Vedanta and Siddhanta Alone Show the
Path to Siva-Becoming
Siva-Becoming
Is the goal of Vedanta and Siddhanta
The rest four Ends lead not to Siva-Becoming,
--Siva that is Sadasiva--
And so it is that Vedanta and Siddhanta
Are wondrous Ways indeed.`,
    elaborationTamil: `ஆறந்தங்களுள், 'வேதாந்தம், சித்தாந்தம்' என்னும் இரண்டும், சீவன் சிவம் ஆதலைக் கூறுவதில் வேறுபட வில்லை. ஏனை, 'போதாந்தம், கலாந்தம், நாதாந்தம், யோகாந்தம்' என்னும் நான்கும் ஒன்றின் ஒன்று கீழ்ப்பட்ட நிலைகளையே விளக்கி நிற்கும். வேதமும், சித்தாந்தத்தைக்கூறும் சிவாகமும், உண்மையில் 'சிவம் எனப்படுகின்ற அந்தப்பொருளே, தடத்தத்தில் 'சதாசிவன்' என்னும் பெயரையும், அதற்குரிய வடிவத்தையும் கொண்டு செய்த முதல்நூல் ஆகுமானால், அவற்றுக்கிடையே வேறுபாடிருத்தல் எங்ஙனம் கூடும். கூடாது. ஆகவே, வேதாந்த ஞானம், சித்தாந்த ஞானமேயாம்.`,
  },
  {
    id: 2395, tantraId: 8, verseNumber: 2394,
    tamil: `சித்தாந்த தேசீவன் முத்திசித் தித்திலால்
சித்தாந்தத் தேநிற்போர் முத்திசித் தித்திவர்
சித்தாந்த வேதாந்தம் செம்பொருள் ஆதலால்
சிந்தாந்த வேதாந்தம் காட்டும் சிவனையே`,
    transliteration: `cittānta tēcīvaṉ mutticit tittilāl
cittāntat tēniṟpōr mutticit tittivar
cittānta vētāntam cemporuḷ ātalāl
cintānta vētāntam kāṭṭum civaṉaiyē`,
    english: `2394: Jivan Mukti in Siddhanta
In Siddhanta is attained
Jivan Mukti (Liberation in this body);
Those who stood in Siddhanta
Have verily reached the Mukti
State;
As Siddhanta-Vedanta
Leads to the Goal of Siva-Becoming,
Siddhanta-Vedanta
Is the Path Exalted.`,
    elaborationTamil: `ஆறந்தங்களுள் சித்தாந்தத்தில் நிற்கும் நிலையில் தான் சீவன் முத்தி (அஃதாவது, உடம்பு உள்ளபொழுதே அதில் தொடக்கற்று, வீட்டின்பத்தில் இருக்கும்நிலை) கிடைக்கும். ஆகையால், சித்தாந்த நிலையில் நிற்பவர் உலகர்போலவே காணப் படினும், அவர் உலகருள் ஒருவராகாது, வீடுபேற்றில் இருப்பவரே ஆவார். வேதாந்தத்தின் உட்கிடையும் சித்தாந்தமேயாதலால், அவ்வுட்கிடையை உணரவல்லவர்கட்கு வேதாந்தம், சித்தாந்தம் இரண்டும் சிவனையே பரமாகக் காட்டி நிற்றல் விளங்கும்.`,
  },
  {
    id: 2396, tantraId: 8, verseNumber: 2395,
    tamil: `சிவனைப் பரமனுள் சீவனுள் காட்டும்
அவமற்ற வேதாந்த சித்தாந்தம் ஆனால்
நவமுற்று அவத்தையில் ஞானம் சிவமாம்
தவமிக்கு உணர்ந்தவர் தத்துவத் தாரே`,
    transliteration: `civaṉaip paramaṉuḷ cīvaṉuḷ kāṭṭum
avamaṟṟa vētānta cittāntam āṉāl
navamuṟṟu avattaiyil ñāṉam civamām
tavamikku uṇarntavar tattuvat tārē`,
    english: `2395: Beyond Jiva Turiya and Para Turiya is Siva Turiya
In the Vedanta-Siddhanta Way
Beyond Siva aspects in Param and in Jiva
Arises the Jnana
In Pure State of Experience (Turiyatita)
That verily is Siva State ultimate
Only those who in Tapas stood
Realized Siva Truth (Tattva).`,
    elaborationTamil: `சிவனை ஈசுரனிடத்திலும், சீவனிடத்திலும் வைத்துக் காட்டுவது வேதாந்தம். அதில் இருவகை உண்டு. ஒன்று பரிணாம வாதம்; மற்றொன்று ஆபாசவாதம். ஆபாசம் - போலி. விவர்த்தனம் ஆபாசத்துள் அடங்கும். விவர்த்தனம் - கயிறு பாம் பாதல் போலும் பொய்த்தோற்றம். 'நிர்க்குணமாகிய பரப்பிரமமே தன் இச்சையால், சத்துவகுணனாகிய ஈசுரனாகவும், இராசத குண னாகிய சீவனும், தாமத குணத்தவாகிய அந்தக் கரணம் முதலிய கருவி களுமாய்ப் பரிணமிக்கும்' என்பது பரிணாம வாதம். 'நிர்க் குணமாகிய பரப்பிரமத்திலே - இன்னது எனச்சொல்ல இயலாத - மாயை என்பது உண்டு. அது முக்குணங்களை யுடையது. மூன்றுநிறம் உடைய கண்ணாடியைப் போன்றது. அம்மூன்றுகூற்றிலும் கண்ணாடி -யில் நிழல் போலப் பரப்பிரமம் பிரதிபலிக்கும். அவற்றுள் சத்துவக் கூற்றின் பிரதி பலனம் ஈசுரனாயும், இராரசதக் கூற்றின் பிரதிபலனம் சீவனாயும், தாமதக் கூற்றின் பிரதி பலனம் அந்தக் கரணம் முதலிய கருவிகளாயும் நின்று செயற்படும்' என்பது ஆபாசவாதம். இந்த ஆபாசத்திற்கு அடிப்படை மாயையே யாகையால், ஆபாசவாதமே 'மாயாவாதம்' எனப்படுகின்றது எவ்வகை யிலேனும் இந்தவேதாந்தம் 'சகம், சிவன், பரம்' என்னும் முப் பொருளை உணர்த்துதலால், இதனை உணர்ந்த பின் ஆகமாந்தத்தை உணருங்கால், வேதாந்தக் கூற்று தூலாருந்ததி முறைமைத்தாதல் விளங்கும். தூலாருந்ததி முறைமை யாவது, 'அருந்ததி மீன் மிக நுண்ணி தாதலின், அதனைக் காட்டுதல் அரிது' என்று கருதி முதற்கண், அதற்கு அருகில் உள்ள ஒரு பெரு மீனைச் சுட்டி, 'அதுவே அருந்ததி' எனக் காட்டுதல் போன்ற முறை. முதலில் அப்பெருமீனைக் கண்டுணர்ந் தவனுக்குப் பின்பு, 'அஃதன்று அருந்ததி மீன்; அதனைச் சார்ந்து மிக நுண்ணியதாய் விளங்குகின்றதனைப் பார்; அதுவே அருந்ததி மீன்' எனக்காட்டினால், அவன் அருந்ததியைக் கண்டுகொள்வான். இம் முறையில் அருந்ததி யல்லாத மீனை அணுக்கம் பற்றி 'அருந்ததி' என்றல் போல்வது இங்குக் கூறிய வேதாந்தப் பொருள். அருந்ததி மீனையே சுட்டி, 'அருந்ததி மீன்' எனக் காட்டுதல் போல்வது ஆகமாந்தப்பொருள். ஆகவே, தூலாருந்ததி முறைமை பற்றி நோக்கினால் இங்குக் கூறிய வேதாந்தமும் பயனில்லது ஆகா தாகலின், இந்த வேதாந்தமும் சித்தாந்தமேயாம். இவ்வாறு ஆகும் நிலைமையில் ஒருவனது ஞானம் அமையுமாயின், அந்த ஞானம் தசகாரியத்துள் ஒன்பதாம் நிலையாகிய 'சிவயோகம்' எனப்படுகின்ற சீவன் சிவனாய் நிற்கும் நிலைமையைத் தரும். 'சரியை, கிரியை, யோகம்' என்றும் தவங்களின் மிகுதியனாலே இத்தகைய ஞானத்தை எய்தினோரே, 'தத்துவ ஞானிகள்' எனப்படுகின்றார்கள்.`,
  },
  {
    id: 2397, tantraId: 8, verseNumber: 2396,
    tamil: `தத்துவம் ஆகும் சகள அகளங்கள்
தத்துவ மாம்விந்து நாதம் சதாசிவம்
தத்துவ மாகும் சீவன் தன் தற்பரம்
தத்துவ மாம்சிவ சாயுச் சியமே`,
    transliteration: `tattuvam ākum cakaḷa akaḷaṅkaḷ
tattuva māmvintu nātam catācivam
tattuva mākum cīvaṉ taṉ taṟparam
tattuva māmciva cāyuc ciyamē`,
    english: `2396: All States Are Tattvas or Steps Only to Siva-Sayujya
The Form and Formless States
Are alike Tattvas;
The Bindu, Nada and Sadasiva too
Are Tattvas verily;
So too is Jiva's (Tvam Pada and Tat Pada);
Tattva truly is where Tatpara is in Siva-Sayujya.`,
    elaborationEnglish: ``,
    elaborationTamil: `சித்தாந்தத்தில் சொல்லப்படுகின்ற உருவம், அருவம் உருவாருவம் ஆகிய சிவவடிவங்களும், அவற்றிற்கு இடமாகின்ற விந்து, நாதம், சாதாக்கியம் ஆகிய நிலைக்களங்களும், சீவனும், அதனின் மேம்பட்ட சிவன், சத்தி, சதாசிவன் ஆகிய கருத்தாக் -களும் உண்மைகளேயன்றி, மேற்கூறிய வேதாந்தத்தில் சொல்லப் படுபவன போல, பரிணாமமோ, ஆபாசமோ அல்ல. ஆகவே, சீவன் சிவனோடு, கதிரவன் ஒளியில் விளக்கொளிபோல இரண்டறக் கலக்கும் சித்தாந்த முத்தியே உண்மை முத்தியாம்.`,
  },
  {
    id: 2398, tantraId: 8, verseNumber: 2397,
    tamil: `வேதமோடு ஆகமம் மெய்யாம் இறைவன்நூல்
ஓதும் பொதுவும் சிறப்பும்என்று உள்ளன
நாதன் உரையவை நாடில் இரண்டந்தம்
பேதமது என்பர் பெரியோர்க்கு அபேதமே`,
    transliteration: `vētamōṭu ākamam meyyām iṟaivaṉnūl
ōtum potuvum ciṟappumeṉṟu uḷḷaṉa
nātaṉ uraiyavai nāṭil iraṇṭantam
pētamatu eṉpar periyōrkku apētamē`,
    english: `2397: Veda and Agama Alike Revealed by God
Veda and Agama alike
Are revelations of God,
That is Truth;
The one is general
The other special;
Their goals two, they say;
Search them both,
For the truly learned,
There is difference none.`,
    elaborationTamil: `இதன்பொருள் வெளிப்படை.`,
  },
  {
    id: 2399, tantraId: 8, verseNumber: 2398,
    tamil: `பராநந்தி மன்னும் சிவானந்தம் எல்லாம்
பரானந்தம் மேல்மூன்றும் பாழுறா ஆனந்தம்
விராமுத்தி ரானந்தம் மெய்நடன ஆனந்தம்
பொராநின்ற உள்ளமே பூரிப்பி யாமே`,
    transliteration: `parānanti maṉṉum civāṉantam ellām
parāṉantam mēlmūṉṟum pāḻuṟā āṉantam
virāmutti rāṉantam meynaṭaṉa āṉantam
porāniṉṟa uḷḷamē pūrippi yāmē`,
    english: `2398: Beyond Bliss of Voids is the Bliss of Siva Dance
All transcendental states of bliss
That Jiva experiences
Are, alike, Siva-bliss (Sivanandam);
The Three Higher States of
Transcendental Bliss
Are States that come out of the three Voids;
The Bliss that comes of Mudras appropriate
Is the Bliss of Siva's Dance within;
It is the State that fills Soul in rapture.`,
    elaborationEnglish: ``,
    elaborationTamil: `வேதாந்தத் தெளிவாம் சித்தாந்த நெறியில் அடையப்படும் ஆனந்தம் சிவானந்தம். அதனை முற்றப்பெற்ற உயிரே மேலான ஆனந்தத்தைப் பெற்ற உயிராகும். இனி அந்த ஆனந்தம் முப் பாழுக்கு மேலே விளைவதாகும். அதனை இவ்வுலகிலே இறைவன் செய்யும் திருக்கூத்திலும் பெறலாம். திருக்கூத்தில் பெறும் 'முத்திரானந்தம், எனப்படும். அதனை எல்லாரும் பெறுதல் கூடும். சிவானந்தத்தை எந்த வகையிலேனும் பெறும் உயிரே இன்பத்தால் நிறைக்கப்பட்ட உயிராகும்.`,
  },
  {
    id: 2400, tantraId: 8, verseNumber: 2399,
    tamil: `ஆகுங் கலாந்தம் இரண்டந்த நாதாந்தம்
ஆகும் பொழுதிற் கலைஐந்தாம் ஆதலில்
ஆகும் அரனேபஞ் சாந்தகன் ஆம் என்ற
ஆகும் மறைஆ கமம்மொழிந் தான்அன்றே`,
    transliteration: `ākuṅ kalāntam iraṇṭanta nātāntam
ākum poḻutiṟ kalaiaintām ātalil
ākum araṉēpañ cāntakaṉ ām eṉṟa
ākum maṟaiā kamammoḻin tāṉaṉṟē`,
    english: `2399: Kalanta Leads to Siva as Panchantaka
Kalanta and Nadanta
Are Ends (goals) two;
As they are reached
The five Kalas (of Siva Tattva) are attained;
So the Lord that arises there
Is as Panchantaka known
Thus He spake in Vedas and Agamas.`,
    elaborationTamil: `ஆறந்தங்களில், 'கலாந்தம், நாதாந்தம்' என இரண்டு கூறப்படினும், நாதாந்தம் கலாந்தத்துள் அடங்கும் ஆதலின், நிவிர்த்தி முதலிய பஞ்சகலைகளின் முடிவே முடிவாகும் ஆகவே, 'அந்தப் பஞ்சகலைகளையும் சுத்த மாயையுள் ஒடுக்கியும், மீள விரித்தும் நிற்பவன் சிவன்' எனக் கேட்கப்படுதலன்றிப் பிறர் ஒருவரும் அத்தன்மையராதல் கேட்கப்படாமையால், அவனே ஆறந்தங்கட்கும் மூலமாகிய வேதாகமங்களைச் செய்தருளினான்.`,
  },
  {
    id: 2401, tantraId: 8, verseNumber: 2400,
    tamil: `அன்றாகும் என்னாதுஐ வகைஅந்தம் அன்னை
ஒன்றான வேதாந்த சித்தாந்தம் உள்ளிட்டு
நின்றால் யோகாந்தம் நேர்படும் நேர்பட்டால்
மன்றாடி பாதம் மருவலும் ஆமே`,
    transliteration: `aṉṟākum eṉṉātuai vakaiantam aṉṉai
oṉṟāṉa vētānta cittāntam uḷḷiṭṭu
niṉṟāl yōkāntam nērpaṭum nērpaṭṭāl
maṉṟāṭi pātam maruvalum āmē`,
    english: `2400: Beyond Kalanta Vedanta-Siddhanta Leads to Yoganta
and to Dance-Bliss
Wait not for the day
To vision the Five Kalantas;
Take to the Way of
Vedanta-Siddhanta, that one are;
Then will you reach the Yoganta,
And there will you envision the Feet
Of the Eternal Dancer,
That is Siva.`,
    elaborationTamil: `வேதாந்தத்தைத் தவிர மற்றை ஐந்து அந்தங்களை, 'உண்மையல்ல; போலி என்று இகழாதே தலையாய வேதாந்தத்தைச் சித்தாந்தத்தின் வழியாக உள்ளவாறுணர்ந்து நின்றால், யோகாந்தம் செயல்முறையில் வாய்க்கும். அது வாய்த்தால், மன்றாடியாகிய சிவனது திருவடிப்பேறும் கூடும்.`,
  },
  {
    id: 2402, tantraId: 8, verseNumber: 2401,
    tamil: `அனாதி சீவன்ஐம் மலமற்றுஅப் பாலாய்
அனாதி அடக்கித் தனைக்கண்டு அரனாய்த்
தன்ஆதி மலம்கெடத் தத்துவா தீதம்
வினாவுநீர் பாலாதல் வேதாந்த உண்மையே`,
    transliteration: `aṉāti cīvaṉaim malamaṟṟuap pālāy
aṉāti aṭakkit taṉaikkaṇṭu araṉāyt
taṉāti malamkeṭat tattuvā tītam
viṉāvunīr pālātal vētānta uṇmaiyē`,
    english: `2401: Truth of Vedanta is Jiva Mingling in Siva
Jiva that is eternal
Freed of Malas Five
Passes beyond Tattvas;
There it realizes the Self Eternal;
Then the Primal Mala of Anava
Withers away,
And with that the Tattva-atita State ensues
There one with Siva becoming is
Like water with milk indistinguishably intermingled;
That, verily, is the Truth of Vedanta.`,
    elaborationTamil: `பதியைப்போலவே பசுவாகிய சீவனும் அனாதி. அதற்கு அனாதியே ஒரு குற்றம் உண்டு. அந்தக்குற்றம் மேல் எழாமல் கீழாம்படி அடக்கினால் சீவன் தனது உண்மையைத் தான் உணரும். தன்னை உணர்ந்தால், பின் தலைவனை உணர்ந்து, அவனைச் சார்ந்து அவனாகி நிற்கும். அங்ஙனம் நிலையை அடைதற்பொருட்டுச் சீவன் அனாதிக்குப் பின் ஆதியாய் வந்த மலங்களும் நீங்கும்படி அவற்றைக் கடக்கும் முறையை ஞான குருவை அடைந்து வினாவும். பின் அவர் உபதேசித்தபடி நின்று, ஐந்து மலங்களும் நீங்கப் பெற்றுத் தூயதாய் உலகத்தைக் கடந்து நிற்கும். அந்நிலையில் அது சிவத்தைச் சேர்ந்து சிவம் ஆதல், நீர் பாலோடு சேர்ந்து பாலாதல் போல்வதாம். வேதாந்தத்தின் உண்மைப்பொருள் இதுதான்.`,
  },
  {
    id: 2403, tantraId: 8, verseNumber: 2402,
    tamil: `உயிரைப் பரனை உயிர்சிவன் தன்னை
அயர்வற்று அறிதொந் தத்தசி அதனால்
செயலற்று அறிவாகி யும்சென்று அடங்கி
அயர்வற்ற வேதாந்த சித்தாந்தம் ஆமே`,
    transliteration: `uyiraip paraṉai uyircivaṉ taṉṉai
ayarvaṟṟu aṟiton tattaci ataṉāl
ceyalaṟṟu aṟivāki yumceṉṟu aṭaṅki
ayarvaṟṟa vētānta cittāntam āmē`,
    english: `2402: Tvam-Tat-Asi State is Goal of Vedanta-Siddhanta
Jiva, Para and Siva--the States
Exalted
Continuous know;
You then reach the State,
Tvam-Tat-Asi;
There, actionless are you;
All Jnana are you;
Thus be merged;
--So says Vedanta-Siddhanta.`,
    elaborationTamil: `'உயிர், பரன், திருவருள்' என்னும் முப்பொருளை யும், 'அவற்றுள் ஒன்றையும் விடாது முறையே உணர்த்துகின்ற, 'துவம், தத், அசி' என்னும் மூன்று பதங்களால் ஆகிய வேதாந்த மகா வாக்கியத்தை அனுபவமாக உணர்வதால், நீ சடமாகிய பாசங்கள் ஆகாது, சித்தாகி விடுவாய். ஆயினும், அதன்பின் 'யான் எதனையும் யானே அறியமாட்டாமையால், தூலசித்தாகின்ற எனக்கு எஞ் ஞான்றும் அறிவித்து வருகின்ற சூக்கும சித்து ஒன்று உண்டு என உணர்ந்து, எதனையும், 'யான் அறிகின்றேன், யான் செய்கின்றேன்' எனச் செருக்குதலை விடுத்து, அந்தச் சூக்கும சித்தின்கீழ்ப் போய் அடங்கியிரு. அப்பொழுதே வேதாந்தம் சித்தாந்தம் ஆகிவிடும்.`,
  },
  {
    id: 2404, tantraId: 8, verseNumber: 2403,
    tamil: `மன்னிய சோகமாம் மாமறை யாளர்தம்
சென்னிய தான சிவயோகமாம் ஈதென்ன
அன்னது சித்தாந்த மாமறை யாய்பொருள்
துன்னிய ஆகம நூலெனத் தோன்றுமே`,
    transliteration: `maṉṉiya cōkamām māmaṟai yāḷartam
ceṉṉiya tāṉa civayōkamām īteṉṉa
aṉṉatu cittānta māmaṟai yāyporuḷ
tuṉṉiya ākama nūleṉat tōṉṟumē`,
    english: `2403: Siddhanta Agamas Are Filled With Vedic Wisdom
The mantram "Soham"
That Vedantins intone
Is but Siva Yoga
That is exalted;
Thus said Siddhanta;
Verily is it apparent
That Agamas are scriptures
With Vedic Wisdom filled.`,
    elaborationTamil: `பொது மறையாகிய வேதத்தை மட்டுமே நூலாகக் கொண்டு, சிவாகமங்களை நூலாகக்கொள்ளாதவர்கட்குத் தலையான மகாவாக்கியமாய் உள்ளது, ''ஸோஹம் அஸ்மி'' என்பது [இதன் பொருள், 'அது நான் ஆகின்றேன்' அல்லது, 'அவன் நான் ஆகின்றேன்' என்பது 'தத்துவமசி' மகாவாக்கியத்தில் முன்னிலையில் வைத்துச் சொல்லப்பட்ட பொருளே இதில், தன்மையில் வைத்துச் சொல்லப்பட்டது. ஆகையால் இவ்விரண்டிற்கும் இடையே உள்ளது வடிவு வேற்றுமையே யன்றிப் பொருள் வேற்றுமையில்லை. 'தத்துவமசி' மகாவாக்கியம், மாணவனுக்கு உபதேசிக்கும் ஆசிரியர் கூற்று. 'ஸோஹம் அஸ்மி' மகாவாக்கியம், ஆசிரியர் உபதேசித்த பொருளை அனுபவமாகக் காணும் மாணவன் கூற்று. இவற்றால் இவை முன்னிலையிடத்தும், தன்மையிடத்தும் ஆயின]. 
இனிப் பொதுமறையாகிய வேதத்தோடு, சிறப்பு மறையாகிய சிவாகமங்களையும் நூலாகக் கொள்வோர், வேதாந்தத்தில் 'ஸோக மஸ்மி' எனப் பொதுவாகக் கூறப்பட்டது, உண்மையில், 'சிவோஹ மஸ்மி' எனக்கொள்வர். (இதன் பொருள், 'சிவன் நான் ஆகின்றேன்' என்பது). அக்கொள்கையே சிறப்பு மறையாகிய சிவாகமங்கள் ஆராய்ந்து காட்டும் முடிநிலை முடிபாகும். அந்த முடிபைப் பல்லாற்றா -னும் வலியுறுத்த எழுந்த நூல்களே 'சிவாகமம்' எனப்பெயர் பெற்று விளங்குகின்றன.`,
  },
  {
    id: 2405, tantraId: 8, verseNumber: 2404,
    tamil: `முதலாகும் வேத முழுதுஆ கமம்அகப்
பதியான ஈசன் பகர்ந்தது இரண்டு
முதிதான வேதம் முறைமுறை யால்அமர்ந்து
அதிகாதி வேதாந்த சித்தாந்தம் ஆகவே`,
    transliteration: `mutalākum vēta muḻutuā kamamakap
patiyāṉa īcaṉ pakarntatu iraṇṭu
mutitāṉa vētam muṟaimuṟai yālamarntu
atikāti vētānta cittāntam ākavē`,
    english: `2404: Out of Vedas and Agamas Evolved Vedanta-Siddhanta
Two are the scriptures
That Lord Siva
In the Beginning revealed,
--The Primal Vedas and the Perfect Agamas;
The Vedas and Agamas,
In gradualness appropriate
Evolved Vedanta-Siddhanta
That is great, great indeed.`,
    elaborationEnglish: `Mular has coined the phrase He says it is evolved out of the Vedas and Agamas. It is apparent that Mular feels keenly the need for somehow reconciling the Agamic and Vedic systems.`,
  },
  {
    id: 2406, tantraId: 8, verseNumber: 2405,
    tamil: `அறிவுஅறிவு என்ற அறிவும் அனாதி
அறிவுக்கு அறிவாம் பதியும் அனாதி
அறிவினைக் கட்டிய பாசம் அனாதி
அறிவு பதியில் பிறப்பறுந் தானே`,
    transliteration: `aṟivuaṟivu eṉṟa aṟivum aṉāti
aṟivukku aṟivām patiyum aṉāti
aṟiviṉaik kaṭṭiya pācam aṉāti
aṟivu patiyil piṟappaṟun tāṉē`,
    english: `2405: Pati, Pasu, and Pasam--All Three Eternal
Beginningless is Jiva that of Knowledge speak
Beginningless is Lord, the source of all Knowledge,
Beginningless is Pasam, that binds knowledge
When God-Knowledge dawns,
No more will birth be.`,
    elaborationTamil: `உலகத்தாரால், 'அறிவு, அறிவு' என்று சொல்லப் படுவதாகிய உயிர்களும் அனாதியே உள்ளன. அவற்றின் அறிவுக்கு அறிவாய் உள்ள இறைவனும் அனாதியே உளன். அறிவாகிய உயிர்களைக் கட்டியுள்ள அறிவற்றனவாகிய பாசங்களும் அனாதியே உள்ளன. ஆயினும் அனாதியாகிய சிவனது ஞான சத்தி உயிரி -னிடத்துப் பதியுமாயின், உயிர் பிறவித்தொடர்ச்சி அறப்பெறும்.`,
  },
  {
    id: 2407, tantraId: 8, verseNumber: 2406,
    tamil: `பசுப்பல கோடி பிரமன் முதலாய்ப்
பசுக்களைக் கட்டிய பாசம்மூன் றுண்டு
பசுத்தன்மை நீக்கிஅப் பாசம் அறுத்தால்
பசுக்கள் தலைவனைப் பற்றி விடாவே`,
    transliteration: `pacuppala kōṭi piramaṉ mutalāyp
pacukkaḷaik kaṭṭiya pācammūṉ ṟuṇṭu
pacuttaṉmai nīkkiap pācam aṟuttāl
pacukkaḷ talaivaṉaip paṟṟi viṭāvē`,
    english: `2406: When Pasas Leave
Countless are Jivas (Pasu)
From Brahma downward;
Three are the Pasas (bonds)
That bind Jivas;
When bonds of Pasa are sundered,
And Jiva-nature altered,
Jivas will cling to Lord
And never leave Him.`,
    elaborationTamil: `முன் மந்திரத்தில், ''அனாதி'' எனப்பட்ட பசுக்கள் பிரமதேவன் முதலாகக் கோடிக் கணக்கில் உள்ளன. ஆயினும், அவற்றைக் கட்டியுள்ள பாசங்கள் மூன்றே. (ஆணவம், மாயை, கன்மம்). பதி பசுக்களைக் கட்டியுள்ள பாசங்களை அறுத்துவிட்டால், பசுக்கள் பசுத்தன்மை நீங்கிப் பதியைப் பற்றிக்கொள்ளும். பின்பு அவை பதியை விட்டு நீங்கமாட்டா.`,
  },
  {
    id: 2408, tantraId: 8, verseNumber: 2407,
    tamil: `கிடக்கின்ற வாறே கிளர்பயன் மூன்று
நடக்கின்ற ஞானத்தை நாடோ றும் நோக்கித்
தொடக்குஒன்றும் இன்றித் தொழுமின் தொழுதால்
குடக்குன்றில் இட்ட விளக்கது வாமே`,
    transliteration: `kiṭakkiṉṟa vāṟē kiḷarpayaṉ mūṉṟu
naṭakkiṉṟa ñāṉattai nāṭō ṟum nōkkit
toṭakkuoṉṟum iṉṟit toḻumiṉ toḻutāl
kuṭakkuṉṟil iṭṭa viḷakkatu vāmē`,
    english: `2407: Prayer Takes Jiva to States Beyond Three Pasas
Even with Pasas (three),
Attainments three can be;
Daily contemplate on Jnana
That moves you to the goal ultimate,
Unintermittent do pray;
Praying thus,
Yours will be a Light that shall beam
As from a hill-top high.`,
    elaborationTamil: `உயிர்கள் அனாதியே கிடந்த பாசநிலையிலே கிடந்தாலும் அப்பொழது அவைகட்கு உண்டாகின்ற பயன் மூன்று. அவை, 'அறம், பொருள், இன்பம்' என்பனவாம். நான்காவதாகிய வீடு அந்நிலையிலே கிட்டாது. அது கிடைக்க வேண்டுமாயின், அந்த மூன்றும் நீங்குதற்கு ஏதுவாகிய ஞானம் ஒன்றையே விரும்பிப் பதியை உலகப் பற்றுச்சிறிதும் இன்றி, நாள்தோறும் வழிபடுங்கள். வழிபட்டால் அந்தப் பதி, குடத்தில் இட்ட விளக்குப் போல மறைந்திருந்த நிலையினின்றும் நீங்கிக் குன்றில் இட்ட விளக்குப் போல வெளிப்பட்டு விளங்கும்.`,
  },
  {
    id: 2409, tantraId: 8, verseNumber: 2408,
    tamil: `பாசம்செய் தானைப் படர்சடை நந்தியை
நேசம்செய்து ஆங்கே நினைப்பர் நினைத்தாலும்
கூசம் செய்து உன்னிக் குறிக்கொள்வது எவ்வண்ணம்
வாசம்செய் பாசத்துள் வைக்கின்ற வாறே`,
    transliteration: `pācamcey tāṉaip paṭarcaṭai nantiyai
nēcamceytu āṅkē niṉaippar niṉaittālum
kūcam ceytu uṉṉik kuṟikkoḷvatu evvaṇṇam
vācamcey pācattuḷ vaikkiṉṟa vāṟē`,
    english: `2408: Why Pasas--To Seek God
He who the bonds made (you bind),
He, Nandi, of spreading matted locks,
In love endearing they (Jnanis) think of;
Thinking, they shrink from Pasas
And Godward seek;
Lo! for this it is why
He placed them (Jivas) in Pasas.`,
    elaborationTamil: `முற் பாசத்தை நீக்குதற்குப் பிற்பாசங்களைக் கூட்டிப் பிறப்பு இறப்புக்களில் சூழலவைத்து இவனை, 'அஃதும் கருணையே' என அறிந்து அவன் மாட்டு அன்பு செய்து அவனை நினைப்பவர். அவ்வாறு நினைத்தபின், அவன் பிறப்பு இறப்புக்களில் வைத்துள்ளமை பற்றி நாணம் உறுதலும், அந்நாணத்தால் அதனை வன் கண்மையாகக் கருதுதலும் எங்ஙனம் உளவாகும்? உளவாகா.`,
  },
  {
    id: 2410, tantraId: 8, verseNumber: 2409,
    tamil: `விட்ட விடம்ஏறா வாறுபோல் வேறாகி
விட்ட பசுபாசம் மெய்கண்டோ ன் மேவுறான்
சுட்டிய கேவலம் காணும் சகலத்தைச்
சுட்டு நனவில் அதீதத்துள் தோன்றுமே`,
    transliteration: `viṭṭa viṭamēṟā vāṟupōl vēṟāki
viṭṭa pacupācam meykaṇṭō ṉ mēvuṟāṉ
cuṭṭiya kēvalam kāṇum cakalattaic
cuṭṭu naṉavil atītattuḷ tōṉṟumē`,
    english: `2409: After Pasas Atita Plane
No longer ascends the body,
He who the truth of Pasu-Pasa saw and shed them
Will not in them again be,
He stands apart;
He scorches them
In the states of Primal Kevala
(inertness)
And living Sakala;
Then enters the Atita Jagrat plane.`,
    elaborationEnglish: `The once sundered will not touch jiva again, even as, the poison, once extracted, does not retum to the body. jiva, having sundered pasa through the states of keval and, sakala, enters the atita jagrat plane, which is beyond pasas.- Jiva and pasa are also eternal like the Lord, whom you seek. Nandi grants freedom from the’ eternal bondage of pasa to those who seek Him in the Siddhanta way with love and devotion.`,
    elaborationTamil: `ஒருவனுடைய உடலில் பற்றிய விடம், மணி மந்திர ஔடதங்களால் நீங்கிப் போனபின்பு மீண்டும் அஃது அவன் உடலில் ஏற இயைபில்லாததுபோல, மெய்ஞ்ஞானத்தை உணர்ந்தவன், அவ்வுணர்வினால் அவனோடு ஒன்றியிருந்த பாசங்கள் வேறாகி நீங்கிவிட்ட பின்பு, அவன் அப்பாசங்களோடு பொருந்துதற்கு இயைபில்லை. அதனால், அவன் தன்னைத் தடை செய்திருந்த கேவல சகல நிலைகளைப் போக்கி சாக்கிரத்தில் அதீதமாகிய நின்மல துரியாதீதத்தில் அழுந்திச் சீவன் முத்தனாகியே நிற்பான்.`,
  },
  {
    id: 2411, tantraId: 8, verseNumber: 2410,
    tamil: `நாடும் பதியுடன் நற்பசு பாசமும்
நீடுமாம் நித்தன் நிலையறி வார்இல்லை
நீடிய நித்தம் பசுபாச நீக்கமும்
நாடிய சைவர்க்கு நந்தி அளித்ததே`,
    transliteration: `nāṭum patiyuṭaṉ naṟpacu pācamum
nīṭumām nittaṉ nilaiyaṟi vārillai
nīṭiya nittam pacupāca nīkkamum
nāṭiya caivarkku nanti aḷittatē`,
    english: `2410: To Freedom Eternal From Bondage Eternal
The Lord you seek is Eternal
So too is Jiva and Pasa;
None know the nature of Lord Eternal;
He it is, Nandi,
That granted knowledge
Of Freedom Eternal
From Bondage Eternal
To Saiva Siddhantins that seek Him true.`,
    elaborationTamil: `சத்தி நிபாதம் வரப்பெற்றமையால், 'நாம் உய்யும் வழியாவது யாது' என ஏக்கற்று ஆராயும் பக்குவிகள் அவ்வழியை உணர்தற் பொருட்டுச் சிவாகமங்கள் வழியாகச் சிவபெருமான் அருளிச் செய்தவை, பதியேயன்றிப் பசு பாசங்களின் அனாதி நித்தத் தன்மையும், அவற்றுள் பசுக்கள் பாசத்தினின்றும் நீங்கிப் பதியை அடையும் முறைமையும் ஆகும். ஆயினும் அவைகளை அறியும் பக்குவிகள் உலகத்து அரியர்.`,
  },
  {
    id: 2412, tantraId: 8, verseNumber: 2411,
    tamil: `ஆய பதிதான் அருட்சிவ லிங்கமாம்
ஆய பசுவும் அடலே றெனநிற்கும்
ஆய பலிபீடம் ஆகுநற் பாசமாம்
ஆய அரனிலை ஆய்ந்துகொள் வார்கட்கே`,
    transliteration: `āya patitāṉ aruṭciva liṅkamām
āya pacuvum aṭalē ṟeṉaniṟkum
āya palipīṭam ākunaṟ pācamām
āya araṉilai āyntukoḷ vārkaṭkē`,
    english: `2411: Pati-Pasu-Pasam Relationship Symbolised in Temple
The Pati (Lord) is the blessed Siva Linga,
The Pasu (Jiva) is the mighty bull in front stands,
The Pasa (Bond) is the altar;
Thus in the temple
The Lord stands
For them that searching see.`,
    elaborationTamil: `சிவாலயங்களின் அமைப்பை உற்று நோக்கி உணரவல்லார்க்குக் கருவறையில் முதலிடத்தில் உள்ள இலிங்கமே பதியாயும், அவ்விலிங்கத்தின் திருமுன்பில் உள்ள இடபமே பசுவாயும், (உயிராயும்) இடபத்திற்குப் பின் உள்ள பலிபீடமே அடக்கிஒடுக்கப்பட்ட பாசமாயும் காட்சியளிக்கும்.`,
  },
  {
    id: 2413, tantraId: 8, verseNumber: 2412,
    tamil: `பதிபசு பாசம் பயில்வியா நித்தம்
பதிபசு பாசம் பகர்வோர்க்கு ஆறாக்கிப்
பதிபசு பாசத்தைப் பற்றற நீக்கும்
பதிபசு பாசம் பயில நிலாவே`,
    transliteration: `patipacu pācam payilviyā nittam
patipacu pācam pakarvōrkku āṟākkip
patipacu pācattaip paṟṟaṟa nīkkum
patipacu pācam payila nilāvē`,
    english: `2412: Lord Teaches Truth of Pasu-Pasam
The Lord daily teaches you
The truth of Pasu-Pasam;
The Lord leads the Way;
To those who realize truth of Pasu-Pasam
The Lord removes entire
The bonds of Pasu-Pasam,
--But Himself stands untouched by Pasu-Pasam.`,
    elaborationEnglish: ``,
    elaborationTamil: `முப்பொருள் இயல்பை மாணாக்கர்க்கு முன்னர்க் கேட்பித்துப் பின்னர் மீள மீள அவற்றைச் சிந்திப்பித்தற்பொருட்டு அவற்றை உபதேசிக்கின்ற ஆசிரியன் மார்கட்கு உபதேச மொழியை ஆக்கி, அதுவழியாகச் சிவன் பசுக்களின் பாசங்களை அறிவே நீக்குவான். அம்முறையில் முப்பொருள் இயல்பைச் சிந்தித்துத் தெளியின் பாசங்கள் தம்மியல்பில் நிற்கமாட்டா 'நிலைகெட்டு ஒடுங்கும்' என்பதாம்.`,
  },
  {
    id: 2414, tantraId: 8, verseNumber: 2413,
    tamil: `பதியும் பசுவொடு பாசமும் மேலைக்
கதியும் பசுபாச நீக்கமும் காட்டி
மதிதந்த ஆனந்த மாநந்தி காணும்
துதிதந்து வைத்தனன் சத்தசை வத்திலே`,
    transliteration: `patiyum pacuvoṭu pācamum mēlaik
katiyum pacupāca nīkkamum kāṭṭi
matitanta āṉanta mānanti kāṇum
tutitantu vaittaṉaṉ cattacai vattilē`,
    english: `2413: Lord Placed Pati-Pasu-Pasam Truth in Suddha Saiva
The truth of
Pati, Pasu and Pasam,
The beatitude of Mukti,
The Way of Liberation
From bonds of Pasu-Pasam,
--All these the Great Nandi of
Bliss
That wears the crescent moon
Placed in Suddha Saiva thought,
In praise worthiness surpassing.`,
    elaborationTamil: `சித்தாந்தத் தத்துவங்களைச் சிவாகம ஞான பாதத்தில் அருளிச்செய்த சிவபெருமான், அப்பொருளைப் பயக்கும் தோத்திரங்களையும் கிரியா பாதத்தில் சொல்லிவைத்திருக்கின்றான்.`,
  },
  {
    id: 2415, tantraId: 8, verseNumber: 2414,
    tamil: `அறிந்தணு மூன்றுமே யாங்கணும் ஆகும்
அறிந்தணு மூன்றுமெ யாங்கணும் ஆக
அறிந்த அனாதி வியாத்தனும் ஆவன்
அறிந்த பதிபடைப் பான்அங்கு அவற்றையே`,
    transliteration: `aṟintaṇu mūṉṟumē yāṅkaṇum ākum
aṟintaṇu mūṉṟume yāṅkaṇum āka
aṟinta aṉāti viyāttaṉum āvaṉ
aṟinta patipaṭaip pāṉaṅku avaṟṟaiyē`,
    english: `2414: The Three Classes of Jivas Created According to Degrees
of Knowledge
Everywhere are the three Jivas,
Of knowledge possessed;
The timeless Lord of Divine Knowledge, too,
Is everywhere,
Pervading Jivas three;
And so to each according to his desert,
He created them, three.`,
    elaborationTamil: `மூவகை ஆன்மாக்களும் தாம் தாம் பெற்ற தனு கரணத்தளவாக அறிவு விளங்கப் பெறுதலின், அவை யாவும் 'அணு' எனப்படுகின்றன ஆயினும் அவற்றின் உண்மை நிலை பதியைப் போல வியாபகமே. பாசத் தடை நீங்கியபின் உயிர் தனது உண்மை நிலை யாகிய வியாபக நிலையை அடையும். ஆயினும், பதியினது வியாபகத்தில் அது வியாப்பியமேயாம். உயிர்களின் ஏகதேச நிலை, வியாபக நிலை ஆகிய இருநிலைகளும் என்றும் ஒரு பெற்றியனாய் உள்ள பதியே அவைகட்கு ஆவனவற்றைச் செய்துநிற்பான்.`,
  },
  {
    id: 2416, tantraId: 8, verseNumber: 2415,
    tamil: `படைப்புஆதி யாவது பரம்சிவம் சத்தி
இடைப்பால உயிர்கட்கு அடைத்துஇவை தூங்கல்
படைப்பாதி சூக்கத்தைத் தற்பரன் செய்ய
படைப்பாதி தூய மலம்அப் பரத்திலே`,
    transliteration: `paṭaippuāti yāvatu paramcivam catti
iṭaippāla uyirkaṭku aṭaittuivai tūṅkal
paṭaippāti cūkkattait taṟparaṉ ceyya
paṭaippāti tūya malamap parattilē`,
    english: `2415: How Pasas Arise in the Order of Creation
This the way
The Primal Creation was;
Para,
Acting on Siva-Sakti
Puts Jivas to Kevala Slumber
Then, the Unborn Being
Acting on Sukshma (Subtle) Maya
Rouses them to activity;
Finally, the Para
Acting on Pure Maya
Conjoins Malas to Jivas.`,
    elaborationTamil: `படைப்பு முதலிய செயல்கள் நிகழ்தல் 'பரசிவம், பராசத்தி' என்னும் இருவராலேயாம். படைப்பு முதலிய ஐந்தொழில் களாவன, தனுகரண புவன போகங்கைள உயிர்களுக்குச் சேர்ப்பித் தலும், நீக்குதலுமேயாம். இவ்வைந்தொழில், 'சூக்குமம், தூலம்' என்னும் இருவகையில் நிகழும். சூக்கும ஐந்தொழிலைச் சிவன் சுத்தமாயையில் தான் நேரே செய்வான். தூல ஐந்தொழிலை அவன் அசுத்த மாயை பிர கிருதி மாயைகளில் அனந்ததேவர், சீகண்டர் வழியாகச் செய்விப்பான்.`,
  },
  {
    id: 2417, tantraId: 8, verseNumber: 2416,
    tamil: `ஆகிய சூக்கத்தை அவ்விந்து நாதமும்
ஆகிய சத்தி சிவபர மேம்ஐந்தால்
ஆகிய சூக்கத்தில் ஐங்கரு மம்செய்வோன்
ஆகிய தூயஈ சானனும் ஆமே`,
    transliteration: `ākiya cūkkattai avvintu nātamum
ākiya catti civapara mēmaintāl
ākiya cūkkattil aiṅkaru mamceyvōṉ
ākiya tūyaī cāṉaṉum āmē`,
    english: `2416: Creation Continues
The act of Creation continues;
With the Suksma Maya that from Para arose
The Five High;
Bindu, Nada, Sakti, and Siva
In the Sukshma also arose the five-faced God
That the Five Acts perform,
(Creation, Preservation, Dissolution, Obfuscation and Redemption)
--He, the Isanan Pure.`,
    elaborationTamil: `அபரவிந்து, அபரநாதம், பரவிந்து, பரநாதம், பராசத்தி என்னும் மேலான ஐந்து நிலைகளில் நின்று சூக்கும ஐந்தொழில் செய்பவன். அருவத்தையும் கடந்த பரம சிவன். தூல ஐந்தொழிலைச் செய்பவன் மகேசுரன்.`,
  },
  {
    id: 2418, tantraId: 8, verseNumber: 2417,
    tamil: `மேவும் பரசிவம் மேற்சத்தி நாதமும்
மேவும் பரவிந்து ஐம்முகன் வேறுஈசன்
மேவும் உருத்திரன் மால்வேதா மேதினி
ஆகும் படிபடைப் போன்அர னாமே`,
    transliteration: `mēvum paracivam mēṟcatti nātamum
mēvum paravintu aimmukaṉ vēṟuīcaṉ
mēvum uruttiraṉ mālvētā mētiṉi
ākum paṭipaṭaip pōṉara ṉāmē`,
    english: `2417: Creation Further Continued
Para Siva, Sakti and Nada
Para Bindu, the Five-faced Sadasiva
And Mahesa
And Rudra, Mal and Brahma
--Thus in order were they created,
All by Hara.`,
    elaborationTamil: `(இம்மந்திரத்தில் கூறப்படும் பொருள் எழாம் தந்திரத்தில், ''சிவமொடு சத்தி நிகழ்நாதம் விந்து'', ''தலையான நான்கும் தனதருவாகும்'' என்னும் மந்திரங்களில் கூறப்பட்டதேயாம். ஆகையால், அவற்றில் கண்டு கொள்க.)`,
  },
  {
    id: 2419, tantraId: 8, verseNumber: 2418,
    tamil: `படைப்பும் அளிப்பும் பயில்இளைப் பாற்றும்
துடைப்பும் மறைப்பும்முன் தோன்ற அருளும்
சடத்தை விடுத்த அருளும் சகலத்து
அடைத்த அனாதியை ஐந்தென லாமே`,
    transliteration: `paṭaippum aḷippum payiliḷaip pāṟṟum
tuṭaippum maṟaippummuṉ tōṉṟa aruḷum
caṭattai viṭutta aruḷum cakalattu
aṭaitta aṉātiyai ainteṉa lāmē`,
    english: `2418: Five Acts Eternal
Creation, Preservation, and Dissolution,
(That for Jivas grant rest from birth-and-death whirl)
Obfuscation and Grace
(That redeem Jiva after life below)
These, for Sakala souls He filled;
All these acts Five,
Beginningless His are.`,
    elaborationTamil: `'கேவலம், சகலம், சுத்தம்' என்னும் மூன்றனுள் சகலத்தில் படைத்தல், காத்தல், உயிர்களை இளைப்பாற்றுதற் பொருட்டு அழித்தல், சிற்றின்பத்தை அதன் இழிவு அறிந்து வெறாது விரும்பி நுகருமாறு மறைத்தல் ஆகிய முன்னர் நிகழும் அருட் செயல்களையும், சடமாகிய பாசங்களை விடுவித்துத் தன்னைக் காட்டி யருளும் அருளலாகிய பின்னர் நிகழும் அருட்செயலையும் உயிர்கள் பொருந்த வைத்த அனாதியாகிய பரமசிவனை, இத்தொழில்களை நோக்கி, 'ஐவர்' என்று கூறலாம்.`,
  },
  {
    id: 2420, tantraId: 8, verseNumber: 2419,
    tamil: `ஆறாறு குண்டலி தன்னின் அகத்திட்டு
வேறாகு மாயைில் முப்பால் மிகுத்திட்டுஅங்கு
ஈறாம் கருவி இவற்றால் வகுத்திட்டு
வேறாம் பதிபசு பாசம்வீ டாகுமே`,
    transliteration: `āṟāṟu kuṇṭali taṉṉiṉ akattiṭṭu
vēṟāku māyaiil muppāl mikuttiṭṭuaṅku
īṟām karuvi ivaṟṟāl vakuttiṭṭu
vēṟām patipacu pācamvī ṭākumē`,
    english: `2419: Creation of Tattvas7Tattvas six into six,
He placed in Kundalini
And divided the Maya into categories three
And with the last of them (Prakriti Maya)
Forged the (Tattvic) instruments;
Then were let in the Pasas to Jiva belong
He, the Pati (Lord), who apart is.`,
    elaborationTamil: `பதி, முப்பத்தாறு தத்துவங்களைச் சுத்த மாயையில் வியாப்பியமாகச் செய்து, அம்முப்பத்தாறு தத்துவங்கட்குக் காரணமாய் வேறுநிற்கும் மாயையை, சுத்த, சுத்தாசுத்தம், அசுத்தம்' என மூன்றாக வகுத்து, அந்த மாயை மாயேயங்களின் பின்னவாகிய 'தாத்துவிகம்' என்னும் காரிய பூதங்களையும் இந்தமாயை மாயேயங்களால் ஆக்கி, அனைத்துப் பொருள்கட்கும் வேறாய் நிற்கும். (எனவே, 'பசு, மாயை, மாயேயம், தாத்துவிகம் ஆகியவற்றில் கட்டுண்டு நிற்கும் என்பது பெறப்பட்டது. எனினும்) பாசங்கள் நீங்கியவழிப் பசு, பதியாகும்.`,
  },
  {
    id: 2421, tantraId: 8, verseNumber: 2420,
    tamil: `வீட்கும் பதிபசு பாசமும் மீதுற
ஆட்கும் இருவினை ஆங்குஅவற் றால் உணர்ந்து
ஆட்கு நரசு சுவர்க்கத்தில் தானிட்டு
நாட்குற நான்தங்கு நற்பாசம் நண்ணுமே`,
    transliteration: `vīṭkum patipacu pācamum mītuṟa
āṭkum iruviṉai āṅkuavaṟ ṟāl uṇarntu
āṭku naracu cuvarkkattil tāṉiṭṭu
nāṭkuṟa nāṉtaṅku naṟpācam naṇṇumē`,
    english: `2420: Creation of Experiences for Jiva
The Pasu-Pasam thus released,
When it overcomes Jiva
Pati works out his redemption;
And receives him into His Grace,
Having made him experience Karmas two,
He consigns him into hell and heaven;
And as days pass,
Jiva acquires love of God--(Pati-Pasam)
In which am I steeped.`,
    elaborationEnglish: ``,
    elaborationTamil: `பதி, பசுவை இயல்பாகவே உள்ள ஒரு பாசத்தின்மேல் மற்றொரு பாசம் பற்றும்படி அதனுள்ளே புகுத்தும். (இப்பாசம் மாயை, இயல்பாக உள்ளது ஆணவம்) அதன்பின், இருவினைகளாகிய குழியிலே ஆழச் செய்யும். அதன்பின், அந்த இருவினைகளுக்கு ஈடான துன்பத்தையும், இன்பத்தையும் பசு நுகர்தற்பொருட்டு அதனை நரகத்திலும். சுவர்க்கத்திலும் சேர்த்து, அங்கே சிலநாள் தங்க வைக்கும், இவையெல்லாம் இப்படித் தொடர்ச்சியாக நிகழ்தல் திரோதான சத்தியாலாம். அச்சத்தி இவ்வாறு செய்வித்தல், பசுக்கள் தம் பசுத்துவத்தின் நீங்கிப் பதியை அடையும் நாளைக் கிட்டுதற் பொருட்டாம்.`,
  },
  {
    id: 2422, tantraId: 8, verseNumber: 2421,
    tamil: `நண்ணிய பாசத்தில் நான்எனல் ஆணவம்
பண்ணிய மாயையில் ஊட்டல் பரிந்தனன்
கண்ணிய சேதனன் கண்வந்த பேரருள்
அண்ணல் அடிசேர் உபாயமது ஆகுமே`,
    transliteration: `naṇṇiya pācattil nāṉeṉal āṇavam
paṇṇiya māyaiyil ūṭṭal parintaṉaṉ
kaṇṇiya cētaṉaṉ kaṇvanta pēraruḷ
aṇṇal aṭicēr upāyamatu ākumē`,
    english: `2421: Anava Gives Longing for Pleasures and Maya Supplies
Them
In Pasam that binds,
Anava is I-ness;
And possessed of it,
The Jiva longs for Mayaic pleasure experiences;
Then on him descends heavenly Grace;
That indeed the Way
His Holy Feet to reach.`,
    elaborationTamil: `உயிர்களைப் பற்றியுள்ள பாசங்களில், 'நான்' என்னும் முனைப்பை உண்டாக்குவது ஆணவமே. (இம் முனைப்பே, 'தற்போதம்') என்றும், 'சீவ போதம்' என்றும் சொல்லப்படும். மாயையைக் கருவியாகப் பற்றி உயிர்கள் செயற்படும்பொழுது, இந்த 'நான்' என்னும் முனைப்போடு செயற்படுவதால்தான் அவைகட்கு வினைகள் உண்டாகின்றன. 'நான் செய்கின்றேன்' என்னும் உணர் -வோடு செய்தலால், அச் செயல்களின் பயனைச் செய்த உயிரையே நுகரச் செய்ய இறைவன் திருவுளங் கொள்கிறான். அதற்குக் காரணமும் அவன் அவ்வுயிர்கள் மாட்டு வைத்த கருணையே யன்றிப் பிறிதில்லை. அதனால், வினைப் பயனை ஊட்டுவித்தலும் அவை அவனது திருவடியை அடைதற்கு உபாயமேயாகும்.`,
  },
  {
    id: 2423, tantraId: 8, verseNumber: 2422,
    tamil: `ஆகும் உபாயமே யன்றி அழுக்கற்று
மோசு மறச்சுத்தன் ஆதற்கு மூலமே
ஆகும் அறுவை அழுக்கேற்றி ஏற்றல்போல்
ஆகுவ தெல்லாம் அருட்பாச மாகுமே`,
    transliteration: `ākum upāyamē yaṉṟi aḻukkaṟṟu
mōcu maṟaccuttaṉ ātaṟku mūlamē
ākum aṟuvai aḻukkēṟṟi ēṟṟalpōl
ākuva tellām aruṭpāca mākumē`,
    english: `2422: Grace Works Out Purity
Not only is Grace
The means to Lord's Feet,
It is the source too
For desires to end,
And purification to attain;
Even as the cloth's dirt is removed
By earth-dirt (saline earth),
Pati-Pasam Grace works out
Jiva's purity.`,
    elaborationTamil: `இறைவன் உயிர்கட்கு ஆணவ பாசத்தின்மேல் மாயை கன்ம பாசங்களைச் சேர்த்தது பல உபாயங்களுள் ஓர் உபாயம் அன்று. உயிர்கள் ஆணவ மலத்தினின்றும் நீங்கித் தூய்மை பெறுதற்கு அவற்றைச் சேர்ப்பது தவிர வேறு வழியேயில்லை. அஃது எதுபோலும் எனின், புதிதாகத் தோன்றிய ஆடையில் இயல்பாய் உள்ள அழுக்கினை மேலும் பிற அழுக்கை ஏற்றித் துவைத்தும் போக்குதல் போல்வதாம். அதனால், இயற்கையாக அன்றி இறைவனால் சேர்க்கப்பட்ட பாசங்கள் யாவும் அருளால் சேர்க்கப்பட்ட பாசங்களே.`,
  },
  {
    id: 2424, tantraId: 8, verseNumber: 2423,
    tamil: `பாசம் பயிலுயிர் தானே பரமுதல்
பாசம் பயிலுயிர் தானே பசுவென்ப
பாசம் பயிலப் பதிபர மாதலால்
பாசம் பயிலப் பதிபசு வாகுமே`,
    transliteration: `pācam payiluyir tāṉē paramutal
pācam payiluyir tāṉē pacuveṉpa
pācam payilap patipara mātalāl
pācam payilap patipacu vākumē`,
    english: `2423: Pati-Pasam Leads to Pasu-Pati
Jivas that in Pati-Pasam (Arul Pasam) stand,
Reaches the Para State;
Jivas that in Pasu-Pasam stand,
Are but Pasus (in worldly ways);
As Jivas in Pati-Pasam stand,
Attain Para State,
Jivas in Pati-Pasam continous standing
Verily become Pasu-Pati (Lord of Jivas).`,
    elaborationEnglish: ``,
    elaborationTamil: `பசு தன்னைக் கட்டியுள்ள பாசங்கள் குறும்பு செய்தலால், 'நானே பரம்' என்கின்றது. ஆயினும், அங்ஙனம் நினைப்பதும், சொல்வதும் என்றும் நிலைத்து நில்லாமல் பின் நீங்கிப் போவதால், உயிர்க்கு அந்நிலை செயற்கை நிலையாதல் விளங்கு தலின், 'உயிர் அனாதியே செயற்கையோடு கூடிப் பசுவேயாய் நிற்கின்று? என, அறிந்தோர் கூறுவர். ஆயினும், 'பதிதான் முதலிலே பாசத்தோடு கூடிப் பசுவாய் இருந்து பின் பாசத்தினின்றும் நீங்கிப் பதி யாகின்றது' எனச் சிலர் கூற முற்படுவாராயின், அங்ஙனம் கூறு வார்க்குப் பதியின் வேறாய்ப் பசு இல்லையாம் ஆகலானும், பாசங்கள் சடம் ஆகலின் தாமே செயற்படமாட்டா ஆகலானும் பதியே தன்னின் மிக இழிந்த பாசங்களை மேலிட்டுக்கொண்டு பசுவாதல் கூடுமோ?`,
  },
  {
    id: 2425, tantraId: 8, verseNumber: 2424,
    tamil: `அத்தத்தில் உத்தரம் கேட்ட அருந்தவர்
அத்தத்தில் உத்தர மாகும் அருள்மேனி
அத்தத்தி னாலே அணையப் பிடித்தலும்
அத்தத்தில் தம்மை அடைந்து நின்றாரே`,
    transliteration: `attattil uttaram kēṭṭa aruntavar
attattil uttara mākum aruḷmēṉi
attatti ṉālē aṇaiyap piṭittalum
attattil tammai aṭaintu niṉṟārē`,
    english: `2424: Siva-Guru Teaches the Four Rishis
The Tapasvins (four) sought of yore
The Way (of Truth) from the Lord;
He, the Gracious One,
Gave them answer by Divine Gesture
(Chin mudra);
And as with their hands they held fast to His feet,
They reached the Way of Truth,
their Self-realizing.`,
    elaborationEnglish: `Sanatana, Sanatkumara, Sanantana—these are the four holy rishis, said to be the spiritual sons of Brahma, who sought of Siva the truth of holy wisdom. Siva sitting under the wild banyan tree as Guru Dakshinamurt, facing southward, . taught them the Divine Truth by chin-mudra (gesture 9f jnana) in silence. Dakshinamurthi is held as the Supreme Siva Guru.

Also see the Prologue.`,
    elaborationTamil: `வேதாகமங்களின் அர்த்தத்திலே தெளிவு பிறவாமல் ஐயுற்று வினாவிய முனிவர்களை, அந்த வேதாமகப் பொருள்களில் முடிந்த பொருளாய் உள் அருட்டிரு மேனியானது தனது கையினாலே அணைத்துத் தழுவிக் கொள்ளுதலும், அவர்கள் அத்திருமேனியில் அமைந்த கைக்குறிப்பினாலே தம்மை உள்ளவாறு உணர்ந்துகொண்டார்கள்.`,
  },
  {
    id: 2426, tantraId: 8, verseNumber: 2425,
    tamil: `காலும் தலையும் அறியார் கலதிகள்
கால்அந்தச் சத்தி அருள்என்பர் காரணம்
பாலொன்று ஞானமே பண்பார் தலைஉயிர்
கால்அந்த ஞானத்கைக் காட்டவீ டாகுமே`,
    transliteration: `kālum talaiyum aṟiyār kalatikaḷ
kālantac catti aruḷeṉpar kāraṇam
pāloṉṟu ñāṉamē paṇpār talaiuyir
kālanta ñāṉatkaik kāṭṭavī ṭākumē`,
    english: `2425: Feet are Grace; Head is Jnana
Neither head nor foot they know
Miscreants they are;
The Feet the Holy say
Are the Grace of Sakti;
The Head the Holy say
Is Jnana
That with First Cause unites;
When to Jiva the Feet of Grace
Shows the Head of Jnana
Then shall Liberation be.`,
    elaborationTamil: `முற்செய் தவம் இன்மையால் இப்பிறப்பில் நல்லறி வின்றிப் புல்லறிவேயுடையார், தம்மை எல்லாம் அறிந்தவராக மதித்துக்கொண்டு, ஏவவும் செய்கலாது, தாமும் தேராதுl பயனில வற்றைப் 'பயனிடைய' எனவும், பயனுடையவற்றை 'பயனில' எனவும் கொண்டு தாம் வேண்டியவாறே செல்பவர்களை, 'தலை கால் தெரியாது திரிபவர்' என்றல் வழக்கு. அதன் பொதுப் பொருள் வெளிப் படையாயினும், சிறப்புப் பொருள் குறிப்பாகவே உள்ளது. அஃது யாதெனின், 'கால்' என்பது சிவனது சத்தி. அஃதே திருவருள். அஃதே எல்லாவற்றிற்கும் வினை முதல் 'தலை' என்பது உயிர். 'உயிர்க்கு அறிவு உண்டாதல் தலையிலே' என்பது யாவரும் அறிந்தது. எனவே, ஞானம் உதயமாவது 'தலை' எனப்படுகின்ற உயிரினிடத்திலேதான். அந்த ஞானம் தானே உதயமாகாது. 'கால்' எனப்படுகின்ற சிவசத்தி உதிப்பிக்கவே உதயமாகும். (ஞானகுரு மாணாக்கனது தலையில் தமது காலை வைத்துத் தீக்கைசெய்தல் இந்த உண்மையை நன் குணர்த்தும். தாழ்ந்தோர் உயர்ந்தோர் காலில் தங்கள் தலைபடும் படிவணங்கும் மரபும் இது பற்றியது. ''பொல்லார் இணை மலர் நல்லார் புனைவரே''8 என மெய்கண்டதேவர் அருளிச்செய்த குறிப்பும் உணரத்தக்கது. 
''கோள் இல் பொறியிற் குணம் இலவே, எண்குணத்தான் 
தாளை வணங்காத் தலை''* 
என்றதும் இக்குறிப்பினதே.) காலாகிய சிவசத்தி உதிப்பிக்கின்ற ஞானத்தின் பயன் அந்த உயிர் வீடு பெறுதலாம்.`,
  },
  {
    id: 2427, tantraId: 8, verseNumber: 2426,
    tamil: `தலைஅடி யாவது அறியார் காயத்தில்
தலைஅடி உச்சியில் உள்ளது மூலம்
தலைஅடி யான அறிவை அறிந்தோர்
தலைஅடி யாகவே தான்இருந் தாரே`,
    transliteration: `talaiaṭi yāvatu aṟiyār kāyattil
talaiaṭi ucciyil uḷḷatu mūlam
talaiaṭi yāṉa aṟivai aṟintōr
talaiaṭi yākavē tāṉirun tārē`,
    english: `2426: Head and Feet Are Within
They know not
The Head and Foot (of Lord) is within body,
The Head is in Sahasrara (Cranium)
The Foot in Muladhara;
Those who visioned thus in the Yogic way,
Remained in Prayer
Their heads bowed at Lord's feet.`,
    elaborationTamil: `(முன் மந்திரத்தில், ''காலந்த ஞானத்தைக் காட்ட வீடாகுமே'' என்ற சிவஞானமாகிய பதி ஞானமாம்) உடம்பில் 'தலை, கால்' என்பன. வெளியுறுப்பாய் இருத்தல் யாவரும் அறிந்தது. ஆயினும் உடம்பிற்கு உள்ளே தலை கால்கள் உள்ளன; அவற்றைப் பலர் அறியார். அந்த 'தலை, கால்' என்பன முறையே தலை உச்சியும், மூலாதாரமும் ஆகும். (தலை உச்சி 'ஏழாம்தானம் எனப்படும்) அந்தத் தலையில் எல்லாருக்கும் இயல்பாக உண்டாகின்ற அறிவு உலகியல் அறிவாகும். அந்த அறிவு, மூலாதாரத்தில் உள்ள குண்டலி கீழ் மேலாகச் சுழன்று செய்யும் செயலால் யோகக்காட்சி அறிவாய் மாறி நிகழப்பெற்றவர், அந்த அறிவையே உடையராய் இருத்தலன்றி, உலகியல் அறிவை உடையவர் ஆகார்.`,
  },
  {
    id: 2428, tantraId: 8, verseNumber: 2427,
    tamil: `நின்றான் நிலமுழுது அண்டமும் மேலுற
வன்தாள் அசுரர் அமரரும் உய்ந்திடப்
பின்தான் உலகம் படைத்தவன் பேர்நந்தி
தன்தாள் இணைஎன் தலைமிசை ஆனதே`,
    transliteration: `niṉṟāṉ nilamuḻutu aṇṭamum mēluṟa
vaṉtāḷ acurar amararum uyntiṭap
piṉtāṉ ulakam paṭaittavaṉ pērnanti
taṉtāḷ iṇaieṉ talaimicai āṉatē`,
    english: `2427: Greatness of Feet
He stood, heaven and earth encompassing,
That the mighty Asuras and Devas
May redemption know;
He who created this world
Is the Great Nandi;
His Feet, on my head, I bore.`,
    elaborationTamil: `'அடி தலை அறியும் திறம்' என்பது, 'இறைவனது அடி தலைகளை அறிதல்' எனவும் பொருள் தரும். அம்முறையில் பார்க்கும்பொழுது, 'அவனது அடி தலைகள் உயிர்களால் அறிய இயலாதவை' என்று அறிதலே மெய்யறிவாகும் அந்த உண்மையை அறிவிக்கவே அவன் மாலும், அயனும் போர் செய்தபொழுது அப்போரினால் மிக்க வலிமையையுடைய அசுரரும் - தேவருங்கூட அழியாது வாழ்தற்பொருட்டுத் தனது திருவடிகள் நிலம் முழுதும் கடந்து கீழாகவும், முடி அண்டங்களை யெல்லாம் கடந்து அவற்றிற்கு மேலாகவும் இருக்கும்படி நெடியதோர் உருவத்தோடு அவர்கட்கு இடையே தோன்றி நின்றான். (அவர்கள் அவனது அடியையும், முடியையும் தேடிக் காணாது இளைத்தனர். அங்ஙனமாகவே) உலகம் முழுவதையும் படைத்தல் முதலிய ஐந்தொழிலைச் செய்யும் முதல்வன் அவனே ஆகின்றான். அவன் 'நந்தி' என்பதைத் தனது பெயராக உடையவன். அவனது திருவடியிணை தான் தலைமேல் உள்ளது.`,
  },
  {
    id: 2429, tantraId: 8, verseNumber: 2428,
    tamil: `சிந்தையின் உள்ளே எந்தை திருவடி
சிந்தையின் எந்தை திருவடிக் கீழது
எந்தையும் என்னை அறியகி லான்ஆகில்
எந்தையை யானும் அறியகி லேனே`,
    transliteration: `cintaiyiṉ uḷḷē entai tiruvaṭi
cintaiyiṉ entai tiruvaṭik kīḻatu
entaiyum eṉṉai aṟiyaki lāṉākil
entaiyai yāṉum aṟiyaki lēṉē`,
    english: `2428: Only By God's Grace Jiva Can Know Him
Are my Father's Holy Feet;
At my Father's Holy Feet;
Are my thoughts centered
If my Father knows me not,
Neither will I my Father know.`,
    elaborationTamil: `(முன் மந்திரத்தில் சொல்லியவாறு சிவனது திருவடி -யினை எனது தலைமேல் மட்டும் உள்ளதன்று எனது சித்தத்தி னுள்ளேயும் உள்ளது. இனி எனது சித்தத்தை உள்ளடக்கி, வெளியி -லேயும் உள்ளது. (இந்நிலை, அவன்தானே இரங்கி எனக்குச் செய்த அருட்செயலாகும். ஏனெனில்,) முதற் கண் அவன் என்னை நினையாதிருப்பின், நான் அவனை நினைப்பதற்கே வழியில்லை.`,
  },
  {
    id: 2430, tantraId: 8, verseNumber: 2429,
    tamil: `பன்னாத பாரொளிக்கு அப்புறத்து அப்பால்
என்நா யாகனார் இசைந்தங்கு இருந்திடம்
உன்னா ஒளியும் உரைசெய்யா மந்திரம்
சொன்னான்கழலினை சூடிநின் றேனே`,
    transliteration: `paṉṉāta pāroḷikku appuṟattu appāl
eṉnā yākaṉār icaintaṅku iruntiṭam
uṉṉā oḷiyum uraiceyyā mantiram
coṉṉāṉkaḻaliṉai cūṭiniṉ ṟēṉē`,
    english: `2429: Lord Gave Jnana and Mantra
Beyond, beyond the Light
That defies description,
Is the place where
My loving Lord abides;
He showed me the Light (Jnana)
That is beyond thought;
He taught me the Mantra
That is beyond words;
His Holy Feet, adoring I stood.`,
    elaborationTamil: `சொற்களால் சொல்லவராராத ஒரு நிலம்; அவ்வாறான ஓர் ஓளி; இவ்வாறெல்லாம் சொல்லப்படுகின்ற அதற்கு அப்புறத்தாகிய இடமே என்னுடையதலைவர் இருக்கும் இடம். அவர் அவ்வாறிருக்கவும் மனக் கண்ணிற்கும் காணப்படாத ஓர் ஒளியாயும், வாக்கிற்கு வாராத ஒரு மந்திரமாயும் உள்ள அதனது இயல்பையும், அதனை அடையும் வழியையும் ஒருவன் எனக்குச் சொன்னான். அந்த வழியிலே நின்றமையால், முன் தந்திரத்திற் கூறியவாறு என் தலைவனது திருவடியை யான் அடைந்தேன்.`,
  },
  {
    id: 2431, tantraId: 8, verseNumber: 2430,
    tamil: `பதியது தோற்றும் பதமது வைம்மின்
மதியது செய்து மலர்ப்பதம் ஓதும்
நதிபொதி யும்சடை நாரியோர் பாகன்
கதிசெயும் காலங்கள் கண்டுகொ ளீரே`,
    transliteration: `patiyatu tōṟṟum patamatu vaimmiṉ
matiyatu ceytu malarppatam ōtum
natipoti yumcaṭai nāriyōr pākaṉ
katiceyum kālaṅkaḷ kaṇṭuko ḷīrē`,
    english: `2430: Wait and Pray; Lord Will Come to You
The Lord's Holy Feet
In your thoughts hold;
His flower-like Feet
In wisdom adore;
The Lord who carries Sakti on His body
With Ganga muffled in his russet matted locks
Will in time your salvation grant;
Do wait and pray.`,
    elaborationTamil: `பதியாகிய சிவன் உங்கட்குக் காட்டாவிடினும் அன்பர்கட்குக் காட்டிய திருவடிகளை பதி வரலாறு உணர்ந்து அவைகளைப் பாவனையால் உங்கள் தலை மேல் வையுங்கள் மற்றும் மலர்போன்று அவைகளை உங்கள் உள்ளத்திலே வைத்துத் தியானிப்ப -துடன், வாயால் புகழ்ந்து பாடுங்கள். இவைகளையெல்லாம் இடை யறாது செய்யாவிடினும் இவற்றிற்குரிய காலங்களைத் தெரிந்து அக்காலங்களில் செய்யுங்கள்.`,
  },
  {
    id: 2432, tantraId: 8, verseNumber: 2431,
    tamil: `தரித்துநின்றானடி தன்னிட நெஞ்சில்
தரித்து நின்றான் அமராபதி நாதன்
கரித்துநின் றான்கரு தாதவர் சிந்தை
பரித்துநின் றான்அப் பரிபாகத் தானே`,
    transliteration: `tarittuniṉṟāṉaṭi taṉṉiṭa neñcil
tarittu niṉṟāṉ amarāpati nātaṉ
karittuniṉ ṟāṉkaru tātavar cintai
parittuniṉ ṟāṉap paripākat tāṉē`,
    english: `2431: Grace is Granted According to Degree of Devotion
In the thoughts of those
Who hold Him steadfast,
Firm He stood, His Feet planted;
--He, the Lord of Celestials;
Those who thought not of Him,
He shunned;
To each according to his devotion
He His Grace grants.`,
    elaborationTamil: `எல்லாப்பொருள் கட்கும் ஆதாரமாய் அவை -களைத் தாங்கிநிற்பவனாகிய சிவன் தன்னை எண்ணாதவர்களது உள்ளத்தை வெறுத்தும், அடைதற்கரிய அப்பரிபாகத்தை அடைந் தமை காரணமாக பரிபாகிகளது உள்ளத்தை விரும்பியும் நிற்கின்றான். ஆகவே, அவனது திருவடியைத் தனது உள்ளத்தில் தாங்கி நிற்பவன் இவ்வுலகத்திருப்பினும் சிவலோகத்தில் இருப்பவனேயாவான்.`,
  },
  {
    id: 2433, tantraId: 8, verseNumber: 2432,
    tamil: `ஒன்றுண்டு தாமரை ஒண்மலர் மூன்றுள
தன்தாதை தாளும் இரண்டுள காயத்துள்
நன்றாகக் காய்ச்சிப் பதஞ்செய வல்லார்கட்கு
இன்றேசென்று ஈசனை எய்தலும் ஆமே`,
    transliteration: `oṉṟuṇṭu tāmarai oṇmalar mūṉṟuḷa
taṉtātai tāḷum iraṇṭuḷa kāyattuḷ
naṉṟākak kāyccip patañceya vallārkaṭku
iṉṟēceṉṟu īcaṉai eytalum āmē`,
    english: `2432: Go the Intense Way and Behold Lord's Feet Even Today
One the heart's lotus
Three the radiant flowers
Two the Father's Feet within;
Those who can discipline the body
In Yogic Kundalini Way
May well behold Him,
Even this day.`,
    elaborationTamil: `மக்கள் உடம்பிற்குள் தாமரைக் கொடி ஒன்றே உள்ளது: அதில் மலர்கள் மூன்று உள்ளன. அந்த மூன்று மலர்களிலும் என்றும் அவற்றால் வருந்துதல் இல்லாத சிவனது திருவடியிணையும் உள்ளது. ஆயினும் அத்திருவடியிணையைக் காண்பதற்கு அந்த மூன்று மலர்களும் மலராக மலர்தல்வேண்டும். அவ்வாறு மலர்தற்கு அவை பக்குவப்படவேண்டும். அதற்கு உடம்பிற்றானே உள்ள நெருப்பை எழுப்பி வெதுப்பினால், அம்மலர்கள் பக்குவப்பட்டு மலரும் மலர்ந்தால், அங்ஙனம் மலர்விக்க வல்லவர்கட்குச் சிவனை அடைதல் இப்பொழுதே எளிதாகிவிடும்.`,
  },
  {
    id: 2434, tantraId: 8, verseNumber: 2433,
    tamil: `கால்கொண்டுஎன் சென்னியிற் கட்டறக் கட்டற
மால்கொண்ட நெஞ்சின் மயக்கிற் றுயக்கறப்
பால்கொண்ட என்ணைப் பரன்கொள்ள நாடினான்
மேல்கொண்டென் செம்மை விளம்ப ஒண்ணாதே`,
    transliteration: `kālkoṇṭueṉ ceṉṉiyiṟ kaṭṭaṟak kaṭṭaṟa
mālkoṇṭa neñciṉ mayakkiṟ ṟuyakkaṟap
pālkoṇṭa eṉṇaip paraṉkoḷḷa nāṭiṉāṉ
mēlkoṇṭeṉ cemmai viḷampa oṇṇātē`,
    english: `2433: Grace Leads to Holy State
Firm He planted His Feet on my head;
My fetters into fragments broke;
My heart's impurities were entire cleansed;
Milky-white pure it became;
The Lord then sought
To take me into His Fold;
What more can I say
Of my Holy State?`,
    elaborationTamil: `சிவபெருமான் பக்குவம் எய்திய என்னைத் தனது திருவடியாகிய மலர்கள் எனது தலையிலே எனது பாசக்கட்டு நீங்குமாறு மலரும்படி செய்யும் முகத்தால், மயக்கம் கொண்ட எனது மனத்தால் திகைத்து நிற்கின்ற திகைப்பை நீக்கி ஆட்கொள்ள நினைத்தான். அதனால் நான் கோணங்கள் எல்லாம் நீங்கி, நேர்மையை அடைந்தேன் அந்த நேர்மை இது' எனச் சொல்லவாராது.`,
  },
  {
    id: 2435, tantraId: 8, verseNumber: 2434,
    tamil: `பெற்ற புதல்வர்போல் பேணிய நாற்றமும்
குற்றமுங் கண்டு குணங்குறை செய்யவோர்
பற்றைய ஈசன் உயிரது பான்மைக்குச்
செற்றமி லாச் செய்கைக்கு எய்தின செய்யுமே`,
    transliteration: `peṟṟa putalvarpōl pēṇiya nāṟṟamum
kuṟṟamuṅ kaṇṭu kuṇaṅkuṟai ceyyavōr
paṟṟaiya īcaṉ uyiratu pāṉmaikkuc
ceṟṟami lāc ceykaikku eytiṉa ceyyumē`,
    english: `2434: God's Love For Man7The Lord loves Jivas as His
children;
Well may they wallow in dirt and blemish;
He removes them and mends their ways;
Thus is God's love for Man;
To each according to his deeds
In compassion He bestows His care.`,
    elaborationTamil: `தாம் பெற்ற புதல்வரிடத்தில் உள்ள தீ நாற்றத்தையும், அதற்குக் காரணமான அசுத்தப் பொருள்களையும் அனுபவித்த போதிலும் அப்புதல்வரிடத்தில், வெறுப்புக் கொள்ளாமலே பெற் றோர்கள் அவை நீங்குதற் பொருட்டுப் புதல்வர்க்கு வெறுப்பான செயல்கைளச் செய்வார். (அவை நெய்யிட்டு, நலங்கிட்டு முழுக் காட்டுதல், மருந்தூட்டுதல் முதலியனவாம்) அது போலவே, சிவனும் உயிர்கள் பக்குவம் எய்தற் பொருட்டு உலகப் பற்றை அவைகட்கு உண்டாக்குதலால், அப்பற்றின் வழியவான செயல் -களைச் செய்வான் ஆகவே, அது கருணை காரணமானது அன்றி, வன்கண்மை காரணமானது அன்றாம்.`,
  },
  {
    id: 2436, tantraId: 8, verseNumber: 2435,
    tamil: `மூன்றுள குற்றம் முழுதும் நலிவன
மான்றுஇருள் தூங்கி மயங்கிக் கிடந்தன
மூன்றினை நீங்கினர் நீக்கினர் நீங்காதார்
மூன்றினுள் பட்டு முடிகின்ற வாறே`,
    transliteration: `mūṉṟuḷa kuṟṟam muḻutum nalivaṉa
māṉṟuiruḷ tūṅki mayaṅkik kiṭantaṉa
mūṉṟiṉai nīṅkiṉar nīkkiṉar nīṅkātār
mūṉṟiṉuḷ paṭṭu muṭikiṉṟa vāṟē`,
    english: `2435: The Truly Liberated
That harass Jiva alike,
And in darkness enveloped
He lies in stupor;
They who are from them liberated
Are the truly liberated;
Others, entangled in them,
Surely perish.`,
    elaborationTamil: `உயிர்களை எப்பொழுதும் வருத்துவனவாய் மூன்று குற்றங்கள் உள்ளன. அதனால் ஆணவத்தின் சத்தி முற்றும் மடங்காது செயற்பட, சில வேளைகளில் ஒன்றை மற்றொன்றாக உணர்ந்தும், சில வேளைகளில் எதனையும் அறியாதே கிடந்தும் உயிர்கள் துன்புறு கின்றன. ஆகவே அம்முக்குற்றம் நீங்கப்பெற்றவரே துன்பத்தை நீக்கினவர் ஆகின்றனர். நீங்கப் பெறாதவர் அக்குற்றங்களில் கிடந்து கெடும் முறைமையை உடையவர் ஆவர்.`,
  },
  {
    id: 2437, tantraId: 8, verseNumber: 2436,
    tamil: `காமம் வெகுளி மயக்கம் இவைகடிந்து
ஏமம் பிடித்திருந் தேனுக்கு எறிமணி
ஓமெனும் ஓசையின் உள்ளே உறைவதோர்
தாமம் அதனைத் தலைப்பட்ட வாறே`,
    transliteration: `kāmam vekuḷi mayakkam ivaikaṭintu
ēmam piṭittirun tēṉukku eṟimaṇi
ōmeṉum ōcaiyiṉ uḷḷē uṟaivatōr
tāmam ataṉait talaippaṭṭa vāṟē`,
    english: `2436: Experiences in Liberation
Lust, anger and ignorance
I subdued;
And I waxed strong;
An ethereal bliss suffused me;
As though I was within the sound of "Aum"
Of a chiming bell, swinging struck.`,
    elaborationTamil: `'காமம், வெகுளி, மயக்கம்' என்னும் மூன்று குற்றங்களையும் நான் முற்றக்கடிந்து, எனக்குப் பாதுகாவலாய் உள்ள பொருளை நோக்கிக்கொண்டிருந்தேன். அப்பொழுது, அடிக்கப்பட்ட மணியினின்றும் எழும் ஓசை போல, 'ஓம்' என்னும் ஓர்ஓசை என் உடம்பினின்றும் எழுந்தது. அவ்வோசையை நுணுகி நோக்கியபோது அதனுள்ளே ஓர் அரியபொருள் வெளிப்பட அதனை நான் அடைந்தேன். இது வியப்பு.`,
  },
  {
    id: 2438, tantraId: 8, verseNumber: 2437,
    tamil: `தோன்றிய தொம்பதம் தற்பதம் சூழ்தர
ஏன்ற அசிபதம் இம்மூன்றோடு எய்தனோன்
ஆகின்ற பராபர மாகும் பிறப்பற
ஏன்றனன் மாளச் சிவமாய் இருக்குமே`,
    transliteration: `tōṉṟiya tompatam taṟpatam cūḻtara
ēṉṟa acipatam immūṉṟōṭu eytaṉōṉ
ākiṉṟa parāpara mākum piṟappaṟa
ēṉṟaṉaṉ māḷac civamāy irukkumē`,
    english: `2437: The Three States Lead to Siva-Becoming
Tvam-Padam, Tat-Padam and Asi-Padam
He who has these three states of liberation attained,
Has verily become Para-Para Himself;
No more birth shall be for him;
And when he departs
He shall indeed Siva be.`,
    elaborationTamil: `'துவம்' என்பதே சித்தர் மரபில், 'தொம்' என மரூஉ மொழியாகக் கூறப்படுகின்றது.] 'துவம்' என்னும் பதம் முன்னே எழ, அதனை அடுத்து, 'தத்' என்னும் பதம் வந்து பற்ற. அதன்பின் 'அசி' என்னும் பதமும் வந்து சேர, இம் மூன்றும் கூடிய கூட்டமாய் அமைந்த வாக்கியத்தின் பொருளாக ஒருவன் ஆகிவிடுவானாயின், அவன் வியாபகப்பொருளாகிய பரம்பொருளேயாவன். பின் முன்பு தான் பொருந்தியிருந்த மும்மலங்களும் நீங்கச் சிவமாகியிருப்பான்.`,
  },
  {
    id: 2439, tantraId: 8, verseNumber: 2438,
    tamil: `போதந் தனையுன்னிப் பூதாதி பேதமும்
ஓதுங் கருவிதொண் ணூறுடன் ஓராறு
பேதமும் நாதாந்தப் பெற்றியில் கைவிட்டு
வேதம்சொல் தொம்பத மாகுதல் மெய்ம்மையே`,
    transliteration: `pōtan taṉaiyuṉṉip pūtāti pētamum
ōtuṅ karuvitoṇ ṇūṟuṭaṉ ōrāṟu
pētamum nātāntap peṟṟiyil kaiviṭṭu
vētamcol tompata mākutal meymmaiyē`,
    english: `2438: Tvam-Pada is Beyond Nadanta State
Aim at Bodha State;
Discard elements and their diversities
(That Tattvas are composed of;)
And the ninety and six instruments of experience;
Transcend Nadanta State of glory;
Ascend beyond;
There indeed is the Tvam-Pada
State,
The Truth Vedas speak of.`,
    elaborationTamil: `'அறிவாவது சடத்தின் குணமாகாது, வேறேயாம்' என்பதை உணர்ந்து பூதம் முதலிய தத்துவ வகைகளையும், அவற்றின் கூறுகளாகிய தாத்துவிக வகைகளையும் ஆகத் தொண்ணூற்றாறு கருவிகளையும் நாதமுடிவாக அவற்றின் இயல்புகளை ஆராயும் முகத்தால், 'தான்' என மயங்காது விட்டொழித்து உண்மையாகவே, 'தத்துவமசி' என்னும் வேதாந்த மகாவாக்கியத்தில் உள்ள 'தொம்' பதப்பொருளாகி நிற்றலே ஆன்மாவின் உண்மை இயல்பாகும்.`,
  },
  {
    id: 2440, tantraId: 8, verseNumber: 2439,
    tamil: `தற்பதம் என்றும் துவம்பதம் தான்என்றும்
நிற்பது அசியத்துள் நேரிழை யாள்பதம்
சொற்பதத் தாலும் தொடரஒண் ணாச்சிவன்
கற்பனை யின்றிக் கலந்துநின் றானே`,
    transliteration: `taṟpatam eṉṟum tuvampatam tāṉeṉṟum
niṟpatu aciyattuḷ nēriḻai yāḷpatam
coṟpatat tālum toṭaraoṇ ṇāccivaṉ
kaṟpaṉai yiṉṟik kalantuniṉ ṟāṉē`,
    english: `2439: Siva is Beyond the Three Padas
In the state of Asipada, Sakti wondrous stands;
But Siva remains still beyond,
Beyond the reach of speech
In unimaginable immanence
In all, in all.`,
    elaborationTamil: `முப்பதங்களுள், 'அசி' என்னும் பதமே தத் பதம் என்றும் 'துவம் பதம்' என்றும் சொல்லத்தக்கதாய் உள்ளது. (அஃதாவது, இரண்டையும் ஒன்றாகச் செய்கின்றது.) அந்தப்பதத்தில் தான் அருட்சத்தி இருக்கின்றாள். அதனால், வாக்குக்களால் எட்ட முடியாத சிவனும் அந்தப்பதத்திலேதான் கற்பனையாக அன்றி, உண்மையாகவே கலந்து நிற்கின்றான்.`,
  },
  {
    id: 2441, tantraId: 8, verseNumber: 2440,
    tamil: `அணுவும் பரமும் அசிபதத்து ஏய்ந்த
கணுஒன் றிலாத சிவமும் கலந்தால்
இணையறு பால்தேன் அமுதென இன்பத்
துணையது வாயுரை யற்றிடத் தோன்றுமே`,
    transliteration: `aṇuvum paramum acipatattu ēynta
kaṇuoṉ ṟilāta civamum kalantāl
iṇaiyaṟu pāltēṉ amuteṉa iṉpat
tuṇaiyatu vāyurai yaṟṟiṭat tōṉṟumē`,
    english: `2440: Asi-Pada Experience
When Jiva and Para
Reach Asi-Pada State
And in pervasive Siva merge,
Then as sweetness compounded
Of milk, honey, and ambrosia
Will He in the Silentness agreeable appear.`,
    elaborationTamil: `'துவம்' பதப்பொருளாகிய ஆன்மாவும் 'தத்' பதப் பொருளாகிய பரமும் 'அசி' பதத்தால் ஒன்றான பின்பு, அதில் சிவமும் கலந்துவிடுமாயின், அக்கலவை, பாலும் தேனும் கலந்த கலவையில் அமுதமும் கலந்தாற்போல இனிமையோடு, உறுதியையும் தந்து நிற்கும். அக்கலவையின் சிறப்புச் சொல்லற்ற நிலையாய்த் தோன்றும்.`,
  },
  {
    id: 2442, tantraId: 8, verseNumber: 2441,
    tamil: `தொம்பதம் தற்பதம் தோன்றும் அசிபதம்
நம்பிய சீவன் பரன்சிவ னாய்நிற்கும்
அம்பத மேலைச் சொரூபமா வாக்கியம்
செம்பொருள் ஆண்டருள் சீர்நந்தி தானே`,
    transliteration: `tompatam taṟpatam tōṉṟum acipatam
nampiya cīvaṉ paraṉciva ṉāyniṟkum
ampata mēlaic corūpamā vākkiyam
cemporuḷ āṇṭaruḷ cīrnanti tāṉē`,
    english: `2441: Tvam-Tat-Asi
In States, Tvam-Pada, Tat-Pada and Asi-Pada
Jiva stands as Jiva, Para and Siva
In order respective;
Beyond them is the Svarupa Mahavakya (Supreme Word Manifest)
(Tvam-Tat-Asi);
Revealing that Truth,
Nandi accepted me in His Grace.`,
    elaborationTamil: `அழகிய சொற்களால் ஆகிய, பழமையான, மெய்ம்மை கூறும் மகாவாக்கியம் 'தொம், (துவம்) தத், அசி' என்னும் மூன்று சொற்களை யுடையது. அச்சொற்கள் முறையே புத்தி முத்திகளை விரும்புகின்ற சீவன், பரம்பொருள், அதன் சத்தி ஆகியவற்றைக் குறித்து நிற்கும். அவ்வாக்கியத்தைப் பன்முறையும் உணர்தலால் அடையப்படும் செவ்விய பொருள், குருவாகி வந்து ஆட்கொள்கின்ற சிவனே.`,
  },
  {
    id: 2443, tantraId: 8, verseNumber: 2442,
    tamil: `ஐம்பது அறியா தவரும் அவர்சிலர்
உம்பனை நாடி உரைமுப்ப தத்திடைச்
செம்பர மாகிய வாசி செலுத்திடத்
தம்பரயோகமாய்த் தான்அவன் ஆகுமே`,
    transliteration: `aimpatu aṟiyā tavarum avarcilar
umpaṉai nāṭi uraimuppa tattiṭaic
cempara mākiya vāci celuttiṭat
tamparayōkamāyt tāṉavaṉ ākumē`,
    english: `2442: Yoga Way Also Leads to the Three States
Even some who know not the letters Fifty
Reach the States three above said;
They did by (directing) their breath in Yogic Way
Into Para;
Thus with Siva they one became.`,
    elaborationTamil: `எழுத்தறி கல்வியில் அறியவேண்டிய எழுத்துக்கள் ஐம்பது. அவற்றுள் ஒன்றையேனும் அறியாதவரும் உளர். அவரும் மக்களுட் சிலராகவே இருக்கின்றனர்: (அவர்கள் நற்கதி அடையு மாறில்லை. ஆகவே,) கல்வி கற்றவர் அக்கல்வியின் முடிநிலையாக முப்பதங்களைக் கொள்ளுதல் வேண்டும். கொண்டு, செம்மையான, உயர்ந்த வாசியோகத்தைச் செய்தல் வேண்டும். அவ்யோகம் 'ஹம்ஸ:' என்னும் மந்திரமாக அமைதலின், அதுவே தொம்பதமும், தத்பதமுமாய் நிற்கும். நிற்கவே, அது, 'யோஹம்' என்று ஆகி, சீவன் சிவனாகின்ற பயனைத் தகும்.`,
  },
  {
    id: 2444, tantraId: 8, verseNumber: 2443,
    tamil: `நந்தி அறிவும் நழுவில் அதீதமாம்
இந்தியும் சத்தாதி விடவிய னாகும்
நந்திய மூன்றுஇரண்டு ஒன்று நலம்ஐந்து
நந்தி நனவாதி மூட்டும் அனாதியே`,
    transliteration: `nanti aṟivum naḻuvil atītamām
intiyum cattāti viṭaviya ṉākum
nantiya mūṉṟuiraṇṭu oṉṟu nalamaintu
nanti naṉavāti mūṭṭum aṉātiyē`,
    english: `2443: Turiyatita Experience
Is Atita State;
The sense organs (Indriyas) no more cognise
The Sound and the rest;
Pervasive Jiva becomes;
The Malas three, the Karmas two,
the Jiva one,
The experiences (Avasthais) Five,
All these subside;
Thus subsiding, the Beginningless
One wakes
Into the Turiyatita Jagra State.`,
    elaborationTamil: `ஆன்மாவிற்குச் சிவனை அறிகின்ற அறிவும் நழுவுவதே 'அதீதம்' எனப்படும் முடிவுநிலைவாய்க்கும். அஃதாவது, ஆன்மாச் சிவனை அறியும் பொழுது, 'யான் சிவனை யறிகின்றேன்' என அறிகின்ற அறிவும் அதைவிட்டு நழுவினால் அதன் பின்பே துரியாதீதநிலை வாய்க்கும்' என்பதாம். (ஆகவே அவ்வறிவு நழுவிய நிலை துரியமாதல் பெறப்பட்டது.) இனி அவ்வாறின்றி, ஞானேந்திரியம், கன்மேந்திரியம் அவற்றின் விடயங்களாகிய சத்தாதி, வசனாதி முதலிய தத்துவ தாத்துவிகங்கள் நீங்கியபோதிலும், 'யான்' என்னும் உணர்வு நீங்காது. ஆகவே, அது நீங்குதல் நின்மல சாக்கிரம் முதலியவற்றிலாம். அவையும் நீங்கினால் பரசாக்கிரம், பரசொப்பனம் முதலியனவே இயற்கை நிலையாகிய முத்தியைக் கூட்டுவிக்கும்.`,
  },
  {
    id: 2445, tantraId: 8, verseNumber: 2444,
    tamil: `பரதுரி யத்து நனவு படியுண்ட
விரிவிற் கனவும் இதன்உப சாந்தத்து
துரிய கழுமுனையும் ஓவும் சிவன்பால்
அரிய துரியம் அசிபதம் ஆமே`,
    transliteration: `paraturi yattu naṉavu paṭiyuṇṭa
viriviṟ kaṉavum itaṉupa cāntattu
turiya kaḻumuṉaiyum ōvum civaṉpāl
ariya turiyam acipatam āmē`,
    english: `2444: Experiences in Para Turiya
Beyond the Jagra (waking) in Paraturiya State
Is the Dream State within
That leads to Upasantha;
In the Sushupti State (of Para Turiya)
And in Turiya within Para Turiya
Is Siva reached;
Then indeed is Asi-Pada attained.`,
    elaborationTamil: `பரதுரியத்தில் உலகத்தை அனுபவித்தலாகிய கேவல சகல அஞ்சவத்தைகள் எஞ்ஞான்றும் நிகழாது அறவே நீங்கும். ஆயினும் நின்மல துரியத்தில் அவை ஒரோவொருகால் நிகழினும் நிகழும். ஆகவே, நின்மல துரிய 'அசி' பத அனுபவமாய் நிற்பதே. 'அதையும் கடந்த அனுபவம் ஆதல் இல்லை' என்பதாம்.)`,
  },
  {
    id: 2446, tantraId: 8, verseNumber: 2445,
    tamil: `தோன்றிஎன் உள்ளே சுழன்றுஎழு கின்றதோர்
மூன்று படிமண் டலத்து முதல்வனை
ஏன்றெய்தி இன்புற்று இருந்தே இளங்கொடி
நான்று நலம்செய் நலந்தரு மாறே`,
    transliteration: `tōṉṟieṉ uḷḷē cuḻaṉṟueḻu kiṉṟatōr
mūṉṟu paṭimaṇ ṭalattu mutalvaṉai
ēṉṟeyti iṉpuṟṟu iruntē iḷaṅkoṭi
nāṉṟu nalamcey nalantaru māṟē`,
    english: `2445: Parallel Yoga Way
In the encircling Spheres Three within me,
The Primal Lord appears;
I reached Him and was in bliss immersed;
I clung to the tender vine of Kundalini Sakti
That she, Her Grace may shower.`,
    elaborationEnglish: ``,
    elaborationTamil: `எனது உடம்பினுள்ளே உற்பத்தியாகி, கீழ்மேலாய் உள்ளது. யோக முயற்சியால் மேல் கீழாய்ச் சுழல்வதற்கு இடமாகின்ற மூன்று மண்டலங்கள் உள. (அவை 'தீ, ஞாயிறு, திங்கள்' என்பன) அம்மண்டலங்கட்கு மேலேயுள்ள முதல்வனைப் பற்றியுள்ள ஓர் இளமையான கொடி, அவனைப் பற்றித் தொங்கிக்கொண்டு, உடல் நலத்தையும், உயிர் நலத்தையும் தருதல் அறியத் தக்கது.`,
  },
  {
    id: 2447, tantraId: 8, verseNumber: 2446,
    tamil: `மன்று நிறைந்தது மாபர மாயது
நின்று நிறைந்தது நேர்தரு நந்தியும்
கன்று நினைந்தெழு தாயென வந்தபின்
குன்று நிறைந்த குணவிளக்கு ஆமே`,
    transliteration: `maṉṟu niṟaintatu māpara māyatu
niṉṟu niṟaintatu nērtaru nantiyum
kaṉṟu niṉainteḻu tāyeṉa vantapiṉ
kuṉṟu niṟainta kuṇaviḷakku āmē`,
    english: `2446: Lord Appears in love in Para Turiya
The Expanse vast of Para
As divine dance arena extended
Nandi there appeared
And stood and filled;
When He came in tender love
As cow that yearns for calf,
Beaming was Jiva,
As lamp upon hill-top placed.`,
    elaborationTamil: `மண்டல பரம் துவாதசாந்தத்தில் நிற்றலால் ஏனைய கடவுளர்க்கெல்லாம் மேலான கடவுளாயும், அங்கே திருநடனம் புரிவதால் மன்றில் நிறைந்ததாயும், தனது சத்தியால் உடம்பெங்கும் நிறைந்து விளங்குவதாயும், இன்னும் நேரே எழுந்தருளிவந்து அருள் புரியும் குருவடிவாயும் உள்ளது. அந்தப்பரம் உயிர்களைக் கன்றை நினைந்து ஓடிவரும் தாயைப் போல நினைந்து எதிர்வந்து அருள் புரிந்த பின்னர், குடத்துள் இருந்த விளக்குப்போல இருந்த அது, குன்றின் மேல் விளங்கும் விளக்குப் போல இனிது விளங்கி நிற்கும்.`,
  },
  {
    id: 2448, tantraId: 8, verseNumber: 2447,
    tamil: `ஆறாறு தத்துவத்து அப்புறத்து அப்புரம்
கூறா உபதேசம் கூறில் சிவபரம்
வேறாய் வெளிப்பட்ட வேதப் பசுவனார்
பேறாக ஆனந்தம் பேறும் பெருகவே`,
    transliteration: `āṟāṟu tattuvattu appuṟattu appuram
kūṟā upatēcam kūṟil civaparam
vēṟāy veḷippaṭṭa vētap pacuvaṉār
pēṟāka āṉantam pēṟum perukavē`,
    english: `2447: Beyond Para is Parasiva
Is that Para;
When the unarticulated mantra
Is in Silentness chanted,
Then appears Siva Para,
That is still above;
He is the God
Of whom Vedas speak;
Then shall Divine Rapture well up in you;
Do foster it, and enlarge.`,
    elaborationTamil: `பரம்பொருள், 'முப்பத்தாறு தத்துவங்களுக்கும் அப்பாற்பட்டது' என உணரப்படும் பொழது 'தத்துவ பரம்' எனப்படும். பொருளால் வேறாகாமை பற்றி முன்மந்திரத்தில், 'மண்டல பரமே குருவாய் வந்து உணர்த்துவது' எனக் கூறப்பட்டதாயினும் அவ்வாறு வந்து உணர்த்துவது தத்துவ பரமே. பரம் பொருள் குருவாகி வந்து உணர்த்தியது சைவ வரலாற்றில் அன்றிப் பிற சமய வரலாற்றில் காணப்படாமையால், குருவாகி வந்து உணர்த்தும் தத்துவ பரம் சிவபரமே என்பது தெளிவு. அது செய்த உபதேசமும் சொல்லமாற் சொன்ன உபதேசமே. அஃதாவது, சின் முத்திரையால் உணர்த்திய உபதேசமே. அந்த உபதேச பரத்திற்கு வேறாய்வெளிப்பட்ட, வேதாகமங்களை அருளிச்செய்த சதாசிவ நாயனார் வெளிப்பட்டது. முற்கூறிய கூறா உபதேசம் இனிது தெளியப்பட்டு பயன் தருதற் பொருட்டாம். அவ்விரு மூர்த்திகளது செயலாலும் பயன்கொள்பவரால் அச்செயல்கள் மேலும் மேலும் இன்பம் பெருகும்படி நன்கு பேணப்படும்.`,
  },
  {
    id: 2449, tantraId: 8, verseNumber: 2448,
    tamil: `பற்றறப் பற்றில் பரம்பதி யாவது
பற்றறப் பற்றில் பரனறி வேபரம்
பற்றறப் பற்றினில் பற்றவல் லோர்கட்கே
பற்றறப் பற்றில் பரம்பர மாமே`,
    transliteration: `paṟṟaṟap paṟṟil parampati yāvatu
paṟṟaṟap paṟṟil paraṉaṟi vēparam
paṟṟaṟap paṟṟiṉil paṟṟaval lōrkaṭkē
paṟṟaṟap paṟṟil parampara māmē`,
    english: `2448: Seek Lord in Intense Divine Desire and Become Siva
Shedding desires (worldly)
In intense (Divine) desire seek Him;
Yours shall be the Heavenly Kingdom of God (Param);
When you in intense (Divine) desire seek Him,
Shorn of desires (worldly),
Then shall the Knowledge of God be;
Only those who in intense (Divine) desire seek Him,
Bereft of desires (worldly),
Will (Param Param) Siva become.`,
    elaborationTamil: `பரம்பொருள் உயிர்களைப் பாதுகாக்கும் பதியாகி நிற்றல், அவ்வுயிர்கள் வேறு பற்று எதுவும் இன்றி, அனைத்துப் பற்றுக்களையும் விடுத்து, அந்தப் பரம் பொருள் ஒன்றையே பற்றி நிற்கும் பொழுதுதான், (இப்பாதுகாவல், பிறவிக் கடலினின்றும் எடுத்துக் காக்கும் காவல்) பிற பற்றுக்களை யெல்லாம் விடுத்துப் பரம் பொருளையே பற்றுதல், குரு உபதேசத்தைச் சிந்தித்துத் தெளிதலால் உண்டாகும். அதனையே,
''ஓர்த்துள்ளம் உள்ள துணரின், ஒருதலையாப்
பேர்த்துள்ள வேண்டா பிறப்பு''
-திருக்குறள் - 357.
எனத் திருவள்ளுவர் கூறினார்.
அங்ஙனம் வேறு பற்று அறப் பரம்பொருளையே பற்றும் பொழுது அந்தப் பரம்பொருளின் ஞானமே உயிரினது ஞானமாகிப் பின்பு, அதுவே பரம் பொருளும் ஆகிவிடும். பரம்பொருளாகிய பற்றப்படும் பொருளை இவ்வாறு பற்ற வல்லவர்கட்கு அப்பற்றுதலின் கண் பரம் பொருள் பரம்பொருளாகவே வெளிப்படும்.`,
  },
  {
    id: 2450, tantraId: 8, verseNumber: 2449,
    tamil: `பரம்பர மான பதிபாசம் பற்றாப்
பரம்பர மாகும் பரஞ்சிவ மேவப்
பரம்பர மான பரசிவா னந்தம்
பரம்பர மாகப் படைப்பது அறிவே`,
    transliteration: `parampara māṉa patipācam paṟṟāp
parampara mākum parañciva mēvap
parampara māṉa paracivā ṉantam
parampara mākap paṭaippatu aṟivē`,
    english: `2449: Pati-Pasam Leads to Para, Para Siva and Para Siva-
Ananda
Cherish Pati-Pasam (God-love)
That is holy beyond holiness;
Then shall the transcendental Para be;
And then beyond Parasiva reached be;
Then shall the transcendental Siva Bliss (Parasivananda) be;
Jiva Becoming Siva is indeed Knowledge Divine.`,
    elaborationTamil: `பாசங்களோடு சிறிதும் தொடர்பின்றி, மேலானதற்கும் மேலானதாய் நிற்கின் அதுவே மிகமேலான பரம்; பதி. (என்றது 'பசு பரம்' என்றபடி பாசங்களின் மேலானது பசு; அது பரம். அதற்கு மேலானது பதி; அது பரம்பரம் 'தற்பரம்' என்றும் சொல்லப் படும். தற்பரம் தனக்கு மேலானது. 'தன்' என்பது ஆன்மா தற்பரம், பரமான்மா 'தத்துவ பரம்' என்பது தத்துவங்களைக் கடந்த நிலையை மட்டும் குறிப்பது. 'பசு - பரம்' என்பது, கன்மம் திரோதாயி இவற்றிற்கு மேல் பசு இவற்றையும் கடந்தது பசுபரம்) இவ்வாறான 'பரம்' என்றும் 'சிவம்' என்றும் சொல்லப்படுகின்ற அந்தப் பொருளை உயிர், மாயா காரியப் பொருள்களில் எந்த ஒன்றினின்றும் அடையப்படாத பேரானந்தத்தையுடையதாகும். அந்த ஆனந்தத்தைப் பொருளாகக் கொண்டு முயன்று அடையும் அறிவே, 'அறிவு' என்று சொல்லப்படும்.`,
  },
  {
    id: 2451, tantraId: 8, verseNumber: 2450,
    tamil: `நனவில் கலாதியாம் நாலொன்று அகன்று
தனியுற்ற கேவலம் தன்னில் தானாகி
நினைவுற்று அகன்ற அதீதத்துள் நேயந்
தனையுற்று இடத்தானே தற்பர மாமே`,
    transliteration: `naṉavil kalātiyām nāloṉṟu akaṉṟu
taṉiyuṟṟa kēvalam taṉṉil tāṉāki
niṉaivuṟṟu akaṉṟa atītattuḷ nēyan
taṉaiyuṟṟu iṭattāṉē taṟpara māmē`,
    english: `2450: Beyond Kalanta is Tat-Para State (God-Union and Not
God-Becoming Yet)
Transcend Kalas Five
In the Waking State (of Turiya) appear;
Reach the lonely State of Higher Kevala (inertness)
And there solitary be;
Bereft of sentience,
Ardent enter the (Turiya) atita State;
Then shall you the very Tat-Para be.`,
    elaborationEnglish: `1)Nivritti, prathista, vidya, santi, santiatita. They belong to

the: sphere of Siva tattvas — vide Mantra 2377. 2)One in God-union. Shsert Neoreupib Upsregs Sms srepibd UTEP! SOHSDD`,
    elaborationTamil: `சகலத்தில் புருவ நடுவிலே நிகழும் 'கேவல சாக்கிரம், சகல சாக்கிரம்' என்னும் இருவகைச் சாக்கிரத்துள், வித்தியா தத்துவங்களில் கலை முதலிய ஐந்து தத்துவங்களும் செயற்படாது ஒடுங்கிய நிலையில் ஆன்மா உயிர்ப்பும் இன்றித் தனித்துக் கிடக்கும் ஒருநிலையை அடையும் அந்நிலையும் ஒருவகைக் கேவலமே. அந் நிலையில் கருவிகள் இல்லாவிடினும், ஆணவம் உள்ளது. கருவிகள் ஒடுங்கிய நிலையில் இந்தக் கேவல நிலை உண்டாகாமல் நீங்கித் திருவருள் அறிவிக்க அறிதலாகிய அறிவினைப் பெற்று அறிகின்ற சாக்கிரம் முதலியவைகளை அடைந்து, முடிவாக அதீதத்தை எய்தி, அதன்கண் விளங்குகின்ற ஞேயத்தில் அழுந்தும் பொழுதே ஆன்மா, மேற்கூறிய பசு பரமாகிய தற்பரமாய் நிற்கும்.`,
  },
  {
    id: 2452, tantraId: 8, verseNumber: 2451,
    tamil: `தற்கண்ட தூயமும் தன்னில் விசாலமும்
பிற்காணும் தூடணம் தானும் பிறழ்வுற்றுத்
தற்பரன் கால பரமும் கலந்தற்ற
நற்பரா தீதமும் நாடுஅக ராதியே`,
    transliteration: `taṟkaṇṭa tūyamum taṉṉil vicālamum
piṟkāṇum tūṭaṇam tāṉum piṟaḻvuṟṟut
taṟparaṉ kāla paramum kalantaṟṟa
naṟparā tītamum nāṭuaka rātiyē`,
    english: `2451: In Tat-Para Union is Aum
The Purity State
That Self-Realization brought,
The Expansive State within it,
The Malas that affected Jiva before
All these passing,
Seek the Para-atita State
Where the Tatpara and the time-bound Jiva that Para became
Commingle into one letter
That with "A" begins; "Aum."`,
    elaborationTamil: `ஆன்மா தன்னைத்தான் வேறு 'தத்துவங்கள் வேறு' என உணர்தல் ஆன்ம தரிசனமாம். அதன்பின், கருவிகள் நீங்கிய பின்பும் தனக்கு அறிவு நிகழக் காணுதலால் 'எஞ்ஞான்றும் தனக்கு அறிவைத் தருவது சிவமே' என உணர்ந்து சிவனது அறிவையே தனது அறிவிற்குப் பற்றுக் கோடாக உணர்ந்து, அவன் அறிவினாலே அவனை நோக்குதல் சிவதரிசனமாகும். இவ்விடத்தில் ஆன்மசுத்தியும் ஓரளவு உடன் நிகழும். பின்பு அங்ஙனம் உணரப்பட்ட சிவனிடத்தில் தான் அடங்கி அவனேயாய் நிற்றல் சிவயோகமாகும். இந்நிலையில் ஆன்ம சுத்தி நிறைவுறும். அதனால், பின்பு பிரபஞ்சம் காட்சிப்படினும் ஆன்மா அதனைப் பற்றாது ஒதுக்கிவிடும். இம்மூன்று நிலைகளையும் தாண்டிய பொழுது, காலத்தைக் கடந்து நிற்றலால், 'கால பரம்' என்னும், ஆன்மாவைக் கடந்து நிற்றலால், 'தற்பரம்' என்றும் சொல்லப் படுகின்ற பசுபரம் தோன்றும். பின் அதனோடு ஒற்றுமைப் படுதல் நின்மல துரியாதீதமாகும். இஃது இம்மையில் அம்மையாம் ஆன்ம லாபமாகும். இவற்றிற்குப்பின் தேகம் நீங்கப் பரசிவத்தில் கலத்தல் பரதுரியாதீத மாகும். இவற்றை யெல்லாம் தெரிந்துணர்தல், அகரத்தை முதலாக உடைய எழுத்துக்களால் ஆகிய நூல்களினாலேயாம்.`,
  },
  {
    id: 2453, tantraId: 8, verseNumber: 2452,
    tamil: `அதீதத்து ளாகி அகன்றவன் நந்தி
அதீதத்து ளாகி அறிவிலோன் ஆன்மா
மதிபெற் றிருள்விட்ட மன்னுயிர் ஒன்றாம்
பதியிற் பதியும் பரவுயிர் தானே`,
    transliteration: `atītattu ḷāki akaṉṟavaṉ nanti
atītattu ḷāki aṟivilōṉ āṉmā
matipeṟ ṟiruḷviṭṭa maṉṉuyir oṉṟām
patiyiṟ patiyum paravuyir tāṉē`,
    english: `2452: Para Jiva that Had Become Tat-Para, Jiva, Now Merges in
Siva Himself
He, Nandi, is within Atita
And Beyond it;
He, Jiva that had Para-Jiva become
Is within Atita
Yet Jnana (Full) without;
The Para Jiva attaining Jnana
And rid of dark Ignorance
Will with God (Pati) One be.`,
    elaborationTamil: `சிவன் நின்மல துரியாதீதத்தில் ஞேயமாய் வெளிப் பட்டுப் பின்பு அதனையும் நீங்கி நிற்பான். (அஃதாவது, 'போக்கியப் பொருளாகாது நிற்பான்' என்றபடி. அவன் போக்கியப் பொருளாதல் பராவத்தைகளிலாம்) அந்நிலையில் உயிர் தற்போதத்தை இழந்து நிற்கும். ஞானத்தைப் பெற்று, அஞ்ஞானத்தினின்றும் நீங்கிய உயிரே, ஒன்றாகிய பதிப்பொருளில் அழுந்தி அதுவாகும். அங்ஙனம் ஆய பொழுது அந்த உயிரே 'பரமான்மா' என்னும் பெயரைப் பெறும்.`,
  },
  {
    id: 2454, tantraId: 8, verseNumber: 2453,
    tamil: `ஆதியும் அந்தமும் இல்லா அரும்பதி
சோதிப் பரஞ்சுடர் தோன்றத்தோன் றாமையின்
நீதிய தாய்நிற்கும் நீடிய அப்பர
போதம் உணர்ந்தவர் புண்ணியத் தோரே`,
    transliteration: `ātiyum antamum illā arumpati
cōtip parañcuṭar tōṉṟattōṉ ṟāmaiyiṉ
nītiya tāyniṟkum nīṭiya appara
pōtam uṇarntavar puṇṇiyat tōrē`,
    english: `2453: Nature of Pati
The Pati (Lord) has
Neither Beginning nor End;
He is Divine Light Resplendent;
He is seen and yet unseen;
Those who attain Jnana
Of that Para
Are Holy indeed.`,
    elaborationTamil: `பதியாகிய பரம்பொருள் தோற்றமும் அழிவும் இல்லாதது. வியாபகமான பேரொளியாயும், அப்பொழுதே உயிர்க் குயிராய்க் கலந்து நிற்கும் மி நுண்ணிய விளக்காயும் உள்ளது. அஃது ஏனைப் பொருள்கள்போல எல்லார்க்கும் இனிது விளங்கித் தோன்றாது, ஒரு சிலர்க்கே விளங்கித் தோன்றுவதாய் நின்றே, கோட்டம் இன்றி, நடுவு நிலையதாயே உள்ளது. காலத்தைக் கடந்ததாகிய அந்தப் பரம் பொருளின் இயல்புகளை உணர்ந்தவர் தவம் செய்தவராவர்.`,
  },
  {
    id: 2455, tantraId: 8, verseNumber: 2454,
    tamil: `துரியங் கடங்கு துரியா தீதத்தே
அரிய வியோகங்கொண்டு அம்பலத் தாடும்
பெரிய பிரானைப் பிரணவக் கூபத்தே
துரியவல் லார்க்குத் துரிசில்லை தானே`,
    transliteration: `turiyaṅ kaṭaṅku turiyā tītattē
ariya viyōkaṅkoṇṭu ampalat tāṭum
periya pirāṉaip piraṇavak kūpattē
turiyaval lārkkut turicillai tāṉē`,
    english: `2454: He Dances in Void and Lurks Inside the Deep Well of
And entering Turiyatita,
Is the endless Void;
There vision the mighty Lord
That dances eternal;
They who can peer
Into the deep well of Pranava (Aum) within,
And glimpse Him
Will no more birth have.`,
    elaborationTamil: `யோகாவத்தையில், அனாகதம், விசுத்தி ஆஞ்ஞை, பிரமரந்திரம், துவாதசாந்தம் என்பன முறையே சாக்கிரம், சொப்பனம், சுழுத்தி, துரியம், துரியாதீதம் என்னும் அவத்தைகட்குரிய தானங்க -ளாகும். அவற்றுள் துரியத்தானமாகிய பிரமரந்திரத்தையும் கடந்து, அதீதத் தானமாகிய துவாத சாந்தத்தில், அரிதாகிய அம்பலத்தில் பொருந்தி ஆடுபவன் பெரிய பெருமான்; மகாதேவன் அந் நடனத்தைக் காணுதல் பிரணவ கலைகளின் வழியாகவே கூடும் ஆகையால், அவ்வழியால் அக்கூத்தில் அவனைக் காணவல்லவர்க்கு மலக்குற்றங்கள் இல்லையாகும்.`,
  },
  {
    id: 2456, tantraId: 8, verseNumber: 2455,
    tamil: `செம்மைமுன் னிற்பச் சுவேதம் திரிவபோல்
அம்மெய்ப் பரத்தோடு அணுவன்உள் ளாயிடப்
பொய்மைச் சகமுண்ட போத வெறும்பாழில்
செம்மைச் சிவமேரு சேர்கொடி யாகுமே`,
    transliteration: `cemmaimuṉ ṉiṟpac cuvētam tirivapōl
ammeyp parattōṭu aṇuvaṉuḷ ḷāyiṭap
poymaic cakamuṇṭa pōta veṟumpāḻil
cemmaic civamēru cērkoṭi yākumē`,
    english: `2455: Jiva's Purification
In contact with color red
White, too, becomes red;
Unto it it is,
When Jiva purified (white)
Reaches Siva (that is red);
In Jnana's Void
That absorbs universes so unreal,
Siva stands high aloft
As a flag planted on Meru Mountain top.`,
    elaborationEnglish: ``,
    elaborationTamil: `மாணிக்க மணியின் செந்நிறம் முன் வந்து நின்ற போது, பளிங்கின் வெண்ணிறம் அந்தச் செந்நிறமாகவே திரிந்து காணப்படுதல் போல, வெளிப்பட்டு நின்ற அந்த நிலையான பரம் பொருள் முன்வந்து நின்றபொழுது ஆன்மாத் தன்வண்ணம் அப்பரம்பொருள் வண்ணமேயாக, அதனுள் அடங்கி நிற்கும் அப்பொழுது அதுகாறும் நிலையற்ற பிரபஞ்சத்தை நுகர்ந்து வந்த ஆன்ம ஞானம் பாச ஞானமாய் இருந்த நிலை அற்றொழியும். அவ்வொழிவில் சிவம் மேருமலையாய் நிற்க. ஆன்மா அந்த மேருமலையை அடுத்த காக்கையாய் இருக்கும்.`,
  },
  {
    id: 2457, tantraId: 8, verseNumber: 2456,
    tamil: `வைச்ச கலாதி வருதத்து வங்கெட
வெச்ச இருமாயை வேறாக வேரறுத்து
உச்ச பரசிவ மாம்உண்மை ஒன்றவே
அச்சம் அறுத்தென்னை ஆண்டவன் நந்தியே`,
    transliteration: `vaicca kalāti varutattu vaṅkeṭa
vecca irumāyai vēṟāka vēraṟuttu
ucca paraciva māmuṇmai oṉṟavē
accam aṟutteṉṉai āṇṭavaṉ nantiyē`,
    english: `2456: Lord Accepts Jiva in His Grace
Faded have they,
Kalas and other Tattvas (below);
Sundered were they,
The Mayas two, left behind;
And after taking me into the baptismal font of Jnana,
He made me in Him unite;
Dispelling my fears
He accepted me in His Grace,
He, Nandi Holy.`,
    elaborationTamil: `எனக்குக் குருவாகிய நந்திபெருமான் சிவபெருமானால் எனக்கென என்னோடு கூட்டி வைத்த கலை முதல் நிலம் ஈறாக வருகின்ற தத்துவங்கள் எல்லாம் தம்தன்மை கெட்டுச் சிவ கரணங்களாகும் படியும், பின்பு அத்தத்துவங்கட்கு முதலாகிய அசுத்தமாயை. அதன் காரியங்களைச் செலுத்தி நிற்கின்ற கருவிகட்கு முதலாகிய சுத்தமாயை ஆகிய துன்பத்தைத் தரும் இருமாயைகளும் என்னைப் பொறுத்த மட்டில் காரண மாதற்றன்மை அடியோடு கெடும்படியும் செய்து, அதனால், யான் தடத்தசிவத்திற்கு மேலேயுள்ள சொரூபசிவத்தைத் தலைப்படும்படி. 'இனியும் பிறவி வருமோ' என்னும் அச்சம் நிகழாதவாறு என்னை ஆட்கொண்டருளினார்.`,
  },
  {
    id: 2458, tantraId: 8, verseNumber: 2457,
    tamil: `என்னை அறிய இசைவித்த என்நந்தி
என்னை அறிந்து அறி யாத இடத்துய்த்துப்
பின்னை ஒளியிற் சொரூபம் புறப்பட்டுத்
தன்னை அளித்தான் தற்பர மாகவே`,
    transliteration: `eṉṉai aṟiya icaivitta eṉnanti
eṉṉai aṟintu aṟi yāta iṭattuyttup
piṉṉai oḷiyiṟ corūpam puṟappaṭṭut
taṉṉai aḷittāṉ taṟpara mākavē`,
    english: `2457: After Self-Realization is the Light Where No Self is
Realize the Self,
--So taught my Nandi;
When I realized the Self,
He placed me in place where the
Self is unknown;
There the Light-Form arose,
And He granted me Himself,
Tat-Para I became.`,
    elaborationTamil: `எனக்குக் குருவாகிய நந்திபெருமான், முதலில் என்னை யான் அறியுமாறு அறிவித்தருளினார். (கருவிக் கூட்டத்தி -னின்றும் என்னை வேறாக யான் உணரும்படி செய்தார்.) அதனால், என்னை யான் அறிந்தபின்பு, என்னையான் அறியாது நிற்கின்ற ஓர் இடத்திலே என்னைச் செலுத்தினார். (சிவபோத மிகுதியால் சீவ போதம் தோன்றாது நிற்கின்ற திருவருள் நிலையிலே செலுத்தினார்.) பின்னர் அங்ஙனம் நின்ற அந்த ஒளியினாலே அவ்வொளிக்கு முதலாகிய பொருள் புலப்பட்டது. புலப்பட்டபின் யான் அந்த மேலான பொருளே ஆகும்படி அதனை என் கைக்குள் வருமாறு அளித்தார்.`,
  },
  {
    id: 2459, tantraId: 8, verseNumber: 2458,
    tamil: `பரந்தும் சுருங்கியும் பார்புனல் வாயு
நிரந்தர வளியொடு ஞாயிறு திங்கள்
அரந்த அறநெறி யாயது வாகித்
தரந்த விசும்பொன்று தாங்கிநின் றானே`,
    transliteration: `parantum curuṅkiyum pārpuṉal vāyu
nirantara vaḷiyoṭu ñāyiṟu tiṅkaḷ
aranta aṟaneṟi yāyatu vākit
taranta vicumpoṉṟu tāṅkiniṉ ṟāṉē`,
    english: `2458: Siva's Immanence and Transcendence
Expanding and contracting,
Earth, water, space and wind,
Sun and Moon,
Pervasive and immanent,
Hara stood;
Supporting the firmament vast.`,
    elaborationTamil: `சிவன்,
''நிலம், நீர், நெருப்பு, உயிர், நீள் விசும்பு, நிலாப், பகலோன்,
புலனாய மைந்தனோடு எண்வகையாய்ப் புணர்ந்து நின்றான்''3
எனவும்,
''இருநிலனாய்த், தீயாகி, நீரு மாகி,
இயமான னாய், எறியும் காற்றா மாகி,
அருநிலைய திங்களாய், ஞாயி றாகி,
ஆகாச மாய் அட்ட மூர்த்தி யாகி
... ... ... எம்மடிகள் நின்ற வாறே''l
எனவும் அருளிச் செய்தவாறு, ஐம்பெரும்பூதங்களும், 'ஞாயிறு' திங்கள், என்னும் இரு சுடர்களும், ஆன்மாவும் ஆகிய எட்டினையும் தனக்குத் திருமேனியாகும்படி அவைகளில் வேறின்றிக் கலந்து நிற்கின்றான்.`,
  },
  {
    id: 2460, tantraId: 8, verseNumber: 2459,
    tamil: `சத்தின் நிலையினில் தானான சத்தியும்
தற்பரை யாய்நிற்கும் தானாம் பரற்கு உடல்
உய்த்தரும் இச்சையில் ஞானாதி பேதமாய்
நித்தம் நடத்தும் நடிக்கும்மா நேயத்தே`,
    transliteration: `cattiṉ nilaiyiṉil tāṉāṉa cattiyum
taṟparai yāyniṟkum tāṉām paraṟku uṭal
uyttarum iccaiyil ñāṉāti pētamāy
nittam naṭattum naṭikkummā nēyattē`,
    english: `2459: Sakti Manifestations
From Sat (Siva) arose of Herself, Sakti,
In that State She as Tat-Parai stands;
In the Ichcha (Desire) State
She Para's Form materiality is;
Then Jnana Sakti and other forms
She assumes;
Thus acting in love surpassing
She daily, daily moves this world.`,
    elaborationTamil: `'தத்' பதப் பொருளாகிய சிவன், தனது உண்மை நிலையில் உள்ள பொழுது அவனின் வேறாகாது அவனோடு ஒன்றாகியே நிற்கும் சத்தியும், 'பரை' என நிற்கும். அஃதாவது யாதொன்றனையும் பற்றாது, தான் தனியே மேலானதாய் நிற்கும் என்பதாம். ''சத்தியும்'' என்னும் உம்மையால், சத்தியையுடைய சத்திமானாகிய சிவனும் அப்பொழுது 'பரன்' என நிற்றல் பெறப்பட்டது. 'பரசிவனாய் நிற்பன்' என்க. அந்தச் சத்தியே சிவனுக்கு வடிவம். என்றது, 'சிவம் சத்தியே மயமானது' என்றபடி. இனி அந்தச் சத்தி, அருள் காரணமாக உயிர்களின் பொருட்டு ஐந்தொழிலாகிய நாடகத்தை மேற்கொண்டு செய்யும் பொழுது, தன்னிச்சையாகவே இச்சை, ஞானம், கிரியை முதலிய வகைகளாய்ப் பலவாகி, அவ்வைந் தொழிலை இடையறாது நடத்தும்.`,
  },
  {
    id: 2461, tantraId: 8, verseNumber: 2460,
    tamil: `மேலொடு கீழ்பக்கம் மெய்வாய்கண் நாசிகள்
பாலிய விந்து பரையுள் பரையாகக்
கோலிய நான்சுவை ஞானம் கொணர் விந்து
சீலமி லாஅணுச் செய்திய தாமே`,
    transliteration: `mēloṭu kīḻpakkam meyvāykaṇ nācikaḷ
pāliya vintu paraiyuḷ paraiyākak
kōliya nāṉcuvai ñāṉam koṇar vintu
cīlami lāaṇuc ceytiya tāmē`,
    english: `2460: Bindu Sakti Imparts Power to Cognitive Organs
From within Parai
Expanded Bindu Sakti;
From above descending, to here below,
It imparted sentience to the cognitive Organs four,
--This the story of Jivas,
That inherent no sentience has.`,
    elaborationTamil: `முன் மந்திரத்தில் கூறிய சத்தி மேல், கீழ், புடை என்னும் இடங்களையும், மெய், வாய், கண், நா, மூக்கு என்னும் ஐம் பொறிகளையும், விந்து, நாதம், பர நாதம் என்னும் வாக்குகளையும், அவைகட்குப் பற்றுக் கோடாய் நின்று அவற்றின் பெயர்களையே தாமும் பெற்று நிற்கின்ற சுத்த தத்துவங்களையும் இங்ஙனம் பாகுபட்ட பல பொருள்களை உண்டாக்கி அவற்றால் எல்லாம் சரியை முதலிய நான்கினாலும் ஞானத்தை வருவித்து, இவ்வாறெல்லாம் அஞ் ஞானத்திற் கிடக்கின்ற உயிர்களை ஈடேற்றுதலாகிய செயல்களை உடையதாய் நிற்கும்.`,
  },
  {
    id: 2462, tantraId: 8, verseNumber: 2461,
    tamil: `வேறாம் அதன்தன்மை போலும்இக் காயத்தில்
ஆறாம் உபாதி அனைத்தாகும் தத்துவம்
பேறாம் பரவொளி தூண்டும் பிரகாசமாய்
ஊறாய் உயிர்த்துண்டு உறங்கிடும் மாயையே`,
    transliteration: `vēṟām ataṉtaṉmai pōlumik kāyattil
āṟām upāti aṉaittākum tattuvam
pēṟām paravoḷi tūṇṭum pirakācamāy
ūṟāy uyirttuṇṭu uṟaṅkiṭum māyaiyē`,
    english: `2461: Maya, Little Light Leading to Great Light
Then separate arose Maya from Parai
And the Caused Tattvas and experiences six
The body is an heir to;
Feeling, breathing, eating, and sleeping
Are all enjoyments that Maya gives;
She is the little light within,
That kindles the Great Light to reach.`,
    elaborationTamil: `முன் மந்திரத்தில், 'அணு' எனக் கூறப்பட்ட உயிரின் தன்மை தனியானது. ஆகவே, காணப்படாது நிற்கின்ற அந்த உயிருக்குக் காணப்படுகின்ற இந்த உடம்பில் உள்ள ஆறு அத்துவாக் -களும் உபாதிகளேயாம். அஃதாவது, அதனை மாசுபடுத்துகின்ற வேற்றுப் பொருள்களேயாம். அதனால், முப்பத்தாறு தத்துவங்களும் உயிர் தான் பெறுதற்குரிய மேலான ஒளியை அடைதற்குத் தூண்டு கின்ற சிறிய ஒளியாய் உதவுவதால், மாயையாலே உயிர் உறுதல், உயிர்த்தல், உண்டல் முதலியவைகளைச் செய்து, பின் அதிலிருந்து நீங்கியும் நிற்கும்.`,
  },
  {
    id: 2463, tantraId: 8, verseNumber: 2462,
    tamil: `தற்பரம் மன்னும் தனிமுதல் பேரொளி
சிற்பரம் தானே செகமுண்ணும் போதமும்
தொற்பதம் தீர்பாழில் சுந்தரச் சோதிபுக்கு
அப்புறம் மற்றதுஇங்கு ஒப்பில்லை தானே`,
    transliteration: `taṟparam maṉṉum taṉimutal pēroḷi
ciṟparam tāṉē cekamuṇṇum pōtamum
toṟpatam tīrpāḻil cuntarac cōtipukku
appuṟam maṟṟatuiṅku oppillai tāṉē`,
    english: `2462: Lord is Splendorous Light in the Void Beyond
The Primal Lord that is Tat-Para
Is Light Resplendent
He is Chit-Para, (Divine Jnana filled)
He is the Divine Sentience
That engrosses universe;
Enter in the Splendorous Light,
In the Void that is beyond words,
No more is there anything to compare.`,
    elaborationEnglish: ``,
    elaborationTamil: `'தத்' பதப் பொருளாகிய பதி, தன்னிலையில், நிலையான ஒப்பற்ற, முதன்மை வாய்ந்த பேரறிவே எனினும், அதுவே உயிர்களை நோக்கி இயங்கும் பொதுநிலையில் உயிர்களை உலகத்தை நுகரும்படி செய்கின்ற பாச அறிவாய் நிற்கும். ('திரோதான சத்தியாய் நிற்கும்' என்றாம். ) அந்தப் பாச அறிவால் உயிர் உலகத்தை நுகர்ந்து வருங்காலத்தில் அந்தப் பாச அறிவும், அதன் அறிவாகிய பசு அறிவும் நீங்கப் பெற்ற பொழுது, முன்சொன்ன பேரொளியிற்கலந்து, அதற்கு அப்பாலும்போய், முன்னை நிலையெல்லாம் நீங்கப்பெற்று நிற்கும். அப்பொழுது அதற்கு ஒத்ததும், உயர்ந்ததும் இல்லாத ஓர் உயர்வை அஃது அடையும்.`,
  },
  {
    id: 2464, tantraId: 8, verseNumber: 2463,
    tamil: `பண்டை மறைகள் பரவான் உடலென்னும்
துண்ட மதியோன் துரியாதீ தந்தன்னைக்
கண்டு பரனும்அக் காரணோ பாதிக்கே
மிண்டின் அவன்சுத்தம் ஆகான் வினவிலே`,
    transliteration: `paṇṭai maṟaikaḷ paravāṉ uṭaleṉṉum
tuṇṭa matiyōṉ turiyātī tantaṉṉaik
kaṇṭu paraṉumak kāraṇō pātikkē
miṇṭiṉ avaṉcuttam ākāṉ viṉavilē`,
    english: `2463: Risk to Suddha State Even in Turiyatita
The hoary scriptures say,
The expanding Space is His Body;
He wears the crescent moon;
Even after reaching the Turiyatita State,
If Jiva a victim to Causal Experiences (of Suddha Maya) falls.
He will Suddha (Pure) per se not be,
When you ask me.`,
    elaborationTamil: `முதல் நூல்களாகிய வேதாகமங்கள், சில இடங்களில் சுத்த மாயையை, 'சிவனுக்குத் திருமேனி' எனக் கூறும். அஃது உபசாரமே. 
[''சுத்ததத் துவம் சிவன்றன் சுதந்திர வடிவ மாகும்; 
நித்தம்என் றுரைப்பர் காலம் நீங்கிய நிலைமை யாலே''*
என்னும் சிவஞான சித்தியையும், அதன் உரையையும் காண்க.] ஏனெனில், சிவன் துரியத்தையும் கடந்து அதீதமூர்த்தி. (நின்மல துரியம் வரையிலே சுத்தமாயை உள்ளது) தத்துவசுத்தி, ஆன்மரூபம் ஆகியவற்றைக் கடந்து ஆன்ம தரிசனத்தைப் பெற்ற ஆன்மாவும் சிவ தரிசன சிவயோகங்களால் ஆன்ம சுத்தியை எய்தாது, காரணோபாதி யாகிய சுத்தமாயையில் இருப்பானாயின் அவனது நிலையை நன்கு ஆராயுமிடத்து அவன் தூய்மை எய்தியவன் ஆகான்.`,
  },
  {
    id: 2465, tantraId: 8, verseNumber: 2464,
    tamil: `வெளிகால் கனல்அப்பு மேவுமண் நின்ற
தனியா இயதற் பரங்காண் அவன்தான்
வெளிகால் கனல்அப்பு மேவுமண் நின்ற
வெளியாய சத்தி அவன்வடி வாமே`,
    transliteration: `veḷikāl kaṉalappu mēvumaṇ niṉṟa
taṉiyā iyataṟ paraṅkāṇ avaṉtāṉ
veḷikāl kaṉalappu mēvumaṇ niṉṟa
veḷiyāya catti avaṉvaṭi vāmē`,
    english: `2464: Pervasive Sakti is Pervasive Siva's Form
Space, air, fire, water and earth
He pervasive fills
He is Tat-Para of love infinite;
Sakti that is manifested
In space, air, fire, water and earth
Is but of His Form Divine.`,
    elaborationEnglish: ``,
    elaborationTamil: `'மாயா காரியமாகிய உலகப்பொருள் அனைத்திலுமே பரமசிவன் அருள் காரணமாக நிறைந்திருக்கின்றான்' என வேதாகமங்கள் கூறும். அவ்வாறு கூறுவதற்கும், 'அவனது சத்தியே அவ்வாறு நிறைந்துள்ளது' என்பதே கருத்து. பூதாகாயம் ஏனைப் பூதங்களில் எல்லாம் நிறைந்திருத்தல் போல அனைத்துலகங் களிலும் நிறைந்திருத்தல் பற்றி அச்சத்தி, 'பரவெளி - பராகாயம்' எனக் கூறப்படுகின்றது. அந்தச்சத்தியே, உண்மையில் பரமனுக்கு திருமேனியாகும்.`,
  },
  {
    id: 2466, tantraId: 8, verseNumber: 2465,
    tamil: `மேருவி னோடே விரிகதிர் மண்டலம்
ஆர நினையும் அருந்தவ யோகிக்குச்
சீரார் தவம்செய்யில் சிவனருள் தானாகும்
பேரவும் வேண்டாம் பிறிதில்லை தானே`,
    transliteration: `mēruvi ṉōṭē virikatir maṇṭalam
āra niṉaiyum aruntava yōkikkuc
cīrār tavamceyyil civaṉaruḷ tāṉākum
pēravum vēṇṭām piṟitillai tāṉē`,
    english: `2465: Contemplate in Yogic Way
To the Yogis of intense Tapas,
Contemplating on Mystic Meru Mount
In the radiant Sphere within,
In their rare Tapas
Siva's Grace, of itself, appears;
Move not from this way;
There is none other too.`,
    elaborationTamil: `இடைகலை பிங்கலைகளை, 'சந்திர சூரியர் வழி' எனக் கூறுதலால், அவ்வழியாக இயங்கும் பிராண வாயும் வலம் வரும் சுழுமுனை நாடியை, 'மகாமேரு' என்றலும், அந்தச் சுழுமுனை நாடியின் நடுப் பாகமாகிய அநாகத விசுத்தி ஆதாரங்களை, 'சூரிய மண்டலம்' என்றலும் யோக நூல் வழக்கு. அனாகதமாகிய இருதயம் பூசைத் தானமாகக் கொள்ளப்படும். அதனால், சுழுமுனை வழியாகச் சென்று இருதயத்தில் சிவபெருமானை நன்றாக நினைந்து வழிபடு பவனை, 'மேருவினோடே சென்று விரிகதிர் மண்டிலத்தில் (சிவனை) ஆரநினையும் அருந்தவயோகி' ('சென்று') என ஒரு சொல் வருவித்து, 'விரிகதிர் மண்டிலத்தில்' என உருபு விரித்து கொள்க.) ''செய்யின்'' என்பது 'செய்வதனால்' எனப் பொருள்தந்து நின்றது. ஆகவே, 'அந்த அருந்தவ யோகிக்குச் சிவனருள் தானாகவே கிடைக்கும்' என்றும், 'அவன் கைக்கொள்ள வேண்டிய சாதனம் வேறொன்றும் இல்லை யாகையால் அந்நெறியைவிட்டு அவன் விலகுதல் வேண்டா' என்றும் கூறினார்.`,
  },
  {
    id: 2467, tantraId: 8, verseNumber: 2466,
    tamil: `நனவாதி மூன்றினில் சீவ துரியம்
தனதுஆதி மூன்றினில் பரதுரி யந்தான்
நனவாதி மூன்றி னில்சிவ துரியமாம்
இனதாகும் தொந்தத் தசிபதத் துஈடே`,
    transliteration: `naṉavāti mūṉṟiṉil cīva turiyam
taṉatuāti mūṉṟiṉil paraturi yantāṉ
naṉavāti mūṉṟi ṉilciva turiyamām
iṉatākum tontat tacipatat tuīṭē`,
    english: `2466: Three Turiyas--Jiva, Para and Siva; and Their Respective
Reaches
Tvam Pada, Tat Pada and Asi Pada
The Turiya beyond (in Jagrat)
Waking, Dreaming and Deep Sleep States
Is Jiva Turiya;
The Turiya beyond
The Waking, Dreaming and Deep Sleep States (in the Jiva Turiya State)
In Para Turiya;
The Turiya further beyond (in the Para Turiya State)
Is Siva Turiya;
In these are reached
Tvam, Tat and Asi States respective.`,
    elaborationTamil: `[ஆன்மா, 'சீவன்' எனப்படுவது பாசநிலையில் ஆகலின், முதற்கண் சொல்லப்பட்ட நனவு, சகலத்தில் கேவலமாய் நிகழும். கீழாலவத்தையிலும், சகலத்தில் சகலமாய் நிகழும் மத்தியாலவத்தையிலும் நிகழும் நனவுகளாம்.] கீழாலவத்தையில் நிகழும் சாக்கிரம் முதலியவற்றில் நிகழும் துரியம் ஆணவ அனுபவம் மிகுவது ஆதலாலும், மத்தியாலத்தையில் நிகழும் சாக்கிரம் முதலிய வற்றில் நிகழும். துரியம் ஐம்புல அனுபவம் மிகுவது ஆதலாலும் அவையிரண்டும் சீவ துரியமாம். (இவை தொடக்கத்தில் நிகழ்வன. மேலாலவத்தையாகிய யோக துரியமும் சீவதுரியமே) இறுதியில் நிகழும் பராவத்தையில் நிகழும் சாக்கிரம் முதலியவற்றில் நிகழும் துரியத்தில் உயிர் பாசப்பற்று இன்றிப் பரம்பொருள் அனுபவமே மிகப் பெற்றிருத்தலால் அது பர துரியமாம். ('இஃது இலய முத்திநிலை' என்பது மேலே குறிப்பிடப்பட்டது.) இடையில் மத்தியாலவத்தைக்கு மேல் நிகழும் மேலாலவத்தையாகிய யோகாவத்தையில் நிகழும் சாக்கிரம் முதலியவற்றில் நிகழும் துரியமும், நின்மல சாக்கிரம் முதலியவற்றில் நிகழும் துரியமும் உலகியல் உணர்வு முற்ற நீங்காத நிலையில் சிவானுபவம் மிகப் பெறுவன ஆதலின் அவை பரதுரியம் ஆகாது சிவதுரியமாம். இவற்றுள் சிவதுரியமும், பர துரியமுமே 'தத்துவமசி' மகா வாக்கிய அனுபவங்களாம்.`,
  },
  {
    id: 2468, tantraId: 8, verseNumber: 2467,
    tamil: `தானாம் நனவில் துரியம்தன் தொம்பதம்
தானாம் துரியம் நனவாதி தான்மூன்றில்
ஆனாப் பரபதம் அற்றது அருநனா
வானான மேல்மூன்றில் துரியம் அணுகுமே`,
    transliteration: `tāṉām naṉavil turiyamtaṉ tompatam
tāṉām turiyam naṉavāti tāṉmūṉṟil
āṉāp parapatam aṟṟatu arunaṉā
vāṉāṉa mēlmūṉṟil turiyam aṇukumē`,
    english: `2467: States of Consciousness in the Three Turiyas
In Jiva Turiya of Waking State
Is Tvam-Pada;
The end of Jiva Turiya is the beginning of Para Turiya Jagrat;
At the end of Para Turiya
Is Para Pada (Tat-Pada)
Three steps beyond,
In the fourth, is Siva Turiya (Asi Pada).`,
    elaborationTamil: `சீவன் சீவனாகவே இருக்கின்ற மத்தியாலவத்தைச் சாக்கிரம் முதலியவற்றில் நிகழும் துரியத்தில் ஆன்மா, 'துவம்' பதப் பொருளாய் இருக்கும். ஆன்மாச் சிவமாந்தன்மையைப் பெறுகின்ற நின்மல சாக்கிரம், பராசாக்கிரம் முதலியவற்றில் நிகழ்கின்ற துரியங்களில் ஆன்மா சிவமாகி, 'தத்' பொருளாய் இருக்கும். ஆகவே, இவ்விரு துரியங்களிலும் ஆன்மாப் பாசம் அற்றதாம். சகலத்தில் கேவலத்திற்கு மேலாக நிகழும் மூன்று துரியங்களிலும் ஆன்மா இவ்வாறான நிலைகளை அடையும்.`,
  },
  {
    id: 2469, tantraId: 8, verseNumber: 2468,
    tamil: `அணுவின் துரியத்து நான்கும துஆகிப்
பணியும் பரதுரி யம்பயில் நான்கும்
தணிவில் பரமாகிச் சாரமுந் துரியக்
கணுவில் இந் நான்கும் கலந்தார் ஐந்தே`,
    transliteration: `aṇuviṉ turiyattu nāṉkuma tuākip
paṇiyum paraturi yampayil nāṉkum
taṇivil paramākic cāramun turiyak
kaṇuvil in nāṉkum kalantār aintē`,
    english: `2468: Ten States of Consciousness in All--In the Three Turiyas
The four states of Jiva Turiya
And the four states of Para Turiya
And the four states of Siva Turiya
As the end of one Turiya is the beginning state of next
They really are states Ten.`,
    elaborationEnglish: `S.Jiva turiya jagrat 6.Jiva turiya svapna 7.Jiva turiya sushupti 8.Jiva turiya turiya`,
    elaborationTamil: `பெத்த துரியம் அனைத்தையும் 'சீவ துரியம்' என ஒன்றாகவும் முத்தி துரியம் இரண்டையும் ஒன்றாகவும் ஆக்க. அவ்விரண்டிலும் துரியம் முதலாகக் கீழ் நோக்க உளவாம் அவத்தைகள் இருநான்கு; எட்டு. இனி இவ்விரண்டிலும் உள்ள துரியா தீதங்களைக் கூட்ட அவத்தைகள் பத்தாகும். இவைகளில் பெத்தா வத்தை ஐந்தில் ஆன்மாக்கீழ் நிலையதாயும், முத்தியவத்தை ஐந்தில் மேல்நிலையை எய்தியும் இருக்கும்.`,
  },
  {
    id: 2470, tantraId: 8, verseNumber: 2469,
    tamil: `ஈர்ஐந்து அவத்தை இசைமுத் துரியத்துள்
நேர்அந்த மாகநெறிவழி யேசென்று
பார்அந்த மான பராபத்து அயிக்கியத்து
ஓர்அந்த மாம்இரு பாதியைச் சேர்த்திடே`,
    transliteration: `īraintu avattai icaimut turiyattuḷ
nēranta mākaneṟivaḻi yēceṉṟu
pāranta māṉa parāpattu ayikkiyattu
ōranta māmiru pātiyaic cērttiṭē`,
    english: `2469: At the End of Ten is Union in Para Para
The Ten States are in the Turiyas
Three;
Them as Ends, you proceed;
At the Final End is identity with
Para Para
Connecting the States in the middle two each
(Jiva Turiya and Para Turiya Jagrat into one
And Para Turiya Turiya and Siva
Turiya Jagrat into one.)`,
    elaborationTamil: `கீழாலவத்தை ஐந்து, மத்தியாலவத்தை ஐந்து, மேலாலவத்தை ஐந்து இம் மூவைந்து பதினைந்தவத்தைகளை 'சீவாவத்தை' என ஓரைந்தாகவும், நின்மலாவத்தை ஐந்து, பராவத்தை ஐந்து இவ்வீரைந்தையும் 'பராவத்தை ஐந்து' என ஓரைந்தாகவும் தொகுக்க அவத்தைகள் ஈரைந்தாகி, 'சீவ துரியம், சிவ துரியம், பர துரியம்' என்னும் முத்துரியங்களும் அவற்றுள்ளே அடங்கும். அவ் அவத்தைகளை மேலாலவத்தைச் சாக்கிரம் முதலாகத் தொடங்கிப் படி முறையாக மேலே மேலே ஏறிச்சென்று, முடிவில் எல்லாமாய் உள்ள பரம்பொருளில் ஒன்று பட்டு, முடிந்த பயனைப் பெற்று, அதற்கு முன்னே நிகழ்ந்த யோக துரியம், நின்மல துரியம் ஆகிய இரண்டு உபாதிகளையும் பயனுடைய அவத்தைகளாகும் படி ஆக்கிக்கொள்க.`,
  },
  {
    id: 2471, tantraId: 8, verseNumber: 2470,
    tamil: `தொட்டே இருமின் துரிய நிலத்தினை
எட்டாது எனின்நின்று எட்டும் இறைவனைப்
பட்டாங்கு அறிந்திடில் பன்னா உதடுகள்
தட்டாது ஒழிவதோர் தத்துவந் தானே`,
    transliteration: `toṭṭē irumiṉ turiya nilattiṉai
eṭṭātu eṉiṉniṉṟu eṭṭum iṟaivaṉaip
paṭṭāṅku aṟintiṭil paṉṉā utaṭukaḷ
taṭṭātu oḻivatōr tattuvan tāṉē`,
    english: `2470: If You Cannot Reach Turiya Land, Persevere Still
Reach the Turiya Land, and be there;
If you cannot reach it
Think of Lord in the Way scriptures speak of,
You shall reach the Truth
That is beyond beyond words.`,
    elaborationTamil: `இறைவனை அறியுமாற்றால் அறியின், பல், நா, உதடுகள் இவைகளில் அகப்படாத ஒரு மெய்ப்பொருள் யாராலும் அணுக முடியாதாயினும் அணுக முடியும். ஆகையால், மெய்ப் பொருளை அடைய முயல்கின்றவர்களே, நீவிர் அதனை அடைதற் பொருட்டு துரிய நிலத்திலிருந்து கீழ் இறங்கிவிடாமல் இருங்கள்.`,
  },
  {
    id: 2472, tantraId: 8, verseNumber: 2471,
    tamil: `அறிவாய் அசத்தென்னும் ஆறாறு அகன்று
செறிவாய மாயை சிதைத்துஅரு ளாலே
பிறியாத பேரருள் ஆயிடும் பெற்றி
நெறியான அன்பர் நிலையறிந் தாரே`,
    transliteration: `aṟivāy acatteṉṉum āṟāṟu akaṉṟu
ceṟivāya māyai citaittuaru ḷālē
piṟiyāta pēraruḷ āyiṭum peṟṟi
neṟiyāṉa aṉpar nilaiyaṟin tārē`,
    english: `2471: The Holy Way
Become Knowledge;
Away with Tattvas six times six
That Asat (unreal) are;
Crush the crowding Maya
With Lord's Grace;
Then will be the Divine Grace abiding;
That way, the holy ones knew.`,
    elaborationTamil: `சடங்களாகிய முப்பத்தாறு தத்துவங்களையும் நீக்கும் முகத்தால், அடர்ந்துள்ள மாயையைப் போக்கிச்சித்தாய் நின்றுபின்னர் வெளிப்படுகின்ற திருவருளாலே அதுவேயாய் நிற்கின்ற தன்மையால் உயர் நெறியை அடைந்த அன்பர்களே சிவனது இயல்பை உண்மையாக உணர்ந்தோராவர்.`,
  },
  {
    id: 2473, tantraId: 8, verseNumber: 2472,
    tamil: `நனவின் நனவாகி நாலாம் துரியம்
தனதுயிர் தெம்பதம் ஆமாறு போல
வினையறு சீவன் நனவாதி யாகத்
தனைய பரதுரி யந்தற் பதமே`,
    transliteration: `naṉaviṉ naṉavāki nālām turiyam
taṉatuyir tempatam āmāṟu pōla
viṉaiyaṟu cīvaṉ naṉavāti yākat
taṉaiya paraturi yantaṟ patamē`,
    english: `2472: From Jiva Turiya to Para Turiya
The Fourth States of Jagrat
Is Turiya (Jiva Turiya);
There Jiva attains Tvam-Pada;
The Karmas end;
Again, commencing from Jiva Turiya
Is the Jagrat State in Para Turiya;
Reach Turiya in Para Turiya State,
There indeed is Tat-Pada State.`,
  },
  {
    id: 2474, tantraId: 8, verseNumber: 2473,
    tamil: `தொம்பதம் தற்பதம் சொன்முத் துரியம்பொல்
நம்பிய மூன்றாம் துரியத்து நல்நாமம்
அம்புலி யுன்னா அதிசூக்கம் அப்பாலைச்
செம்பொருள் ஆண்டருள் சீர்நந்தி தானே`,
    transliteration: `tompatam taṟpatam coṉmut turiyampol
nampiya mūṉṟām turiyattu nalnāmam
ampuli yuṉṉā aticūkkam appālaic
cemporuḷ āṇṭaruḷ cīrnanti tāṉē`,
    english: `2473: On to the Third Turiya
As you reached Tvam-Pada and Tat-Pada,
So now enter the third Turiya State (Siva Turiya)
At its end is the Divine Light (Asi-Pada)
The Super-Subtlety (Suksma) that words can conceive not;
Beyond is Siva
Who as Nandi accepted me into His Grace.`,
  },
  {
    id: 2475, tantraId: 8, verseNumber: 2474,
    tamil: `சீவன்தன் முத்தி அதீதம் பரமுத்தி
ஓய்உப சாந்தம் சிவமுத்தி ஆனந்தம்
மூவயின் முச்சொரூப முத்திமுப் பாலதாய்
ஓவுறு தாரத்தில் உள்ளும்நா தாந்தமே`,
    transliteration: `cīvaṉtaṉ mutti atītam paramutti
ōyupa cāntam civamutti āṉantam
mūvayiṉ muccorūpa muttimup pālatāy
ōvuṟu tārattil uḷḷumnā tāntamē`,
    english: `2474: The Three Muktis Are Direct Experiences With Siva-Form
Jiva-Mukti is the Atita (Beyond Consciousness State);
Para-Mukti is Upasanta (Divine Peace);
Siva-Mukti is Ananda (Divine Bliss);
All three are Svarupa Muktis
That from Nadanta branchs
Where Pranava (Aum) as letters Three (A,U,M) are.`,
    elaborationEnglish: ``,
    elaborationTamil: `மும்முத்திகளுள் முதலாவதாகிய சீவன் மும்முத்தி யாவது, உலகத்தில் இருப்பினும் உலகத்தைக் கடந்து நிற்கும் நிலையாம். எனவே, 'இஃது உடம்புள்ள பொழுதே நிகழ்வது' என்பது அறியப்படும். நின்மலாவத்தையில் சாக்கிரம் முதலியனவாம். மூன்றாவதாகிய பரமுத்தியாவது, உயிர் முன்பு இருந்த பாச நிலைகள் முற்றும் அற்று நிலையான அமைதியைப் பெறும் நிலையாகும். (ஆகவே, இஃது உடம்பு நீங்கிய பின்னர்ப் பெறப்படுவதால் விளங்கும். பிறர், 'விதேக முத்தி' என்பர். இந்நிலையில், 'சிவானந்தத்தை நாம் அனுபவிக்கின்றோம்' என்னும் உணர்வும் இன்றி, அந்த ஆனந்தத்துள் மூழ்கியிருக்கும் நிலையாதல் பற்றி இதனை, 'ஆனந்தாதீதம்' என்றும் கூறுவர். ஆனந்தாதீதம் ஆனந்தத்தில் ஆதீதம். இவ்வாறன்றி, உலக இன்பத்தில் தோயாது, சிவானந்தத்திலே தோய்தல் சிவமுத்தியாம். (எனவே நின்மலாவத்தையில் துரியாதீத நிலையாம்.) இவ்வாறு மூன்று நிலைகளில், உயிர் மூன்று தன்மைகளை உடையதாக, முத்தி மூன்று வகையாய் இருக்கும். இவற்றுள் சொல்லிறந்த முத்தியாகிய பரமுத்தியே நாதாந்த முத்தியாகக் கருதப்படும்.`,
  },
  {
    id: 2476, tantraId: 8, verseNumber: 2475,
    tamil: `ஆவது அறியார் உயிர்பிறப் பாலுறும்
ஆவது அறியும் உயிர்அருட் பாலுறும்
ஆவது ஒன்றில்லை அகம்புறத் தென்றுஅகன்று
ஓவு சிவனுடன் ஒன்றாதல் முத்தியே`,
    transliteration: `āvatu aṟiyār uyirpiṟap pāluṟum
āvatu aṟiyum uyiraruṭ pāluṟum
āvatu oṉṟillai akampuṟat teṉṟuakaṉṟu
ōvu civaṉuṭaṉ oṉṟātal muttiyē`,
    english: `2475: Mukti is the Goal of Being One With Siva
They know not the goal of birth,
The Jiva who knows it
Will in Grace be;
Nothing here to be in home or outside,
Thus renouncing all,
Be one with Siva
That verily is Mukti.`,
    elaborationTamil: `[''அறிவுடையார் ஆவ தறிவார்;'' அறிவிலார் - அஃதறிகல்லாதவர்''* என்றபடி, பின் வளைவதை முன் கூட்டிக் காரிய காரண இயைபு பற்றி உய்த்துணர்பவரே 'அறிவுடையார்' எனப் படுவார். அங்ஙனம் அறியமாட்டாதவர் அறிவிலார் ஆவர். அறிவால் இன்பம் வருதலும், அறியாமையால் துன்பம் வருதலும் நியதி. ஆகவே] பின் விளைவதை முன்கூட்டி அறிந்து வருமுன்னர்க் காத்துக் கொள்ளாத உயிர்கள் பிறப்பாகிய துன்பத்திலே வீழ்ந்திடும். பின் விளைவதை முன்கூட்டியே அறிந்து, 'வருமுன்னர்க் காத்துக் கொண்ட உயிர்கள் சிவனது திருவருளிலே சென்று பொருந்தும். 'சிவனாலன்றி உடம்பாலும், உலகத்தாலும் உயிர்கட்கு வருவதொன்றில்லை' என்பதை உணர்ந்து, அவனது அருளைப் பெற்று, அந்த அருளாலே அவனுடன் ஒன்றுபடுதலே முத்தியாகும்.`,
  },
  {
    id: 2477, tantraId: 8, verseNumber: 2476,
    tamil: `சிவமாகி மும்மலம் முக்குணம் செற்றுத்
தவமான மும்முத்தி தத்துவத்து அயிக்கியத்
துவம்ஆ கியநெறி சோகம்என் போர்க்குச்
சிவமாம் அமலன் சிறந்தனன் தானே`,
    transliteration: `civamāki mummalam mukkuṇam ceṟṟut
tavamāṉa mummutti tattuvattu ayikkiyat
tuvamā kiyaneṟi cōkameṉ pōrkkuc
civamām amalaṉ ciṟantaṉaṉ tāṉē`,
    english: `2476: Way of So-Ham
Siva Becoming,
The Malas triple perishing,
The Gunas triple perishing,
The Muktis triple attaining,
One with Tattvas uniting
That the way of "So-ham" is;
Unto those who follow this Way
The Immaculate Siva Himself reveals.`,
  },
  {
    id: 2478, tantraId: 8, verseNumber: 2477,
    tamil: `சித்தியும் முத்தியும் திண்சிவ மாகிய
சுத்தியும் முத்தீ தொலைக்கும் சுகானந்த
சத்தியும் மேலைச் சமாதியும் ஆயிடும்
பெத்தம் அறுத்த பெரும்பெரு மானே`,
    transliteration: `cittiyum muttiyum tiṇciva mākiya
cuttiyum muttī tolaikkum cukāṉanta
cattiyum mēlaic camātiyum āyiṭum
pettam aṟutta perumperu māṉē`,
    english: `2477: All Attainments, Work of Lord
Lord
Siddhi and Mukti,
And Suddhi that is Siva Pure,
And Sakti of Pure Bliss,
That extinguishes the Fires Three;
And the Samadhi Exalted
--All these the work of Divine Lord
Who thine bonds sunders.`,
    elaborationTamil: `பக்குவான்மாக்கட்குப் பாசத்தை அறுத்துத் தன்னையே அளிப்பதாகிய சித்தாந்த முத்தியைத் தருகின்ற, பெரிய பெருமானாகிய (மகாதேவனாகிய) சிவனே ஏனையோர்கட்கு அவரவர்களது தகுதிக்கு ஏற்ப, பொது யோகிகள் விழைகின்ற அணிமாதி அட்ட மாசித்தியாகிய பயனையும், ஏனைச் சமயத்தார் தாம் தாம் 'முத்தி' எனக் கொண்டு விழைகின்ற பல்வேறு பயன்களையும், அகப்புற, அகச்சமயிகள் விழையும் பொதுநிலைச் சிவபதமாகிய பயனையும், இப்பயனுக்கு எதிராய் உள்ள 'தாபத் திரயம்' எனப்படும் மூவகைத் துன்பங்களைப் போக்கிக் கொள்கின்ற ஆற்றலையும், சிவயோகிகள் விரும்புகின்ற அந்தமேலான சமாதியாகிய சீவன் முத்தியையும் தருபவனாவான்.`,
  },
  {
    id: 2479, tantraId: 8, verseNumber: 2478,
    tamil: `ஏறிய வாறே மலம்ஐந் திடைஅடைந்து
ஆறிய ஞானச் சிவோகம் அடைந்திட்டு
வேறும் எனமுச் சொரூபத்து வீடுற்று அங்கு
ஈறதில் பண்டைப் பரன்உண்மை செய்யுமே`,
    transliteration: `ēṟiya vāṟē malamain tiṭaiaṭaintu
āṟiya ñāṉac civōkam aṭaintiṭṭu
vēṟum eṉamuc corūpattu vīṭuṟṟu aṅku
īṟatil paṇṭaip paraṉuṇmai ceyyumē`,
    english: `2478: Beyond Triple Muktis is God
As you ascend,
Attenuate Malas Five
And espouse "So-ham"
That is Jnana filled;
And be liberated
Attaining Svarupa Mukti triple;
And in the End,
Vision Truth of Para (Siva) Eternal.`,
    elaborationTamil: `பெத்தம் தடத்தமாக, முத்தியே சொரூபம் ஆதலின், முன் அதிகாரத்தில் கூறிய மும்முத்திகளையே இவ்வதிகாரத்தில் 'முச்சொரூபம்' என ஏழு மந்திரங்களால் வேறொரு வகையாக விளக்குகின்றார். 'பெத்தம் தடத்தமே, முத்தியே சொரூபம்' என உணர்தலே இவ்வதிகாரத்தின் பயன். (தடத்தம் - செயற்கை, சொரூபம் - இயற்கை.)
'ஆணவம், திரோதாயி, மாயை, மாயேயம், கன்மம்' என இவ்வாறு ஐந்து மலங்களும் ஆன்மாவை வந்து பற்றி, ஒன்று, இரண்டு, மூன்று', என இவ்வாறு தொகை மிகுந்த முறையிலே அவற்றினின்றும் ஒவ்வொன்றாக நீங்கி, முழுதும் விடுபட்ட ஆன்ம ஞானம், பின் 'சிவோகமஸ்மி' என்னும் அனுபவத்தைப் பெற்று, அதற்குப் பின்னும் மேலே மேலே சென்று முச்சொரூபமாகிய மும்முத்திகளைப் பெற்று, முடிவில் அநாதியான சொரூப சிவனை அடைந்து நலம் பெறும்.`,
  },
  {
    id: 2480, tantraId: 8, verseNumber: 2479,
    tamil: `மூன்றுள மாளிகை மூவர் இருப்பிடம்
மூன்றினில் முப்பத் தாறும் உதிப்புள
மூன்றினின் உள்ளே முளைத்தெழும் சோதியைக்
காண்டலும் காயக் கணக்கற்ற வாறே`,
    transliteration: `mūṉṟuḷa māḷikai mūvar iruppiṭam
mūṉṟiṉil muppat tāṟum utippuḷa
mūṉṟiṉiṉ uḷḷē muḷaitteḻum cōtiyaik
kāṇṭalum kāyak kaṇakkaṟṟa vāṟē`,
    english: `2479: Light in the Three Mansions
Three the Mansions
Three that reside there
In the Three merge the thirty-six (Tattvas)
The Light that rises from within the Three
May well the Jiva vision;
Then ended will birth's cycle be
That endless was.`,
    elaborationTamil: `'சகலர், பிரளயாகலர், விஞ்ஞானகலர்' என்னும் மூவகை உயிர்களுக்கும் மூன்றுவகையான மாளிகை போன்ற, 'பிராகிருத சரீரம், மாயேய சரீரம், வைந்தவ சரீரம்' என்னும் மூன்று வகையான உடம்புகள் இருப்பிடமாய் உள்ளன. அந்த மூன்று வகை உடம்புகட்குள்ளேதான் தத்துவங்களும் உள்ளன. அவ்வுடம்புகளில் ஒவ்வொன்றிலுமே 'ஆன்மா,சிவம், பரம்' என்னும் மூன்று ஒளிப்பொருள்களும் வெளிப்படுகின்றன. அவ்வொளிகளை நேரே உணரும் வாய்ப்பு உளதாயின், அதன்பின் மேற்கூறிய உடம்புகளுக் குள்ளே உயிர் இருக்க வேண்டிய விதி இல்லையாய்விடும்.`,
  },
  {
    id: 2481, tantraId: 8, verseNumber: 2480,
    tamil: `உலகம் புடைபெயர்ந்து ஊழியம் போன
நிலவு சுடரொளி மூன்றும் ஒன்றாய
பலவும் பரிசொடு பான்மையுள் ஈசன்
அளவும் பெருமையும் ஆரறி வாரே`,
    transliteration: `ulakam puṭaipeyarntu ūḻiyam pōṉa
nilavu cuṭaroḷi mūṉṟum oṉṟāya
palavum paricoṭu pāṉmaiyuḷ īcaṉ
aḷavum perumaiyum āraṟi vārē`,
    english: `2480: Lord's Vastness
The worlds tumbled,
The aeons passed,
The three Lights,
Sun, Moon and Fire
One became;
All in Benevolent Lord merged;
Who knows His vastness and greatness!`,
    elaborationEnglish: ``,
    elaborationTamil: `உலகங்கள் எல்லாம் ஒடுக்க நிலையை எய்தி விட்டன. அதனால், உலகம் உள்ளளவும் இருந்த அந்த ஊழியும் போய், அடுத்த ஊழி வரும் நிலைமை தோன்றி விட்டது, உலகம் உள்ள பொழுது விளங்கிக்கொண்டிருந்த, 'ஞாயிறு, திங்கள் தீ' என்னும் முச்சுடர்களும் காரண நிலையில் ஒன்றாகி விட்டன. இவை போல எல்லாப் பொருள்களும் தம் தம் காரண நிலைகளை எய்தி விட்டன. ஆயினும் பரமசிவன் முன் இருந்தவாறே இருக்கின்றான் என்றால், அவனது நீளத்தின் எல்லையையும், அகலத்தின் எல்லையையும் யார் அறிய வல்லார்!`,
  },
  {
    id: 2482, tantraId: 8, verseNumber: 2481,
    tamil: `பெருவாய் முதலெண்ணும் பேதமே பேதித்து
அருவாய் உருவாய் அருவுரு வாகிக்
குருவாய் வரும்சத்தி கோன்உயிர்ப் பன்மை
உருவாய் உடனிருந்து ஒன்றாய்அன் றாமே`,
    transliteration: `peruvāy mutaleṇṇum pētamē pētittu
aruvāy uruvāy aruvuru vākik
kuruvāy varumcatti kōṉuyirp paṉmai
uruvāy uṭaṉiruntu oṉṟāyaṉ ṟāmē`,
    english: `2481: God's Multiple Forms
The Primal One, the indivisible
Great
Himself into several divided;
As Form, Formless and
Form-Formless,
And as Guru, and as Sakti-Lord
In Forms numerous
He immanent in Jivas became
And transcendent too.`,
    elaborationTamil: `மகா மாயையை முதலாக வைத்து எண்ணுகின்ற காரணங்களையும், அவற்றின் காரியங்களையும் வேறு வேறு வகைபடத் தோற்றுவித்து, அவற்றை அங்ஙனம் செய்தற்கு ஏற்ற 'அருவம், உருவம், அருவுருவம்' என்னும் மூவகைத் திருமேனிகளைக் கொண்டு, மூவகை நிலையில் நின்று, முடிவில் குருவாகியும் வந்து ஆட்கொள்கின்ற அருளாளனாகிய சிவன், அளவில்லாத உயிர்களிலும் அவ்வவற் -றோடும் சேர்ந்து உயிர்க்கு உயிராதல் தன்மையால் உடனாயும், கலப்பினால் ஒன்றாயும், பொருள் தன்மையால் வேறாயும் உள்ளான்.`,
  },
  {
    id: 2483, tantraId: 8, verseNumber: 2482,
    tamil: `மணிஒளி சோபை இலக்கணம் வாய்த்து
மணிஎன வாய்நின்ற வாறுஅது போலத்
தணிமுச் சொருபாதி சத்தியாதி சாரப்
பணிவித்த பேர்நந்தி பாதம்பற்றாயே`,
    transliteration: `maṇioḷi cōpai ilakkaṇam vāyttu
maṇieṉa vāyniṉṟa vāṟuatu pōlat
taṇimuc corupāti cattiyāti cārap
paṇivitta pērnanti pātampaṟṟāyē`,
    english: `2482: Jiva Shines in Triple Mukti
In Triple Mukti Jiva receives Light Divine
With light and brillance infused,
The crystal as a gem shines;
Unto it is Jiva
When he attains Muktis Three
And Grace of Sakti Divine;
Hold to the Feet of Nandi
Who all these Graces ordained.`,
    elaborationTamil: `இரத்தினங்கள் நிறம், ஒளி, வடிவம் என்பவற்றைப் பெற்றுப் பல அணிகலங்களாய் நிற்கும் முறைமை போலத் தான் 'பரம், சிவம், ஆன்மா' என்னும் முச்சொரூபத்தை யுடையதாகி அந் நிலைகளில் தனது சத்தியால் சீவனும் அடங்கித் தோன்றும்படி செய்த, 'நந்தி' என்னும் பெயரையுடைய அந்த முதல்வனது திருவடிகளையே பற்றாகப் பற்றி உய்வாயாக.`,
  },
  {
    id: 2484, tantraId: 8, verseNumber: 2483,
    tamil: `கல்லொளி மாநிறம் சோபை கதிர்தட்ட
நல்ல மணியொன்றின் நாடிஒண் முப்பதும்
சொல்லறும் முப்பாழில் சொல்லறு பேருரைத்து
அல்அறும் முத்திராந் தத்துஅனு பூதியே`,
    transliteration: `kalloḷi māniṟam cōpai katirtaṭṭa
nalla maṇiyoṉṟiṉ nāṭioṇ muppatum
collaṟum muppāḻil collaṟu pēruraittu
alaṟum muttirān tattuaṉu pūtiyē`,
    english: `2483: Beyond Triple Mukti is Mudra of Jnana
With crystalline hue and radiant brilliance,
The Lord stands as a gem of purest ray serene;
Seek Him and reach the Mukti State Three;
Beyond is Void that defies speech,
There contemplate on Aum in Silentness
In that Mudra of Jnana
The final Grace is.`,
    elaborationTamil: `பிற மணிகளில் ''ஒளி'' என்றும், 'நிறம்' என்றும் 'சோபை' என்றும் இங்ஙனம் பல பெயர்களால் சொல்லப்பட்டு விளங்குகின்ற கதிர்கள் ஒரு படிக மணியிலே பொருந்த, அப்படிக மணிவேறு பல மணிகளாய்க் காட்சியளிப்பது போன்றதே 'தத்துமசி' மகாவாக்கியத்தால் உபதேசிக்கப்படும் பொருள். அஃதாவது, 'உயிர் சார்ந்ததன் வண்ணமாம் இயல்புடையது ஆதலின், பாசத்தைச் சார்ந்து பாசமாய் இருந்த நீ, அந்நிலை நீங்கிச் சிவத்தைச் சார்ந்து சிவம் ஆகிறாய்' என்பதாம். (சீவன் பாசமாய் இருந்த நிலை சொல்லால் சொல்லப்படும். அஃது அந்நிலையினின்றும் நீங்கிச் சிவமாகிய நிலை) சொல்லால் சொல்ல வாராது, முத்தி பஞ்சக்கரமும் மொழியாய் இராது அனுபவமான ஒளி நிலையாகும். இது முப்பாழும் கடந்த நிலையும், குரு பஞ்சாக்கரத்தை உபதேசித்து, சின்முத்திரையால் அஞ் ஞானத்தைப் போக்கி, மெய்ஞ்ஞானத்தை உணர்த்திய முடிந்த நிலையும் ஆகும்.`,
  },
  {
    id: 2485, tantraId: 8, verseNumber: 2484,
    tamil: `உடந்தசெந் தாமரை உள்ளுறு சோதி
நடந்தசெந் தாமரை நாதம் தகைந்தால்
அடைந்த பயோதரி அட்டி அடைத்தஅவ்
விடம்தரு வாசலை மேல்திற வீரே`,
    transliteration: `uṭantacen tāmarai uḷḷuṟu cōti
naṭantacen tāmarai nātam takaintāl
aṭainta payōtari aṭṭi aṭaittaav
viṭamtaru vācalai mēltiṟa vīrē`,
    english: `2484: Kundalini Yoga
He is the Light within the heart's crimson lotus;
If the Crimson Lotus within, Nada you reached,
You shall wake Kundalini Sakti;
And closing Muladhara where She imprisoned is,
Ascend upward (through Sushumna in Yogic breathing)
And open wide the gate above at cranium top.`,
    elaborationTamil: `வரிசையாய் அமைந்துள்ள செந்தாமரை மலர்களின் பல்வேறு வகையாய்க் காட்சியளிக்கின்ற இறைவனை மூலாதாரத்தி னின்றும் எழுந்து மேல்நோக்கி நடக்கின்ற அனல் நாதாந்தத்திலே நிறுத்திக்காட்ட, அதனால், அவ்விடத்தை அடைந்த பால் ஒழுகும் தனங்களையுடைய பெருமாட்டி அடைத்து வைத்திருக்கின்ற விசாலமான மேல் வாசலைத் திறக்கும் உபாயம் அறிந்து திறவுங்கள்.`,
  },
  {
    id: 2486, tantraId: 8, verseNumber: 2485,
    tamil: `இடனொரு மூன்றில் இயைந்த ஒருவன்
கடன் உறும் அவ்வுரு வேறெனக்காணும்
திடமது போலச் சிவபர சீவர்
உடனுரை பேதமும் ஒன்றென லாமே`,
    transliteration: `iṭaṉoru mūṉṟil iyainta oruvaṉ
kaṭaṉ uṟum avvuru vēṟeṉakkāṇum
tiṭamatu pōlac civapara cīvar
uṭaṉurai pētamum oṉṟeṉa lāmē`,
    english: `2485: Jiva, Para and Siva Are One in Three Places
Yet may be as three different appear;
Unto this
Are Jiva, Para and Siva;
One are they
But in different places appear.`,
    elaborationTamil: `உயிர் சகலாவத்தையில் தத்துவங்களோடு கூடி 'சீவான்மா' எனப் பெயர் பெற்று நிற்பினும் அது தத்துவங்களின் வேறாதல்போல்வதும், நின்மலாவத்தையில் தத்துவங்களின் நீங்கி வாக்குகளின் வடிவாய் நிற்குமிடத்து 'அந்தரான்மா' எனப்பெயர் பெற்று நிற்பினும் அது வாக்குகளின் வேறாதல் போல்வதும் பரா வத்தையில் பரத்தோடு கூடிப் பரான்மா எனப் பெயர் பெற்று நிற்பினும் அது பரத்தின் வேறாதல் போல்வதுந்தாம். பரம் பொருள் சீவான் மாவில் நிறைந்து 'சிவம்' என நிற்பினும் அது சிவனின் வேறாதலும், பரான்மாவில் நிறைந்து 'பரம்' என நிற்பினும் அது பரான்மாவின் வேறாதலும்.`,
  },
  {
    id: 2487, tantraId: 8, verseNumber: 2486,
    tamil: `ஒளியைஒளிசெய்து ஓம்என்று எழுப்பி
வளியை வளிசெய்து வாய்த்திட வாங்கி
வெளியை வெளிசெய்து மேலெழ வைத்துத்
தெளியத் தெளியும் சிவபதம் தானே`,
    transliteration: `oḷiyaioḷiceytu ōmeṉṟu eḻuppi
vaḷiyai vaḷiceytu vāyttiṭa vāṅki
veḷiyai veḷiceytu mēleḻa vaittut
teḷiyat teḷiyum civapatam tāṉē`,
    english: `2486: How to Reach Siva State
Brighten the light within
To merge in the Light (without);
Through Sound potency in "Aum"
Rouse Prana breath within
To merge in the breath without (Cosmic Life);
Coursing it appropriate upward,
Merge the space within into Space without;
Clear shall you the Siva-State vision.`,
    elaborationTamil: `பொருள்களை மாறாக உணரும் மயக்கத்தை நீக்கி உள்ளவாறுணரும் தெளிவைத் தருதலால் குண்டலி சத்தி ஒளியெனத் தக்கது. அதனை உலகர் இருளாக்கி வைத்துள்ளனர். அவ்வாறில்லாது அதனை ஒளியாகவே விளங்கும்படிச் செய்தல் வேண்டும். அது பிராணாயாமத்தால் மூலாக்கினியை எழுப்புதலால் உண்டாகும். அஃது உண்டாகும் பொழுதுதான் 'வெறுங் காற்று' எனப்படுகின்ற மூச்சு சூரிய சந்திர கலைகளாம் சிறப்பு வளியாகும். அதனை அவ்வாறு செய்து, பயன் கிட்டும்படி கும்பகத்தால் சேமித்து, அதனானே சுழு முனை வழி வழியாயில்லாமல் அடைத்தும், உச்சியில் அருள் ஞானம் விளங்குகின்ற இடம் இடமாய் இல்லாமல் பாழ்படுத்தியும் வைத்திருக்கின்ற நிலையை மாற்றி வழியாகவும், இடமாகவும் செய்து குண்டலியை 'ஓம்' என்று எழுப்பி மேற்போய் உலாவச் செய்து தெளி வுணர்வைப் பெற்றால், சிவ சீவர்களது உண்மை நிலை விளங்கும்.`,
  },
  {
    id: 2488, tantraId: 8, verseNumber: 2487,
    tamil: `முக்கர ணங்களின் மூர்ச்சைதீர்த்து ஆவதுஅக்
கைக்கா ரணம் என்னத் தந்தனன் காண்நந்தி
மிக்க மனோன்மணி வேறே தனித்துஏக
ஒக்குமது உன்மணி ஓதுஉள் சமாதியே`,
    transliteration: `mukkara ṇaṅkaḷiṉ mūrccaitīrttu āvatuak
kaikkā raṇam eṉṉat tantaṉaṉ kāṇnanti
mikka maṉōṉmaṇi vēṟē taṉittuēka
okkumatu uṉmaṇi ōtuuḷ camātiyē`,
    english: `2487: Unmai Sakti Takes Over
He ended the pulsations of Karanas
By a sleight of hand, as it were--My Nandi
As the lovely Manonmani (Sakti) left,
Unmani (Sakti) no less lovely entered,
Do take to Her in Samadhi inward.`,
    elaborationTamil: `ஆறாதாரங்களில் மணிபூரகம், அனாகதம் ஆஞ்ஞை என்னும் மூன்று ஆதாரங்கள் சிறப்புடையன. சுவாதிட்டத் தினின்றும் எழுகின்ற பிராணன் 'உதானன்' எனப் பெயர் பெற்று மேலோங்கி இவ்விடங்களில் சென்று ஆஞ்ஞையில் முடியும். அவ்வாறு முடியும்படி அதனை முடித்த பின்பு அவ்வாறு முடித்ததனால் உண்டாகும் பயனைக் கைம்மேற் பலனாக எமக்கு எம் ஆசிரியர் நந்தி பெருமான் அளித்தருளினார். அப்பயன் தான் யாதெனில், ஆஞ்ஞையில் விளங்கிய மனோன்மணி சத்தி அதற்கு மேலே வியாபினி சமனை உன்மனைகளாய்ச் செல்ல, உன்மனாந்தத்தில் சிவத்தோடு ஒன்றும் சமாதி நிலையாம்.`,
  },
  {
    id: 2489, tantraId: 8, verseNumber: 2488,
    tamil: `தற்பதம் தொம்பதம் தானாம் அசிபதம்
தொல்பதம் மூன்றும் துரியத்துத் தோற்றலே
நிற்பது உயிர்பரன் நிகழ்சிவ மும்மூன்றின்
சொற்பத மாகும் தொந்தத் தசியே`,
    transliteration: `taṟpatam tompatam tāṉām acipatam
tolpatam mūṉṟum turiyattut tōṟṟalē
niṟpatu uyirparaṉ nikaḻciva mummūṉṟiṉ
coṟpata mākum tontat taciyē`,
    english: `2488: Tvam-Tat-Asi
Tvam-Pada, Tat-Pada and Asi-Pada
All three states in Turiya arose;
In all three states one of Three stands
--Jiva, Para and Siva in order respective--
Together are they known
By the expression compounded,
That is, Tvam-Tat-Asi (Maha Vakiyam).`,
    elaborationTamil: `துவம் தத், அசி, என்னும் மூன்று சொற்கள் தொன்மை -யான வேதத்தில் சொல்லப்பட்டனவாகும். இவை உலகியலில் தோன்றுதல் போலாது யோக துரியம். நின்மலதுரியம், பரதுரியம் ஆகிய முத்துரியங்களில் உணர்வின்கண் தோன்றும் பொழுது அவை முறையே சீவ அறுதியும், பர அறுதியும், சிவ அறுதியுமாய் நிற்கும்.`,
  },
  {
    id: 2490, tantraId: 8, verseNumber: 2489,
    tamil: `தொந்தத் தசிமூன்றில் தொல்கா மியமாதி
தொந்தத் தசிமூன்றில் தொல்கா மதமாதி
வந்த மலம்குணம் மாளச் சிவம்தோன்றின்
இந்துவின் முன்இருள் ஏகுதல் ஒக்குமே`,
    transliteration: `tontat tacimūṉṟil tolkā miyamāti
tontat tacimūṉṟil tolkā matamāti
vanta malamkuṇam māḷac civamtōṉṟiṉ
intuviṉ muṉiruḷ ēkutal okkumē`,
    english: `2489: Siva Appears Beyond Tvam-Tat-Asi
In the Three States Tvam Tat and Asi
Are the time-honored Malas Three--Kamiya and the rest
In the Three States Tvam Tat and Asi
Are the time-honored Gunas Three--Tamas and the rest
When these Malas and Gunas are seared,
Siva appears;
And as He appears, they fleet away,
As does darkness before moon's beam.`,
    elaborationTamil: `முன் மந்திரத்தில் கூறிய மூன்று அறுதிகளுள் தொம்பத அறுதியில் (சீவ அறுதியில்) மாயா - மலமும், தற்பத அறுதியில் பர அறுதியில்) ஆணவ மலமும், அசிபத அறுதியில் (சிவ அறுதியில்) கன்ம மலமும் நீங்கும். அவ்வாறே அம்மூன்று அறுதிகளிலும் முறையே இராசதம், சாத்துவீகம் தாமதம் என்னும் குறைகள் நீங்கும். இவ்வாறு மூவறுதியில் மும்மலங்களும், முக்குணங் களும் நீங்குதல் நிலாவின் முன் இருள் நீங்குதலை ஒக்கும்.`,
  },
  {
    id: 2491, tantraId: 8, verseNumber: 2490,
    tamil: `தொந்தத் தசியைஅவ் வாசியில் தோற்றியே
அந்த முறைஈர் ஐந்தாக மதித்திட்டு
அந்தம் இல்லாத அவத்தைஅவ் வாக்கியத்து
உந்து முறையில் சிவன்முன்வைத்து ஓதிடே`,
    transliteration: `tontat taciyaiav vāciyil tōṟṟiyē
anta muṟaiīr aintāka matittiṭṭu
antam illāta avattaiav vākkiyattu
untu muṟaiyil civaṉmuṉvaittu ōtiṭē`,
    english: `2490: Tvam-Tat-Asi Becomes Tat-Tvam-Asi
Attain the State of Tvam-Tat-Asi
Through coursing breath (in Yogic Way)
Consider it as the Tenth State of (Turiya) experience;
Endless is that Experience;
Alter that expression so
That Siva (Tat) stands first
(That is Tat-Tvam-Asi, or Tatvamasi)
Thus meditate on it and ascend.`,
    elaborationTamil: `'தொம், தத், அசி' என்னும் மூன்று பதங்களையும் முத்தி பஞ்சாக்கர மூன்றெழுத்துக்களில் முறையே யகார சிகார வகாரங் -களில் வைத்து அந்த முறையிற்றானே தூல பஞ்சாக்கரம் ஐந்தும், சூக்கும பஞ்சாக்கரம் ஐந்தும் அடங்கியிருப்பதாகக் கொண்டு அதனையே அழிவில்லாத யோகாவத்தை நின்மலாவத்தை பராவத்தைகளில் 'தொந்ததசி' வாக்கியமாகச் சிகார வகாரங்களை முன் வைத்து உச்சரி.`,
  },
  {
    id: 2492, tantraId: 8, verseNumber: 2491,
    tamil: `வைத்துச் சிவத்தை மதிசொரு பானந்தத்து
உய்த்துப் பிரணவ மாம்உப தேசத்தை
மெய்த்த இதயத்து விட்டிடு மெய்யுணர்ந்து
அத்தற்கு அடிமை அடைந்துநின் றானே`,
    transliteration: `vaittuc civattai maticoru pāṉantattu
uyttup piraṇava māmupa tēcattai
meytta itayattu viṭṭiṭu meyyuṇarntu
attaṟku aṭimai aṭaintuniṉ ṟāṉē`,
    english: `2491: As Tatvamasi, Practise Yoga
Thus altering the expression
Into Tatvamasi with Siva (Tat) first
Fix your thought on bliss of Svarupa;
And gently hold to your heart
The Pranava mantra (that is "Aum");
When Jiva thus practises Yoga
He realizes Truth
And stands, in Grace accepted.`,
    elaborationTamil: `முன் மந்திரத்திற் கூறியவாறு முத்தி பஞ்சாக்கரத்தை சிவ முன்னாக வைத்து உணர்வைப் பர சொரூபமாகிய ஆனந்த நிலையிற் செலுத்தி அதனோடே பிரணவமாகிய அந்த உபதேச மந்திரத் -தையும் அவ்வாறே உள்ளத்தில் சேர்ப்பி, சேர்ப்பித்தால், அப்பொழுதே நீ மெய்யுணர்வைப் பெற்றுச் சிவனுக்கு அடிமையாகி விடுவை.`,
  },
  {
    id: 2493, tantraId: 8, verseNumber: 2492,
    tamil: `தொம்பதம் மாயையுள் தோன்றிடும் தற்பதம்
அம்புரை தன்னில் உதிக்கும் அசிபதம்
நம்புறு சாந்தியில் நண்ணும்அவ் வாக்கியம்
உம்பர் உரைதொந்தத் தசிவாசி யாமே`,
    transliteration: `tompatam māyaiyuḷ tōṉṟiṭum taṟpatam
ampurai taṉṉil utikkum acipatam
nampuṟu cāntiyil naṇṇumav vākkiyam
umpar uraitontat tacivāci yāmē`,
    english: `2492: Thom-Tat-Asi is Celestisl Vakya
Tvam-Pada arises in Maya (Sakti)
Tat-Pada in comely Parai (Sakti)
Asi-Pada leads to Santhi (Kala)
That Vakya (expression) is verily of Celestials,
Thom-Tat-Asi by Yogic breathing attained.`,
    elaborationEnglish: ``,
    elaborationTamil: `'தத்துவமசி' மகாவாக்கியத்தில் 'துவம்' பதப்பொரு ளாகிய சீவன் உயிர் தத்துவங்களையே 'தான்' என மயங்கும் மயக்கம் மாயையால் தோன்றுவதாகும். தற்பதப் பொருளாகிய பதி ஐந்தொழில் செய்தற் பொருட்டுப் பரா சத்தியினின்றும் சிவமாகித் தோன்றும் சீவன் சிவமாதலைத் தெரிவிப்பதாகிய 'அசி' பதப்பொருள் உயிர் அனைத்துப் பாசங்களினின்றும் நீங்கித் தூயதாய நிலையில் தோன்றும். இனி, 'தத்துவமசி' மகா வாக்கியத்தில் உள்ள 'அசி, தத், துவம்' என்னும் முப்பதங்களும் முத்தி பஞ்சாக்கரத்தில் முறையே 'வா,சி,ய' மூன்றெழுத்துக்களில் அடங்கும்.`,
  },
  {
    id: 2494, tantraId: 8, verseNumber: 2493,
    tamil: `ஆகிய அச்சோயம் தேவதத் தன்இடத்து
ஆகிய வைவிட்டால் காயம் உபாதானம்
ஏகிய தொந்தத் தசியென்ப மெய்யறிவு
ஆகிய சீவன் பரசிவன் ஆமே`,
    transliteration: `ākiya accōyam tēvatat taṉiṭattu
ākiya vaiviṭṭāl kāyam upātāṉam
ēkiya tontat taciyeṉpa meyyaṟivu
ākiya cīvaṉ paracivaṉ āmē`,
    english: `2493: Jiva in Different Places and Times
Deva Datta is one and same person;
But through time and place he different appears;
Unto it,
If Jiva transcends time and place,
He and Siva one becomes (So-ham)
In Thom-Tat-Asi,
Jiva in body one with Primal Cause is;
Attaining True Jnana
Jiva becomes Para Siva.`,
    elaborationEnglish: `Datta is a fictional name used in Vedanta literature. Here the name is used to illustrate how the individual remains the same, though time and place states may differ. Deva Datta was a bachelor in Benares, a householder in Chidambaram, and a sannyasin in Madurai — all one and the same person in different places.`,
    elaborationTamil: `'சோயம் தேவதத்தன்' என்பது 'தேவதத்தனாகிய அவனே இவன்' என்பது இதன் பொருள். ஒரு வடமொழி உதாரணம். இதன் விளக்கம் இல்லற நிலையில் அதற்குரிய கோலமும், உடையும், பெயருமுடையவனாய் இருந்த ஒருவன் அவற்றையெல்லாம் விடுத்துத் துறவியாகி, அதற்குரிய கோலம், தண்டு கமண்டலம், வேறு பெயர் ஆகியவற்றைக் கொண்டால், 'அவன்' எனப்பட்ட நிலையில் அவனிடம் இருந்த சேர்க்கைப் பொருள்களையெல்லாம் விடுத்து, அவற்றை உடையவனாய் இருந்த அவனை மட்டுமே கொண்டு, 'இவன்' எனச் சுட்டுதல் போல்வதே 'சீவன் சிவமாகிறது' என்றலும் - என்பது அஃதாவது பசுத்துவத்தால் 'சீவன்' எனப்படுகின்ற உயிர் அப்பசுதுவத்தின் நீங்கித் தூயதாகிய நடுநிலையிலேதான் சிவனைச் சார்ந்து சிவமாகின்றது என்பதாம்.`,
  },
  {
    id: 2495, tantraId: 8, verseNumber: 2494,
    tamil: `தாமதம் காமியம் ஆசித் தகுணம்
மாமலம் மூன்றும் அகார உகாரத்தோடு
ஆம்அறும் மவ்வும் அவ் வாய்உடல் மூன்றில்
தாமாம் துரியமும் தொந்தத் தசியதே`,
    transliteration: `tāmatam kāmiyam ācit takuṇam
māmalam mūṉṟum akāra ukārattōṭu
āmaṟum mavvum av vāyuṭal mūṉṟil
tāmām turiyamum tontat taciyatē`,
    english: `2494: The Three Turiyas in the Three Letters A, U, M (Aum)
The Gunas Three, Tamas and the rest,
The Malas Three, Kamiya and the rest,
No more are;
A, U and the consonant M,
In those letters Three are Turiya Three
All these are of Thom-Tat-Asi, forsooth.`,
    elaborationTamil: `முக்குணங்களும், மும்மலங்களும் 'அ, உ, ம' என்னும் பிரணவ கலைகள் செயற்படில் செயற்படும்; ஒடுங்கில் ஒடுங்கும். அச்செயற்பாடு ஒடுக்கங்களும் மூவகை உடம்பின் கண் நிகழும் 'தொம், தத், அசி' என்னும் முப்பதங்களின் சூனியங்களும் அவ்வாறேயாம். அஃதாவது 'முச்சூனியங்கள் நின்மல துரியத்தில் நிகழும்' என்பதாம்.`,
  },
  {
    id: 2496, tantraId: 8, verseNumber: 2495,
    tamil: `காரியம் ஏழ்கண் டறும்மாயப் பாழ்விடக்
காரணம் ஏழ்கண் டறும்போதப் பாழ்விடக்
காரிய காரண வாதனை கண்டறும்
சீர்உப சாந்தமுப் பாழ்விடத் தீருமே`,
    transliteration: `kāriyam ēḻkaṇ ṭaṟummāyap pāḻviṭak
kāraṇam ēḻkaṇ ṭaṟumpōtap pāḻviṭak
kāriya kāraṇa vātaṉai kaṇṭaṟum
cīrupa cāntamup pāḻviṭat tīrumē`,
    english: `2495: Beyond Three Voids--Maya, Bodha and Upasanta
Experiencing the seven Caused States
The Maya Void is left behind;
Experiencing the seven Causal States
The Bodha Void is left behind;
Experiencing and sundering the Cause-Caused States (above)
The Upasanta Void is left behind;
Then alone is End Finale.`,
    elaborationTamil: `காரிய தத்துவங்களாகிய தூல உடம்பு, தூல பூதம், சூக்கும பூதம், ஞானேந்திரியம், கன்மேந்திரியம், அந்தக்கரணம், பிரகிருதி ஆகிய ஏழினையும் தன்னின் வேறாகக் கண்டு அவற்றின் நீங்கிய நிலை 'மாயப் பாழ்' எனப்படும். அதைக் கடந்து காரண தத்துவங்களாகிய வித்தியா தத்துவம் ஏழினையும் தன்னின் வேறாகக் கண்டு நீங்கிய நிலை 'போதப் பாழ்' எனப்படும். அதைக் கடந்து முன் நீங்கியவற்றின் வாசனை உளதாகிய சுத்த தத்துவங்களையும் வேறாகக் கண்டு கடந்த நிலை 'உபசாந்தம்' எனப்படும் இதனையும் கடந்த நிலையே பந்தம் முழுதும் நீங்கிய வீட்டு நிலையாம்.`,
  },
  {
    id: 2497, tantraId: 8, verseNumber: 2496,
    tamil: `மாயப்பாழ் சீவன் வியோமப்பாழ் மன்பரன்
சேயமுப் பாழெனச் சிவசத்தி யில் சீவன்
ஆய வியாப்தம் எனும்முப்பா ழாம்அந்தத்
தூய சொரூபத்தில் சொல்முடி வாகுமே`,
    transliteration: `māyappāḻ cīvaṉ viyōmappāḻ maṉparaṉ
cēyamup pāḻeṉac civacatti yil cīvaṉ
āya viyāptam eṉummuppā ḻāmantat
tūya corūpattil colmuṭi vākumē`,
    english: `2496: Tat-Tvam-Asi End of Voids Three
The Maya Void is of Jiva;
The Bodha (Vyoma) Void is of Para;
The Upasanta Void (Vyapta) is
Where Jiva one with Siva-Sakti is;
All three Voids are of Pure Manifestness (Svarupa)
--The End of Tvam-Tat-Asi that is Tat-Tvam-Asi.`,
    elaborationTamil: `மாயப் பாழ், சீவப் பாழ், வியோமப் பாழ் ஆகிய மூன்றும், 'நிலைபெற்ற பரம் பொருளைப்போல மிக மேம்பட்ட நிலை' என்று சொல்லப்பட மற்றும் அவையே, 'சீவன் சிவனது திருவருளில் அடங்கி நிற்கும் முப்பாழ்' என்றும் சொல்லப்படும். மிகத் தூயதாகிய உண்மை நிலை, அப், 'பாழ்' என்னும் பெயரும் அற்ற இடமாகும்.`,
  },
  {
    id: 2498, tantraId: 8, verseNumber: 2497,
    tamil: `எதிர்அற நாளும் எருதுஉவந்து ஏறும்
பதியெனும் நந்தி பதமது கூடக்
கதியெனப் பாழை கடந்து அந்தக் கற்பனை
உதறிய பாழில் ஒடுங்குகின் றேனே`,
    transliteration: `etiraṟa nāḷum erutuuvantu ēṟum
patiyeṉum nanti patamatu kūṭak
katiyeṉap pāḻai kaṭantu antak kaṟpaṉai
utaṟiya pāḻil oṭuṅkukiṉ ṟēṉē`,
    english: `2497: Lord is in the Void Beyond the Three Voids
Of Himself, daily,
Nandi that rides the bull
Blesses you,
With impediment none;
And when I reach His Feet,
I cross the Void,
And in that Void
That imagination transcends
I merge.`,
    elaborationTamil: `'என்றும் தன்னோடு ஒப்பார் இன்றி ஆனேற்றையே ஊர்தியாக உவந்து ஏறி உலாவுகின்ற சிவன் ஒருவனே பதி; ஏனையோர் யாவரும் பசுக்களே எனத் துணிந்து அவனது திருவடியை அடைய வேண்டி, முன்னர், 'இதுவே கதி', எனக் கருதிய மூன்று பாழ்களையும் கடந்து முன் கருதிய கருது கோள்களையெல்லாம் உதறித்தள்ளி, அவற்றையெல்லாம் கடந்த வேறொரு தனிப் பாழில் இப்பொழுது நான் அடங்கியிருக்கின்றேன்.`,
  },
  {
    id: 2499, tantraId: 8, verseNumber: 2498,
    tamil: `துரியம் அடங்கிய சொல்லறும் பாழை
அரிய பரம்பரம் என்பர்கள் ஆதர்
அரிய பரம்பரம் என்றே துதிக்கும்
அருநிலம் என்பதை யார்அறி வாரே`,
    transliteration: `turiyam aṭaṅkiya collaṟum pāḻai
ariya paramparam eṉparkaḷ ātar
ariya paramparam eṉṟē tutikkum
arunilam eṉpatai yāraṟi vārē`,
    english: `2498: Paraparam is a Wondrous Land
That Void where Turiyas merge
Defies description
They call it Paramparam;
Thus they say who know not;
As Paramparam they worship it;
Who knows, what wondrous Land it is!`,
    elaborationTamil: `முப்பாழையும் கடந்த, சொல்லற்ற நிலையாம் சொரூபமாகிய உண்மையை, அறியாதார் சிலர், 'அஃது உயிர்களால் என்றும் அடையப்படாத மிக மேலேயுள்ள நிலை' எனக் கூறுவர். (உயிர்களால் என்றுமே அடையப்படாது எனின், 'அத்தன்மையதாகிய ஒருபொருள் உண்டு' என்பதே பெறப்படாது முயற்கோடு, ஆகாயத் தாமரை முதலியனபோல அதுவும் வெறும் கற்பனைப் பொருளாய் விடும். மிக மேலானதேயானும் ஆதலின்) அஃது என்றுமே உயிர்களால் அடையப்படாதது அன்று; செயற்கரிய சாதனைகளைச் செய்தவழிக் கிடைக்கின்ற ஓர் அரிய இடமேயாம். இவ்வுண்மையை அறிந்து, அவ்வாற்றால் அதனை அடைய முயல்பவர் எத்துணைப் பேர்? ஒரு சிலரேயாவர்.`,
  },
  {
    id: 2500, tantraId: 8, verseNumber: 2499,
    tamil: `ஆறாறு நீங்க நமவாதி அகன்றிட்டு
வேறா கயபரை யாவென்று மெய்ப்பரன்
ஈறான வாசியில் கூட்டும் அதுவன்றோ
தேறாச் சிவாய நமவெனத் தேறிலே`,
    transliteration: `āṟāṟu nīṅka namavāti akaṉṟiṭṭu
vēṟā kayaparai yāveṉṟu meypparaṉ
īṟāṉa vāciyil kūṭṭum atuvaṉṟō
tēṟāc civāya namaveṉat tēṟilē`,
    english: `2499: Import of Si-Va-Ya-Na-Ma
The Tattvas six times six left,
And Malas, Anava and Maya devoid,
Denoted by letters "Na" and "Ma"--
Parai to Jiva ("Ya") Her Grace granting,
Into Paran ("Va" Sakti and "Si" Siva) makes it merge,
That indeed is "Si Va Ya Na Ma" (the Five-letter mantra).`,
    elaborationTamil: `'மெய்ப் பொருளை அருளாசிரியர் பக்குவம் வாய்ந்தவர்கட்கு உபதேசிக்கும் உபதேச மொழி, 'சிவாய நம' என்னும் மந்திரமே என்பதைச் சைவப் பெருமக்களன்றிப் பிறர் தெளிய மாட்டாராயினும் சைவப் பெருமக்கள் அதனைத் தெளிந்து அதன் உண்மையை ஆராயுமிடத்து, முப்பத்தாறு தத்துவங்களும் தம்மின் வேறாகி நீங்கிய பொழுது அந்த ஐந்தெழுத்தில் பாசத்திற்கு வழியாகிய 'நம' என்பதை நீக்கி, முன்பு நகரத்தின் பொருளாய்த் திரோதானமாய் இருந்த சத்தி வேறுபட்டு அருட்சத்தியாய் வகாரத்தின் பொருளாகி, யகாரத்தின் பொருளாகிய ஆன்மாவை, யகாரம் நீங்கிய இரண் டெழுத்தில் ஈற்றெழுத்தாகிய வகாரம், முதலெழுத்தாகிய சிகாரத்தின் பொருளாகிய உண்மைச் சிவத்தில் பின் என்றும் நீங்காதவாறு சேர்ப்ப தாகவே யன்றோ உணரப்படும்! 'பிறிதாக ஒன்றும் உணரப்படாது' என்பதாம்.`,
  },
  {
    id: 2501, tantraId: 8, verseNumber: 2500,
    tamil: `உள்ளம் உருவென்றும் உருவம் உளமென்றும்
உள்ள பரிசறித் தோரும் அவர்கட்குப்
பள்ளமும் இல்லைத் திடர்இல்லை பாழ்இல்லை
உள்ளமும் இல்லை உருவில்லை தானே`,
    transliteration: `uḷḷam uruveṉṟum uruvam uḷameṉṟum
uḷḷa paricaṟit tōrum avarkaṭkup
paḷḷamum illait tiṭarillai pāḻillai
uḷḷamum illai uruvillai tāṉē`,
    english: `2500: Beyond Thought and Form is Truth
For them who realized Truth
That Thought is Form and Form is Thought,
For them is no descent, no ascent, no Void.
Neither Thought, nor Form.`,
    elaborationTamil: `'உயிர் உடம்பே; உடம்பே உயிர்' என இவ்வாறு உயிரின் இயல்பை மயங்கி உணர்ந்து, அந்நெறியிலே தங்கள் ஆராய்ச்சியைச் செலுத்தபவர்கட்கு உயிர் இல்பொருளேயாம். உயிர் இல்பொருளாயினமையின், உடம்பின் தன்மையை அவர் உணர்ந்ததும் உணராமையேயாம். ஆகவே, அவர்கட்கு இங்குக் கூறி வந்த இருட்குழியாகிய தத்துவச் சிக்கலும் இல்லை; அக்குழியினின்றும் ஏறும் கரையாகிய முப்பாழும் இல்லை. அவற்றைக் கடந்த வேறு வெளியாகிய பரநிலையும் இல்லை.`,
  },
  {
    id: 2502, tantraId: 8, verseNumber: 2501,
    tamil: `செற்றிடும் சீவ உபாதித் திறன்ஏழும்
பற்றும் பரோபதி ஏழும் பகருரை
உற்றிடும் காரிய காரணத் தோடற
அற்றிட அச்சிவ மாகும் அணுவனே`,
    transliteration: `ceṟṟiṭum cīva upātit tiṟaṉēḻum
paṟṟum parōpati ēḻum pakarurai
uṟṟiṭum kāriya kāraṇat tōṭaṟa
aṟṟiṭa acciva mākum aṇuvaṉē`,
    english: `2501 Transcend All Experiences, Caused and Causal
When Caused Experiences Seven of Jiva
And Causal Experiences Seven of Para Leave,
Cause and Caused Difference vanish,
Then Jiva becomes Siva for sure.`,
    elaborationTamil: `முன்அதிகாரத் தொடக்கத்தில்l 'காரிய தத்துவம்' எனக் கூறப்பட்டனவே இங்கு, சீவஉபாதி' என்றும், 'காரண தத்துவம்' எனக் கூறப்பட்டனவே இங்கு, 'பரோபாதி' என்றும் கூறப்பட்டன. இங்கு, 'பரம்' என்பது, பரம் பொருளைக் குறியாமல், 'சீவ உபாதிக்கு மேலே உள்ளவை' எனப் பொருள் தந்தது. 'இவ்விருவகை உபாதிகளும் நீங்கினால் காரியம் காரணத்தோடு அற்றுவிட்டதாகும். அங்ஙனம் அவை அற்று விட்டதால், 'அணு' எனப்பட்ட உயிர் அவ்வணுத்தன்மை நீங்கி, வியாபகப் பொருளாகிய சிவத்தை அடைந்து தனது வியாபக நிலையைப் பெற்று இன்புறும்' என்பது பின்னிரண்டடிகளின் பொருள்.`,
  },
  {
    id: 2503, tantraId: 8, verseNumber: 2502,
    tamil: `ஆறாறு காரியோ பாதி அகன்றிட்டு
வேறாய் நனவு மிகுந்த கனாநனா
ஆறாறு அகன்ற கழுத்தி அதில் எய்தாப்
பேறா நிலத்துயிர் தொம்பதம் பேசிலே`,
    transliteration: `āṟāṟu kāriyō pāti akaṉṟiṭṭu
vēṟāy naṉavu mikunta kaṉānaṉā
āṟāṟu akaṉṟa kaḻutti atil eytāp
pēṟā nilattuyir tompatam pēcilē`,
    english: `2502: Final Goal is in Sushupti--Beyond Experiences
Without Caused Experiences six times six leaving,
Without Jagrat, Svapna and other states of Turiya Jagrat Waking leaving,
Without entering that Sushupti State
That is beyond Tattvas six times six,
What avails it
If of Thom Pada Jiva speaks?
He on earth will never, never,
The Final Goal reach.`,
    elaborationTamil: `தத்துவங்களுக்குள்ளே சில காரியமும், சில காரணமும் ஆதல் பற்றி அவற்றை, 'காரியம், காரணம்' எனப் பிரித்துக் கூறினாலும் தத்துவங்கள் அனைத்திற்கும் மாயையே காரணமாகத் தத்துவங்கள் அவற்றின் காரியம் ஆதல் பற்றி அவை அனைத்தையும் இங்கு ''காரியோபாதி'' என்றார். ''நனவு'' என்றது சகல சாக்கிரத்தை. அதன்கண் நிகழும் 'நனவு, கனவு, உறக்கம்' என்பவற்றில், இவற்றிற்கு முன் நிலைகளில் எல்லாம் கிடைக்கப்பெறாத பேறு கிடைக்கப் பெறுகின்ற துரிய நிலையை அடைந்த பொழுதுதான் உயிர் உண்மையில் 'துவம்' பதப் பொருளாகும்.`,
  },
  {
    id: 2504, tantraId: 8, verseNumber: 2503,
    tamil: `அகாரம் உயிரே உகாரம் பரமே
மகாரம் சிவமாய் வருமுப் பதத்துச்
சிகாரம் சிவமே வகாரம் பரமே
யகாரம் உயிரென்று அறையலும் ஆமே`,
    transliteration: `akāram uyirē ukāram paramē
makāram civamāy varumup patattuc
cikāram civamē vakāram paramē
yakāram uyireṉṟu aṟaiyalum āmē`,
    english: `2503: Interpretation of A-U-M (Aum) and Si-Va-Ya
Letter A is Jiva; U is Para; M is Siva;
In the three States of Mukti;
Si is Siva, Va is Para; Ya is Jiva
Thus the Mantras "Aum" and "Sivaya" are as one interpreted.`,
  },
  {
    id: 2505, tantraId: 8, verseNumber: 2504,
    tamil: `உயிர்க்குயி ராகி ஒழிவற்று அழிவற்று
அயிர்ப்புஅறும் காரணோ பாதி விதிரேகத்து
உயிர்ப்புறும் ஈசன் உபமிதத் தால்அன்றி
வியர்ப்புறும் ஆணவம் வீடல்செய் யாவே`,
    transliteration: `uyirkkuyi rāki oḻivaṟṟu aḻivaṟṟu
ayirppuaṟum kāraṇō pāti vitirēkattu
uyirppuṟum īcaṉ upamitat tālaṉṟi
viyarppuṟum āṇavam vīṭalcey yāvē`,
    english: `2504: Anava (I-ness) leaves only By Grace
As Life of life,
Interminable and imperishable
Beyond travails of Causal Experiences
And Caused Experience opposite,
Is Isa (Siva) vibrant;
Without His Grace abounding,
Anava that makes Jiva tremble
Never, never, leaves.`,
    elaborationTamil: `எல்லா உயிர்களிலும் அவற்றிற்கு உயிராய், ஒரு ஞான்றும் விட்டு நீங்காது, அழிவின்றியிருப்பினும் உயிர்கள் முன் மந்திரத்தில் கூறிய உபாதிகள் அனைத்தினின்றும் நீங்கிய பின்பே முன்பு பாலில் நெய்போல விளங்காதிருந்த நிலையினின்றும் நீங்கித் தயிரில் நெய்போல வெளிப்பட்டு விளங்குகின்ற சிவன் அவ்வாறு வெளிப்பட்டாலன்றி யாதோர் உயிர்க்கும் துன்பத்தைத் தருகின்ற ஆணவ மலம் நீங்குதல் உண்டாகாது.`,
  },
  {
    id: 2506, tantraId: 8, verseNumber: 2505,
    tamil: `காரியம் ஏழில் கலக்கும் கடும்பசு
காரணம் ஏழில் கலக்கும் பரசிவன்
காரிய காரணம் கற்பனை சொற்பதப்
பாரறும் பாழில் பராபரத் தானே`,
    transliteration: `kāriyam ēḻil kalakkum kaṭumpacu
kāraṇam ēḻil kalakkum paracivaṉ
kāriya kāraṇam kaṟpaṉai coṟpatap
pāraṟum pāḻil parāparat tāṉē`,
    english: `2505: Paraparan is in Void Beyond Experiences
Immanent is Jiva in Caused Experiences Seven,
Immanent is Parasiva in Causal Experiences Seven;
In the Void that defies Cause-Caused description,
Beyond Thought and Word,
Is Paraparan.`,
    elaborationTamil: `'காரிய உபாதி' எனமேற் கூறப்பட்ட உபாதிகள் உள்ள பொழுது, உயிர் தன்னையே அறியாது மயங்கும். காரிய உபாதிகள் நீங்கக் காரண உபாதிகள் நீங்காதிருக்குமாயின் உயிர் தன்னை ஒருவாறு அறியினும் தலைவனை அறியாது மயங்கும். இக்காரிய காரண உபாதிகள் உயிர்கட்கு ஆக்கி வைக்கப்பட்டவை. இன்னும் இவ்வுபாதிகள் பலவாகச் சொல்லப்படுகின்ற பதங்களாகிய உலகங்களைச் சார்ந்து நிற்பனவாம். இவையெல்லாம் அற்ற நிலையே 'வெறும் பாழ்' எனப்படுகின்றது. அவ்விடத்தில் தான் மேலானவற்றிற்கெல்லாம் மேலான பரம் பொருள் உள்ளது.`,
  },
  {
    id: 2507, tantraId: 8, verseNumber: 2506,
    tamil: `முத்திக்கு வித்து முதல்வன்தன் ஞானமே
பத்திக்கு வித்துப் பணிந்துற்றப் பற்றலே
சித்திக்கு வித்துச் சிவபரம் தானாதல்
சத்திக்கு வித்துத் தனதுப சாந்தமே`,
    transliteration: `muttikku vittu mutalvaṉtaṉ ñāṉamē
pattikku vittup paṇintuṟṟap paṟṟalē
cittikku vittuc civaparam tāṉātal
cattikku vittut taṉatupa cāntamē`,
    english: `2506: Seeds Four
Seed of Mukti is Knowledge of Primal One;
Seed of Bhakti is intense adoration meek;
Seed of Siddhi is Self, Siva-Para Becoming;
Seed of Sakti is State of Upasanta.`,
    elaborationTamil: `''பற்றுக பற்றற்றான்; பற்றினை; அப்பற்றைப் பற்றுக பற்று விடற்கு''* 
என்றபடி, உலகப் பற்றை நீக்குதற்கு வழி சிவப்பற்றைக் கொள்ளுத -லாகும். அப்பற்று உண்டாதற்கு வழி, சிவனைக் குருலிங்க சங்கமங் -களை வழிபட்டு உறுதுணையாகப் பற்றுதலாகும். மனம் புலன்களின் வழி ஓடாது தன் வயப்படுதற்கு வழி யோகசமாதி. முத்திக்கு வழி சிவ ஞானம். அந்த ஞானம் வருதற்கு வழி உயிர் உபசாந்தத்தை அடைதலாம்.`,
  },
  {
    id: 2508, tantraId: 8, verseNumber: 2507,
    tamil: `காரியம் ஏழும் கரந்திடும் மாயையுள்
காரணம் ஏழும் கரக்கும் கடுவெளி
காரிய காரண வாதனைப் பற்றறப்
பாரண வும் உப சாந்தப் பரிசிதே`,
    transliteration: `kāriyam ēḻum karantiṭum māyaiyuḷ
kāraṇam ēḻum karakkum kaṭuveḷi
kāriya kāraṇa vātaṉaip paṟṟaṟap
pāraṇa vum upa cāntap paricitē`,
    english: `2507: When Upasanta is
The Seven Caused Experiences lie latent in Maya;
The Seven Causal Experiences lie latent in Void;
When Cause-Caused experiences disappear,
Then is pervasive Upasanta.`,
    elaborationTamil: `'காரிய தத்துவம்' எனப்பட்ட ஆன்ம தத்துவங்கள் பிரகிருதியில் ஒடுங்கினும், பிரகிருதி ஒடுங்காத பொழுது அவை மீளத் தோன்றும் நிலை உளதாகும். ஆகவே, பிரகிருதி ஒடுக்கமே காரிய தத்துவ ஒடுக்கம் ஆதலின், அஃது அசுத்த மாயையில் ஒடுங்குவதாம். இனி, 'காரண தத்துவம்' எனப்பட்ட வித்தியா தத்துவம் ஏழும் அசுத்த மாயையில் ஒடுங்க, அசுத்த மாயை கலக்குண்ணாது சுத்த மாயையில் வியாப்பியமாகி நிற்றலே காரணதத்துவ ஒடுக்கம் ஆதலின், அசுத்த மாயை சுத்த மாயையில் ஒடுங்குவதாகும். (இங்கு ஒடுக்கமாவது காரியப் படுதல் இன்றி வியாப்பிய மாத்திரம் ஆதல்) இவ்வாறு காரிய காரண உபாதிகளின் வாசனையும் அற்றபொழுது ஆன்மா பர துரிய நிலையை அடையும். ('அப்பால் அதீத நிலை தானே வரும்' என்பது கருத்து) 'உபசாந்தம்' என்பதன் தன்மை ஆன்மா இவ்வாறு காரிய காரண உபாதிகளின் வாசனையும் அற்றுத் துரிய நிலையை அடைதலேயாகும்.`,
  },
  {
    id: 2509, tantraId: 8, verseNumber: 2508,
    tamil: `அன்ன துரியமே ஆத்தும சுத்தியும்
முன்னிய சாக்கிரா தீதத் துறுபுரி
மன்னும் பரங்காட்சி யாவது உடனுற்றுத்
தன்னின் வியாத்தி தனில்உப சாந்தமே`,
    transliteration: `aṉṉa turiyamē āttuma cuttiyum
muṉṉiya cākkirā tītat tuṟupuri
maṉṉum paraṅkāṭci yāvatu uṭaṉuṟṟut
taṉṉiṉ viyātti taṉilupa cāntamē`,
    english: `2508: Upasanta in Siva Turiya
In (Jagrat) Turiya is Jiva's purification of Self (Atma Suddhi)
In Turiya of the Jagratatita (Para Turiya)
Is Vision of Param;
That extending into Siva Turiya
Is Upasanta pervasive.`,
    elaborationTamil: `முன் மந்திரத்தில், ''பார்'' எனப்பட்ட அந்தப் பர துரியமே முற்றான ஆன்ம சுத்தி நிலையாகும். (எனினும், அதற்கு முன்னே 'சிவதுரியம்' எனச் சொல்லப்பட்ட நின்மல துரியமே ஆன்ம சுத்தியாகச் சொல்லப்படுகின்றதன்றோ எனின்' பராவத்தையில் இனிது வெளிப்படுகின்ற பர சிவம், நின்மலாவத்தையில் ஓரளவாக வெளிப்படுதல் பற்றி அங்ஙனம் கூறப்படுகின்றது. ஆயினும் ஆன்மா பர சிவத்தோடு இரண்டறக் கலந்து உடனாய், வியாபகமாய் நிற்றல் ஒப்பற்ற உபசாந்தமாகிய பராவத்தையிலே யாகலின், பர துரியமே முற்றான ஆன்ம சுத்தியாம் என்க.`,
  },
  {
    id: 2510, tantraId: 8, verseNumber: 2509,
    tamil: `ஆறாதுஅமைந்துஆண வத்தையுள் நீக்குதல்
பேறான தன்னை அறிதல் பின் தீர்சுத்தி
கூறாத சாக்கிரா தீதம் குருபரன்
பேறாம் வியாத்தம் பிறழ்உப சாந்தமே`,
    transliteration: `āṟātuamaintuāṇa vattaiyuḷ nīkkutal
pēṟāṉa taṉṉai aṟital piṉ tīrcutti
kūṟāta cākkirā tītam kuruparaṉ
pēṟām viyāttam piṟaḻupa cāntamē`,
    english: `2509: Beyond Jiva Turiya and Para Turiya is Upasanta
Removing Anava within,
Entwined with Tattvas six times six,
And realizing Self-knowledge,
--These acts of purification
To Jagrat-Turiya (Jiva Turiya) State belongs;
The Grace of Guru Param dawns
In the Jagratatita Turiya (Para Turiya)
That defies speech;
When that is crossed and Siva Turya is reached,
Then is Upasanta pervasive.`,
    elaborationTamil: `முப்பத்தாறு தத்துவங்களும் தன்னின் மேம்பட்டுத் தன்னை மயக்காதபடி அவைகளைக் கீழ்ப்படுத்தி, அவைகளால் வரும் மயக்கத்தினின்றும் நீங்குதலே தன்னைத் தான் பெறுதலாகிய ஆன்ம தரிசனமாகும். (சிவரூபம் இதில் உடன் நிகழும். ''தன் உயிர் தான் அறப் பெற்றானை ஏனைய மன்னுயிரெல்லாம் தொழும்'9 என்றார் திருவள்ளுவரும்) ஆன்ம தரிசனத்திற்குப்பின் நிகழ்வதாகிய ஆன்ம சுத்தியாவது, சொல் நிகழ்ச்சியில்லாத, மௌன நிலையாகிய நின்மல துரியாதீதமாகும். (இதில் சிவதரிசனமும், சிவயோகமும் உடன் நிகழும்) ஆன்ம சுத்திக்குப் பின் அடையற்பலாதாகிய ஆன்ம லாபமாகிய சிவப்பேறாவது, பர துரியா தீதமே.`,
  },
  {
    id: 2511, tantraId: 8, verseNumber: 2510,
    tamil: `வாய்ந்த உபசாந்த வாதனை உள்ளப் போய்
ஏய்ந்த சிவமாத லின்சிவா னந்தத்துத்
தோய்ந்தறல் மோனச் சுகானுபவத் தோடே
ஆய்ந்துஅதில் தீர்க்கை யானதுஈர் ஐந்துமே`,
    transliteration: `vāynta upacānta vātaṉai uḷḷap pōy
ēynta civamāta liṉcivā ṉantattut
tōyntaṟal mōṉac cukāṉupavat tōṭē
āyntuatil tīrkkai yāṉatuīr aintumē`,
    english: `2510: Upasanta State--The Tenth State
Entering into Upasanta experience,
Jiva becomes Siva;
There immersed in Siva-Bliss
Jiva into Siva merges;
Enjoying that Bliss experience
It abides constant there;
That Experience engrosses
All the ten of Jiva
(From Jagrat Upwards to Siva
Turiya.)`,
    elaborationTamil: `உபசாந்தம் பத்து நிலைகளையுடையதாகச் சொல்லப்படும்.
1. கருவி கரணங்கள் உலகியல் வகையில் செயற்படாது, மெய்யுணர்வு நெறியில் செயற்படுதல். (இஃது யோகாவத்தை, இது முன்பு 'சீவ துரியம்' எனப்பட்டது. இது கருவிகளின் மாற்றுச் செயல் ஆதலின், இதனை, வாதனை'' என்றார்).
2. ஆன்மாத் தன்னைக் கருவிகளின் வேறாக உணர்தல் (இஃது ஆன்ம தரிசனமாம். உள்ளம் - ஆன்மா; 'ஆன்மா' என்றது, 'ஆன்மாத் தான் ஆதல்' என்றபடி.)
3. ஆன்மாத் தன்னையிழத்தல். (அஃதாவது தற்போதம் நீங்குதலாம்.) ''போய்'' என்றது, 'தான் போய்' என்றபடி.
4. தற்போதத்தை இழந்த ஆன்மாச் சிவனையே உணர்ந்து அவனேயாதல். (இதுவே தசகாரியத்துள் சொல்லப்படும் சிவயோகம். ஆன்ம தரிசனத்தில் சிவரூபம் உடன் நிகழும். ஆன்ம சுத்தி சிவதரிசனத்தில் தொடங்கி சிவயோகத்தில் முற்றுப்பெறும்.)
5. சிவானந்தம் உதயமாதல். (இது சிவயோகத்தில் முடிநிலையில் நிகழும்.)
6. உயிர் சிவானந்தத்தை அனுபவித்தல். (இஃது 'ஆனந்தானுபவம்' எனப்படும். இதில் உயிருக்கு, 'நாம் ஆனந்தத்தை அனுபவிக்கின்றோம்' என்னும் உணர்வு நிகழும்.)
7. உயிர் ஆனந்தத்தில் அழுந்துதல். (இதில் அந்த உணர்வும் இல்லாதொழியும்.) இஃது 'ஆனந்தாதீதம்' எனப்படும். (இரண்டு முதல் 5 முடிய உள்ள நான்கும் நின்மலாவத்தையில் சாக்கிர, சொப்பன, சுழுத்தி, துரிய அவத்தைகளாம். 6,7 நின்மல துரியாதீதமாம்.)
8. சகலரினின்று பிரளயாகலர்களாகப் பெற்ற உயிர்களும், பிரளயாகலரில் பக்குவம் பெற்ற உயிர்களும் பின் விஞ்ஞானகலராய் இறைவனால் திருவருள் செய்யப்பெற்றுச் சுத்த புவன போக்கியப் பொருள்களால் இன்புற்றிருத்தல்.
9. அதற்கு மேலும் சுத்த புவன அதிபதிகளாய் ஆட்சி புரிதல். (இவை 'அபர முத்தி' எனப்படும்).
10. இங்குக் கூறிய இவைகளில் ஒன்றும் இன்றிச் சிவனோடு இரண்டறக் கலந்து அவனது வியாபகத்தில் அடங்கி விடுதல் என்பன. (இறுதி மூன்றும் பராவத்தைகளாம். அவற்றுள் பத்தாவதே பரமுத்தியாம்.)`,
  },
  {
    id: 2512, tantraId: 8, verseNumber: 2511,
    tamil: `பரையின் பரவ பரத்துடன் ஏகமாய்த்
திரையின்நின்று ஆகிய தெண்புனல் போலவுற்று
உரையுணர்ந்து ஆரமுது ஒக்க உணர்ந்துளோன்
கரைகண் டானுரை அற்ற கணக்கிலே`,
    transliteration: `paraiyiṉ parava parattuṭaṉ ēkamāyt
tiraiyiṉniṉṟu ākiya teṇpuṉal pōlavuṟṟu
uraiyuṇarntu āramutu okka uṇarntuḷōṉ
karaikaṇ ṭāṉurai aṟṟa kaṇakkilē`,
    english: `2511: Shore Beyond
Merged in One with Sakti and Siva,
As cool waters into wavy sea
And realizing Truth of Holy Word,
That is ambrosial sweet
Jiva reaches the Shore Beyond
That indeed defies speech.`,
    elaborationTamil: `பர சிவத்தின் சத்தியாகிய பராசத்தியின் தடத்த நிலை அதன் அபரமும், சொரூபநிலை அதன் பரமும் ஆகும். பெத்தத்தின் நீங்கிய உயிர் முதற்கண் நின்மலாவத்தையிலும், பராவத்தையில் அதீதத்திற்குக் கீழ்ப்பட்ட நான்கு நிலைகளிலும் பராசத்தியின் அபர நிலையைப் பொருந்தியும் அதீதத்தில் அதன் பர நிலையைப் பொருந்தியும் அலையற்றுள்ள கடல்நீர் போல யாதோர் அலைவுமின்றியிருக்கும். எனினும், அபர நிலையில் தேவாமுதத்தைப் பெற்று உண்பவன், அதனைத் தான் பெற்ற அருமை, அதன் சுவை மிகுதி, அதன் பயன் முதலியவற்றை உணர்ந்து நிற்பவன் போலவும், பர நிலையில் அவ்வாறு உணர்தல் இன்றி அந்த அமுதத்தின் சுவையிலே மூழ்கித் தன்னை மறந்து நிற்பவன் போலவும் இருப்பான். இவ்விருவரில் தன்னை மறந்து, உரையுணர்விறந்தவன் நிலையே முடிந்த நிலையாம்.`,
  },
  {
    id: 2513, tantraId: 8, verseNumber: 2512,
    tamil: `பிறையுள் கிடந்த முயலை எறிவான்
அறைமணி வாள்கொண் டவர்தமைப் போலக்
கறைமணி கண்டனக் காண்குற மாட்டார்
நிறையறி வோம்என்பர் நெஞ்சிலர் தாமே`,
    transliteration: `piṟaiyuḷ kiṭanta muyalai eṟivāṉ
aṟaimaṇi vāḷkoṇ ṭavartamaip pōlak
kaṟaimaṇi kaṇṭaṉak kāṇkuṟa māṭṭār
niṟaiyaṟi vōmeṉpar neñcilar tāmē`,
    english: `2512: You Can See Lord Only if You Hold Him in Your Heart
"I shall smite the hare in the moon"
Thus saying
A man unsheaths his jewelled sword;
Unto him are they
Who say,
"We the blue-throated Lord will see,
We know the Way;"
Such shall never see,
As in their hearts they hold Him not.`,
    elaborationTamil: `'சந்திரனிடத்து உள்ள முயலையாம் வெட்டுவோம்' என்று சொல்லி, ஒலிக்கின்ற மணிகட்டியுள்ள வாளையெடுத்து உயர உயர வீசுபவர் போல, அறிவில்லாதவர் நீல மணிபோலும் கறுத்த கண்டத்தையுடைய சிவனை அடையும் நெறியை உணர மாட்டாமலே தாமே மெய்ப்பொருளை முற்ற அறிந்த நிரம்பிய ஞானிகள் போலத் தாம் அறிந்தன சிலவற்றைக் கூறி உண்மை ஞானியரை இகழ்வர்.`,
  },
  {
    id: 2514, tantraId: 8, verseNumber: 2513,
    tamil: `கருந்தாள் கருடன் விசும்பூடு இறப்பக்
கருந்தாள் கயத்தில் கரும்பாம்பு நீங்க
பெருந்தன்மை பேசுதி நீஒழி நெஞ்சே
அருந்தர அலைகடல் ஆறசென் றாலே`,
    transliteration: `karuntāḷ karuṭaṉ vicumpūṭu iṟappak
karuntāḷ kayattil karumpāmpu nīṅka
peruntaṉmai pēcuti nīoḻi neñcē
aruntara alaikaṭal āṟaceṉ ṟālē`,
    english: `2513: Lord is Remote and Near
The black-footed Garuda bird
Across the sky passes;
The black-hued serpent in deep well dies;
Stop bragging of your greatness, O heart!
Be unto the river
That into the wavy ocean merges.`,
    elaborationTamil: `மனமே, 'பெரிய முயற்சியையுடைய கருடன் தன்போக்கிலே தான் ஆகாயத்தில் பறக்கவும், கரிய நாகம் அஞ்சி ஓடி, மிக ஆழ்ந்த புற்றுள் ஒளிந்து கொள்ளுதல் போலவதே, மெய்யுணர் வுடையார் முன் மெய்யுணர்வில்லாதாரது நிலை என்பதைச் சில சான்று களால் நீ உணர்ந்திருந்தும் மெய்யுணர்வில்லாதாரது கூற்றுக்களைப் பெரிது படுத்திப் பேசுகின்றாய். இனி அவ்வாறு பேசுதலை விடு. ஏனெனில் உண்மை மெய்ந்நெறியாகிய பெருநெறியில் ஏனைச் சிறுநெறிகள் எல்லாம் பெரிய ஒரு கடலிலே சிறிய பல ஆறுகள் சென்று உருத்தெரியாது அடங்குதல் போல்வதே.`,
  },
  {
    id: 2515, tantraId: 8, verseNumber: 2514,
    tamil: `கருதலர் மாளக் கருவாயில் நின்ற
பொருதலைச் செய்வது புல்லறி வாண்மை
மருவலர் செய்கின்ற மாதவம் ஒத்தால்
தருவலர் கேட்ட தனியும்ப ராமே`,
    transliteration: `karutalar māḷak karuvāyil niṉṟa
porutalaic ceyvatu pullaṟi vāṇmai
maruvalar ceykiṉṟa mātavam ottāl
taruvalar kēṭṭa taṉiyumpa rāmē`,
    english: `2514: Perform Tapas
If you seek your enemies (Malas) to perish,
Why fight at the Gate of Birth?
Silly heroism indeed!
If suitable the Tapas of holy ones are,
He, who all gifts gives,
Will with Celestials seat them.`,
    elaborationTamil: `பகைவரைப் போர்க்களத்தில் எதிர்த்துப் போர் செய்யாது, அவர்தம் நகரத்தை முற்றுகையிட்டே காலத்தைப் போக்குதல் புல்லறிவாண்மையாகும். சிவநெறியைச் சாராதவர் செய்யும் பெரிய தவங்கள் எல்லாம் அப்புல்லறிவாண்மையை ஒக்குமேயானால், அவற்றால் தரப்படும் பயன்கள் எல்லாம் சுவர்க்க போக வாசிகளாய்ச் சில காலம் வாழ்ந்திருத்தலேயாகும்.`,
  },
  {
    id: 2516, tantraId: 8, verseNumber: 2515,
    tamil: `பிணங்கவும் வேண்டாம் பெருநில முற்றும்
இணங்கிஎம் ஈசனே ஈசன்என்று உன்னில்
கணம்பதி னெட்டும் கழலடி காண
வணங்ககெழு நாடி அங்கு அன்புற லாமே`,
    transliteration: `piṇaṅkavum vēṇṭām perunila muṟṟum
iṇaṅkiem īcaṉē īcaṉeṉṟu uṉṉil
kaṇampati ṉeṭṭum kaḻalaṭi kāṇa
vaṇaṅkakeḻu nāṭi aṅku aṉpuṟa lāmē`,
    english: `2515: Seek and Be in Bliss
Be not in contentions lost;
Our Lord pervades worlds all
He is Siva--
Thus you hold;
Then the very Heavenly Hosts Eighteen
Will worship at your feet;
Seek Him, seek Him;
You shall in bliss be.`,
    elaborationEnglish: `The eighteen heavenly hosts consist of super-normal beings. They are:`,
    elaborationTamil: `பெரிய நிலவுலகத்தவர் யாவரும், வானுலகத்துப் பதினெண் கணங்களும், எங்கள் இறைவனாகிய சிவனையே 'பரம் பொருள்' என உடன்பட்டு மனத்தால் நினைத்தும் பின்னர் அவன் திரு வடியைக் கண்டு வாக்கால் வாழ்த்தியும் தலையால் வணங்கியும் பயன் பெற முயல்கின்றனர். அதனை நன்கு சிந்தித்து அவனிடத்தில் அன்பு செய்தலே தக்கது. அதை விடுத்து பிற சமயிகளது சொற்களைக் கேட்டு மாறுபடாதீர்கள்.`,
  },
  {
    id: 2517, tantraId: 8, verseNumber: 2516,
    tamil: `என்னிலும் என்னுயி ராய இறைவனைப்
பொன்னிலும் மாமணி யாய புனிதனை
மின்னிய எவ்வுய ராய விகிர் தனை
உன்னிலும் உன்னும் உறும்வகை யாலே`,
    transliteration: `eṉṉilum eṉṉuyi rāya iṟaivaṉaip
poṉṉilum māmaṇi yāya puṉitaṉai
miṉṉiya evvuya rāya vikir taṉai
uṉṉilum uṉṉum uṟumvakai yālē`,
    english: `2516: Contemplate on Him
The Lord who is dearer than dearest life in me,
The Pure One who is brighter than purest gold
The Great One, in all life, unvarying glows,
On Him contemplate, in ways appropriate.`,
    elaborationEnglish: ``,
    elaborationTamil: `என்னைத்தான் நான், 'என் உய ர்' என்று ஓற்றுமைக் கிழமை பற்றி எண்ணுவேன். ஆயினும், என் உயிரினுள் உயிராய் நின்று எனக்கு உறுதிசெதய்து வருபவன் எங்கள் இறைவனாகிய சிவன். ஆகவே, 'என் உயிர்' என்று யான் வலியுறுத்திக் கூறுதற்கு உண்மையில் உரியவன் அவனே. அவன் உண்மையில் பொன்னினும், மணியினும் சிறப்பாகக் கொண்டு போற்றத்தக்கவன். தூய்மையே வடிவானவன் உலகில் காணப்படும் பொருள்களில் எல்லாம் மேலான ஒளிப்பொருளாகிய. பகலவன் ''வெங்கதிர்'' என்று சொல்லப்படுதல் போல, உயிரினுள் உயிராய் இருந்து அங்குள்ள இருளை முற்றக் கடிதலால் அவனை 'வெவ்வுயிர்' என்றலும் பொருந்தும் ('வெம்மை' என்பதற்கு, 'விருப்பம்' என்பதும் பொருளாகலின், ''வெவ்வுயிர்'' என்பது, 'விரும்பத் தக்க உயிர்' என்றும் பொருள் தரும்) அவன் உயிர்களின் குணங்கட்கு வேறான குணங்களையுடையவன். அவனை நீவிர் நினைப்பீராயின், உம்மையும் அவன் நினைப்பான். (அவனை நீவிர் அடைதல் கூடும்)`,
  },
  {
    id: 2518, tantraId: 8, verseNumber: 2517,
    tamil: `நின்றும் இருந்தும் கிடந்தும் நிமலனை
ஒன்றும் பொருள்கள் உரைப்பல ராகிலும்
வென்றுஐம் புலனும் விரைந்து பிணக்கறுவந்து
ஒன்றாய் உணரும் ஒருவனும் ஆமே`,
    transliteration: `niṉṟum iruntum kiṭantum nimalaṉai
oṉṟum poruḷkaḷ uraippala rākilum
veṉṟuaim pulaṉum viraintu piṇakkaṟuvantu
oṉṟāy uṇarum oruvaṉum āmē`,
    english: `2517: Adore Him in All Ways
Standing, sitting and prostrating
Well may you, the Pure One adore;
Though learned you be,
Do conquer your Senses Five,
And quick sunder contending Pasas;
Thus seek Him and know Him,
He in you one will be.`,
    elaborationTamil: `நூல்களில் சொல்லப்பட்ட பொருள்களைப் பிறர் அறிய நன்கு உரைப்பவராயினும், தாங்கள் ஐம்புலன்களை வென்று, 'இவன் பரமோ, அவன் பரமோ, எல்லாருமே பரமோ' என இங்ஙனம் பலவாறாக எண்ணி அலமரும் ஐயங்களை விரைவில் விடுத்து, 'இவன் ஒருவனே பரம்' என்று ஒருதலையாக உணரத்தக்கவன் ஒரு முதல்வனே. அத்தகைய முதல்வன் எங்கள் பரமாகிய சிவன் ஒருவனே ஆதலின், அவனையே நீவிர் நிற்றல், இருத்தல், கிடத்தல் முதலிய எத்தொழிலைச் செய்யினும் மனத்தால் ஒன்றியிருங்கள்; பயன் அடைவீர்கள்.`,
  },
  {
    id: 2519, tantraId: 8, verseNumber: 2518,
    tamil: `நுண்ணறி வாய்உல காய்உலகு ஏழுக்கும்
எண்ணறி வாய்நின்ற எந்தை பிரான்தன்னைப்
பண்அறி வாளனைப் பாவித்த மாந்தரை
விண்அறி வாளர் விரும்புகின் றாரே`,
    transliteration: `nuṇṇaṟi vāyula kāyulaku ēḻukkum
eṇṇaṟi vāyniṉṟa entai pirāṉtaṉṉaip
paṇaṟi vāḷaṉaip pāvitta māntarai
viṇaṟi vāḷar virumpukiṉ ṟārē`,
    english: `2518: He is Pervasive Knowledge
As subtle Knowledge He stood;
As pervasive Knowledge, engrossing
The Seven Worlds, too, He stood;
He knows melodies all;
Sing His praise,
The Celestials will you in endearment hold.`,
    elaborationTamil: `உயிர்கள் தூல சித்தாதல் போல இல்லாமல் சூக்கும சித்தாய், சடவுலகத்தை இயக்கியும், அறிவுலகமாகிய உயிர்களின் அறிவுக்கறிவாய் நின்று அறிவித்தும் நிற்கின்ற, எங்கள் தந்தையாகிய சிவபெருமான், உயிர்களின் தனித் தன்மையை உணர்ந்து அவற்றைப் பக்குவப்படுத்தும் முறைகளில் பக்குவப்படுத்துவோனாவான். அவனை உணர்ந்த பெருமக்களையே உயர்ந்த அறிவினையுடையோர் சேரவிரும்புகின்றார்கள்.`,
  },
  {
    id: 2520, tantraId: 8, verseNumber: 2519,
    tamil: `விண்ணவ ராலும் அறிவுஅறி யான்தன்னைக்
கண்ணற வுள்ளே கருதிடின் காலையில்
எண்உற வாசமுப் போதும் இயற்றிநீ
பண்ணிடில் தன்மை பராபர னாமே`,
    transliteration: `viṇṇava rālum aṟivuaṟi yāṉtaṉṉaik
kaṇṇaṟa vuḷḷē karutiṭiṉ kālaiyil
eṇuṟa vācamup pōtum iyaṟṟinī
paṇṇiṭil taṉmai parāpara ṉāmē`,
    english: `2519: Think of Him Continuously
He whom even Celestials know not,
Think of Him, in the waking dawn,
Continuous think of Him morn, noon and eventide
If thus you perservere,
You shall become the very Paraparam.`,
    elaborationTamil: `தேவர்களாலும், (உம்மையால் மூவர்களாலும்) அறிதற்கரியவனாகிய சிவனைச் சிறுதும் இடையீடின்றி உள்ளத்தால் பற்றுங்கள்; பற்றினால் பற்றிய அப்பொழுதே அவன் உங்களால் விரும்பப்படும் பொருளாய் வெளிப்பட்டு விளங்குவான். அதன் பின்பு எஞ்ஞான்றும் நீவிர் அவனை அகத்தும், புறத்தும் வழிபட்டால், உமது தன்மை சிவத்தன்மையாய்விடும்.`,
  },
  {
    id: 2521, tantraId: 8, verseNumber: 2520,
    tamil: `ஒன்றாய் உலகுடன் ஏழும் பரந்தவன்
பின்தான் அருள்செய்த பேரருள் ஆளவன்
கன்றா மனத்தார்தம் கல்வியுள் நல்லவன்
பொன்றாத போது புனைபுக ழானே`,
    transliteration: `oṉṟāy ulakuṭaṉ ēḻum parantavaṉ
piṉtāṉ aruḷceyta pēraruḷ āḷavaṉ
kaṉṟā maṉattārtam kalviyuḷ nallavaṉ
poṉṟāta pōtu puṉaipuka ḻāṉē`,
    english: `2520: He is of Infinite Grace
As One He pervades the seven worlds all,
He, of yore, His Grace on Jiva conferred;
He, Lord of Grace Infinite;
Goodly is He in Jnana
Of the holy ones of constant heart;
He who is festooned in flower unfading,
He, the Famed One.`,
    elaborationTamil: `சிவன், தான் பொருளால் ஒன்றாயினும், எண்ணில்லாத பல பொருள்களிலும் நிறைந்திருப்பவன் (என்றது, 'அவ்வாறு வியாபிக்கும் சத்தியை உடையவன்' என்றபடி) ஆயினும் தன்னைச் சார்ந்தவர்க்குச் சார்ந்தபின்பே அருளும் பேரருளை யுடையவன். அன்பு செய்யும் மனத்தினர் தாம் அறிந்தவாறு செய்யும் செயல்களுக்கெல்லாம் இணங்குபவன். அன்பர்கள் பலவாய் நிறைந்த மலர்களைத் தூவிப் புகழும் கெடாத புகழினையுடையவன்.`,
  },
  {
    id: 2522, tantraId: 8, verseNumber: 2521,
    tamil: `போற்றியென் றேன்எந்தை பொன்னான சேவடி
ஏற்றியே தென்றும் எறிமணி தான்அகக்
காற்றின் விளக்கது காயம் மயக்குறும்
அற்றலும் கேட்டது மன்றுகண் டேனே`,
    transliteration: `pōṟṟiyeṉ ṟēṉentai poṉṉāṉa cēvaṭi
ēṟṟiyē teṉṟum eṟimaṇi tāṉakak
kāṟṟiṉ viḷakkatu kāyam mayakkuṟum
aṟṟalum kēṭṭatu maṉṟukaṇ ṭēṉē`,
    english: `2521: Witness Dance of Siva
"Hail, my Father! Hail His golden Feet!"
Thus I praised;
And as I praised,
The radiant lamp
Of life within sparkled;
And then I heard the bewitching sound,
That my body in rapture immersed;
And lo! there was His Dance!`,
    elaborationTamil: `எம் தந்தையாகிய சிவபெருமானது பொன் போலும் சிவந்த திருவடிகளில், அகத்தில் எனது மனத்தையும், புறத்தில் பூக்களையும் ஏற்றி, 'போற்றி போற்றி' என்று பலநாளும் துதித்தேன். அப்பொழுது, அடிக்கப்பட்ட மணியின் ஓசை போன்ற ஓர் ஓசை உள்ளத்திலே கேட்டது. உடனே, காற்றின் முன்னே உள்ள விளக்குப் போல்வதாகிய உடம்பு எந்த நேரத்திலும் நீங்குவதாயினும், அஃது என்றும் நீங்காமலே இருப்பது போலக் காட்டி மயக்குகின்ற மயக்கத்தை நீக்கும் உபாயமும் கேட்டது. பின்பு எல்லாவற்றையும் அடக்கி, மேலே வியாபித்துள்ள பரவெளியும் என் கண்முன் காணப்பட்டது.`,
  },
  {
    id: 2523, tantraId: 8, verseNumber: 2522,
    tamil: `நேடிக்கொண் டென்னுள்ளே நேர்தரு நந்தியை
ஊடுபுக் காரும் உணர்ந்தறி வாரில்லை
கூடுபுக் கேறலுற் றேனவன் கோலங்கண்
மூடிக்கண் டேனுல கேழுங்க்ண் டேனே`,
    transliteration: `nēṭikkoṇ ṭeṉṉuḷḷē nērtaru nantiyai
ūṭupuk kārum uṇarntaṟi vārillai
kūṭupuk kēṟaluṟ ṟēṉavaṉ kōlaṅkaṇ
mūṭikkaṇ ṭēṉula kēḻuṅkṇ ṭēṉē`,
    english: `2522: God Vision in Yoga Way
I sought my Nandi within
And there I met Him;
They seek Him not within their hearts,
And so know Him not;
In yogic way I entered within
And ascended Adharas;
And eyes closed in trance
I saw His Form Divine;
And the Seven Worlds too.`,
    elaborationTamil: `என்னைத் தானே தேடிக்கொண்டு வந்து என்னுள்ளேயிருக்க ஒருப்பட்டுவிட்ட சிவனை என்னுள்ளே புகுந்து அறிகின்றவர் ஒருவரும் இல்லை. (ஆகவே, வேறிடத்தில் அவனை அறிதலும் இயலாமை வெளிப்படை) யான் வெளியே சென்ற அலையாமல் என் உடம்பினுள்ளே கீழ் இருந்து மேல் ஏறிச் சென்று பொழுது அவனது அழகைக் கண்டேன்; காணுங்கால் கண்ணைத் திறந்து பார்த்துக் காணாமல் கண்ணை மூடிக்கொண்டே கண்டேன். அப்பொழுது அவனை மட்டுமா கண்டேன்? ஏழுலகங்களையும் கண்டேன்.`,
  },
  {
    id: 2524, tantraId: 8, verseNumber: 2523,
    tamil: `ஆன புகழும் அமைந்த தோர் ஞானமுந்
தேனு மிருக்குஞ் சிறுவரை யொன்றுடண்
டூனமொன் றின்றி யுணர்வுசெய் வார்கட்கு
வானகஞ் செய்யு மறவனு மாமே`,
    transliteration: `āṉa pukaḻum amainta tōr ñāṉamun
tēṉu mirukkuñ ciṟuvarai yoṉṟuṭaṇ
ṭūṉamoṉ ṟiṉṟi yuṇarvucey vārkaṭku
vāṉakañ ceyyu maṟavaṉu māmē`,
    english: `2523: Vision of Lord Within
I behold the Little Mount within
In it was Divine Glory,
Abiding Jnana and nectar sweet
For them that realize Him in (love) unfaltering,
He creates the very Heaven within;
He, the Compassionate One.`,
    elaborationTamil: `யோகக் காட்சி பற்றி, 'முக்காலமும் உணர்ந்தவர்' எனப் பலரும் கூறப்பட்டுக் குவியும் புகழாகிய உயர்வையும், அவ்யோகத்தாலே பிறர் ஒருவரால் அசைக்க ஒண்ணா அருள் உணர்வாகிய துளங்கா நிலையையும், அமுதமாகிய தேனையும் உடைய ஒரு சிறு குன்று மக்கள் எல்லாரது உடம்பிலும் உள்ளது. அதனை உணர்ந்து, ஏறும் வழியறிந்து ஏறி, அதனை உணர்வினால் அடைந்த தவத்தோரை, அவர் உடம்பு நீங்கிய பின்னர்த் தனது பேருலகில் ஏற்றுகின்ற ஆண்மையுடையவனாகவும் எங்கள் சிவன் இருக்கின்றான்.`,
  },
  {
    id: 2525, tantraId: 8, verseNumber: 2524,
    tamil: `மாமதி யாமதி யாய்நின்ற மாதவர்
தூய்மதி யாகுஞ் சுடர்பர மானந்தந்
தாமதி யாகச் சகமுணச் சாந்திபுக்
காமல மற்றார் அமைவுபெற் றாரே`,
    transliteration: `māmati yāmati yāyniṉṟa mātavar
tūymati yākuñ cuṭarpara māṉantan
tāmati yākac cakamuṇac cāntipuk
kāmala maṟṟār amaivupeṟ ṟārē`,
    english: `2524: State of Quiescence
Of Wisdom infinite,
The Tapasvins great in wisdom stood,
Pure as moon's rays they beam;
In Transcendental bliss they are;
Themselves Divine Jnana becoming,
They encompassed in Consciousness
The Universe Cosmic;
And entering Upasanta
They freed themselves of Malas,
And State of Quiescence reached.`,
    elaborationEnglish: ``,
    elaborationTamil: `'மதி' என்பதற்கு, 'அறிவு' என்பதும் பொருள் ஆதலால் 'மதி' என்னும் பெயருக்கு வானத்துச் சந்திரனை விட மிக உரிமையுடைய உச்சிச் சந்திரனை அடைந்து, அதனால் உண்டாகும் அறிவையே அறிவாகப் பெற்ற யோகிகளுடைய தூய அறிவாய் விளங்கும் ஒளி, பேரின்பமே வடிவாக உடைய பரம்பொருளாம். அதனால், பிறரெல்லாம் தங்களுடைய நிலையற்ற அறிவையே அறிவாகப் பற்றி உலகத்தை நுகர்ந்துகொண்டிருக்க இவ்யோகிகள் 'உபசாந்தம்' என்னும் நிலையை அடைந்து, அநாதியே பற்றிய மலங்கள் நீங்கப்பெற்று, அமைதி நிலையை அடைகின்றனர்.`,
  },
  {
    id: 2526, tantraId: 8, verseNumber: 2525,
    tamil: `பதமுத்தி மூன்றும் பழுதென்று கைவிட்
டிதமுற்ற பாச இருளைத் துரந்து
மதமற் றெனதியான் மாற்றிவிட் டாங்கே
திதமுற் றவர்கள் சிவசித்தர் தாமே`,
    transliteration: `patamutti mūṉṟum paḻuteṉṟu kaiviṭ
ṭitamuṟṟa pāca iruḷait turantu
matamaṟ ṟeṉatiyāṉ māṟṟiviṭ ṭāṅkē
titamuṟ ṟavarkaḷ civacittar tāmē`,
    english: `2525: Siva Siddha State
They abandoned Muktis three as vain;
They dispelled enticing darkness of Pasa,
They rid themselves of Anava,
They transcended "I" and "mine" consciousness,
They in constancy remained,
They, verily, are Siva Siddhas.`,
    elaborationTamil: `'சாலோகம், சாமீபம், சாரூபம்' மூன்றும் பத முத்திகளாம். சிலர் இவற்றையே வேறு வகையாகக் கூறி 'பரமுத்தி' எனச் சாதிப்பர். அவற்றில் எல்லாம் இருள்மலம் ஆகிய ஆணவம் பற்றறக் கழியாமையால் அதன் காரியமாகிய துன்பம் அவ்விடங்களில் சிறிது சிறிது உள்ளதேயாம். ஆகையால், 'அவை குறையுடையன' என்று அறிந்து, அவற்றோடு நிற்றலை விடுத்து. ஆணவம் பற்றற நீங்கினமையால், அதன் காரியமாகிய மயக்கமும், 'யான், எனது' செருக்கும் பற்றறக் கழிய, அப்பற்றுக்களை இயல்பிலே இல்லாதவ னாகிய பரம சிவனிடத்தில் அடங்கி நிலைத்திருப்பவர்களே உண்மை -யில் சிவனைப் பெற்றவராவர்.`,
  },
  {
    id: 2527, tantraId: 8, verseNumber: 2526,
    tamil: `சித்தர் சிவத்தைக் கண்டவர் சீருடன்
சுத்தாசுக் தத்துடன் தோய்ந்துந்தோ யாதவர்
முத்தரம் முத்திக்கு மூலத்தர் மூலத்துச்
சத்தர் சதாசிவத் தன்மையர் தாமே`,
    transliteration: `cittar civattaik kaṇṭavar cīruṭaṉ
cuttācuk tattuṭaṉ tōyntuntō yātavar
muttaram muttikku mūlattar mūlattuc
cattar catācivat taṉmaiyar tāmē`,
    english: `2526: Siddhas Are Like Sadasiva Himself
Siddhas are those who Siva saw;
Soaked in Suddha-Asuddha,
Yet soaked are not;
Muktas are they,
And source of Mukti, too, are they;
Possessed are they of Muladhara prowess
Alike are they unto Sadasiva.`,
    elaborationTamil: `சிவஞானத்தால் சிவதரிசனத்தைப் பெற்றோர் யாவரும் சிவனைப் பெற்றவராகவே எண்ணப்படுவர். (அவர் பின்பு பதமுத்திக்கு மேலான அபர முத்தி பரமுத்திகளை அடைவர் ஆதலின்,) 
''பரஞானத் தாற்பரனைத் தரிசித்தோர் பரமே
பார்த்திருப்பர்; பதார்த்தங்கள் பாரார்.'' l 
என்றபடி அவர்கள் 'சுத்தம், அசுத்தம்' என்னும் இருவகைப் பிரபஞ்சத்துள் எதில் இருப்பினும் அதில் பற்றற்றேயிருப்பர். அவர், 'பதமுத்தி, அபரமுத்தி, பரமுத்தி' என்னும் மும்முத்திகளையும் தம்மை அடைந்த மாணாக்கர்க்கு அளிக்க வல்ல ஆசிரியர்களும் ஆவர். இனி மூலாதாரத்தில் ஒடுங்கியிருக்கும் குண்டலி சத்தியை எழுப்பி அதன் பயனைப் பெற்ற யோகியரும் சதாசிவ மூர்த்திபோல அபர ஞானமாகிய கலைஞானங்களை வழங்கத் தக்கவராவர்.`,
  },
  {
    id: 2528, tantraId: 8, verseNumber: 2527,
    tamil: `உதிக்கின்ற இந்திரன் அங்கி யமனும்
துதிக்கும் நிருதி வருணன்நல் வாயு
மதிக்கும் குபேரன் வடதிசை யீசன்
நிதித்தெண் டிசையு நிறைந்துநின் றாரே`,
    transliteration: `utikkiṉṟa intiraṉ aṅki yamaṉum
tutikkum niruti varuṇaṉnal vāyu
matikkum kupēraṉ vaṭaticai yīcaṉ
nititteṇ ṭicaiyu niṟaintuniṉ ṟārē`,
    english: `2527: Gods in the Eight Cardinal Points of Earth
Indra, Agni, Yama and Nrudi
Varuna, Vayu, Kubera, and Isanana
They (gods) in order according
Filled the cardinal directions eight.`,
    elaborationEnglish: `“The eight gods of the cardinal points of earth are enumerated to indicate that they are all seated within the eight-petalled lotus in the cranium—the microcosm in the macrocosm.

In most of the books dealing with kundalini yoga, the flower in sahasrara is usually pictured as a thousand-petalled lotus. Hence the name,- sahasrara (thousand petall). Tirumular however, visions it as an eight-petalled lotus. The term, sahasrara, however, is used in the translation for convenience of understanding only. As it is not a centre (chakra or adhara), Tirumular only refers to the experiences in the eight-petalled lotus of the cranium. The region usually referred to as sahasrara is indicated by Tirumular as Mount Meru (in the cranium).

For a different presentation of the petals in the adharas and for the number of adharas, vide ‘‘The Serpent Power by Sir John Woodroffe.

. Indra—god of the Eastern quarter.

Agni—god of the South Eastern quarter.

. Yama—god of the Southern quarter.

. of the South Western quarter. .. Varuna—god of the Western quarter. Vayu—god of North Western quarter. Kubera—god‘of the -Northem quarter. Isanana—god of the North Eastern quarter.`,
    elaborationTamil: `''அண்ட பிண்டம் அவை சமம்''* *கோயிற் புராணம் - பதஞ்சலி சருக்கம் - 70. என்பது எல்லார்க்கும் ஒப்ப முடிந்தது ஆதலின், இதய கமலம் எட்டிதழ்களை உடையதாகக் கொள்ளப்படுதல் போலவே நில வுலகமும் எட்டிதழ்களையுடைய தாமரை மலர்களும், அவ்விதழ்களில் திசைக் காவலர்கள் இருப்பதாகவும் பாவித்து அவர்களை வழிபடல் வேண்டும் - என்பது வைதிகக் கொள்கை. அவரளவிற்கு அது வேண்டுவதே என்பதை முதற்கண் கூறுகின்றார். இதன் பொருள் வெளிப்படை.`,
  },
  {
    id: 2529, tantraId: 8, verseNumber: 2528,
    tamil: `ஒருங்கிய பூவுமோர் எட்டித ழாகும்
மருங்கிய மாயா புரியத னுள்ளே
சுருங்கிய தண்டின் சுழுனையி னூடே
ஒருங்கிய சோதியை ஒர்ந்தெழும் உய்ந்தே`,
    transliteration: `oruṅkiya pūvumōr eṭṭita ḻākum
maruṅkiya māyā puriyata ṉuḷḷē
curuṅkiya taṇṭiṉ cuḻuṉaiyi ṉūṭē
oruṅkiya cōtiyai ornteḻum uyntē`,
    english: `2528: The Eight Petalled Lotus in Sahasrara
In the Maya-Land of body
Is the Flower of petals eight (pointing to directions eight)
Through the lean stalk of Sushumna,
Contemplate on its radiance,
And ascend upward;
Redeemed are you then.`,
    elaborationTamil: `உயிர்களோடு ஒன்றி இயங்குகின்ற மாயா நகரத்தில் ஒன்றை ஒன்று ஒத்துள்ள தாமரைமலர்கள் எட்டிதழ்களையுடையன வாகும். அவை உள்ளே நுணுகிய புழையை உடைய தண்டின்மேல் உள்ளன. அவற்றுள் ஒரு தண்டு 'சுழுமுனை' எனப்படுகின்றது. அதனோடு உள்ள புழையால் மலர்கின்ற தாமரையில் விளங்குகின்ற ஒளியையே யோகிகள் காண்கின்றனர் ஆதலின் மற்றொரு தாமரையிலும் அந்த ஒளியையே பாவித்து உய்தி பெறுங்கள்.`,
  },
  {
    id: 2530, tantraId: 8, verseNumber: 2529,
    tamil: `மொட்டலர் தாமரை மூன்றுள மூன்றினும்
விட்டலர் கின்றனன் சோதி விரிசுடர்
எட்டல ருள்ளே இரண்டலர் உள்ளுறிற்
பட்டலர் கின்றதோர் பண்டங் கனாவே`,
    transliteration: `moṭṭalar tāmarai mūṉṟuḷa mūṉṟiṉum
viṭṭalar kiṉṟaṉaṉ cōti viricuṭar
eṭṭala ruḷḷē iraṇṭalar uḷḷuṟiṟ
paṭṭalar kiṉṟatōr paṇṭaṅ kaṉāvē`,
    english: `2529: How the Eight Petalled Lotus Opens
Three the lotus buds there;
Into the three He sends His rays
That Light spreading,
The eight-petalled bloom within opens;
Into them
If the rays of Petals Two (Ajna) penetrates,
This body, into a (heavenly) dream blossoms.`,
    elaborationTamil: `அரும்பாய் இருந்து அலர்த்த அலர்கின்ற தாமரை மலர்கள் உடலினுள்ளே ஒன்றல்ல; மூன்று உள்ளன. அந்த மூன்றிலுமே ஒளி வடிவான இறைவன் விளங்குகின்றான். எனினும், மேற்கூறிய எட்டிதழ்த் தாமரையிலே நின்றுவிடாமல் ஏறிச் சென்று இரண்டிதழ்த் தாமரையை அடைந்து அவனைத் தரிசித்தால், பிறந்து வளர்கின்ற உடம்பு கனவுக் காட்சியாய்விடும்.`,
  },
  {
    id: 2531, tantraId: 8, verseNumber: 2530,
    tamil: `ஆறே யருவி யகங்குளம் ஒன்றுண்டு
நூறே சிவகதி நுண்ணிது வண்ணமும்
கூறே குவிமுலைக் கொண்பனை யாளொடும்
வேறே யிருக்கும் விழுபொருள் தானே`,
    transliteration: `āṟē yaruvi yakaṅkuḷam oṉṟuṇṭu
nūṟē civakati nuṇṇitu vaṇṇamum
kūṟē kuvimulaik koṇpaṉai yāḷoṭum
vēṟē yirukkum viḻuporuḷ tāṉē`,
    english: `2530: Siva-Sakti in Eight-Petalled Lotus
The six streams (of Adharas)
Into one Pond flow;
Thus in Way subtle
Into Siva-State penetrate;
There indeed is the Precious Truth,
Himself with Sakti stands,
--She of bouncing breasts and tender vine form.`,
    elaborationEnglish: ``,
    elaborationTamil: `உடம்பினுள், முன் அதிகாரத்தில் கூறியவாறு உள்ள சிறுமலையினின்றும் தோன்றுவது ஆறு அன்று; அருவியே அந்த அருவியின் நீரை ஏற்கின்ற குளம் (ஏரி) ஒன்று உண்டு. அதில் விளையும் விளைவுவகைகளோ பல. ஆயினும் அவ்வினைவினது இயல்பு அறிதற்கரிதாய மிக நுட்பமாய் உள்ளது. அதனை வெளிப் படக்கூறினால், மாதொரு கூறனாகிய பரம்பொருளேயாம்.`,
  },
  {
    id: 2532, tantraId: 8, verseNumber: 2531,
    tamil: `திகையெட்டும் தேரேட்டும் தேவதை எட்டும்
வகையெட்டு மாய்நின்ற ஆதிப் பிரானை
வகையெட்டு நான்குமற் றாங்கே நிறைந்து
முகையெட்டும் உள்நின் றுதிக்கின்ற வாறே`,
    transliteration: `tikaiyeṭṭum tērēṭṭum tēvatai eṭṭum
vakaiyeṭṭu māyniṉṟa ātip pirāṉai
vakaiyeṭṭu nāṉkumaṟ ṟāṅkē niṟaintu
mukaiyeṭṭum uḷniṉ ṟutikkiṉṟa vāṟē`,
    english: `2531: He Blooms Within Petals Eight
The Primal One stood,
As directions eight,
Mountains eight,
Gods eight
And Forms eight;
Reach Him,
Who fills within
From eight to four petalled center;
He Who blooms within petals eight.`,
    elaborationEnglish: ``,
    elaborationTamil: `தியானப் பொருள் பிராசாத கலைகள் பன்னிரண்டிலும் நிறைந்து, எட்டிதழ்த் தாமரையாகிய இதய கமலத்திலும் பொருந்தி வெளிப்படச் செய்கின்ற முறை, திசையெட்டும், அவற்றைக் காக்கின்ற தேவர் எண்மரும், அவர்தம் ஊர்தி முதலியனவும், ஐம்பெரும்பூதம், இருசுடர், உயிர் ஆகிய எட்டுப் பொருள்களும் ஆகிய அனைத்துமாய் உள்ள முதல்வனாகிய சிவபிரானை வெளிப்படச் செய்யும் முறையேயாம்.`,
  },
  {
    id: 2533, tantraId: 8, verseNumber: 2532,
    tamil: `ஏழுஞ் சகளம் இயம்பு கடந்தெட்டில்
வாழும் பரமென் றதுகடந் தொன்பதில்
ஊழி பராபரம் ஓங்கிய பத்தினில்
தாழ்வது வான தனித்தன்மை தானே`,
    transliteration: `ēḻuñ cakaḷam iyampu kaṭanteṭṭil
vāḻum parameṉ ṟatukaṭan toṉpatil
ūḻi parāparam ōṅkiya pattiṉil
tāḻvatu vāṉa taṉittaṉmai tāṉē`,
    english: `2532: Centers Beyond Seventh are Formless States (Niradhara)
The Centers Seven are of Form (Svarupa) possessed;
Transcend them;
And beyond in Eighth is Param;
In Ninth is Paraparam, that is Void;
The exalted Tenth is State of Oneness
Where Anava is finally shed.`,
    elaborationTamil: `வைதிக முறையில் வழிபடினும், இதய கமலத்தின் எட்டிதழ்களில் கிழக்கு முதலாகத் தொடங்கி வலமாக ஏழ் எண்ணி ஏழாவதாகிய வட இதழ் ஈறாக உள்ள இதழ்களில் உள்ளவர்களாக மேற்சொல்லப்பட்ட திசைக் காவலர்களைச் சகலவருக்கத்து ஆன்ம வர்க்கத்தவராகவும், அடுத்த வடகீழ் இதழில் உள்ள ஈசானனை அவரின் மேம்பட்ட பிரளயாகல உருத்திரனாவும், எட்டையும் கடந்து மேலாக ஓங்கி நிற்கும் உயர்புற இதழில் சீகண்ட உருத்திரரை வைத்துச் சிவனாகவும், கீழ்நோக்கித் தூங்கும் கீழ்ப்புற இதழில் ஆதார சத்தியை வைத்து அச்சத்தியாகவும் பாவித்து வழி படின் சிறப்புடைய சைவ வழிபாடாக அமையும்.`,
  },
  {
    id: 2534, tantraId: 8, verseNumber: 2533,
    tamil: `பல்லூழி பண்பன் பகலோன் இறையவன்
நல்லூழி ஐந்தினுள் ளேநின்ற வூழிகள்
செல்லூழி அண்டத்துக் சென்றவவ் வூழியுள்
அவ்வூழி யுச்சியு ள்ஒன்றிற் பகவனே`,
    transliteration: `pallūḻi paṇpaṉ pakalōṉ iṟaiyavaṉ
nallūḻi aintiṉuḷ ḷēniṉṟa vūḻikaḷ
cellūḻi aṇṭattuk ceṉṟavav vūḻiyuḷ
avvūḻi yucciyu ḷoṉṟiṟ pakavaṉē`,
    english: `2533: God is Timeless Eternity
He lasts through aeons countless;
He is the Sun; He is the Lord;
Within the five Major Aeons
Were many aeons minor
The universe through several aeons passed;
In the aeon above aeons countless,
Was (God) Bhagava, unique.`,
    elaborationTamil: `முதற்கடவுளாவான் உலகிற்குப் பலவகையான ஊழிகளைப் பகுத்து வைத்துத்தான் அவற்றில் அகப்படாது நிற்பவன். அங்ஙனம் பகுக்கப்பட்ட ஊழிகள் பெரும்பான்மையாக ஐந்தாகும். அவை நிவிர்த்திகலை யூழி முதலாக, சாந்தியதீதைகலை ஊழி ஈறானவையாம். அவற்றில் ஒன்றிலும் உள்ளாய் நிகழும் ஊழிகள் பல. ஒவ்வோர் ஊழியையும் கடந்து அனைத்து ஊழிகளும் முடிந்த பின்பும் அவற்றில் மாயையில் அனைத்து உலகங்களும் ஒடுங்கவும் தான் ஒடுங்காது மேல் நிற்பவன் எவனோ, அவனே முழுமுதற்கடவுள்.`,
  },
  {
    id: 2535, tantraId: 8, verseNumber: 2534,
    tamil: `புரியும் உலகினிற் பூண்டவெட் டானை
திரியுங் களிற்றொடு தேவர் குழாமும்
எரியு மழையும் இயங்கும் வெளியும்
பரியுமா காசத்திற் பற்றது தானே`,
    transliteration: `puriyum ulakiṉiṟ pūṇṭaveṭ ṭāṉai
tiriyuṅ kaḷiṟṟoṭu tēvar kuḻāmum
eriyu maḻaiyum iyaṅkum veḷiyum
pariyumā kācattiṟ paṟṟatu tāṉē`,
    english: `2534: Seek Him Wherever He is
He is in this world
Yet if He is beyond reach,
Seek Him in Heaven,
Where the elephants roam
And the Celestials wander,
Where fire, rain and wind abide;
In that Space seek Him.`,
    elaborationTamil: `முதற் கடவுளால் ஆக்கி அளிக்கப்படும் உலகத்தின் திசைகள் எட்டாகப் பாகுபட்டு உள்ளன. 'அத்திசைகளில் எட்டு யானைகள் நின்று உலகத்தைத் தாங்குகின்றன' என்பதும், 'அந்த யானைகளைத்தங்கள் ஊர்திகளாகக் கொண்டு உலாவும் தலைவர்கள் உளர்' என்பதும் இருக்கட்டும். நெருப்பும், நீரும், ஓயாது இயங்கும் காற்றும் ஆகாசமாகிய வெளியைப் பற்றாகக் கொண்டுதான் இயங்குகின்றன. அதுபோல, அனைத்திற்கும் பற்றுக்கோடாய் உள்ளவன் அனைத்து ஊழிகளையும் கடந்து நிற்கின்ற அவனே.`,
  },
  {
    id: 2536, tantraId: 8, verseNumber: 2535,
    tamil: `ஊறு மருவி யுயர்வரை யுச்சிமேல்
ஆறின்றிப் பாயும் அருங்குளம் ஒன்றுண்டு
சேறின்றிப் பூத்த செழுங்கொடித் தாமரைப்
பூவின்றிச் சூடான் புரிசடை யோனே`,
    transliteration: `ūṟu maruvi yuyarvarai yuccimēl
āṟiṉṟip pāyum aruṅkuḷam oṉṟuṇṭu
cēṟiṉṟip pūtta ceḻuṅkoṭit tāmaraip
pūviṉṟic cūṭāṉ puricaṭai yōṉē`,
    english: `2535: The Eight-Petalled Bloom is Dear to Siva
There on the lofty top of Mount (Meru) within
Is a pond no stream feeds;
And there is a lotus bloom
From no soil mud springs;
Without that bloom,
He decks not Himself
He of matted locks.`,
    elaborationTamil: `சுரந்து பாய்கின்ற அருவியை உடைய, உயர்ந்த மலை உச்சிக்குமேலே, தனக்கு வருவாயாகும் நதி எதுவும் இல்லாமல் தானே நிறைந்து, தனது நீரைக் கீழ் நிலங்கட்குப் பாய விடுகின்ற ஓர் அதிசயக் குளம் உண்டு. அக்குளத்தில் சேறும், கிழங்கும், இல்லாமலே செழிப்பான ஒரு கொடியிற் பூத்த அதிசயத் தாமரையும் ஒன்று உண்டு. அந்தத் தாமரைப் பூவைத் தவிர வேறு பூக்களைச் சிவன் விரும்பிச் சூடுதல் இல்லை.`,
  },
  {
    id: 2537, tantraId: 8, verseNumber: 2536,
    tamil: `ஒன்றும் இரண்டும் ஒருங்கிய காலத்து
நின்றும் இருந்தும் நிலம்பல பேசினும்
வென்று மிருந்து விகிர்தனை நாடுவர்
சென்றும் இருந்தும் திருவடை யோரே`,
    transliteration: `oṉṟum iraṇṭum oruṅkiya kālattu
niṉṟum iruntum nilampala pēciṉum
veṉṟu miruntu vikirtaṉai nāṭuvar
ceṉṟum iruntum tiruvaṭai yōrē`,
    english: `2536: Holy Jivas Ever Think of God
When the One and Two (Siva and Jiva) intermingle,
Standing and sitting
Or in worldly talk indulging,
The holy Jivas their senses conquer
And seek Lord;
Remaining or leaving
They blessed ever are.`,
    elaborationTamil: `மும்மலங்களும் இறைவனது திருவுள்ளத்தோடு ஒத்துப்போகும் காலத்தில், அவனது திருவருளைப்பெற்று நிற்கும் பெரியோர்கள் உலகத்தார் ஆங்காங்கே நின்று கொண்டும், இருந்து கொண்டும், தங்கள் வாய்க்கு வந்த எவற்றைப் பேசினாலும் அவற்றைப்பொருட்படுத்தாது, ஐம்புலன்களை வெல்லுதலும் செய்து, நடந்தாலும், இருந்தாலும் சிவனை உணர்ந்தேயிருப்பர்.`,
  },
  {
    id: 2538, tantraId: 8, verseNumber: 2537,
    tamil: `தொற்பத விசுவன் றைசதன் பிராஞ்ஞன்
நற்பத விராட்டன்பொன் கர்ப்பனவ் யாகிர்தன்
பிற்பதஞ் சொலிதையன் பிரசா பத்தியன்
பொற்புவி சாந்தன் பொருதபி மானியே`,
    transliteration: `toṟpata vicuvaṉ ṟaicataṉ pirāññaṉ
naṟpata virāṭṭaṉpoṉ karppaṉav yākirtaṉ
piṟpatañ colitaiyaṉ piracā pattiyaṉ
poṟpuvi cāntaṉ porutapi māṉiyē`,
    english: `2537: Souls in the Three Mukti States
Visvan, Dhaisathan and Prajnan
They are in Tvampada State;
Virattan, Hranya Garbhan, Avyakritan
They are in Tat-Pada State;
Idayan, Prajapathyan and Santan of Golden World
They are in Asi-Pada State;
Yet are they all but Abhimanis,
Souls that are aspirants still.`,
    elaborationTamil: `வியாத்தன், தைசதன், பிராஞ்ஞன், விராட்டன், இரணிய கருப்பன், அவ்வியாகிருதன் இதயன், பிரசாபதி, சாந்தன் இம்முத்திறத்து ஒன்பது பெயர்களும் சீவ சாக்கிரம் முதலிய முத்திறத்து ஒன்பது அவத்தைகளிலும் சிவன் தான் காட்சிப்படும் முறையால் எய்தும் பெயர்களாம். ஆகவே, அவனை அத்தன்மையனாகக் காணும் காட்சியில் சீவனும் சார்ந்ததன் வண்ணமாம் தன் றன்மையால் அப்பெயர்களைப்பெற்று நிற்கும்.`,
  },
  {
    id: 2539, tantraId: 8, verseNumber: 2538,
    tamil: `நவமாம் அவத்தை நன்வாதி பற்றிற்
பவமா மலங்குணம் பற்றற்றுப் பற்றாத்
தவமான சத்திய ஞானப் பொதுவிற்
றுவமார் துரியஞ் சொருபம தாமே`,
    transliteration: `navamām avattai naṉvāti paṟṟiṟ
pavamā malaṅkuṇam paṟṟaṟṟup paṟṟāt
tavamāṉa cattiya ñāṉap potuviṟ
ṟuvamār turiyañ corupama tāmē`,
    english: `2538: Beyond Ninth State
As nine states beginning with Jagrat are experienced,
Attachment to Malas and Gunas,
That emanate birth, vanish;
In Transcendental Turiya State
Then Void (Satya-Jnana-Podu) succeeds,
Truth and Jnana filled
Where Jiva and Siva one are;
In Turiyas rest
Jiva and Siva are two,
That now in Void is one
Manifestness (Svarupa).`,
    elaborationTamil: `மேற்கூறிய முக்கூற்று ஒன்பான் அவத்தைகளில் முதற்கூறாகிய 'சீவ அவத்தை' எனப்படும் யோகாவத்தையில் நிற்பினும் பிறப்பு உண்டாகவே செய்யும். அதனால் குரு உபதேசத்தின் வழியாகச் சிவ அவத்தை ஆகிய நின்மலாவத்தையை அடைந்து, 'யான், எனது' என்னும் பற்றுக்களை விடுத்து, அப்பற்றுக்கள் சிறிதும் இல்லாத சிவயோகமாகிய உண்மை ஞான வெளியில் நீ அதுவாகி அடங்கி நில். அந்நிலையே சிவ துரியமாகும். அதன்பின் துரியாதீத நிலை எளிதில் கைவர, பரம சிவனை அடையும் உண்மை நிலை உண்டாகும்.`,
  },
  {
    id: 2540, tantraId: 8, verseNumber: 2539,
    tamil: `சிவமான சிந்தையிற் சீவன் சிதைய
பவமான மும்மலம் பாறிப் பறிய
நவமான அந்தத்தின் நற்சிவ போதந்
தவமான மவையாகித் தானல்ல வாகுமே`,
    transliteration: `civamāṉa cintaiyiṟ cīvaṉ citaiya
pavamāṉa mummalam pāṟip paṟiya
navamāṉa antattiṉ naṟciva pōtan
tavamāṉa mavaiyākit tāṉalla vākumē`,
    english: `2539: Dawn of Sivajnana
As in the thought of Siva
Jiva merges,
The Malas Three,
That to birth gives rise,
Flee away;
At the end of avastas nine
Is Siva-bodha (Awareness or Jnana);
Jiva attains that
And Himself no more is.`,
    elaborationTamil: `மேற்கூறிய சிவ துரியத்தில் சீவன் ''அவனே தானே ஆகிய அந்நெறி - ஏகனாகி'' நிற்றலால் 'தான்' என்பதொரு முதல் இல்லையாய்விட, ''மல மாயை தன்னொடு வல்வினையின்றே ''* என்றபடி. பிறப்பிற்குக் காரணமாய் நின்ற மும்மலங்களும் அடியோடு கெட்டொழியும். ஒழியவே சீவபோதம் பராவத்தையின் இறுதியில் நிகழும் சாந்த சிவ போதமேயாம். அதனால் அந்நிலையில் அந்த சாகிய சீவன் செய்யும் செயல்களும் பிறப்பிற்கு ஏதுவாம் ஆகாமிய வினையாகாது சிவ போதத்தை நினைப்பிக்கின்ற தவங்களேயாய், மற்றும் தான் செய்தன ஆகாது சிவன் செய்தனவேயாகி விடும்.`,
  },
  {
    id: 2541, tantraId: 8, verseNumber: 2540,
    tamil: `முன்சொன்ன வொன்பானின் முன்னுறு தத்துவந்
தன்சொல்லில் எண்ணத்தகாவொன்பான் வேறுள
பின்சொல்ல லாகுமிவ் வீரொன்பான் பேர்த்திட்டுத்
தன்செயத வாண்டவன் றான்சிறந் தானே`,
    transliteration: `muṉcoṉṉa voṉpāṉiṉ muṉṉuṟu tattuvan
taṉcollil eṇṇattakāvoṉpāṉ vēṟuḷa
piṉcolla lākumiv vīroṉpāṉ pērttiṭṭut
taṉceyata vāṇṭavaṉ ṟāṉciṟan tāṉē`,
    english: `2540: Nine Avasta Cluster Beyond
Beyond the nine states aforesaid
Are nine that defy thought;
Of these shall be said in detail below;
Great indeed is the Lord
Who these twice-nine States made.`,
    elaborationTamil: `இவ்வதிகாரத்து முதற்கண் சொல்லப்பட்ட ஒன்பது அவத்தைகளைப் போல அவற்றுக்கு முன்னே சீவன் தன் சொல்லால் சொல்லி எண்ணக் கூடாத ஒன்பது நிலைகள் உள்ளன. ஆகவே, அனைத்தையும் தொகுத்து நோக்கும்பொழுது பதினெட்டாகின்ற இவைகளினின்றும் சீவர்களைப் பிரித்துத் தானாகச் செய்துவரும் தலைவனாகிய சிவன் முத்தி நிலையில் தான் ஒருவனேயாகி விளங்கி நிற்கின்றான்.`,
  },
  {
    id: 2542, tantraId: 8, verseNumber: 2541,
    tamil: `உகந்த ஒன்பதும் ஐந்தும் உலகம்
பகர்ந்த பிரானென்னும் பண்பினை நாடி
அகந்தெம் பிரானென்பன் அல்லும் பகலும்
இகந்தன வல்வினை யோடறுத் தானே`,
    transliteration: `ukanta oṉpatum aintum ulakam
pakarnta pirāṉeṉṉum paṇpiṉai nāṭi
akantem pirāṉeṉpaṉ allum pakalum
ikantaṉa valviṉai yōṭaṟut tāṉē`,
    english: `2541: Lord Spoke of Nine States
The nine states from the five (states of Jiva) evolved
Of them Lord spoke
And world rejoiced;
"My Lord, My Lord"--
Thus I prayed day and night;
And He severed my fetters strong.`,
    elaborationTamil: `'உயிர்களின் பொருட்டு அவற்றிற்கு ஏற்புடைய வித்தை பதினான்கையும் செய்தருளிய முதல்வன்' என்று உயர்ந்தோர் யாவராலும் சொல்லப்படுகின்ற அத்தன்மையை உணர்ந்து நான் சிவனை ஏனைத் தேவரினின்றும் வேறு பிரித்து, 'அவனே எங்கள் கடவுள்' என்று இரவும், பகலும் ஓயாது சொல்லிக் கொண்டிருப்பேன். அதனால், வரும் பிறப்புக்களில் என்னை வந்து பற்ற நின்ற வலிய வினைகள் இல்லாதொழிந்தன. மற்றும் இப்பொழுது தோன்றும் வினைகளையும் அவன் அழித்துவிட்டான்.`,
  },
  {
    id: 2543, tantraId: 8, verseNumber: 2542,
    tamil: `நலம்பல காலந் தொகுத்தன நீளங்
குலம்பல வண்ணங் குறிப்பொடுங் கூடும்
பலம்பல பன்னிரு கால நினையும்
நிலம்பல வாறின் நீர்மையன் றானே`,
    transliteration: `nalampala kālan tokuttaṉa nīḷaṅ
kulampala vaṇṇaṅ kuṟippoṭuṅ kūṭum
palampala paṉṉiru kāla niṉaiyum
nilampala vāṟiṉ nīrmaiyaṉ ṟāṉē`,
    english: `2542: Many Paths to God
Many the paths they laid
In Time's Corridor long;
Many the sects
That sought Him to reach;
Think of Him constant, day and night;
He diverse stood in lands many.`,
    elaborationTamil: `சிவன் உயிர்களுக்கான நல்லவழிகள் பலவற்றைச் சொல்லியருளிய காலம் எல்லையறியப்படாத பழமையுடையது. ('படைப்புக் காலம்' என்றபடி) உயிர்த் தொகுதிகள் அவ்வழிகள் பலவற்றில் தம் கருத்திற்கு ஏற்புடையவற்றைப் பற்றி அவற்றிற்கு ஏற்ற பயன்களை அடைந்து வருகின்றன. பெரும் பொழுது ஆறும், சிறு பொழுது ஆறுமாகிய பன்னிரண்டு காலங்களிலும் சிவபெருமானை நினைவதால் விளையும் பயன்களும் பல அங்ஙனம் நினைத்தற்குரிய இடங்களும் பல என்றாலும் ஆறு இடங்களில் (ஆறு ஆதாரங்களில்) சிவன் இனிது விளங்குபவனாய் இருக்கின்றான்.`,
  },
  {
    id: 2544, tantraId: 8, verseNumber: 2543,
    tamil: `ஆதி பராபர மாகும் பராபரை
சோதி பரமுயிர் சொல்லுநற் றத்துவம்
ஓதுங் கமைமாயே யோரிரண் டோ ரமுத்தி
நீதியாம் பேதமொன் பானுடன் ஆதியே`,
    transliteration: `āti parāpara mākum parāparai
cōti paramuyir collunaṟ ṟattuvam
ōtuṅ kamaimāyē yōriraṇ ṭō ramutti
nītiyām pētamoṉ pāṉuṭaṉ ātiyē`,
    english: `2543: Nine Super Tattva Cluster
The Primal Paraparam, Paraparai
Param the Light, Jiva and Tattvas,
The Kala, the Mayas Two and Mukti
These are categories nine
To the Primal One belong.`,
    elaborationTamil: `எல்லாவற்றிற்கும் மேலான முதற்பொருள் தன்னியல்பில் 'சிவம்' என்றும், 'சத்தி' என்றும் இரு கூற்றை யுடையதாய் இருக்கும். அவற்றுள் சத்தி தனது ஒரு சிறு கூற்றில் 'ஆதி' என்னும் பெயருடையதாய் நின்று, 'அறிவு அருள், உயிர், தத்துவங்கள் வேதம் முதலிய நூல்கள், பஞ்சகலைகள், சுத்தமாயை, அசுத்த மாயை, பல சமயத்தாரும், ஆராய்ந்து கூறும் முத்திநிலைகள்' என்னும் ஒன்பது வகையாய் நிற்கும்.`,
  },
  {
    id: 2545, tantraId: 8, verseNumber: 2544,
    tamil: `தேராத சிந்தை தெளியத் தெளிவித்து
வேறாத நரக சுவர்க்கமும் மேதினி
ஆறாப் பிறப்பும் உயிர்க்கரு ளால்வைத்தான்
வேறாத் தெளியார் வினையுயிர் பெற்றதே`,
    transliteration: `tērāta cintai teḷiyat teḷivittu
vēṟāta naraka cuvarkkamum mētiṉi
āṟāp piṟappum uyirkkaru ḷālvaittāṉ
vēṟāt teḷiyār viṉaiyuyir peṟṟatē`,
    english: `2544: Grace Abounding
My inconstant thoughts
He constant made,
Clear vision gave;
He created hell and heaven
And endless births too
In Grace Abounding;
Those who these perceive not
Are in Karma's wheel forever caught.`,
    elaborationEnglish: ``,
    elaborationTamil: `அநாதியே பற்றிய மலத்தால் அறியாமையை யுடையதாய் நிற்கின்ற உயிர்களின் அறிவு அவ்வறியாமை நீங்கித் தெளிவடைதற் பொருட்டுத் தெளிவிற்கு வித்தாக, தம்முள் மாறுபட்ட நரகலோக சுவர்க்க லோகங்களிலும் பூலோகத்திலும் வினைக்கீடாகச் சென்று பிறக்கும் பிறப்புக்களையும் சிவன் உயிர்கட்கு அமைத்திருக் -கின்றான். அங்ஙனம் அமைத்தது அருள் காரணமாகவேயாம். அதனை வன்கண்மையாக நினைக்கும் தங்கள் நினைப்பை விட்டு, அருளாகத் தெளியமாட்டாதார் தெளிதற்கு வாயிலான மானுடப் பிறப்பைப் பெற்றதும் வினையின் விளைவேயாம்.`,
  },
  {
    id: 2546, tantraId: 8, verseNumber: 2545,
    tamil: `ஒன்பான் அவத்தையுள் ஒன்பான் அபிமானி
நன்பாற் பயிலு நவதத் துவமாதி
ஒன்பானில் நிற்பதோர் முத்துரி யத்துறச்
செம்பாற் சிவமாதல் சித்தாந்த சித்தியே`,
    transliteration: `oṉpāṉ avattaiyuḷ oṉpāṉ apimāṉi
naṉpāṟ payilu navatat tuvamāti
oṉpāṉil niṟpatōr mutturi yattuṟac
cempāṟ civamātal cittānta cittiyē`,
    english: `2545: Goal of Siddhanta Philosophy
In the nine states of experience
Jiva as aspirant (abhimani) stands;
The nine categories afterward stated
That to the Primal Lord belong;
When Jiva that stands in states nine
Reaches the Turiya States Three,
Then shall he Siva become;
This the goal of Siddhanta (Philosophy).`,
  },
  {
    id: 2547, tantraId: 8, verseNumber: 2546,
    tamil: `நாசி நுனியினின் நான்குமூ விரலிடை
ஈசன் இருப்பிடம் யாரும் அறிகிலர்
பேசி யிருக்கும் பெருமறை யம்மறை
கூசி யிருக்குங் குணமது வாமே`,
    transliteration: `nāci nuṉiyiṉiṉ nāṉkumū viraliṭai
īcaṉ iruppiṭam yārum aṟikilar
pēci yirukkum perumaṟai yammaṟai
kūci yirukkuṅ kuṇamatu vāmē`,
    english: `2546: Mystery of Lord's Abode
At the tip of nose (Ajna Center)
Is the breath, twelve finger-breadth long,
That Lord's abode is;
None knows this;
The Vedas that in expansiveness truths expound,
Of this was hesitant to speak;
Such indeed is Lord's greatness.`,
    elaborationEnglish: ``,
    elaborationTamil: `மூன்றாம் தந்திரத்தில், நாசிக்கதோமுகம் பன்னிரண்டங்குலம்''8 என்னும் மந்திரத்திற் கூறியபடி, 'மூக்கின் நுனிக்குக் கீழே பன்னிரண்டங்குலத்தில் உள்ள இருதயம் சிவன் எழுந்தருளியிருக்கும் இடம்' என்பதை உங்களுள் ஒருவரும் அறியார். (அதனால் அவர்கள் புறத்தே உள்ள இடங்களில் சிவனைக் காணும் அளவிலே அமைந்து, அதனையே சிவக்காட்சியாகக் கொண்டு இருந்துவிடுகின்றனர்.) ஆயினும் பெரிய மறைநூல்கள் மேற்கூறிய ஈசன் இருப்பிடத்தைச் சொல்லியிருக்கின்றன. எனினும் அந்த மறை நூல் அந்த இடத்தை அணுக இயலாதவர்கட்கு அதனைக் கூற நாணம் உற்று, வெளிப்படையாக அன்றிக் குறிப்பாகவே கூறியமைந்தன. அது மறைநூல்கட்கு இயல்பு.`,
  },
  {
    id: 2548, tantraId: 8, verseNumber: 2547,
    tamil: `கருமங்கள் ஒன்று கருதுங் கருமத்
துரிமையுங் கன்மமும் முன்னும் பிறவிப்
கருவினை யாவது கண்டகன் றன்பின்
புரிவன கன்மக் கயத்துட் புகுமே`,
    transliteration: `karumaṅkaḷ oṉṟu karutuṅ karumat
turimaiyuṅ kaṉmamum muṉṉum piṟavip
karuviṉai yāvatu kaṇṭakaṉ ṟaṉpiṉ
purivaṉa kaṉmak kayattuṭ pukumē`,
    english: `2547: Away From Karmas
The Karmas,
The thoughts rights and deeds of Karmas
Are alike the seeds of births to be;
Seeing that,
Away from them;
Will what you do ever after
Reach the Karma Pond?`,
    elaborationTamil: `உயிர்களால் செய்யப்படும் செயல்கள் யாதேனும் ஒரு பயனைக் கருதிச் செய்யும் செயல்களாகுமிடத்து 'அச்செயல்களைச் செய்தோன் அவனே' என்னும் உரிமை தோன்றுதலையும், செய்த செயல்களும், 'இனி வரும்' எனக் கருதப்படுகின்ற பிறவிக்கு வித்தாம் ஆகாமியம் ஆதலையும் உணர்ந்து, அச்செயல்களில் பற்று வையாது 'எச்செயலையும் செய்யும் வாய்ப்பினை நமக்கு அளித்தவன் சிவன்' என்பதை யுணர்ந்து, அவனிடத்து அன்பு செய்து, எச்செயலையும் அவன் பணியாகச் செய்யின் அம்முறையில் அறிந்தோ, அறியாமலோ நிகழும் செயல்கள் யாவும் வினை நீக்கத்திற்கு வாயிலான தவமாகி, அவற்றைச் செய்தவனை வினை நீக்கத்தில் சேர்ப்பிக்கும்.`,
  },
  {
    id: 2549, tantraId: 8, verseNumber: 2548,
    tamil: `மாயை மறைக்க மறைந்த மறைப்பொருள்
மாயை மறைய வெளிப்படும் அப்பொருள்
மாயை மறைய மறையவல் லார்கட்குக்
காயமும் இல்லை கருத்தில்லை தானே`,
    transliteration: `māyai maṟaikka maṟainta maṟaipporuḷ
māyai maṟaiya veḷippaṭum apporuḷ
māyai maṟaiya maṟaiyaval lārkaṭkuk
kāyamum illai karuttillai tāṉē`,
    english: `2548: Make Maya Vanish
When Maya veils Jiva,
The Truth of Vedas remains hidden;
When Maya leaves,
The Truth of Himself reveals;
Those who can make Maya vanish
Merge in God;
No more is body; no more is mind.`,
    elaborationTamil: `வேதங்களால் முடிநிலைப் பொருளாகக் கொள்ளப் பட்ட முதற்பொருள் உயிர்கட்கு வேறாய் இன்றி அவைகளிடத் திற்றானே இருக்கின்றது. ஆயினும், மாயா காரியங்களாகிய கருவிக் கூட்டங்கள் உயிரினது அறிவைத் தம் வயப்படுத்தியே வைத்திருத்தலால் உயிர்கள் அம்முதற்பொருளை அறியாதிருக்கின்றன. அதனால் முதற்பொருள் மறைந்து நிற்கும் பொருளாக அறியப்படுகின்றது. மாயா காரியங்களாகிய கருவிக் கூட்டங்களின் வயப்படாது விடுபட்டவர்க்கு அக்கருவிக் கூட்டங்கள் மறைந்துவிட, முதற்பொருள் வெளிப்பட்டுத் தோன்றும். அதன் பின்பும் அக்கருவிக் கூட்டங்கள் தம்மை மயக்காதபடி அம்முதற் பொருளுக்குள்ளே அடங்கி நிற்க வல்லவர்கட்கு உடம்பு இருந்தும் இல்லையாம். அதனால் அவை பற்றி யெழுகின்ற, 'யான், எனது' என்னும் செருக்கும் இல்லையாம்.`,
  },
  {
    id: 2550, tantraId: 8, verseNumber: 2549,
    tamil: `மோழை யடைந்து முழைதிறந் துள்புக்குக்
கோழை யடைகின்ற தண்ணற் குறிப்பினில்
ஆழ அடைந்தங் கனலிற் புறஞ்செய்து
தாழ அடைப்பது தன்வலி யாமே`,
    transliteration: `mōḻai yaṭaintu muḻaitiṟan tuḷpukkuk
kōḻai yaṭaikiṉṟa taṇṇaṟ kuṟippiṉil
āḻa aṭaintaṅ kaṉaliṟ puṟañceytu
tāḻa aṭaippatu taṉvali yāmē`,
    english: `2549: Kecari Mudra in Kundalini Yoga
Coursing the Prana Stream into the Eye-brow Center
And opening the uvula cavity
Where phlegm gathers,
Stilling the breath there
In the way Yoga Guru taught,
And warming it in the Fire (Kundalini) within
And restraining it to a measure low
Is to attain divine strength indeed.`,
    elaborationTamil: `ர் புறம் போய் வீணாவதற்கு உரிய, வயல்களின் சிறு புழை போல, விந்து வெளிச்சென்று வீணாகின்ற வழியாகிய குறியைச் செயற்படாமல் தடுத்து, பிராணனைச் சுழுமுனை வழியாகச் செலுத்தி அதனோடே மேல்நிலமாகிய ஆஞ்ஞையில் உணர்வினால் சென்று புகுந்து, அங்கு நிற்கின்ற நிலை சலித்தலை நீக்க முயலு மிடத்துச் சிவ நினைவால் அதனை அடியோடு நீக்கி, உடம்பையும் விரைவில் வீழ்ந் தொழியாதபடி யோகக் கனலால் கற்பஞ்செய்து தன்னைச் சிவத்திற்குள்ளே அடைத்து வைத்தலே ஒருவனுக்கு உண்மையான தன்வலிமையாகும்.`,
  },
  {
    id: 2551, tantraId: 8, verseNumber: 2550,
    tamil: `காயக் குழப்பனைக் காயநன் னாடனைக்
காயத்தி னுள்ளே கமழ்கின்ற நந்தியைத்
தேயத்து ளேயெங்குந் தேடித் திரிவர்கள்
காயத்துள் நின்ற கருத்தறி யாரே`,
    transliteration: `kāyak kuḻappaṉaik kāyanaṉ ṉāṭaṉaik
kāyatti ṉuḷḷē kamaḻkiṉṟa nantiyait
tēyattu ḷēyeṅkun tēṭit tirivarkaḷ
kāyattuḷ niṉṟa karuttaṟi yārē`,
    english: `2550: Lord is Within; Seek Him not Elsewhere
He who is in the Body-mix
He who rules the Body-Land,
He who within the body beams
He, the Nandi,
Him they seek in lands all;
They know not,
He within the body stands.`,
  },
  {
    id: 2552, tantraId: 8, verseNumber: 2551,
    tamil: `ஆசூசம் ஆசூசம் என்பார் அறிவிலார்
ஆசூச மாமிடம் ஆரும் அறிகிலார்
ஆசூச மாமிடம் ஆரும் அறிந்தபின்
ஆசூச மானிடம் ஆசூச மாமே`,
    transliteration: `ācūcam ācūcam eṉpār aṟivilār
ācūca māmiṭam ārum aṟikilār
ācūca māmiṭam ārum aṟintapiṉ
ācūca māṉiṭam ācūca māmē`,
    english: `2551: Mystery of Muladhara
"Unclean, unclean," the ignorant say
They know not the place "unclean" is,
When they know the (Yogic) mysteries
Of that place "unclean"
Then shall they find,
The human birth itself is unclean.`,
    elaborationEnglish: `They who know the yogic do not feel that human birth is unclean.`,
    elaborationTamil: `அறிவில்லாதவர்கள் தங்கள் உடம்பு அசுத்தத்தைத் தீண்டிவிட்டதனால் 'தீட்டு உண்டாகிவிட்டது தீட்டு உண்டாகி விட்டது' என்று சொல்வார்கள். அவர்களில் ஒருவருமே, உண்மையில் தீட்டு எங்கு உண்டாகின்றது' என ஆராய்ந்தறியமாட்டார். யாராயினும் அதனை ஆராய்ந்து அறிவார்களோயானால் 'உயிர் மக்கள் வடிவாய் உள்ள உடம்பைத் தீண்டியதே தீட்டு' என்பது அவர்கட்கு நன்கு புலப்பட்டுவிடும்.`,
  },
  {
    id: 2553, tantraId: 8, verseNumber: 2552,
    tamil: `ஆசூச மில்லை அருநிய மத்தருக்கு
ஆசூச மில்லை அரனை அர்ச் சிப்பவர்க்கு
ஆசூச மில்லையாம் அங்கி வளர்ப்போர்க்கு
ஆசூச மில்லை அருமறை ஞானிக்கே`,
    transliteration: `ācūca millai aruniya mattarukku
ācūca millai araṉai arc cippavarkku
ācūca millaiyām aṅki vaḷarppōrkku
ācūca millai arumaṟai ñāṉikkē`,
    english: `2552: Muladhara is not Unclean
Uncleanness none is for those
Who ritual discipline observe;
Uncleanness none is for those
Who Hara worship;
Uncleanness none is for those
Who the sacred Fire tend;
Uncleanness none is for those
Who in Vedic Jnana versed are.`,
    elaborationTamil: `சிவனது முதன்மையை உணர்ந்து அவனைச் 'சரியை, கிரியை, யோகம், ஞானம்' என்னும் நால்நெறியில் எவ்வகையில் நின்று வழிபடுவார்க்கும் புறத்தூய்மை வாயாவிடினும் அகம் திருவருளில் படிந்திருத்தலால் அவர்கட்கு எந்த வகையான அசுசியும் இல்லையாம்.`,
  },
  {
    id: 2554, tantraId: 8, verseNumber: 2553,
    tamil: `வழிபட்டு நின்று வணங்கு மவர்ககுச்
சுழிபட்டு நின்றதோர் தூய்மை தொடங்கும்
குழிபட்டு நின்றவர் கூடார் குறிகள்
கழிபட் டவர்க்கன்றிக் காணவொண் ணாதே`,
    transliteration: `vaḻipaṭṭu niṉṟu vaṇaṅku mavarkakuc
cuḻipaṭṭu niṉṟatōr tūymai toṭaṅkum
kuḻipaṭṭu niṉṟavar kūṭār kuṟikaḷ
kaḻipaṭ ṭavarkkaṉṟik kāṇavoṇ ṇātē`,
    english: `2553: When Purity Real Begins
For them that in Yogic Way stand,
Purity in Cranium top begins;
They who are sunk in pit of lust
Will Purity's goal reach not;
Only those who have sent Muladhara Fire
Up into Central Nadi of Sushumna
Will see Purity Real;
Others cannot.`,
    elaborationTamil: `முன்னர்ப் புறத்தொண்டுகளைச் செய்து, பின்பு அகத்தும், புறத்தும் சிவனை வழிபடுவார்க்குச் சுழித்தோடுகின்ற நீரில் மூழ்கினார்போலும் ஓர் உண்மைத் தூய்மை தொடங்குவதாகும். (பின்னர் அகத்தும், புறத்தும் அங்கி வளர்த்தலால் அத்தூய்மை முதிரும்.) இவைகளைச் செய்யாது புறத்தூய்மையை மட்டுமே வலியுறுத்திக் கூறு கின்ற நூல்களாகிய குழிகளில் வீழ்ந்தவர்கள் தூய்மையைப் பொருந்தார். இனி முற்கூறிய தூய்மையைப் பொருந்தியவர்களில்கூட, உருவம், அருவுருவம், அருவம் என்னும் குறிகளைக் கடந்து குறியிறந்து உணரும் உணர்வுடையார்க்கன்றிச் சிவனை நேர்படக் காணுதல் இயலாது.`,
  },
  {
    id: 2555, tantraId: 8, verseNumber: 2554,
    tamil: `தூய்மணி தூயனல் தூய ஒளிவிடும்
தூய்மணி தூயனல் தூரறி வாரில்லை
தூய்மணி தூயனல் தூரறி வார்கட்குத்
தூய்மணி தூயனல் தூயவு மாமே`,
    transliteration: `tūymaṇi tūyaṉal tūya oḷiviṭum
tūymaṇi tūyaṉal tūraṟi vārillai
tūymaṇi tūyaṉal tūraṟi vārkaṭkut
tūymaṇi tūyaṉal tūyavu māmē`,
    english: `2554: Lord is Real Pure
He is crystal pure, He is fire pure,
He emanates rays of Purity;
Where His source is, they know not,
They who know the Source,
Themselves,
Crystal pure and fire pure become.`,
    elaborationTamil: `உலகத்தில், மாசு நீங்கக் கழவுவப்பட்ட இரத்தினமும், தூய பொருள்களாலே வளர்க்கப்பட்ட தீயும் தூய ஒளியையே தரும். 'அதுபோல உடம்பினுள் தூய ஒளிகளைத் தரும் தூய இரத்தினமும், தூய தீயும் எவை' என்பதை அறிபவர் உலகருள் எவரும் இல்லை அவற்றை அறிய வல்லவர்கட்கு அவை தாம் தூயவாய் இருத்தலேயன்றி உடம்பிற்குத் தூய்மையைத் தருவனவாய் அமையும்.`,
  },
  {
    id: 2556, tantraId: 8, verseNumber: 2555,
    tamil: `தூயது வாளா வைத்தது தூநெறி
தூயது வாளா நாதன் திருநாமம்
தூயது வாளா அட்டமா சித்தியும்
தூயது வாளா தூயடிச் சொல்லே`,
    transliteration: `tūyatu vāḷā vaittatu tūneṟi
tūyatu vāḷā nātaṉ tirunāmam
tūyatu vāḷā aṭṭamā cittiyum
tūyatu vāḷā tūyaṭic collē`,
    english: `2555: Purity in Silentness
Purity in Silentness is the Way of Purity
Purity in Silentness is Lord's name;
Purity in Silentness are Siddhis eight;
Purity in Silentness are the Holy Feet.`,
    elaborationTamil: `'முதல்வனாகிய முக்கண்ணன் முன்னெறியாகிய* தனது நெறியை உலகிற்கு வைத்தது உயிர் தூயதாதற் பொருட்டேயாம். அந்நெறியிற் செல்வார்க்கு உறுதுணையாக அவன் வைத்தது அவனது திருப்பெயராகிய திருவைந்தெழுத்து மந்திரம். அந்த மந்திரத்தைப் பல்காலும் ஓதி உயிர் தூய்மையுற்றால் அட்டமா சித்திகள் தாமே வந்து அதனை அடையும். ஆதலின் உயிர் தூய்மை அடைவதற்கு முன்பு அங்ஙனம் தூயராயினார் சென்ற அடிச்சுவட்டில் செல்.`,
  },
  {
    id: 2557, tantraId: 8, verseNumber: 2556,
    tamil: `பொருளது வாய்நின்ற புண்ணியன் எந்தை
அருளது போற்றும் அடியவ ரன்றிச்
சுருளது வாய்நின்ற துன்பச் சுழியின்
மருளது வாச்சிந்தை மயங்குகின் றாரே. 45.`,
    transliteration: `poruḷatu vāyniṉṟa puṇṇiyaṉ entai
aruḷatu pōṟṟum aṭiyava raṉṟic
curuḷatu vāyniṉṟa tuṉpac cuḻiyiṉ
maruḷatu vāccintai mayaṅkukiṉ ṟārē. 45.`,
    english: `2556: Adore Lord and Receive Grace
The Quintessence of Truth is my Holy Father
Only they who adore Him
Are in His Grace accepted;
The rest,
Caught in whirl of misery,
In dark stupor lie.`,
    elaborationTamil: `மெய்ப் பொருளாய், என்றும் ஒரு பெற்றியனாய் நிற்பவன் சிவபெருமானே. அவனே எங்கட்குத் தந்தை. அவனது திருவருளைப் போற்றுகின்ற அடியவர்களே சுருண்டு சுருண்டு வருகின்ற கடலின் அலைபோல முடிவின்றி வருகின்ற பிறப்பாகிய துன்பச்சூழலினின்றும் நீங்குவர். அவனது திருவருளைப் போற்றாது ஒழிகின்றவர் எல்லாம் அச்சூழலில் அகப்பட்டுத் திகைக்கின்றார் ஆதலின் அவர் அருளுடையாராகாது மருளுடையவரேயாவர்.`,
  },
  {
    id: 2558, tantraId: 8, verseNumber: 2557,
    tamil: `வினையா மசத்து விளைவ துணரார்
வினைஞானந் தன்னில் வீடலுந் தேரார்
வினைவிட வீடென்னும் வேதமும் ஓதார்
வினையாளார் மிக்க விளைவறி யாரே`,
    transliteration: `viṉaiyā macattu viḷaiva tuṇarār
viṉaiñāṉan taṉṉil vīṭalun tērār
viṉaiviṭa vīṭeṉṉum vētamum ōtār
viṉaiyāḷār mikka viḷaivaṟi yārē`,
    english: `2557: Renounce Karma and Be Liberated
They know not evil fruits
Karma brings,
They choose not to find Jnana
For liberation from Karma;
"Renounce Karma and be liberated"
--This Vedic teaching they know not;
They who wallow in Karma
Will never the Rich Harvest reap.`,
    elaborationTamil: `'நிலையில்லனவாகிய பல வகை உடம்புகள் ஒன்றழிந்தபின் மற்றொன்று தோன்ற, அஃதழிந்தபின் வேறொன்று தோன்ற, இவ்வாறு முடிவின்றி வந்து உயிரை அலைக் கழிப்பது வினையே' என்பதையும், 'அந்த வினை பொருள்களை உற்றவா றுணரும் மெய்யுணர்வால் கெடும்' என்பதையும் ஆசான் அருள் பெறாதார் அறியமாட்டார். இனி, 'வினை நீக்கமே வீடுபேறாம்' எனக் கூறுகின்ற வேதத்தையும் அவர்கள் ஓதுவதில்லை ஆகவே, அவர்கள் வினையை ஆண்டு, அதிற்றானே மகிழ்கின்றவராவர். அவர் பின்னும் பின்னும் எல்லையின்றி வரும் துன்பவினை அறிய மாட்டார்.`,
  },
  {
    id: 2559, tantraId: 8, verseNumber: 2558,
    tamil: `பரகதி யுண்டென இல்லையென் போர்கள்
நரகதி செல்வது ஞாலம் அறியும்
இரகதி செய்திடு வார்கடை தோறும்
துரகதி யுண்ணத் தொடங்குவர் தாமே.`,
    transliteration: `parakati yuṇṭeṉa illaiyeṉ pōrkaḷ
narakati celvatu ñālam aṟiyum
irakati ceytiṭu vārkaṭai tōṟum
turakati yuṇṇat toṭaṅkuvar tāmē.`,
    english: `2558: Deny Not God
Those who say,
There is no Para State to be
Are for hell state destined;
All world knows this;
They shall begging go from door to door;
With horse's speed,
In search of food they run.`,
    elaborationEnglish: ``,
    elaborationTamil: `'பிறப்பிறப்பினின்றும் நீங்கிப் பரம்பொருளை அடைந்து இன்புற்றிருக்கும் நிலை உண்டு' என்று உண்மை நூல்களெல்லாம் கூறாநிற்கவும், 'அஃது இல்லை' எனப்பிணங்கி, மனஞ் சென்றவாறே செல்பவர்கள் நரகலோகத்தை அடைதல் உலகத்தில் உயர்ந்தோர் பலரும் நன்கறிந்தது நரகத்தின் நீங்கிப்பின்னும் அவர் மக்களாய்ப் பிறப்பின் கடைதொறும் சென்று இரக்கும் செயலையே உடையராவர். அங்ஙனம் இரக்குங்கால் வயிறு நிரம்பாமல் உணவு வேளை முடிவதற்குள் பலரிடம் சென்று இரக்க வேண்டி ஓடவும் தொடங்குவர்.`,
  },
  {
    id: 2560, tantraId: 8, verseNumber: 2559,
    tamil: `கூடகில் லார்குரு வைத்த குறிகண்டு
நாடகில் லார்நயம் பேசித் திரிவர்கள்
பாடகில் லாரவன் செய்த பரிசறிந்
தாடவல் லாரவர் பேறெது வாமே.`,
    transliteration: `kūṭakil lārkuru vaitta kuṟikaṇṭu
nāṭakil lārnayam pēcit tirivarkaḷ
pāṭakil lāravaṉ ceyta paricaṟin
tāṭaval lāravar pēṟetu vāmē.`,
    english: `2559: Follow Guru
They follow not the Way
Guru taught;
They seek not the Holy One;
Indulging in frivolous talk, they wander;
They sing not His holy deeds;
They who thus dance about
What will their desert be?`,
  },
  {
    id: 2561, tantraId: 8, verseNumber: 2560,
    tamil: `புறப்பட்டுப் போகும் புகுதுமென் னெஞ்சில்
திறப்பட்ட சிந்தையைப் தெய்வமென் றெண்ணி
அறப்பட்ட மற்றப் பதியென் றழைத்தேன்
இறப்பற்றி னேன்இங் கிதென்னென்கின் றானே`,
    transliteration: `puṟappaṭṭup pōkum pukutumeṉ ṉeñcil
tiṟappaṭṭa cintaiyaip teyvameṉ ṟeṇṇi
aṟappaṭṭa maṟṟap patiyeṉ ṟaḻaittēṉ
iṟappaṟṟi ṉēṉiṅ kiteṉṉeṉkiṉ ṟāṉē`,
    english: `2560: God Responds to Devotion
Into my thoughts He comes and goes;
In the constancy of my thoughts
I held Him as God;
"You my Holy Lord!"
Thus I besought Him;
And in my heart I held Him close;
"What is this here?" He asks.`,
    elaborationTamil: `பிராண வாயு வெளியே செல்லுங்கால் தானும் வெளிச்சென்றும், அஃது உள்ளே வருங்கால் தானும் உள்ளே வந்ததும் இவ்வாறு உழல்கின்ற எனது மனத்தின் அலைவுக்கிடையே அந்தப் பிராணனை அடக்கியதனால் நிலைபெற்ற சித்தத்தையே பரம் பொருளின் இருப்பிடமாகக் கருதி, அவ்விடத்தில் நின்றே, 'புண்ணியங்களின் பயனாய் எதிர்ப்படுகின்ற தேவதேவனே என்று அழைத்தேன் அங்ஙனம் ஒருமுறை யழைத்ததோடன்றித் தொடர்ந்து பன்முறை அழைத்து அவனை உள்ளத்தால் இறுகப் பற்றினேன் அதன்பின்பு அவன் தோன்றி, 'நீ இங்கு என்ன செய்கின்றார்' என்று வினாவுகின்றான்.`,
  },
  {
    id: 2562, tantraId: 8, verseNumber: 2561,
    tamil: `திடரடை நில்லாத நீர்போல் ஆங்கே
உடலிடை நில்லா உறுபொருள் காட்டிக்
கடலிடை நில்லா கலஞ்சேரு மாபோல்
அடலிடை வண்ணனும் அங்குநின் றானே.`,
    transliteration: `tiṭaraṭai nillāta nīrpōl āṅkē
uṭaliṭai nillā uṟuporuḷ kāṭṭik
kaṭaliṭai nillā kalañcēru māpōl
aṭaliṭai vaṇṇaṉum aṅkuniṉ ṟāṉē.`,
    english: `2561: Lord is the Haven for Soul's Ship
As water from upland
Downward flows,
Truth in body remains not;
That Truth He in me showed;
As the ship in the seas
That seeks the shores,
To my trouble-tossed soul
The Fire-Hued Lord
As sure goal stood.`,
    elaborationTamil: `மேட்டு நிலத்தில் பொழியப்பட்ட மழைநீர் அங்கு நிலைத்து நில்லாது நீங்குவதுபோல, வினையால் உடம்பினிடத்துச் சேர்க்கப்பட்ட உயிர் அதன்கண் நிலைத்து நில்லாது நீங்குவதாகும். ஆயினும், தழல் வண்ணனாகிய சிவனும் அவ்வுயிரோடு கூட அவ்வுடம்பின்கண் நிற்கின்றான். ஏனெனில், கடலிடத்தே நில்லாது கரையையே சேர்வதாகிய மரக்கலம் கடலிடை நின்றாருடன் தானும் நிற்பதுபோல, உயிரைப் பந்தத்தினின்றும் விடுவித்து வீட்டை அடைவித்தற் பொருட்டாம்.`,
  },
  {
    id: 2563, tantraId: 8, verseNumber: 2562,
    tamil: `தாமரை நூல்போல் தடுப்பார் பரந்தொடும்
போம்வழி வேண்டிப் புறமே யுழிதர்வர்
காண்வழி காட்டக்கண் காணாக் கலதிகள்
தீநெறி செல்வான் திரிகின்ற வாறே.`,
    transliteration: `tāmarai nūlpōl taṭuppār parantoṭum
pōmvaḻi vēṇṭip puṟamē yuḻitarvar
kāṇvaḻi kāṭṭakkaṇ kāṇāk kalatikaḷ
tīneṟi celvāṉ tirikiṉṟa vāṟē.`,
    english: `2562: They Seek Him Not--The Witless Ones
Continuous as thread within lotus stalk
Is Param within;
Yet they seek Him not there;
But wander about everywhere;
Though the Way to reach Him shown
They see it not;
Fools are they;
They roam about,
Only evil destiny action to reach.`,
    elaborationTamil: `தாமரைத் தண்டின் நூல்போல் அறிவுடையார் முன் எளிதில் அற்றுப்போகின்ற நூல்களால், உண்மை நூல்களின் வழிச் செல்வாரைத் தடுக்கின்றவர்கள் தாங்கள் மேல்நிலையை அடைய விரும்பி, அதற்கு மாறான வழிகளில் சென்று அலைவார்கள் அவர்களது செயல்கள், தெரிய வேண்டிய வழியைத் தெரிந்தவர் காட்டினாலும் அதனைக் கண் கொண்டு பாராத குருடர்கள் தாங்கள் அறிந்ததே வழியாகக் கொண்டு துன்பம் தரும் வழிகளில் திரியும் செயல் போன்றனவேயாம்.`,
  },
  {
    id: 2564, tantraId: 8, verseNumber: 2563,
    tamil: `மூடுதல் இன்றி முடியும் மனிதர்கள்
கூடுவர் நந்தி யவனைக் குறித்துடன்
காடும் மலையுங் கழனி கடந்தோறும்
ஊடும் உருவினை யுன்னிகி லாரே.`,
    transliteration: `mūṭutal iṉṟi muṭiyum maṉitarkaḷ
kūṭuvar nanti yavaṉaik kuṟittuṭaṉ
kāṭum malaiyuṅ kaḻaṉi kaṭantōṟum
ūṭum uruviṉai yuṉṉiki lārē.`,
    english: `2563: They See Him Not
The light within unkindled
They, their lives, end;
These men gather in crowds
And seek Him not;
In fields, forests and hills
Nandi who is immanent in them,
They see not.`,
    elaborationEnglish: ``,
    elaborationTamil: `பாசக் கூட்டம் மறைக்கின்ற மறைப்பு நீங்கி உடல் வீடும் மனிதர்கள் உடலில் இருக்கும்பொழுது, ''மாயோன் மேய காடுறை யுலகம்''3 என்பது முதலாக முறைப்படுத்துச் சொல்லப்பட்ட நால்வகை நிலங்கள் தோறும் உள்ளிடத்துச் சிவபெருமான் கொண்டிருக்கும் திருவுருவங்களைக் குறித்துச் சென்று வணங்கியிருந்து, உடல் நீங்கிய பொழுது பேரின்ப வடிவினனாகிய சிவபெருமானை அடைந்து அவனோடு இரண்டறக் கலப்பர். ஆயினும், பாசக் கூட்டத்தின் மறைப்பு நீங்கப்பெறாத மனிதர்கள் அத்திருவுருவங்கள் எங்கும் இருப்பினும் அவைகளைப் பற்றி யாதும் நினைக்க மாட்டார்கள்,`,
  },
  {
    id: 2565, tantraId: 8, verseNumber: 2564,
    tamil: `ஆவது தெற்கும் வடக்கும் அமரர்கள்
போவார் குடக்கும் குணக்கும் குறுவழி
நாவினின் மந்திர மென்று நடுவங்கி
வேவது செய்து விளங்கிடு வீரே.`,
    transliteration: `āvatu teṟkum vaṭakkum amararkaḷ
pōvār kuṭakkum kuṇakkum kuṟuvaḻi
nāviṉiṉ mantira meṉṟu naṭuvaṅki
vēvatu ceytu viḷaṅkiṭu vīrē.`,
    english: `2564: Seek God Within Through Kundalini Yoga
North and South, men wander about seeking Him
East and West, Celestials go about looking for Him,
But fix divine Mantra (Aum)
On to Muladhara,
And rouse (Kundalini) Fire, upward to stream;
There shall you as Radiant Light be.`,
    elaborationTamil: `(தலையில் வலக் கன்னத்தை, 'தெற்கு' என்றும், இடக் கன்னத்தை 'வடக்கு' என்றும், நெற்றியை, 'கிழக்கு' என்றும், பிடரிக்கு மேல் உள்ள பகுதியை 'மேற்கு' என்று குழூஉக் குறியாக வழங்குதல் சித்தர் மரபு. அம்முறையில்.) தெற்கும், வடக்கும் உயர்வுடையன. அத்திசையிகளில் தேவர்கள் உலாவுவார்கள். (சூரிய கலை சந்திர கலைகளாகிய பிராணங்கள் வியாபிக்கும்.) மேற்கும், கிழக்கும் யோகி தன் தியானப் பொருளைக் குறித்துச் செல்லும் வழிகளாம். அங்ஙனம் செல்லும் பொழுது நாவால் உச்சரிக்கப் படுவன மந்திரங்கள். இவற்றை யெல்லாம் இவ்வாறு உணர்ந்து, மூலாக்கினியை எழுப்பி நடுநாடி வழியாக ஓங்கச் செய்து, அதனால் அறிவு விளங்கப் பெறுவீர்களாக.`,
  },
  {
    id: 2566, tantraId: 8, verseNumber: 2565,
    tamil: `மயக்குற நோக்கினும் மாதவஞ் செய்யார்
தமக்குறப் பேசின தாரணை கொள்ளார்
சினக்குறப் பேசின தீவினை யாளர்
தமக்குற வல்லினை தாங்கிநின் றாரே.`,
    transliteration: `mayakkuṟa nōkkiṉum mātavañ ceyyār
tamakkuṟap pēciṉa tāraṇai koḷḷār
ciṉakkuṟap pēciṉa tīviṉai yāḷar
tamakkuṟa valliṉai tāṅkiniṉ ṟārē.`,
    english: `2565: Men of Evil Fate do not Practise Devotion
Even if men of Tapas great,
With gracious looks entreat
The men of Evil Fate
Do not holy Dharana practise
They indulge in angry speech always;
All, all, their intractable Karma,
Themselves have they to undergo.`,
    elaborationTamil: `சமயப் பூசலை மேற்கொண்டு, பிற சமயத்தவர் சினங்கொள்ளுமாறு கடுஞ்சொற்களைப் பேசின பாவத்தை யடைந்தவர் தாம் 'நெறியல்லா நெறி தன்னை நெறியாக மயங்கும் மயக்கம்* தம்மிடத்தில் பொருந்துதலால் நெறிகளைத் திரிய நோக்கினாராயினும், 'நாம் பெரிய தவத்தைச் செய்கின்றோம்' என்பது தான் அவர்கள் கருத்து அவர்கள் தங்களுக்கு உண்மை மனோலயம் வரும்படி சொல்லிய முறையைக் கைக்கொள்ளாமையால் அக் கருத்துப் போலியேயாய் உண்மையில் அவர்கள் தம்மை வந்து சார வேண்டிய வினைகள் வந்து சார்தலினாலே அவற்றைச் சுமந்து நிற்பவரேயாவர்.`,
  },
  {
    id: 2567, tantraId: 8, verseNumber: 2566,
    tamil: `விட்ட விலக்கணைதான்போம் வியோமத்துத்
தொட்டு விடாத துபசாந்தத் தேதொகும்
விட்டு விடாதது மேவுஞ்சத் தாதியிற்
சுட்டு மிலக்கணா தீதஞ் சொருபமே.`,
    transliteration: `viṭṭa vilakkaṇaitāṉpōm viyōmattut
toṭṭu viṭāta tupacāntat tētokum
viṭṭu viṭātatu mēvuñcat tātiyiṟ
cuṭṭu milakkaṇā tītañ corupamē.`,
    english: `2566: Jiva State Beyond the Ninth Defies Expression
Jiva reaches the Void, Upasanta and Nadanta
They say,
That is but to speak in grammatical convention triple--Laksana Traya;
When Jiva reaches Void,
Its state is of total renunciation of attributes all,
When Jiva reaches Upasanta
Its state is of renunciation and adherence yet
When Jiva reaches Nadanta
Its state is of renunciation and non-renunciation at once
The State of Jiva, in Finite Manifestness (Svarupa)
Transcends grammatical conventions all.`,
    elaborationEnglish: `Lakshana traya is a grammatical theory in Sanskrit which states that an expression in a certain context may lend itself to three interpretations of an object in three ways:

a) The use of the word in its secondary sense, its primary sense having been lost--Tamil, vitta-ilakkanai.

b) The use of the word in which the primary sense is retained along with its secondary sense-—Tamil vidatha-ilakkanai. ce) The use of the word in which the primary sense is partly

discarded and partly

The theory of lakshana is important in all Indian philosophical in trying to discuss the nature of the Ultimate Reality, which is beyond expression. The Vedantins employ this widely in trying to explain expressions like tattvamasi, aham brahmasmi, etc.—vide ‘‘Indian Theories of Meaning,’’~ by Dr.K. Kunjunni Raja, pp.249-255

When jiva reaches the Space, the state that ensues is one of total. effacement of all attributes. Upasanta is thc state of non-attachment and attachment yet. Jiva reaching Nadanta is the state of renunciation and non-renunciation at once. Transcending the grammatical conventions of lakshanatrayam—that is the same jiva being in different places with different experiences—is the state of jiva in Final Self-Manifestness (Svarupa).`,
    elaborationTamil: `ஆன்மாவின் சொரூப (இயற்கை) நிலையைக் குறித்து வரும் சொற்களெல்லாம் இலக்கணைச்சொல்லாகாது இலக்கணச் சொல்லேயாம். அஃதாவது நேர்ப்பொருளைத் தருவனவேயாம். அவை 'ஆன்மா நித்தியம், வியாபகம், சித்து' என்றல் போல்வன. ஆன்மாவின் சொரூப நிலையைக் கூறாது, தடத்த (செயற்கை) நிலையைக் குறித்து வரும் சொற்களே இலக்கணைச் சொல்லாய் நிற்கும். அஃதாவது நேரே பொருளை யுணர்த்தாமல், ஒன்றை இடையிட்டுப் பொருளுணர்த்தும். அது மூன்று வகைப்படும். (அவ்வகைகள் மேலே காட்டப்பட்டன.) 
'ஆன்மா, மேல், கீழ், நடு உலகங்களில் பிறந்தும், இறந்தும் உழலும்' என்றால், ஆன்மா உண்மையில் வியாபகப் பொருள் ஆகையால், அதற்குப் போக்கு வரவு இல்லையாதலின், ஆன்மாவை விட்டு, 'அதன் சூக்கும, பரசரீரங்களே அவ்வாறு உழல்வன' எனக் கொள்கின்றோம். ஆகவே இது விட்ட இலக்கணை. 
இனி, 'ஆன்மாச் சகலத்திற் கேவலம், சகலம், சுத்தம் என்னும் அவத்தைகளை அடைகின்றது' என்றால், அவ்வவத்தைகளில் உணர்வு வேறுபடுவது ஆன்மாவே ஆகையாலும், அதன் கருவிகளின் கூடுதல் பிரிதல்கள் என்பவற்றாலும், சீவ கரணங்கள் சிவ கரணங்களாய் வேறுபடுதலாலுமே அவத்தைகள் நிகழ்தலாலும் ஆன்மாவை விடாமலே அதன் கருவிகளின் கூடுதல் குறைதல் -களையே கொள்கின்றோம். அதனால் இது விடாத இலக்கணையாம். 
இனி, 'ஆன்மா புறத்தே உள்ள ஓசையைக் கேட்கின்றது, உருவத்தைக் காண்கின்றது' என்றால், கேட்டல் காண்டல்களைத் தான் நேரே செய்யாது, செவியும், கண்ணுமாகிய பொறிகளே அவற்றைச் செய்கின்றன என்றும், ஆயினும் அப்பொறிகள் அச்செயல்களைச் செய்யுமாறு ஆன்மா அவற்றை அதிட்டித்து (வாயிலாகப் பற்றி ஏவி) நிற்கின்றது என்றும் கொள்கின்றோம். இதனால், இது விட்டும் விடாத இலக்கணையாம்.`,
  },
  {
    id: 2568, tantraId: 8, verseNumber: 2567,
    tamil: `வில்லின் விசைநாணிற்கோத்திலக்கெய்தபின்
கொல்லுங் களிறைந்துங் கோலொடு சாய்ந்தன
வில்லு ளிருந்தெறி கூரும் ஒருவற்குக்
கல்கலன் என்னக் கதிரெதி யாமே.`,
    transliteration: `villiṉ vicaināṇiṟkōttilakkeytapiṉ
kolluṅ kaḷiṟaintuṅ kōloṭu cāyntaṉa
villu ḷirunteṟi kūrum oruvaṟkuk
kalkalaṉ eṉṉak katireti yāmē.`,
    english: `2567: Reaching the Goal in One Shot
Jiva strung the bow
Took aim
And with one arrow
Five deadly elephants shot;
He who thus shot
Will behold the Radiant Light
Beaming unto gems several in splendor set.`,
    elaborationEnglish: `— Jiva vanquished the five deadly elephants in one shot. He who has shot thus will see the radiant light beaming like gems in diverse colors.

The reference is to the yogic practice of coursing the kundalini energy through the sushumna and ascending the adharas up to the cranium, where God is visioned.`,
    elaborationTamil: `[இம்மந்திரம் ஒட்டணியாய் நின்றது.]
வில்லினிடத்து விசையைத் தருகின்ற நாணை ஏற்றி, அதன்கண் அம்பைப்பூட்டி தொலைவில் உள்ள இலக்கை எய்ய வல்லார் அங்ஙனம் எய்வாராயின் அந்த இலக்கிற்குக் குறுக்கே நிற்கின்ற கொலையானைகள் ஐந்தும் அந்த அம்பாலே வீழ்ந்துவிடும். (அம்பு இலக்கைச் சென்று அடையும்.) இனி அவ்வாறு எய்யும் ஒருவன் தனக்கு வாய்ப்பான இடத்தில் இருந்து கொண்டு எய்யும் பொழுது அச்சாதனையால் இனியதோர் ஒளி மாணிக்கக்கலன் போல் வெளிப்பட்டு விளங்கும்.`,
  },
  {
    id: 2569, tantraId: 8, verseNumber: 2568,
    tamil: `சீவ துரியத்துத் தொம்பதஞ் சீவனார்
தாவு பரதுரி யத்தனில் தற்பதம்
மேவு சிவதுரி யத்தசி மெய்ப்பத
மோவி விடும் தத் துவமசி உண்மையே.`,
    transliteration: `cīva turiyattut tompatañ cīvaṉār
tāvu paraturi yattaṉil taṟpatam
mēvu civaturi yattaci meyppata
mōvi viṭum tat tuvamaci uṇmaiyē.`,
    english: `2568: Tat-Tvam-Asi is Beyond the Three Muktis
In Jiva Turiya Jiva attains Tvam-Pada;
In Para Turiya beyond is Tat-Pada;
In Siva Turiya still beyond Asi-Pada true;
Further beyond is Truth that is Tat-Tvam-Asi.`,
    elaborationTamil: `('வேதாந்த மகாவாக்கியங்கள் சில உள' என்பதும், அவற்றின் இயல்பும் மேற்குறித்த அதிகாரங்களில் சொல்லப்பட்டன. அவ்வாக்கியங்களில் 'தத்துவமசி' என்னும் வாக்கியமே சிறப்பாகக் கூறப்படுதலால் அது பற்றியே இங்குக் கூறுகின்றார். வடமொழியில் 'தத்+த்வம்+அஸி' என்னும் மூன்று பதங்களின் சேர்க்கையே 'தத்துவமஸி' என்று ஆகின்றது. தத் - அது. த்வம் - நீ, அஸி - ஆகின்றாய். தத்துவமஸி - அது நீயாகின்றாய். இங்ஙனமாயினும் 'ஆகின்றாய்' என்பதனால், 'நீ அது ஆகின்றாய், என்பதே கருத்து, த்வம், 'துவம்' என வருகின்றது. 'தொம்' என மரூஉவாகவும் வரும். இங்குக் குறித்த கருத்துப் பற்றி நாயனார், 'தொந்தத்தசி என்றே கூறுவார்) 
'தத்துவமசி' என்பதை, 'தொம், தத், அசி என வைத்து நோக்கினால் முதற்கண் உள்ள 'தொம்' என்பது, மேல் 'முத்துரியம்' என்பவற்றில் சீவ துரியமாகிய யோகாவத்தையாகிய சகலத்திற் சுத்தா வத்தை நிலையில் தியான சமாதிகளில் உள்ள சீவான்மாவைக் குறிக்கும். 'தத்' என்பது பர துரியமாகிய பர முத்தியில் அடையப்படும் சொரூப சிவத்தைக் குறிக்கும். 'அசி' என்பது, நின்மல துரியமாகிய சிவ யோகத்தில் சீவான்மா பரமான்மாவாகிய சிவனேயாய் அவனோடு ஏகமாகி விடுதலைக் குறிக்கும். இதுவே 'தத்துவமசி' மகாவாக்கியத்தின் உண்மைப் பொருள். இப்பொருளைச் சில மதங்கள் தள்ளிவிடுகின்றன.`,
  },
  {
    id: 2570, tantraId: 8, verseNumber: 2569,
    tamil: `ஆறா றகன்ற அணுத்தொம் பதஞ்சுத்தம்
ஈறான தற்பதம் எய்துப சாந்தத்துப்
பேறா கியசீவன் நீங்கிப்பிர சாதத்து
வீறான தொந்தத் தசிதத்வ மசியே.`,
    transliteration: `āṟā ṟakaṉṟa aṇuttom patañcuttam
īṟāṉa taṟpatam eytupa cāntattup
pēṟā kiyacīvaṉ nīṅkippira cātattu
vīṟāṉa tontat tacitatva maciyē.`,
    english: `2569: Beyond Experiences in the Three Suddha States
Tvam-Pada transcends Tattvas six times six;
That is State Suddha;
Then is Tat-Pada;
That leads to Upasanta;
Then is Asi-Pada where Siva is;
Ultimate is the blessed State
Of Tvam-Tat-Asi that is
Tat-Tvam-Asi.`,
    elaborationTamil: `(சகலாவத்தையில் தொம்பதப்பொருளாய் நின்ற தத்துவ வன்ன ரூபியான ஆன்மாச்) சுத்தாவத்தையில் தத்துவம் அனைத் தினின்றும் நீங்கித் தூயதாய்த் தொம்பதப் பொருளாய் நிற்கும். தத்பதப் பொருளாகிய, எல்லாப் பொருட்கும் முடிவாய் உள்ள சொரூப சிவம் எப் பொழுதுமே பரதுரியத்தில் உள்ளது. அதனை அத்துரியத்தில் அடைந்த ஆன்மா அவ்வாறு குருவருளால் அசுத்தத்தின் நீங்கிச் சுத்தத்தை எய்தி, சிவமாய் நிற்கும் பேற்றினையளிக்கின்ற, 'தொம் தத்தசி' என்னும் பதத்தின் பொருளே 'தத்துவமசி' மகாவாக்கியத்தின் பொருளாகும்.`,
  },
  {
    id: 2571, tantraId: 8, verseNumber: 2570,
    tamil: `ஆகிய வச்சோயம் தேவகத் தன்னிடத்து
ஆகிய விட்டு விடாத விலக்கணைத்து
ஆருப சாந்தமே தொந்தத் தசியென்ப
ஆகிய சீவன் பரன்சிவ னாமே.`,
    transliteration: `ākiya vaccōyam tēvakat taṉṉiṭattu
ākiya viṭṭu viṭāta vilakkaṇaittu
ārupa cāntamē tontat taciyeṉpa
ākiya cīvaṉ paraṉciva ṉāmē.`,
    english: `2570: Confluence of Three States Jiva, Para and Siva
The Jiva (Deva Datta) becomes So-Ham
And by the speech of grammatical convention triple
Is in Tvam-Tat-Asi
With attributes thus transferred
There Jiva is Jiva, Para and Siva,
All in one.`,
  },
  {
    id: 2572, tantraId: 8, verseNumber: 2571,
    tamil: `துவந்தத் தசியே தொந்தத் தசியும்
அவைமன்னா வந்து வயத்தேகமான
தவமுறு தத்துவ மசிவே தாந்த
சிவமா மதுஞ்சித் தாந்தவே தாந்தமே.`,
    transliteration: `tuvantat taciyē tontat taciyum
avaimaṉṉā vantu vayattēkamāṉa
tavamuṟu tattuva macivē tānta
civamā matuñcit tāntavē tāntamē.`,
    english: `2571: Tat-Tvam-Asi of Vedanta is the Same as Thom-Tat-Asi
of Siddhanta-Vedanta
Tvam-Tat-Asi is the same as Thomtatasi
The one comes conjoined as the other
The holy concept of (You-being-I) Tat-Tvam-Asi belongs to Vedanta;
The concept of I-Siva-becoming (Thomtatasi) is Siddhanta-Vedanta.`,
    elaborationTamil: `'துவம் தத் அஸி' என்பதே தொந்தத்தசி என்பது மேலே சொல்லப்பட்டது. அவை இரண்டுமே நீக்கப்படாது நிலை பெற்று நின்று, பொருள்கோள் முறையில் ஒன்றாய் இயைகின்ற இயை பினால் ஒன்றேயாகின்றன. இனி, வேதாந்தத்தில் பெரிதும் பயின்று வருகின்ற 'தத்துவமசி' என்னும் மகாவாக்கியம் வேதாந்தம் சீவன் சிவமாதலையே குறிப்பது. ஆகிவே, அதனை, சித்தாந்த மகா வாக்கியம்' என்றும் சொல்லலாம், 'இல்லை, வேதாந்த மகாவாக்கியந் தான்' என்றும் சொல்லலாம்.`,
  },
  {
    id: 2573, tantraId: 8, verseNumber: 2572,
    tamil: `துரியம் அடங்கிய சொல்லறும் பாழை
அரிய பரமென்ப ராகாரி தன்றென்னார்
உரிய பரம்பர மாமொன் றுதிக்கும்
அருநிலம் என்பதை யாரறி வாரே.`,
    transliteration: `turiyam aṭaṅkiya collaṟum pāḻai
ariya parameṉpa rākāri taṉṟeṉṉār
uriya parampara māmoṉ ṟutikkum
arunilam eṉpatai yāraṟi vārē.`,
    english: `2572: Param-Param State Beyond Triple Turiya
The inexplicable Void that is at Turiya end
They call it Param, they who know not;
Nay, that is not so;
There is the Wondrous Land of Param-Param
That rises beyond (the Three Turiya States)
Who knows about that!`,
    elaborationEnglish: ``,
    elaborationTamil: `துரியத்தைக் கீழ்ப்படுத்தி நிற்கும். துரியாதீத நிலை, சுட்டுணர்வினால், உணரவும், சொல்லாற் சொல்லவும் வாராமையால் அந்நிலையை எய்தாதவர்க்கு அது வெறும் பாழ்போல்வதாகும். அதனால் அவர் அதில் விளங்கும் பொருளை, ஒருவராலும் அடைய இயலாத ஒரு தனிப் பொருள் என்று கூறுவர். அதனை வேறு சிலர், 'அஃது இன்னது ஆம் - என்றும், இன்னது அன்று' என்றும் அநிர்வச னீயமாகக் கூறுவர் ஆயினும், 'அந்தத் துரியாதீத நிலை அனுபவிக்கத் தக்க, மிக மேலான, ஒன்றேயான ஒப்பற்ற ஒரு பெரும் பொருள் விளங்குகின்ற நிலை' என்பதை அறிபவர் யார்!`,
  },
  {
    id: 2574, tantraId: 8, verseNumber: 2573,
    tamil: `தொம்பதந் தற்பதஞ் சொல்லும் அசிபதம்
நம்பிய முத்துரி யத்துமே னாடவே
யும்பத மும்பத மாகும் உயிர்பரன்
செம்பொரு ளான சிவமென லாமே.`,
    transliteration: `tompatan taṟpatañ collum acipatam
nampiya mutturi yattumē ṉāṭavē
yumpata mumpata mākum uyirparaṉ
cemporu ḷāṉa civameṉa lāmē.`,
    english: `2573: Beyond Jiva, Para and Siva States
Transcend beyond Tvam-Pada, Tat-Pada and Asi-Pada
And seek beyond the triple Turiyas
Then is the State-beyond-all-states
The (One) Truth beyond Jiva, Para and Siva.`,
    elaborationTamil: `மேற்கூறிய, சீவ துரியம், சிவ துரியம் பரதுரியம் என்னும் மூன்று துரியத்திலுமே தொம்பதப் பொருளாகிய ஆன்மா, தத்பதப் பொருளாகிய சிவத்தை, அசிபதத்தின் வழியாக, மேல் நோக்கு உணர்வினால் உணருமாயின், பரதுரியத்திற்போலவே ஏனை, இரு துரியங்களிலும் அது சிவமாகியே நிற்கும் (சீவனாகி நில்லாது' என்பதாம்.)`,
  },
  {
    id: 2575, tantraId: 8, verseNumber: 2574,
    tamil: `வைத்த துரிய மதிற்சொரு பானந்தத்
துய்த்த பிரணவ மாமுப தேசத்தை
மெய்த்த விதயத்து விட்டிடு மெய்யுணர்
வைத்த படியே யடைந்து நின்றானே.`,
    transliteration: `vaitta turiya matiṟcoru pāṉantat
tuytta piraṇava māmupa tēcattai
meytta vitayattu viṭṭiṭu meyyuṇar
vaitta paṭiyē yaṭaintu niṉṟāṉē.`,
    english: `2574: Supreme Awareness Beyond Siva Turiya State
At the end of Siva Turiya State
Is the Bliss of Manifestness
(Svarupa)
There chant within your heart
The Mantra that is Pranava (Aum)
Then appears Siva the Awareness
Supreme.`,
    elaborationTamil: `'தத்துவமசி' என்னும் உபதேசத்தையேயன்றிப் பிரணவ உபதேசத்தை ஒருவன் தனது நிலையான உள்ளத்தில் அழுத்தி வைப்பினும் அதனால் விளையும் மெய்யுணர்வினால் அவன் தன்னை ஆசிரியர் ஆக்கி வைத்த சிவநிலையை இழக்காது அடைந்து நிற்பவனாவான்.`,
  },
  {
    id: 2576, tantraId: 8, verseNumber: 2575,
    tamil: `நனவாதி ஐந்தையும் நாதாதியில் வைத்துப்
பினமா மலத்தைப் பின்வைத்துப் பின்சுத்தத்
தனதாஞ் சிவகதி சத்தாதி சாந்தி
மனவா சகங்கெட்ட மன்னனை நாடே.`,
    transliteration: `naṉavāti aintaiyum nātātiyil vaittup
piṉamā malattaip piṉvaittup piṉcuttat
taṉatāñ civakati cattāti cānti
maṉavā cakaṅkeṭṭa maṉṉaṉai nāṭē.`,
    english: `2575: Beyond Suddha Upasanta and Siva States
Merge the experiences five in Nada;
Drop the lowly Malas behind;
Then enter the Suddha State
Thus the onward course pursue;
Beyond the Upasanta State (Para Turiya)
Is the Siva State
Further beyond the reach of thought and word
Is the Lord Param-Param;
Do Him seek.`,
    elaborationTamil: `'அகாரம், உகாரம், மகாரம், விந்து, நாதம்' என்னும் பிரணவ கலைகள் ஐந்தையும் முறையே யோகாவத்தையில் சாக்கிரம், சொப்பனம், சுழுத்தி, துரியம், துரியாதீதம் என்னும் அவத்தைகளாகிய 'பிரணாயமம், பிரத்தியாகாரம், தாரணை: தியானம், சமாதி' என்னும் ஐந்திலும் பொருந்த வைத்துப் பயின்றால், உன்னின் வேறாகாது உடனாய் ஒன்றி நின்ற ஆணவ மல சத்தி உன்னின் வோறாய்ப் பிரியும். அங்ஙனம் அது பிரியுமிடத்து நின்மலாவத்தையில் சாக்கிரம் முதலிய ஐந்திலும் மேற்சொல்லியவாறே அகாரம் முதலிய கலைகளை வைத்துப் பாவிக்க, ஆணவ சத்தி உன்னை மறைக்க மாட்டாது. கீழ்ப் பட்டு அடங்கும். அஃது அடங்கவே, ஆன்ம சுத்தி உண்டாகி, அதன் பின் ஆன்ம லாபமும் கிடைக்கும். இவ்வாறு சத்தாதி ஐம்புலன் களையும் உணரும் ஐம்பொறிகளையும், அவற்றின் வழி ஓடுகின்ற மனத்தையும், அதற்குமேல் வாக்கையும் கடந்த தலைவனாகிய சிவனை நீ உணர்வாயாக.`,
  },
  {
    id: 2577, tantraId: 8, verseNumber: 2576,
    tamil: `பூரணி யாது புறம்பொன்றி லாமையின்
பேரணி யாதது பேச்சொன்றி லாமையின்
ஓரணை யாததுவொன்றுமி லாமையிற்
காரண மின்றியே காட்டுந் தகைமைத்தே.`,
    transliteration: `pūraṇi yātu puṟampoṉṟi lāmaiyiṉ
pēraṇi yātatu pēccoṉṟi lāmaiyiṉ
ōraṇai yātatuvoṉṟumi lāmaiyiṟ
kāraṇa miṉṟiyē kāṭṭun takaimaittē.`,
    english: `2576: Nature of Confluent State in Tat-Tvam-Asi
Completeness it has none,
Limit it has none,
Speech it has none;
Attachment it has none,
Possession it has none;
Uncaused, of itself It reveals--
This It's nature is.`,
    elaborationTamil: `(முன் மந்திரத்தில் ''மன்னன்'' என ஆண்பாலாகச் சொல்லப்பட்ட சிவம்) தனக்குப் புறம்பாகயாதொரு பொருளும் இல்லாதபடி எல்லாவற்றையும் தன்னுள் அடக்கி நிற்றல் பற்றி, 'பூரணத்துவம் உடையது' என்று சொல்ல படுகின்றது. (அஃதன்றி, 'அது தவிர வேறு பொருள் இல்லை' என்னும் கருத்தில் 'அது பூரணத்துவம் உடையது' என்று சொல்லப்படவில்லை.)
''அகிலாண்ட கோடி யெல்லாம்
தன் அருள் வெளிக்குளே தங்கும்படிக்கு இச்சை வைத்து''
என்னும் தாயுமானவர் பாடல் இங்கு நோக்கத் தக்கது.
வாக்கைக் கடந்து நிற்றலால் அஃது எந்த ஒரு பெயராலும் திட்டமாகச் சொல்ல ஒண்ணாதது. குணங்குறி ஒன்றும் இன்மையால் உயிர்களால் அனுமித்து உணரப்படாதது. ஆயினும் பிற காரணங்களால் காட்டப்படாது, தன்னாலே தான் காட்டப் படுவதாம்.`,
  },
  {
    id: 2578, tantraId: 8, verseNumber: 2577,
    tamil: `நீயது வானா யெனநின்ற பேருரை
ஆயது நானானேன் என்னச் சமைந்தறச்
சேய சிவமாக்குஞ் சீர்நந்தி பேரருள்
ஆயது வாயனந் தானந்தி யாகுமே.`,
    transliteration: `nīyatu vāṉā yeṉaniṉṟa pērurai
āyatu nāṉāṉēṉ eṉṉac camaintaṟac
cēya civamākkuñ cīrnanti pēraruḷ
āyatu vāyaṉan tāṉanti yākumē.`,
    english: `2577: Mahavakyam: You Become That
"You Become That"--
Thus the Great Expression (Mahavakyam) stood;
And I became That;
Thus to Siva Becoming
Nandi blessed me;
And as I became That
In Infinite Bliss I was immersed.`,
    elaborationTamil: `'நீ அது ஆகிறாய்' என்னும் பொருளதாய் ஆசிரியர் மாணவனுக்கு உபதேசிக்கின்ற 'தொம்தத்தசி' (தத்துவமசி) என்னும் அந்த மகாவாக்கியமே, மாணாக்கன் பயில்கையில், 'நான் அது ஆனேன்' என்னும் பொருளதாகிய 'அஹம்பிஹ்மாஸ்மி' என்னும் மகாவாக்கிய -மாய் நின்று, சிவனை அதன் பாசங்கள் முற்றும் அற்றொழியப் பண்ணி, வாக்கு மனங்கட்கு அப்பாற்பட்ட சிவமாகச் செய்யும். அங்ஙனம் பயில்கின்ற சீவன் முதலில் சிவனது அருளே தானாய்ப் பின்பு சிவனேயாய், அவனது முடிவில்லாத ஆனந்தத்தை அனுபவிப்பதாகும்.`,
  },
  {
    id: 2579, tantraId: 8, verseNumber: 2578,
    tamil: `உயிர்பர மாக உயர்பர சீவன்
அரிய சிவமாக அச்சிவ வேதத்து
இரியிலுஞ் சீராம் பராபரன் என்ன
உரிய உரையற்ற வோமய மாமே.`,
    transliteration: `uyirpara māka uyarpara cīvaṉ
ariya civamāka acciva vētattu
iriyiluñ cīrām parāparaṉ eṉṉa
uriya uraiyaṟṟa vōmaya māmē.`,
    english: `2578: From Jiva to "Aum"--Five Stages
Jiva becomes Para;
And that Para-Jiva becomes Siva;
And from that Vedic Lamp of Siva
Arose the light of Paraparan;
And in turn fills as Aum
That no speech could describe.`,
    elaborationTamil: `முன் மந்திரத்திற் கூறிய முறையால் சீவன் சிவமான பொழுது, அது 'சீவான்மா' எனப்படாது, பரமான்மா' என்றே சொல்லப்படும். (இவ்வாறு சருவஞ்ஞானோத் தரத்தில் சொல்லப் பட்டது. என்பதைச் சிவஞான போத ஆறாம் சூத்திர மாபாடியத்தில் காண்க.) அங்ஙனம் சொல்லப்படுமாறு சீவன் சிவமேயாய் விட்ட பொழுது, அவ்வாறான அந்த ஆக்கச் சிவம், மூனறு வேதங்களிலும் பராபரம்' எனப் புகழ்தற்கு உரியது. சொல் இறந்ததும், பிரணவமே வடிவானதும் ஆன அந்தச் சிவமேயன்றி, வேறன்றாம்.`,
  },
  {
    id: 2580, tantraId: 8, verseNumber: 2579,
    tamil: `வாய்நாசி யேபுரு மத்தகம் உச்சியில்
ஆய்நாசி யுச்சி முதலவை யாய்நிற்கும்
தாய்நாடி யாதிவாக் காதி சகலாதி
சேய்நா டொளியெனச் சிவகதி யைந்துமே.`,
    transliteration: `vāynāci yēpuru mattakam ucciyil
āynāci yucci mutalavai yāyniṟkum
tāynāṭi yātivāk kāti cakalāti
cēynā ṭoḷiyeṉac civakati yaintumē.`,
    english: `2579: The Five Lights in the Body in Yoga
When from nose-tip to cranium the Prana breath
Through Mother-Nadi (Sushumna) passes,
To the Fivonce are;
They of Knowledge True
Know Siva
Who stands as Fire and Water (Siva-Sakti) commingled;
Unless the Knower within
Makeonce are;
They of Knowledge True
Know Siva
Who stands as Fire and Water (Siva-Sakti) commingled;
Unless the Knower within
Make Para and then Siva`,
    elaborationEnglish: ``,
    elaborationTamil: `மேல் வாயின்கண் உள்ள, நாசிக்குச் செல்லும் வழியிடம், (என்பது நாக்கின் அடிக்கு மேல் உள்ள இடம். இஃது 'அண்ணம்' எனப்படும்.) புருவ நடு, நடு நெற்றி, உச்சித் தலை என்னும் நான்கும் சுழுமுனை வழியாகச் செல்லும் பிராணன் செல்லும் வழிகளில் சிறப்பானவையாகும். அவற்றிலும் புருவ நடுவும், உச்சியும் சிறப்பிற் சிறப்பானவை. சுழுமுனை நாடிக்கும் முலதாய் உள்ள மூலா தாரத்தில் உறங்கிக் கிடக்கின்ற, நால்வகை வாக்கிற்கும் முதலாகிய குண்டலி சத்தி எழுந்தோங்கிப் பிராணனுடன் மேற்சொல்லிய இரண் -டிடங்களை அடைந்து, அவற்றிற்கு அப்பால் உள்ள பொருளைக் காணும் ஒளியாக அமையுமாயின் அப்பொழுது, 'கலை, காலம், நியதி, வித்தை, அராகம்' என்னும் ஐந்து தத்துவங்களும் சிவகதியை அடை வதற்குத் துணையாகிவிடும்.`,
  },
  {
    id: 2581, tantraId: 8, verseNumber: 2580,
    tamil: `அறிவறி யாமை இரண்டும் அகற்றிப்
செறிவறி வாய்எங்கும் நின்ற சிவனைப்
பிறிவறி யாது பிரானென்று பேணுங்
குறியறி யாதவர் கொள்ளறி யாரே.`,
    transliteration: `aṟivaṟi yāmai iraṇṭum akaṟṟip
ceṟivaṟi vāyeṅkum niṉṟa civaṉaip
piṟivaṟi yātu pirāṉeṉṟu pēṇuṅ
kuṟiyaṟi yātavar koḷḷaṟi yārē.`,
    english: `2580: Adoration way to reach goal
Jiva's knowledge and Jiva's ignorance
Both He dispelled;
And all supreme knowledge
Siva pervasive stood;
Leave Him not;
Adore Him as Lord;
Those who know not this way,
Will never the goal reach.`,
    elaborationTamil: `கருவி கரணங்களால் வரும் அறிவைக் கொண்டு புறப் பொருள்களை அறிந்து வருகின்ற சிற்றறிவையும், கருவிகள் முடங்கியவழி ஆணவ மலத்தால் உண்டாகின்ற அறியாமையும் ஆகிய இரண்டையும், எங்கும் நிறைந்துள்ள சிவனது பேரறிவால் நீங்கும்படி நீக்கி, அந்த அறிவினாலே சிவனை, 'அவனே உயிர்களில் என்றும் நீக்க மின்றி நிறைந்திருக்கின்ற முதல்வன்' என உணர்ந்து அவனையே பற்றி நிற்கும் முறையை அறியாதவர்கள் (தாம் மெய்ப்பொருளை அறிந்து பற்றிவிட்டதாகக் கருதிக்கொள்ளினும்) அது மாட்டாதவரே ஆவர்.`,
  },
  {
    id: 2582, tantraId: 8, verseNumber: 2581,
    tamil: `அறிவார் அறிவன அப்பும் அனலும்
அறிவார் அறிவன அப்புங் கலப்பும்
அறிவான் இருந்தங் கறிவிக்கி னல்லால்
அறிவான் அறிந்த அறிவறி யோமே.`,
    transliteration: `aṟivār aṟivaṉa appum aṉalum
aṟivār aṟivaṉa appuṅ kalappum
aṟivāṉ iruntaṅ kaṟivikki ṉallāl
aṟivāṉ aṟinta aṟivaṟi yōmē.`,
    english: `2581: Knowledge comes only if God makes us know
They of knowledge True
Know Siva
Who Water and Fire at once are;
They of Knowledge True
Know Siva
Who stands as Fire and Water (Siva-Sakti) commingled;
Unless the Knower within
Makes you know,
You know not what your knowledge avails.`,
    elaborationTamil: `பொருள்களைத் தாமாக அறிபவர் யாவரும் அறியும் பொருள்கள் காட்சிப் பொருள்களே. அவையேயன்றிக் கருத்துப் பொருள்களும் உள ஆதலால், அவற்றை அறிவிப்பவன் ஒருவன் இருந்துகொண்டு அறிவித்தாலன்றி, அறிபவன் தானே அறிந்து பெற்ற அறிவாக நாம் எந்த அறிவையும் அறிகின்றிலம்.`,
  },
  {
    id: 2583, tantraId: 8, verseNumber: 2582,
    tamil: `அதீதத்துள் ளாகி அகன்றவன் நந்தி
அதீதத்துள் ளாகி அறிவிலோன் ஆன்மா
மதிபெற் றுருள்விட்ட மன்னுயி ரொன்றாம்
பதியிற் பதியும் பரவுயிர் தானே.`,
    transliteration: `atītattuḷ ḷāki akaṉṟavaṉ nanti
atītattuḷ ḷāki aṟivilōṉ āṉmā
matipeṟ ṟuruḷviṭṭa maṉṉuyi roṉṟām
patiyiṟ patiyum paravuyir tāṉē.`,
    english: `2582: Jiva Becomes Para and then Siva
He, Nandi, is within Atita
And Beyond it;
He, Jiva, Jnana bereft of,
And enters Atita;
And attains Jnana
And rid of Ignorance dark, Para becomes;
Then will with God (Pati) one be.`,
  },
  {
    id: 2584, tantraId: 8, verseNumber: 2583,
    tamil: `அடிதொழ முன்னின் றமரர்க ளத்தன்
முடிதொழ ஈசனும் முன்னின் றருளிப்
படிதொழ நீபண்டு பாவித்த தெல்லாங்
கடிதொழ காணன்னுங் கண்ணுத லானே.`,
    transliteration: `aṭitoḻa muṉṉiṉ ṟamararka ḷattaṉ
muṭitoḻa īcaṉum muṉṉiṉ ṟaruḷip
paṭitoḻa nīpaṇṭu pāvitta tellāṅ
kaṭitoḻa kāṇaṉṉuṅ kaṇṇuta lāṉē.`,
    english: `2583: Result of Prayer and Penance
Head bowed low,
I worshipped at the Feet
Of the Lord of Celestials;
Lo! the Lord stepped forward and said:
You shall now see the result
Of all your prayer and penance,
Of yore performed
And so blessed me,
He the Lord of Fore-head Eye.`,
    elaborationTamil: `சிவபெருமானைத் தேவர்கள் அவன் திருமுன் நின்று அவனது திருவடிகளைத் தலை வணங்கிப் பணிய, அவனும் அவர்கட்கு முன்னின்று அவர்கள் வேண்டுவனவற்றை அளித் தருளுவன். இனி, உலகமெல்லாம் 'ஞானி' என்று வணங்கும்படி நிற்கின்ற உனக்கு அவன், நீ முன்பு யோக பாவனையில் பாவனை யாகப் பாவித்தவைகளையெல்லாம் இப்பொழுது விரைவில் உண்மை -யாய் விளங்கக் கண்டு இன்புறுவாயாக' என்று அருள்புரிவான்.`,
  },
  {
    id: 2585, tantraId: 8, verseNumber: 2584,
    tamil: `நின்மல மேனி நிமலன் பிறப்பிலி
என்னுளம் வந்திவன் என்னடி யானென்று
பொன்வளர் மேனி புகழ்கின்ற வானவன்
நின்மல மாகென்று நீக்கவல் லானே.`,
    transliteration: `niṉmala mēṉi nimalaṉ piṟappili
eṉṉuḷam vantivaṉ eṉṉaṭi yāṉeṉṟu
poṉvaḷar mēṉi pukaḻkiṉṟa vāṉavaṉ
niṉmala mākeṉṟu nīkkaval lāṉē.`,
    english: `2584: Acceptance in Grace
Of Form Pure, Holy, Birthless,
He in me came and said:
"You are in My Grace received;
Be Pure"
Thus He blessed me,
And my blemishes removed;
He of Golden Form,
Heavenly Lord whom Celestials praise.`,
    elaborationTamil: `வேதங்களில், 'பொன்னிறம் விளங்க நிற்பவன்' (இரணிய கருப்பன்) எனப் புகழப்படுகின்ற சிவன், இயல்பாகவே மலம் இல்லாத தூயோன் ஆதலின் பிறப்பில்லாதவனாய் அருளே திருமேனியாகக் கொண்டு, 'இவன் என்னுடைய அடியவன்' என்று கருணைகூர்ந்து, என் உள்ளம் மகிழும்படி என் எதிர்வந்து இவனும் என்னைப் போல மலம் நீங்கித் தூயன் ஆகுக' எனக் கருதுதல் செய்து, அவ்வாறே நீங்குதற்கரிய எனது மலத்தை நீக்கவல்லவனாயினான்.`,
  },
  {
    id: 2586, tantraId: 8, verseNumber: 2585,
    tamil: `துறந்துபுக் கொள்ளொளி சோதியைக் கண்டு
பறந்ததென் உள்ளம் பணிந்து கிடந்தே
மறந்தறி யாவென்னை வான்வர் கோனும்
இறந்து பிறவாமல் ஈங்குவைத் தானே.`,
    transliteration: `tuṟantupuk koḷḷoḷi cōtiyaik kaṇṭu
paṟantateṉ uḷḷam paṇintu kiṭantē
maṟantaṟi yāveṉṉai vāṉvar kōṉum
iṟantu piṟavāmal īṅkuvait tāṉē.`,
    english: `2585: Immortality Conferred
Renouncing all, I inward entered
And beheld the Light within;
My heart trembled;
I prostrated low;
But Him I forgot never;
And the Lord of Celestials
Freeing me from whirl of births
Immortal made me, here below.`,
    elaborationEnglish: ``,
    elaborationTamil: `நான் இவ்வுலகில் 'யான், எனது' என எனக்கு இருந்த பற்றை எனது புண்ணிய வசத்தால் துறந்து, வித்தியா குரு, கிரியா குரு இவர்களால் என் உள்ளே ஒளிந்து நிற்கும் ஒளியாகிய சிவனை ஓராற்றால் கண்டு, முன்பு அலையாய் அலைந்து கொண்டிருந்த எனது மனம் ஒருங்கி அவனிடத்தே அடங்கிக் கிடக்க, அதனால் அவனை மறவாதவனாகிய என்னை அவனும், இறத்தலும், பின்பு பிறத்தலும் ஆகிய இவைகளை அடையாதபடி செய்து, பின்னும் இவ்வுலகிலே இருக்க வைத்தான்.`,
  },
  {
    id: 2587, tantraId: 8, verseNumber: 2586,
    tamil: `மெய்வாய் கண்மூக்குச் செவியென்னும் மெய்த் தோற்றத்
தவ்வாய அந்தக் கரணம் அகில்மும்
எவ்வா யியுரும் இறையாட்ட ஆடலாற்
கைவா யிலாநிறை எங்குமெய் கண்டதே.`,
    transliteration: `meyvāy kaṇmūkkuc ceviyeṉṉum meyt tōṟṟat
tavvāya antak karaṇam akilmum
evvā yiyurum iṟaiyāṭṭa āṭalāṟ
kaivā yilāniṟai eṅkumey kaṇṭatē.`,
    english: `2586: Pervasive Truth Form
The five sense organs external
The four cognitive organs internal
The worlds all, and lives all
All, all, are by Lord swayed;
He is the pervasive Truth Form
That neither hand nor mouth has.`,
    elaborationTamil: `'மெய், வாய், கண், மூக்கு, செவி' எனப் படுகின்ற ஐந்து புற அறிவுக் கருவிகளும், 'மனம், புத்தி, சித்தம், அகங்காரம்' எனப்படுகின்ற நான்கு அக அறிவுக் கருவிகளும், பிறவும் கூடிய உடம்புகளும், அறிவின்றி விரிந்து பரந்துள்ள பல உலகங்களும், அவற்றைச் சார்ந்து எவ்விடத்தும் அறிவையும் இன்பத்துன்ப நுகர்ச்சிகளையும் பெற்று வருகினற அளவற்ற உயிர்களும் ஆகிய அனைத்தும் சிவன் ஆட்டவே ஆடுகின்றன. இதனை, ''ஆட்டு வித்தால் ஆர் ஒருவர் ஆடாதாரே''* என்னும் திருமுறையும், ''அவன் அன்றி ஓர் அணுவும் அசையாது'' என்னும் முதுமொழியும் விளக்கி நிற்கின்றன. அதனால் சிவனது கை, வாய் முதலிய உறுப்புகளுள் யாதொன்றும் இல்லாத பெருநிறைவு எங்கும் உள்ளதாகிய அத்துவித உண்மை அருளாளரால் நன்குணரப்பட்டது.`,
  },
  {
    id: 2588, tantraId: 8, verseNumber: 2587,
    tamil: `அழிகின்ற சாயா புருடனைப் போலக்
கழிகின்ற நீரிற் குமிழியைக் காணில்
எழுகின்ற தீயிற்கர்ப் பூரத்தை யொக்கப்
பொழிகின்ற இவ்வுடற் போமப் பரத்தே.`,
    transliteration: `aḻikiṉṟa cāyā puruṭaṉaip pōlak,
kaḻikiṉṟa nīriṟ kumiḻiyaik kāṇil,
eḻukiṉṟa tīyiṟkarp pūrattai yokkap,
poḻikiṉṟa ivvuṭaṟ pōmap parattē..`,
    english: `2587: Absolute Union
Even as shadow disappears with body,
Even as bubble returns into water,
Even as flame of camphor leaves traces none,
So is it when Jiva into Param unites.`,
    elaborationTamil: `விரையத் தோன்றி மறைகின்ற சாயா புருடனைப் போலவும், சிறிது நின்று கெடுகின்ற நீர்க்குமிழி போலவும், சிறிது நீட்டித்துக்கெடுகின்ற, தீயிடைப்பட்ட கருப்பூரத்தைப்போலவும், அசுத்தத்தைப்பொழிகின்ற தூலவுடம்பும் ஒரு காலத்தில் சிவத்தில் ஒடுங்குவதேயாம்.`,
  },
  {
    id: 2589, tantraId: 8, verseNumber: 2588,
    tamil: `உடலும் உயிரும் ஒழிவற ஒன்றிற்
படருஞ் சிவசத்தி தாமே பரமாம்
உடலைவிட் டிந்த உயிரெங்கு மாகிக்
கடையுந் தலையுங் கரக்குஞ் சிவத்தே.`,
    transliteration: `uṭalum uyirum oḻivaṟa oṉṟiṟ
paṭaruñ civacatti tāmē paramām
uṭalaiviṭ ṭinta uyireṅku mākik
kaṭaiyun talaiyuṅ karakkuñ civattē.`,
    english: `2588: Total Merging
When body and Jiva
As unbroken unite (in Yoga)
Then shall Grace of Siva Sakti be;
Then does Jiva, Param become;
Jiva that leaves this body,
Pervasive then becomes;
With beginning and end none
In Siva forever it merges.`,
    elaborationTamil: `உடம்பும், உயிரும் நீக்கமற ஒன்றியிருக்கும் பொழுது, உலகத்தை நோக்கிச் செல்லும் சிவ சக்தியே உயிருக்குத் தலைமையாய் நின்று நடத்தும். உடலை அறவே விட்டொழித்தவழி, உயிர் சிவனைப் போலப் போலவே எங்கும் இருப்பதாய், முடிவும், முதலுமாகிய எல்லைகளில் எதுவும் இன்றி வியாபகமாய்ச் சிவனது வியாபகத்தில் அடங்கிவிடும்.`,
  },
  {
    id: 2590, tantraId: 8, verseNumber: 2589,
    tamil: `செவிமெய்வாய் கண்மூக்குச் சேரிந் திரியம்
அவியின் றியமன மாதிகள் ஐந்துங்
குவிவொன் றிலாமல் விரிந்து குவிந்து
தவிர்வொன் றிலாத சராசரந் தானே.`,
    transliteration: `cevimeyvāy kaṇmūkkuc cērin tiriyam
aviyiṉ ṟiyamaṉa mātikaḷ aintuṅ
kuvivoṉ ṟilāmal virintu kuvintu
tavirvoṉ ṟilāta carācaran tāṉē.`,
    english: `2589: Tattva Involutes Into Maya
The Tattvas that confuse sense organs five,
And cognitive organs internal
Expanding unintermittent
Finally (in Maya) merge;
This the fate of universe,
Inevitable it is.`,
    elaborationEnglish: ``,
    elaborationTamil: `செவி முதலிய ஐந்து ஞானேந்திரியங்கள், மனம் முதலிய நான்கு அந்தக் கரணங்கள், பிரகிருதி ஆகப் பத்தினையும் பற்றி நின்று செலுத்துகின்ற உயிர்கள் அவற்றைப் பலதலைப் பட்டு விரிந்து செல்லவிடாது சிவம் ஒன்றையே நோக்கிக் குவிந்து செல்லுமாறு செலுத்துதல் வேண்டும். அங்ஙனம் செலுத்தாமையால் அவை பல வழியாக விரிந்து செல்லத் தாமும் அவ்வாறே முதற்கண் உலகில் விரிந்து செல்கின்றன. ஆயினும் அவை முன் சொல்லிய வற்றுள் குவிந்த பொழுது, சராசரங்களாகிய அனைத்து உடம்புகளும் உயிர்களும் சிவத்தில் ஒடுங்கிச் சிறிதும் நீங்காதனவாய் இருக்கும்.`,
  },
  {
    id: 2591, tantraId: 8, verseNumber: 2590,
    tamil: `பரனெங்கு மாரப் பரந்துற்று நிற்கும்
திரனெங்கு மாகிச் செறிவெங்கு மெய்தும்
உரனெங்கு மாயுல குண்டு உமிழ்க்கும்
வரமிங்ஙன் கண்டியான் வாழ்ந்துற்ற வாறே.`,
    transliteration: `paraṉeṅku mārap parantuṟṟu niṟkum
tiraṉeṅku mākic ceṟiveṅku meytum
uraṉeṅku māyula kuṇṭu umiḻkkum
varamiṅṅaṉ kaṇṭiyāṉ vāḻntuṟṟa vāṟē.`,
    english: `2590: When Jiva Becomes Para
Jiva becomes Para;
That Para pervasive stands;
Immanent too in all creation it is;
A mighty Power it is,
That can dissolve and create universes vast;
This was the boon granted to me;
And thus is my state exalted.`,
    elaborationTamil: `சிவன் வியாபகன்; மாற்றம் இல்லாதவன் எவ்விடத்திலும், எப்பொருளிலும் நிறைந்து அதனால், தனது ஆற்றலால் சுத்தமும், அசுத்தமும் ஆய இரு மாயா காரியங்களிலும் தனது ஆற்றலால் தங்கி அவற்றைத் தன்னுள் ஒடுக்கவும் செய்வான். பின்பு விரிக்கவும் செய்வான். நான் மேல்நிலை அடைந்து பேரின்ப வாழ்வில் வாழ்ந் திருத்தற்குக் காரணம் இந்த உண்மையை இவ்வாறு உணர்ந்ததே.`,
  },
  {
    id: 2592, tantraId: 8, verseNumber: 2591,
    tamil: `அளந்து துரியத் தறிவினை வாங்கி
உளங்கொள் பரஞ்சகம் உண்ட தொழித்துக்
கிளர்ந்த பரஞ்சிவஞ்சேரக் கிடைத்தால்
விளங்கிய வெட்ட வெளியனு மாமே.`,
    transliteration: `aḷantu turiyat taṟiviṉai vāṅki
uḷaṅkoḷ parañcakam uṇṭa toḻittuk
kiḷarnta parañcivañcērak kiṭaittāl
viḷaṅkiya veṭṭa veḷiyaṉu māmē.`,
    english: `2591: When Para Becomes Parasiva
Attaining Divine Knowledge-Form of Turiya State;
And omniscient experience of phenomenal universe
If Para can reach Para-Siva,
Then He belongs to Void,
That is Light.`,
    elaborationTamil: `உயிரினது அறிவின் நிலைமையை அளந்து, அஃது நின்மல துரியத்தை அடைந்தவாற்றினைத் தெரிந்து, அதன்கண் உயிரினது அறிவினை வாங்கித் தன் அறிவினுள் அடக்கிக் கொண்ட நின்மல சிவம். அந்நிலையில் உயிரினது உடம்பும், உலகமும் இருப் பினும் அவையில்லாதது போலத் தனது அருளினுள் அடக்குமாற்றால், உயிரினது, 'யான், எனது' என்னும் பற்றை அறுத்துத் துரியத்திற்கு மேற் பட்ட பரசிவமாய்ப் பொருந்தக் கிடைத்தால், ஆன்மா அந்தப் பரசிவ -மாகிய பராகாயத்தில் அடங்கிவிடும் பேற்றினையும் பெற்றுவிடும்.`,
  },
  {
    id: 2593, tantraId: 8, verseNumber: 2592,
    tamil: `இரும்பிடை நீரென என்னையுள் வாங்கிப்
பரம்பர மான பரமது விட்டே
உரம்பெற முப்பாழ் ஒளியை விழுங்கி
இருந்தஎன் நந்தி இதயத்து ளானே.`,
    transliteration: `irumpiṭai nīreṉa eṉṉaiyuḷ vāṅkip
parampara māṉa paramatu viṭṭē
urampeṟa muppāḻ oḷiyai viḻuṅki
iruntaeṉ nanti itayattu ḷāṉē.`,
    english: `2592: Three Voids
He absorbed me in totality
As hot iron absorbs water;
Transcending Param-Para State;
He stands engulfing the Three Voids Luminous
There He is, Nandi
That in my heart resides.`,
    elaborationTamil: `உலையிற்பட்ட இரும்பு தன்மேல் வீழ்ந்த நீரை மீள வெளிப்படாதபடி தன்னுள் ஒடுக்கிக் கொள்வது போல, மேலானதற்கும் மேலான பொருளாகிய சிவன், யான் அஞ்ஞானத்தை விட்டு மெய்ஞ்ஞானத்தைப் பெற்றமையால் முப்பாழிலும் முறையானே எனது சீவ போதத்தைத் தான் விழுங்கித் தான் மட்டுமே எனக்கு மேலேயிருந்தான்; என் அறிவினுள்ளும் இருந்தான்.`,
  },
  {
    id: 2594, tantraId: 8, verseNumber: 2593,
    tamil: `கரியுண் விளவின் கனிபோல் உயிரும்
உரிய பரமுமுன் னோதுஞ் சிவமும்
அரிய துரியமேல் அகிலமும் எல்லாம்
திரிய விழுங்குஞ் சிவபெரு மானே.`,
    transliteration: `kariyuṇ viḷaviṉ kaṉipōl uyirum
uriya paramumuṉ ṉōtuñ civamum
ariya turiyamēl akilamum ellām
tiriya viḻuṅkuñ civaperu māṉē.`,
    english: `2593: Beyond Siva Turiya
As unto the wood-apple
By "elephant" disease consumed,
So are Jiva and Para before Siva;
In the rare state beyond Siva Turiya
Is Supreme Siva
That engrosses worlds all.`,
    elaborationEnglish: ``,
    elaborationTamil: `'சீவ அவத்தை, சிவ அவத்தை, பர அவத்தை' என மேற்கூறிய மூன்று அவத்தைகளிலும் அரியனவாம் துரிய நிலையில் சிவபெருமான் அனைத்துலகங்களையும், அவற்றில் வாழும் உயிர் -களையும் அவற்றது முன்னை இழிநிலை மாறி, உயர்நிலையாகும்படி விழுங்கிவிடுவான்.`,
  },
  {
    id: 2595, tantraId: 8, verseNumber: 2594,
    tamil: `அந்தமும் ஆதியும் ஆகும் பராபரன்
தந்தம் பரம்பரன் தன்னிற் பரமுடன்
நந்தமை யுண்டுமெய்ஞ் ஞானநே யாந்தத்தே
நந்தி யிருந்தனன் நாமறி யோமே.`,
    transliteration: `antamum ātiyum ākum parāparaṉ
tantam paramparaṉ taṉṉiṟ paramuṭaṉ
nantamai yuṇṭumeyñ ñāṉanē yāntattē
nanti yiruntaṉaṉ nāmaṟi yōmē.`,
    english: `2594: No More Knower and Known in Parapara
Paraparan is the end and beginning,
He is Parapara for each and every one;
He absorbed Para and us Jivas;
And at end of Jnana-Jneya relationship
As Jnathru, He, Nandi was;
This, indeed, is our comprehension-beyond.`,
    elaborationTamil: `சிவபெருமான், அனைத்துப் பொருள்கட்கும் அந்தமும், ஆதியுமாய் உள்ள பெரும் பொருளாய் நின்று, பல உயிர்களும் அடையும் பலவேறு அவத்தைகளில் தடத்த சிவனாய் எல்லாம் அவற்றிற்குத் தலைவனாய்ப் படிமுறையால் அவைகளை உயர்த்தி, முடிவில் சொரூப சிவனாய் அவனது ஞானமே கண்ணாக உணரும் ஞானத்திற்கு ஞேயமாய் இருக்கின்றான். அவனது செயல்களை நாம் அறுதியிட்டு அறியமாட்டோம்.`,
  },
  {
    id: 2596, tantraId: 8, verseNumber: 2595,
    tamil: `அற்ற துரைக்கில் அருளுப தேசங்கள்
குற்ற மறுத்தபொன் போலுங் கனலிடை
அற்றற வைத்திறை மாற்றற ஆற்றிடில்
செற்றம் அறுத்த செழுஞ்சுட ராகுமே.`,
    transliteration: `aṟṟa turaikkil aruḷupa tēcaṅkaḷ
kuṟṟa maṟuttapoṉ pōluṅ kaṉaliṭai
aṟṟaṟa vaittiṟai māṟṟaṟa āṟṟiṭil
ceṟṟam aṟutta ceḻuñcuṭa rākumē.`,
    english: `2595: When Jiva Becomes Radiant
By holy instructions are impurities rid;
Jiva shines unto gold in fire purified;
Having been of impurities rid,
If Jiva constant thinks of Siva,
Then he becomes a Radiant Flame,
That has passions burnt away.`,
    elaborationTamil: `உயிர்கள் அடையத் தகும் முடிவான பயனை கூறுமிடத்து, அது வேதாந்த சித்தாந்த மகாவாக்கியங்களின் ஒருமித்த பொருளேயாகும். அதுமேலே சொல்லப்பட்டது. அந்தப்பயன், இறைவன், உயிர்கள் பாச பந்தங்களினின்றும் முற்றாக நீங்கத் திருவுளம் பற்றி, தான் அந்தப் பந்தங்களை நீக்கும் செயல்களைக் குறைவின்றிச் செய்தால் தீயில் இட்டு மாசுக்களை நீக்க நீங்கிய பொன்போல உயிர்கள் தன்னைச் சூழ்ந்துள்ள இருளை ஓட்டி ஒளிவிடுகின்ற விளக்குப்போல ஆகி, பந்தங்கள் அனைத்தையும் துரத்தி விளங்கும்.`,
  },
  {
    id: 2597, tantraId: 8, verseNumber: 2596,
    tamil: `எல்லாம் அறியும் அறிவு தனைவிட்டு
எல்லாம் அறிந்தும் இலாபமங் கில்லை
எல்லாம் அறிந்த அறிவினை நானென்னில்
எல்லாம் அறிந்த இறையென லாமே.`,
    transliteration: `ellām aṟiyum aṟivu taṉaiviṭṭu
ellām aṟintum ilāpamaṅ killai
ellām aṟinta aṟiviṉai nāṉeṉṉil
ellām aṟinta iṟaiyeṉa lāmē.`,
    english: `2596: Knowledge That Knows All
What avails you
If you know all,
But not the Knowledge that knows all'
When you can say,
I am the Knowledge that knows all
Then can you well say,
I am God.`,
    elaborationTamil: `உயிர்கள் இறைவனைத் தவிர மற்றை எல்லாப் பொருள்களையும் அறிதல் அவற்றிற்குப்பந்தமாகும், அதனைக் குருவருளால் நீங்கிச் சிவனைப்போல முற்றறிவைப் பெற்றபின்னும் இறைவனைத் தவிர வேறுபொருள்களை அறிவதில் பேறு ஒன்றும் இல்லை. (மாறாக, இன்ப இழப்பே உளதாகும், ஏனெனில், பிற எல்லாம் துன்பப் பொருள்களேயாதலின). ஆகவே 'சிவன் நான்' என்னும் அந்த ஒற்றுமை உணர்விலே நிலைத்து நிற்பின், உயிர் இறை நிலையினின்றும் பிறழாதிருக்கும்.`,
  },
  {
    id: 2598, tantraId: 8, verseNumber: 2597,
    tamil: `தலைநின்ற தாழ்வரை மீது தவஞ்செய்து
முலைநின்ற மாதறி மூர்த்தியை யானும்
புலைநின்ற பொல்லாப் பிறவி கடந்து
கலைநின்ற கள்வனை கண்டுகொண் டேனே.`,
    transliteration: `talainiṉṟa tāḻvarai mītu tavañceytu
mulainiṉṟa mātaṟi mūrttiyai yāṉum
pulainiṉṟa pollāp piṟavi kaṭantu
kalainiṉṟa kaḷvaṉai kaṇṭukoṇ ṭēṉē.`,
    english: `2597: I Met the "Thief"
Tapas I performed
In the montane valley within my head;
Lo! I beheld Lord with his consort Sakti,
I crossed the river of birth in this fleshly body;
And met the "Thief" hiding in Kailas.`,
    elaborationEnglish: ``,
  },
  {
    id: 2599, tantraId: 8, verseNumber: 2598,
    tamil: `தானே யுலகில் தலைவ னெனத்தகும்
தானே யுலகுக்கோர் தத்துவ மாய்நிற்கும்
வானே மழைபொழி மாமறை கூர்ந்திடும்
ஊனே யுருகிய வுள்ளமொன் றாமே.`,
    transliteration: `tāṉē yulakil talaiva ṉeṉattakum
tāṉē yulakukkōr tattuva māyniṟkum
vāṉē maḻaipoḻi māmaṟai kūrntiṭum
ūṉē yurukiya vuḷḷamoṉ ṟāmē.`,
    english: `2598: Melt in Love of God
He will be Lord of worlds all,
He will be Tattvas for worlds all,
The heavens will rain because of him,
Whose flesh melts in love of God;
-Thus say the Vedas.`,
    elaborationTamil: `சிவபெருமான் ஒருவனே உலகங்கட்கெல்லாம் முழு முதல் தலைவனும், மெய்ப்பொருளும் ஆவன். அறம் முதலிய உறுதிப்பொருள்களை உணர்த்தும் மறைகளின் வழியே அவைகள் நிலைபெறற் பொருட்டு வானம் மழைபொழியவும் கருணை கூர்வன். இவற்றை உணர்ந்து ஊனும் உருகும்படி எந்த உள்ளம் அன்பினால் உருகுகின்றதோ அந்த உள்ளம் அவனோடு சேர்ந்து ஒன்றாகும்.`,
  },
  {
    id: 2600, tantraId: 8, verseNumber: 2599,
    tamil: `அருள்பெற்ற காரணம் என்கொல் அமரில்
இருளற்ற சிந்தை இறைவனை நாடி
மருளுற்ற சிந்தையை மாற்றி அருமைப்
பொருளுற்ற சேவடி போற்றுவோர் தாமே.`,
    transliteration: `aruḷpeṟṟa kāraṇam eṉkol amaril
iruḷaṟṟa cintai iṟaivaṉai nāṭi
maruḷuṟṟa cintaiyai māṟṟi arumaip
poruḷuṟṟa cēvaṭi pōṟṟuvōr tāmē.`,
    english: `2599: How to Receive Grace
How is it they received Lord's Grace? you ask;
(Well it is thus:)
In the battle of life,
Their bewildered thought wandered;
They trained its course;
And freed of darkness,
They sought Lord,
And adored His Holy Feet.`,
    elaborationTamil: `'திருவருளைப் பெற்றவர் அதனைப் பெற்றது எதன்பொருட்டு' என்று அறிய விரும்பினால், அவர் அத்திருவருளால் மலம் நீங்கப்பெற்ற தமது அறிவுகள் அத்திருவருளே கண்ணாக அத்திருவருட்கு முதலாகிய சிவத்தை ஆராய்ந்து அவ்வாராய்ச்சியால் முன்பு நீங்கிப்போன மலத்தின் வாசனை தங்கியுள்ள தங்களது அறிவை அவ்வாசனையும் அற்ற தூய அறிவாய் நிற்கும்படி செய்து, இங்ஙனம் அரிதிலே பெறப்பட்ட பொருளாய் உள்ள இவனது திருவடியையே விடாது பற்றி, அவற்றின்கீழ் அடங்கியிருப்பர்.`,
  },
  {
    id: 2601, tantraId: 8, verseNumber: 2600,
    tamil: `மெய்கலந் தாரொடு மெய்கலந் தான்தன்னை
பொய்கலந் தார்முன் புகுதா ஒருவனை
உய்கலந் தூழித் தலைவனுமாய் நிற்கும்
மெய்கலந் தின்பம் விளைந்திடும் மெய்யர்க்கே`,
    transliteration: `meykalan tāroṭu meykalan tāṉtaṉṉai
poykalan tārmun pukutā oruvaṉai
uykalan tūḻit talaivaṉumāy niṟkum
meykalan tiṉpam viḷaintum meyyarkkē`,
    english: `2600: The Truthful Are Beloved of God
Into them that are Truthful
He in Truth merged;
Before them that are untruthful
He never His appearance makes;
At time's End He stands as Lord,
To work redemption of souls all;
True ones sport in True Joy.`,
    elaborationTamil: `எவ்வகையிலும் வாய்மையையே பற்றி நிற்பாரோடே அளவளாவுபவன் சிவன். எவ்வகையிலும் பொய்யைப் பற்றி நிற்பவர்க்குத் தனது இருப்பையும் புலப்படுத்தாதவன் அவன். தாம் உய்தி பெறற்பொருட்டு பெறற்பொருட்டு அவனையே சார்தலால், அத்தகைய வாய்மையாளருக்கு அவன் பேரொடுக்கத்தைச் செய்பவனாக இருந்து, நிலையான இன்பத்தை எல்லையின்றி விளையுமாறு செய்வன்.`,
  },
  {
    id: 2602, tantraId: 8, verseNumber: 2601,
    tamil: `மெய்கலந் தாரொடு மெய்கலந் தான்மிகப்
பொய்கலந் தாருட் புகுதாப் புனிதனை
கைகலந் தாவி எழும்பொழு தண்ணலைக்
கைகலந் தார்க்கே கருத்துற லாமே.`,
    transliteration: `meykalan tāroṭu meykalan tāṉmikap
poykalan tāruṭ pukutāp puṉitaṉai
kaikalan tāvi eḻumpoḻu taṇṇalaik
kaikalan tārkkē karuttuṟa lāmē.`,
    english: `2601: Lord Abides in Hearts of the Truthful
He united in those
Who in Truth united,
He the Pure One
Who entered not false hearts;
When Prana upward ascends in Sushumna,
And you meet the Lord,
Then shall verily,
He in your thoughts abide.`,
    elaborationTamil: `முன் மந்திரத்திற்கூறிய அத்தகைமையனாகிய சிவனை, ஆவி உடலைவிட்டு நீங்கும் காலத்தில் நினைத்தல், அதற்கு முன்னெல்லாம் இடைவிடாது நினைந்தவர்கட்கே கூடும்.`,
  },
  {
    id: 2603, tantraId: 8, verseNumber: 2602,
    tamil: `எய்திய காலத் திருபொழு துஞ்சிவன்
மெய்செயின் மேலை விதியது வாய்நிற்கும்
பொய்யும் புலனும் புகலொன்று நீத்திடில்
ஐயனும் அவ்வழி யாகிநின் றானே.`,
    transliteration: `eytiya kālat tirupoḻu tuñcivaṉ
meyceyiṉ mēlai vitiyatu vāyniṟkum
poyyum pulaṉum pukaloṉṟu nīttiṭil
aiyaṉum avvaḻi yākiniṉ ṟāṉē.`,
    english: `2602: When Lord Reveals to the Truthful
When thus He in your thoughts abides,
Meditate on Him day and night;
Then will He in cranium above appear;
And if you give up falsehood and fleshly desires,
The Lord in truth reveals to you.`,
    elaborationTamil: `ஒருவன் எய்தற்கரிய மானுடப் பிறவி தனக்கு எய்தி யிருப்பதையும், அதன் நிலையாமையையும் உணர்ந்து காலை, மாலை இருபொழுதும் சிவன் வகுத்த உலகியல் அருளியல் இரண்டிலும் வாய்மையையே கடைப்பிடித்து ஒழுகுவானாயின்' அதுவே வருங்காலத்தில் அவன் பயனடைதற்கு ஏற்ற நெறி முறையாகும். சிவபெருமானும் அவ்வழியில்தான் புலப்பட்டு நிற்பான்.`,
  },
  {
    id: 2604, tantraId: 8, verseNumber: 2603,
    tamil: `எய்துவ தெய்தா தொழிவ திதுவருள்
உய்ய அருள்செய்தான் உத்தமன் சீர்நந்தி
பொய்செய்புலன் நெறியொன்பதுந்தாட்கொளின்
மெய்யென் புரவியை மேற்கொள்ள லாமே.`,
    transliteration: `eytuva teytā toḻiva tituvaruḷ
uyya aruḷceytāṉ uttamaṉ cīrnanti
poyceypulaṉ neṟiyoṉpatuntāṭkoḷiṉ
meyyeṉ puraviyai mēṟkoḷḷa lāmē.`,
    english: `2603: How to Mount Steed of Truth
Whether you reach Yogic climax or not
Is God's Grace;
That is the Way of Redemption,
Goodly Nandi taught;
If the deceptive senses nine you subdue,
Well may you mount the steed of Truth.`,
    elaborationTamil: `யாதானும் ஒன்று கிடைப்பது அல்லது கிடையாது ஒழிவது ஆகிய இந்நிலையை திருவருளால் அமைவது. இதனை உத்தம குருவாகிய எங்கள் புகழ்மிக்க நந்திபெருமான் நாங்கள் உய் வடைதற் பொருட்டு எங்கட்கு அருளிச்செய்தார். ஆகவே, ஒன்றைப் பெற வேண்டியோ, அல்லது போக்க வேண்டியோ பொய்யை மேற் கொள்ளத் தேவையில்லை. ஆயினும் யோகியரே இந்நிலைமையைத் தெளிபவர்கள். அந்த யோகம் வாய்க்கவேண்டினால், பொய்ப் பொருளிலே பூசையை உண்டாக்குகின்ற நவத்துவாரங்களையும் அடைத்தலாகிய இமய நியமங்களைக் கைக்கொளல் வேண்டும். கைக்கொண்டால் உண்மையான வாசியோகம் எளிதாக அமையும்.`,
  },
  {
    id: 2605, tantraId: 8, verseNumber: 2604,
    tamil: `கைகலந் தானை கருத்தினுள் நந்தியை
மெய்கலந் தான்தன்னை வேத முதல்வனைப்
பொய்கலந் தார்முன் புகுதாப் புனிதனைப்
பொய்யொழிந் தார்க்கே புகலிட மாமே`,
    transliteration: `kaikalan tāṉai karuttiṉuḷ nantiyai
meykalan tāṉtaṉṉai vēta mutalvaṉaip
poykalan tārmuṉ pukutāp puṉitaṉaip
poyyoḻin tārkkē pukaliṭa māmē`,
    english: `2604: Lord is the Refuge only of the Truthful
He who entered my Sushumna Nadi,
He who is in my thoughts ever-Nandi
He who is in my body,
He the source of Vedas all
He the Holy One,
That reveals not to men untrue;
He who is the Refuge,
Of only those who their falsehood shed.`,
    elaborationTamil: `(இவ்வதிகாரத்துள் முன்பே இரு மந்திரங்களில் கூறியபடி) வாய்மையாளரையே விரும்புதலும்' பொய்ம்மையாளரை வெறுத்தலும் உடையவனும், எல்லா உயிர் உள்ளங்களிலும் உள்ளவனும், வேத முதல்வனும் ஆகிய சிவபெருமானைப் பொய்யை யொழித்து, மெய்யாகப் பற்றினவர்க்கே அவன் புகலிடமாவான். (''மெய்யராகிப் பொய்யை நீக்கி வேதனையைத் துறந்து * செய்யரானார் சிந்தையானே தேவர் குலக்கொழுந்தே'' என அருளிச்செய்தார் ஆளுடைய பிள்ளையாரும்).`,
  },
  {
    id: 2606, tantraId: 8, verseNumber: 2605,
    tamil: `மெய்த்தாள் அகம்படி மேவிய நந்தியைக்
கைத்தாள் கொண்டாருந் திறந்தறி வாரில்லை
பொய்த்தாள் இடும்பையைப் பொய்யற நீவிட்டாம்
கத்தாள் திறக்கில் அரும் பேற தாமே.`,
    transliteration: `meyttāḷ akampaṭi mēviya nantiyaik
kaittāḷ koṇṭārun tiṟantaṟi vārillai
poyttāḷ iṭumpaiyaip poyyaṟa nīviṭṭām
kattāḷ tiṟakkil arum pēṟa tāmē.`,
    english: `2605: Give Up Deceptive Bodily Thoughts
Nandi imprinted
His Holy Feet on my heart;
None have drawn the bolt of His door
And glimpsed Him in;
Give up unreserved,
Thoughts of this deceptive body;
Sorrow's receptacle it is;
Then unbolt the Sushumna door
Rich, indeed, shall your reward be.`,
    elaborationTamil: `உயிர்களின் உள்ளங்களாகிய கோயிலுக்கு உள்ளே சிவபெருமான் தனது நிலையான திருவடிகளை விரும்பி வைத்து விளங்குகின்றான் அக்கோயில் பூட்டப்பட்டுள்ளது. ஆயினும் அப்பூட்டைத் திறத்தற்குரிய திறவுகோல்கள் மக்கள் எல்லாரிடத்திலும் உள்ளது. இருந்து அந்தத் திறவுகோலைப் பயன்படுத்தி அந்தப் பூட்டைத்திறந்து சிவனைத் தரிசிப்பவர் யாரும் இல்லை. அதற்குக் காரணம், அருவருக்கத் தக்க பொருள்களைப் பொதித்து வைத்து மூடியுள்ள பைகளை அவர்கள் 'பொய்' என்கின்ற கயிற்றால் இறுகக் கட்டி, அவற்றைக் காவல் புரிந்து கொண்டிருப்பதாகும். மாணவகனே, நீயும் அவர்களைப்போல இருந்தும் விடாமல் அந்தப்பைக் காவலை உண்மையாகவே விட்டு, உன் கையில் உள்ள அந்தத் திறவுகோலால் அந்தக் கோயிலைத் திறப்பாயாயின், கிடைத்தற்கரிய பேறு உனக்குக் கிடைக்கும்.`,
  },
  {
    id: 2607, tantraId: 8, verseNumber: 2606,
    tamil: `உய்யும் வகையால் உணர்வில் ஏத்துமின்
மெய்யன் அரனெறி மேலுண்டு திண்ணெனப்
பொய்யொன்று மின்றிப் புறம்பொலி வார்நடு
ஐயனும் அங்கே அமர்ந்துநின் றானே.`,
    transliteration: `uyyum vakaiyāl uṇarvil ēttumiṉ
meyyaṉ araṉeṟi mēluṇṭu tiṇṇeṉap
poyyoṉṟu miṉṟip puṟampoli vārnaṭu
aiyaṉum aṅkē amarntuniṉ ṟāṉē.`,
    english: `2606: Lord Abides in the Heart of the Faithful
Seeking the Way of Redemption
Adore Lord with feeling intense;
Sure, sure, Hara's Grace yours shall be;
In the heart of those who untruth utter not
He shines;
In their midst He abiding stood.`,
    elaborationTamil: `பொய்ம்மையைச் சிறிதும் இல்லாது உறுதியாக அப்பாற்போக்கி, அகத்தில் மட்டுமன்றிப் புறத்திலும் வாய்மை விளங்க நிற்பாரது நடுவிலே சிவனும் விரும்பி எழுந்தருளி யிருக்கின்றான். ஆகையால், உய்தியின் பொருட்டு, அந்த நிலைமையை உணர்ந்து சிவனைத் துதியுங்கள் அப்பால், மெய்ம்மையின்கண் உள்ளவனாகிய சிவனை அடையும் வழிதானே கிடைப்பதாகும்.`,
  },
  {
    id: 2608, tantraId: 8, verseNumber: 2607,
    tamil: `வம்பு பழுத்த மலர்ப்பழம் ஒன்றுண்டு
தம்பாற் பறவை புகுந்துணத் தானொட்டா
தம்புகொண் டெய்திட் டகலத் துரத்திடிற்
செம்பொற் சிவகதி சென்றெய்த லாமே`,
    transliteration: `vampu paḻutta malarppaḻam oṉṟuṇṭu
tampāṟ paṟavai pukuntuṇat tāṉoṭṭā
tampukoṇ ṭeytiṭ ṭakalat turattiṭiṟ
cempoṟ civakati ceṉṟeyta lāmē`,
    english: `2607: Lord is a Delicious Fruit Within
There is a Fruit Delicious,
From fragrant flower within it ripens;
The birds within the Self
Hinder you from reaching it;
Shoot your arrow,
And drive them away;
Then can you reach Siva State
Lustrous as Pure Red Gold.`,
    elaborationTamil: `நறுமணம் மிக்க மலர்களினின்றும் காய்த்துப் பழுத்த நல்ல பழம் ஒன்று தோட்டத்தில் உள்ளது. அதனை தோட்டத்தில் விளைவித்தவன் உண்ணாதபடி ஒரு கொடிய பறவை வந்து கொத்தித் தின்கின்றது. அஃது அவ்வாறு செய்யாதபடி வில்லில் அம்பைத் தொடுத்து எய்து பறந்தோடும்படி ஓட்டினால் சிவந்த பொன்போலும் கிடைத்தற்கரிய சிவகதியைச் சென்று அடையலாம்.`,
  },
  {
    id: 2609, tantraId: 8, verseNumber: 2608,
    tamil: `மயக்கிய ஐம்புலப் பாசம் அறுத்துத்
துயக்கறுத்தானைத் தொடர்மின்தொடர்ந்தால்
தியக்கஞ் செய்யாதே சிவனெம் பெருமான்
உயப்போ எனமனம் ஒன்றுவித் தானே`,
    transliteration: `mayakkiya aimpulap pācam aṟuttut
tuyakkaṟuttāṉait toṭarmiṉtoṭarntāl
tiyakkañ ceyyātē civaṉem perumāṉ
uyappō eṉamaṉam oṉṟuvit tāṉē`,
    english: `2608: Follow Lord and Be Redeemed
Control the senses that tempt,
Sunder the Pasas that corrupt,
Follow Lord,
Who your confusion ends;
If you do so,
Unhesitating my Siva says,
"Be you redeemed;"
And makes your thoughts
Center on Him.`,
    elaborationTamil: `தன் அடியார்களுடைய ஐம்புல ஆசையாகிய பாசங்களைப் போக்கி, அவர்கள் கலக்கத்தை நீக்கித் தெளிவைத் தருகின்றவன் சிவன் ஆதலின், அவனை அறிவினாலே பற்றுங்கள்; பற்றினால், அவன் சற்றும் தாழாது, உங்களை 'உய்யப் போக' எனத் திருவுளம்பற்றி, உங்களுடைய மனங்களை ஒருவழிப்படுத்துவான்.`,
  },
  {
    id: 2610, tantraId: 8, verseNumber: 2609,
    tamil: `மனமது தானே நினையவல் லாருக்குக்
கினமெனக் கூறு மிருங்காய மேவற்
றனிவினி னாதன்பால் தக்கன செய்யில்
புனிதன் செயலாகும் போதப் புவிக்கே`,
    transliteration: `maṉamatu tāṉē niṉaiyaval lārukkuk
kiṉameṉak kūṟu miruṅkāya mēvaṟ
ṟaṉiviṉi ṉātaṉpāl takkaṉa ceyyil
puṉitaṉ ceyalākum pōtap puvikkē`,
    english: `2609: Constant Think of Him and Receive Grace
They who constant think of Him
Will reach into a body,
Glorious and strong;
There, if they adore Lord
In ways appropriate,
They reach the World of Jnana,
Receiving Grace of the Holy One.`,
    elaborationTamil: `ஒருங்கிய மனம் தானாகவே சிவனை நினைக்கும் நிலையுடையதாகும். அந்நிலைக்கு மனத்தைக் கொணர வல்லவர் கட்கு, அனைத்துயிர்க்கும் துணையாகின்ற முறையில் அவர்கட்கு அமைந் துள்ள தூல உடம்பும் அவர் ஏவியவற்றையே செய்யும் ஏவலாளியாய்க் கீழ்ப்படிந்து நிற்கும். அக்கீழ்ப்படிதலைக் கொண்டு சிவன்பால் ஏற்புடைய செயல்களைச் செய்தால், இப்பிறப்பிலேயே அவர் செய்யும் செயல்கள் எல்லாம் மிகவும் சிவன் செயலேயாய்விடும்.`,
  },
  {
    id: 2611, tantraId: 8, verseNumber: 2610,
    tamil: `முன்னை வினைவரின் முன்னுண்டே நீங்குவர்
பின்னை வினைக்கணார் பேர்ந்தறப் பார்ப்பர்கள்
தன்னை யறிந்திடுந் தததுவ ஞானிகள்
நன்மையில் ஐம்புலன் நாடலி னாலே`,
    transliteration: `muṉṉai viṉaivariṉ muṉṉuṇṭē nīṅkuvar
piṉṉai viṉaikkaṇār pērntaṟap pārpparkaḷ
taṉṉai yaṟintiṭun tatatuva ñāṉikaḷ
naṉmaiyil aimpulaṉ nāṭali ṉālē`,
    english: `2610: How They Deal With Karma
If Karma from past
Overtakes them,
They exterminate them,
Patiently experiencing them;
But they see,
Future Karma is created not;
They realize the Self,
They are Jnanis,
That have Tattvas cognised;
They train senses five,
In ways goodly.`,
    elaborationTamil: `தம்மை நன்குணர்ந்தபின் தலைவனையும் உள்ளவாறு அறிந்தவரே (சிவஞானபோதம் - அவையடக்கம்) உண்மைத் தத்துவஞானிகள். அவர்கள் பிராரத்த வினைதோன்றினால், 'இது நாம் முகந்துகொண்டு வந்தது, இதனை அனுபவித்துத்தான் ஆகவேண்டும்' என்று உணர்ந்து அதன் பயனாகிய இன்பத்தில் விருப்பமும், துன்பத்தில் வெறுப்பும் இல்லாமல் கடன்கழிப்பார்போலப் பற்றற்றே ஐம்புலன்களை நுகருமாற்றால் அவ்வினையினின்றும் நீங்குவர். (பற்றுச்செய்யா மையால் அவ்வினை அவர்தம் உணர்வைத் தாக்காமல். உடலையே தாக்கி ஒழியும்) விருப்பு வெறுப்பு இன்மையால் இன்பத்தை நிலை நிறுத்திக்கொள்ளவும், துன்பத்தை விரைவில் ஒழிக்கவும் அவர்கள் எண்ணமையால், அவர்கள் ஆகாமிய வினையில் வீழ்தல் இல்லை. அதன் தோற்றத்தை நிகழாதபடி தடுத்து விடுவார்கள்.`,
  },
  {
    id: 2612, tantraId: 8, verseNumber: 2611,
    tamil: `தன்னை யறிந்திடும் தத்துவ ஞானிகள்
முன்னை வினையின் முடிச்சை யவிழ்பவர்கள்
பின்னை வினையைப் பிடித்து பிசைவர்கள்
சென்னியின் வைத்த சிவனரு ளாலே`,
    transliteration: `taṉṉai yaṟintiṭum tattuva ñāṉikaḷ
muṉṉai viṉaiyiṉ muṭiccai yaviḻpavarkaḷ
piṉṉai viṉaiyaip piṭittu picaivarkaḷ
ceṉṉiyiṉ vaitta civaṉaru ḷālē`,
    english: `2611: Tattva Jnanis Crush Karma
The Tattva Jnanis realize the Self;
The Gordian knot of Karma Past
They cut asunder;
Future Karmas they seize and crush,
By Grace of Siva,
Whom they hold,
High on their heads.`,
    elaborationTamil: `முன் மந்திரத்திற் கூறிய அந்த ஞானிகள், அம் மந்திரத்தில் கூறியபடி தாங்கள் வினையினின்று நீங்குதலோ டல்லாமல், தங்களைச் சிவமாகக் கருதி வந்து அடைந்தவர்களது வினைகளையும் சிவனது திருவருள் வியாபகத்தில் நின்று நீங்கியருள்வார்கள்.`,
  },
  {
    id: 2613, tantraId: 8, verseNumber: 2612,
    tamil: `மனவாக்குக் காயத்தால் வல்வினை மூளும்
மனவாக்கு நேர்நிற்கில் வல்வினை மன்னா
மனவாக்கு கெட்டவர் வாதனை தன்னால்
தனைமாற்றி யாற்றத் தகுஞானி தானே`,
    transliteration: `maṉavākkuk kāyattāl valviṉai mūḷum
maṉavākku nērniṟkil valviṉai maṉṉā
maṉavākku keṭṭavar vātaṉai taṉṉāl
taṉaimāṟṟi yāṟṟat takuñāṉi tāṉē`,
    english: `2612: No Karma, if Thought and Word are Consistent
Through thought, word and deed
Karmas accumulate;
If thought and word consistent stand
Karma bides not;
Thought and word conquering,
They experience Karmas,
And alter their course,
They the great Jnanis are.`,
    elaborationTamil: `உயிர்களின் மனமும், வாக்கும், காயமும் நேர்முறையில் செயற்படாது, கோடும் முறையில் செயற்பட்டால் உயிர்கட்கு, நீக்குதற்கரிய வலிய வினைகள் உளவாகும். அவை அவ்வாறின்றி, நேர்முறையில் செயற்பட்டால் அவ்வாறான நிலைமை ஏற்படாது. (எனினும் அஞ்ஞானமுடையவர்களது மனோவாக்குக் காயங்கள் நேர்முறையிற் செயற்படமாட்டா). இனி ஒருவன் அஞ்ஞானத்தின் நீங்கிமெய்ஞ்ஞானத்தைப்பெற்று, மனோ வாக்குக் காயங்களின் பிடியில் அகப்படாது விடுபட்டானாயினும், பழைய வாசனை காரணமாக ஒரோவழி அவை தம்மியல்பில் வந்து அவனைத் தாக்குதல் கூடும். அப்பொழுது அவன் தற்போதத்தை நீக்கிச் சிவபோதத்தை உடையவனாய் அவற்றைச் செயற்படுத்தினால், அவன், 'ஞானி' என்னும் நிலையினின்று நீங்கான்.`,
  },
  {
    id: 2614, tantraId: 8, verseNumber: 2613,
    tamil: `வாசியு மூசியும் பேசி வகையினால்
பேசி இருந்து பிதற்றிப் பயனில்லை
ஆசையும் அன்பும் அறுமின் அறுத்தபின்
ஈசன் இருந்த இடம் எளிதாமே`,
    transliteration: `vāciyu mūciyum pēci vakaiyiṉāl
pēci iruntu pitaṟṟip payaṉillai
ācaiyum aṉpum aṟumiṉ aṟuttapiṉ
īcaṉ irunta iṭam eḷitāmē`,
    english: `2613: Conquer Desires
No use prattling of
Breath and Sushumna;
Sunder your desires and passions;
Having sundered,
The Lord's place, easy be.`,
    elaborationTamil: `வாசி யோகத்தின் பெருமையையும், அதிற் பயிலும் யோகியின் பெருமையையும் நூல்களால் உணர்ந்து அவற்றை வகை வகையாக விரித்துரைப்பவனைப் போல, ஞானிகளும் விரித் துரைத்துக் கொண்டு காலம் போக்குவதில் பயனில்லை. ஆகையால் நீவிர் உயிரல் பொருள்கள் மேல் செல்லும் ஆசையையும் உயிர்ப் பொருள்கள்மேல் செல்லும் அன்பினையும் அடியோடு நீக்குங்கள். நீக்கினால் நீவிர் இறை நிலையை அடைதல் எளிதாகும்.`,
  },
  {
    id: 2615, tantraId: 8, verseNumber: 2614,
    tamil: `மாடத்து ளானலன் மண்டபத் தானலன்
கூடத்து ளானலன் கோயிலுள் ளானலன்
வேடத்து ளானலன் வேட்கைவிட் டார்நெஞ்சில்
மூடத்து ளேநின்று முத்திதந் தானே`,
    transliteration: `māṭattu ḷāṉalaṉ maṇṭapat tāṉalaṉ
kūṭattu ḷāṉalaṉ kōyiluḷ ḷāṉalaṉ
vēṭattu ḷāṉalaṉ vēṭkaiviṭ ṭārneñcil
mūṭattu ḷēniṉṟu muttitan tāṉē`,
    english: `2614: Lord is in the Desire-Abnegated
In stony houses and stately halls, He is not;
In parlors deep and temples massive, He is not;
In holy garbs He is not;
In the thoughts of those,
Who have desires abnegated, is He,
Fleshly body, though therein be;
He, their liberation granted.`,
    elaborationTamil: `சிவன், ஆசையால் மூடப்பட்டுள்ள அந்த மனங் களிலே வெளிப்படாது மறைந்து நின்று, ஆசையற்றவர்களது மனங் களிலே வெளிப்பட்டு விளங்கி, அவர்கட்கு முத்தியைத் தருகின்றான். ஆகையால் அவன், அவனை வைத்து வழிபடுகின்ற மாடம், மண்டபம், கூடம், கோயில், திருவேடம் ஆகிய இவ்விடங்களில் இல்லை.`,
  },
  {
    id: 2616, tantraId: 8, verseNumber: 2615,
    tamil: `ஆசை யறுமின்கள் ஆசை யறுமின்கள்
ஈசனோ டாயினும் ஆசை யறுமின்கள்
ஆசை படப்பட ஆய்வருந் துன்பங்கள்
ஆசை விடவிட ஆனந்த மாமே`,
    transliteration: `ācai yaṟumiṉkaḷ ācai yaṟumiṉkaḷ
īcaṉō ṭāyiṉum ācai yaṟumiṉkaḷ
ācai paṭappaṭa āyvarun tuṉpaṅkaḷ
ācai viṭaviṭa āṉanta māmē`,
    english: `2615: Sunder Desires
Sunder your desires, sunder your desires
Sunder your desires even unto Lord;
The more the desires, the more your sorrows;
The more you give up, the more your bliss shall be.`,
    elaborationEnglish: ``,
    elaborationTamil: `மேற்கூறிய உலக ஆசைகள் அனைத்தையும் நீவிர் கட்டாயமாக அறவே விட்டொழியுங்கள்; அவைகளை விட்டு நீவிர் சிவனை அடைந்தபின்பும் பழைய பழக்கத்தால் அந்த ஆசைகள் மீண்டும் உங்கள்பால் தோன்றுதல் கூடும். அப்பொழுதும் அதனை முளையிலேயே அறுத்தெறியுங்கள்; ஏனெனில் ஆசை மிகுந்து மிகுந்து வருவதால்தான் எந்நிலையிலும் துன்பங்கள் மிகுந்து மிகுந்து வருகின்றன. ஆசையை நீக்க நீக்க, இன்பங்களே மிகுந்து மிகுந்து வரும்.`,
  },
  {
    id: 2617, tantraId: 8, verseNumber: 2616,
    tamil: `அடுவன பூதங்கள் ஐந்தும் உடனே
படுவழி செய்கின்ற பற்றற வீசி
விடுவது வேட்கையை மெய்ந்நின்ற ஞானம்
தொடுவது தம்மைத் தொடர்தலு மாமே`,
    transliteration: `aṭuvaṉa pūtaṅkaḷ aintum uṭaṉē
paṭuvaḻi ceykiṉṟa paṟṟaṟa vīci
viṭuvatu vēṭkaiyai meynniṉṟa ñāṉam
toṭuvatu tammait toṭartalu māmē`,
    english: `2616: Jnana Way
The five senses burn you up;
They lead you to destruction's way;
Give up desires and scatter them away;
Reach to the Truth of Jnana;
That the Way to reach Lord.`,
    elaborationTamil: `கொல்வது போலும் துன்பத்தை ஒருங்குகூடிச் செய்வனவே ஐம்பூதங்கள், அவற்றின்மேல் வைக்கின்ற பற்று மீண்டும் மீண்டும் சிக்குதற்கு வழி செய்வதே. அதனால், அந்தப் பற்றினைப் போக்கி, மீண்டும் அவற்றின்மேல் செல்ல எழுகின்ற ஆசையை எழாமல் தடுப்பதே நிலைத்து நிற்கின்ற ஞானமாகும். அந்தப் பூதங்களை மனத்தால் சிறிது தீண்டுதலும் அவை தொடர்தலுக்கு வழியேயாகும்.`,
  },
  {
    id: 2618, tantraId: 8, verseNumber: 2617,
    tamil: `உவாக்கடல் ஒக்கின்ற வூழியும் போன
துவாக்கட லுட்பட்டுத் துஞ்சினர் வானோர்
அவாக்கட லுட்பட் டழுந்தினர் மண்ணோர்
தவாக்கடல் ஈசன் தரித்து நின்றானே`,
    transliteration: `uvākkaṭal okkiṉṟa vūḻiyum pōṉa
tuvākkaṭa luṭpaṭṭut tuñciṉar vāṉōr
avākkaṭa luṭpaṭ ṭaḻuntiṉar maṇṇōr
tavākkaṭal īcaṉ tarittu niṉṟāṉē`,
    english: `2617: Perish not in the Flood of Pleasure and Pain
Unto the ocean that foams and rages
At full-moon tide,
Many, many, floods rose and passed away
Through passage of Time;
Caught in floods of pleasure and pain,
Celestials numberless perished;
Caught in the floods of desires
The humans countless sank;
God alone forever stood
In the Ocean of Bliss Eternal.`,
    elaborationTamil: `நிறை மதி நாளன்று பொங்குகின்ற கடலைப்போல ஊழிவெள்ளம் தோன்றி உலகை விழுங்கிவிட்டு மறைந்தது. என்றும் கெடாத இன்பக்கடலை இறைவன் தாங்கிக் கொண்டிருக்கின்றான். ஆயினும், வானோரும், மண்ணோரும் ஆசைக்கடலில் மூழ்கியிருந் தமையால் இறைவனது இன்பக்கடலை அடைய மாட்டாது, அந்த ஊழி வெள்ளத்தில் மூழ்கி அழிந்தனரேயன்றி பயன் ஏதும் பெற்றாரில்லை.`,
  },
  {
    id: 2619, tantraId: 8, verseNumber: 2618,
    tamil: `நின்ற வினையும் பிணியும் நெடுஞ்செயல்
துந்தொழி லற்றுச் சுத்தம தாகலும்
பின்றைங் கருமமும் பேர்த்தருள் நேர்பெற்றுத்
துன்ற அழுத்தலும் ஞானிகள் தூய்மையே`,
    transliteration: `niṉṟa viṉaiyum piṇiyum neṭuñceyal
tuntoḻi laṟṟuc cuttama tākalum
piṉṟaiṅ karumamum pērttaruḷ nērpeṟṟut
tuṉṟa aḻuttalum ñāṉikaḷ tūymaiyē`,
    english: `2618: Jnani's Purified Way
Emancipated from Karmas of past,
Rid of disease of Pasa,
Prolonged activity suspended;
They, the Suddha State reach;
Then transcending the five acts of God
(Of creation, preservation, dissolution, obfuscation and Grace-granting)
His direct Grace, they receive
There they forever immersed are
These, Jnanis, purified ways are.`,
    elaborationTamil: `ஞானிகளாயினார் செய்யும் வீட்டு நெறிச் செயலாவன, (தீக்கையால் எரிக்கப்பட்டு ஒழிந்த சஞ்சித வினைபோக, முகந்து கொண்டு) எஞ்சி நின்ற பிராரத்த வினைத் தாக்கத்தையும், கருவி கரணங்களால் நிற்கும் மாயையின் தாக்கத்தையும் வாசனை யளவாய் நிற்கும் ஆணவத்தின் தாக்கத்தையும் முன்போல நீடியாது (சிவஞானபோதப் பன்னிரண்டாம் சூத்திரத்திற் கூறிய முறையால்) உடனே தடுத்துப் போக்கித் தூய்மையோடிருத்தலும், ஐந்தொழில் முதல்வர் செய்யும் ஐந்தொழிலின்றும் நீங்கிச் சிவனது திருவருளைப் பெற்று அவற்றால் அவனை நேரே கூடி அவனது இன்பத்தில் மூழ்குதலுமேயாகும்.`,
  },
  {
    id: 2620, tantraId: 8, verseNumber: 2619,
    tamil: `உண்மை யுணர்ந்துற ஒண்சித்தி முத்தியாம்
பெண்மயற் கெட்டறப் பேறட்ட சித்தியாம்
திண்மையின் ஞானி சிவகாயம் கைவிட்டால்
வண்மை யருள்தான் அடைந்தபின் ஆறுமே`,
    transliteration: `uṇmai yuṇarntuṟa oṇcitti muttiyām
peṇmayaṟ keṭṭaṟap pēṟaṭṭa cittiyām
tiṇmaiyiṉ ñāṉi civakāyam kaiviṭṭāl
vaṇmai yaruḷtāṉ aṭaintapiṉ āṟumē`,
    english: `2619: Jnanis Remain Immortal in God-Love
Realizing Truth in full,
Luminous Siddhi and Mukti they attained;
Sex desire entire devoid,
They achieved mighty Siddhis eight;
As Siva Jnani leaves behind this body,
Divine Grace descends on him;
And then in God-Love, forever, he remains.`,
    elaborationTamil: `பொருளியல்புகளை உள்ளவாறு உணருமாற்றால் பொய்ப் பொருள்களில் ஆசையை அறத்தொலைத்து, மெய்ப் பொருளை உணர்ந்து நிற்றலால் அடையப்படும் வீடு பேறே ஒருவனுக்குச் சிறந்த பேறாகும். அவ்வாறன்றிப் பெண்ணாசையை மட்டும் தொலைத்துப் புகழ், பொருள் முதலியவற்றை அவாவி யோகத்தில் நிற்றலால் பெறும் பேறு அட்டமாசித்திகளாம். (அவை பிறப்பை நீக்காமையால் 'பேறு' எனப்படா) மற்று, மேற்கூறியவாறு மெய்யுணர்தலால், ''உரன் என்னும் தோட்டியான் ஓர் ஐந்தும் காக்கும்''3 திறம் பெற்ற ஞானி தனுவோடு (உடம்போடு) இருப்பினும் அவனது தனு சிவதனுவேயாகும், பிராரத்தம் முடிந்தபின் அத்தனு நீங்கினால், அவன் சிவனை மிக அணியனாய் அணைதற்குரிய அருளைப் பெற்று அணைவான். அணைந்தபொழுது சிவனிடத்தே அன்பு மீதூர்ந்து அவன் சிவனது இன்பத்திலே அமைதியுடன் திளைத்திருப்பான்.`,
  },
  {
    id: 2621, tantraId: 8, verseNumber: 2620,
    tamil: `அவனிவன் ஈசனென் றன்புற நாடிச்
சிவனிவன் ஈசனென் றுண்மையை யோரார்
பவனிவன் பல்வகை யாமிப் பிறவி
புவனிவன் போவது பொய்கண்ட போதே`,
    transliteration: `avaṉivaṉ īcaṉeṉ ṟaṉpuṟa nāṭic
civaṉivaṉ īcaṉeṉ ṟuṇmaiyai yōrār
pavaṉivaṉ palvakai yāmip piṟavi
puvaṉivaṉ pōvatu poykaṇṭa pōtē`,
    english: `2620: Realize the Truth that Jiva is Siva
That this Jiva to become Siva
They in love sought not;
That this Jiva is Siva
That truth they know not;
Knowing not this Jiva is Siva,
They diverse births take,
And into worlds several wander
When Truth they realize not.`,
    elaborationTamil: `சிவபெருமான் ஒருவனையே முதற் கடவுளாக உணர்தலே, முன் மந்திரத்திற் கூறியவாறு உண்மையை உணர்தலாகும். அவ்வாறின்றி, பிற கடவுளரை, 'அவனே கடவுள், இவனே கடவுள்' என உணர்ந்து அன்பு செய்வன எல்லாம் இறையன்புகள் ஆகா; உயிர் அன்புகளே. தான் உண்மையை உணர்ந்துவிட்டதாகக் கருதிய ஒருவன் அதன் பின்னும் வலிய பலவகைப் பிறவிகளாகிய தேரினை ஊர்ந்து, பலவகைப் புவனங்களாகிய வீதிகள்தோறும் பவனி வருதல் அவன் பொய்யை மெய்யாகத் திரிய உணர்ந்த பொழுதேயாம்.`,
  },
  {
    id: 2622, tantraId: 8, verseNumber: 2621,
    tamil: `கொதிக்கின்ற வாறுங் குளிர்கின்ற வாறும்
பதிக்கின்ற வாறிந்தப் பாரக முற்றும்
விதிக்கின்ற ஐவரை வேண்டா துலகம்
நொதிக்கின்ற காயத்து நூலொன்று மாமே`,
    transliteration: `kotikkiṉṟa vāṟuṅ kuḷirkiṉṟa vāṟum
patikkiṉṟa vāṟintap pāraka muṟṟum
vitikkiṉṟa aivarai vēṇṭā tulakam
notikkiṉṟa kāyattu nūloṉṟu māmē`,
    english: `2621: Jnanis are not for Becoming Performing Gods
The Five Gods consign Jiva to broiling miseries,
And then cooling him,
Again consign him to fresh birth;
Thus in the whirl of creation endless they them ordain;
The status of these Five Gods
The Jnanis seek not;
But within the fleshly body itself
Through the mystic thread of Sushumna
They enter into union,
One wih the Lord.`,
    elaborationEnglish: ``,
    elaborationTamil: `துன்பத்தைக் காய்தலும், இன்பத்தை உவத்தலும் ஆகிய இத்தன்மைகளையே உள்ளத்தில் உறுதியாகக் கொள்ளும் முறைமையையுடையதே இவ்வுலகம் முழுதும், ஆயினும், அந்தத் துன்ப இன்பங்கள் அவற்றிற்குக் காரணமான புலன்களைக் கொணர்ந்து பொருத்துகின்றவர் ஐம்பொறிகளாகிய துட்டரேயாகலின், அவரை உலகம் வெறுத்தொதுக்கி, அழியும் தன்மையுடைய இவ்வுடம்பில் இருந்துகொண்டே சிவநூல்களின் வழி நிற்றலே தக்கது.`,
  },
  {
    id: 2623, tantraId: 8, verseNumber: 2622,
    tamil: `உய்ந்தனம் என்பீர் உறுபொருள் காண்கிலீர்
கந்த மலரிற் கலக்கின்ற நந்தியைச்
சிந்தையில் வைத்துத் தெளிவுறச் சேர்த்திட்டால்
முந்தைப் பிறவிக்கு மூலவித் தாமே`,
    transliteration: `uyntaṉam eṉpīr uṟuporuḷ kāṇkilīr
kanta malariṟ kalakkiṉṟa nantiyaic
cintaiyil vaittut teḷivuṟac cērttiṭṭāl
muntaip piṟavikku mūlavit tāmē`,
    english: `2622: Seek Nandi Within
You say, redeemed you are;
But you have not seen the Way appropriate;
Nandi merges in fragrant flower within;
Hold Him in your thoughts in vision clear,
Then have you sown the seed
Of birthlessness-to-be.`,
  },
  {
    id: 2624, tantraId: 8, verseNumber: 2623,
    tamil: `முத்திசெய் ஞானமும் கேள்வியு மாய்நிற்கும்
அத்தனை மாயா அமரர் பிரான்தனைச்
சுத்தனை தூய்நெறி யாய்நின்ற சோதியைப்
பத்தர் பரசும் பசுபதி தானென்றே`,
    transliteration: `mutticey ñāṉamum kēḷviyu māyniṟkum
attaṉai māyā amarar pirāṉtaṉaic
cuttaṉai tūyneṟi yāyniṉṟa cōtiyaip
pattar paracum pacupati tāṉeṉṟē`,
    english: `2623: He is Lord of All
He confers Mukti;
He is Jnana and Mantra;
He is the Father;
He is the Lord of Celestials immortal;
He is the Pure One;
He is the Light that is the Holy Way;
He is the Pasu-Pati (Lord of Jivas)
Whom the devotees in ardour adore.`,
    elaborationTamil: `வீடுபேற்றைத் தருகின்ற ஞான நூலைக் கற்கின்ற கல்வியின் பயனாயும், அவற்றைப் பற்றிக் கேட்கின்ற கேள்வியின் பயனாயும் உள்ளவனும், உலகிற்குத் தந்தையும் தேவர்கட்குத் தேவனும், தான் இயல்பாகவே தூயனாய், உயிர்கள் தூய்மை அடைதற்குரிய வழியாய் நிற்பவனும், அறிவே வடிவாய் உள்ளவனும் ஆகிய சிவனையே, 'உயிர்கட்குத் தலைவன்' என்று உணர்ந்து இறையன் புடையோன் போற்றுவான்.`,
  },
  {
    id: 2625, tantraId: 8, verseNumber: 2624,
    tamil: `அடியார் அடியார் அடியார்க் கடிமைக்
கடியவனாய் நல்கிட் டடினையும் பூண்டேன்
அடியார் அருளால் அவனடி கூட
அடியா னிவனென் றடிமைகொண் டானே`,
    transliteration: `aṭiyār aṭiyār aṭiyārk kaṭimaik
kaṭiyavaṉāy nalkiṭ ṭaṭiṉaiyum pūṇṭēṉ
aṭiyār aruḷāl avaṉaṭi kūṭa
aṭiyā ṉivaṉeṉ ṟaṭimaikoṇ ṭāṉē`,
    english: `2624: Be a Devotee of Devotees
To devotees of devotees of Lord
In succession continuous,
I a devotee became;
Giving myself thus,
Into their vassalage I entered;
With the Grace of devotees
I reached His Feet;
Then saying, "He my devotee is"
He accepted me in His vassalage (of Grace).`,
    elaborationEnglish: ``,
    elaborationTamil: `சிவனுக்கு அடியராயினார்க்கு அடியர் ஆயினார் சிலர் அவர்கட்கு அடியராயினார் சிலர். அவர்கட்கு அடியராயினார் மற்றும் சிலர் அவர்கட்கே நான் அடியவன் ஆக என்னைக் கொடுத்து அடியவனாகி, அடிமைகட்குரிய பணிகளைச் செய்வதையே எனது கடமையாகவும் மேற்கொண்டேன். அதனால் என்னை ஆளாக ஏற்றுக் கொண்ட அடியார்கள் என்மேல் கருணை வைத்து அந்தப் பெரு மானுடைய திருவடிகளில் என்னைச் சேர்ப்பிக்க, அப்பெருமானும் என்னைத் 'தனக்கே அடியவன்' என்று சொல்லி, நேராகவே என்னை அடிமை கொண்டான்.`,
  },
  {
    id: 2626, tantraId: 8, verseNumber: 2625,
    tamil: `நீரிற் குளிரும் நெருப்பினிற் சுட்டிடும்
ஆரிக் கடனந்தி யாமா ரறிபவர்
பாரிற் பயனாரைப் பார்க்கிலும் நேரியர்
ஊரில் உமாபதி யாகிநின் றானே`,
    transliteration: `nīriṟ kuḷirum neruppiṉiṟ cuṭṭiṭum
ārik kaṭaṉanti yāmā raṟipavar
pāriṟ payaṉāraip pārkkilum nēriyar
ūril umāpati yākiniṉ ṟāṉē`,
    english: `2625: Lord is Righteous and Bounteous
Cooler than water is He;
Hotter than fire is He;
Who this Ocean of Nandi is-
Who knows?
By far righteous is He;
Than all bounteous beings in world;
Within the heart He stood,
As Umapati (Sakti's Lord) He stood.`,
    elaborationTamil: `சிவன் குளிர்ச்சியால் இருக்க வேண்டிய சமையத்தில் நீரைவிடக் குளிர்ச்சியாய் இருப்பான். சுடவேண்டிய சமையத்தில் நெருப்பை விடச் சூடாகச் சுடுவான். (இரண்டும் கருணையே). அவனது முறை இவ்வாறாதலை அறிய வல்லார் ஆர்! நிலவுலகில் உள்ளார்க்குப் புலனாகாமலே சூக்குமமாய் இருந்து, அவர்கட்குப் பயன் தருகின்ற தேவர் பலரையும்விடச் சிவன் அதிசூக்குமன் ஆயினும், அவன் உயிர்களின் பொருட்டு ஊர்கள் தோறும் உமாதேவிக்குக் கணவனாய், அவளோடும் எழுந்தருளிக் காட்சியளிக்கின்றான்.`,
  },
  {
    id: 2627, tantraId: 8, verseNumber: 2626,
    tamil: `ஒத்துல கேழும் அறியா ஒருவனென்
ற்த்தன் இருந்திடம் ஆரறிவார்சொல்லப்
பத்தர்தம் பத்தியிற் பாற்படில் அல்லது
முத்தினை யார்சொல்ல முந்துநின் றாரே`,
    transliteration: `ottula kēḻum aṟiyā oruvaṉeṉ
ṟttaṉ iruntiṭam āraṟivārcollap
pattartam pattiyiṟ pāṟpaṭil allatu
muttiṉai yārcolla muntuniṉ ṟārē`,
    english: `2626: Where is That Peerless Pearl?
Well may denizens of seven worlds, all,
Entire try,
They cannot know Him;
Who can say where Lord is?
Unless He of Himself appears
In devotion of His devotees,
Who dares say,
Where that peerless Pearl is!`,
    elaborationTamil: `அன்பரது அன்பில் சென்றாலல்லது, 'அனைத் துலகங்களாலும் அறிய இயலாத ஒருவன்' எனச்சொல்லப்படுகின்ற சிவன் இருக்கின்ற இடத்தை அறிந்து சென்றடைய வல்லார் யாவர்? அவ்வாறே, அன்பர்கள் தம் அன்பிற்கண்டு சொன்னாலல்லது, கிடைத்தற்கரிய முத்துப்போன்ற அவனைக் கண்டு சொல்ல முற்படுவார் யாவர்? ஒருவரும் இல்லை.`,
  },
  {
    id: 2628, tantraId: 8, verseNumber: 2627,
    tamil: `ஆன்கன்று தேடி யழைக்கு மதுபோல்
நான்கன்றாய் நாடி யழைத்தேனென் நாதனை
வான்கன்றுக் கப்பாலாய் நின்ற மறைப்பொருள்
ஊன்கன்றா னாடிவந் துள்புகுந் தானே`,
    transliteration: `āṉkaṉṟu tēṭi yaḻaikku matupōl
nāṉkaṉṟāy nāṭi yaḻaittēṉeṉ nātaṉai
vāṉkaṉṟuk kappālāy niṉṟa maṟaipporuḷ
ūṉkaṉṟā ṉāṭivan tuḷpukun tāṉē`,
    english: `2627: Year for Lord
As the calf that searches,
And calls for mother-cow,
I, in yearning, sought and cried for my Lord;
He is Hidden Truth of Vedas
Who beyond heavens eternal stood;
In endearness tender,
He entered into me,
In this body fleshly.`,
    elaborationTamil: `தாயைப் பிரிந்த பசுக்கன்று தன் தாயை நாடி அழைப்பதுபோல, சிவன் ஆவாய் இருக்க, நான் அவனைப் பிரிந்து வாடும் கன்றாய் இருந்து, என் தலைவனாகிய அவனையே நாடி, 'அப்பாவோ! ஐயாவோ!' எனப் பன்முறை அழைத்தேன்; அவன் வானுலகத்திலுள்ள பசுக்கன்றுகள் போலும் தேவர்கட்கெல்லாம் அப்பால் நிற்கும் வேதப்பொருளாயினும் எனது கூக்குரலைச் செவிமடுத்து, உருவம் யாதும் கொள்ளாமலே என்னைத் தேடி வந்து, என் உள்ளத்துள்ளே புகுந்தான்.`,
  },
  {
    id: 2629, tantraId: 8, verseNumber: 2628,
    tamil: `பெத்தத்துந் தன்பணி இல்லை பிறத்தலான்
முத்தத்துந் தன்பணி இல்லை முறைமையால்
அத்தற் கிரண்டும் அருளால் அளித்தலாற்
பத்திப்பட் டோ ர்க்குப் பணியொன்றும் இல்லையே`,
    transliteration: `pettattun taṉpaṇi illai piṟattalāṉ
muttattun taṉpaṇi illai muṟaimaiyāl
attaṟ kiraṇṭum aruḷāl aḷittalāṟ
pattippaṭ ṭō rkkup paṇiyoṉṟum illaiyē`,
    english: `2628: Birth and Release are God's Giving
The Jivas in born-condition
Have tasks none to perform,
As of itself their birth comes;
The Jivas in Mukti State too
(By the very condition of that state)
Have nothing to perform;
Lord by His Grace grants states both;
What then is there for devotees to do
(But to hold Lord in their thoughts?)`,
    elaborationEnglish: ``,
    elaborationTamil: `உயிர்களின் நிலை 'பெத்தம், முத்தி' என இரண்டு. பெத்தம், பாசங்களிற் கட்டுண்ட நிலை. முத்தி, அவற்றினின்றும் விடு பட்ட நிலை. இவ்விரண்டு நிலைகளிலும், 'உயிர்களின் செயல்' என்று ஒன்று இல்லை ஏனெனில், பெத்தத்தில் உயிர்கள் பல பிறவிகளில் சென்று உழல்கின்றன. அப்பிறப்புக்களைத் தருபவனும், வாழுங் காலத்து இன்பத் துன்ப நுகர்ச்சிகளை அவற்றிற்குரிய பொருள்களைத் தந்து ஊட்டுவிப்பவனும், பின்பு அந்தப் பிறவியை நீக்கிவிடுபவனும் எல்லாம் சிவனே. அதனால், பெத்தத்திலும் அவற்றிற்கென்று ஒரு செயல் இல்லை. இனி, முத்தியாவது சிவன் குருவாய் வந்து ஞான தீக்கை செய்து வினைக்கட்டினை அறுத்து அதினின்று விடுவிப்பது. அந்நிலையிலும் உயிர் அவன் காட்டிய வழியில் நடத்தற்குரியதே யன்றித் தானாக எவ்வழியிலும் செல்லாது. மேலும் ஞான தீக்கையில் உயிர் தனது, உடல், பொருள், ஆவி அனைத்தையும் சிவன் கையில் முழுமையாக ஒப்புவித்துவிடுகின்றது. இவ்வாற்றால், பெத்தம், முத்தி யிரண்டிலும் உண்மையில் உயிருக்கென்று ஒரு செயல் இல்லை. ஆயினும் மயக்கத்தால் உயிர்கள் பெத்தத்தில் நிகழும் செயல்களைத் தம் செயல்களாகவும், முத்தர்கள் செயலையும் அவரது செயல்க ளாகவும் கருதி மயங்குகின்றன. ஞானம் கைவரப்பெற்று பத்தி மிகுந் தவர்க்கு அத்தகைய மயக்கம் இன்றி, உண்மையே விளங்கி நிற்றலால், தமக்கும் பணியாதும் இல்லையாகும் நிலை அவர்கட்கே உள்ளது.`,
  },
  {
    id: 2630, tantraId: 8, verseNumber: 2629,
    tamil: `பறவையிற் கற்பமும் பாம்புமெய் யாகப்
குறவஞ் சிலம்பக் குளிர்வரை யேறி
நறவார் மலர்கொண்டு நந்தியை யல்லால்
இறைவனென் றென்மனம் ஏத்தகி லாவே`,
    transliteration: `paṟavaiyiṟ kaṟpamum pāmpumey yākap
kuṟavañ cilampak kuḷirvarai yēṟi
naṟavār malarkoṇṭu nantiyai yallāl
iṟaivaṉeṉ ṟeṉmaṉam ēttaki lāvē`,
    english: `2629: Reach God the Kundalini Yoga Way
With Prana breath for Seed-Energy,
And the serpent (Kundalini) for body,
To the resounding music of Nada,
Upward I climb to the cool mountain within;
And with fragrant flower there blooms,
I adore Nandi;
None else the God to adore,
My mind I let.`,
    elaborationTamil: `உபநிடதம் கூறுமாறு ஐந்து பறவைகள் போன்றுள்ள ஐந்து உடம்புகளுள்ளும் உள்ளீடாய் நிற்கின்ற ஆன்மாவும், அன்ன மயம், பிராணமயம் என்னும் உடம்பினுள் பாம்பு வடிவாய் உள்ள குண்ட லினியும் பொதுமை நீங்கி, உண்மை நிலையை அடைந்திருக்க, அவ் வுடம்புகளுள்ளே மலையில் வாழும் குறவர்கள் இசைக்கும் இசைபோல எழுகின்ற நாதங்கள் ஒலிக்க, அமிர்தத்தால் குளிர்ந்திருக்கின்ற, விந்துத் தானமாகிய, 'மேரு' எனப்படும் ஆஞ்ஞையை அடைந்து அங்குக் கொல் -லாமை முதலிய எட்டையும் எட்டு மலர்களாகக் கொண்டு வழிபட்டுத் 'தியானம்' செய்யும்பொழுது, எங்கள் சிவபெருமானையன்றி, எனது மனம் வேறொருவனை 'இறைவன்' என்று கொண்டு தியானியாது.`,
  },
  {
    id: 2631, tantraId: 8, verseNumber: 2630,
    tamil: `உறுதுணை நந்தியை உம்பர் பிரானை
பெறுதுணை செய்து பிறப்பறுத் துய்மின்
செறிதுணை செய்து சிவனடி சிந்தித்
துறுதுணை யாயங்கி யாகிநின் றானே`,
    transliteration: `uṟutuṇai nantiyai umpar pirāṉai
peṟutuṇai ceytu piṟappaṟut tuymiṉ
ceṟituṇai ceytu civaṉaṭi cintit
tuṟutuṇai yāyaṅki yākiniṉ ṟāṉē`,
    english: `2630: God Grants Protection
Nandi is my Protector in need;
He is Lord of Celestials;
Seek His protection;
And ending birth cycle, be redeemed;
Think constant of Siva's Feet,
He, Divine protection grants,
He, who as Fire stood.`,
    elaborationTamil: `சிவன், தன்னையே நெருங்கி நிற்கும் துணைவனாக உணர்ந்து, தனது திருவடிகளைச் சிந்தித்தவழிக் கிடைக்கும் துணைவனாயும், ஒளி விளக்காயும் உள்ளான். அவனையன்றிப் பெருந்துணைவரும், பெறத்தக்க துணைவரும் வேறிலர். (ஏனெனில், பேரருளால் உயிர்களின் பிறப்பை அறுப்பவன் அவனேயாகலின்) ஆகையால், உணர்வுடையீர், அதனை உணர்ந்து அவனையே துணையாகப் பற்றிப் பிறப்பையறுத்துப் பிழையுங்கள்.`,
  },
  {
    id: 2632, tantraId: 8, verseNumber: 2631,
    tamil: `வானவர் தம்மை வலிசெய் திருக்கின்ற
தானவர் முப்புரஞ் செற்ற தலைவனைக்
கானவன் என்றுங் கருவரை யானென்றும்
ஊனத னுள்நினைந் தொன்றுபட் டாரே`,
    transliteration: `vāṉavar tammai valicey tirukkiṉṟa
tāṉavar muppurañ ceṟṟa talaivaṉaik
kāṉavaṉ eṉṟuṅ karuvarai yāṉeṉṟum
ūṉata ṉuḷniṉain toṉṟupaṭ ṭārē`,
    english: `2631: He Protects Good Against Evil
The Dhanavas (of Dark World)
Held the Vanavas (of Luminous World)
In fief;
He the Lord destroyed,
The Three Forts of the Evil Ones;
Him the devotees worshipped,
As Lord of Forests;
And of Mountains Black;
Thus adoring Him in fleshly body,
They in Him united.`,
    elaborationEnglish: ``,
    elaborationTamil: `தேவர்களைத் துன்புறுத்திய அசுரர்களது மூன்று கோட்டைகளைத் தன் சிரிப்பினாலே ஒரு நொடியில் சாம்பலாக்கி அழித்த தலைவன் சிவன். அவனைச் சிலர், 'காட்டிலே ஆடுபவன்' என்றும், 'கரிய மலையில் வாழ்பவன்' என்றும் தங்கள் ஊன் உடம்பின் உள்ளுக்குள்ளாகவே இகழ்ந்து, அவனைக்கூடார் ஆயினார்.`,
  },
  {
    id: 2633, tantraId: 8, verseNumber: 2632,
    tamil: `நிலைபெறு கேடென்று முன்னே படைத்த
தலைவனை நாடித் தயங்குமென் உள்ளம்
மலையுளும் வானகத் துள்ளும் புறத்தும்
உலையுளும் உள்ளத்து மூழ்கிநின் றேனே`,
    transliteration: `nilaipeṟu kēṭeṉṟu muṉṉē paṭaitta
talaivaṉai nāṭit tayaṅkumeṉ uḷḷam
malaiyuḷum vāṉakat tuḷḷum puṟattum
ulaiyuḷum uḷḷattu mūḻkiniṉ ṟēṉē`,
    english: `2632: Seek Him Within and Without
This birth is a lasting curse to me;
And so, I seek Him in drooping heart
In Mountain and Sky
Within and without;
And in Fire within too;
Thus in holy thought immersed,
I stood.`,
    elaborationTamil: `உலகனைத்தையும், 'இவை சிலகாலம் நிலைபெற்றிருந்து, பின் 'ஒடுங்குக' என்று சங்கற்பித்துப் படைத்த தலைவன் எங்கேயிருக்கின்றான்'' என்று அவனைக் காணத்தேடி என் உள்ளம் திகைத்தது. பின்பு அவன் தேட வேண்டாது எங்கும் நிறைந்து, உயிர்களின் புறத்தும், அவனைத்தேடித் திகைக்கும் உள்ளத்தும் 'புறம், அகம்' என்னும் வேறுபாடின்றி விளங்குதலைக்கண்டு வியந்தேன்.`,
  },
  {
    id: 2634, tantraId: 8, verseNumber: 2633,
    tamil: `முத்தியில் அத்தன் முழுத்த அருள்பெற்றுத்
தத்துவ சுத்தி தலைப்பட்டுத் தன்பணி
மெய்த்தவஞ் செய்கை வினைவிட்ட மெய்யுண்மைப்
பத்தியி லுற்றோர் பரானந்த போதரே`,
    transliteration: `muttiyil attaṉ muḻutta aruḷpeṟṟut
tattuva cutti talaippaṭṭut taṉpaṇi
meyttavañ ceykai viṉaiviṭṭa meyyuṇmaip
pattiyi luṟṟōr parāṉanta pōtarē`,
    english: `2633: Jiva's Task is to Seek Him
Receiving in full the Grace of Lord in Mukti State,
Purified of Tattvas, the Suddha State attaining,
To perform Tapas thus is Jiva's task;
And so rid of Karmas, in devotion true they stand;
They indeed the Jnanis
In transcendental bliss immersed.`,
    elaborationEnglish: ``,
    elaborationTamil: `முத்தி நிலையை அடைந்தவர் சிவனது திருவருளை முழுமையாகப் பெறுவர். (எனவே, 'ஏனையோர் சிறிது சிறிது பெறுவர்' என்றதாம்). அதனால், அவரே கருவி கரணங்களின் கட்டற்றவராவர் (கருவி கரணங்களோடு கூடியிருப்பினும் அவற்றால் உலகியலில் செல்லார்' என்பதாம்). ஆகவே, அவர் தன் முனைப்புக் கொண்டு 'யான், எனது என்னும் வகையில்) உலகை நோக்கி ஒன்றைச் செய்தலும், அவ் வாறன்றிச் சிவனையே நோக்கி ஒன்றைச் செய்தலும் ஆகிய செயல்கள் எல்லாவற்றையும் விடுத்து, சொரூப சிவனிடத்து உண்மையான பத்தியில் மட்டுமே நிற்பர். அதனால், அவர் அடையும் ஆனந்தமே உண்மைப் பேரானந்தமாகும். உண்மை ஞானியரும் அவரே.`,
  },
  {
    id: 2635, tantraId: 8, verseNumber: 2634,
    tamil: `வளங்கனி தேடிய வன்றாட் பறவை
உளங்கனி தேடி யுழிதரும் போது
களங்கனி யங்கியிற் கைவிளக் கேற்றி
நலங் கொண்ட நால்வரும் நாடுகின்றாரே`,
    transliteration: `vaḷaṅkaṉi tēṭiya vaṉṟāṭ paṟavai
uḷaṅkaṉi tēṭi yuḻitarum pōtu
kaḷaṅkaṉi yaṅkiyiṟ kaiviḷak kēṟṟi
nalaṅ koṇṭa nālvarum nāṭukiṉṟārē`,
    english: `2634: Jiva-Bird Seeks Siva-Fruit
The Jiva-Bird,
With its feet planted firm (on Muladhara),
Seeks the Rich Fruit (that is Siva);
When within the heart that Fruit it seeks,
Lighting the Sushumna lamp
In the Flaming Fire of Kundalini within,
It reaches its goodly goal;
Its four cognitive organs,
Ever seek Him thereafter.`,
    elaborationTamil: `(மேல், ''பறவையில் கர்ப்பமும்''9 என்னும் மந்திரத்தில் சொல்லியபடி) உலகமாகிய மரத்தில் தனக்கு இனிமையான பழத்தைத் தேடி அலைந்த சீவனாகிய பறவை, பின்பு அந்தப்பழம் தன்னுள்ளே யிருப்பதை அறிந்து அதனைத் தேடி அங்கு அலைந்துகொண்டிருக்கும் பொழுது, அதற்குக் கண்ணும், சிறகும்போல உதவுகின்ற அந்தக் கரணங்களாகிய நால்வரும் முன்புபோலத் தீயராய் இல்லாது நல்லவராய் விட்டமையால், அங்கே (உள்ளத்துள்ளே) மிக்கு விளங்குகின்ற பேரொளியிலிருந்து சிறு கைவிளக்கை ஏற்றிப் பிடித்து, அப் பறவைக்கு உதவி புரிகின்றனர்.`,
  },
  {
    id: 2636, tantraId: 8, verseNumber: 2635,
    tamil: `பெம்மான் பெருநந்தி பேச்சற்ற பேரின்பத்து
அம்மா நடிதந் தருட்கடல் ஆடினோம்
எம்மாய மும்விடுத் தெம்மைக் கரந்திட்டுச்
சும்மா திருந்திடஞ் சோதனை யாகுமே`,
    transliteration: `pemmāṉ perunanti pēccaṟṟa pēriṉpattu
ammā naṭitan taruṭkaṭal āṭiṉōm
emmāya mumviṭut temmaik karantiṭṭuc
cummā tiruntiṭañ cōtaṉai yākumē`,
    english: `2635: Divine Experiment
The Mighty Lord, the Great Nandi,
Granted me His Feet of indescribable Bliss;
And in Ocean of Grace immersed me;
Freeing me from illusions all,
And secretly guarding me in safety,
He bore me to the holy banks of Silentness
That indeed was an Experiment Divine.`,
    elaborationTamil: `எல்லோரினும் பெரியவனும், பெருந்தலைவனும் சொல்ல வாராத பெரிய இன்பத்தைத் தன்னை அடைந்தவர்க்கு வழங்கி யருளும் அன்னதொரு பெருந்தகையை உடையவனும் ஆகிய சிவன் உம்முன் வந்து தனது திருவடிகளை எங்கள் தலைமேற் சூட்டினமையால் நாங்கள் அவனது திருவருளாகிய கடலில் மூழ்கினோம் அதனால், (நீருள் இருக்கும் மீனைச் சிச்சிலி கொத்தமாட்டாது ஓடி விடுதல்போல) பொய்யாகிய பாசங்கள் எல்லாம் எம்மைப் பற்றமாட்டாது நீங்கிவிட, நாங்கள் எங்களை அவனிடத்தில் ஒளித்து வைத்துச் சும்மா இருக்கின்றோம். இந்த நிலையில் எங்கட்குச் சோதனைகள் வருகின்றன.`,
  },
  {
    id: 2637, tantraId: 8, verseNumber: 2636,
    tamil: `அறிவுடை யானரு மாமறை யுள்ளே
செறிவுடை யான்மிகு தேவர்க்குந் தேவன்
பொறியுடை யான்புலன் ஐந்துங் கடந்த
குறியுடை யானொடுங் கூடுவன் நானே`,
    transliteration: `aṟivuṭai yāṉaru māmaṟai yuḷḷē
ceṟivuṭai yāṉmiku tēvarkkun tēvaṉ
poṟiyuṭai yāṉpulaṉ aintum kaṭanta
kuṟiyuṭai yāṉoṭuṅ kūṭuvaṉ nāṉē`,
    english: `2636: Seeking Union in God
He is the Wise One;
He fills Vedas rare;
He is the God of countless Gods;
He is of Divine Sense possessed,
The five senses transcending;
With Him who these attributes has
I my union seek.`,
    elaborationTamil: `அறியாமையோடு கூடுதல் சிறிதும் இன்மையால், 'அறிவுடையான்' எனப்படுதற்கு உரிமையுடையவனும், அரிய பெரிய வேதங்களில் எங்கும் பரவலாகப் போற்றப்படுபவனும், பெரிய தேவர்கட்கும் தேவனும், கண், செவி முதலிய பொறிகளையுடைய னாயினும் அவற்றால் அறியப்படுகின்ற ஐந்து புலன்களில் ஒருபோதும் தோய்வின்றித் தன்னிலையில் திரியாதிருப்பவனும், ஆகிய சிவனோடே யான் என்றும் கூடியிருப்பதன்றிப் பிரிதல் இல்லை.`,
  },
  {
    id: 2638, tantraId: 8, verseNumber: 2637,
    tamil: `அறிவறி வென்றங் கரற்றும் உலகம்
அறிவறி யாமையை யாரும் அறியார்
அறிவறி யாமை கடந்தறி வானால்
அறிவறி யாமை யழகிய வாறே`,
    transliteration: `aṟivaṟi veṉṟaṅ karaṟṟum ulakam
aṟivaṟi yāmaiyai yārum aṟiyār
aṟivaṟi yāmai kaṭantaṟi vāṉāl
aṟivaṟi yāmai yaḻakiya vāṟē`,
    english: `2637: Dividing Line Between Knowledge and Ignorance
Jnana, Jnana, thus laments this world,
They know not that Jnana of Jiva
Is Jnana none, but (ignorance);
When Siva Jnana overlays Jiva Jnana,
They both Pure Jnana are;
Thus much is it after all,
Between Knowledge and Ignorance.`,
  },
  {
    id: 2639, tantraId: 8, verseNumber: 2638,
    tamil: `குறியாக் குறியினிற் கூடாத கூட்டத்
தறியா அறிவில் அவிழ்ந்தேக சித்தமாய்
நெறியாம் பராநந்தி நீடருள் ஒன்றுஞ்
செறியாச் செறிவே சிவமென லாமே`,
    transliteration: `kuṟiyāk kuṟiyiṉiṟ kūṭāta kūṭṭat
taṟiyā aṟivil aviḻntēka cittamāy
neṟiyām parānanti nīṭaruḷ oṉṟuñ
ceṟiyāc ceṟivē civameṉa lāmē`,
    english: `2638: Merge in God's Pervasiveness
Into the Goal beyond goals,
Into the Assembly where none assemble,
Into the Knowledge beyond knowledge,
I loosened myself,
In single-minded thought;
I merged in Holy Nandi's Grace,
There in Pervasiveness beyond pervasiveness
Was Siva.`,
    elaborationTamil: `குறியாக் குறி - தற்போதத்தால் தானே கொள்ளாது, குரு கொள்வித்தபடி கொண்ட இலட்சியம் கூடாத கூட்டம் - தற் போதத்தின் வழிச்சென்று புணராது, திருவருள் வழிச்சென்று புணர்ந்த புணர்ச்சி. அறியா அறிவு - தற்போதமாய் நின்று அறியாது, சிவ போதமாய் நின்று அறியும் அறிவு அவிழ்தல் பாசக்கட்டு நீங்குதல் எனவே, 'குறியா ... ... அவிழ்ந்து' என்றது ''தானே கொள்ளாது குருவுணர்த்திய இலட்சியமாகிய சிவத்தில், தற்போதத்தால் முயலாது, திருவருள் வழியாக முயன்று ஒன்றுபட்டுபின்னும் அந்தத் திருவருளாலே அஃதொன்றையே அறிந்து நிற்குமாற்றால் பாசங்கள் நீங்கப்பெற்று' என்றதாயிற்று. பாசக்கட்டு நீங்கினமையால், பலவாகிய பொய்ப்பொருட்பற்றுத் தொலைய, ஒன்றாகிய மெய்ப்பொருளிடத்தே அன்பு மீதூர நிற்றலால், நன்னெறியாகிய அருட்சத்தியின் முதலாகிய அச்சிவத்தில் அவ்வருளால் அழுந்துதலாகிய இயற்கை இயைபே உண்மைச் சிவ சம்பந்தமாம்.`,
  },
  {
    id: 2640, tantraId: 8, verseNumber: 2639,
    tamil: `காலினில் ஊருங் கரும்பினில் கட்டியும்
பாலினுள் நெய்யும் பழத்துள் இரதமும்
பூவினுள் நாற்றமும் போலுளன் எம்மிறை
காவலன் எங்குங் கலந்துநின் றானே`,
    transliteration: `kāliṉil ūruṅ karumpiṉil kaṭṭiyum
pāliṉuḷ neyyum paḻattuḷ iratamum
pūviṉuḷ nāṟṟamum pōluḷaṉ emmiṟai
kāvalaṉ eṅkuṅ kalantuniṉ ṟāṉē`,
    english: `2639: Lord is Immanent
As feel within breeze,
As sweet within sugarcane,
As ghee within milk,
As juice within fruit,
As fragrance within flower,
Immanent is my Lord;
Thus does the Lord pervade all.`,
    elaborationEnglish: ``,
    elaborationTamil: `எல்லாப் பொருள்களிலும் தங்கியிருத்தல் பற்றி, 'இறை' என்றும், எல்லா உயிர்களையும் பாதுகாத்தல் பற்றி, 'பதி' என்றும் சொல்லப்படுபவனாகிய எங்கள் சிவபெருமான், காற்றில் பரிசமும், கரும்பில் வெல்லமும், பாலில் நெய்யும், பழத்தில் சுவையும், மலரில் மணமும் போல, உயிர்களின் உள்ளங்களில் எல்லாம் இரண்டறக் கலந்து நிற்கின்றான்.`,
  },
  {
    id: 2641, tantraId: 8, verseNumber: 2640,
    tamil: `விருப்பொடு கூடி விகிர்த்னை நாடிப்
பொருப்பகஞ் சேர்தரு பொற்கொடி போல
இருப்பர் மனத்திடை எங்கள் பிரானார்
நெருப்புரு வாகி நிகழ்ந்துநின் றாரே`,
    transliteration: `viruppoṭu kūṭi vikirtṉai nāṭip
poruppakañ cērtaru poṟkoṭi pōla
iruppar maṉattiṭai eṅkaḷ pirāṉār
neruppuru vāki nikaḻntuniṉ ṟārē`,
    english: `2640: Lord is Unto a Hidden Vein of Gold
Seek Siva in love endearing;
As unto the vein of gold
In recesses of a mountain,
My Lord in my thoughts abides;
He Who as Form of Fire stood.`,
    elaborationTamil: `எங்கள் சிவனார், தம்மை அன்பினால் நோக்கின், தம்முடைய சத்திபோல வந்து, அங்ஙனம் நோக்கி நிற்பவரது உள்ளத்தில், பேரறிவாய், உயிர்க்குயிராய் நிறைந்து, நீங்காதிருப்பார்.`,
  },
  {
    id: 2642, tantraId: 8, verseNumber: 2641,
    tamil: `நந்தி பெருமான் நடுவுள் வியோமத்து
வந்தென் அகம்படி கோயில்கொண் டான்கொள்ள
எந்தைவந் தானென் றெழுந்தேன் எழுதலுஞ்
சிந்தையி லுள்ளே சிவனிருந் தானே`,
    transliteration: `nanti perumāṉ naṭuvuḷ viyōmattu
vanteṉ akampaṭi kōyilkoṇ ṭāṉkoḷḷa
entaivan tāṉeṉ ṟeḻuntēṉ eḻutaluñ
cintaiyi luḷḷē civaṉirun tāṉē`,
    english: `2641: Lord is in the Heart's Temple
Seated in the center of Void,
Nandi descended into my heart's temple,
And there his place took;
And as He descended,
I stood up saying: "My Father Come;"
Thus as I greeted,
Siva in my thoughts instant stood.`,
    elaborationTamil: `'பர வியோமம்' எனப்படுகின்ற அருள்வெளியில் உள்ள சிவபெருமான், அங்கு நின்றும் போந்து என் உள்ளத்துள்ளே புகுந்து அதனையே தனது இடமாகக் கொண்டான். கொண்டது எவ்வா றெனில், அவன் எனது உள்ளத்தை நோக்கி வரும்பொழுது, ''வாராத என் தந்தை வருகின்றான்'' என்று நான் பதைத்தெழுந்து எதிர்கொண்டேன். அதனால்தான் அவன் என் உள்ளத்தையே தனது இடமாகக் கொண்டுவிட்டான்.`,
  },
  {
    id: 2643, tantraId: 8, verseNumber: 2642,
    tamil: `தன்மைவல் லோனைத் தவத்துள் நலத்தினை
நன்மைவல் லோனை நடுவுறை நந்தியைப்
புன்மைபொய் யாதே புனிதனை நாடுமின்
பன்மையில் உம்மைப் பரிசுசெய் வானே`,
    transliteration: `taṉmaival lōṉait tavattuḷ nalattiṉai
naṉmaival lōṉai naṭuvuṟai nantiyaip
puṉmaipoy yātē puṉitaṉai nāṭumiṉ
paṉmaiyil ummaip paricucey vāṉē`,
    english: `2642: Lord Will Make You First of Many
He is of attributes mighty;
The Fruit of Tapas;
All things goodly He is;
In the center of my thoughts He resides;
He is the Great Nandi;
Seek the Holy One in truth unfaltering,
He will place you as the First of Many.`,
    elaborationTamil: `உயிர்களுக்கு ஆகும் நன்மைகளை யெல்லாம் செய்ய வல்லவனும், அனைத்துயிர்களையும் ஒப்ப நோக்கும் நடுவு நிலையாளனும் இயல்பாகவே பாசங்கள் இல்லாத தூயவனும் ஆகிய சிவபெருமானை நீவிர் புன்மை உண்டாகும்படி பொய்த்தல் இன்றி, உண்மையாக விரும்புங்கள்; விரும்பினால், பல உயிர்களுள்ளும் உம்மை, 'இவ்வுயிர் யாது' எனச் சிறப்பாக நோக்கி, நும் செயற்கையை நீக்கி, இயற்கையாகச் செய்து அத்தொன்னிலையில் பின்னும் தொடர்ந்தே நிற்பான்.`,
  },
  {
    id: 2644, tantraId: 8, verseNumber: 2643,
    tamil: `தொடர்ந்துநின் றானென்னைச் சோதிக்கும் போது
தொடர்ந்துநின் றானல்ல நாதனும் அங்கே
படர்ந்துநின் றாதிப் பராபரன் எந்தை
கடந்துநின் றவ்வழி காட்டுகின் றானே`,
    transliteration: `toṭarntuniṉ ṟāṉeṉṉaic cōtikkum pōtu
toṭarntuniṉ ṟāṉalla nātaṉum aṅkē
paṭarntuniṉ ṟātip parāparaṉ entai
kaṭantuniṉ ṟavvaḻi kāṭṭukiṉ ṟāṉē`,
    english: `2643: I Found Love Within Me
He was with me
As I searched Him within me;
And continuous there He stood;
My Father, Paraparan,
Pervasive He stands;
And transcending beyond too,
He shows me the Way.`,
    elaborationTamil: `சிவபெருமான் சற்குருவாய் வந்து எனது ஆறு அத்துவாக்களையும் அவற்றில் உள்ள சஞ்சித கன்மங்களை நீக்கித் தூய்மை செய்யும் பொழுது, அந்தச் செயலிலே தொடர்ந்து நின்றான். பின்பு தூய்மையாகிவிட்ட அந்த அத்துவாக்களிலே அவனே தொடர்ந்து நின்றான். அதன் பின்பு எல்லாப் பொருளிலும் கலப்பினால் ஒன்றா -கியும், பொருள்தன்மையால் வேறாகியும் நிற்கின்ற அந்த நிலைகளை எனக்கு அறிவித்துக் கொண்டே யிருக்கின்றான்.`,
  },
  {
    id: 2645, tantraId: 8, verseNumber: 2644,
    tamil: `அவ்வழி காட்டும் அமரர்க் கரும்பொருள்
இவ்வழி தந்தை தாய் கேளியான் ஒக்குஞ்
செவ்வழி சேர்சிவ லோகத் திருந்திடும்
இவ்வழி நந்தி இயல்பது தானே`,
    transliteration: `avvaḻi kāṭṭum amarark karumporuḷ
ivvaḻi tantai tāy kēḷiyāṉ okkuñ
cevvaḻi cērciva lōkat tiruntiṭum
ivvaḻi nanti iyalpatu tāṉē`,
    english: `2644: He is Father, Mother, Kith and Kin
He who shows that Way
Is rare for Celestials to reach;
Here below,
Is He as Father, Mother, Kith and Kin;
He is in Siva Loka
The Holy Way leads to;
This the Way, Nandi is.`,
    elaborationTamil: `விண்ணுலகத்தில் விண்ணவர்கட்கும் அவர்கள் அவ்வுலகத்தில் பற்றற்றுச் செல்ல வேண்டிய அந்த வழியைக் காட்டும் அரிய பொருளாய் இருப்பான். மண்ணுலகத்தில் மக்களுக்குத் தந்தை போலவும், தாய்போலவும், உறவினர் போலவும் இம்மைக்கு வேண்டுவன பலவும் செய்து, அம்மைக்கு ஆகும் நல்வழியையும் கற்பித்துத் தனது உலகத்தில் இருக்கச் செய்வான். இஃது எங்கள் சிவபெருமானது இயல்பு.`,
  },
  {
    id: 2646, tantraId: 8, verseNumber: 2645,
    tamil: `எறிவது ஞானத் துறைவாள் உருவி
அறிவது னோடேயவ் வாண்டகை யானைச்
செறிவது தேவர்க்குத் தேவர் பிரானைப்
பறிவது பல்கணப் பற்றுவி டாரே`,
    transliteration: `eṟivatu ñāṉat tuṟaivāḷ uruvi
aṟivatu ṉōṭēyav vāṇṭakai yāṉaic
ceṟivatu tēvarkkut tēvar pirāṉaip
paṟivatu palkaṇap paṟṟuvi ṭārē`,
    english: `2645: Unsheath the Sword of Jnana
Unsheath the Sword of Jnana and smite;
That instant you shall know Lord;
Unite in Him,
Who the Lord of Celestials is;
Away then shall you be
From the rabble numerous
That to desire cling.`,
    elaborationTamil: `உலகப் பற்றை விடுத்துச் சிவப்பற்றைப் பற்றினோர், அந்நிலைக்கண் தமக்கு யாதேனும் இடையூறுவரின் அவர்கள் அவற்றைப் போழ்வது, ஞானமாகிய வாளைத் திரு வருளாகிய உறையினின்றும் உருவியாம். அங்ஙனம் இடையூற்றைப் போக்கி முன்போல அவர்கள் அறிந்து நிற்பது, தம் இயல்பையும், தலைவன் இயல்பையுமாம். (ஆகவே அடிமை நிலையினின்றும் பிறழார் என்பதாம்) அங்ஙனம் அறிந்து அடிமை செய்து நிற்றலால் அவர்கள் இரண்டறக் கலப்பது சிவபெருமானையே. அவர்கள் அறவே விட்டு விலகுவது, வேற்றியல்புடைய பல குழுக்களையாம்.`,
  },
  {
    id: 2647, tantraId: 8, verseNumber: 2646,
    tamil: `ஆதிப் பிரான்தந்த வாள்ங்கைக்கொண்டபின்
வேதித்து என்னை விலக்கவல் லாரில்லை
சோதிப்பன் அங்கே சுவடு படாவண்ணம்
ஆதிக்கட் டெய்வ மவனிவ னாமே`,
    transliteration: `ātip pirāṉtanta vāḷṅkaikkoṇṭapiṉ
vētittu eṉṉai vilakkaval lārillai
cōtippaṉ aṅkē cuvaṭu paṭāvaṇṇam
ātikkaṭ ṭeyva mavaṉiva ṉāmē`,
    english: `2646: Be not Separated from Lord
Holding the Sword of Jnana
That Primal Lord gifted me,
None there is to separate me (from Him);
Search did I there further
Leaving traces none;
Then Jiva with Primal Siva one became.`,
    elaborationTamil: `யான் தொடக்கத்தில் தேவனாய் இருந்து, இப்பொழுது சிவனே ஆகிவிட்டேன். அஃது முழுமுதற் கடவுளாகிய சிவன் தனது ஞானமாகிய வாளை எனக்கு ஈந்தருள, இதனை யான் விடாது பற்றிக்கொண்டமையால். என்னை இனி அவனை அடைய ஒட்டாமல் வேறுபடுத்தி விலக்க வல்லவர் எங்கும், எவரும் இல்லை. அவ்வா றன்றி எங்கேனும், யாரேனும் என்னை வேறுபடுத்தி விலக்க வருவார்களேயாயின் அவர்கள் வந்து சென்ற சுவடும் தோன்றாதபடி அவர்களது வலிமையைச் சோதித்து ஓட்டிவிடுவேன்.`,
  },
  {
    id: 2648, tantraId: 8, verseNumber: 2647,
    tamil: `அந்தக் கருவை யருவை வினைசெய்தற்
பந்தம் பணியச்சம் பல்பிறப் பும்வாட்டிச்
சிந்தை திருத்தலுஞ் சேர்ந்தாரச் சோதனை
சந்திக்கத் தற்பர மாகுஞ் சதுரர்க்கே`,
    transliteration: `antak karuvai yaruvai viṉaiceytaṟ
pantam paṇiyaccam palpiṟap pumvāṭṭic
cintai tiruttaluñ cērntārac cōtaṉai
cantikkat taṟpara mākuñ caturarkkē`,
    english: `2647: Search Lord in Calmness
Pasa, that seminal seed of birth
Maya, that invisible one,
Karma, that to desire gives birth,
The doubts and fears
That in their train come,
The births numerous,
-All these I scorched;
Thus my thoughts purified,
In calmness I search;
The skilful ones that practise thus
Shall one with Tat-Para be.`,
    elaborationTamil: `எல்லா அனத்தங்கட்கும் மூலமாய் உள்ள ஆணவம், சத்தி சமூகம் ஆதலின் அருவமாய் உள்ள மாயை, அதனைக் கொண்டு சில செயல்களைச் செய்வதாகிய கன்மம் ஆகிய இப் பந்தங்களால் உளவாகின்ற, நடுங்கத் தக்க அச்சத்தைத் தரும், எண்ணிறந்தனவாகிய பிறப்புக்கள் அனைத்தையும் போக்கி, ஞானாசிரியர் ஆன்ம அறிவைத் தூயதாக்க, அதனால் சிவத்தைச் சேர்ந்து சிவமாயினோர், அதன்பின்பும் வரும் சோதனைகளை உறுதியோடு சந்தித்து வென்றால், அங்ஙனம் வென்ற திறமையாளர்க்கு அந்தச் சிவப்பேறு நிலைத்திருக்கும்.`,
  },
  {
    id: 2649, tantraId: 8, verseNumber: 2648,
    tamil: `உரையற்ற தொன்றை யுரைத்தான் எனக்குக்
கரையற் றெழுந்த கலைவேட் டறுத்துத்
திரையொத்த என்னுடல் நீங்கா திருத்திப்
புரையற்ற என்னுட் புகுந்தற் பரனே`,
    transliteration: `uraiyaṟṟa toṉṟai yuraittāṉ eṉakkuk
karaiyaṟ ṟeḻunta kalaivēṭ ṭaṟuttut
tiraiyotta eṉṉuṭal nīṅkā tiruttip
puraiyaṟṟa eṉṉuṭ pukuntaṟ paraṉē`,
    english: `2648: Tat-Para Enters Within Jiva
He taught me
The word that is beyond words;
He severed my desires
For learning limitless;
My body, restless as waves,
He in calmness fixed;
In my purified being within
He, the Tatpara, entered.`,
    elaborationTamil: `முதுமை காரணமாக வருகின்ற திரையில்லா (இளமையாகவே யிருக்கின்ற) என்னுடைய உடம்பை அவ்வாறே என்றும் அழியாதிருக்கும்படி வைத்து, 'காமம், வெகுளி, மயக்கம்' என்னும் குற்றங்கள் அற்ற என்னுடைய உள்ளத்தில் புகுந்த சிவன், எனக்கு, அளவின்றிக் கிடக்கின்ற நூல்களின்மேல் செல்கின்ற அவாவை அறுத்து, சொல்லுக்கு எட்டாத ஓர் அரும்பொருளை எனக்கு உபதேசித்தான்.`,
  },
];
